// AUTO-GENERATED German overlay for cityContent. Do not edit by hand.
export interface CityContentDe { history?: string; petTips?: string[]; practicalInfo?: string[]; sights?: Record<string, string> }
export const cityContentDe: Record<string, CityContentDe> = {
  'a-coruna': {
    history: `A Coruña, eine Atlantikstadt in Galicien mit 245.000 Einwohnern, schmiegt sich um eine windgepeitschte Halbinsel, gekrönt vom Torre de Hércules, einem römischen Leuchtturm aus dem 2. Jahrhundert, der noch in Betrieb und als UNESCO-Weltkulturerbe gelistet ist. Wegen der verglasten Erker, die ihre Fassaden vor Wind und Regen schützen, trägt sie den Beinamen „Stadt aus Glas" und besitzt eine der längsten Uferpromenaden Europas: einen fast 13 km langen Paseo Marítimo, der die Stadtstrände Riazor und Orzán mit dem Hafen und den Hügeln des Monte de San Pedro verbindet. Das historische Herz liegt rund um die Plaza María Pita und die kopfsteingepflasterte Altstadt, während das milde, feuchte Ozeanklima das Spazierengehen das ganze Jahr über angenehm macht. Für Reisende mit Hund ist sie ein unkomplizierter galicischer Stopp: viel offener Raum, ein endloser Küstenweg und eine einladende Terrassenkultur, sofern man die sommerlichen Einschränkungen an den bewachten Stränden kennt.`,
    petTips: [`Sommersaison beachten: Hunde sind an den bewachten Stränden Riazor und Orzán typischerweise von Juni bis September verboten, Bußgelder werden durchgesetzt.`, `Alternative Strände: Suchen Sie in der Nähe eine ausgewiesene playa canina (etwa das Gebiet Oza oder eine benachbarte Bucht), damit Ihr Hund außerhalb der Saison ins Wasser kann.`, `Mildes, aber sehr feuchtes Atlantikklima: Packen Sie einen Regenmantel für den Hund und Handtücher ein, der feine Nieselregen (orballo) kann Sie zu jeder Jahreszeit überraschen.`, `Angeleinte Hunde sind in den meisten Taxis und im städtischen Busnetz erlaubt, klären Sie dies aber mit dem Fahrer und halten Sie einen Maulkorb bereit für Rassen, die als PPP eingestuft sind.`, `Spanien: Als potenziell gefährlich eingestufte Rassen (PPP) müssen in der Öffentlichkeit eine kurze Leine und einen Maulkorb tragen, mit gültiger Lizenz und Versicherung.`],
    practicalInfo: [`Der Flughafen A Coruña-Alvedro (LCG) liegt 8 km vom Zentrum entfernt; der Flughafen Santiago (SCQ), 65 km entfernt, bietet deutlich mehr internationale Verbindungen.`, `Einheitliche Notrufnummer in Spanien: 112 (Feuerwehr, Polizei, Rettungsdienst), mit mehrsprachigen Vermittlern.`, `Ozeanisches Klima: milde Sommer (22-24 °C) und regnerische, windige Winter; die Stadt bleibt das ganze Jahr über angenehm zum Spazierengehen, anders als der glühend heiße Süden.`, `Erkundigen Sie sich im Voraus nach einer 24-Stunden-Tierklinik im Großraum; mehrere Praxen decken Notfälle außerhalb der Öffnungszeiten ab, bestätigen Sie die Zeiten telefonisch.`, `EU-Reisende: Ein EU-Heimtierausweis, ein Mikrochip und eine aktuelle Tollwutimpfung genügen für die Einreise nach Spanien, eine Bandwurmbehandlung ist nicht vorgeschrieben.`],
    sights: {
      "Torre de Hércules": `Der älteste noch in Betrieb befindliche römische Leuchtturm der Welt, gelegen auf einer UNESCO-gelisteten Küstenlandzunge. Angeleinte Hunde sind auf den weitläufigen Rasenflächen und im Skulpturenpark rund um den Turm willkommen, jedoch nicht im Inneren des Monuments.`,
      "Paseo Marítimo": `Eine der längsten Uferpromenaden Europas, fast 13 km rund um die gesamte Halbinsel. Breite Gehwege, Bänke und Brunnen machen sie zur bevorzugten Route für Hundespaziergänge, angenehm selbst an windigen Tagen.`,
      "Playas de Riazor y Orzán": `Die zwei großen Stadtstrände direkt im Zentrum, beliebt bei Surfern und Schwimmern. Hunde sind während der Badesaison verboten (etwa Juni bis September); weichen Sie auf die angrenzende Promenade oder einen ausgewiesenen Hundestrand aus.`,
      "Plaza de María Pita": `Der prachtvolle arkadengesäumte Platz im historischen Herzen, dominiert vom Rathaus und gesäumt von Caféterrassen. Angeleinte Hunde sind auf dem gesamten Platz und in den kopfsteingepflasterten Gassen der umliegenden Altstadt willkommen.`,
      "Monte de San Pedro": `Eine ehemalige Küstenfestung, die zu einem großen Panoramapark mit Blick auf die Bucht umgestaltet wurde. Wanderwege, Rasenflächen und ein gläserner Panoramalift machen ihn zu einem perfekten grünen Rückzugsort für angeleinte Hunde.`,
      "Aquarium Finisterrae": `Ein spektakuläres städtisches Aquarium direkt am Ozeanrand nahe dem Torre de Hércules, ebenso wie das benachbarte interaktive Museum Domus. Haustiere sind im Inneren nicht erlaubt, aber die umliegende Küste eignet sich hervorragend für einen Spaziergang.`,
    },
  },
  aarhus: {
    history: `Aarhus, um 770 von den Wikingern gegründet, war tausend Jahre lang ein bedeutender Handelshafen am Kattegat. Mit 360.000 Einwohnern ist es Dänemarks zweitgrößte Stadt, war 2017 Kulturhauptstadt Europas und ist als Studentenstadt (50.000 Studierende) von junger Energie geprägt. Der Hafen wurde in ein Innovationsviertel verwandelt: Dokk1, der Iceberg, Aarhus Ø, zeitgenössische architektonische Wahrzeichen, die die kopfsteingepflasterten Gassen des Lateinischen Viertels und die Kathedrale aus dem 13. Jahrhundert ergänzen. Für Hundebesitzer ist Aarhus eine herausragende Entdeckung: kostenlose öffentliche Verkehrsmittel im gesamten Netz von Letbanen und Midttrafik, 8 offizielle Freilaufwälder, darunter Marselisborg Hundeskov (25 ha), in 15 Minuten mit dem Bus erreichbar, das ganze Jahr über geöffnete Hundestrände am Bellevue Strand und eine dänische Hygge-Cafékultur, die Hunde ab Oktober selbstverständlich auch drinnen willkommen heißt. Die Stadt verfügt zudem über zwei rund um die Uhr geöffnete Tierkliniken (AniCura und Evidensia), selten für eine Stadt dieser Größe.`,
    petTips: [`Letbanen (Straßenbahn) + Midttrafik-Busse: Angeleinte Hunde fahren im gesamten Netz kostenlos, keine Größenbeschränkung.`, `Dänische Leinenpflicht: Hunde müssen überall außerhalb der 8 ausgewiesenen Hundeskove angeleint sein. 1.000 DKK Bußgeld bei Verstoß.`, `Strände: Freilaufzonen gelten vom 1. Oktober bis 14. Mai; vom 15. Mai bis 30. September gilt Leinenpflicht, selbst an hundefreundlichen Stränden.`, `24/7-Tierklinik-Notdienste: AniCura Aarhus (+45 86 14 28 00) und Evidensia Aarhus Højbjerg (+45 87 32 03 00).`, `Dänemark akzeptiert den EU-Heimtierausweis ohne zusätzliche Bandwurmbehandlung (anders als Großbritannien, Irland, Finnland, Norwegen und Malta).`],
    practicalInfo: [`Der Flughafen Aarhus (AAR) liegt 36 km entfernt, der Midttrafik-Bus 925X verkehrt stündlich, 45 Minuten, Hunde fahren kostenlos.`, `DSB-Intercity-Zug Aarhus-Kopenhagen: 3 Std., kleine Hunde in Transportboxen fahren kostenlos, größere Hunde benötigen ein hund-billet (50 DKK / 7 €).`, `In Dänemark sind seit 2010 13 Rassen verboten (Pitbull, Tosa, American Bulldog, Boerboel, Kangal usw.), sie dürfen nicht ins Land einreisen.`, `Dänische Tierarztgebühren gehören zu den höchsten Europas: einfacher Notfall 1.800-2.400 DKK (240-320 €). EU-Tierversicherungen werden akzeptiert.`, `Das Aarhus Festival (Ende August) belegt alle Hotels, buchen Sie 3 Monate im Voraus oder meiden Sie die letzte Augustwoche.`],
    sights: {
      "Marselisborg Hundeskov": `Aarhus' größter offizieller Freilaufwald für Hunde (25 ha), innerhalb des größeren Marselisborg-Waldes (1.400 ha). Wanderwege, Ballspiellichtung, direkter Zugang mit Leine zum übrigen Wald.`,
      "Bellevue Strand": `Aarhus' beliebtester Stadtstrand, nördliche Bucht, 15 Minuten mit der Letbanen. Ganzjähriger Hundebereich mit Freilaufschwimmen, sandig, sanfter Abhang.`,
      "Den Gamle By": `Freilichtmuseum mit 75 historischen dänischen Gebäuden aus dem ganzen Land. Straßen, Gärten und Außenbereiche erlauben angeleinte Hunde (Eintritt kostenpflichtig).`,
      "Dokk1 Harbour Plaza": `Preisgekrönte Uferbibliothek und öffentlicher Platz. Der Außenbereich ist hundefreundlich an der Leine, mit Blick auf den Hafen und Aarhus Ø.`,
      "Riis Skov": `100 Hektar Buchenwald entlang der nördlichen Bucht, mit einem eigenen Hundeskov-Bereich und direktem Zugang zum Hundestrand Bellevue Strand.`,
      "Marselisborg Royal Park": `Sommerresidenz der dänischen Königsfamilie, 13 Hektar öffentliche, ganzjährig geöffnete Gartenanlagen. Angeleinte Hunde willkommen.`,
    },
  },
  'abu-dhabi': {
    history: `Abu Dhabi, die Hauptstadt der Vereinigten Arabischen Emirate, erstreckt sich über eine Insel im Persischen Golf und die umliegende Wüste und vereint Wolkenkratzer, Kulturinseln und Mangroven. Innerhalb einer einzigen Generation wurde aus einem Perlenfischerdorf eine Metropole mit 1,5 Millionen Einwohnern, gespickt mit Ikonen wie der Sheikh-Zayed-Moschee, dem Louvre Abu Dhabi auf Saadiyat Island und den Rennstrecken von Yas Island. Es ist eine grüne, geordnete Stadt mit langen Corniches, gepflegten Parks und einem Mangroven-Nationalpark, den man mit dem Kajak erkunden kann. Für Reisende mit Hund erfordert Abu Dhabi einen nüchternen Blick: Die Regeln sind streng, Hunde müssen angeleint bleiben und sind von den meisten öffentlichen Stränden, Einkaufszentren und allen Sakralstätten ausgeschlossen. Die Sommerhitze übersteigt 45 °C und verbrennt zur Mittagszeit die Pfotenballen. Wirklich haustierfreundliche Angebote (spezielle Strände und Parks) existieren, sind aber begrenzt, und die Einfuhrbestimmungen sind deutlich strenger als ein EU-Heimtierausweis.`,
    petTips: [`Extreme Hitze von Mai bis September: Über 45 °C verbrennt der Gehweg die Pfotenballen; gehen Sie mit dem Hund nur bei Sonnenaufgang und spätabends spazieren, nie bei vollem Tageslicht.`, `Strenges Gesetz: Hunde müssen in der Öffentlichkeit angeleint sein und sind von den meisten öffentlichen Stränden, Einkaufszentren und allen Sakralstätten ausgeschlossen; es drohen Bußgelder.`, `Wirklich haustierfreundliche Strände und Parks sind selten und oft privat oder kostenpflichtig; recherchieren Sie im Voraus und verlassen Sie sich nicht auf spontane Hundeausflüge.`, `Führen Sie immer Wasser mit sich und erwägen Sie Pfotenschuhe; Hitzschlag und verbrannte Pfoten sind hier im Sommer die häufigsten tierärztlichen Notfälle.`, `Viele Hotels akzeptieren keine Haustiere: Tierpensionen sind in Abu Dhabi verbreitet und gut organisiert, buchen Sie diese bei Bedarf vor der Anreise.`],
    practicalInfo: [`Der Zayed International Airport (AUH) liegt 30 km vom Zentrum entfernt; der wichtigste Etihad-Airways-Drehkreuz, mit genauen Regeln für den Tiertransport im Frachtraum oder in der Kabine.`, `Notrufnummern der VAE: 999 (Polizei) und 998 (Rettungsdienst); 997 für die Feuerwehr.`, `Strenge Einfuhrbestimmungen: Eine offizielle Einfuhrgenehmigung ist erforderlich (Mikrochip, Tollwutimpfung, Antikörpertitertest); ein EU-Ausweis allein genügt nicht, planen Sie mehrere Wochen ein.`, `Die Hitze von Mai bis September übersteigt oft 45 °C bei hoher Küstenluftfeuchtigkeit; der Winter (November bis März, 20-28 °C) ist mit Abstand die beste Reisezeit mit Hund.`, `Moderne Tierkliniken sind verfügbar, einschließlich Notdiensten; identifizieren und speichern Sie bei Ankunft eine Klinik in der Nähe Ihrer Unterkunft.`],
    sights: {
      "Sheikh Zayed Grand Mosque": `Eine der größten Sakralstätten der Welt, ein Meisterwerk aus weißem Marmor und floralen Mosaiken und Symbol der VAE. Tiere sind nicht erlaubt und angemessene Kleidung ist vorgeschrieben; respektieren Sie diese kulturellen und religiösen Regeln strikt.`,
      "The Corniche": `Eine lange, begrünte Uferpromenade mit Radwegen und Rasenflächen. Angeleinte Hunde werden in einigen ausgewiesenen Grünflächen geduldet, sind aber am öffentlichen Corniche Beach selbst verboten.`,
      "Louvre Abu Dhabi": `Ein universelles Museum, gekrönt von Jean Nouvels gewaltiger Gitterkuppel, auf der Kulturinsel Saadiyat. Haustiere sind im Inneren oder unter der Kuppel nicht erlaubt; nur Assistenzhunde sind eine Ausnahme.`,
      "Saadiyat Island beaches": `Lange geschützte weiße Sandstrände, ein Rückzugsort für nistende Meeresschildkröten und gesäumt von Resorts. Hunde sind hier zum Schutz der Tierwelt verboten; betrachten Sie diese Strände als Ausflug ohne Haustier.`,
      "Mangrove National Park": `Ein weitläufiges Mangrovenschutzgebiet, durchzogen von Holzstegen und Kajak- oder Paddeltouren, reich an Vogelwelt. Haustiere sind auf den Stegen oder bei geführten Touren nicht erlaubt, da dieses Ökosystem geschützt ist.`,
      "Yas Island": `Die Freizeitinsel mit der Yas-Marina-Formel-1-Strecke und großen Indoor-Themenparks. Haustiere sind in den Parks und Attraktionen verboten, doch einige Restaurantterrassen im Freien akzeptieren möglicherweise angeleinte Hunde.`,
    },
  },
  agadir: {
    history: `Agadir ist nach marokkanischen Maßstäben eine junge Stadt: Nach dem Erdbeben vom 29. Februar 1960, das sie zerstörte, wurde sie vollständig nach einem modernen Plan wiederaufgebaut, mit breiten Alleen, niedrigen erdbebensicheren Gebäuden und einer 6 km langen Uferpromenade, die bis heute ihr schlagendes Herz ist. Im 16. Jahrhundert ein portugiesischer Handelsposten, lebt die Stadt heute vom weltweit größten Sardinenfischereihafen und vom Strandtourismus am Atlantik. Für Reisende mit Hund ist Agadir eines der sanftesten Tore nach Marokko: ein dank der Meeresbrise mildes Klima das ganze Jahr über, eine ebene Promenade, ideal am frühen Morgen, die Kasbah Agadir Oufella für Panoramablicke und das eine Autostunde entfernte Paradise Valley für Wanderungen an der Leine. Hunde sind im marokkanischen öffentlichen Raum noch selten, doch Hotels in der Touristenzone öffnen sich allmählich für Haustiere, besonders außerhalb der Hochsaison.`,
    petTips: [`Gehen Sie mit Ihrem Hund früh morgens oder nach 18 Uhr spazieren: Auch wenn die Meeresbrise die Küste mildert, ist die Sonne tagsüber stark und Sand wie Asphalt heizen sich schnell für Pfoten auf.`, `Vermeiden Sie im Sommer Ausflüge ins Landesinnere (Paradise Valley, Taroudant) während der heißen Stunden: Es ist dort oft 10 Grad heißer als in Agadir, brechen Sie bei Sonnenaufgang auf und führen Sie ausreichend Wasser mit.`, `Streunende Hunde leben rund um die Stadt und an manchen Stränden: Halten Sie Ihren Hund an der Leine, meiden Sie jeden Kontakt und stellen Sie sicher, dass seine Impfungen, allen voran gegen Tollwut, vollständig auf dem neuesten Stand sind.`, `Führen Sie immer Wasser und einen faltbaren Napf mit: Öffentliche Brunnen sind selten und Caféterrassen bieten nicht systematisch Wasser für Hunde an.`, `Hunde sind im marokkanischen öffentlichen Raum kulturell nach wie vor ungewöhnlich: Halten Sie Ihr Haustier in belebten Gebieten an einer kurzen Leine und bevorzugen Sie die Touristenviertel, die eher an Tiere gewöhnt sind.`],
    practicalInfo: [`Der Flughafen Al Massira (AGA) liegt etwa 25 km vom Zentrum entfernt: Transfer per Taxi oder Shuttle, eine Transportbox wird empfohlen, und die Mitnahme eines Hundes im Grand Taxi liegt im Ermessen des Fahrers.`, `Marokko ist nicht tollwutfrei: Für die Rückkehr in die EU mit Ihrem Hund ist ein Tollwut-Antikörpertitertest in einem EU-zugelassenen Labor vorgeschrieben, den Sie mindestens 3 Monate vor der Rückreise einplanen sollten.`, `Marokkanische Notrufnummern: 19 für die Polizei in den Städten, 15 für Feuerwehr und Rettungsdienst, 177 für die Gendarmerie außerhalb der Stadtgebiete.`, `Klima: Die Meeresbrise hält die Küste das ganze Jahr über mild, das Landesinnere (Souss-Tal, Berge) ist im Sommer jedoch deutlich heißer; passen Sie den Spaziergangsrhythmus Ihres Hundes entsprechend an.`, `Tierkliniken gibt es in den Vierteln Talborjt und Founty: Fragen Sie bei Ankunft in Ihrem Hotel nach den Details des nächstgelegenen Tierarztes, bevor ein Notfall eintritt.`],
    sights: {
      "Promenade d'Agadir": `Eine 6 km lange Uferpromenade zwischen der Marina und dem Viertel Founty. Angeleinte Hunde werden geduldet, idealerweise früh morgens oder gegen Ende des Tages, wenn Menschenmenge und Hitze nachlassen.`,
      "Agadir Oufella": `Überreste der Kasbah aus dem 16. Jahrhundert auf dem Hügel über der Bucht, mit dem Motto Gott, Vaterland, König, das nachts beleuchtet wird. Die Außenesplanade ist für angeleinte Hunde zugänglich, mit einem großartigen Panorama über den Hafen und den Strand.`,
      "Souk El Had": `Einer der größten überdachten Märkte Marokkos, rund 3.000 Stände hinter ockerfarbenen Mauern. Hunde sind nicht zugelassen: Lassen Sie Ihren Begleiter im Hotel und rechnen Sie mit 2 bis 3 Stunden für den Besuch.`,
      "Marina d'Agadir": `Eine moderne Marina am Fuß der Kasbah, mit Fußgängerkais gesäumt von Geschäften und Cafés. Angeleinte Hunde können auf den Außenkais spazieren gehen, die bei Sonnenuntergang besonders angenehm sind.`,
      "Paradise Valley": `Die Schluchten des Flusses Tamraght, eine Autostunde im Landesinneren, mit Palmenhainen, natürlichen Becken und felsigen Pfaden. Angeleinte Hunde sind auf den Wegen erlaubt; brechen Sie früh auf, denn die Hitze steigt fernab des Ozeans schnell an.`,
      "Crocoparc": `Ein botanischer Tierpark mit Schwerpunkt auf Nilkrokodilen, am östlichen Stadtrand. Hunde sind nicht zugelassen, wie in den meisten Wildparks; planen Sie diesen Besuch ohne Ihren Begleiter.`,
    },
  },
  'aix-en-provence': {
    history: `Aix wurde 122 v. Chr. vom römischen Konsul Sextius Calvinus rund um die Thermalquellen gegründet, die der Stadt ihren Namen Aquae Sextiae gaben, und war lange Zeit Hauptstadt der Grafschaft Provence, bevor sie 1481 an Frankreich angegliedert wurde. Das 17. Jahrhundert war ihr goldenes Zeitalter: Der provenzalische Adel errichtete über 160 Stadtpalais, der Cours Mirabeau wurde 1651 angelegt, und die monumentalen Brunnen, die die Stadt prägen, stammen aus dieser Zeit. Aix ist auch die Stadt Paul Cézannes, der hier 1839 geboren wurde und unermüdlich den Berg Sainte-Victoire im Osten malte. Die provenzalische Tradition der Caféterrassen und schattigen Innenhöfe hat Hunde stets einbezogen: Man begegnet ihnen auf dem Cours Mirabeau, auf dem Markt am Place Richelme und auf den Wanderwegen der Sainte-Victoire. Die Stadt verhängt konsequent Bußgelder für nicht entsorgten Hundekot und schließt das Massiv im Sommer wegen Waldbrandgefahr, zwei örtliche Einschränkungen, die man einplanen sollte.`,
    petTips: [`Sommerliche Schließungen: Vom 21. Juni bis 24. September wird das Massiv Sainte-Victoire (Bibémus, Bimont) an Tagen mit hoher oder sehr hoher Waldbrandgefahr geschlossen, prüfen Sie risque-prevention-incendies.fr am Vorabend um 19 Uhr.`, `Bußgelder für Hundekot: Die städtische Polizei im historischen Zentrum verhängt Bußgelder von 68 bis 135 €; Tütenspender gibt es im Parc Jourdan, an der Place des Cardeurs und entlang des Cours Mirabeau.`, `Provenzalische Hitze: Der Asphalt erreicht von 11 bis 18 Uhr im Juli und August über 50 °C; gehen Sie vor 9 oder nach 19 Uhr spazieren.`, `Tiernotdienst: Vétérinaires 2 Toute Urgence, 35 rue Émilien Gautier, +33 4 42 82 13 13, die einzige spezialisierte Notfallklinik der Stadt, nachts und am Wochenende.`, `Umweltzone: Seit 2025 sind Fahrzeuge mit Crit'Air 4 oder schlechter tagsüber im zentralen Périphérique verboten; parken Sie am P+R Krypton mit kostenlosem Shuttle für ältere Wohnmobile.`],
    practicalInfo: [`Aix lässt sich in 25 Minuten von einem Ende zum anderen zu Fuß durchqueren; keine Metro oder Straßenbahn, der elektrische Diabolo-Minibus umkreist das Zentrum für 1,20 €.`, `Über 70 % der Terrassenrestaurants akzeptieren Hunde ohne Vorankündigung; in der Regel lehnen nur Innenräume von Michelin-Restaurants sie ab.`, `Hunde fahren kostenlos im Aix em Bus (kleine im Transportbehälter, mittlere/große mit Maulkorb nach Ermessen des Fahrers); im TGV wird eine Pauschale von 7 € pro Hund fällig.`, `Alle 39 städtischen Museen lassen nur Assistenzhunde zu; der Vorplatz der Kathedrale Saint-Sauveur akzeptiert angeleinte Hunde, das Innere und der Kreuzgang nicht.`, `Der EU-Heimtierausweis bleibt in Frankreich gültig; eine mindestens 21 Tage alte und aktuelle Tollwutimpfung ist vorgeschrieben.`],
    sights: {
      "Cours Mirabeau": `440 m lange zentrale Allee, gesäumt von vier Reihen Platanen, Brunnen und Terrassen; die symbolträchtige hundefreundliche Flaniermeile von Aix.`,
      "Sainte-Victoire": `1.011 m hoher, von Cézanne gemalter Kalksteinkamm, von Bibémus und Bimont aus an der Leine begehbar; vom 21. Juni bis 24. September bei hoher Waldbrandgefahr geschlossen.`,
      "Parc Jourdan": `3 Hektar großer öffentlicher Park südlich des Quartier Mazarin, schattige Rasenflächen und Boulebahnen; Hunde an der Leine, ein Treffpunkt für Ortsansässige.`,
      "Atelier de Cézanne": `Cézannes letztes Atelier (1902) auf dem Hügel Les Lauves; der Garten ist kostenlos und für angeleinte Hunde zugänglich, das Atelierinnere ist geschlossen.`,
      "Pavillon de Vendôme": `Klassizistischer Pavillon aus dem 17. Jahrhundert mit einem 6.000 m² großen französischen Ziergarten; kostenloser Gartenzugang für angeleinte Hunde.`,
      "Marché de la Place Richelme": `Täglicher Lebensmittelmarkt (8-13 Uhr) unter Schatten auf einem kleinen Platz im historischen Zentrum; angeleinte Hunde willkommen.`,
    },
  },
  'aix-les-bains': {
    history: `Aix-les-Bains wuchs um Thermalquellen, die seit der Römerzeit bekannt sind (der Bogen des Campanus und Überreste römischer Bäder stehen noch nahe dem Stadtzentrum), doch seine moderne Identität als eine der großen europäischen Kurstädte geht auf das 19. Jahrhundert zurück, als Königin Victoria und der europäische Adel am Lac du Bourget, Frankreichs größtem natürlichen See, zur Kur weilten. Die Thermes Nationaux, im Jahr 2000 innerhalb des historischen Parks der Villa Chevalley wiedererrichtet, ziehen bis heute Besucher für rheumatologische und Atemwegsbehandlungen an. Rund 30.000 Einwohner leben in einer Stadt, die für weit mehr Besucher gebaut wurde, mit prachtvollen Belle-Époque-Hotels, einem Kasino und Bootsfahrten über den See zur Zisterzienserabtei Hautecombe, der Grabstätte des Hauses Savoyen. Hunde dürfen weder die Therme selbst noch die bewachten Sommerstrände betreten, doch der 18 Hektar große Wald Bois Vidal oberhalb der Stadt, die historischen Gärten des Parc Thermal und ein grüner Uferweg nahe dem Cap des Séselets geben der Stadt jenseits der Kur eine wirklich begehbare, hundefreundliche Seite.`,
    petTips: [`Die bewachten Strände des Lac du Bourget verbieten Hunde, selbst angeleint, etwa von Juni bis September; nutzen Sie stattdessen den grünen Weg beim Cap des Séselets, der ganzjährig geöffnet bleibt.`, `Die Thermalbäder selbst lassen niemals Haustiere zu, planen Sie für die Kurzeit einen Spaziergang im Bois Vidal oder einen Rover.fr-Betreuer ein.`, `Clinique Vétérinaire du Grand Port (171 avenue du Grand Port, +33 4 79 63 43 99) und Clinique Vétérinaire de la Dent du Chat (11 boulevard Jean Charcot, +33 4 79 53 20 10) sind beides etablierte lokale Praxen.`, `Angeleinte Hunde sind gegen einen kleinen Aufpreis an Bord der Ausflugsboote zur Abtei Hautecombe erlaubt, müssen aber während des Kirchenbesuchs draußen warten.`, `In den Regionalzügen und den städtischen Ondéa-Bussen fahren Hunde unter 6 kg kostenlos in einer geschlossenen Transportbox; größere Hunde müssen mit ermäßigtem Fahrschein angeleint und mit Maulkorb reisen.`],
    practicalInfo: [`Der nächstgelegene Flughafen ist Chambéry-Savoie (CMF), etwa 20 km entfernt; der Flughafen Genf (GVA) ist rund 1 Stunde mit dem Auto oder Zug entfernt.`, `Beste Reisezeit: Mai bis September für Spaziergänge im Bois Vidal und am See; in diesem Zeitraum sind Hunde an den bewachten Stränden verboten, nutzen Sie stattdessen den grünen Weg beim Cap des Séselets.`, `Der 24-Stunden-Notdienst läuft über die Bereitschaftsrotation der örtlichen Kliniken; die Clinique Vétérinaire du Grand Port (+33 4 79 63 43 99) ist eine praktische erste Anlaufstelle.`, `Der eigene SNCF-Bahnhof von Aix-les-Bains hat direkte TGV- und TER-Verbindungen nach Paris, Lyon, Chambéry und Annecy, ein Umweg über eine andere Stadt ist nicht nötig.`, `Das französische Recht schreibt Leinenpflicht für Hunde in bebauten öffentlichen Bereichen vor, sofern der Besitzer nicht die volle Rufkontrolle hat; die Regel wird an den bewachten Sommerstränden am Lac du Bourget streng durchgesetzt.`],
    sights: {
      "Bois Vidal": `Ein 18 Hektar großes städtisches Waldgebiet mit Wiesen direkt oberhalb des Kurviertels, kostenlos und täglich von 8 bis 17 Uhr geöffnet. Hunde jeder Größe sind auf den breiten Fußwegen und Sportpfaden willkommen.`,
      "Parc Thermal": `Ein denkmalgeschützter historischer Garten rund um die Thermes Nationaux, mit fünf Pavillons, breiten Kieswegen und der schattigen Terrasse der Rotonde-Bar. Angeleinte Hunde sind in diesem Landschaftsgarten aus dem 19. Jahrhundert im Stadtzentrum überall willkommen.`,
      "Esplanade du Lac & Petit Port": `Die Uferesplanade bis zum Petit Port ist der Standardspaziergang von Aix-les-Bains, ein ebener Weg mit Seeblick, Strandbars und Restaurantterrassen auf der gesamten Strecke. Er führt direkt zum Anlegeplatz der Boote zur Abtei Hautecombe.`,
      "Voie Verte & Cap des Séselets": `Ein grüner Rad- und Fußweg verläuft am Ufer zwischen Plage du Rowing und Plage des Mottets, vorbei am Cap des Séselets, wo Hunde das ganze Jahr über frei vom Ufer aus waten und schwimmen können. Er ist die verlässliche Alternative zu den bewachten Stränden der Stadt, die jeden Sommer Hunde ganz verbieten.`,
      "Abbaye de Hautecombe (lake cruise)": `Eine Bootsfahrt über den Lac du Bourget vom Grand Port aus führt zur Zisterzienserabtei Hautecombe, der Grabstätte des Hauses Savoyen am gegenüberliegenden Seeufer. Hunde sind an Bord gegen einen kleinen Aufpreis angeleint erlaubt, müssen aber während des Kirchenbesuchs draußen warten.`,
      "Thermes Nationaux": `Die moderne Therme der Stadt, im Jahr 2000 innerhalb des historischen Parks der Villa Chevalley wiedererrichtet, ist der Grund für die Existenz von Aix-les-Bains, jedoch wie jede französische Therme strikt für Haustiere tabu. Planen Sie für die Stunden im Inneren einen Spaziergang im Bois Vidal oder einen Betreuer ein.`,
    },
  },
  ajaccio: {
    history: `Ajaccio, Hauptstadt von Süd-Korsika und Geburtsort Napoléon Bonapartes (1769), ist eine sonnenverwöhnte Mittelmeerstadt mit 72.000 Einwohnern am Kopf eines geschützten Golfs gegenüber den Sanguinaires-Inseln. 1492 von der Republik Genua auf einem verteidigungsfähigen Vorgebirge gegründet, bewahrt die Stadt ihre genuesische Zitadelle Miollis aus dem 16. Jahrhundert, die granitgepflasterten Gassen der Vieille Ville rund um die Maison Bonaparte und den Palais Fesch, eine der schönsten Sammlungen italienischer Malerei Frankreichs außerhalb von Paris, das Vermächtnis von Kardinal Fesch, Napoléons Onkel. Für Hundebesitzer ist Ajaccio die haustierfreundlichste Basis auf Korsika: Mittelmeerklima mit sehr milden Wintern (11-12 °C im Januar), der 7 km lange Kammweg Sentier des Crêtes auf den Höhen mit 360°-Meerespanorama, die Pointe de la Parata und die Sanguinaires-Inseln im Westen, mit dem Boot erreichbar (angeleinte Hunde auf offenen Decks), ein wilder ganzjähriger Hundestrand am Capo di Feno und eine korsische Kultur, die Haustiere in den Trattorien der Vieille Ville und den Strandbars am Meer herzlich willkommen heißt. Fährverbindungen (Marseille/Nizza/Toulon/Livorno/Savona/Piombino) und Flüge (Air Corsica/Air France) sind gut etabliert, erfordern aber für Juli und August eine Tierbuchung 6-8 Wochen im Voraus.`,
    petTips: [`Zecken + Leishmaniose: Korsika hat sowohl eine sehr hohe Zeckendichte als auch die höchste französische Rate an caniner Leishmaniose, verwenden Sie eine Woche vor Ankunft Bravecto/Frontline UND Advantix (Spot-on gegen Sandmücken).`, `Sommerliches Strandverbot: Hunde sind vom 1. Juni bis 30. September am zentralen Plage du Ricanto, Trottel und Saint-François verboten, 38 € städtisches Bußgeld. Ganzjährige Ausnahmen: Capo di Feno (Westen) und das östliche Ende von Ricanto hinter dem Flughafen.`, `TCA-Bus (1,60 €): Hunde unter 6 kg in Transportboxen kostenlos, größere Hunde mit Maulkorb an kurzer Leine nach Ermessen des Fahrers. In Ajaccio gibt es keine Straßenbahn oder Metro.`, `Kein dedizierter 24/7-Tiernotdienst in Ajaccio: telefonisch vermittelte Bereitschaftsrotation zwischen den Kliniken. Nummern vor der Ankunft speichern: Clinique des Salines (+33 4 95 22 39 51) und die landesweite Hotline SOS Vétérinaires (+33 9 70 72 73 73).`, `Korsischer Granit zur Mittagszeit: Pflastersteine erreichen an Sommernachmittagen 50 °C und verbrennen Pfoten in unter einer Minute. Gehen Sie von Mitte Juni bis Mitte September vor 9 und nach 19 Uhr spazieren.`],
    practicalInfo: [`Der Flughafen Ajaccio Napoléon-Bonaparte (AJA) liegt 7 km östlich des Zentrums, TCA-Shuttlelinie 8 alle 30 Min. (4,50 €, Hunde in Transportboxen kostenlos); Taxi 25-35 € ohne Tierzuschlag bei den meisten Unternehmen.`, `Corsica Linea & Corsica Ferries ab Marseille (12 Std. über Nacht), Toulon (10 Std. über Nacht), Nizza (5,5 Std. NGV tagsüber) und Italien (Livorno 6 Std., Savona 10 Std., Piombino 8 Std.). Tierzuschlag 20-45 €, eine haustierfreundliche Kabine ist für große Hunde auf Nachtüberfahrten unerlässlich.`, `Chemins de Fer de la Corse (CFC) Ajaccio-Bastia: 4-stündige Panoramafahrt quer über den korsischen Gebirgskamm, kleine Hunde in Transportboxen kostenlos, größere angeleinte Hunde mit Maulkorb 5 €.`, `Keine Straßenbahn oder Metro in Ajaccio, städtische Fortbewegung meist zu Fuß (sehr kompaktes Zentrum, 1,2 km vom Hafen bis zu den Stadtmauern).`, `Der EU-Heimtierausweis ist für alle Fähren und Flüge nach Korsika erforderlich, mit gültiger Tollwutimpfung (mindestens 21 Tage nach der Erstimpfung).`],
    sights: {
      "Sentier des Crêtes": `7 km langer Kammweg oberhalb von Ajaccio, 360°-Panorama über den Golf und die Sanguinaires. Auf dem Kamm ist Freilauf erlaubt, teilweise Schatten durch Pinien und Steineichen, zwei natürliche Quellen.`,
      "Pointe de la Parata": `Felsige Landzunge am westlichen Ende, genuesischer Turm aus dem 16. Jahrhundert, Rundweg zu den Sanguinaires. Hunde an der Leine, magisch bei Sonnenuntergang, wenn sich die Sanguinaires-Inseln rot färben.`,
      "Maison Bonaparte (extérieur)": `Napoléons Geburtshaus, ein Stadtpalais aus dem 17. Jahrhundert im Herzen der Vieille Ville. Das Museumsinnere ist für Hunde nicht zugänglich, aber die Fassade und der davorliegende Place Letizia sind das ganze Jahr über hundefreundlich.`,
      "Plage de Capo di Feno": `Wilde, weiße Sandbucht 15 Minuten westlich mit dem Auto, dem offenen Meer zugewandt. Hunde sind ganzjährig ohne Einschränkung erlaubt, 800 m lang, im Sommer keine Bademeisterüberwachung.`,
      "Citadelle Miollis & remparts": `Genuesische Zitadelle aus dem 16. Jahrhundert, die den Hafen bewacht, 2019 entmilitarisiert. Frei zugänglicher Rundgang auf den Wällen, angeleinte Hunde ganzjährig erlaubt, der schönste Panoramaplatz im Zentrum.`,
      "Jardin des Milelli": `Olivenhain der Familie Bonaparte, 4 km nördlich, als freier öffentlicher Park geöffnet. Jahrhundertealte Olivenbäume, Picknicktische, die einzige wirklich schattige städtische Grünfläche im Sommer.`,
    },
  },
  albufeira: {
    history: `Albufeira, mit rund 42.000 Einwohnern (und etwa 5 Millionen Besuchern pro Jahr) der größte Badeort der Algarve, begann als maurische, später christliche Fischersiedlung an einer Kalksteinbucht der portugiesischen Südküste, bis zum Erdbeben von Lissabon 1755 von einer befestigten Burg beherrscht, deren Fragmente noch in der Cidade Velha liegen. Heute hat die Stadt zwei Gesichter: die kopfsteingepflasterte Altstadt mit weiß getünchten Häusern fällt hinab zum Praia dos Pescadores und dem Aussichtspunkt Pau da Bandeira, während sich der Ferienstreifen Areias de São João mit Hochhaushotels, Bars und dem nächtlichen Strip an der Avenida Sá Carneiro ostwärts erstreckt. Für Reisende mit Hund vereint die Algarve rund 300 Sonnentage im Jahr, offizielle ganzjährige Hundestrände in Cova Redonda und Barranco das Belharucas, den Klippenweg Pine Cliffs unter Schirmpinien und das Lagunenschutzgebiet Praia dos Salgados mit seinen Flamingos. Das Timing ist entscheidend: Vom 1. Mai bis 30. September sind Hunde an allen zentralen Stränden verboten (GNR-Bußgelder bis 120 €), und im Juli und August treibt die Hitze Asphalt und Sand über 50 °C. April-Mai und Oktober-November machen Albufeira zu einer der lohnendsten haustierfreundlichen Fluchtorte Südeuropas, mit Hotelpreisen 40-60 % unter dem Augustniveau und allen Stränden ab dem 1. Oktober wieder offen für angeleinte Hunde.`,
    petTips: [`Sommerliches Strandverbot: Hunde sind vom 1. Mai bis 30. September an allen zentralen Stränden verboten (Pescadores, Oura, Santa Eulália, Galé), GNR-Bußgelder bis 120 €. Ganzjährige Ausnahmen: Praia da Cova Redonda (15 km westlich) und Praia do Barranco das Belharucas (10 km östlich).`, `Extreme Hitze im Juli und August: Sand und Asphalt über 50 °C, verbrennen Pfotenballen in unter einer Minute. Gehen Sie vor 9 oder nach 19:30 Uhr spazieren und bevorzugen Sie die Nebensaison (April-Mai, Oktober-November).`, `Nächste 24-Stunden-Tierklinik: Hospital Veterinário do Algarve in Loulé (20 km östlich, +351 289 410 020). Kein 24-Stunden-Dienst innerhalb von Albufeira selbst, speichern Sie die Nummer vor der Ankunft.`, `Öffentliche Verkehrsmittel: Der städtische Bus Próximo nimmt kleine Hunde in Transportboxen kostenlos mit, große Hunde an der Leine mit Maulkorb nach Ermessen des Fahrers. Der CP-Zug Faro-Lagos verlangt für große Hunde eine Pauschale von 5 € (kostenlos in Transportbox unter 10 kg).`, `Meiden Sie den Strip von Areias de São João (Avenida Sá Carneiro) nach 22 Uhr von Juni bis September mit einem lärmempfindlichen Hund, laute Musik und Menschenmengen die ganze Nacht. Bevorzugen Sie Hotels in der Cidade Velha, in Olhos de Água oder an der Praia da Galé.`],
    practicalInfo: [`Der Flughafen Faro (FAO) liegt 40 km östlich, etwa 35 Minuten mit dem Auto über die A22. EVA Transportes Aerobus verkehrt stündlich zum Terminal in Albufeira (nur Hunde in Transportboxen); privater haustierfreundlicher Transfer 50-70 € pro Fahrt, empfohlen für große Hunde.`, `Der CP-Regionalzug Faro-Albufeira-Lagos verkehrt etwa stündlich. Kleine Hunde in Transportboxen unter 10 kg fahren kostenlos; große Hunde an der Leine mit Maulkorb zahlen eine Pauschale von 5 €. Der Bahnhof Albufeira-Ferreiras liegt 6 km landeinwärts vom Zentrum.`, `Städtische Próximo-Busse: 9 Linien verbinden Cidade Velha, Areias de São João, Olhos de Água und den Bahnhof. Kleine Hunde in Transportboxen kostenlos; große Hunde an der Leine mit Maulkorb nach Ermessen des Fahrers (strenger zu Stoßzeiten).`, `Portugal nutzt den Euro, kontaktloses Zahlen ist überall möglich, Tierzuschläge in Albufeira-Hotels betragen 10-25 €/Nacht, höher als in Faro, aber niedriger als in Ferienorten der spanischen Costa del Sol.`, `Britische Reisende: Das Animal Health Certificate (AHC) wird von einem EU-OV innerhalb von 10 Tagen vor der Rückreise ausgestellt. Clínica Veterinária de Albufeira und VetSet Albufeira können es ausstellen, 72 Stunden im Voraus buchen (80-120 €).`],
    sights: {
      "Pine Cliffs Trail": `4 km langer Klippenweg durch Schirmpinienwald zwischen Praia da Falésia und Olhos de Água. Angeleinte Hunde ganzjährig erlaubt, leuchtend rote Sandsteinklippen, Trinkbrunnen an beiden Enden.`,
      "Cidade Velha (Old Town)": `Labyrinth aus kopfsteingepflasterten Gassen und weiß getünchten Häusern, die zum Fischerstrand hinabfallen, mit der Igreja de São Sebastião und dem Aussichtspunkt Pau da Bandeira ganz oben. Angeleinte Hunde überall in den öffentlichen Straßen willkommen.`,
      "Praia da Cova Redonda": `Kleine hufeisenförmige Bucht 15 km westlich, von der Gemeinde Lagoa offiziell als ganzjähriger Hundestrand ausgewiesen. Angeleinte Hunde alle zwölf Monate erlaubt, hölzerner Bohlenweg hinab, saisonales Strandcafé.`,
      "Marina de Albufeira": `Marina mit 475 Liegeplätzen und bunten Gebäuden des Architekten Vasco Vieira, rund um die Uhr geöffnete Promenade, hundefreundliche Restaurantterrassen und Delfinbeobachtungsboote. Angeleinte Hunde ganzjährig überall auf der Promenade willkommen.`,
      "Praia dos Salgados Reserve": `Küstenlagune und Salzmarschschutzgebiet 8 km westlich, 3 km langer Bohlenweg über die Sümpfe mit Flamingos und Reihern das ganze Jahr über. Angeleinte Hunde auf dem Bohlenweg ganzjährig willkommen.`,
      "Castelo de Silves": `Rot-sandsteinerne maurische Burg 25 km nordwestlich, die ehemalige arabische Hauptstadt der Algarve. Angeleinte Hunde sind auf dem Außengelände und den Wällen ganzjährig erlaubt (Eintritt 2,80 €), nicht in den Museumsgebäuden.`,
    },
  },
  alcudia: {
    history: `Alcúdia vereint zweitausend Jahre Geschichte auf kleinstem Raum im Norden Mallorcas: Die römische Stadt Pollentia, 123 v. Chr. gegründet, erstreckt sich direkt außerhalb der mittelalterlichen Stadtmauern aus dem 14. Jahrhundert, die die Altstadt noch heute umschließen. Nach Piratenüberfällen befestigte die Krone Aragon die Stadt, deren Tore Xara und Mallorca bis heute stehen. Zwei Kilometer entfernt ist Port d'Alcúdia zum wichtigsten Badeort der Nordküste geworden, mit seinem langen Sandstrand und der Uferpromenade an der Bucht. Für Reisende mit Hund ist die Kombination reizvoll: schattige Gassen in der Altstadt, der Rundweg auf der Stadtmauer, die Pfade der Halbinsel Victoria und das Feuchtgebiet s'Albufera, alles an der Leine zu erkunden. Das Sommerverbot an den Hauptstränden macht es jedoch unerlässlich, die geduldeten alternativen Buchten zu kennen.`,
    petTips: [`Sommerliches Strandverbot: Wie überall auf den Balearen sind Hunde an bewachten Stränden während der Badesaison verboten; peilen Sie die Nebensaison in der Morgendämmerung an und erkunden Sie geduldete Buchten wie Punta Engroixada.`, `Mallorquinische Sommerhitze: Gehen Sie früh morgens und nach Sonnenuntergang spazieren und testen Sie Sand und Pflaster mit der Hand, bevor Sie Ihren Hund darauf laufen lassen.`, `In s'Albufera ist eine kurze Leine praktisch Pflicht: Nistende Wildtiere sind überall präsent und Ranger achten darauf, bleiben Sie auf den Hauptwegen.`, `Prozessionsspinnerraupen von Spätwinter bis Frühling in den Kiefernwäldern von La Victoria und Cap des Pinar: Halten Sie Ihren Hund von am Boden liegenden Raupen fern, sie sind hochgiftig.`, `Führen Sie auf den Wegen der Talaia d'Alcúdia immer Wasser mit: Nach der Einsiedelei gibt es keine Wasserstelle mehr und wenig Schatten auf dem Kamm.`],
    practicalInfo: [`Der Flughafen Palma (PMI) liegt etwa 60 km entfernt: Transfer per Mietwagen oder Taxi, das Hunde akzeptiert; im TIB-Busnetz sind nur kleine Tiere in Transportboxen zugelassen.`, `Fähre von Barcelona zum Hafen von Alcúdia: Unternehmen akzeptieren Hunde nach eigenen Regeln, in Bordzwingern oder auf Außendecks mit Leine und Maulkorb; prüfen Sie die Bedingungen bei der Buchung.`, `Spaniens einheitliche Notrufnummer ist 112, gültig für jeden menschlichen Notfall; für Ihren Hund suchen Sie bei Ankunft eine Tierklinik in Alcúdia oder Port d'Alcúdia.`, `Spanische Vorschriften: EU-Heimtierausweis und Mikrochip sind vorgeschrieben, und sogenannte PPP-Rassen müssen im öffentlichen Raum eine kurze Leine und einen Maulkorb tragen.`, `Die Hauptsaison läuft von Mai bis Oktober: Haustierfreundliche Unterkünfte in Port d'Alcúdia sind schnell ausgebucht, buchen Sie für den Sommer mehrere Monate im Voraus.`],
    sights: {
      "Pollentia": `Ruinen der wichtigsten römischen Stadt der Balearen: Forum, Häuser und ein aus dem Fels gehauenes Theater. Ein Freilichtareal; angeleinte Hunde werden auf den umliegenden Wegen geduldet, das frei zugängliche Theater ist der am einfachsten mit Haustier zu besichtigende Bereich.`,
      "Murallas de Alcúdia": `Rundgang auf den mittelalterlichen Wällen aus dem 14. Jahrhundert, 1,5 km rund um die Altstadt zwischen Porta de Xara und Porta de Mallorca. Ein kostenloser, offener Spaziergang, angeleinte Hunde willkommen, mit schönem Blick über die Dächer und die Bucht.`,
      "Passeig Marítim del Port d'Alcúdia": `Uferpromenade zwischen der Marina und den Stränden, gesäumt von Terrassen, von denen viele Hunde draußen dulden. Das ganze Jahr über angenehm, im Sommer sehr belebt: gehen Sie morgens.`,
      "Parc Natural de s'Albufera": `Das größte Feuchtgebiet der Balearen, ein Zufluchtsort für Zugvögel wenige Kilometer vom Hafen entfernt. Angeleinte Hunde sind auf den Hauptwegen zugelassen; bleiben Sie auf den Pfaden und meiden Sie die Beobachtungshütten zu stark frequentierten Zeiten.`,
      "Platja d'Alcúdia": `Sieben Kilometer sanft abfallender weißer Sand, der große Familienstrand Nordmallorcas. Hunde sind während der sommerlichen Badesaison verboten; außerhalb der Saison wird ein früher Spaziergang an der Leine geduldet. Weichen Sie im Sommer auf das Gebiet Punta Engroixada aus, das als hundegeduldete Alternative bekannt ist.`,
      "Ermita de la Victòria": `Eine Wallfahrtskapelle aus dem 17. Jahrhundert auf der Halbinsel zwischen Alcúdia und Cap des Pinar, Ausgangspunkt der Wege hinauf zur Talaia d'Alcúdia (445 m). Angeleinte Hunde auf den Pfaden willkommen, mit Panoramablick über beide Buchten.`,
    },
  },
  alghero: {
    history: `An der Nordwestküste Sardiniens gelegen, besitzt Alghero eine in Italien seltene Besonderheit: Hier wird noch Katalanisch gesprochen, ein Erbe der aragonesischen Herrschaft im 14. Jahrhundert, das ihr den Beinamen „Barceloneta" einbrachte. Die von goldenen Bastionen und Wachtürmen zum Meer hin umringte Altstadt bewahrt kopfsteingepflasterte Gassen, Fassaden mit katalanisch-gotischen Zügen und eine Schmucktradition, die mit vor der Küste gefischter roter Koralle arbeitet. Ringsum offenbart die Riviera die dramatischen Klippen von Capo Caccia und die Neptunsgrotte, während sich südlich die Sandstrände von Le Bombarde, Lazzaretto und Maria Pia erstrecken, gesäumt von Pinienwäldern. Für Reisende mit Hund bietet Alghero eine reizvolle Mischung aus Kulturerbe und Natur: Der Spaziergang entlang der Bastionen an der Leine ist bei Sonnenuntergang ein Genuss, und die Küstenwege gleichen die sommerlichen Einschränkungen an den bewachten Stränden aus.`,
    petTips: [`Sommerverbot an bewachten Stränden: Von Juni bis September sind Hunde an den Hauptstränden wie Le Bombarde verboten; peilen Sie die Nebensaison in der Morgendämmerung an und erkunden Sie den geduldeten Pinienwaldbereich Maria Pia.`, `Sardische Sommerhitze: Gehen Sie früh morgens und nach Sonnenuntergang spazieren und testen Sie Sand und Pflaster mit der Hand, bevor Sie Ihren Hund darauf laufen lassen.`, `Der Abendspaziergang entlang der Bastioni ist an der Leine perfekt, aber die Wälle sind im Sommer sehr belebt: Bevorzugen Sie den späten Nachmittag an einem Wochentag.`, `Hunde sind in der Neptunsgrotte nicht erlaubt: Planen Sie einen Begleiter ein, der draußen wartet, oder erkunden Sie stattdessen die Klippen von Capo Caccia.`, `Auf den Wegen von Capo Caccia gibt es wenig Schatten und keine Wasserstelle: Führen Sie immer Wasser und einen faltbaren Napf für Ihren Hund mit.`],
    practicalInfo: [`Der Flughafen Alghero-Fertilia (AHO) liegt etwa 10 km entfernt und ist mit mehreren italienischen und europäischen Städten verbunden; Fähren vom Festland (Genua, Civitavecchia, Barcelona) legen in Porto Torres, 35 km nördlich, an.`, `Auf den Fähren akzeptieren die Reedereien Hunde nach eigenen Regeln, in Bordzwingern oder auf Außendecks mit Leine und Maulkorb; prüfen Sie die Bedingungen bei der Buchung.`, `Europas einheitliche Notrufnummer ist 112, gültig für jeden menschlichen Notfall; für Ihren Hund suchen Sie bei Ankunft eine Tierklinik in Alghero.`, `Italienische Vorschriften: Mikrochip und Impfausweis sind vorgeschrieben, eine Leine ist im öffentlichen Raum erforderlich, und ein Maulkorb muss in öffentlichen Verkehrsmitteln und an belebten Orten griffbereit sein.`, `Die Hauptsaison läuft von Juni bis September: Haustierfreundliche Unterkünfte in Alghero und entlang der Riviera sind schnell ausgebucht, buchen Sie für den Sommer mehrere Monate im Voraus.`],
    sights: {
      "Bastioni di Alghero": `Rundgang auf den Wällen und Bastionen aus dem 16. Jahrhundert, die die zum Meer gewandte Altstadt umringen. Ein kostenloser, schattiger Spaziergang bei Sonnenuntergang, angeleinte Hunde fühlen sich auf dieser Panoramaroute vollkommen zu Hause.`,
      "Grotta di Nettuno": `Eine spektakuläre Meereshöhle am Fuß von Capo Caccia, per Boot oder über die Treppe Escala del Cabirol (654 Stufen) erreichbar. Hunde sind im Inneren der Höhle nicht erlaubt; lassen Sie Ihren bei einem Begleiter draußen oder genießen Sie stattdessen die Klippen.`,
      "Capo Caccia": `Ein Kalksteinvorgebirge mit steilen Klippen, das die Bucht von Alghero abschließt, ein Rückzugsort für Greifvögel und ein Aussichtspunkt bei Sonnenuntergang. Freiluftwege, auf denen angeleinte Hunde willkommen sind; bringen Sie Wasser mit, da es kaum Schatten gibt.`,
      "Spiaggia di Maria Pia": `Ein weißer Sandstrand, gesäumt von einem Pinienwald nördlich der Stadt, ruhiger als die großen südlichen Strände. Innerhalb der Pinienwaldzone gibt es einen geduldeten Bereich für Hunde; beachten Sie örtliche Schilder, da sich die Sommerregeln jede Saison ändern können.`,
      "Spiaggia di Le Bombarde": `Einer der schönsten Strände der Umgebung, mit türkisfarbenem Wasser und feinem Sand, beliebt bei Surfern. Hunde sind in der sommerlichen Hochsaison an diesem bewachten Strand verboten; außerhalb der Saison wird ein früher Besuch an der Leine geduldet.`,
      "Porto di Alghero": `Eine Marina, gesäumt von einer langen, lebendigen Promenade zwischen Altstadt und Hafen, mit Terrassen und Korallengeschäften. Ein angenehmer Spaziergang an der Leine das ganze Jahr über, und die meisten Terrassen dulden Hunde draußen.`,
    },
  },
  alicante: {
    history: `Alicante, Hauptstadt der gleichnamigen Provinz und eine der größten Städte der Costa Blanca (335.000 Einwohner), erstreckt sich am Fuß des Berges Benacantil, gekrönt vom Castillo de Santa Bárbara, einer maurischen Festung aus dem 9. Jahrhundert, die nach der Reconquista 1248 zur christlichen Festung wurde. Der von den Römern als Lucentum gegründete Mittelmeerhafen wird heute von der Explanada de España beherrscht, gepflastert mit 6.600 roten, weißen und schwarzen Marmorfliesen in Wellenmuster, mit Blick zur Marina. Für Hundebesitzer ist Alicante eine der wirklich haustierfreundlichsten Basen an der spanischen Küste: Mittelmeerklima mit über 320 Sonnentagen im Jahr, sehr milde Winter (12-13 °C im Januar), die Playa de Agua Amarga, offiziell einer der wenigen ganzjährigen Hundestrände Spaniens, der Küstenweg Serra Grossa mit Blick über den Golf und ein TRAM-Metropolitano-Netz, das nordwärts bis Benidorm fährt. Die levantinische Kultur heißt Haustiere auf den Terrassen des Casco Antiguo (Santa Cruz) und der Explanada herzlich willkommen, und der internationale Flughafen ALC, 9 km westlich, ist einer der großen Low-Cost-Drehkreuze Südeuropas.`,
    petTips: [`Brutale Sommerhitze: Von Juni bis September liegen die Durchschnittswerte bei 28-30 °C, der Boden übersteigt nachmittags auf der Marmor-Explanada 50 °C. Gehen Sie vor 9 und nach 20 Uhr spazieren und testen Sie den Boden 5 Sekunden lang mit der Hand, wenn Sie es nicht aushalten, der Hund auch nicht.`, `Strände mit Sommerverbot: Playa del Postiguet und Playa de San Juan verbieten Hunde vom 1. Mai bis 1. Oktober, städtisches Bußgeld bis 300 €. Ganzjährig erlaubt: nur Playa de Agua Amarga, 4 km südlich mit dem TAM-Bus 21 erreichbar.`, `TRAM Metropolitano d'Alacant: Hunde unter 10 kg in geschlossenen Transportboxen fahren kostenlos, größere angeleinte Hunde mit Maulkorb nach Ermessen des Fahrers (außerhalb der Stoßzeiten meist unproblematisch). Linie 1 nach Benidorm-Denia ist besonders reizvoll.`, `Städtischer TAM-Bus (Vectalia): Hunde unter 10 kg in Transportboxen kostenlos, große Hunde mit Maulkorb sind außer Assistenzhunden nicht zugelassen. Die Flughafenlinie ALC C-6 (3,85 €) nimmt kleine Hunde in Transportboxen mit.`, `24/7-Tiernotdienst: Hospital Veterinario Alicante im Polígono Pla de la Vallonga (+34 965 109 044, www.hospitalveterinarioalicante.es) deckt den Großraum ab, etwa 10 Minuten mit dem Taxi vom Zentrum. Kein kommunaler Streunerdienst nachts.`],
    practicalInfo: [`Der Flughafen Alicante-Elche (ALC) liegt 9 km westlich, eines der großen Low-Cost-Drehkreuze Südeuropas (Ryanair, easyJet, Vueling). Buslinie C-6 (3,85 €, kleine Hunde in Transportboxen erlaubt) alle 20 Minuten ins Zentrum, Taxi 25-30 €.`, `TRAM Metropolitano d'Alacant: moderne Stadtbahn, die die Stadt durchquert und nordwärts nach Benidorm (1:05 Std.) und weiter nach Denia (2:15 Std.) fährt. Hunde unter 10 kg in Transportboxen kostenlos, größere Hunde mit Maulkorb außerhalb der Stoßzeiten.`, `Renfe-Cercanías-Linie C-1 nach Murcia (1:20 Std.) und AVE-Hochgeschwindigkeitszüge Madrid-Alicante (2:30 Std.) oder Barcelona-Alicante (4:45 Std.). Kleine Hunde in Transportboxen kostenlos, große Hunde mit Maulkorb im AVE erlaubt (10 € Aufpreis).`, `ALSA-Fernbusse vom Busbahnhof nach Valencia (2:30 Std.), Murcia (1:15 Std.), Calpe (1:15 Std.), Almería (4 Std.), kleine Hunde in Transportboxen kostenlos, große Hunde nach Ermessen des Fahrers.`, `EU-Heimtierausweis für alle EU-Reisenden erforderlich (Mikrochip + aktuelle Tollwutimpfung). Britische Reisende nach dem Brexit: Animal Health Certificate (AHC), maximal 4 Monate gültig, 10 Tage vor Abreise beim Tierarzt beantragen.`],
    sights: {
      "Castillo de Santa Bárbara": `Maurische Festung aus dem 9. Jahrhundert auf dem Berg Benacantil (166 m), zu Fuß über den Südpfad oder per Aufzug von der Playa del Postiguet erreichbar. Angeleinte Hunde sind auf allen Außenwegen und Wällen erlaubt, jedoch nicht in den Museumsräumen.`,
      "Playa de Agua Amarga": `Offizieller ganzjähriger Hundestrand 4 km südlich des Zentrums, einer der wenigen in Spanien. Goldener Sand, 450 m lang, Hundeduschen und Abfallbehälter, erreichbar mit der TAM-Buslinie 21 oder mit dem Auto (kostenlose Parkplätze). Freilauf auf dem Sand erlaubt.`,
      "Explanada de España": `Ikonische 500 m lange Uferpromenade mit Blick zur Marina, gepflastert mit 6.600 roten, weißen und schwarzen Marmorfliesen in Wellenmuster, gesäumt von vier Palmenreihen. Angeleinte Hunde jederzeit willkommen, durchgehend hundefreundliche Terrassen.`,
      "Serra Grossa": `Kleiner 3 km langer Küstenkamm zwischen der Stadt und der Playa de San Juan, ein ehemaliger Steinbruch, heute ein ausgeschilderter Wanderweg. Panoramablick über den Golf von Alicante, angeleinte Hunde, wenig Schatten, im Sommer zwischen 11 und 17 Uhr meiden.`,
      "Parque El Palmeral": `Großer, 11 ha großer städtischer Park 3 km südlich, ein schattiger Palmenhain mit künstlichen Seen, Bächen und Picknickbereichen. Angeleinte Hunde überall, vollständig eingezäunte Freilaufzone im Nordteil mit automatischer Bewässerung.`,
      "Barrio de Santa Cruz": `Historische Altstadt am Hang des Benacantil, weiß getünchte Gassen, blumengeschmückte Treppen und mit Bougainvillea bewachsene Fassaden. Auf den Tapas-Terrassen sehr hundefreundlich, steile Treppen sollten in den heißesten Stunden gemieden werden.`,
    },
  },
  almeria: {
    history: `An der trockenen Südostküste Andalusiens gelegen, verdankt Almería seinen Namen dem arabischen „al-Mariyya", dem Wachturm, und sein goldenes Zeitalter dem Kalifat von Córdoba, das die Stadt im 10. Jahrhundert zu einem der bedeutenden Mittelmeerhäfen machte. Aus dieser Zeit ist die Alcazaba erhalten, die zweitgrößte maurische Festung Spaniens nach der Alhambra, deren Wälle noch heute über die Stadt ragen. Ringsum liegt eine einzigartige mineralische Landschaft: Der Naturpark Cabo de Gata entfaltet seine vulkanische Küste und wilde Strände, während die Wüste Tabernas, die einzige Wüste Europas, unzähligen Italowestern als Kulisse diente. Almería gilt als die trockenste und sonnenreichste Stadt Europas, was ihren Reiz ausmacht, von Reisenden mit Hund jedoch ständige Vorsicht gegen Hitze und Wasserknappheit verlangt, besonders an den wilden Stränden von Cabo de Gata.`,
    petTips: [`Europas trockenste und heißeste Stadt: Gehen Sie im Sommer nur bei Sonnenaufgang und nach Sonnenuntergang spazieren und testen Sie den glühend heißen Boden mit der Hand, bevor Sie Ihren Hund darauf laufen lassen.`, `Wasserknappheit in Cabo de Gata: Die wilden Strände haben weder Brunnen noch Geschäft, führen Sie also immer mehrere Liter Wasser und einen faltbaren Napf für Ihren Hund mit.`, `Sommerverbot an bewachten Stadtstränden: Von Juni bis September weichen Sie auf die unbewachten Strände von Cabo de Gata aus, wo angeleinte Hunde in der Regel geduldet werden.`, `Vorbeugung gegen Leishmaniose: Die Sandmücke ist an der andalusischen Küste endemisch, schützen Sie Ihren Hund daher mit einem insektenabweisenden Halsband oder Spot-on, besonders in der Dämmerung.`, `Sogenannte PPP-Rassen müssen im öffentlichen Raum eine kurze Leine und einen Maulkorb tragen: Halten Sie den Maulkorb im Stadtzentrum und in öffentlichen Verkehrsmitteln griffbereit.`],
    practicalInfo: [`Der Flughafen Almería (LEI) liegt etwa 10 km entfernt und ist mit Madrid, Barcelona und mehreren europäischen Städten verbunden; ein Renfe-Bahnhof bietet Verbindungen nach Granada und Madrid.`, `Die Wüste Tabernas und Cabo de Gata besuchen Sie am besten mit dem Auto: Wählen Sie einen Mietwagen, der Haustiere akzeptiert, denn öffentliche Verkehrsmittel bedienen diese Naturgebiete kaum.`, `Spaniens einheitliche Notrufnummer ist 112, gültig für jeden menschlichen Notfall; für Ihren Hund suchen Sie bei Ankunft eine Tierklinik in Almería.`, `Spanische Vorschriften: EU-Heimtierausweis und Mikrochip sind vorgeschrieben, und sogenannte PPP-Rassen müssen im öffentlichen Raum eine kurze Leine und einen Maulkorb tragen.`, `Die Hauptsaison von Juni bis September bringt extreme Hitze: Buchen Sie klimatisierte, haustierfreundliche Unterkünfte frühzeitig, wichtig für den Komfort Ihres Hundes.`],
    sights: {
      "Alcazaba de Almería": `Eine weitläufige maurische Festung aus dem 10. Jahrhundert, die zweitgrößte Spaniens, mit terrassierten Gärten und Wällen mit Blick über die Stadt. Ein Freiluftkomplex, in dem angeleinte Hunde auf den Wegen im Allgemeinen zugelassen sind; prüfen Sie die Regel am Eingang, da sie sich ändern kann.`,
      "Parque Natural de Cabo de Gata": `Eine geschützte vulkanische Küste mit wilden Stränden und kristallklaren Buchten östlich der Stadt. Angeleinte Hunde sind auf vielen Wegen und unbewachten Stränden zugelassen, manche Bereiche sind jedoch reguliert; bringen Sie Wasser mit, da es nirgends welches gibt.`,
      "Paseo Marítimo de Almería": `Eine lange, palmengesäumte Uferpromenade zwischen dem Hafen und den Stadtstränden, gesäumt von Terrassen. Ein angenehmer Spaziergang an der Leine außerhalb der heißesten Stunden, die meisten Terrassen dulden Hunde draußen.`,
      "Refugios de la Guerra Civil": `Ein Netz unterirdischer Schutzräume, während des Spanischen Bürgerkriegs unter der Stadt angelegt, zu den besterhaltenen Europas gehörend, nur mit Führung zu besichtigen. Hunde sind im Inneren nicht zugelassen; lassen Sie einen Begleiter für die Dauer der Führung draußen warten.`,
      "Desierto de Tabernas": `Die einzige Wüste Europas, etwa dreißig Kilometer nördlich, berühmt für ihre noch stehenden Kulissen aus Italowestern. Ein Tagesausflug: Angeleinte Hunde sind in den Freilandschaften willkommen, doch die Hitze ist extrem, halten Sie sich also an die kühleren Stunden mit reichlich Wasser.`,
      "Playa de San Miguel": `Ein großer sandiger Stadtstrand am Ende des Paseo Marítimo, im Sommer bewacht und lebendig. Hunde sind in der sommerlichen Hochsaison verboten; außerhalb der Saison wird ein früher Spaziergang an der Leine geduldet. Weichen Sie im Sommer auf die unbewachten Strände von Cabo de Gata aus.`,
    },
  },
  amalfi: {
    history: `Am Fuß einer steilen Schlucht auf der Südseite der Sorrentiner Halbinsel gelegen, war Amalfi im Mittelalter eine mächtige Seerepublik, Rivalin von Venedig, Genua und Pisa, deren Schiffe bis nach Byzanz und Ägypten Handel trieben. Aus jenem goldenen Zeitalter ist die imposante gestreifte Kathedrale Sant'Andrea über ihrer großen Treppe erhalten, ebenso der Kreuzgang des Paradieses, und eine Tradition der Papierherstellung, die im Tal darüber noch lebendig ist. Eine Flutwelle im Jahr 1343 verschlang einen Teil der Unterstadt, doch Amalfi blieb ein Handelszentrum. Heute ist es das Herz einer zum UNESCO-Weltkulturerbe zählenden Küste aus Treppen, terrassierten Zitronenhainen und hoch gelegenen Dörfern. Für Reisende mit Hund bietet es eine flachere, besser bewohnbare Basis als Positano, sofern man die Sommerhitze und die regulierten Strände einplant.`,
    petTips: [`Sommerhitze und heißes Gestein: Von Juni bis August gehen Sie bei Sonnenaufgang und am Abend spazieren und testen Kiesel und Fels mit der Hand, da sie am Nachmittag Pfoten verbrennen können.`, `Regulierte Strände: Hunde sind von Juni bis September an den meisten öffentlichen Stränden verboten; für einen richtigen Badespaß fahren Sie weiter östlich Richtung Salerno zu einem ausgewiesenen Hundestrand.`, `Maulkorbpflicht in öffentlichen Verkehrsmitteln: SITA-Busse, lokale orangefarbene Busse und die Fähren von Travelmar/Alilauro akzeptieren angeleinte, mit Maulkorb versehene Hunde gegen einen kleinen Fahrpreis.`, `Terrassierte Küste: Nutzen Sie jenseits der flachen Uferpromenade die Lokalbusse nach Pogerola, Pontone und Ravello, statt bei Hitze hunderte Stufen zu erklimmen.`, `Gesperrte Innenräume: Die Kathedrale Sant'Andrea mit ihrem Kreuzgang lässt ebenso wie die Museen keine Hunde zu; planen Sie, sich für diese Besuche abzuwechseln.`],
    practicalInfo: [`Nächster Flughafen: Neapel (NAP), etwa 60 km entfernt; erreichen Sie Amalfi über die Küstenstraße oder saisonal per Fähre von Salerno oder aus der Bucht von Neapel.`, `Keine vollwertige Tierklinik in Amalfi selbst: die nächstgelegenen liegen in Vietri sul Mare Richtung Salerno und in Sorrent; speichern Sie die Nummer vor Wanderungen, bei denen der Empfang ausfällt.`, `Italiens einheitliche Notrufnummer ist 112, gültig für jeden menschlichen Notfall; halten Sie die Kontaktdaten eines Küsten-Tierarztes offline gespeichert.`, `Italienische (EU-)Vorschriften: EU-Heimtierausweis, Mikrochip und Tollwutimpfung sind vorgeschrieben; Maulkorb und Leine sind in den meisten öffentlichen Verkehrsmitteln erforderlich.`, `Die Hauptsaison von Juni bis September ist überlaufen und heiß: Buchen Sie haustierfreundliche Unterkünfte frühzeitig und bevorzugen Sie Frühling oder Herbst für Reisen mit Hund.`],
    sights: {
      "Duomo di Sant'Andrea": `Eine spektakuläre Kathedrale mit gestreifter Fassade oben auf einer großen Treppe über dem Hauptplatz. Angeleinte Hunde können den Platz und die Stufen genießen, doch das Innere der Kathedrale und der Kreuzgang des Paradieses lassen keine Haustiere zu; wechseln Sie sich für den Besuch ab.`,
      "Valle delle Ferriere": `Ein kühles, schattiges Naturschutzgebiet mit Wasserfällen, Bächen und alten Eisenhütten in der Schlucht oberhalb von Amalfi. Angeleinte Hunde sind auf dem Wanderweg willkommen, im Sommer deutlich kühler als die Stadt; ein Ticket für das obere Schutzgebiet kaufen Sie am Informationspunkt in Pontone.`,
      "Torre dello Ziro": `Ein verfallener Wachturm auf dem Grat zwischen Amalfi und Atrani, über einen kurzen, steilen Pfad von Pontone aus erreichbar, mit weitem Blick über beide Buchten. Angeleinte Hunde willkommen; der Turmbereich ist nicht eingezäunt, halten Sie sie also nahe bei sich.`,
      "Marina Grande (spiaggia)": `Amalfis Hauptstrand aus Kieseln unterhalb der Stadt, größtenteils in private Strandbäder unterteilt, mit einem kleinen freien Abschnitt. Hunde sind in den Strandbädern in der Regel nicht erlaubt und werden im Sommer ferngehalten; die ruhigeren Buchten Duoglio und Santa Croce sind außerhalb der Saison toleranter.`,
      "Atrani": `Eines der kleinsten Dörfer Italiens, in der nächsten Bucht, ein kurzer flacher Spaziergang von Amalfi entfernt, mit einem geschützten Platz und einem Labyrinth stiller Gassen. Ein unberührter Ort, ideal für einen Spaziergang an der Leine und ein entspanntes Abendessen.`,
      "Ravello": `Eine elegante Gartenstadt hoch über Amalfi, berühmt für die auf Klippen liegenden Gärten der Villa Rufolo und der Villa Cimbrone. Angeleinte Hunde in der Stadt willkommen; die Gartenvillen lassen in der Regel angeleinte Hunde zu, bestätigen Sie dies am Eingang. Fahren Sie mit dem lokalen orangefarbenen Bus hinauf.`,
    },
  },
  ambleside: {
    history: `Ambleside, eine stattliche Steinstadt am Kopf des Lake Windermere, entstand rund um seinen Markt, die Wassermühlen am Stock Ghyll und, ab dem 19. Jahrhundert, den romantischen Tourismus, den die Fjälls und Seen anzogen. Das nahegelegene Rydal Mount war das Zuhause des Dichters William Wordsworth, und die Gegend ist tief geprägt von der Kultur der Lake Poets. Heute ist Ambleside eine der großen Wanderbasen des zum UNESCO-Welterbe zählenden Lake District, dazu mit einer tief verwurzelten britischen Hundekultur: Hunde sind auf fast jedem Fjäll und Fußweg willkommen, fahren kostenlos mit den Windermere Lake Cruises ab Waterhead und sind in den meisten Pubs gern gesehen. Wandern ist der Grund, hierher zu kommen, vom Wasserfall Stock Ghyll Force wenige Minuten vom Zentrum bis zum weitläufigen Loughrigg Fell. Das winzige Bridge House, auf einem Bogen über den Bach thronend, ist das Wahrzeichen der Stadt. Ein praktischer Hinweis: Seit dem Brexit ist für Hunde aus der EU ein GB Animal Health Certificate erforderlich.`,
    petTips: [`Halten Sie Ihren Hund in der Nähe von Schafen und Rindern auf den Fjälls sowie während der Brutzeit bodenbrütender Vögel im Frühling an der Leine; ein zuverlässiger Rückruf ist auf offenem Fjäll unerlässlich.`, `Achten Sie im Sommer auf Blaualgen im Windermere und im Rydal Water, die für Hunde potenziell tödlich sind, und prüfen Sie das Wasser vor jedem Schwimmen bei Waterhead oder White Moss.`, `Hunde fahren kostenlos mit den Windermere Lake Cruises ab Waterhead (an der Leine) und, in den National-Rail-Zügen nach Windermere, bis zu zwei pro Fahrgast.`, `Die meisten Pubs heißen Hunde in der Bar willkommen, und der Royal Oak bietet sogar eine Hundespeisekarte; fragen Sie, welcher Bereich hundefreundlich ist.`, `Tierarztnummern: die Ambleside-Filiale von Oakhill (+44 15394 32631), Oakhills 24-Stunden-Leitung in Windermere (+44 15394 88555) und die Vets-Now-Klinik in Kendal (+44 1539 232221).`],
    practicalInfo: [`Einreise nach dem Brexit: Großbritannien akzeptiert den EU-Heimtierausweis nicht mehr; Hunde benötigen ein GB Animal Health Certificate (innerhalb von 10 Tagen ausgestellt), einen Mikrochip, eine Tollwutimpfung und eine Bandwurmbehandlung 24 bis 120 Stunden vor Ankunft.`, `Anreise: kein Flughafen oder Bahnhof in Ambleside; Zug nach Windermere, dann der hundefreundliche Bus 555 oder 599. Der nächste Flughafen ist Manchester (MAN), etwa 90 Minuten bis zwei Stunden mit dem Auto.`, `Fortbewegung: eine kompakte, zu Fuß erkundbare Stadt; Stagecoach-Busse und die Windermere Lake Cruises ab Waterhead verbinden Bowness, Grasmere und Windermere.`, `Wetter: eine der regenreichsten Ecken Englands; packen Sie ganzjährig Regenkleidung und ein Hundehandtuch ein, mit milden Sommern (17-18 °C) und kalten, nassen Wintern (4-5 °C).`, `Nützliche Nummern: allgemeiner Notruf 999 oder 112; Oakhill Ambleside +44 15394 32631; 24-Stunden-Oakhill Windermere +44 15394 88555; außerhalb der Öffnungszeiten Vets Now Kendal +44 1539 232221.`],
    sights: {
      "Stock Ghyll Force": `Ein 21 Meter hoher Wasserfall am Ende eines leichten Waldspaziergangs wenige Minuten vom Market Cross entfernt. Hunde können unter Kontrolle im Wald ohne Leine laufen, in der Nähe von Wasser und Straße an der Leine.`,
      "Loughrigg Fell": `Ein niedriges, weitläufiges Fjäll zwischen Ambleside, Rydal und Grasmere mit gewaltigen Ausblicken und der Rydal Cave. Hunde unter Kontrolle ohne Leine, in der Nähe von Schafen an der Leine.`,
      "Rydal Water": `Ein kleiner, flacher See mit stillen Buchten, ein Favorit zum Hundeschwimmen, erreichbar durch den Wald von White Moss. Vor dem Schwimmen auf Blaualgen prüfen.`,
      "Windermere Lake Cruises (Waterhead)": `Klassische Dampfer und Boote vom Pier in Waterhead nach Bowness, Brockhole und Lakeside. Hunde fahren kostenlos, an der Leine gehalten, mit Wassernäpfen an Bord.`,
      "Bridge House": `Das winzige Haus aus dem 17. Jahrhundert auf einem Bogen über den Stock Beck, das Wahrzeichen von Ambleside. Draußen sind Treppen und Garten rund um die Uhr geöffnet; im Inneren nur Assistenzhunde.`,
      "Stagshaw Garden": `Ein Waldgarten des National Trust oberhalb von Waterhead, im Frühling berühmt für seine Rhododendren, mit Wegen hinauf zu Jenkin Crag. Hunde an der Leine (Weidevieh).`,
    },
  },
  amsterdam: {
    history: `Im 13. Jahrhundert um einen Damm am Fluss Amstel gegründet, daher der Name, wurde Amsterdam während des niederländischen Goldenen Zeitalters zur Handelshauptstadt der Welt. Die VOC (Niederländische Ostindien-Kompanie), der erste Multinationalkonzern der Geschichte, hatte hier ihren Sitz. Dieser Wohlstand finanzierte die 165 Grachten, 1.500 Brücken und schmalen Giebelhäuser des zum UNESCO-Welterbe zählenden historischen Zentrums. Die Stadt pflegt seit jeher eine Kultur der Toleranz und Offenheit, die sich auch auf Hunde erstreckt, die in Cafés, auf Terrassen und sogar in öffentlichen Verkehrsmitteln willkommen sind.`,
    petTips: [`Hunde fahren in der Amsterdamer Metro, Straßenbahn und im Bus kostenlos mit, wenn sie in einer Tasche getragen oder angeleint und mit Maulkorb versehen sind. Andernfalls ist ein „Hundeticket" (Kindertarif) erforderlich.`, `Die meisten Caféterrassen akzeptieren Hunde. Fragen Sie einfach; eine Ablehnung ist im Stadtzentrum selten.`, `Grachtenwasser ist zwar technisch befahrbar, enthält aber Bakterien: Hindern Sie Ihren Hund daran, daraus zu trinken oder darin zu schwimmen.`, `Fahrräder beherrschen die Straße: Bleiben Sie aufmerksam und halten Sie Ihren Hund auf belebten Straßen an einer kurzen Leine.`, `Mehrere Parks verfügen über Trinkwasserzapfstellen für Hunde, darunter der Vondelpark.`],
    practicalInfo: [`24/7-Tiernotdienst: Dierenkliniek Boerhaave, +31 20 662 60 03`, `Tierapotheke: bei den meisten Tierärzten im Stadtzentrum erhältlich`, `Züge aus London (Eurostar): Haustiere in Taschen oder Transportboxen kostenlos akzeptiert; große Hunde auf ausgewählten Verbindungen mit Ticket`, `Flughafen Schiphol: keine Quarantäne für EU-Haustiere mit gültigem Heimtierausweis`],
    sights: {
      "Vondelpark": `Der größte Park der Stadt (47 ha) ist der beliebteste Spielplatz der Amsterdamer und ihrer Hunde. Mehrere Bereiche sind offiziell Freilaufzonen. Ideal am Morgen vor dem Besuch des nahegelegenen Rijksmuseums.`,
      "Jordaan": `Das ehemalige Arbeiterviertel, das zu Amsterdams elegantestem Stadtteil wurde, eignet sich ideal für Spaziergänge mit Hund. Kopfsteinpflasterstraßen, kleine Grachten und Caféterrassen, oft hundefreundlich, machen es zu einem unverzichtbaren Spaziergang. Verpassen Sie samstags nicht den Noordermarkt.`,
      "Amsterdamse Bos": `Der „Amsterdamer Wald" ist dreimal so groß wie der Vondelpark und bietet kilometerlange Waldwege, Seen zum Hundeschwimmen und offene Wiesen. Hunde können in den meisten Bereichen frei laufen. 20 Minuten mit dem Fahrrad vom Zentrum entfernt.`,
      "Rijksmuseum": `Das niederländische Nationalmuseum beherbergt Meisterwerke von Rembrandt und Vermeer. Hunde sind im Inneren nicht zugelassen, aber der Museumshof (Museumplein) und die Gärten sind zugänglich. Eine Gepäckaufbewahrung steht zur Verfügung, um Leine und Rucksack zu deponieren.`,
      "Quartier des canaux (Grachtengordel)": `Der Grachtengürtel aus dem 17. Jahrhundert bildet das Rückgrat Amsterdams. Die Kais entlang der Herengracht, Keizersgracht und Prinsengracht eignen sich perfekt für einen Hundespaziergang. Hinweis: Die meisten Grachtenrundfahrten akzeptieren keine Haustiere.`,
      "Marché Albert Cuyp": `Amsterdams größter Freiluftmarkt (Pijp) ist lebendig, bunt und sehr tolerant gegenüber angeleinten Hunden. Stroopwafels, frischer Hering und Schnittblumen, eine geballte Ladung niederländisches Leben. Montags bis samstags geöffnet.`,
    },
  },
  angers: {
    history: `Angers, die historische Hauptstadt des Anjou, entwickelte sich aus einer gallischen Fluchtburg am Zusammenfluss von Maine und Sarthe zu einem karolingischen Zentrum und danach zum Sitz der Grafen von Anjou, deren Plantagenet-Nachkommen vom 12. bis 13. Jahrhundert England regierten. Das Château d'Angers, eine 17-türmige Festung, die um 1230 vom heiligen Ludwig erbaut wurde, beherbergt heute den Apokalypse-Wandteppich (104 Meter, der größte mittelalterliche Wandteppich der Welt, gewebt um 1380). Die Stadt war lange ein bedeutendes Universitäts- und Weinzentrum und bleibt die Metropole einer renommierten Weinbauregion (Anjou, Saumur, Coteaux du Layon). Für Reisende mit Hund bietet Angers ein kompaktes Fußgängerzentrum, über 700 Hektar städtische Grünflächen, eine 24/7-Regionaltierklinik und eine direkte TGV-Verbindung nach Paris-Montparnasse in 1:30 Std. Nantes und der Atlantik sind 45 Minuten mit dem TER entfernt, Tours und die Loire-Schlösser eine Stunde.`,
    petTips: [`Das Château d'Angers lässt angeleinte Hunde auf dem frei zugänglichen Rundgang auf den Außenwällen und in den Grabengärten zu, jedoch nicht im Bergfried oder in der Galerie des Apokalypse-Wandteppichs; planen Sie ein, dass eine Person draußen wartet.`, `Das Irigo-Netz (Straßenbahn A + Busse) nimmt kleine Hunde in geschlossener Transportbox kostenlos mit; größere Hunde sind nach Ermessen des Fahrers mit Maulkorb und Leine zugelassen, meiden Sie die Stoßzeiten.`, `In allen städtischen Parks von Angers gilt Leinenpflicht (Bußgelder bis 68 €). Nur die Waldwege des Parc de Pignerolle, 8 km östlich, dulden Freilauf.`, `Der Badestrand am Lac de Maine ist von Juni bis September für Hunde gesperrt. Den Rest des Jahres ist das Ufer zugänglich und eignet sich gut für einen Wadegang.`, `TER-Züge nach Nantes, Tours oder Saumur akzeptieren Hunde zum Pauschalpreis von 7 € (kostenlos für kleine Hunde unter 6 kg in einer Transportbox).`],
    practicalInfo: [`Regionaler Tiernotdienst (24/7, Überweisung): 02 41 47 26 26`, `Landesweite kostenlose Tiernotfall-Hotline (24/7): 3115`, `Tierheim SPA Angers: 02 41 36 13 26`, `Bahnhof Angers Saint-Laud: TGV nach Paris-Montparnasse 1:30 Std.; TER nach Nantes 45 Min., Tours 1 Std., Saumur 25 Min.`, `Nächster Flughafen: Nantes Atlantique (NTE), 90 km westlich`],
    sights: {
      "Château d'Angers": `Mittelalterliche Festung aus dem 13. Jahrhundert mit 17 Türmen aus schwarzem Schiefer über der Maine. Angeleinte Hunde sind auf dem frei zugänglichen Rundgang auf den Außenwällen und in den Grabengärten willkommen; sie dürfen weder den Bergfried noch die Galerie des Apokalypse-Wandteppichs betreten.`,
      "Parc de Pignerolle": `Ein 80 Hektar großer Landschaftspark rund um ein Schloss aus dem 18. Jahrhundert, 8 km östlich von Angers. Hunde können auf den ausgeschilderten Waldwegen frei laufen (in den formalen Gärten gilt Leinenpflicht). Er ist das wichtigste Ziel für Hundespaziergänge im Großraum.`,
      "Promenade du Bout du Monde": `Der charakteristische Uferweg am Fuß der Schlosswälle, entlang der Maine. Eine breite gepflasterte Allee mit schattigen Bänken, direktem Blick auf die Festung und die Pont de Verdun, das ganze Jahr über für angeleinte Hunde geöffnet.`,
      "Quartier de la Doutre": `Das mittelalterliche Viertel am linken Maine-Ufer, mit Fachwerkhäusern rund um die Place de la Laiterie und die Place du Tertre Saint-Laurent. Fast vollständig fußgängerfreundlich, hundefreundlich auf den Terrassen und beim Samstagvormittagsmarkt der Kunsthandwerker.`,
      "Cathédrale Saint-Maurice": `Gotische Kathedrale aus dem 12.-13. Jahrhundert mit geschnitzter Schirmfassade und der reichsten Sammlung sakraler Kunst Westfrankreichs. Hunde sind im Inneren nicht zugelassen, aber der Vorplatz und die monumentale Treppe sind zugänglich und bieten einen der schönsten Ausblicke auf das Zentrum.`,
      "Lac de Maine": `Ein 100 Hektar großer städtischer See am Südwestrand von Angers, umgeben von einem 220 Hektar großen Freizeitpark. Angeleinte Hunde sind auf Wegen und Ufer das ganze Jahr über erlaubt, außer am ausgewiesenen Badestrand von Juni bis September.`,
    },
  },
  annecy: {
    history: `Annecy, im 12. Jahrhundert als gallo-römisches Dorf unterhalb der Burg der Grafen von Genf gegründet, wurde im 16. Jahrhundert Hauptstadt von Savoyen, als Herzog Franz von Sales hier seinen Sitz errichtete. Der Verkauf Savoyens durch Napoleon III. im Jahr 1860 band die Stadt an Frankreich; der romantische Tourismus des 19. Jahrhunderts (Lamartine hielt sich hier auf) brachte ihr den Beinamen „Venedig der Alpen" ein. Die durch die Vieille Ville fließenden Kanäle Thiou und Vassé, der dreieckige Palais de l'Île und der Pont des Amours ergeben das nach dem Mont-Saint-Michel meistreproduzierte Postkartenmotiv Frankreichs. Für Reisende mit Hund ist Annecy eines der vollständigsten Hundereiseziele Frankreichs: eine in 15 Minuten zu Fuß erkundbare Vieille Ville, eine standardmäßig hundetolerante savoyardische Brasseriekultur, ein See mit kristallklarem Wasser (Klasse A), das Hunde bedenkenlos trinken können, ein flacher, 42 km langer Radweg, der ihn komplett umrundet, und der Wald von Semnoz auf 1.699 m direkt südlich mit 50 km Freilaufwegen. Genf ist 40 Minuten mit dem direkten TER entfernt.`,
    petTips: [`Die savoyardische Café-/Brasseriekultur heißt Hunde standardmäßig willkommen, etwa 80 % der Lokale in Annecy akzeptieren angeleinte Hunde auf der Terrasse.`, `SIBRA-Busse und TER-Züge: mittlere/große Hunde zum halben Fahrpreis (1 € bei SIBRA), im TER mit Leine und Maulkorb; kleine Hunde in der Transportbox kostenlos.`, `Offizieller Hundestrand bei Les Marquisats, 10 Gehminuten vom Zentrum, ganzjährig geöffnet.`, `24/7-Tiernotdienst: Vétérys in Argonay (+33 4 50 63 22 22), 12 Minuten mit dem Auto über die D14.`, `Das Annecy Animation Festival (Juni), die Fête du Lac (erster Samstag im August, 200.000 Besucher plus Feuerwerk) und das Sechs-Nationen-Rugby (März-April) bringen dichtes Gedränge, meiden Sie diese Termine mit einem ängstlichen Hund.`],
    practicalInfo: [`Frankreich ist Mitglied der EU und des Schengen-Raums: EU-Heimtierausweis + gültige Tollwutimpfung + ISO-Mikrochip genügen aus jedem EU-Land.`, `Direkte TER-Züge: Genf 40 Min., Aix-les-Bains 35 Min., Lyon 1:45 Std., Chamonix 2 Std. (Umstieg in La-Roche-sur-Foron), Paris 4 Std. (TGV über Bellegarde).`, `Der Flughafen Genf (GVA) ist 40 Minuten mit dem TER plus 8 Minuten Flughafenshuttle entfernt, deutlich hundefreundlicher als Lyon Saint-Exupéry (1:45 Std.) für internationale Flüge.`, `Währung: Euro. Tagesbudget mit Hund: 80-110 €/Tag ohne Unterkunft, alpines Kurortpreisniveau, aber niedriger als Genf.`, `Parken: Die Vieille Ville ist eine kostenpflichtige Fußgängerzone; nutzen Sie Tiefgaragen (Bonlieu, Hôtel de Ville) für 2-3 €/Stunde.`],
    sights: {
      "Palais de l'Île": `Dreieckige Festung aus dem 12. Jahrhundert auf einer Insel im Kanal Thiou, das Postkartenmotiv von Annecy. Außenansicht rund um die Uhr hundefreundlich; das Museum im Inneren nur für Assistenzhunde.`,
      "Pont des Amours": `Eiserne Fußgängerbrücke von 1907 über den Kanal Vassé, die den Pâquier mit den Jardins de l'Europe verbindet, der romantischste Ort von Annecy. Rund um die Uhr geöffnet, hundefreundlich.`,
      "Le Pâquier": `7 Hektar große zentrale Rasenfläche zwischen dem See und dem Platz Le Pâquier, Seeblick, Eisdielen, Anschluss an die Avenue d'Albigny. Angeleinte Hunde.`,
      "Lake Annecy Cycle Path": `Flacher, 42 km langer Radweg rund um den See, autofrei, hundefreundlich, durchgehend Seeblick.`,
      "Forêt du Semnoz": `1.699 m hoher, bewaldeter Berg südlich des Zentrums, 50 km Freilaufwege außerhalb der Brutzeit, Ausblicke über den See und den Mont Blanc.`,
      "Château d'Annecy": `Burg aus dem 12.-15. Jahrhundert auf dem Hügel über der Vieille Ville, die Außenterrassen hundefreundlich mit angeleinten Hunden, das Museum im Inneren nur für Assistenzhunde.`,
    },
  },
  antibes: {
    history: `Antibes wurde im 6. Jahrhundert v. Chr. von den Phokäern unter dem Namen Antipolis (die Nizza gegenüberliegende Stadt) gegründet und ist einer der ältesten Häfen der Côte d'Azur. Römisch, dann genuesisch, ab 1481 französisch, erhielt sie im 17. Jahrhundert ihre zum Meer gewandten Vauban-Wälle. Im 19. Jahrhundert machten russische und britische Aristokraten sie zu einem Winterrückzugsort, und Juan-les-Pins erfand rund um sein Kasino von 1909 das Modell des Sommerferienorts. Picasso arbeitete 1946 einige Monate im Château Grimaldi, das heute das nach ihm benannte Museum beherbergt. Für reisende Haustiere schreibt Frankreich den EU-Heimtierausweis, den ISO-Mikrochip und eine gültige Tollwutimpfung vor. Angeleinte Hunde sind auf den Wällen, am Port Vauban, auf dem Marché Provençal und entlang des Küstenwegs von Cap d'Antibes ganzjährig willkommen; die städtischen Strände (La Salis, La Garoupe, La Gravette) verbieten Hunde vom 15. Juni bis 15. September.`,
    petTips: [`Die bewachten städtischen Strände (Salis, Garoupe, Gravette, Ponteil, plages de Juan) verbieten Hunde vom 15. Juni bis 15. September. Weichen Sie auf die Buchten des Sentier du Littoral rund um Cap d'Antibes aus, die ganzjährig zugänglich sind.`, `Der Parc Exflora zwischen Antibes und Golfe-Juan lässt überhaupt keine Hunde zu: planen Sie dort keinen Gartenspaziergang. Nutzen Sie stattdessen die Pinède Gould oder die Wälle von Antibes.`, `Das Envibus-Busnetz akzeptiert nur Blindenführhunde und kleine Haustiere in geschlossener Transportbox. Nutzen Sie für Fahrten entlang der Riviera (Cannes 10 Min., Nizza 20 Min.) besser TER-Züge als den Bus.`, `Im Juli und August spazieren Sie vor 9 oder nach 19 Uhr: Die Kalksteinwälle und Felsen am Cap speichern Hitze, die Pfotenballen verbrennen kann.`, `Das Cabinet Vétérinaire de la Clairière (04 93 61 06 78) in Juan-les-Pins übernimmt 24/7-Notfälle auf Abruf; auch die landesweite Hotline 3115 funktioniert entlang der gesamten Küste.`],
    practicalInfo: [`Anreise: Der SNCF-Bahnhof Antibes liegt an der Küstenlinie zwischen Cannes (10 Min.) und Nizza (20 Min.), TER alle 15 bis 30 Minuten. Der Flughafen Nizza Côte d'Azur (NCE) ist 25 Minuten mit dem Taxi entfernt. Hunde unter 6 kg in Transportbox 7,50 €; über 6 kg mit Leine und Maulkorb zum halben Erwachsenenpreis.`, `Strände: Hunde vom 15. Juni bis 15. September verboten (Salis, Garoupe, Gravette, Ponteil, Juan-les-Pins). Die Buchten des Sentier du Littoral und die unbewachten Küstenabschnitte am Cap sind ganzjährig zugänglich.`, `Parks: Pinède Gould, Jardin Albert 1er und der Wallrundgang heißen alle angeleinte Hunde willkommen. Der Parc Exflora lässt keine Hunde zu.`, `Tierärzte: Cabinet de la Clairière (Juan-les-Pins, 04 93 61 06 78, 24/7 auf Abruf), Clinique Antibes-Les-Pins (Notdienst-Weiterleitung an Clausonnes 04 93 65 40 54) sowie die kostenlose landesweite Hotline 3115.`, `Dokumente: EU-Heimtierausweis, ISO-Mikrochip und gültige Tollwutimpfung sind vorgeschrieben. Reisende von außerhalb der EU (UK, USA) benötigen ein Animal Health Certificate oder eine USDA-APHIS-Bestätigung.`],
    sights: {
      "Vieil Antibes": `Das Vieil Antibes, innerhalb der Vauban-Wälle, ist ein Labyrinth kopfsteingepflasterter Gassen rund um den Cours Masséna und das Château Grimaldi. Angeleinte Hunde sind hier vollkommen zu Hause, mit Terrassen überall, öffentlichen Brunnen und einem natürlichen 45-minütigen Rundgang entlang der Wälle und des Port Vauban.`,
      "Sentier du Littoral (Tirepoil)": `Der 5 km lange Küstenweg rund um die felsige Spitze von Cap d'Antibes ist einer der schönsten Hundespaziergänge an der Riviera. Die offizielle Tourismus-Website heißt angeleinte Hunde ausdrücklich willkommen. Rechnen Sie mit 1 bis 2 Stunden bei normalem Tempo und tragen Sie festes Schuhwerk: Der Fels ist bei Nässe rutschig.`,
      "Marché Provençal": `Unter dem eisernen Vordach des Cours Masséna öffnet der Marché Provençal jeden Morgen außer montags im Winter, im Sommer täglich: Gemüse aus dem Var, Fisch, Käse, Blumen, Socca und Tapenade. Angeleinte Hunde sind zwischen den Ständen willkommen, und die Verkäufer sind vollkommen an sie gewöhnt.`,
      "Port Vauban": `Eine der größten Yachtmarinas Europas, einschließlich des berühmten Quai des Milliardaires. Die flache Promenade rund um das Becken ergibt zu jeder Jahreszeit einen 30-minütigen Spaziergang mit Hund, und der Blick von der Bastion Saint-André über die Bucht bis zu den Alpen lohnt den Umweg.`,
      "Pinède Gould (Juan-les-Pins)": `Der Schirmpinienhain am Meer hinter dem Kasino von Juan-les-Pins ist das tägliche Spaziergebiet der Ortsansässigen: flache Sandwege, tiefer Schatten und Abfallbehälter an jedem Eingang. Während des Jazz-à-Juan-Festivals Mitte Juli geschlossen.`,
      "Plage de la Salis (off-season)": `Der lange sandige Bogen zwischen der Altstadt und dem Cap, mit dem schönsten Blick auf die Wälle von Antibes. Vom 15. Juni bis 15. September für Hunde gesperrt, wird er außerhalb der Saison zu einem der besten Strände für Hundespaziergänge an der Riviera, besonders bei Sonnenaufgang.`,
    },
  },
  arles: {
    history: `Arles, von den Griechen gegründet und später, nachdem Konstantin im 4. Jahrhundert dort residierte, römische Kaiserstadt, besitzt eine der außergewöhnlichsten Sammlungen antiker Überreste Frankreichs: Amphitheater, antikes Theater, Kryptoportikus und die Nekropole Alyscamps, gemeinsam 1981 in die UNESCO-Weltkulturerbeliste aufgenommen. Im 19. Jahrhundert malte Vincent van Gogh hier in fünfzehn Monaten über 300 Werke und verewigte die Place du Forum, die Langlois-Brücke und die Sonnenblumenfelder, bevor er in das Hôtel-Dieu der Stadt eingeliefert wurde. Für reisende Haustiere schreibt Frankreich den EU-Heimtierausweis, den ISO-Mikrochip und eine gültige Tollwutimpfung vor. Das Fremdenverkehrsamt von Arles veröffentlicht eine der wenigen speziellen Seiten zum Reisen mit Hund in Frankreich: In der ganzen Stadt gilt Leinenpflicht, Hunde sind aus kostenpflichtigen Monumenten und Museen verbannt (außer Blinden- und Assistenzhunde), und rund dreißig Tütenspender wurden im historischen Zentrum installiert. Die wilden Strände der Camargue, 30 bis 45 Minuten südlich, runden das Bild ab.`,
    petTips: [`Das Fremdenverkehrsamt von Arles veröffentlicht eine der wenigen speziellen Seiten zum Reisen mit Hund in Frankreich; prüfen Sie sie vor der Anreise auf aktuelle Regeln und Tierarztkontakte.`, `Alle kostenpflichtigen Monumente und Museen (Arènes, Théâtre Antique, Cryptoportiques, Musée Arles Antique) verbieten Hunde außer Blindenführhunden; konzentrieren Sie den Besuch auf die im Freien zugänglichen Van-Gogh-Sichtachsen und die Alyscamps.`, `Die städtischen Envia-Busse akzeptieren nur kleine Haustiere in geschlossenem Korb und Blindenführhunde; für die Camargue braucht man mit einem mittelgroßen oder großen Hund das Straßennetz oder ein Taxi/Auto.`, `Im Juli und August spazieren Sie vor 9 oder nach 19 Uhr: Arles überschreitet regelmäßig 32 °C und der Mistral beschleunigt die Austrocknung, besonders auf den schattenlosen Deichen der Camargue.`, `Regionaler 24/7-Tierarztdienst: 04 27 04 02 72 (Arles + Nîmes); die landesweite Nummer 3115 funktioniert auch in ganz der Provence.`],
    practicalInfo: [`Anreise: Der SNCF-Bahnhof Arles liegt 10 Gehminuten vom Zentrum, TER alle 30 Minuten nach Avignon (20 Min.), Nîmes (30 Min.) und Marseille (1 Std.); saisonaler TGV nach Paris in 4 Std. Der Flughafen Marseille Provence (MRS) ist 50 Minuten mit dem Auto entfernt.`, `Strände: kein Stadtstrand; Plage de Beauduc und Plage de Piémanson in der Camargue (30-45 Min. südlich) lassen angeleinte Hunde zu und geben ihnen am Hauptstrand von Beauduc Freilauf; am bewachten Sommerbereich von Piémanson sind Hunde verboten.`, `Parks: Jardin Hortus, Jardin d'Été und die Allée des Alyscamps heißen angeleinte Hunde willkommen; innerhalb der Stadtmauern gibt es keinen Freilaufpark, freies Laufen am Digue à la Mer in der Camargue.`, `Tierärzte: Univet Arles les Remparts (04 90 96 64 06), Clinique Trinquetaille (04 90 49 55 83), Clinique des Alyscamps (04 90 96 02 00); regionale 24/7-Bereitschaftslinie 04 27 04 02 72; kostenlose landesweite Hotline 3115.`, `Dokumente: EU-Heimtierausweis, ISO-Mikrochip und gültige Tollwutimpfung sind vorgeschrieben. Reisende von außerhalb der EU (UK, USA) benötigen ein Animal Health Certificate oder eine USDA-APHIS-Bestätigung.`],
    sights: {
      "Arènes d'Arles (Amphithéâtre romain)": `Das Amphitheater aus dem 1. Jahrhundert, in dem noch jedes Jahr die Osterferia stattfindet, ist das visuelle Wahrzeichen von Arles. Das Fremdenverkehrsamt ist eindeutig: Hunde außer Blinden- und Assistenzhunden sind im Inneren NICHT zugelassen. Der freie Außenrundgang mit seinen zwei Arkadenebenen steht jedoch angeleinten Hunden offen und bietet den besten Blick auf die Altstadt.`,
      "Place du Forum (Café Van Gogh)": `Der Platz, den Van Gogh in seinem Werk Caféterrasse am Abend malte, mit derselben ockerfarbenen Markise, die noch heute dort hängt. Platanen, Cafés an drei Seiten und ein gepflasterter offener Platz in der Mitte. Angeleinte Hunde sind hier zu jeder Stunde vollkommen zu Hause; eine dauerhafte Tafel zeigt das Gemälde genau an der Stelle, an der Van Gogh seine Staffelei aufstellte.`,
      "Allée des Alyscamps": `Die frei zugängliche römische Nekropole südlich des Zentrums, gesäumt von Sarkophagen und beschattet von Pappeln. Die berühmte Allee, von Van Gogh und Gauguin während ihres Aufenthalts gemalt, ist rund um die Uhr frei zugänglich und heißt angeleinte Hunde willkommen. Nur die kostenpflichtige innere Zone des Kreuzgangs Saint-Honorat verbietet Hunde.`,
      "Espace Van Gogh": `Der Kreuzganghof des alten Hôtel-Dieu, in dem Van Gogh im Dezember 1888 behandelt wurde, restauriert nach seinem Gemälde Der Garten des Hôtel-Dieu von Arles. Freier Eintritt, versenkter Garten mit geometrischen Beeten und Arkadengang. Angeleinte Hunde sind im Hof und in der Arkade willkommen; die Bibliothek im Obergeschoss nicht.`,
      "Jardin Hortus": `Ein von der Antike inspirierter Garten in Form einer antiken Rennbahn, neben dem Musée Départemental Arles Antique, mit zugänglichen Rasenflächen, Picknickhängen und Wegen entlang der Rhône. Angeleinte Hunde sind auf Rasenflächen und Wegen willkommen; der eingezäunte Kinderspielplatz im Garten lässt keine Hunde zu.`,
      "Plage de Beauduc (Camargue)": `Der 25 km lange wilde Strand an der Südspitze der Camargue, 40 Minuten mit dem Auto südlich von Arles. Das Fremdenverkehrsamt bestätigt: angeleinte Hunde am Parkplatz, Hinterstrand und Deich; Freilauf am eigentlichen Hauptstrand. Keine Einrichtungen, keine Geschäfte: bringen Sie Wasser, Sonnenschutz und Kotbeutel mit.`,
    },
  },
  antalya: {
    history: `Vom Taurusgebirge im Rücken und dem Mittelmeer zugewandt, ist Antalya die Hauptstadt der türkischen Riviera und das große Tor des Landes zum Strandtourismus. Ihr historisches Herz, Kaleiçi, entfaltet ein Labyrinth kopfsteingepflasterter Gassen, umschlossen von Wällen, gesäumt von hölzernen osmanischen Häusern, Hamams und dem eleganten Hadrianstor, einem 130 n. Chr. errichteten römischen Triumphbogen. Darunter empfängt der hufeisenförmige alte Hafen, einst ein römischer Ankerplatz, heute Ausflugsboote. Rund um die Stadt stürzen die Düden-Wasserfälle von der Klippe direkt ins Meer, während sich die langen Strände von Konyaaltı und Lara beiderseits des Zentrums erstrecken. Für Reisende mit Hund ist Antalya dank einer tierfreundlichen Straßenkultur und des bekannten städtischen Streunerprogramms attraktiv, verlangt aber Planung rund um die extreme Sommerhitze.`,
    petTips: [`Extreme Sommerhitze: Von Juni bis September übersteigen die Temperaturen oft 35 °C und der Boden glüht. Gehen Sie bei Sonnenaufgang und nach Sonnenuntergang spazieren, testen Sie Kies und Asphalt mit der Hand und führen Sie stets Wasser mit.`, `Stadtstrände tabu: Hunde sind an den bewirtschafteten Stränden Konyaaltı und Lara in der Hochsaison nicht erlaubt; bevorzugen Sie stattdessen die Parks der Düden-Wasserfälle und ruhigere Buchten.`, `Tierfreundliche Straßenkultur: Antalya hat viele Straßenkatzen und -hunde, die im Rahmen eines städtischen Programms versorgt und gepflegt werden; sie tragen oft eine Ohrmarke (geimpft). Halten Sie Ihren Hund angeleint, um Konflikte zu vermeiden.`, `Klippenrand an den unteren Düden-Wasserfällen: Die Aussichtspunkte bei Lara sind nicht immer eingezäunt, halten Sie Ihren Hund also oberhalb des Abhangs an kurzer Leine.`, `Rückkehr in die EU aus der Türkei: Planen Sie den Tollwut-Antikörpertitertest (Blutprobe) für Tiere ein, die aus einem Nicht-EU-Land zurückkehren, durchgeführt innerhalb der vorgeschriebenen Frist vor der Abreise.`],
    practicalInfo: [`Der Flughafen Antalya (AYT) liegt etwa 13 km östlich des Zentrums, einer der geschäftigsten der Türkei, mit Verbindungen in ganz Europa; die Antray-Straßenbahn und Shuttlebusse fahren in die Stadt.`, `Einheitliche Notrufnummer: 112 in der Türkei, gültig für jeden menschlichen Notfall; suchen Sie bei Ankunft eine Tierklinik (veteriner) in Antalya für Ihren Hund.`, `Formalitäten für die Rückkehr in die EU: Da die Türkei außerhalb der EU liegt, planen Sie einen Mikrochip, eine aktuelle Tollwutimpfung und vor allem den Tollwut-Antikörpertitertest ein, durchgeführt innerhalb der vorgeschriebenen Frist vor der Abreise.`, `Die nostalgische Straßenbahn und das Antray-Netz dulden im Allgemeinen kleine Hunde in einer Transportbox; für große Hunde bleibt ein Taxi die einfachste Option, klären Sie dies mit dem Fahrer.`, `Die Hauptsaison läuft von Mai bis Oktober mit intensiver Hochsommerhitze: Buchen Sie haustierfreundliche Unterkünfte frühzeitig und bevorzugen Sie die Nebensaisonen (April-Mai, Oktober) für Reisen mit Hund.`],
    sights: {
      "Kaleiçi": `Historische, von Wällen umschlossene Altstadt, ein Labyrinth kopfsteingepflasterter Gassen, osmanischer Häuser und schattiger Innenhöfe, die zum Hafen hinabführen. Ein charmanter, kostenloser Spaziergang an der Leine, bei dem die lokale Kultur der Straßenkatzen und -hunde sehr lebendig ist.`,
      "Hadriyanüs Kapısı": `Das Hadrianstor, ein dreibögiges römisches Triumphtor, errichtet 130 n. Chr. für den Besuch des Kaisers, das einzige erhaltene antike Tor der Stadtmauer. Ein frei zugängliches Monument im Freien, angeleinte Hunde sind auf dem gepflasterten Platz willkommen.`,
      "Düden Şelalesi (chutes hautes)": `Die oberen Düden-Wasserfälle in einem bewaldeten Park nördlich der Stadt, mit einem Weg hinter dem Wasservorhang. Angeleinte Hunde sind auf den schattigen Parkwegen erlaubt, eine erfrischende Pause, die in den heißen Stunden willkommen ist.`,
      "Aşağı Düden Şelalesi": `Die unteren Düden-Wasserfälle, die von einer 40 m hohen Klippe direkt ins Meer bei Lara stürzen, am besten von den Aussichtspunkten des Parks aus zu bewundern. Angeleinte Hunde an den Aussichtspunkten, aber halten Sie sie deutlich vom ungesicherten Klippenrand fern.`,
      "Konyaaltı Plajı": `Ein langer Kiesstrand am Fuß des Taurusgebirges, der Hauptstadtstrand westlich des Zentrums. An diesem bewirtschafteten Strand sind Hunde in der Hochsaison in der Regel nicht erlaubt; suchen Sie stattdessen außerhalb der Saison nach ruhigeren Buchten.`,
      "Yat Limanı": `Der hufeisenförmige alte Hafen unterhalb von Kaleiçi, einst ein römischer Ankerplatz, heute eine Marina mit Terrassen und Ausflugsbooten. Ein angenehmer Spaziergang an der Leine entlang der Kais, und die meisten Terrassencafés dulden Hunde draußen.`,
    },
  },
  antwerp: {
    history: `Antwerpen, Flanderns Diamantenhauptstadt und Belgiens zweitgrößte Stadt, ist seit dem 16. Jahrhundert eine Handelsmacht, als Rubens hier malte und der Hafen mit Venedig konkurrierte. Heute teilen sich die 530.000 Einwohner die Stadt mit einer ungewöhnlich hohen Hundedichte, Flandern hat eine der höchsten Hundebesitzquoten Europas, und Antwerpen zählt mehrere hundert registrierte eingezäunte Hundeauslaufzonen (hondenlosloopzones). Die Stadt nimmt das Wohl von Haustieren ernst: Alle Hunde müssen gechippt und in DogID registriert sein, außerhalb ausgewiesener Zonen gelten strenge Leinenregeln. Dank der Antwerp Six-Designer eine ausgesprochen modebewusste Stadt, ist sie zugleich überraschend entspannt, was vierbeinige Gäste in Cafés und Boutiquen angeht. Die Uferpromenade an der Schelde, der mittelalterliche Grote Markt und der weitläufige Skulpturenpark Middelheim dienen alle zugleich als erstklassiges Terrain für Hundespaziergänge.`,
    petTips: [`De-Lijn-Straßenbahnen und -Busse akzeptieren Hunde zum ermäßigten Fahrpreis von 1,80 € pro Fahrt (kleine Hunde in Transportbox fahren kostenlos); ein Maulkorb ist gesetzlich nicht vorgeschrieben, eine Leine jedoch Pflicht.`, `Laden Sie die Karte „Stad Antwerpen" der hondenlosloopzones herunter, es gibt über 40 eingezäunte Freilaufzonen in der Stadt, darunter große im Rivierenhof und im Nachtegalenpark.`, `Hundekot wird mit Bußgeldern bis 350 € streng geahndet, und Antwerpen betreibt in einigen Bezirken Pilotprojekte zur DNA-Rückverfolgung, sammeln Sie also immer auf.`, `Viele Antwerpener Hotels berechnen eine „Hundegebühr" von 10-25 € pro Nacht; Boutiquehotels im Viertel Het Zuid sind oft am entgegenkommendsten, fragen Sie bei der Buchung nach Größenbeschränkungen.`, `Wenn Sie mit Ihrem Hund in die Niederlande weiterreisen, hat Antwerpen-Centraal direkte Intercity-Verbindungen nach Rotterdam und Amsterdam, wo Hunde für eine NS-Dagkaart-Hond von 3,40 € mitfahren.`],
    practicalInfo: [`Hauptflughafen: Brussels Airport (BRU) liegt 45 km entfernt; der Flughafen Antwerpen (ANR) bedient nur Kurzstrecken. Thalys und Eurostar erreichen Antwerpen-Centraal, einen der schönsten Bahnhöfe Europas.`, `Alle in der EU registrierten Hunde benötigen für die Einreise nach Belgien einen EU-Heimtierausweis, einen Mikrochip und eine gültige Tollwutimpfung (mindestens 21 Tage alt).`, `Beste Reisezeit: Mai-Juni und September bei mildem Wetter von 18-22 °C und blühenden Parks; die Winter sind feucht, aber selten unter dem Gefrierpunkt.`, `24/7-Tiernotdienst: Dierenkliniek Visserij (+32 3 449 55 51) und AniCura Kontich südlich der Stadt für spezialisierte Versorgung.`, `Leitungswasser ist ausgezeichnet und in den meisten Cafés kostenlos, fragen Sie einfach nach „water voor de hond" und Sie erhalten in der Regel einen Napf.`],
    sights: {
      "Grote Markt & Cathedral of Our Lady": `Der dreieckige mittelalterliche Platz wird von Gildehäusern und der 123 Meter hohen gotischen Kathedrale mit vier Rubens-Altarbildern beherrscht. Hunde können den Platz und die umliegenden Kopfsteinpflasterstraßen genießen, dürfen aber nicht in die Kathedrale selbst.`,
      "Park Spoor Noord": `Ein wiederbelebtes, 24 Hektar großes ehemaliges Bahngelände, umgewandelt in einen städtischen Park im angesagten Viertel 2060, mit einer großen eingezäunten Freilaufzone (hondenweide). Bei Einheimischen beliebt für Wochenendläufe und Planschbecken-Tage im Sommer.`,
      "Het Steen & Scheldt Riverside": `Das Schloss aus dem 13. Jahrhundert an der Schelde markiert den Beginn einer langen Uferpromenade, beliebt bei Joggern und Hundespaziergängern. Die neue Terrasse am Steenplein bietet weite Ausblicke bis zum Linkeroever.`,
      "Middelheim Open-Air Sculpture Museum": `Ein 30 Hektar großer Park mit 400 modernen und zeitgenössischen Skulpturen, darunter Werke von Rodin und Henry Moore, in dem angeleinte Hunde frei umherlaufen dürfen. Der Eintritt ist ganzjährig kostenlos.`,
      "MAS Museum rooftop": `In die Museumsgalerien dürfen keine Hunde, doch der kostenlose Aufstieg über die Freiluft-Rolltreppe auf 60 Meter Höhe ist hundefreundlich und bietet das beste Panorama über Hafen und Altstadt.`,
      "Zurenborg & Cogels-Osylei": `Dieses Viertel aus der Belle Époque ist ein lebendiges Museum des Jugendstils und eklektischer Architektur, am besten in Ruhe zu Fuß erkundet. Das Dakota Café und mehrere Terrassen am Dageraadplaats heißen Hunde willkommen.`,
    },
  },
  arcachon: {
    history: `Arcachon entstand aus Wasser und Sand. Bis Mitte des 19. Jahrhunderts war es nur ein Weiler von Fischern und Austernzüchtern am Südufer der Bucht. Alles änderte sich 1857, als die Bankiers und Eisenbahnbauer Brüder Pereire die Stadt gründeten und die Ville d'Hiver ins Leben riefen, ein Hangviertel mit extravaganten Villen, konzipiert als Winterkurort zur Behandlung schwacher Lungen in der balsamischen Kiefernluft. Es folgte die Ville d'Été am Meer mit ihrem Kasino, ihrem Pier und ihrer Promenade. Heute vereint Arcachon Belle-Époque-Architektur, die Austernkultur des Bassin, ruhige Buchtstrände und die kolossale Dune du Pilat im Süden. In Hundefragen ist die Stadt außerhalb der Saison liberal: Die Buchtstrände heißen Haustiere von Oktober bis Mai an der Leine willkommen, die Dune du Pilat ganzjährig, und die UBA-Fähre bringt sie hinüber nach Cap Ferret.`,
    petTips: [`Sommerliches Strandverbot: Hunde sind an den Stadtstränden von Arcachon im Sommer (etwa Juni-September) per städtischem Erlass verboten, mit Bußgeldern; von Oktober bis Mai sind sie am Pereire und an den Abatilles an der Leine willkommen.`, `Die Dune du Pilat heißt angeleinte Hunde ganzjährig willkommen, doch der Sand bietet keinen Schatten und verbrennt im Sommer Pfoten; gehen Sie früh oder spät spazieren und führen Sie ausreichend Wasser mit.`, `Die UBA-Fähre bringt angeleinte Hunde ganzjährig nach Cap Ferret, der beste Hundetagesausflug am Bassin (Leuchtturm, Ozeanstrände, Austernhütten).`, `Das Bassin ist eine Gezeitenbucht: Prüfen Sie die Gezeitentabelle vor Spaziergängen auf den Sandbänken und halten Sie Ihren Hund von den Austernbänken fern, die Schalen schneiden Pfoten.`, `Hunde der Kategorien 1 und 2 (in Frankreich gelistete gefährliche Rassen) müssen im öffentlichen Raum einen Maulkorb tragen und eine offizielle Genehmigung des Rathauses mitführen.`],
    practicalInfo: [`Nächster Flughafen: Bordeaux-Mérignac (BOD), etwa 1 Stunde mit dem Auto; der SNCF-Bahnhof Arcachon erreicht Bordeaux Saint-Jean in 50 Minuten (kleine Hunde in Transportboxen kostenlos, große Hunde mit Maulkorb im TER zum halben Preis, ca. 7 €).`, `Tiernotfälle: Die Clinique Vétérinaire Arcavet (131 Boulevard Deganne) leitet Sie außerhalb der Öffnungszeiten an den diensthabenden Tierarzt weiter; 3115 (kostenlos, 24/7) erreicht den nächsten diensthabenden Tierarzt am Bassin.`, `Mildes, sonniges Ozeanklima mit Kiefernluft: warme Sommer (24-25 °C), aber selten glühend heiß, milde Winter (10 °C); Regen ist ganzjährig möglich, packen Sie ein Hundehandtuch ein.`, `Das Bassin ist eine Gezeitenbucht: Das Wasser zieht sich bei Ebbe weit zurück, prüfen Sie die Gezeitenzeiten vor jedem Ausflug auf die Sandbänke oder Buchtstrände.`, `Das französische Recht schreibt für alle grenzüberschreitenden Haustiere einen EU-Heimtierausweis, einen ISO-Mikrochip und eine gültige Tollwutimpfung vor.`],
    sights: {
      "Dune du Pilat": `Europas höchste Sanddüne mit über 100 Metern, zwischen dem Kiefernwald der Landes und dem Atlantik. Angeleinte Hunde sind ganzjährig willkommen; der Kamm bietet ein Panorama über den Banc d'Arguin, Cap Ferret und den Ozean. Bringen Sie Wasser mit, der offene Sand bietet keinen Schatten und wird im Sommer sehr heiß.`,
      "Ville d'Hiver & Parc Mauresque": `Das Belle-Époque-Viertel der Brüder Pereire, ein Hang mit kunstvollen Villen aus dem 19. Jahrhundert zwischen Kiefern, konzentriert um den Parc Mauresque und seinen Aussichtspunkt über die Bucht. Angeleinte Hunde sind im Park und in den Straßen des Viertels willkommen; ein Aufzug verbindet die Anhöhe mit der Uferpromenade.`,
      "Cap Ferret (bac UBA)": `Die Halbinsel gegenüber, erreichbar mit der UBA-Fähre von der Jetée Thiers aus (angeleinte Hunde ganzjährig erlaubt). Dort gibt es den Leuchtturm, die wilden Ozeanstrände, die ruhigen Buchtstrände und die Austernhütten. Es ist der klassische Hundetagesausflug von Arcachon.`,
      "Plage Pereire": `Der ruhige Buchtstrand, umgeben vom kiefernbeschatteten Parc Pereire, einer der schönsten der Stadt. Angeleinte Hunde sind von Oktober bis Mai erlaubt; ein sommerliches Verbot (etwa Juni-September) gilt per städtischem Erlass. Prüfen Sie den aktuellen Erlass.`,
      "Île aux Oiseaux & cabanes tchanquées": `Die flache Insel mitten im Bassin, gekrönt von den zwei Pfahlbauten cabanes tchanquées, dem Wahrzeichen von Arcachon. Bootstouren und traditionelle Pinassen umrunden sie und das Naturschutzgebiet Banc d'Arguin; viele Anbieter lassen angeleinte Hunde an Bord zu.`,
      "Port de L'Aiguillon": `Der Austernhafen, in dem Produzenten ihre Hütten in Verkostungstische verwandeln: Austern des Bassin, Garnelen und Pignots über dem Wasser serviert. Hunde sind an den Tischen im Freien zu Hause. Kommen Sie bei Ebbe für die ruhigste Atmosphäre.`,
    },
  },
  athens: {
    history: `Athen ist seit über 5.000 Jahren durchgängig bewohnt und schenkte der Welt seit seinem goldenen Zeitalter im 5. Jahrhundert v. Chr. unter Perikles die Demokratie, die Philosophie und das westliche Drama. Die Akropolis krönt noch heute den Parthenon über einer ausufernden modernen Vier-Millionen-Metropole, geprägt von osmanischer Herrschaft, den Flüchtlingswellen aus Kleinasien nach 1922 und einem städtebaulichen Umbau nach den Olympischen Spielen 2004. Athen hat eine der größten frei lebenden Hundepopulationen Europas, der berühmte athenische Streuner, oft sterilisiert, geimpft und von der Stadtverwaltung mit einer Ohrmarke versehen, steht Wache an Metrostationen und archäologischen Stätten. Griechisches Recht hat seit 2021 die Haustierregulierung verschärft und schützt gleichzeitig Streuner.`,
    petTips: [`Athener Sommerhitzewellen übersteigen regelmäßig 40 °C, marmorgepflasterte Straßen strahlen weit über 50 °C aus, beschränken Sie Spaziergänge im Juli und August zwingend auf die Zeit vor 7:30 Uhr und nach 21:30 Uhr.`, `Griechisches Recht (4830/2021) schreibt vor, dass alle Hunde gechippt, in der Öffentlichkeit angeleint und ihr Kot entfernt sein müssen; Besucher müssen EU-Heimtierausweis und Tollwutimpfnachweis mitführen.`, `Die berühmten athenischen Streuner sind meist geimpft und ruhig, nähern Sie sich ihnen nicht mit Ihrem eigenen angeleinten Hund, da territoriale Begegnungen stressig sein können.`, `Die Athener Metro erlaubt jederzeit einen kleinen Hund pro Fahrgast in einer Transportbox; größere angeleinte Hunde mit Maulkorb sind außerhalb der Stoßzeiten erlaubt (vor 7:00 Uhr, 9:30-14:00 Uhr, 17:30-20:30 Uhr) an Wochentagen, den ganzen Tag an Wochenenden.`, `Wasser ist entscheidend: Viele haustierfreundliche Cafés füllen auf Nachfrage die Wasserflasche Ihres Hundes auf („neraki gia to skylaki"), und der Nationalgarten verfügt an mehreren Toren über funktionierende Brunnen.`],
    practicalInfo: [`Flughafen: Athen Eleftherios Venizelos (ATH) verfügt über einen eigenen Auslaufbereich für Haustiere und erlaubt angeleinte Hunde im Terminal; die Metrolinie 3 ins Zentrum akzeptiert Hunde nach den üblichen Regeln.`, `Tierärzte: das 24-Stunden-Tierkrankenhaus von Athen (Glyfada) und Vet Alliance (zentral) sind gut ausgestattet; die Tiermedizinische Fakultät in Votanikos für komplexe Fälle.`, `Strände: An den meisten Stränden der attischen Küste sind Hunde im Sommer verboten; Palaio Faliro hat einen eigenen Hundestrand, und außerhalb der Saison sind Vouliagmeni und Varkiza oft tolerant.`, `Taxis (Beat/FreeNow): Wählen Sie bei der Buchung die Option „mit Haustier"; Fahrer können ablehnen, aber die meisten akzeptieren angeleinte Hunde gegen ein kleines Trinkgeld.`, `Tierbedarf: Pet City ist die wichtigste Ladenkette mit Filialen im gesamten Großraum.`],
    sights: {
      "Acropolis": `Auf dem archäologischen Gelände sind nur Assistenzhunde zugelassen, doch der umliegende Spazierweg (die Fußgängerstraße Dionysiou Areopagitou) ist einer der großartigsten Hundespaziergänge Athens, mit direktem Blick hinauf zum Parthenon.`,
      "National Garden": `Der 15,5 Hektar große ehemalige Königsgarten hinter dem Parlament erlaubt Hunde an kurzer Leine auf den Hauptwegen, schließt sie jedoch vom kleinen Zoo, dem Entenweiher und den Spielplatzbereichen aus. Im Sommer am besten vor 9 Uhr wegen der Kühle und der Gesellschaft besucht.`,
      "Lycabettus Hill": `Mit 277 m der höchste Punkt Athens, erreichbar zu Fuß über einen serpentinenreichen, kiefernbeschatteten Pfad (angeleinte Hunde willkommen) oder mit der Standseilbahn (Haustiere nur in Transportboxen erlaubt). Die Gipfelkapelle und die Panoramaterrasse bieten 360°-Blicke über die Stadt.`,
      "Plaka & Anafiotika": `Das älteste Viertel, um den Hang der Akropolis geschmiegt, ist ein unschlagbarer Spaziergang an der Leine mit den weiß getünchten, kykladisch anmutenden Gassen von Anafiotika, Bougainvillea und Dutzenden haustierfreundlichen Tavernen. Sehr steil, bringen Sie Wasser mit.`,
      "Stavros Niarchos Park": `Der 21 Hektar große, von Renzo Piano entworfene Park am Meer in Kallithea verfügt über einen eigenen eingezäunten Hundepark, kühlende überdachte Korridore und kostenloses Kulturprogramm. Der beste große Grünraum für aktive Hunde in der Stadt.`,
      "Monastiraki & Ancient Agora perimeter": `Der Flohmarktplatz und die Fußgängerstraße Adrianou entlang der Zäune der antiken Agora bieten auf einem Spaziergang an der Leine gestaffelte Blicke auf die Ruinen. Für das Innere der Anlage sind Tickets nötig und Haustiere nicht zugelassen.`,
    },
  },
  auckland: {
    history: `Auckland, auf Māori Tāmaki Makaurau, liegt auf einer schmalen Landenge zwischen zwei Häfen, dem Waitematā im Norden und dem Manukau im Süden, auf einem Vulkanfeld mit etwa fünfzig Kegeln, viele noch terrassiert mit den Erdwerken der Māori-Pā. Die Region war vor der europäischen Ankunft eine der am dichtesten besiedelten Neuseelands, gerade weil vulkanische Böden und zwei Meerzugänge sie strategisch wertvoll machten. 1840 zur Kolonialhauptstadt gewählt, verlor die Stadt diesen Status 1865 an Wellington, nie aber ihre demografische Führung: Heute leben hier etwa 1,7 Millionen Menschen, ein Drittel des Landes, und sie bleibt die größte polynesische Stadt der Welt. Für einen Hund ist sie eine der praktikabelsten Städte der südlichen Hemisphäre: Busse, Züge und Fähren nehmen ihn alle mit, mehr als zweitausend Parks und Strände stehen ihm offen, und das Meer ist nie mehr als ein paar Minuten entfernt. Der Kompromiss läuft auf ein Wort hinaus: Naturschutz.`,
    petTips: [`Busse und Züge von Auckland Transport: Ein Hund jeder Größe fährt an Wochentagen zwischen 9 und 15 Uhr sowie nach 18:30 Uhr kostenlos, an Wochenenden und Feiertagen den ganzen Tag, mit Maulkorb-Muzzle und Leine oder in einer Transportbox, ein Haustier pro Fahrgast.`, `Hafenfähren: Ein Hund fährt mit einem zahlenden Fahrgast auf den Fullers360-Routen kostenlos mit, mit zugewiesenen Sitzplätzen auf den Außendecks und ohne Maulkorbpflicht, zu jeder Tageszeit.`, `Strände: An den meisten Aucklander Stränden gilt vom 1. Dezember bis 1. März zwischen 10 und 17 Uhr eine Hundebeschränkung; der Saint Leonards Beach an der North Shore bleibt das ganze Jahr über rund um die Uhr freilauffreundlich.`, `Der Waitākere-Ranges-Regionalpark und die schädlingsfreien Golfinseln, einschließlich Rangitoto und Tiritiri Matangi, sind für Haustierhunde gesperrt, planen Sie also keinen Tag um sie herum.`, `Giftige Meeresnacktschnecken: 2009 starben Hunde in Narrow Neck und Cheltenham, nachdem sie Pleurobranchaea maculata gefressen hatten, die Tetrodotoxin trägt, halten Sie einen aasfressenden Hund also entlang der Gezeitenlinie an der Leine.`],
    practicalInfo: [`Der Flughafen Auckland (AKL), etwa 21 km südlich des Stadtzentrums: Ein eingeführtes Tier reist im Frachtraum und durchläuft die Biosicherheitskontrolle, statt an der Gepäckausgabe herauszukommen.`, `Einfuhr: Neuseeland hat keinen Heimtierausweis; Sie benötigen eine Einfuhrgenehmigung, einen ISO-Mikrochip, eine Tollwutimpfung, einen Antikörpertitertest und mindestens zehn Tage Quarantäne in einer von MPI zugelassenen Einrichtung, außer bei Ankunft aus Australien.`, `24-Stunden-Tiernotdienst: Animal Emergency bei VSA Sylvia Park, 1 Te Apunga Place, Mount Wellington, +64 9 849 2121. Notdienst der North Shore: 96B Ellice Road, Glenfield, +64 9 443 5640. Die Nummer 111 ist nur für Menschen.`, `Gemäßigtes ozeanisches Klima: 23 bis 24 °C von Dezember bis Februar, um 15 °C und feucht von Juni bis August, und ein Frühling von September bis November, der die beste Jahreszeit mit Hund ist.`, `Betreuung: Pawshake und PetBacker decken beide den Großraum ab, rechnen Sie mit etwa 40 bis 75 neuseeländischen Dollar pro Nacht für die Betreuung zu Hause, ein Impfnachweis ist erforderlich.`],
    sights: {
      "Meola Reef Reserve (Te Tokaroa)": `Eine wiederhergestellte Deponie auf einer Lavazunge bei Westmere, heute die einzige vollständig eingezäunte Freilaufzone im Zentrum von Auckland, mit einem eigenen Bereich für kleine Hunde und einer Uferstelle für wasserliebende Hunde.`,
      "Maungawhau Mount Eden": `Der höchste natürliche Vulkankegel der Stadt, mit seinem 50 m tiefen Krater und einem 360-Grad-Blick über beide Häfen. Auf dem Maunga selbst gilt Leinenpflicht, doch zwischen den Eingängen Clive Road und Summit Road gibt es eine eingezäunte Freilaufwiese.`,
      "Cornwall Park, Maungakiekie": `Ein arbeitender Bauernhof mitten in der Stadt, 1901 der Nation geschenkt und rund um den Kegel One Tree Hill gelegen. Überall gilt Leinenpflicht, und eingeschränkte Zonen sind vom 17. Juli bis 10. September während der Lamm- und Kalbsaison für Hunde gesperrt.`,
      "Devonport, Maungauika North Head": `Zwölf Minuten mit der Fähre von der Innenstadt, der Hund fährt kostenlos mit, für ein viktorianisches Dorf, den Aufstieg auf den Takarunga und die Tunnel von North Head gegenüber Rangitoto. Der ganze Tag lässt sich zu Fuß und an der Leine ab dem Fährsteg gestalten.`,
      "Waiheke Island": `Die einzige Insel im Hauraki-Golf, die Hunde willkommen heißt, 40 Minuten mit der Fähre entfernt. Acht ihrer belebtesten Strände sind vom 1. Dezember bis 1. März zwischen 10 und 18 Uhr für Hunde gesperrt, während Hooks Lane und Owhanake das ganze Jahr über geöffnet bleiben.`,
      "Waitākere Ranges Regional Park": `Der Regenwald der westlichen Hügel, zu dem Piha und Karekare gehören, ist für Haustierhunde gesperrt: Nur registrierte Assistenzhunde dürfen hinein, um das Kauri-Baumsterben zu verlangsamen und bodenbrütende Vögel zu schützen.`,
    },
  },
  austin: {
    history: `Austin wuchs aus einem kleinen Handelsposten namens Waterloo zur Hauptstadt der Republik Texas im Jahr 1839 heran, teils wegen der Schönheit des Hill Country und der Lage am Colorado River gewählt. 1883 kam die University of Texas hinzu, und bis Mitte des 20. Jahrhunderts hatte Austin eine Regierungsstadt über eine College-Stadt geschichtet, eine Kombination, die die berühmte Live-Musikszene entlang der Sixth Street und später den Technologie-Boom der Stadt säte. Lady Bird Johnsons Verschönerungskampagnen in den 1970er-Jahren gestalteten das nach ihr benannte Ufer um, das den Colorado zum Lady Bird Lake staute und mit dem Wander- und Radweg säumte, der bis heute die Outdoor-Kultur der Stadt verankert. Für einen Hund ist das prägende Merkmal Austins das Leben im Freien: unumzäunte Freilaufparks, Restaurantbesuche nur auf der Terrasse gemäß texanischem Gesundheitsrecht und ein Hill-Country-Klima, das von milden Wintern zu wirklich gefährlicher Sommerhitze schwankt.`,
    petTips: [`Testen Sie jeden Gehweg, Kies oder Bohlenweg 10 Sekunden lang mit der Handfläche, bevor Sie Ihren Hund darauf laufen lassen, von Juni bis September erreichen die Oberflächentemperaturen routinemäßig Werte, die Pfoten binnen Minuten verbrennen.`, `Capital Metro (Busse, MetroRail, MetroRapid) befördert nur Assistenzhunde, gewöhnliche Haustierhunde sind in keinem öffentlichen Verkehrsmittel Austins zugelassen, planen Sie stattdessen mit Mietwagen oder Fahrdienst.`, `Austins Freilaufzonen bei Zilker, Red Bud Isle und Auditorium Shores sind anders als die meisten US-Hundeparks unumzäunt, ein zuverlässiger, stimmgesteuerter Rückruf zählt hier mehr als fast überall sonst.`, `Das texanische Gesundheitsrecht hält Hunde landesweit aus jedem Innenbereich von Restaurants fern, hundefreundlich bedeutet hier immer die Terrasse, prüfen Sie das, bevor Sie eine Innenraum-Ausnahme annehmen.`, `Lassen Sie einen Hund in Austin zwischen April und Oktober niemals in einem geparkten Auto zurück, die Innentemperaturen erreichen selbst im Schatten mit angekippten Fenstern binnen Minuten gefährliche Werte.`],
    practicalInfo: [`Flughafen: Austin-Bergstrom International (AUS) verfügt über Auslaufbereiche für Haustiere drinnen und draußen; Fluggesellschaften legen ihre eigenen Kabinen- und Frachtrichtlinien für Haustiere fest, bestätigen Sie diese direkt vor der Buchung.`, `Tierärzte: Zwei 24/7-Notfallkliniken verankern die Stadt, Austin Veterinary Emergency & Specialty (AVES) im Nordwesten und MedVet Austin nahe der I-35, dazu VEG South Lamar für dringende Fälle ohne Termin.`, `Öffentliche Verkehrsmittel: Capital-Metro-Busse, MetroRail und MetroRapid befördern nur Assistenzhunde, ein Mietwagen oder Fahrdienst ist die realistische Art, sich mit Haustierhund fortzubewegen.`, `Strände: Austin liegt landeinwärts, es gibt keinen Meeresstrand; das beste Süßwasserschwimmen bietet Red Bud Isle am Lake Austin und die Hundeeinlassstelle am Auditorium Shores am Lady Bird Lake.`, `Einreise: Inländisches US-Reisen erfordert keine Haustierpapiere; internationale Ankünfte, die zum ersten Mal einen Hund in die USA bringen, müssen seit August 2024 dem CDC-Dog-Import-Form-Verfahren folgen.`],
    sights: {
      "Zilker Metropolitan Park": `Die Great Lawn in diesem 351 Hektar großen Flaggschiff-Park ist täglich von 5 bis 22 Uhr eine unumzäunte Freilaufzone, wobei Hunde vom Spielplatz, Pool und den Sportfeldern ausgeschlossen bleiben. Kombinieren Sie ihn mit dem Lady-Bird-Lake-Weg am Parkrand.`,
      "Red Bud Isle": `Eine 5 Hektar große Freilaufinsel im Lake Austin direkt unterhalb des Tom Miller Dam, mit einem schattigen Rundweg und mehreren Kieszugängen, an denen Hunde frei schwimmen. Unumzäunt und unbeaufsichtigt, achten Sie im Spätsommer auf Algenwarnungen.`,
      "Congress Avenue Bridge Bats": `Bis zu 1,5 Millionen mexikanische Bulldoggfledermäuse schwärmen von etwa März bis Oktober bei Dämmerung unter dieser Innenstadtbrücke hervor. Beobachten Sie das Schauspiel mit angeleintem Hund vom Wander- und Radweg darunter, eines der kostenlosen, hundefreundlichen abendlichen Rituale der Stadt.`,
      "Auditorium Shores": `Eine ausgewiesene Freilaufzone am Lady Bird Lake mit einer Kies-Einlassstelle zum Schwimmen, inklusive Skyline-Blick auf die Innenstadt. Im Rest des Parks gilt Leinenpflicht, mit Bußgeldern bis zu 500 US-Dollar für lose Hunde außerhalb des markierten Bereichs.`,
      "Mount Bonnell": `Austins höchster öffentlicher Aussichtspunkt, erreichbar über 102 steile Kalksteinstufen, angeleinte Hunde willkommen, mit weitem Blick über das Hill Country und den Lake Austin. Der Stein wird in der Sommersonne schnell heiß, ein früher oder abendlicher Besuch ist für Pfoten deutlich schonender.`,
      "Zilker Botanical Garden": `Ein 11 Hektar großer Garten mit thematischen Bereichen, darunter ein japanischer Garten und eine Kakteensammlung. Die veröffentlichte eigene Richtlinie des Gartens heißt angeleinte Hunde ganzjährig willkommen, mit Ausnahmen nur bei einer Handvoll kostenpflichtiger Abendveranstaltungen.`,
    },
  },
  aveiro: {
    history: `Aveiro, mit dem Beinamen „Venedig Portugals", verdankt seine Existenz der Ria de Aveiro, einer Küstenlagune, die die Stadt seit dem Mittelalter geprägt hat. Sie wurde reich durch Salz, Kabeljaufischerei und die Ernte von Moliço (Seetang), die mit Moliceiro-Booten eingesammelt wurde, verfiel dann, als die Lagune im 16. Jahrhundert verlandete, bevor sie im 19. Jahrhundert mit einem neuen, zum Meer führenden Kanal und einer Blüte des Jugendstils wiederauflebte. Heute machen ihre Kanäle, verzierten Fassaden und bunt bemalten Moliceiro-Boote sie zu einem der malerischsten Ziele Mittelportugals. Für den Reisenden mit Hund ist Aveiro ungewöhnlich entgegenkommend: flach und kompakt, mit drei eingezäunten Hundeparks, einer toleranten Esplanada-Kultur, Moliceiro-Booten, die angeleinte Hunde akzeptieren, und Atlantikstränden sowie den gestreiften Palheiros von Costa Nova, alle in kurzer Entfernung.`,
    petTips: [`Die portugiesische Esplanada-Kultur ist weitgehend hundetolerant; das Einkaufszentrum Forum Aveiro lässt angeleinte Hunde zu, außer im Food-Court.`, `Drei eingezäunte städtische Hundeparks (Força-Vouga, Fonte do Meio, Canal de São Roque) sind der einzige zugelassene Freilaufbereich; überall sonst gilt Leinenpflicht.`, `Strände: Costa Nova und Barra (konzessioniert, Blaue Flagge) verbieten Hunde während der Badesaison; nutzen Sie im Sommer den nicht konzessionierten Praia de Cortegaça, ganzjährig erlaubt.`, `Moliceiro: Kleine angeleinte oder mit Maulkorb versehene Hunde sind bei einer Bootsfahrt zugelassen, müssen aber bei der Buchung angefragt werden.`, `24/7-Tierarzt: Hospital Veterinário de Aveiro (+351 234 386 427), VetRia-Notdienst (969 939 939); Zeckenrisiko auf den Wegen durch Dünen und Pinienwald.`],
    practicalInfo: [`Portugal ist Mitglied der EU und des Schengen-Raums: EU-Heimtierausweis + gültige Tollwutimpfung + ISO-Mikrochip genügen aus jedem EU-Land.`, `Der Bahnhof Aveiro an der Nordlinie: häufige CP-Züge nach Porto (40-70 Min.) und Lissabon; kleine Hunde in Transportbox kostenlos, größere mit Ticket + Maulkorb + kurzer Leine + Dokumenten.`, `Nächster Flughafen: Porto (OPO), etwa 1 Stunde mit dem Auto oder Zug, mit vielen europäischen Flügen.`, `Währung: Euro. Aveiro Bus für Costa Nova/Barra und die Fähre São Jacinto; kleine Haustiere in Transportbox, größere Hunde an der Leine mit Maulkorb.`, `Mit Hund meiden: die konzessionierten Strände (Costa Nova, Barra) während der Badesaison-Spitze im Juli-August; bevorzugen Sie Frühling und Herbst mit mildem Klima und für Hunde geöffneten Stränden.`],
    sights: {
      "Canal Central & moliceiros": `Der zentrale Kanal mit seinen bunten, inzwischen elektrischen Moliceiro-Booten, gesäumt von Jugendstilfassaden. Kostenloser, hundefreundlicher Spaziergang; kleine angeleinte Hunde auf Anfrage bei einer Bootsfahrt zugelassen.`,
      "Bairro da Beira-Mar": `Das alte Fischerviertel entlang des Kanals São Roque, enge Straßen, gekachelte Häuser und Jugendstilgebäude. Vollständig fußgängerfreundlich, hundefreundlich an der Leine.`,
      "Costa Nova (palheiros)": `Die gestreiften Palheiros von Costa Nova, ehemalige Fischerlagerhäuser, zu den meistfotografierten Häusern Portugals zählend. Uferpromenade hundefreundlich an der Leine.`,
      "Parque Infante D. Pedro": `Der zentrale Stadtpark, rund 20 ha auf dem Gelände eines ehemaligen Klosters, baumgesäumte Alleen, Seen und ein Jugendstil-Musikpavillon. Angeleinte Hunde für einen schattigen Spaziergang.`,
      "Parques caninos de Aveiro": `Drei eingezäunte städtische Hundeparks (Força-Vouga im Osten, Fonte do Meio im Norden, Canal de São Roque im Westen) mit Agility-Geräten, die einzige legale Möglichkeit, einen Hund frei laufen zu lassen.`,
      "Praia das Dunas de São Jacinto": `Ein wilder Atlantikstrand am Rand eines geschützten Naturschutzgebiets, mit der Fähre erreichbar. Nur angeleinte Hunde; eingeschränkte Zonen sind tabu, freilaufende Hunde können Schließungen auslösen.`,
    },
  },
  avignon: {
    history: `Avignon, in römischer Zeit als Avenio gegründet, wurde im 14. Jahrhundert zu einem der wichtigsten politischen Zentren Europas, als sich hier sieben Päpste niederließen (1309-1377) und den größten gotischen Palast der Welt in Auftrag gaben (15.000 m², 250 Meter Wälle). Die legendäre Pont Saint-Bénézet, verewigt im Kinderlied „Sur le Pont d'Avignon", überquerte einst die Rhône, bevor eine Flut im Jahr 1668 18 ihrer 22 Bögen fortriss. Heute ist Avignon Hauptstadt der Provence (95.000 Einwohner intra muros) und Austragungsort des größten Theaterfestivals der Welt (das Festival d'Avignon, Anfang Juli) und eine der meistbesuchten Kulturstädte Frankreichs. Für Reisende mit Hund ist es eines der vollständigsten Reiseziele der Provence: in 20 Minuten intra muros zu Fuß erkundbar, standardmäßig hundetolerante Café-/Bistrokultur, die Île de la Barthelasse gegenüber dem Papstpalast (Europas größte Flussinsel) mit 4 km Uferweg, und direkter TGV-Zugang von Paris in 2:40 Std.`,
    petTips: [`Die provenzalische Café-/Bistrokultur heißt Hunde standardmäßig willkommen, etwa 80 % der Lokale in Avignon akzeptieren angeleinte Hunde das ganze Jahr über auf der Terrasse.`, `Orizo-Busse: mittlere/große Hunde zum halben Fahrpreis (1 €) an der Leine; der kostenlose Baladine-Shuttle intra muros alle 8 Minuten, hundefreundlich.`, `SNCF-TGV/TER-Züge: Halber Fahrpreis plus Maulkorb für mittlere/große Hunde; kleine Hunde in Transportbox kostenlos.`, `24/7-Tiernotdienst: Clinique VetSud in Le Pontet (+33 4 90 32 28 28), 5 km nördlich an der N7.`, `Das Festival d'Avignon (Anfang Juli) macht die Innenstadt intra muros unpassierbar, meiden Sie es mit einem ängstlichen Hund oder beschränken Sie Ausflüge auf vor 11 Uhr / nach 21 Uhr.`],
    practicalInfo: [`Frankreich ist Mitglied der EU und des Schengen-Raums: EU-Heimtierausweis + gültige Tollwutimpfung + ISO-Mikrochip genügen aus jedem EU-Land.`, `Direkte TGV-Züge: Paris 2:40 Std., Marseille 35 Min., Lyon 1:10 Std., Nîmes 30 Min., Montpellier 1 Std., Barcelona 4 Std. (TGV inOui).`, `Der Flughafen Avignon-Provence (AVN) liegt 8 km entfernt, alternativ Marseille-Provence (MRS) 1 Stunde mit dem Auto oder der Flughafen Nîmes (FNI) 45 Minuten.`, `Währung: Euro. Tagesbudget mit Hund: 75-100 €/Tag ohne Unterkunft, entspricht dem französischen Median.`, `Hundefreundliche Tagesausflüge: Pont du Gard (30 Min.), Châteauneuf-du-Pape (15 Min.), Les Baux-de-Provence (45 Min.), Saintes-Maries-de-la-Mer in der Camargue (1:15 Std.).`],
    sights: {
      "Palais des Papes": `Europas größter gotischer Palast (UNESCO 1995), Sitz von sieben Päpsten (1309-1377). Platz und Außenwälle hundefreundlich mit angeleinten Hunden; im Inneren nur Assistenzhunde.`,
      "Pont Saint-Bénézet": `Legendäre mittelalterliche Brücke aus dem 12. Jahrhundert, Außenansicht hundefreundlich vom Rocher des Doms oder von der Barthelasse aus, der Brückenspaziergang (kostenpflichtiges Ticket) nur für Assistenzhunde.`,
      "Rocher des Doms": `3 Hektar großer Landschaftsgarten, der den Felsvorsprung über dem Papstpalast krönt, Teich, Panorama über die Rhône, die Brücke und den Mont Ventoux. Angeleinte Hunde.`,
      "Place de l'Horloge": `Der wichtigste Café-Theater-Platz, Rathaus, Oper, über 30 Caféterrassen ringsum. Rund um die Uhr geöffnet, durchgehend hundefreundlich.`,
      "Île de la Barthelasse": `Europas größte Flussinsel (700 ha) gegenüber dem Papstpalast, 4 km Uferweg, kostenlose Fähre April-Oktober.`,
      "Remparts médiévaux": `4,3 km mittelalterliche Stadtmauer aus dem 14. Jahrhundert, die die Innenstadt intra muros umschließt, hundefreundlicher Spaziergang mit angeleinten Hunden, freier Zugang rund um die Uhr.`,
    },
  },
  'bad-gastein': {
    history: `Bad Gastein verdankt seine Existenz seinen radonreichen Thermalquellen, die seit dem Mittelalter bekannt sind und von den Habsburgern, Bismarck und Kaiserin Sisi besucht wurden. Im 19. Jahrhundert wurde der kleine Pongauer Kurort zum „Monte Carlo der Alpen": Monumentale Belle-Époque-Hotels stiegen theatralisch gestaffelt rund um den Wasserfall der Gasteiner Ache empor, der 341 Meter durch das Stadtzentrum stürzt. Auf etwa 1.000 m in den Hohen Tauern gelegen, lebt der Ort heute vom Skifahren, Wandern und seinen Thermalbädern. Für Reisende mit Hund ist er einer der praktischsten Alpen-Kurorte: Gondeln, die Hunde mitnehmen (5 EUR pro Tag), das flache Kötschachtal mit hundefreundlichen Hütten, kaiserzeitliche Waldpromenaden und auf Haustiere spezialisierte Hotels, die während der Behandlungen auf den Hund aufpassen. Die einzigen Einschränkungen sind das steile Gelände und die Maulkorbpflicht in öffentlichen Verkehrsmitteln.`,
    petTips: [`Führen Sie stets einen Maulkorb mit: Er ist zusammen mit der Leine in ÖBB-Zügen und Talbussen vorgeschrieben und in den Gondeln empfohlen.`, `Von Juni bis September werden die Almweiden beweidet: Halten Sie den Hund angeleint und meiden Sie Herden weiträumig, die Hauptursache für Zwischenfälle mit Hunden in den österreichischen Bergen.`, `Der Wasserfallweg ist im Winter geschlossen, und die Treppen der Stadt werden gestreut und gesalzen: Schützen Sie von Dezember bis März die Pfoten.`, `Die Thermalbäder (Felsentherme, Alpentherme, Radonstollen) lassen niemals Hunde zu: Buchen Sie die Hundebetreuung des Hotels zusammen mit Ihren Behandlungen.`, `In der Höhe schlägt das Wetter selbst im August schnell um: Handtuch, Wasser und Wettercheck vor einem Tag am Stubnerkogel; der Bach im Kötschachtal ist eine dauerhafte Wasserstelle.`],
    practicalInfo: [`Talärztin: Tierarztpraxis Mag. Katrin Laubichler, Achenstraße 17, Bad Hofgastein (7 km), +43 664 3840438, Kleintierpraxis Mo/Mi/Fr 11:00-13:00 Uhr nach telefonischer Terminvereinbarung.`, `Notfälle: Rufen Sie zunächst die Praxis an (der Anrufbeantworter verweist auf den rotierenden Bereitschaftsdienst des Landes Salzburg); 112 ist nur für menschliche Notfälle.`, `Verkehr: Maulkorb und Leine sind in ÖBB-Zügen (Pauschale 2 EUR bis 98 km) und SVV-Bussen (Mindesttarif) vorgeschrieben; kleine Hunde in Transportboxen fahren kostenlos; Gastein-Lifte 5 EUR/Tag pro Hund.`, `Örtliche Regeln: Salzburger Landgemeinden schreiben Leinen- oder Maulkorbpflicht im öffentlichen Raum vor; in der Praxis gilt in der Stadt und auf den Promenaden überall Leinenpflicht.`, `Dokumente: Standard-EU-Regeln (Heimtierausweis, Mikrochip, gültige Tollwutimpfung); keine Quarantäne für Ankünfte aus der EU.`],
    sights: {
      "Gasteiner Wasserfall": `Ein 341 m hoher Wasserfall, der in drei Stufen durch das Stadtzentrum fällt, einer der höchsten städtischen Wasserfälle Europas. Kostenlose Plattformen und Weg, angeleinte Hunde willkommen; der Weg ist im Winter geschlossen.`,
      "Stubnerkogel Hängebrücke": `Eine 140 m lange Hängebrücke knapp unterhalb des Gipfels des Stubnerkogel (2.246 m), mit der Gondel und dem Hund erreichbar (5 EUR/Tag). Ein Weg mit festem Bodenbelag umgeht das Gitterdeck, falls der Hund zögert.`,
      "Kaiser-Wilhelm-Promenade": `Eine breite, nahezu ebene Panoramapromenade über der Stadt, angelegt für kaiserliche Kurgäste. Schattig und kühl, ist sie der ideale tägliche Hundespaziergang an der Leine.`,
      "Kötschachtal": `Ein flach verlaufendes Seitental entlang eines Baches bis zum Alpenhaus Prossau (1.278 m). Zwei hundefreundliche Hütten unterwegs und überall Wasser: DIE Hundewanderung des Tales.`,
      "Sportgastein": `Ein Hochtal auf etwa 1.600 m hinter Böckstein, über die Gasteiner Alpenstraße erreichbar. Offene Wiesen und Höhenwege; halten Sie den Hund in der Nähe der sommerweidenden Herden angeleint.`,
      "Gasteiner Museum": `Heimatmuseum im Belle-Époque-Herzen der Stadt, das die Geschichte des Kurorts, die Vergangenheit des Tals im Goldbergbau und die Ära der Grandhotels behandelt. Der Innenbereich ist nur Assistenzhunden vorbehalten.`,
    },
  },
  'bad-ischl': {
    history: `Bad Ischl verdankt sein Glück Salzquellen und einer Hochzeit: die Geburt von Erzherzog Franz Joseph, dem künftigen Kaiser, im Jahr 1830 nach einer Fruchtbarkeitskur seiner Mutter, verwandelte die kleine Salzkammergut-Salinenstadt in eine kaiserliche Sommerresidenz. Franz Joseph verbrachte 82 aufeinanderfolgende Sommer in der senffarbenen Kaiservilla in einem 20 Hektar großen Park und unterzeichnete dort 1914 die Kriegserklärung, die den Ersten Weltkrieg einleitete. Die Trinkhalle von 1829, die Esplanade am Fluss und jahrhundertealte Konditoreien wie Zauner tragen bis heute jenen Belle-Époque-Kurortscharme. Heute ist die Stadt Kulturhauptstadt des Salzkammerguts und Tor zu den benachbarten Seen (Hallstättersee, Wolfgangsee, Traunsee) sowie zu Hallstatt und bleibt eine kompakte, flache Basis, die sich mit Hund leicht zu Fuß erkunden lässt, auch wenn das größte Wahrzeichen, die Kaiservilla, nicht mit Hund besichtigt werden kann.`,
    petTips: [`Führen Sie stets einen Maulkorb mit: Er ist zusammen mit der Leine in ÖBB-Zügen, Postbussen und der Katrin-Seilbahn vorgeschrieben (die Hunde kostenlos befördert).`, `Die Kaiservilla lässt sich nicht mit Hund besichtigen: Kaufen Sie das Ticket nur für den Park, um den Kaiserpark zu genießen, während ein Begleiter die Führung macht.`, `Bad Ischl hat keinen eigenen See: Für ein echtes Schwimmen rechnen Sie mit 30 Minuten Fahrt zum ausgewiesenen Hundebadeplatz am Hallstättersee bei Obertraun.`, `Die Esplanade und der Platz vor der Trinkhalle bieten keinen Schatten: Meiden Sie im Juli und August die volle Mittagszeit und bevorzugen Sie Morgen oder frühen Abend.`, `Hallstatt, 25 Minuten mit dem Auto oder einer Kombination aus Postbus/Zug, eignet sich als einfacher hundefreundlicher Tagesausflug.`],
    practicalInfo: [`24-Stunden-Tierarzt: Tierklinik Bad Ischl Dr. Adelsmayr/Mag. Grabner OG, Kaltenbachstraße 26b, +43 6132 25849, Notfälle jeden Tag einschließlich Sonn- und Feiertagen.`, `Zweite Praxis: Tierambulanz Salzkammergut (Dr. Peter Prinz), Salinenplatz 2b, +43 6132 23724, Routineuntersuchungen nach Terminvereinbarung.`, `Verkehr: Maulkorb und Leine sind in ÖBB-Zügen (Pauschale 2 EUR bis 98 km) und Postbussen vorgeschrieben; die Katrin-Seilbahn ist für Hunde kostenlos.`, `Schwimmen: kein See in der Stadt; ein geprüfter Hundebadeplatz am Hallstättersee bei Obertraun (etwa 30 km) oder eine informelle Zugangsstelle am Traunsee bei Altmünster (etwa 25 km).`, `Dokumente: Standard-EU-Regeln (Heimtierausweis, ISO-Mikrochip, Tollwutimpfung mindestens 21 Tage vor der Reise gültig); 112 ist nur für menschliche Notfälle.`],
    sights: {
      "Kaiservilla": `Die Sommerresidenz von Kaiser Franz Joseph für 82 Jahre, wo 1914 die Kriegserklärung unterzeichnet wurde. Die geführte Innenbesichtigung lässt keine Hunde zu.`,
      "Kaiserpark": `Ein 20 Hektar großer Landschaftspark rund um die Kaiservilla, mit schattigen Kiesalleen und dem Marmorschlössl. Angeleinte Hunde auf den Wegen willkommen, nicht in den Pavillons.`,
      "Katrin Seilbahn": `Eine Seilbahn seit 1959 hinauf zur Bergstation Katrin (1.400 m), mit Alpenwegen und Ausblicken über die Seen des Salzkammerguts. Hunde fahren kostenlos, Maulkorb und Leine sind vorgeschrieben.`,
      "Trinkhalle": `Das Kurgebäude von 1829, heute Tourismusbüro und kultureller Treffpunkt, mit dem offenen Kurpark davor. Angeleinte Hunde in den Außengärten willkommen.`,
      "Siriuskogel": `Ein 130 m hoher bewaldeter Hügel am Stadtrand, gekrönt vom Kaiser-Franz-Josef-Warte-Turm von 1885. Ein schattiger 4,1 km langer Rundweg, Leine empfohlen.`,
      "Esplanade": `Eine flache, baumgesäumte Promenade entlang der Traun, die den Kurpark, die Trinkhalle und die Cafés der Stadt verbindet. Der Standardspaziergang für jeden Tag, an der Leine.`,
    },
  },
  bakewell: {
    history: `Bakewell, die einzige echte Marktstadt innerhalb des Peak-District-Nationalparks, entstand rund um seine Furt am River Wye, seine fünfbogige mittelalterliche Brücke und den wöchentlichen Markt, für den es im 13. Jahrhundert ein Marktrecht erhielt. Landesweit berühmt für den Bakewell Pudding und die Bakewell Tart, ist es heute die Wanderbasis des White Peak, jenes Landes aus Kalksteintälern und alten Eisenbahntrassen. Eine tief verwurzelte britische Hundekultur kommt hinzu: Hunde sind in den meisten Pubs willkommen, auf dem flachen Monsal Trail mit seinem berühmten Viadukt und an der Leine im Garten und im weiten Parkgelände von Chatsworth, einem der größten Herrensitze Englands. Dies ist eine landwirtschaftlich genutzte Landschaft, überall Schafe und Rinder sowie im Frühling bodenbrütende Vögel. Ein praktischer Hinweis: Seit dem Brexit ist für Hunde aus der EU ein GB Animal Health Certificate erforderlich.`,
    petTips: [`Halten Sie Ihren Hund in der Nähe von Schafen, Rindern und dem frei umherziehenden Vieh im Chatsworth Park sowie im Frühling und Frühsommer in der Nähe bodenbrütender Vögel auf dem offenen Moor an der Leine.`, `Halten Sie den Hund auf dem Monsal Trail an der Leine: Der Weg wird von vielen Radfahrern geteilt und führt durch dunkle Tunnel, in denen Ruhe sicherer ist.`, `Chatsworth heißt angeleinte Hunde im Garten und im Park willkommen, doch Haddon Hall lässt überhaupt keine Hunde zu; planen Sie entsprechend, um am Tor nicht abgewiesen zu werden.`, `Hunde fahren kostenlos in National-Rail-Zügen (bis zu zwei pro Fahrgast, an der Leine); die nächsten Bahnhöfe sind Matlock, Grindleford und Hathersage, per Bus oder Taxi erreichbar.`, `Tierarzt: Die Bakewell Veterinary Clinic in der Mill Street bietet einen 24-Stunden-Notdienst (+44 1629 812744); der Mobilfunkempfang in den Tälern ist lückenhaft, speichern Sie die Nummer also vorab.`],
    practicalInfo: [`Einreise nach dem Brexit: Großbritannien akzeptiert den EU-Heimtierausweis nicht mehr; Hunde benötigen ein GB Animal Health Certificate (innerhalb von 10 Tagen ausgestellt), einen Mikrochip, eine Tollwutimpfung und eine Bandwurmbehandlung 24 bis 120 Stunden vor Ankunft.`, `Anreise: kein Flughafen oder Bahnhof in Bakewell; der nächste Flughafen ist Manchester (MAN), etwa eine Stunde mit dem Auto. Züge nach Matlock, Grindleford oder Hathersage, dann Bus oder Taxi.`, `Fortbewegung: eine kompakte, zu Fuß erkundbare Stadt; lokale Peak-District-Busse verkehren nach Buxton, Matlock und Sheffield und nehmen einen gut erzogenen Hund nach Ermessen des Fahrers mit.`, `Wetter: ein kühles, gemäßigtes Binnenklima; milde, wechselhafte Sommer (17-19 °C) und kalte, nasse Winter (6 °C). Packen Sie ganzjährig Regenkleidung und ein Hundehandtuch ein.`, `Nützliche Nummern: allgemeiner Notruf 999 oder 112; Bakewell Veterinary Clinic 24-Stunden-Notdienst +44 1629 812744.`],
    sights: {
      "Monsal Trail": `Ein flacher, verkehrsfreier, 13,7 km langer Weg auf einer ehemaligen Bahnlinie, mit beleuchteten Tunneln und dem Headstone-Viadukt. Hunde an der Leine (Radfahrer, Tunnel).`,
      "Chatsworth Garden and Park": `Ein großes Anwesen 5 km entfernt: Hunde an der Leine im 42 Hektar großen Garten und im weiten Park. Im Haus, auf dem Bauernhofgelände und dem Spielplatz nur Assistenzhunde.`,
      "River Wye Riverside and Recreation Ground": `Ein flacher Uferweg entlang der Wye, vorbei an der mittelalterlichen Brücke, wenige Schritte vom Zentrum. Hunde an der Leine: familienfreundlicher Ort nahe dem Wasser und den Enten.`,
      "Monsal Head Viewpoint": `Ein berühmter grasbewachsener Aussichtspunkt über dem Wye-Tal und den Bögen des Viadukts. Hunde an der Leine am Aussichtspunkt und auf den Wegen hinab zum Fluss.`,
      "Ashford-in-the-Water and Sheepwash Bridge": `Ein Kalksteindorf 3 km entfernt, bekannt für die niedrige mittelalterliche Sheepwash Bridge über die Wye. Ein sanfter Spaziergang an der Leine, kombiniert mit einer Rückkehr am Ufer entlang.`,
      "Haddon Hall": `Ein wunderbar erhaltenes mittelalterliches Herrenhaus südlich von Bakewell. Hunde sind auf dem Gelände nicht erlaubt; bewundern Sie es vom öffentlichen Fußweg entlang der Wye aus.`,
    },
  },
  barcelona: {
    history: `Barcelona, um 15 v. Chr. von den Römern als Barcino gegründet, wurde im Mittelalter Hauptstadt der Krone Aragon, einer der großen Seemächte des Mittelmeers. Sein heutiges Gesicht verdankt die Stadt dem Visionär Ildefons Cerdà, dessen Erweiterungsplan von 1860, der Eixample, das charakteristische rechtwinklige Raster mit abgeschrägten Ecken und 20 Meter breiten Straßen schuf. Gaudí formte danach mit der Sagrada Família, dem Parc Güell und der Casa Batlló die Seele der Stadt. Heute ist Barcelona eine der Städte Europas mit dem am schnellsten wachsenden Anteil an Haustierbesitz, und ihre Parks und Strände passen sich allmählich dieser Realität an.`,
    petTips: [`Hunde sind in der Barcelona-Metro erlaubt, wenn sie in einer Tasche oder Transportbox getragen werden. Große Hunde sind in öffentlichen Verkehrsmitteln nicht zugelassen, nutzen Sie Taxis oder Fahrdienste (bei der Buchung angeben).`, `Die Sommerhitze (Juli-August) kann 35 °C übersteigen. Vermeiden Sie Ausflüge zwischen 12 und 17 Uhr und halten Sie Ihren Hund gut hydriert.`, `Der offizielle Hundestrand am Llevant ist der einzige ganzjährig zugängliche Strand, merken Sie sich seine Lage vor der Ankunft.`, `Örtliche Supermärkte von Mercadona und Lidl verkaufen Tiernahrung und Zubehör zu vernünftigen Preisen.`, `Der Parc de la Ciutadella ist kostenlos und öffnet früh, perfekt für einen langen Morgenspaziergang vor der Hitze und den Touristen.`],
    practicalInfo: [`24/7-Tiernotdienst: Clínica Veterinaria Mediterrani, Carrer de Còrsega 251, +34 93 217 00 45`, `Gut ausgestattete Klinik: Atenea Veterinaris, Carrer de Provença 320, Eixample`, `Züge aus Paris oder Madrid: Tiere in Transportboxen im Renfe Avant zugelassen. Große Hunde müssen im Frachtraum oder im Privatfahrzeug reisen.`, `Flughafen Barcelona-El Prat: EU-Haustiere mit gültigem Ausweis ohne Quarantäne zugelassen.`],
    sights: {
      "Parc de la Ciutadella": `Barcelonas zentraler Hauptpark (17 ha) ist der beliebteste Treffpunkt für Hunde und ihre Besitzer. Offene Rasenflächen, ein Bootssee und schattige Wege. Hunde können morgens in ausgewiesenen Bereichen frei laufen.`,
      "Parc Güell": `Gaudís Park heißt Hunde in seinen freien Bereichen willkommen (der Großteil des Parks). Die kostenpflichtige monumentale Zone akzeptiert keine Haustiere. Erkunden Sie die oberen Terrassen für einen atemberaubenden Blick über die Stadt.`,
      "Barceloneta & plage": `Barcelonas Hauptstrände (Barceloneta, Bogatell) sind von Juni bis September für Hunde gesperrt. Außerhalb der Saison werden Hunde am frühen Morgen geduldet. Der Strand Llevant (nördlich von Barceloneta) hat eine offizielle, ganzjährig geöffnete Hundezone.`,
      "Gràcia & Eixample": `Das Viertel Gràcia ist Barcelonas hundefreundlichstes: lebendige Terrassen, intime Plätze wie die Plaça del Sol und Anwohner, die an Hunde gewöhnt sind. Die breiten Gehwege des Eixample eignen sich ideal für Schaufensterbummel.`,
      "Collserola": `Der Naturpark Collserola (8.000 ha) überragt Barcelona und bietet Dutzende Kilometer an Wegen, auf denen Hunde frei laufen können. Erreichbar mit der FGC ab Plaça Catalunya. Ideal für eine morgendliche Wanderung vor der Rückkehr in die Stadt.`,
      "La Sagrada Família": `Das Innere der Basilika ist für Tiere tabu. Der Platz und die Außengärten sind jedoch offen, um die Architektur von außen zu genießen, und viele nahegelegene Cafés heißen Hunde auf ihren Terrassen willkommen.`,
    },
  },
  bari: {
    history: `Bari, Hauptstadt Apuliens, wurde von den Peuketiern gegründet und später von Rom als Barium kolonisiert. Im Mittelalter wurde es zu einem bedeutenden Handelshafen an der Adria und einem Wallfahrtszentrum nach der Überführung der Reliquien des Heiligen Nikolaus von Myra im Jahr 1087. Heute eine Stadt mit 315.000 Einwohnern (1,2 Millionen im Großraum), vereint Bari ein befestigtes mittelalterliches Herz, Bari Vecchia, das sich um die Basilika San Nicola aus dem 11. Jahrhundert schmiegt (ein gemeinsamer orthodoxer und katholischer Wallfahrtsort), mit einem klassizistischen Raster aus dem 19. Jahrhundert, dem Viertel Murat, angelegt unter Joachim Murat während der französischen Besatzung. Die Stadt bietet 4 km Uferpromenade, den Lungomare Nazario Sauro, den längsten Italiens, und drei große Stadtparks mit offiziellen Freilaufzonen, die seit 2020 eröffnet wurden (Parco 2 Giugno, Parco Rossani). Als Hauptstadt der apulischen Bauernküche (Orecchiette, Focaccia barese, Tiella di riso patate e cozze) heißt Bari angeleinte Hunde an fast jeder Terrassenosteria willkommen, betreibt drei 24/7-Tierkliniken (eine seltene Dichte für Süditalien) und bietet direkte Zugverbindungen zu den hundefreundlichen Küstenorten Polignano a Mare (35 Min.), Monopoli (45 Min.) und Alberobello (UNESCO, mit Umstieg). Ein praktischer Punkt: Die städtischen AMTAB-Busse verbieten derzeit mittelgroße und große Hunde, planen Sie also mit Fußwegen (das Zentrum ist 2 km breit) oder einem Taxi.`,
    petTips: [`Italien gehört zur EU-Heimtierausweiszone: Mikrochip + gültige Tollwutimpfung + EU-Ausweis bei der Einreise erforderlich.`, `AMTAB-Busse: Nur kleine Hunde in geschlossenen Transportboxen fahren mit, mittelgroße und große Hunde sind verboten (eine Regelung von 2025, die von der Stadt überprüft wird). Planen Sie mit Taxis oder zu Fuß.`, `Drei offizielle Freilaufzonen für Hunde, seit 2020 eröffnet: Parco 2 Giugno (Eingang Viale Einaudi), Parco Rossani (zwei Zonen), Parco Princess Aldobrandeschi (kleiner).`, `Drei 24/7-Tierkliniken: Santa Fara (+39 080 5043434), Croce Azzurra (+39 080 5505444), Centro Veterinario Einaudi (+39 080 5566655).`, `Die Stadtstrände Pane e Pomodoro und Torre Quetta sind bis 2026-2027 wegen Renovierung geschlossen; für gesicherten hundefreundlichen Sand fahren Sie 35 Minuten südlich zum Bau Beach Polignano.`],
    practicalInfo: [`24-Stunden-Tiernotdienst: Santa Fara Ospedale Veterinario, Via Generale Nicola Bellomo 91 bis, +39 080 5043434.`, `Trenitalia-Züge: Angeleinte und mit Maulkorb versehene Hunde 5 € pauschal oder 50 % des Fahrpreises 2. Klasse, kleine Hunde in Transportboxen kostenlos. Bari Centrale bedient Polignano (35 Min.), Monopoli (45 Min.) und Lecce (1:30 Std.).`, `Der Flughafen Bari Karol Wojtyla (BRI): 8 km vom Zentrum, Kabinenhaustiere max. 10 kg, Frachtraum für größere Hunde bei den meisten Fluggesellschaften. Der FerroTramviaria-Zug zwischen Zentrum und Flughafen fährt in 17 Minuten, 5 €.`, `Während des Festes des Heiligen Nikolaus (7.-9. Mai) buchen Sie Hotels und Tierbetreuer mindestens 2 Wochen im Voraus, die Stadt empfängt zehntausende Pilger.`, `Nützliche Nummern: Carabinieri 112, medizinischer Notfall 118, Tierarzt Santa Fara +39 080 5043434.`],
    sights: {
      "Basilica di San Nicola": `Die romanische Basilika (1087) mit den Reliquien des Heiligen Nikolaus, ein gemeinsamer orthodoxer und katholischer Wallfahrtsort. Innenbereich für Haustiere geschlossen, aber der Vorplatz und die umliegenden Gassen sind an der Leine hundefreundlich.`,
      "Bari Vecchia": `Der von Mauern umgebene mittelalterliche Kern, ein Labyrinth aus Gassen zwischen der Piazza Mercantile und der Kathedrale. Von einem Ende zum anderen begehbar, überall hundetolerante Osterien und Cafés, mit den Orecchiette-Großmüttern, die morgens in der Via Arco Basso arbeiten.`,
      "Castello Svevo": `Die normannisch-staufische Burg aus dem 12. Jahrhundert, die den Westrand von Bari Vecchia beherrscht, mit einem breiten Grabengarten, der an der Leine begehbar ist. Das Museum im Inneren lässt keine Haustiere zu, aber das Gelände ist den ganzen Tag geöffnet.`,
      "Lungomare Nazario Sauro": `Italiens längste Uferpromenade (4 km), zwischen Bari Vecchia und der Fiera del Levante. Die gesamte Strecke ist an der Leine hundefreundlich, mit durchgehendem Blick auf die Adria.`,
      "Parco 2 Giugno": `Baris größter Stadtpark (52.000 m²), jahrhundertealte Olivenbäume, Pinienhain und ein See. Eingezäunte Freilaufzone am Eingang Viale Einaudi, geöffnet von 7 bis 22 Uhr in der Sommersaison.`,
      "Parco Rossani": `Wiederbelebter Stadtpark (10 ha) auf dem Gelände der ehemaligen Kaserne Rossani, zwei eingezäunte Freilaufzonen, 2023 eröffnet, moderne Beleuchtung bis 23 Uhr, abendlicher Treffpunkt für Hundehalter.`,
    },
  },
  basel: {
    history: `Basel, im 1. Jahrhundert als römisches Lager Basilia gegründet und später eine mittelalterliche Bischofsstadt, trat 1501 als elfter Kanton der Schweizerischen Eidgenossenschaft bei und wurde mit seiner Universität (1460), Erasmus und Holbein zu einer Hauptstadt des europäischen Humanismus. Heute die drittgrößte Stadt der Schweiz (180.000 Einwohner; 830.000 im Dreiländer-Großraum Frankreich-Deutschland-Schweiz), vereint Basel schweizerische Ordnung mit einer entspannten Rheinkultur: Von Juni bis September schwimmen Einheimische im Fluss, ihre Habseligkeiten in wasserdichten Wickelfisch-Beuteln treibend, wechseln mit lautlosen, seilgezogenen Fähren das Ufer und speisen auf Terrassen, wo Hunden ungefragt ein Wassernapf gebracht wird. Mit 40 Museen (dem Kunstmuseum, dem ältesten öffentlichen Kunstmuseum der Welt; der Fondation Beyeler; dem Tinguely) sowie der Art Basel jeden Juni und Architektur von Herzog & de Meuron, Mario Botta und Renzo Piano beansprucht Basel den Titel der Kulturhauptstadt der Schweiz. Für Hunde: Die Schweiz gehört zum EU-Heimtierausweissystem, zwei offizielle Hundebadi-Badestellen säumen den Rhein, und der Kanton setzt in städtischen Parks Leinenpflicht streng durch, doch die Auenwälder entlang der Wiese bieten kilometerweise Freilauf.`,
    petTips: [`Die Schweiz gehört zur EU-Heimtierausweiszone: Mikrochip + gültige Tollwutimpfung + EU-Heimtierausweis sind an der Grenze verpflichtend.`, `Zwei offizielle Hundebadi-Stellen am Rhein: Birsköpfli (ruhige Bucht, für alle Hunde) und St. Alban-Rheinweg beim Tinguely-Museum (starke Strömung, nur für sichere Schwimmer).`, `BVB/BLT-Trams: Hunde über 30 cm Schulterhöhe zahlen einen ermäßigten Fahrpreis 2. Klasse; kleinere Hunde in geschlossenen Transportboxen fahren kostenlos. Kaufen Sie das Ticket am grünen TNW-Automaten vor dem Einsteigen.`, `Die hölzernen Rheinfähren (Münsterfähre, Klingentalfähre) nehmen Hunde gegen einen kleinen Pauschalpreis mit, deutlich weniger stressig für ängstliche Tiere als eine Tram.`, `Kantonale Notruflinie für Tierärzte: 0900 515 114 (CHF 1.90/Min.). Die VetTrust Tierklinik in Münchenstein ist rund um die Uhr geöffnet.`],
    practicalInfo: [`24-Stunden-Tiernotdienst: VetTrust Tierklinik Basel, Emil Frey-Strasse 137, Münchenstein, +41 61 416 13 14.`, `Kantonale Bereitschaftsnummer außerhalb der Öffnungszeiten: 0900 515 114 (CHF 1.90/Min.).`, `Züge: SBB-CFF akzeptiert angeleinte und mit Maulkorb versehene Hunde über 30 cm (ermäßigtes Ticket 2. Klasse); Katzen und kleine Hunde in Transportboxen fahren kostenlos.`, `EuroAirport Basel-Mulhouse-Freiburg: EU-Heimtierausweis erforderlich. Nutzen Sie den Schweizer Ausgang für die Buslinie 50 nach Basel (20 Min. bis zum Bahnhof Basel SBB).`, `Während der touristischen Hochsaison (Art Basel Mitte Juni, Herbstmesse Ende Oktober) buchen Sie Hotels und Tierbetreuer mindestens eine Woche im Voraus.`],
    sights: {
      "Basel Münster": `Die Kathedrale aus rotem Sandstein, hoch über dem Rhein gelegen (12.-15. Jh.). Die dahinter liegende Pfalz-Terrasse bietet einen der großartigsten kostenlosen Flussblicke Europas, hundefreundlich an der Leine.`,
      "Marktplatz": `Zentraler Platz, beherrscht vom spektakulären roten Rathaus (16. Jh.), das mit Fresken bedeckt ist. Täglicher Morgenmarkt (außer sonntags), angeleinte Hunde auf dem Kopfsteinpflaster willkommen.`,
      "Mittlere Brücke": `Die mittelalterliche Brücke, die seit 1226 Grossbasel und Kleinbasel verbindet, eine der ältesten Rheinquerungen. Ikonischer Blick auf das Münster, zu jeder Stunde hundefreundlich an der Leine.`,
      "Birsköpfli": `Halbinsel am Zusammenfluss von Birs und Rhein, eine der beiden offiziellen Hundebadi-Stellen des Kantons. Sanfte Strömung, Sandstrand, ohne Leine.`,
      "Landschaftspark Wiese": `3 km langer Uferpark entlang der Wiese, vom nördlichen Kleinbasel bis zur deutschen Grenze. Freilaufabschnitte, Kiesstrände, Flusszugang für schwimmende Hunde.`,
      "Tinguely Fountain": `Jean Tinguelys kinetischer Brunnen (1977) auf dem Theaterplatz, zehn sich drehende und spuckende Metallskulpturen in ständiger Bewegung. Offener Platz, hundefreundlich an der Leine.`,
    },
  },
  bath: {
    history: `Bath, von den Römern 60 n. Chr. als Aquae Sulis rund um Großbritanniens einzige natürliche heiße Thermalquelle gegründet, wurde im 18. Jahrhundert zum mondänsten Kurort Englands, eine vollständig aus honigfarbenem Kalkstein der umliegenden Hügel wiederaufgebaute georgianische Stadt, seit 1987 UNESCO-Weltkulturerbe. Die heute 90.000 Einwohner teilen sich die Stadt mit internationalem Tourismus (6 Millionen Besucher pro Jahr) und einer starken britischen Hundekultur: Pubs akzeptieren Hunde standardmäßig, der Treidelpfad des Kennet-&-Avon-Kanals bietet 140 km autofreie Wege ab der Stadt, und der 9,6 km lange National-Trust-Wanderweg Bath Skyline ist einer der beliebtesten städtischen Hundespaziergänge Großbritanniens. Die Geografie ist kompakt (1,5 km im Durchmesser), was Bath mit Hund hervorragend zu Fuß erkundbar macht, von der georgianischen Royal Crescent über die Roman Baths bis zur geschäftegesäumten Pulteney Bridge (eine von nur vier Brücken dieser Art weltweit). Ein praktischer Hinweis: Großbritannien hat nach dem Brexit das EU-Heimtierausweissystem verlassen, daher ist für EU-Hunde ein innerhalb von 10 Tagen vor der Reise ausgestelltes Animal Health Certificate (AHC) sowie eine vorgeschriebene Bandwurmbehandlung erforderlich.`,
    petTips: [`Leinenpflicht im gesamten Stadtzentrum und in formalen Parks (Public Spaces Protection Order), Bußgelder ab 100 £.`, `GWR- und South-Western-Railway-Züge akzeptieren bis zu 2 Hunde KOSTENLOS pro Fahrgast, ungewöhnlich großzügig nach europäischen Maßstäben.`, `Bath Skyline National Trust: freilauffähig auf offenen Wiesen (Oktober-April), an der Leine in der Nähe von Weidevieh (Mai-September, Lammsaison).`, `24/7-Tiernotdienst: Vets Now Bath in der Rosemary Lodge (01225 832521); dieselbe Nummer leitet an den Tages- oder Nachtdienst weiter.`, `Brexit-Hinweis: Seit 2021 benötigen EU-Hunde ein innerhalb von 10 Tagen ausgestelltes Animal Health Certificate (AHC) plus vorgeschriebene Bandwurmbehandlung.`],
    practicalInfo: [`Roman Baths, Pump Room, Thermae Bath Spa und alle Indoor-Museen verbieten Hunde, buchen Sie einen örtlichen Pawshake- oder Tailster-Betreuer.`, `Animal Health Certificate (AHC) EU→UK: von Ihrem Tierarzt innerhalb von 10 Tagen ausgestellt, kostet 100-200 €. Bandwurmbehandlung 24 Std. bis 5 Tage vor Ankunft.`, `Britische Rasseverbote (Dangerous Dogs Act 1991): Pitbull, Japanischer Tosa, Dogo Argentino und Fila Brasileiro sind verboten, die Einfuhr ist illegal, selbst auf der Durchreise.`, `Britische Pubs akzeptieren Hunde standardmäßig, über 80 % der Pubs außerhalb strenger Küchenbereiche. Bath hat die höchste Dichte im Land.`, `Fünf ganzjährige Hundestrände innerhalb einer Stunde: Berrow Beach (50 Min. Fahrt) und das Uphill-Ende von Weston-super-Mare (45 Min.) sind am einfachsten erreichbar.`],
    sights: {
      "Royal Crescent": `30 georgianische Häuser aus honigfarbenem Stein, angeordnet in einem 150 m weiten geschwungenen Bogen (1774). Der Rasen davor ist ein öffentlicher Park, hundefreundlich an der Leine.`,
      "Bath Skyline": `9,6 km langer National-Trust-Weg durch Wälder und Wiesen auf den Hügeln über Bath. Freilauf außerhalb der Weidezonen. Einer der schönsten Hundespaziergänge Großbritanniens.`,
      "Pulteney Bridge": `Eine von nur vier Brücken der Welt mit Geschäften auf beiden Seiten (neben dem Ponte Vecchio). Geschäfte, Cafés und Blick auf das Wehr des Avon.`,
      "Royal Victoria Park": `Baths größter Stadtpark (23 ha) direkt unterhalb der Royal Crescent. Freilaufzone im Westteil, botanischer Garten an der Leine, Café im Pavilion.`,
      "Kennet & Avon Canal": `140 km Treidelpfad von Bath bis Reading. Flach, verkehrsfrei, durchgehend Wasserzugang, ein Paradies für britische Hundespaziergänge.`,
      "Bath Abbey Churchyard": `Ein mittelalterlicher Platz im Herzen von Bath, gerahmt von der spätgotischen Westfassade der Abtei und der Kolonnade des Pump Room. Angeleinte Hunde auf dem Platz willkommen.`,
    },
  },
  batumi: {
    history: `Georgiens zweitgrößte Stadt und Hauptstadt Adscharas, Batumi erstreckt sich am Schwarzen Meer, direkt an der türkischen Grenze. Einst ein Handelsposten und dann ein mondäner Kurort der russischen Kaiserzeit, hat sich die Stadt zu einer überraschenden Mischung aus restaurierter Belle-Époque-Architektur und kühnen Wolkenkratzern neu erfunden, darunter der berühmte Alphabet-Turm, der die 33 Buchstaben der georgischen Schrift feiert. Ihr schlagendes Herz ist der Batumi Boulevard, eine 7 km lange begrünte Promenade entlang des Kiesstrandes, gesäumt von Brunnen, Cafés und einer Seilbahn, die in die Hügel hinaufführt. Weiter südlich entfaltet der botanische Garten seine blühenden Terrassen über den Wellen. Für Reisende mit Hund ist Batumi einladend: unkomplizierte Einreise nach Georgien, ein langer, an der Leine idealer Uferspaziergang und ruhige städtische Streunerhunde, erkennbar an einer Ohrmarke, die Impfung und Kastration bestätigt.`,
    petTips: [`Feuchtsubtropischer Sommer: Von Juni bis September herrschen drückende Hitze und hohe Luftfeuchtigkeit am Schwarzen Meer. Gehen Sie früh morgens und abends spazieren, legen Sie auf dem Boulevard häufig Schattenpausen ein und führen Sie Wasser mit sich.`, `Streunerhunde mit Ohrmarke: Die Stadt betreibt ein städtisches Impf- und Kastrationsprogramm; diese Hunde sind meist ruhig, halten Sie Ihren jedoch angeleint, um Konfrontationen zu vermeiden.`, `Kiesstrand: Außerhalb der Saison angenehm für Spaziergänge an der Leine, doch die Kiesel heizen sich im Hochsommer auf und die bewirtschafteten Badebereiche schließen Hunde im Sommer aus; peilen Sie die unbewachten Abschnitte bei Sonnenaufgang an.`, `Rückkehr in die EU aus Georgien (ein Nicht-EU-Land): Planen Sie einen Mikrochip, eine gültige Tollwutimpfung und den Tollwut-Antikörpertitertest innerhalb der vorgeschriebenen Frist vor der Abreise ein.`, `Der 7 km lange begrünte Boulevard ist das beste Spaziergebiet der Stadt, schattig und flach; konzentrieren Sie dort Ihre langen Ausflüge mit Hund.`],
    practicalInfo: [`Der internationale Flughafen Batumi (BUS) liegt etwa 5 km südlich des Zentrums, verbunden mit mehreren Städten in Europa und der Region; Taxis und Busse fahren in die Stadt.`, `Einheitliche Notrufnummer: 112 in Georgien, gültig für jeden menschlichen Notfall; suchen Sie bei Ankunft eine Tierklinik in Batumi für Ihren Hund.`, `Die Einreise nach Georgien ist für die meisten Reisenden unkompliziert (visumfreie Touristenaufenthalte für viele Nationalitäten); prüfen Sie vor der Abreise die Bedingungen für Ihren Pass.`, `Rückkehr in die EU: Da Georgien außerhalb der EU liegt, planen Sie im Voraus einen Mikrochip, eine aktuelle Tollwutimpfung und einen Tollwut-Antikörpertitertest ein, durchgeführt innerhalb der vorgeschriebenen Frist vor der Heimreise.`, `Die sommerliche Hauptsaison von Juni bis September ist sehr geschäftig: Buchen Sie haustierfreundliche Unterkünfte frühzeitig; Frühling und früher Herbst sind milder für Reisen mit Hund.`],
    sights: {
      "Batumi Bulvari": `Der Batumi Boulevard, eine 7 km lange begrünte Promenade entlang des Schwarzen Meeres, gesäumt von Brunnen, Skulpturen und Radwegen. Angeleinte Hunde sind auf der gesamten Länge vollkommen zu Hause, ideal am frühen Morgen oder in der Kühle des Abends.`,
      "Batumi Botanical Garden": `Ein weitläufiger terrassierter botanischer Garten am Green Cape, 9 km nördlich, einer der reichhaltigsten der ehemaligen Sowjetunion mit nach Weltregionen geordneten Sammlungen. Angeleinte Hunde sind auf den Wegen erlaubt; bringen Sie Wasser und gutes Schuhwerk für die Hänge mit.`,
      "Piazza": `Ein Platz im italienischen Stil im alten Batumi, mit Mosaiken, einem Campanile und neuvenezianischen Fassaden rund um einen gepflasterten, von Cafés gesäumten Raum. Ein angenehmer Durchgang an der Leine, die meisten Terrassen dulden Hunde draußen.`,
      "Alphabet Tower": `Der Alphabet-Turm, ein 130 m hoher spiralförmiger Wolkenkratzer, dessen Struktur die 33 Buchstaben der georgischen Schrift feiert, mit einer Aussichtsplattform ganz oben. Der Vorplatz lässt sich an der Leine begehen, doch Aufzug und Innenplattform lassen keine Hunde zu.`,
      "Batumi Beach": `Ein langer, kilometerweit den Boulevard säumender Kiesstrand, größtenteils unbewirtschaftet. Angeleinte Hunde werden auf den unbewachten Abschnitten abseits der bewirtschafteten Sommerbadebereiche geduldet, vorzugsweise am frühen Morgen.`,
      "Argo Cable Car": `Die Argo-Seilbahn, die von der Stadt zum Hügel Anuria hinaufführt und ein Panorama über die Bucht und die Berge Adscharas bietet. Hunde sind in den Kabinen nicht erlaubt; lassen Sie Ihren unten zurück und genießen Sie stattdessen den Hügelweg an der Leine.`,
    },
  },
  como: {
    history: `Como, eine italienische Provinzhauptstadt mit rund 84.000 Einwohnern am Südzipfel des Comer Sees, ist seit dem 18. Jahrhundert ein Luxusziel am See, als der europäische Adel Villen entlang seiner Ufer errichtete. Das kompakte mittelalterliche Zentrum der Stadt, umgeben von römischen Mauern und solchen aus dem 12. Jahrhundert, liegt zwischen dem spiegelglatten See und dem bewaldeten Höhenzug von Brunate, der bis auf 715 m aufragt. Como baute seinen Wohlstand auf der Seidenweberei auf (noch heute der wichtigste Wirtschaftszweig) und heute auch auf dem Tourismus: 4 Millionen Besucher pro Jahr, von denen ein wachsender Anteil mit Hund anreist. Die Seekultur ist für ein italienisches Luxusziel ungewöhnlich haustierfreundlich - das Fährnetz Navigazione Laghi nimmt Hunde auf jedem Schiff mit, die Standseilbahn von 1894 nach Brunate hat eine klare Haustierrichtlinie, und eine Reihe herrschaftlicher Villengärten (Olmo, Balbianello, Carlotta) öffnet ihre Anlagen für angeleinte Haustiere, auch wenn deren Innenräume das nicht tun. Die 50 km lange Fahrt nach Süden nach Mailand mit seiner rund um die Uhr geöffneten Tierklinik der Universität macht Como auch zu einem praktischen Reiseziel für Haustierbesitzer.`,
    petTips: [`Das italienische Gesetz schreibt vor, dass in der Öffentlichkeit jederzeit ein Maulkorb mitgeführt werden muss, auch wenn er nicht angelegt ist; halten Sie einen weichen Körbchenmaulkorb für die Standseilbahn und die Fähren bereit.`, `Die Lombardei verhängt Bußgelder von bis zu 300 EUR für nicht entsorgten Hundekot, und Ordnungshüter in Como patrouillieren im Sommer entlang des Lungo Lario und der Piazza Cavour; entsorgen Sie alles in einem der grünen Straßenmülleimer.`, `Die Augustluft in Como erreicht Spitzenwerte von 28-30 °C bei einer Seewassertemperatur von 24 °C; gehen Sie vor 9 Uhr und nach 19 Uhr spazieren, nutzen Sie die schattigen Wege von Villa Olmo und das kühlende Seewasser bei Villa Geno.`, `Die Fähren von Navigazione Laghi nehmen zu jeder Jahreszeit auf jedem Schiff Hunde mit; kleine Hunde in einer Transportbox fahren kostenlos, größere Hunde benötigen ein zusätzliches Ticket zu etwa dem halben Fahrpreis.`, `Como liegt als Schengen-Grenzstadt an der Schweiz - stichprobenartige Kontrollen des EU-Heimtierausweises finden auf der Zugstrecke Como-Lugano S40 und auf der Autobahn A9 Richtung Chiasso statt.`],
    practicalInfo: [`Kein 24-Stunden-Notfall-Tierarzt direkt in Como. Abendkontakt: Clinica Veterinaria San Siro Cernobbio (3 km nördlich), +39 031 511 233. Echte nächtliche Notfälle: Ospedale Veterinario Universitario di Lodi (1 Std. südlich), +39 02 5033 4143.`, `Tagesklinik im Zentrum: Clinica Veterinaria San Rocco, Via San Rocco 12, +39 031 261 188, Mo-Fr.`, `Trenord Como Nord Lago → Milano Cadorna: 1 Std. (näher am See). Trenitalia Como San Giovanni → Milano Centrale: 35-45 Min. (näher an der Autobahn A9).`, `Nächster internationaler Flughafen: Mailand Malpensa (MXP), 50 km / 1 Std. mit dem Malpensa Express plus Transfer; Linate (LIN) 60 km für Inlands- und Kurzstreckenflüge.`],
    sights: {
      "Passeggiata Lino Gelpi": `Comos charakteristische Uferpromenade, die 1,5 km von der Piazza Cavour westwärts bis zur Villa Olmo führt, gepflastert, eben und von Platanen beschattet. Der klassische Morgen- und Sonnenuntergangs-Hundespaziergang; alle 100 m Bänke und Zugänge zum Seewasser entlang der Ufermauer.`,
      "Funicolare Como–Brunate": `Historische Standseilbahn von 1894, die vom Ufer aus in 7 Minuten 540 Höhenmeter nach Brunate erklimmt. Hunde jederzeit zugelassen, angeleint und mit Maulkorb (kleine Hunde in der Tragetasche fahren kostenlos). Ausgangspunkt der besten Hundewanderung der Stadt.`,
      "Faro Voltiano (Volta Lighthouse)": `1927 zum hundertsten Todestag von Alessandro Volta errichtet, bietet dieser 29 Meter hohe Leuchtturm auf dem Höhenzug von Brunate das klassische Seepanorama. Ein 30-minütiger angeleinter Spaziergang von der Standseilbahnstation; Hunde am Fuß willkommen, nicht beim Aufstieg selbst.`,
      "Parco di Villa Olmo": `Die Uferanlage der neoklassizistischen Villa Olmo, seit 1925 öffentlicher Park mit formalen italienischen Gärten, einem englischen Landschaftsteil und einem 600 m langen Uferweg. Angeleinte Hunde ganzjährig im Park willkommen; das Innere der Villa ist für Haustiere tabu.`,
      "Duomo di Como": `Der Dom von Como, 1396 begonnen und im 18. Jahrhundert vollendet, vereint spätgotische und Renaissance-Fassaden an der Piazza Duomo. Hunde dürfen nicht hinein, doch der Domplatz und die umliegenden Kopfsteinpflastergassen sind für angeleinte Hunde geeignet und ein klassischer Fotostopp.`,
      "Bellagio (Ferry Day Trip)": `Das berühmte Dorf am See, 30 km nördlich, erreichbar mit der gemütlichen Langsamfähre (2 Std.) oder dem Tragflügelboot (45 Min.) ab Piazza Cavour. Kopfsteinpflastergassen, terrassierte Cafés, der öffentliche Park auf der Landzunge Punta Spartivento - alles haustierfreundlich für angeleinte Hunde; Fähren nehmen Hunde jederzeit mit.`,
    },
  },
  'conil-de-la-frontera': {
    history: `Conil de la Frontera, ein altes Fischerdorf, das sich zu einem der reizvollsten weißen Dörfer der Costa de la Luz gewandelt hat, staffelt seine weiß getünchten Häuser über kilometerlangem goldenem Atlantiksand. Seit phönizischer Zeit besiedelt, lebte der Ort jahrhundertelang im Rhythmus der Almadraba, dem traditionellen Fang des Roten Thunfischs, den das Haus Guzmán vom Torre de Guzmán aus betrieb, einem Bergfried aus dem 14. Jahrhundert, der noch heute über dem Zentrum aufragt. Das alte Fischerviertel La Chanca hält diese maritime Erinnerung lebendig. Für Reisende mit Hund ist Conil im Frühling und Herbst ein Vergnügen: Die riesigen Strände von Los Bateles und La Fontanilla sind außerhalb der Saison weitgehend begehbar, ein Küstenpfad auf den Klippen führt bis zu den Calas de Roche, und die weißen Gassen bleiben morgens kühl. Der Sommer bringt eigene Regeln mit sich: Die Stadtstrände sind für Hunde gesperrt, die andalusische Hitze beißt, und der berühmte Levante-Wind bläst kräftig.`,
    petTips: [`Strände: Während der sommerlichen Hauptsaison sind Hunde an Conils Badestränden verboten; planen Sie Frühling und Herbst für die großen Strände ein und weichen Sie im Sommer auf die ausgewiesenen Hundestrände der Provinz Cádiz aus.`, `Der Levante-Wind kann tagelang kräftig wehen: windgetriebener Sand reizt Augen und Ohren des Hundes, wechseln Sie bei starkem Wind auf die geschützte Seite des Pfades der Calas de Roche oder in die Gassen der Altstadt.`, `Andalusische Hitze von Juni bis September: gehen Sie in der Morgendämmerung und nach 20 Uhr spazieren, machen Sie den Handrückentest auf Sand und Pflaster, führen Sie immer Wasser mit sich und rechnen Sie mit wenig Schatten entlang der Küste.`, `Vorbeugung gegen Leishmaniose ist an der andalusischen Küste unerlässlich (Sandmücken aktiv von Frühling bis Herbst): Repellent-Halsband oder Spot-on verwenden und Ausflüge in der Dämmerung nahe dem feuchten Boden des Río Salado meiden.`, `In Spanien ist die Leinenpflicht in Ortschaften vorgeschrieben; für sogenannte PPP-Rassen (potenziell gefährliche Hunde) sind Maulkorb und kurze Leine im öffentlichen Raum vorgeschrieben, Lizenz griffbereit.`],
    practicalInfo: [`Europäische Notrufnummer: 112, in ganz Spanien gültig für Polizei, Feuerwehr und Rettungsdienst`, `Tierarztpraxen in Conil selbst für die Routineversorgung; für nächtliche Notfälle liegen die nächsten 24-Stunden-Tierkliniken um Chiclana, Cádiz und Jerez, 30 bis 50 Minuten mit dem Auto entfernt`, `Haustierregale in den Supermärkten Mercadona, Dia und Lidl im Ort; besser sortierte Zoofachgeschäfte in den Gewerbegebieten von Chiclana de la Frontera`, `Nächster Flughafen: Jerez (XRY), etwa 1 Stunde mit dem Auto entfernt, mit Sevilla und Gibraltar als Alternativen; kein Bahnhof in Conil, und Fernbusse von Comes ab Cádiz nehmen kleine Hunde in Transportboxen je nach Bedingungen des Betreibers mit`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich; Spanien ist EU-Mitglied, keine zusätzlichen Formalitäten bei Einreise aus Frankreich oder Portugal`],
    sights: {
      "Playa de los Bateles": `Conils Hauptstadtstrand entfaltet seinen goldenen Sand am Fuß des Ortes, wo der Río Salado auf den Ozean trifft. Wie an Andalusiens überwachten Stränden üblich, sind Hunde während der sommerlichen Badesaison verboten; von Oktober bis Ostern wird er jedoch bei Ebbe zu einem weitläufigen Spaziergebiet.`,
      "Playa de la Fontanilla": `Conils berühmtester Strand, gesäumt von Chiringuitos, die für gegrillten Fisch bekannt sind, erstreckt sich bis zu den niedrigen Klippen im Norden. Im Sommer wie alle Badestrände des Ortes für Hunde gesperrt, wird er außerhalb der Saison wieder zu einem großartigen Spazierweg, und die Provinz Cádiz unterhält ein paar Kilometer entfernt ausgewiesene Hundestrandbereiche.`,
      "Torre de Guzmán": `Dieser Bergfried aus dem 14. Jahrhundert, ein Überbleibsel der Burg der Guzmáns, diente einst als Wachturm gegen die Almadraba und Berberüberfälle. Der Aufstieg im Inneren erfolgt ohne Hunde, doch der kleine Platz darum herum, der Patio de la Villa und die benachbarten weißen Gassen eignen sich hervorragend für einen angeleinten Spaziergang, besonders zur goldenen Stunde.`,
      "Barrio de La Chanca": `Das alte Fischerviertel liegt um die ehemalige Chanca, die Halle, in der Almadraba-Thunfisch gesalzen wurde, heute ein Kulturzentrum, das dieser tausendjährigen Fischerei gewidmet ist. Seine niedrigen Gassen, blumengeschmückten Patios und weißen Mauern lassen sich mit angeleintem Hund frei erkunden, sobald man die Einkaufsstraßen verlässt, in echter Ruhe.`,
      "Calas de Roche": `Nördlich von La Fontanilla führt ein Küstenpfad über ockerfarbene Klippen zu den Buchten von Roche und ihrem kleinen Leuchtturm. Dies ist Conils großer Hundespaziergang: angeleint entlang des Pfades, mit großartigen Atlantikblicken und wilden Buchten darunter; im Sommer früh starten und vom Klippenrand bei starkem Wind fernbleiben.`,
      "Puerto pesquero de Conil": `Unter der Klippe von Roche gelegen, landet der kleine Fischereihafen noch immer täglich den Fang der Küste an und im Frühjahr während der Almadraba-Saison auch Roten Thunfisch. Die Mole und die Kais bieten einen schönen salzigen Spaziergang an der Leine, auf der einen Seite bunte Boote, auf der anderen Buchten.`,
    },
  },
  conwy: {
    history: `Conwy ist eine mittelalterliche Burgstadt mit Stadtmauer an der Mündung des Conwy-Ästuars an der nordwalisischen Küste. Ihre Burg, in den 1280er Jahren von Edward I. mit acht mächtigen Türmen erbaut, und ihr nahezu vollständiger Mauerring mit 21 Türmen bilden eines der am besten erhaltenen mittelalterlichen Ensembles Europas, ein UNESCO-Weltkulturerbe. Der einstige Fischereihafen bewahrt einen lebendigen Kai, an dem das kleinste Haus Großbritanniens steht. Conwy ist auch ein Tor zu Eryri (Snowdonia). Für einen Hund ist es ein außergewöhnlich einladender Ausgangsort: Hunde reisen kostenlos im Zug auf der North Wales Coast Line und der landschaftlich reizvollen Conwy Valley Line ins Gebirge mit, sind in den Pubs und Cafés der Castle Street und am Kai willkommen sowie auf hervorragenden Wanderungen wie dem Conwy Mountain. Die einzigen Ausnahmen sind das Burginnere und die Mauerwege, die nur Assistenzhunde zulassen. Und seit dem Brexit verlangt Großbritannien anstelle des EU-Heimtierausweises ein GB Animal Health Certificate.`,
    petTips: [`Haustiere dürfen nicht ins Innere von Conwy Castle oder auf die schmalen Mauerwege (nur Assistenzhunde); bewundern Sie die Burg stattdessen vom haustierfreundlichen Kai und Ästuar aus.`, `Fast alles andere in Conwy ist haustierfreundlich: die Pubs und Cafés der Castle Street und am Kai, wie Cantîn, das Hundebetten, Leckerlis und Wasser bereitstellt.`, `An den Stränden verhängt der Conwy County Borough Council saisonale Einschränkungen vom 1. Mai bis 30. September (Bußgeld 100 Pfund); Conwy Morfa ist haustierfreundlich, und West Shore hat eine eingeschränkte Zone zwischen den Buhnen.`, `Auf dem Conwy Mountain und in Eryri halten Sie Ihren Hund in der Nähe von weidenden Schafen und Ponys an der Leine und führen Sie Wasser mit.`, `Nächster Tierarzt: Cater Veterinary Practice, Llandudno Junction (+44 1492 581920); Murphy & Co Vets, Llandudno (+44 1492 878581), mit Bereitschaftsdienst außerhalb der Öffnungszeiten.`],
    practicalInfo: [`Einreise nach Großbritannien nach dem Brexit: Großbritannien akzeptiert den EU-Heimtierausweis nicht; Hunde benötigen ein GB Animal Health Certificate (innerhalb von 10 Tagen ausgestellt), einen Mikrochip, eine Tollwutimpfung und eine Bandwurmbehandlung 24 bis 120 Stunden vor der Ankunft.`, `Anreise: Zug auf der North Wales Coast Line; der Hauptumsteigebahnhof Llandudno Junction liegt eine Station entfernt (Hunde kostenlos). Die Conwy Valley Line führt nach Eryri. Flughäfen: Manchester (MAN) und Liverpool (LPL), etwa 1,5 Stunden entfernt.`, `Fortbewegung: Die von Mauern umgebene Stadt ist kompakt und am besten zu Fuß zu erkunden; lassen Sie das Auto auf den Parkplätzen am Kai und am Bahnhof. An Sommerwochenenden sehr belebt.`, `Wetter: mildes ozeanisches Klima, feuchter und kühler als im Süden Großbritanniens; milde Winter (7 °C), warme, aber nicht heiße Sommer (18 °C), in den Bergen oft bewölkt. Frühling und Herbst sind ideal.`, `Nützliche Nummern: allgemeiner Notruf 999 oder 112; Tierarzt Cater Veterinary Practice +44 1492 581920; Murphy & Co Vets +44 1492 878581.`],
    sights: {
      "Conwy Castle": `Edward I.'s UNESCO-Festung (1280er Jahre) mit acht mächtigen Türmen über dem Ästuar. Nur Assistenzhunde dürfen hinein; großartig anzusehen vom haustierfreundlichen Kai und Ästuar aus.`,
      "Conwy Town Walls and Quay": `Ein nahezu vollständiger Ring aus Mauern des 13. Jahrhunderts mit 21 Türmen um einen lebendigen Kai. Keine Hunde auf den schmalen Mauerwegen, aber angeleint willkommen in der ganzen Stadt und am Kai.`,
      "The Smallest House in Great Britain": `Das berühmte leuchtend rote Quay House, 72 Zoll breit, das offiziell kleinste Haus Großbritanniens. Der Kai ist haustierfreundlich, ein unterhaltsamer Fotostopp unterhalb der Mauern.`,
      "Conwy Mountain (Mynydd y Dref)": `Der walfischrückenförmige Hügel über der Stadt mit grasbewachsenen Wegen, einer eisenzeitlichen Hügelfestung und einer empfohlenen 3,5-Meilen-Rundtour. Hunde an der Leine in der Nähe weidender Schafe und Ponys.`,
      "Bodnant Garden (National Trust)": `Ein weltberühmter National-Trust-Garten im Conwy-Tal. Hunde an kurzer, nicht ausziehbarer Leine von Donnerstag bis Sonntag von April bis September, und täglich von Oktober bis März.`,
      "Aber Falls (Rhaeadr Fawr, Eryri)": `Eine familienfreundliche Wanderung zu einem 37 Meter hohen Wasserfall bei Abergwyngregyn, in Eryri westlich von Conwy. Ein einfacher Hin- und Rückweg, auf dem angeleinte Hunde willkommen sind; Schafe an den Hängen.`,
    },
  },
  copenhagen: {
    history: `Kopenhagen, das durchgehend zu den lebenswertesten Städten der Welt zählt, ist auch eine der haustierfreundlichsten Hauptstädte Europas. Dänen pflegen eine tiefe, unsentimentale Beziehung zu ihren Hunden: Kopenhagener fahren mit Hunden im Lastenrad, nehmen sie mit zur Arbeit und bringen sie ganz selbstverständlich in die zahlreichen hundefreundlichen Cafés und Restaurants der Stadt. Das Engagement der Stadt für die Fahrradinfrastruktur, ihr Netz von Hafenbädern, Parks und Stränden in Fahrraddistanz sowie ihr hohes soziales Vertrauen schaffen eine Umgebung, in der Hunde wirklich willkommen sind und nicht nur geduldet werden. Schätzungsweise 70.000 Hunde leben im Großraum Kopenhagen.`,
    petTips: [`Die Kopenhagener Metro lässt Hunde nur in Transportboxen zu. S-Tog (Vorortzüge) und Regionalzüge erlauben Hunde mit Maulkorb zum Kindertarif. Busse lassen Hunde in Transportboxen zu.`, `Lastenräder (Christiania-Räder) sind in Kopenhagen allgegenwärtig, und Dänen transportieren ihre Hunde routinemäßig darin. Einige Fahrradverleihe bieten Lastenräder an, eine typisch Kopenhagener Art, mit einem großen Hund unterwegs zu sein.`, `Dänische Cafés sind überwiegend hundefreundlich, achten Sie auf Schilder mit "hunde velkomne" (Hunde willkommen). Es ist ungewöhnlich, ein Kopenhagener Nachbarschaftscafé zu finden, das Hunde ablehnt.`, `Strände: Bellevue Beach (20 Min. mit der S-Bahn, Klampenborg) verfügt über einen eigenen Hundestrand ohne Leine. Am Amager Beach gibt es hundefreundliche Abschnitte außerhalb von Juni bis August.`, `Die berühmte Fußgängerzone Strøget ist mit Hund zugänglich; die großen Kaufhäuser (Magasin, Illum) lassen keine Hunde zu.`],
    practicalInfo: [`Notfall-Tierarzt: Dyrehospitalet Frederiksberg, Howitzvej (+45 38 86 55 55), rund um die Uhr geöffnete Fach-Tierklinik im Zentrum Kopenhagens.`, `Anreise: Der Flughafen Kopenhagen (CPH) ist mit der Metro M2 in 15 Minuten mit dem Stadtzentrum verbunden. Hunde in Transportboxen werden akzeptiert; größere Hunde benötigen Maulkorb und Leine.`, `Aus Schweden: Die Öresundbrücke verbindet Kopenhagen mit Malmö (35 Min. mit dem Zug). Hunde mit EU-Heimtierausweis können frei einreisen.`, `Dänemark verwendet die dänische Krone (DKK), nicht den Euro. Die meisten Orte akzeptieren Karten; Bargeld wird selten benötigt.`],
    sights: {
      "Frederiksberg Have & Søndermarken": `Die romantischen englischen Landschaftsgärten des Frederiksberg-Schlosses, 32 Hektar Kanäle, Hügel und Waldland, zählen zu Kopenhagens besten Hundespaziergängen. Sie schließen direkt an den 55 Hektar großen Søndermarken-Park mit einer großen Freilaufzone an und sind das bevorzugte Morgenziel für Hundebesitzer im Westen Kopenhagens.`,
      "Refshaleøen & Amager Fælled": `Die ehemalige Werftinsel Refshaleøen, heute ein Kreativ- und Food-Hub, grenzt an das weitläufige Naturschutzgebiet Amager Fælled. Der Fælled (Gemeindeland) umfasst 3,5 km² Wiesen, Feuchtgebiete und Wald, einer der besten wild wirkenden Hundespaziergänge ohne Leine in jeder europäischen Hauptstadt.`,
      "Nørrebro & Assistens Cemetery": `Nørrebro ist Kopenhagens hundefreundlichstes Viertel: unabhängige Cafés mit Hunden unter den Tischen, ein samstäglicher Biomarkt und der Assistens-Friedhof, Begräbnisstätte von Kierkegaard und H.C. Andersen, der zugleich ein beliebter öffentlicher Park ist, in dem Einheimische picknicken und Hunde ausführen.`,
      "Copenhagen Harbour & Nyhavn": `Der bunte Kanal von Nyhavn aus dem 17. Jahrhundert und die Hafenfront sind mit Hund befahrbar. Die Hafenbäder (Badestellen) sind für Hunde nicht zugänglich, doch die Uferpromenade und die Kanalrundfahrten (Nettobådene) lassen Hunde in Transportboxen zu.`,
      "Tivoli Gardens": `Tivoli lässt keine Hunde zu. Es ist eine der Top-Attraktionen Kopenhagens, erfordert aber, das Haustier im Hotel zu lassen. Prüfen Sie Unterkünfte mit sicherer Hundebetreuung, wenn Sie einen Tivoli-Abend planen.`,
    },
  },
  cordoba: {
    history: `Córdoba, im 2. Jahrhundert v. Chr. von den Römern gegründet, war im 10. Jahrhundert die größte Stadt Europas, Hauptstadt des Umayyaden-Kalifats von al-Andalus, mit rund 500.000 Einwohnern, 700 Moscheen, 600 Hammams und einer der größten Bibliotheken der Welt. Dieses dreifache Erbe, römisch, maurisch, dann christlich, prägt die moderne Stadt: die UNESCO-gelistete Mezquita-Catedral, die römische Brücke über den Guadalquivir, das mittelalterliche Judería-Viertel mit seinen weiß getünchten Gassen und die andalusische Patio-Tradition (Festival im Mai). Heute ist Córdoba mit 325.000 Einwohnern der unverzichtbare Halt auf jeder andalusischen Hochgeschwindigkeitszug-Route, 45 Minuten mit dem AVE von Sevilla, 1 Std. 45 Min. von Madrid entfernt. Für Hundebesitzer ist Córdoba von Oktober bis Mai herrlich begehbar (kompaktes historisches Zentrum, hundefreundliche Terrassen, zwei städtische Áreas de Esparcimiento Canino), aber im Juli und August strapaziös: Die Temperaturen übersteigen regelmäßig 40 °C, und der Gehweg erreicht 60 °C.`,
    petTips: [`Extreme Sommerhitze: im Juli-August regelmäßig über 40 °C, Gehweg bei 60 °C, NUR zwischen 6 und 8 Uhr morgens oder nach 21 Uhr spazieren gehen. Keine nahen Hundestrände (200 km bis zum Meer).`, `Renfe AVE nimmt kleine Hunde in Transportboxen kostenlos mit; Pilotprogramm Mascotas Grandes (15 €) im AVE für Hunde bis 40 kg, Córdoba liegt im Herzen des Streckennetzes.`, `Spanisches PPP-Gesetz (Ley 50/1999): 8 Rassen benötigen eine Genehmigung, Leine und Maulkorb in der Öffentlichkeit sowie eine Haftpflichtversicherung.`, `Das Hospital Veterinario Córdoba (957 281 940) im Stadtzentrum ist die einzige rund um die Uhr geöffnete Tierklinik, speichern Sie die Nummer vor der Ankunft.`, `Patio-Festival (Anfang Mai): über 60 Patios öffnen kostenlos, die meisten hundefreundlich. Das beste kulturelle Zeitfenster.`],
    practicalInfo: [`Mezquita-Catedral, Alcázar und Synagoge lassen alle keine Haustiere zu, buchen Sie für diese Besuche einen lokalen Pawshake- oder Gudog-Betreuer im Voraus.`, `Kompaktes historisches Zentrum (1,5 km breit), außerhalb der sommerlichen Hitzestunden vollständig mit Hund begehbar.`, `Der Flughafen Córdoba ist klein, nutzen Sie Sevilla-San Pablo (1 Std. 45 Min. mit dem AVE) oder Málaga-Costa del Sol (2 Std. mit dem Auto). Iberia/Vueling nehmen Hunde bis 8 kg in der Kabine mit.`, `AVE-Tagesausflüge ab Córdoba: Sevilla (45 Min.), Madrid (1 Std. 45 Min.), Málaga (1 Std.), Granada (1 Std. 30 Min. mit AVE plus Avant), alle hundefreundlich.`, `Brexit, Schweiz außerhalb der EU: Standard-EU-Regeln für die Einreise nach Spanien. EU-Heimtierausweis plus gültige Tollwutimpfung.`],
    sights: {
      "Mezquita-Catedral": `Kathedrale-Moschee aus dem 10. Jahrhundert, UNESCO-Weltkulturerbe, die ehemalige Große Moschee des Kalifats. Im Inneren keine Hunde erlaubt, besuchen Sie das Äußere und die römische Brücke davor.`,
      "Roman Bridge": `16-bogige römische Brücke über den Guadalquivir (1. Jahrhundert v. Chr.). Seit 2008 vollständig fußgängerfreundlich, ikonischer Blick auf die Mezquita bei Sonnenuntergang.`,
      "Judería": `Mittelalterliches jüdisches Viertel mit engen weiß getünchten Gassen. Die berühmte Calleja das Flores rahmt den Turm der Mezquita ein. Angeleint hundefreundlich, außer in den Bauwerken.`,
      "Plaza de la Corredera": `Córdobas einziger großer rechteckiger Platz (1683), mit roten kastilisch-barocken Gebäuden. Samstäglicher Lebensmittelmarkt, hundefreundliche Café-Terrassen.`,
      "Sotos de a Albolafia": `Geschütztes Naturgebiet am Flussufer entlang des Guadalquivir unterhalb der römischen Brücke. 2 km angeleinter Weg, geschützte Tierwelt. Außergewöhnlicher Blick auf die Mezquita.`,
      "Sierra de Córdoba": `Ausläufer der Sierra Morena, 15 Minuten nördlich. Pinien- und Eichenwald, markierte Wege ohne Leine, Stauseen zum Schwimmen für Hunde. Unverzichtbare Sommerflucht.`,
    },
  },
  corfu: {
    history: `Korfu ist die venezianischste der griechischen Inseln: vier Jahrhunderte Herrschaft der Serenissima (1386-1797) prägten ihre UNESCO-gelistete Altstadt mit ihren zwei Festungen, engen Gassen (kantounia) und hohen Häusern mit Fensterläden. Die Franzosen fügten die Liston-Arkaden hinzu, nach dem Vorbild der Rue de Rivoli, und die Briten brachten Cricket und den Palast von St. Michael und St. George mit, bevor die Insel 1864 Griechenland beitrat. Kaiserin Sisi ließ hier das Achilleion errichten, einen Achilles gewidmeten Palast. Grün, regenreich und mit drei Millionen Olivenbäumen bepflanzt, ist Korfu anders als jede andere griechische Insel. Mit Hund ist die Insel ein echter Spielplatz: Spaziergänge unter Olivenhainen, Buchten an der Nordostküste, eine riesige Esplanade in der Stadt und eine sehr aktive lokale Tierschutzgemeinschaft.`,
    petTips: [`Im Sommer sind organisierte Strände mit Sonnenliegen tagsüber für Hunde gesperrt: Zielen Sie auf die Buchten der Nordostküste (rund um Kalami und Agni) und wildere Strände, früh morgens oder abends.`, `In öffentlichen Räumen ist die Leinenpflicht vorgeschrieben, und in der belebten Altstadt wird das Entsorgen von Kot erwartet.`, `Die Insel hat viele streunende Hunde und Katzen; die lokale Hilfsorganisation ARK (Animal Rescue Kerkyra) ist auf der Insel gut bekannt. Halten Sie Abstand zu frei umherstreifenden Rudeln auf dem Land.`, `Von Juni bis September ermüden Hitze und Luftfeuchtigkeit Hunde schnell: Gehen Sie in den kühlen Stunden spazieren, führen Sie stets Wasser mit sich und lassen Sie ein Tier nie im Auto zurück.`, `Vorbeugung gegen Leishmaniose und Zeckenbehandlung sind unerlässlich: Sandmücken sind auf den Ionischen Inseln von Mai bis Oktober präsent.`],
    practicalInfo: [`Mehrere Tierarztpraxen in Korfu-Stadt und den Hauptorten; rufen Sie bei einem nächtlichen Notfall zuerst an, der Bereitschaftsdienst rotiert zwischen den Praxen`, `Europäische Notrufnummer: 112; bei einem verletzten Streuner ist die Hilfsorganisation ARK der örtlich bekannte Ansprechpartner`, `Zoofachgeschäfte in der Stadt und Haustierregale in Supermärkten in den Touristengebieten`, `Stadt- und Überlandbusse (KTEL Green Buses): kleine Hunde in Transportboxen; bei Taxis hängt die Mitnahme vom Fahrer ab`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich; Fähren von Igoumenitsa und Italien nehmen Hunde mit (Deck, Zwinger oder Haustierkabine je nach Reederei)`],
    sights: {
      "Palia Poli (Old Town)": `Korfus UNESCO-gelistete Altstadt ist ein Geflecht venezianischer Gassen zwischen zwei Festungen. Weitgehend fußgängerfreundlich und schattig, lässt sie sich mit angeleintem Hund gut erkunden, am besten früh morgens, bevor die Kreuzfahrtausflüge eintreffen.`,
      "Liston": `Die eleganten Liston-Arkaden, unter französischer Herrschaft nach dem Vorbild der Rue de Rivoli erbaut, säumen die weite Spianada-Esplanade. Die Cafés heißen Hunde auf ihren Terrassen willkommen, und die Esplanade bietet eine der größten städtischen Promenaden Griechenlands.`,
      "Achilleion": `Kaiserin Sisis neoklassizistischer, Achilles gewidmeter Palast blickt von Gastouri aus mit seinen statuengeschmückten Gärten auf das Meer. Hunde sind weder im Palast noch in den umschlossenen Gärten zugelassen: Bewundern Sie ihn von außen und setzen Sie den Weg zu den Olivenhain-Pfaden in den nahen Hügeln fort.`,
      "Paleokastritsa": `Sechs türkisfarbene Buchten am Fuß von mit Oliven und Zypressen bedeckten Hügeln: Paleokastritsa ist die berühmteste Landschaft der Insel. Bevorzugen Sie mit Hund die weniger erschlossenen Buchten und den Pfad, der zum Dorf Lakones hinaufsteigt, für eine unvergessliche Aussicht.`,
      "Mon Repos": `Dieses bewaldete Anwesen südlich der Stadt, Geburtsort von Prinz Philip, verbirgt eine neoklassizistische Villa, die antiken Ruinen von Paleopolis und schattige Pfade hinunter zum Meer. Der Park kann angeleint durchquert werden; das Villenmuseum selbst bleibt für Hunde geschlossen.`,
      "Palaio Frourio": `Die Alte Venezianische Festung, auf einem durch eine Brücke verbundenen Felseneiland gelegen, bewacht seit dem 15. Jahrhundert den Eingang zur Altstadt. Als ticketpflichtige, umschlossene Anlage lässt sie keine Hunde zu: Der Faliraki-Hafenspaziergang direkt darunter bietet den besten Blick auf ihre Wehrmauern.`,
    },
  },
  cork: {
    history: `Cork, mit 210.000 Einwohnern Irlands zweitgrößte Stadt, wurde im 7. Jahrhundert von den Mönchen des Heiligen Finbarr auf einer sumpfigen Insel am Zusammenfluss des River Lee gegründet und im 9. Jahrhundert von den Wikingern zu einer befestigten Stadt ausgebaut (der Name stammt vom gälischen "Corcaigh": Sumpf). Im 19. Jahrhundert wurde Cork der wichtigste Auswandererhafen für Iren, die nach Nordamerika aufbrachen; von Cobh aus, 20 Minuten mit dem Zug entfernt, legte 1912 die Titanic ab. Heute als "Rebel City" für ihre Rolle im Unabhängigkeitskrieg bekannt, pflegt Cork einen ausgeprägten lokalen Stolz um ihren viktorianischen English Market, ihre 25.000 Studierenden des University College Cork und ihre Gastroszene: drei mit Michelin-Sternen ausgezeichnete Köche in einer Stadt, die kleiner ist als Bordeaux. Für Reisende mit Hund ist Cork eine von Irlands einladendsten Städten: Fitzgerald's Park im Herzen des Zentrums, der Ballincollig Regional Park (200 Hektar mit Freilaufzone) 8 km entfernt, traditionelle Pubs, die die "Snug"-Tradition pflegen (kleine holzvertäfelte Nebenräume, in denen Hunde zugelassen sind), sowie der Cork Harbour mit Cobh, Fountainstown und Garrettstown, alle unter 30 Minuten mit dem Auto für Strandspaziergänge erreichbar. Bus Éireann und Iarnród Éireann befördern angeleinte Hunde kostenlos.`,
    petTips: [`Bus Éireann und Iarnród Éireann nehmen angeleinte und mit Maulkorb versehene Hunde kostenlos mit, nach Ermessen des Fahrers bzw. Schaffners.`, `Die Satzungen des Cork City Council sehen Bußgelder von bis zu 4.000 € für nicht entsorgten Hundekot vor; kostenlose Kotbeutelspender stehen an jedem öffentlichen Parkeingang.`, `Die "Snug"-Tradition (kleine holzvertäfelte Nebenräume neben der Bar) wird bei Sin É, The Long Valley und An Spailpín Fánach gepflegt, Hunde sind dort willkommen.`, `24-Stunden-Notfallkliniken: Gilabbey Veterinary Hospital (021 431 2900) und ARK Veterinary Hospital (021 496 6677).`, `Irlands Listenhunde (Pit Bull Terrier, Rottweiler, Dobermann, Bull Mastiff) müssen in der Öffentlichkeit Maulkorb und kurze Leine (≤2 m) tragen, was auch an den Uferspaziergängen des Cork Harbour durchgesetzt wird.`],
    practicalInfo: [`Einreise nach Irland: EU-Heimtierausweis plus Bandwurmbehandlung (Echinokokken), von einem EU-Tierarzt 24-120 Std. vor der Ankunft verabreicht und im Ausweis vermerkt.`, `Der Flughafen Cork (ORK) liegt 8 km südlich, Bus 226A alle 30 Min., 25 Minuten Fahrzeit, angeleinte Hunde kostenlos.`, `Iarnród-Éireann-Zug Cork-Dublin (2 Std. 30 Min.) und Cork-Cobh (25 Min.), kleine Hunde in Transportboxen kostenlos, größere angeleinte und mit Maulkorb versehene Hunde kostenlos im Vorraum.`, `Das Cork Jazz Festival (Ende Oktober) füllt die Hotels, buchen Sie 3 Monate im Voraus oder meiden Sie die letzte Oktoberwoche.`, `Feuchtes ozeanisches Klima: Packen Sie ein saugfähiges Handtuch und einen Hunderegenmantel ein, es regnet in der Grafschaft Cork durchschnittlich an 200 Tagen im Jahr.`],
    sights: {
      "Fitzgerald's Park": `Corks bester edwardianischer Park (5 Hektar) am westlichen Rand des Stadtzentrums, mit dem River Lee, dem Cork Public Museum, Brunnen und Rosengärten. Angeleinte Hunde, Beutel an den Eingängen.`,
      "Ballincollig Regional Park": `Corks größter Park (200 Hektar) entlang des River Lee, 8 km westlich. Ausgewiesene Freilaufzone entlang des südlichen Uferwegs; Ruinen der königlichen Schießpulvermühlen.`,
      "Blackrock Castle": `Burg aus dem 16. Jahrhundert auf einer Landzunge des Cork Harbour, heute eine Sternwarte. Anlage, Uferdamm und Café-Terrasse für angeleinte Hunde zugänglich.`,
      "Saint Fin Barre's Cathedral": `Neugotische Kathedrale von William Burges (1879) mit den meistfotografierten Türmen Corks. Angeleinte Hunde im Außenbereich und auf den Rasenflächen willkommen.`,
      "The Lough": `5 Hektar großer Süßwassersee und Wildschutzgebiet in den südlichen Vororten, mit 1 km langem Uferweg. Angeleinte Hunde, geschützte Schwanenkolonie.`,
      "Cobh waterfront": `Historischer Abfahrtshafen der Titanic, 25 Minuten mit dem Zug entfernt, mit 2 km Uferpromenade, der ikonischen Häuserreihe Deck of Cards und der St.-Colman's-Kathedrale. Angeleinte Hunde in allen Außenbereichen willkommen.`,
    },
  },
  'costa-da-caparica': {
    history: `Costa da Caparica erstreckt sich am Südufer des Tejo, gegenüber von Lissabon, und gehört zur Gemeinde Almada im Bezirk Setúbal. Einst ein Fischerdorf und heute ein bei Lissabonnern beliebter Badeort, reiht der Ort fast 24 Kilometer atlantischer Strände aneinander, hinterlegt von der Arriba Fóssil, einer als Naturlandschaft geschützten Fossilklippe. Die nördlichen Stadtstrände wie Praia do Rei und Praia da Saúde versammeln Restaurants, Surfschulen und sommerliches Treiben, während der Süden, im Sommer vom kleinen Zug Transpraia bedient, sich zu wilderen Praias bis nach Fonte da Telha öffnet. Hinter den Dünen breitet sich der Kiefernwald Mata dos Medos aus, ein botanisches Reservat, das im 18. Jahrhundert angepflanzt wurde, um den Sand zurückzuhalten. Wer mit Hund hierher reist, muss die atlantischen Gezeiten, die sommerlichen Strandverbote von Juni bis September und die Anreise per Fähre und Bus ab Lissabon einplanen.`,
    petTips: [`Sommerliches Verbot an bewachten Stränden: Von etwa 1. Juni bis 30. September sind Hunde an Portugals ausgezeichneten Stränden verboten, weichen Sie auf die wilden südlichen Praias wie Fonte da Telha aus oder besuchen Sie die Gegend außerhalb der Saison.`, `Atlantische Gezeiten und Strömungen: Die Küste ist der Dünung ausgesetzt, und Strömungen (agueiros) sind verbreitet, halten Sie Ihren Hund nahe am Ufer und beobachten Sie die steigende Flut, die den Strand schnell schrumpfen lässt.`, `Glühend heißer Sommersand: Zwischen Juni und September erreicht der Sand in den heißen Stunden pfotenverbrennende Temperaturen, bevorzugen Sie die Morgendämmerung oder den späten Nachmittag und testen Sie den Boden mit der Hand.`, `Der kleine Zug Transpraia und die Mata dos Medos bieten schattige Alternativen, wenn Strände tabu oder zu heiß sind, der Kiefernwald bleibt auch im Hochsommer kühl.`, `Für die Fahrt nach Lissabon akzeptieren die Fähre Cacilhas-Lissabon und die Regionalbusse in der Regel angeleinte Hunde mit Maulkorb, führen Sie also einen Maulkorb und den aktuellen Impfausweis mit.`],
    practicalInfo: [`Einzige Notrufnummer in Portugal: 112 (Polizei, Feuerwehr, Rettungsdienst).`, `Nächster Flughafen: Lissabon (LIS, Humberto Delgado), etwa 20 km entfernt über die Brücke 25 de Abril, dann mit dem Bus nach Costa da Caparica.`, `Mildes atlantisches Klima: warme, sonnige Sommer und milde, feuchte Winter, Frühling und Frühherbst sind für Reisen mit Hund am angenehmsten.`, `Anreise von Lissabon: die Fähre Cais do Sodré-Cacilhas plus Bus, oder ein direkter Bus ab Bahnhof Sete Rios, führen Sie einen Maulkorb für große Hunde in öffentlichen Verkehrsmitteln mit.`, `Fragen Sie in Ihrer Unterkunft nach der nächstgelegenen diensthabenden Tierklinik in Almada oder Costa da Caparica, bevor Sie ankommen.`],
    sights: {
      "Praia do Rei e Praia da Saúde": `Die wichtigsten Stadtstrände entlang der Küste, das Herz des Badeorts mit seinen Restaurants, Surfschulen und der lebhaften Promenade. Wie die meisten bewachten portugiesischen Strände verbieten sie Hunde im Hochsommer, sparen Sie sich dafür die wilderen südlichen Praias oder die Nebensaison auf.`,
      "Arriba Fóssil da Costa da Caparica": `Die lange ockerfarbene Fossilklippe, die über der Küste aufragt und wegen ihrer geologischen Schichten und Flora als Naturlandschaft geschützt ist. Die Klippenpfade können angeleint begangen werden und bieten weite Ausblicke über den Atlantik, fernab der überfüllten Strände.`,
      "Mata Nacional dos Medos": `Der küstennahe Kiefernwald Mata dos Medos, ein im 18. Jahrhundert zur Stabilisierung der Dünen angepflanztes botanisches Reservat, in dem alte Pinien und Wacholder überdauern. Seine schattigen Wege eignen sich für angeleinte Spaziergänge, ein willkommener kühler Rückzugsort, wenn die Strände heiß werden.`,
      "Fonte da Telha": `Der Strandweiler am südlichen Ende des Dünenstreifens, unterhalb der Fossilklippe, wilder und weniger reglementiert als die nördliche Küste. Fernab der bewachten Zonen tolerieren diese langen Strände häufiger angeleinte Hunde, besonders außerhalb der Saison und am frühen Morgen.`,
      "Cabo Espichel": `Die wilde Landzunge im Süden der Halbinsel, gekrönt vom barocken Wallfahrtsort Nossa Senhora do Cabo und umgeben von meerumtosten Klippen. Die Stätte wird im Freien und an der Leine besucht, zwischen der Esplanade des Heiligtums, dem Leuchtturm und den auf dem Fels sichtbaren Dinosaurierspuren.`,
      "Núcleo Piscatório da Caparica": `Das alte, um die Fischerei entstandene Zentrum mit seinen niedrigen Gassen, Fischständen und Terrassen mit gegrillten Spezialitäten. Es lässt sich leicht angeleint erkunden und erlaubt bei schönem Wetter, mit Ihrem Hund zu Füßen auf einer Terrasse zu speisen.`,
    },
  },
  cromer: {
    history: `Cromer, ein Küstenort in North Norfolk, entwickelte sich von einem für seine Krabben berühmten Fischerdorf zu einem eleganten viktorianischen Badeort, der mit der Eisenbahn erreichbar wurde. Sein denkmalgeschützter Pier, 1902 eröffnet, beherbergt das letzte End-of-Pier-Theater des Landes und eine RNLI-Rettungsbootstation. Auf den höchsten Klippen Norfolks gelegen, ist der Ort noch immer berühmt für die Cromer-Krabbe und für eine fest etablierte britische Hundekultur. Der wichtigste Punkt für Besucher mit Hund: Der North Norfolk District Council verbietet Hunde vom 1. Mai bis 30. September vom Hauptstrand beiderseits des Piers, mit einem Bußgeld von 100 Pfund. Die Promenade bleibt das ganze Jahr über hundefreundlich, der benachbarte Strand von East Runton heißt Hunde auch mitten im Sommer willkommen, und der Norfolk Coast Path verläuft entlang der Klippen. Ein praktischer Hinweis: Seit dem Brexit ist für Hunde, die aus der EU einreisen, ein GB Animal Health Certificate erforderlich.`,
    petTips: [`Wichtige Regel: Vom 1. Mai bis 30. September sind Hunde am Hauptstrand von Cromer beiderseits des Piers verboten (100 Pfund Bußgeld); nutzen Sie die Promenade oder fahren Sie nach East Runton, das das ganze Jahr über hundefreundlich ist.`, `Von Oktober bis April öffnet sich der Strand von Cromer vollständig für Hunde und wird zu einem großartigen, windigen Ort zum Herumtoben unterhalb der Klippen.`, `Halten Sie den Hund auf den Klippen an der Leine und deutlich vom erodierenden, unbefestigten Rand entfernt; im Landesinneren an der Leine in der Nähe von Vieh und bodenbrütenden Vögeln.`, `Die Bittern Line nimmt Hunde kostenlos mit (bis zu zwei pro Fahrgast, an der Leine): Gehen Sie die Küste von Cromer nach Sheringham entlang und fahren Sie mit dem Zug zurück.`, `Tierarzt: Cromer Vets, 48 Overstrand Road, bietet für Kunden 24-Stunden-Support (+44 1263 808999); speichern Sie die Nummer vor einem langen Spaziergang.`],
    practicalInfo: [`Einreise nach Großbritannien nach dem Brexit: Großbritannien akzeptiert den EU-Heimtierausweis nicht; Hunde benötigen ein GB Animal Health Certificate (innerhalb von 10 Tagen ausgestellt), einen Mikrochip, eine Tollwutimpfung und eine Bandwurmbehandlung 24 bis 120 Stunden vor der Ankunft.`, `Anreise: Cromer verfügt über einen Bahnhof an der landschaftlich reizvollen Bittern Line nach Sheringham und Norwich; der nächste Flughafen ist Norwich (NWI), etwa 45 Minuten mit dem Auto entfernt.`, `Fortbewegung: eine kompakte Stadt zum Zu-Fuß-Gehen; die Bittern Line und lokale Busse fahren entlang der Küste nach Sheringham und den Runtons und nehmen Hunde mit.`, `Wetter: ein kühles Küstenklima an der Nordsee, windig; milde Sommer (18-19 °C) und kalte, nasse Winter (7 °C). Packen Sie eine winddichte Jacke und ein Hundehandtuch ein.`, `Nützliche Nummern: allgemeiner Notruf 999 oder 112; Cromer Vets, 24-Stunden-Support für Kunden, +44 1263 808999.`],
    sights: {
      "Cromer Beach and Promenade": `Ein Sand-Kies-Strand unterhalb der Klippen und des Piers. Hunde vom 1. Mai bis 30. September vom Strand verboten (100 Pfund Bußgeld); Promenade und Strand außerhalb der Saison problemlos, an der Leine.`,
      "East Runton Beach": `Der nächstgelegene ganzjährige Hundestrand, 1,5 Meilen westlich. Weiter Sand bei Ebbe, keine saisonale Einschränkung. Hunde an der Leine in der Nähe anderer Strandbesucher.`,
      "Cromer Pier": `Ein denkmalgeschützter viktorianischer Pier von 1902 mit End-of-Pier-Theater und RNLI-Station. Hunde das ganze Jahr über an der Leine auf der Promenade; das Wahrzeichen der Stadt.`,
      "Norfolk Coast Path": `Ein etwa 4 Meilen langer Klippenpfad von Cromer nach Sheringham über Beeston Bump. Hunde an der Leine; Abstand zum erodierenden Rand halten. Rückfahrt mit der Bittern Line.`,
      "Felbrigg Hall Estate": `Ein 3 Meilen entferntes National-Trust-Anwesen, 520 Acres Wald, Park und ein See. Hunde vom 1. März bis 31. Juli an der Leine über das gesamte Anwesen; nicht im Haus oder im ummauerten Garten.`,
      "West Runton Beach": `Ein 3 Meilen westlich gelegener Sand-Kreide-Strand, berühmt für das West-Runton-Mammut. Kleine Einschränkung nahe der Slipanlage vom 1. Mai bis 30. September; ansonsten das ganze Jahr über Hunde erlaubt.`,
    },
  },
  delft: {
    history: `Delft ist eine Kanalstadt in Südholland, auf halbem Weg zwischen Den Haag und Rotterdam, berühmt für zwei innerhalb ihrer Mauern geborene Größen: den Maler Johannes Vermeer und die blaue Delfter Keramik. Rund um den großen Markt stehen sich die Nieuwe Kerk, deren Gruft die Gräber des königlichen Hauses Oranien-Nassau birgt, und das Renaissance-Rathaus gegenüber. Etwas weiter neigt sich die Oude Kerk sichtbar über die Kanäle, während das Prinsenhof, ein ehemaliges Kloster, in dem Wilhelm von Oranien 1584 ermordet wurde, die Erinnerung an die niederländische Unabhängigkeit wachhält. Die königliche Manufaktur Royal Delft pflegt seit 1653 die Kunst der handbemalten Kachel. Flach, kompakt und von Fahrrädern durchzogen, lässt sich Delft am besten zu Fuß entlang seiner grachten und seiner hofjes erkunden, jener friedlichen Innenhöfe, unter einem milden maritimen Klima, das oft windig und feucht ist.`,
    petTips: [`Der Park Delftse Hout verfügt über ein offizielles hondenlosloopgebied (Freilaufzone) und eine Hundeschwimmstelle am See, der beste Ort für eine richtige Pause nahe dem Zentrum.`, `Im historischen Zentrum und entlang der Kanäle den Hund angeleint halten und den Kot entsorgen (opruimplicht), es drohen Bußgelder, aber die flachen Kopfsteinpflastergassen machen die Stadt sehr leicht zu Fuß erkundbar.`, `Im Sommer die Pflastersteine und die Kanalsteine mit der Hand testen und an heißen Tagen Wasser mitführen, und beachten Sie, dass am 27. April, dem Königstag (Koningsdag), das Zentrum überfüllt und laut ist, was mit einem ängstlichen Hund besser gemieden wird.`, `In NS-Zügen reist ein großer Hund mit einer Hunde-Tageskarte (dagkaart hond), kleine Hunde reisen kostenlos in einer Transportbox, halten Sie ihn auf Bahnsteigen und in Straßenbahnen angeleint.`, `Terrassen und viele Geschäfte dulden Hunde, doch die Kirchen (Nieuwe Kerk, Oude Kerk) und die Werkstätten von Royal Delft lassen sie im Inneren nicht zu.`],
    practicalInfo: [`Einzige Notrufnummer in den Niederlanden und in ganz Europa: 112.`, `Delft liegt an der NS-Strecke zwischen Den Haag und Rotterdam, etwa zehn Minuten von jeder Stadt entfernt, mit sehr häufigen Zügen.`, `Nächster Flughafen: Rotterdam The Hague (RTM), etwa 15 km entfernt, oder Amsterdam Schiphol (AMS), etwa 60 km.`, `Flache, fahrradfreundliche Stadt mit mildem maritimem Klima: regnerische, windige Winter, gemäßigte Sommer, Frühling und Sommer sind für Reisen mit Hund am angenehmsten.`, `Fragen Sie in Ihrer Unterkunft nach der nächstgelegenen diensthabenden Tierklinik, bevor Sie ankommen.`],
    sights: {
      "Markt": `Der große Kopfsteinpflasterplatz im Herzen der Stadt, gesäumt von Cafés und Terrassen, zwischen dem Rathaus und der Nieuwe Kerk. Man überquert ihn angeleint, und die niederländischen Terrassen heißen wohlerzogene Hunde gerne bei einer Waffel oder einem Kaffee willkommen.`,
      "Nieuwe Kerk": `Die gotische Kirche am Markt, deren hoher Turm die Stadt überragt und deren Gruft die Gräber des Hauses Oranien-Nassau birgt. Hunde dürfen weder hinein noch auf den Turm, doch man kann sie angeleint problemlos auf dem Platz umrunden.`,
      "Oude Kerk": `Die alte Kirche, erkennbar an ihrem deutlich über den Kanal geneigten Turm, in der Vermeer begraben liegt. Das Innere ist für Hunde geschlossen, doch der Kai daneben und die nahegelegene Brücke bieten einen schönen angeleinten Spaziergang am Wasser.`,
      "Grachten en hofjes": `Das Netz von Kanälen, gesäumt von Giebelhäusern, und die hofjes, jene blumigen, friedlichen Innenhöfe, verborgen hinter Toren. Alles wird angeleint entlang flacher, gepflasterter Gassen erkundet, ideal für einen Spaziergang mit Hund fernab des Verkehrs.`,
      "Koninklijke Porceleyne Fles": `Die königliche Manufaktur Royal Delft, der letzte historische Hersteller des blauen Delfter Porzellans, der seit 1653 noch arbeitet, mit ihrem Museum und Handbemal-Werkstätten. Aus Hygienegründen sind Hunde in den Werkstätten oder im Museum nicht zugelassen.`,
      "Delftse Hout": `Der große bewaldete Erholungspark östlich der Stadt, mit seinem Badesee, seinen Wegen und seiner Hundefreilaufzone. Er verfügt über ein offizielles hondenlosloopgebied und eine Stelle, an der Hunde schwimmen können, die beste Adresse für eine echte Pause ohne Leine.`,
    },
  },
  denia: {
    history: `Dénia erstreckt sich am Fuß des Montgó-Massivs an der Costa Blanca, auf halbem Weg zwischen Alicante und Valencia. Einst römische Kolonie und dann im 11. Jahrhundert Hauptstadt eines muslimischen Taifa-Königreichs, wird der Ort von seiner mittelalterlichen Burg gekrönt, in der sich das archäologische Museum befindet und die über ein Gassengewirr und die Calle Loreto, die Tapas-Straße, wacht. Sein Fischerei- und Yachthafen unterhält die Fähren nach Ibiza und Formentera, während die Küste sich zwischen den langen Sandstränden von Les Marines im Norden und der felsigen Küste von Les Rotes im Süden mit ihren zahlreichen Buchten aufteilt. Hinter dem Ort schützt der Naturpark Montgó ein 750 Meter hohes Kalksteinmassiv, durchzogen von Wanderwegen. Wer mit Hund hierher reist, muss die starke mediterrane Hitze und die Strandverbote der Hochsommersaison einplanen.`,
    petTips: [`Sommerliches Verbot an Stadtstränden: Von etwa Ostern bis Ende September sind Hunde an den überwachten Stränden von Les Marines verboten, gehen Sie stattdessen zum ausgewiesenen Hundestrand oder zu den Buchten von Les Rotes.`, `Starke mediterrane Hitze: Von Juni bis September übersteigen die Temperaturen oft 30 °C, und der Sand verbrennt die Pfoten, gehen Sie in der Morgendämmerung oder abends spazieren und testen Sie den Boden mit der Hand.`, `Das Montgó-Massiv ist steil und kaum beschattet: Führen Sie Wasser mit, starten Sie früh und verzichten Sie in den heißen Stunden auf Wanderungen, der Kalkstein strahlt die Hitze zurück.`, `Für die Fährüberfahrt zu den Balearen prüfen Sie die Regeln des Betreibers im Voraus: Eine Transportbox, ein Maulkorb und ein aktueller Impfausweis sind in der Regel erforderlich.`, `In Spanien den Hund in der Ortschaft angeleint halten und den Kot entsorgen, kommunale Bußgelder sind entlang der Costa Blanca verbreitet.`],
    practicalInfo: [`Einzige Notrufnummer in Spanien: 112 (Polizei, Feuerwehr, Rettungsdienst).`, `Nächste Flughäfen: Alicante (ALC), etwa 100 km entfernt, und Valencia (VLC), etwa 110 km, beide über die Autobahn erreichbar.`, `Mediterranes Klima: heiße, trockene Sommer und milde Winter, Frühling und Herbst sind für Reisen mit Hund am angenehmsten.`, `Vom Hafen aus bedienen Fähren Ibiza und Formentera; Hunde werden nach den Regeln des Betreibers akzeptiert, buchen Sie deren Platz im Voraus.`, `Fragen Sie in Ihrer Unterkunft nach der nächstgelegenen diensthabenden Tierklinik in Dénia, bevor Sie ankommen.`],
    sights: {
      "Castell de Dénia": `Die mittelalterliche Burg, die den Hügel krönt, mit ihren Wehrmauern, dem Gouverneurspalast und dem in ihre Mauern eingebetteten archäologischen Museum. Angeleinte Hunde sind in den Gärten und auf den Wehrmauern erlaubt, aber nicht in den Museumsräumen.`,
      "Parc Natural del Montgó": `Das 750 Meter hohe Kalksteinmassiv über dem Ort, ein Naturpark, durchzogen von Wanderwegen durch Buschland und Klippen. Angeleinte Hunde sind erlaubt, doch das Gelände ist steil und exponiert, führen Sie also Wasser mit und meiden Sie die heißen Sommerstunden.`,
      "Les Rotes": `Die felsige Küste südlich des Ortes, wo kleine Buchten und Felsplatten den Sand ersetzen. Ruhiger und unmarkiert, dulden mehrere dieser Buchten angeleinte Hunde, besonders außerhalb der Saison, eine Alternative zu den im Sommer für sie gesperrten Stadtstränden.`,
      "Puerto de Dénia": `Der Fischerei- und Yachthafen, von dem aus die Fähren nach Ibiza und Formentera ablegen. Die Kais und die Promenade werden angeleint begangen, und Hunde sind an Bord der Fähren nach den Regeln des Betreibers zugelassen, üblicherweise in einer Box oder mit Maulkorb an Deck.`,
      "Playa canina de Les Marines": `Am Sandstreifen von Les Marines nördlich des Ortes richtet Dénia einen Hundestrand ein, an dem Hunde auch im Sommer erlaubt sind. Es ist der sicherste Ort, um sie in der Hochsaison das Meer genießen zu lassen, wenn die Stadtstrände für sie gesperrt sind.`,
      "Calle Loreto": `Das alte Zentrum unterhalb der Burg, mit seinen Gassen und der Calle Loreto, der von Terrassen gesäumten Tapas-Straße. Es lässt sich leicht angeleint erkunden, und bei schönem Wetter heißen viele Terrassen einen Hund zu Füßen willkommen.`,
    },
  },
  denver: {
    history: `Denver begann 1858 als Goldgräberlager dort, wo der Cherry Creek auf den South Platte trifft, an der Stelle, die heute Confluence Park ist. Der Goldrausch verebbte schnell, doch die Siedlung hielt sich als Handels- und Eisenbahnknotenpunkt der Front Range, angelehnt an die Wand der Rocky Mountains. Sie wird die Mile High City genannt, weil eine Stufe des State Capitol genau eine Meile über dem Meeresspiegel liegt, 1.609 Meter. Das zwanzigste Jahrhundert hinterließ ihr die Union Station, die Backsteinlagerhausblocks von LoDo und ein Netz großer Stadtparks aus dem City-Beautiful-Plan, später erweitert durch die Denver Mountain Parks, zu denen auch Red Rocks gehört. Heute stapelt die Stadt Brauereien, die RiNo-Wandbilder und direkten Zugang zu den Bergen aufeinander, mit einer Hundekultur, die auf jeder Terrasse sichtbar ist, sofern man eine kurze Leine und ein für Haustiere gesperrtes öffentliches Verkehrssystem akzeptiert.`,
    petTips: [`Die Leinenlänge ist in Denver an jedem öffentlichen Ort auf sechs Fuß (1,8 m) begrenzt, und Freilauf ist nur innerhalb der siebzehn eingezäunten städtischen Hundeparks legal. Die städtische Verordnung sieht Bußgelder von bis zu 999 Dollar vor.`, `RTD, das die Busse, die Stadtbahn und die A-Line-Flughafenbahn betreibt, nimmt nur kleine Haustiere in einer verschlossenen Transportbox mit. Kein angeleinter Hund jeglicher Größe, und keine Ausnahme außerhalb der Stoßzeiten.`, `Hunde dürfen nicht in die Seen der Stadtparks, einschließlich Smith und Grasmere, teilweise wegen der spätsommerlichen Blaualgen. Die nächstgelegene legale Schwimmmöglichkeit sind die Teiche der Freilaufzone Chatfield.`, `Cannabis ist in Colorado legal, und weggeworfene Esswaren verursachen einen stetigen Strom von Vergiftungen bei Hunden. Ein Hund, der wackelig wird, stark sabbert oder desorientiert wirkt, sollte direkt zum Notfall-Tierarzt.`, `Testen Sie den Asphalt im Juli mit dem Handrücken, bevor Sie spazieren gehen, und spülen Sie im Winter die Pfoten danach ab: Die Stadt streut und enteist stark, und diese Mischung reißt Ballen auf und ist giftig, wenn sie abgeleckt wird.`],
    practicalInfo: [`24-Stunden-Notfall-Tierärzte: VEG Denver, 3845 E Colfax Ave, +1 720 574 9834, ohne Termin; Wheat Ridge Animal Hospital, 10140 W 44th Ave, +1 303 424 3325; VRCC, 3550 S Jason St in Englewood, +1 303 874 7387. 911 ist nur für Menschen.`, `Einreise in die Vereinigten Staaten: Die CDC-Regeln seit August 2024 verlangen einen mindestens sechs Monate alten Hund, gesund bei Ankunft, einen ISO-kompatiblen Mikrochip, der vor jeder Tollwutimpfung implantiert wurde, sowie eine online vor der Reise erhaltene Empfangsbestätigung des CDC Dog Import Form.`, `Denver liegt auf 1.609 m, sodass ein Hund, der auf Meereshöhe ankommt, mehr trinkt und schneller ermüdet. Echte Höhenkrankheit beginnt oberhalb von 2.400 m, wo die Wanderwege westlich der Stadt beginnen.`, `Die großen Indoor-Attraktionen schließen Haustiere aus: Denver Botanic Gardens, der Zoo, das Aquarium, das Denver Art Museum und das Museum of Nature & Science. Hunde sind auch aus den Speisebereichen der Restaurants verbannt und auf Terrassen mit Außenzugang beschränkt.`, `Beste Zeitfenster: Ende April bis Mitte Juni und September bis Mitte Oktober. Juli und August übersteigen regelmäßig 30 °C mit Nachmittagsgewittern, und März ist der schneereichste Monat.`],
    sights: {
      "Washington Park": `Siebenundsechzig Hektar Rasen, alte Bäume und Blumengärten, mit einer 4 km langen Runde, die der Standardspaziergang der Stadt ist. Hunde sind an einer Leine von höchstens 1,8 m willkommen, dürfen aber nicht in den Smith Lake oder Grasmere Lake sowie nicht auf die Spielplätze und Sportfelder.`,
      "Red Rocks Park": `Der rote Sandsteinpark der Denver Mountain Parks, 25 km westlich, berühmt für sein natürliches Amphitheater. Angeleinte Hunde sind außerhalb der Veranstaltungszeiten auf den Parkwegen erlaubt, aber niemals im Amphitheater, im Besucherzentrum oder bei einer Veranstaltung mit Ticket.`,
      "Confluence Park": `Der Zusammenfluss von Cherry Creek und South Platte, der Geburtsort der Stadt von 1858 und der Kreuzungspunkt ihrer beiden großen Grünzüge. Steinstufen führen zum Wasser hinab, Kajakfahrer nehmen die Rutsche, und ein Hund geht dort an der Leine spazieren, zehn Minuten von der Union Station entfernt.`,
      "Cherry Creek Trail": `Der Grünzug, der dem Bett des Cherry Creek vom Confluence Park bis nach Cherry Creek North und darüber hinaus folgt und dabei über weite Strecken unterhalb des Straßenniveaus verläuft. Es ist die beste Spazierroute in der Stadt mit Hund, verkehrsfrei und mit Abfalleimern gesäumt.`,
      "Union Station": `Der 1914 im Beaux-Arts-Stil erbaute, 2014 restaurierte Bahnhof, das Herz von LoDo mit seinen Terrassen, dem Platz und den Hotels. Angeleinte Hunde bewegen sich problemlos rund um den Außenplatz und entlang der Wynkoop Street, doch die Geschäfte und die große Halle liegen jeweils im Ermessen des Betreibers.`,
      "Chatfield State Park": `Der State Park in Littleton, eine halbe Stunde südlich, dessen Freilaufzone 28 eingezäunte Hektar, zwei Teiche, in denen Hunde schwimmen dürfen, und kilometerlange Wege bietet. Sie benötigen den Fahrzeug-Parkausweis sowie einen separaten Hunde-Freilaufzonen-Ausweis, 3 Dollar für den Tag oder 25 Dollar für das Jahr.`,
    },
  },
  dresden: {
    history: `Um 1206 an den Ufern der Elbe gegründet, wurde Dresden im 18. Jahrhundert unter Kurfürst August dem Starken zum "Elbflorenz", dessen Zwinger, Schloss und Frauenkirche die Stadt zu einem der glanzvollsten Barockhöfe Europas machten. Die alliierten Bombenangriffe vom Februar 1945 zerstörten das Zentrum; der geduldige Wiederaufbau der 2005 vollendeten Frauenkirche ist zum Symbol der Wiedergeburt der Stadt geworden. Als Hauptstadt Sachsens und gesäumt von den Elbwiesen, jenen Flussauen, auf denen Hunde nach langjährigem Brauch ohne Leine laufen, verbindet Dresden barockes Erbe, einen 5.800 Hektar großen städtischen Wald und eine historische Raddampferflotte, die Hunde ohne Aufpreis willkommen heißt.`,
    petTips: [`In DVB-Straßenbahnen und -Bussen müssen Hunde außerhalb einer Transportbox einen Maulkorb tragen und an kurzer Leine geführt werden, 20 € Bußgeld bei fehlendem Maulkorb.`, `Auf den Elbwiesen laufen Hunde nach lokalem Brauch ohne Leine, bleiben Sie auf dem Grünstreifen zwischen Fluss und Radweg und meiden Sie markierte Wasserschutzbereiche.`, `Die Dresdner Heide unterliegt vom 1. März bis 30. Juni der Leinenpflicht (Brutzeit im Wald); den Rest des Jahres gelten markierte Hundeauslauf-Trails.`, `Die Raddampfer der Sächsischen Dampfschifffahrt nehmen Hunde an kurzer Leine ohne Aufpreis mit, die stromaufwärts führende Pillnitz-Linie fährt durch die Weinberge.`, `Zentrale Notfall-Tierarztnummer: 01805 843736 (Rotation des Tierärztlichen Notdienstes Dresden); ein Netto-Notfallzuschlag von 50 € kommt zu den Standardgebühren hinzu.`],
    practicalInfo: [`EU-Heimtierausweis und aktuelle Tollwutimpfung beim Check-in in jedem haustierfreundlichen Hotel erforderlich.`, `Leinenpflicht in allen öffentlichen Räumen außerhalb der Hundeauslaufzonen und der Elbwiesen, Kot muss entsorgt werden, Bußgelder ab 20 €.`, `Zwinger, Albertinum, Residenzschloss und Frauenkirche lassen nur Assistenzhunde zu, buchen Sie einen Pawshake- oder Rover-Betreuer, wenn Sie diese besuchen möchten.`, `Notfall außerhalb der Öffnungszeiten (Tierärztlicher Notdienst Dresden): rufen Sie 01805 843736 an, die Rotation der diensthabenden Praxis wird wöchentlich aktualisiert.`, `Nächster Flughafen: Dresden International (DRS), 9 km vom Zentrum entfernt; alternativ Berlin BER mit direktem ICE-Zug (2 Std. 15 Min.).`],
    sights: {
      "Frauenkirche": `Die von 1994 bis 2005 auf den Ruinen der Bombardierung von 1945 wiederaufgebaute barocke protestantische Kathedrale, Dresdens eindrucksvollstes Symbol der Auferstehung. Im Inneren sind nur Assistenzhunde zugelassen, doch der Platz und der Blick von der Brühlschen Terrasse sind jederzeit angeleint zugänglich.`,
      "Zwinger": `Ein barocker Palast aus dem 18. Jahrhundert, der ehemalige königliche Hof und heute ein Museumskomplex. Die Innenhöfe und Gärten sind für angeleinte Hunde jederzeit zugänglich; die Museen (Gemäldegalerie Alte Meister, Porzellansammlung, Mathematisch-Physikalischer Salon) lassen nur Assistenzhunde zu.`,
      "Brühlsche Terrasse": `Eine erhöhte Uferpromenade, genannt der "Balkon Europas", die zwischen der Augustusbrücke und der Carolabrücke verläuft. Tag und Nacht geöffnet, mit Treppen hinunter zu den Elbwiesen, deckt sie in einer angeleinten 20-minütigen Runde einen Großteil der berühmten Canaletto-Blick-Skyline ab.`,
      "Großer Garten": `Ein 147 Hektar großer zentraler Barockpark, 1676 angelegt. Angeleinte Hunde im gesamten Park willkommen (außer im Botanischen Garten). Ideal für einen regelmäßigen Spaziergang mitten im Zentrum, mit einer hundefreundlichen Café-Terrasse am Carolasee.`,
      "Elbwiesen": `Weite Wiesen, die beide Ufer der Elbe durch das zentrale Dresden säumen. Hunde laufen nach lokalem Brauch auf dem Grünstreifen zwischen Fluss und Radweg ohne Leine. Der Abschnitt Carolabrücke-Albertbrücke ist der breiteste.`,
      "Schlosspark Pillnitz": `Romantischer Schlosspark am östlichen Elbufer, erreichbar mit dem Raddampfer oder Bus 63. Der gesamte Park ist für angeleinte Hunde geöffnet; die Gebäude (Museum, Palmenhaus, Kamelienhaus) bleiben nur Assistenzhunden vorbehalten.`,
    },
  },
  dubai: {
    history: `Dubai, mit fast 3,5 Millionen Einwohnern die größte Stadt der Vereinigten Arabischen Emirate, erhob sich innerhalb einer einzigen Generation aus der Wüste zu einer Metropole aus Wolkenkratzern, klimatisierten Einkaufszentren und künstlich angelegten Stränden am Persischen Golf. Der Burj Khalifa, der höchste Turm der Erde, thront über einer futuristischen Innenstadt, während die Marina, die Palm-Inseln und der alte Creek die zwei Gesichter der Stadt verkörpern. Für Reisende mit Hund verlangt Dubai einen klaren, nüchternen Ansatz: Hunde sind an öffentlichen Stränden, in der U-Bahn, in Einkaufszentren, in den meisten Parks und in allen Indoor-Attraktionen verboten. Die Sommerhitze übersteigt 45 °C und verbrennt mittags die Pfotenballen. Wirklich haustierfreundliche Orte gibt es zwar (Hundecafés, ein paar Hundestrände und Hundeparks, Wüstenausflüge), doch sie bleiben begrenzt, und die Einfuhrbestimmungen sind weit strenger als ein EU-Heimtierausweis.`,
    petTips: [`Extreme Hitze von Mai bis September: Über 45 °C verbrennen Sand und Gehweg die Pfotenballen; führen Sie den Hund nur in der Morgendämmerung und am späten Abend spazieren, niemals bei vollem Tageslicht.`, `Strenges Gesetz: Hunde sind an öffentlichen Stränden, in der U-Bahn und den Straßenbahnen, in Einkaufszentren, den meisten Parks und allen Indoor-Einrichtungen verboten; Leinenpflicht gilt in der Öffentlichkeit.`, `Wirklich haustierfreundliche Orte (Hundecafés, ausgewiesene Hundestrände und Hundeparks, geführte Wüstenausflüge) sind rar: Suchen und buchen Sie diese im Voraus, improvisieren Sie nicht.`, `Führen Sie stets Wasser mit sich und erwägen Sie Pfotenschuhe; Hitzschlag und verbrannte Ballen sind hier die häufigsten tierärztlichen Sommer-Notfälle.`, `Viele Hotels akzeptieren keine Haustiere: Haustierbetreuung ist in Dubai verbreitet und gut organisiert, buchen Sie diese bei Bedarf vor der Ankunft.`],
    practicalInfo: [`Der Flughafen Dubai International (DXB) liegt 5 km vom Zentrum entfernt, einer der belebtesten der Welt; für den Haustiertransport im Frachtraum oder in der Kabine gelten je nach Airline genaue Regeln.`, `Notrufnummern der VAE: 999 (Polizei) und 998 (Rettungsdienst); 997 für die Feuerwehr.`, `Strenge Einfuhr: Eine offizielle Einfuhrgenehmigung ist erforderlich (Mikrochip, Tollwutimpfung, Antikörpertiter-Bluttest); ein EU-Ausweis allein reicht nicht, planen Sie also mehrere Wochen ein.`, `Die Hitze von Mai bis September übersteigt oft 45 °C bei hoher Küstenluftfeuchtigkeit; der Winter (November bis März, 20-28 °C) ist mit Abstand die beste Reisezeit mit Hund.`, `Moderne Tierkliniken sind vorhanden, einschließlich Notfalldiensten; ermitteln Sie bei der Ankunft eine Klinik in der Nähe Ihrer Unterkunft und speichern Sie diese.`],
    sights: {
      "Burj Khalifa & Downtown Dubai": `Der höchste Turm der Erde (828 m) thront über einer Innenstadt aus Springbrunnen und Boulevards. Haustiere sind im Turm, in der Dubai Mall und in den Indoor-Attraktionen nicht erlaubt; angeleinte Hunde werden bestenfalls auf einigen Außenpromenaden früh am Tag geduldet.`,
      "Dubai Marina & JBR": `Ein Viertel aus Türmen und Kanälen, gesäumt von einer langen, lebhaften Promenade. Angeleinte Hunde werden in den kühleren Stunden auf einigen Abschnitten des Außenwegs geduldet, bleiben aber vom JBR-Strand selbst verbannt.`,
      "Al Qudra Lakes": `Künstlich angelegte Seen im Herzen des Wüstenschutzgebiets Al Marmoom, beliebt bei Outdoor-Fans. Es ist einer der wenigen Orte, an denen angeleinte Hunde willkommen sind; kommen Sie früh, führen Sie reichlich Wasser mit und meiden Sie tagsüber den glühenden Sand.`,
      "Al Seef & Dubai Creek": `Der historische Gezeiten-Creek, gesäumt vom Al-Seef-Altstadtviertel, den Souks und den Wassertaxi-Überfahrten der Abras. Haustiere sind in den überdachten Souks oder Museen nicht erlaubt; angeleinte Hunde werden nur auf einigen Außenkaiabschnitten geduldet.`,
      "Safa Park": `Ein großer landschaftlich gestalteter Park zwischen Downtown und der Küste, mit Rasenflächen und Seen. Wie die meisten städtischen Parks Dubais verbietet er Hunde; planen Sie hier keinen Spaziergang mit Ihrem Haustier und weichen Sie auf die wenigen speziellen Hundeparks aus.`,
      "Kite Beach & public beaches": `Lange öffentliche Strände wie Kite Beach oder La Mer sind gepflegt und überwacht, aber ganzjährig für Hunde tabu. Um Ihr Haustier das Wasser genießen zu lassen, müssen Sie einen ausgewiesenen Hundestrand abseits der zentralen öffentlichen Strandabschnitte ansteuern.`,
    },
  },
  dublin: {
    history: `Dublin, auf Irisch Baile Átha Cliath, "die Stadt der Furt der Hürden", wurde im 9. Jahrhundert von den Wikingern an den Ufern der Liffey gegründet. Als Hauptstadt Irlands seit der normannischen Eroberung im 12. Jahrhundert war es sieben Jahrhunderte lang das Verwaltungszentrum der britischen Präsenz in Irland, bevor es 1922 Hauptstadt des Irischen Freistaats wurde. Heute ist Dublin eine warmherzige, lebendige Stadt, bekannt für ihre Pubs, ihre literarische Kultur (Joyce, Beckett, Wilde) und ihre legendäre Gastfreundschaft. Hunde sind in Biergärten, auf Küstenwanderungen und im Phoenix Park willkommen, einem der größten städtischen Parks Europas mit 1.750 Hektar.`,
    petTips: [`⚠️ WICHTIG: Irland verlangt eine Bandwurmbehandlung für Hunde 24-120 Stunden vor der Ankunft, und die Einreise muss über einen zugelassenen Hafen oder Flughafen erfolgen. Konsultieren Sie im Voraus Ihren Tierarzt.`, `Hunde sind in Dublins Bussen oder der DART (Vorortzug) nur in einer Transportbox zugelassen. Taxis sind in der Regel hundefreundlich, bestätigen Sie dies bei der Buchung.`, `Biergärten irischer Pubs sind fast durchweg hundefreundlich. Die Pub-mit-Hund-Kultur ist in Dublin fest etabliert.`, `Wasser, und Regen, sind in Irland eine Konstante. Packen Sie ein Handtuch ein, um Ihren Hund zu trocknen, bevor Sie ein Café oder Hotel betreten.`, `Der Temple-Bar-Markt samstags ist für Hunde geöffnet und bietet eine lebendige Atmosphäre im Herzen Dublins.`],
    practicalInfo: [`24-Stunden-Notfall-Tierarzt: UCD Veterinary Hospital, Belfield, Dublin 4, +353 1 716 6100`, `Zentrale Klinik: Clontarf Veterinary Hospital, 193 Clontarf Road, +353 1 833 3284`, `⚠️ Bandwurmbehandlung 24-120 Std. vor der Einreise nach Irland erforderlich, durchgeführt von einem zugelassenen Tierarzt.`, `Empfohlene Fähre: Irish Ferries Rosslare-Cherbourg oder Brittany Ferries Cork-Roscoff, Tiere an Bord in Kabinen oder Zwingern zugelassen.`],
    sights: {
      "Phoenix Park": `Mit 1.750 Hektar ist der Phoenix Park einer der größten eingefriedeten Stadtparks der Welt. Hunde können sich in den meisten Bereichen frei bewegen. Der Park beherbergt frei lebendes Damwild, halten Sie Ihren Hund an der Leine, wenn Sie sich ihm nähern.`,
      "Dodder River Walk": `Der Weg entlang des Flusses Dodder von Rathfarnham bis zum Hafen von Ringsend ist einer der beliebtesten Spaziergänge für Dubliner und ihre Hunde. Grün, abwechslungsreich und ganzjährig zugänglich.`,
      "Sandymount Strand": `Sandymount Strand, 3 km vom Zentrum Dublins entfernt, ist ganzjährig mit Hund zugänglich (während der Badesaison an der Leine). Bei Ebbe sind die weiten Sandflächen perfekt für einen langen Hundespaziergang.`,
      "Ranelagh & Portobello": `Ranelagh und Portobello sind Dublins hundefreundlichste Viertel. Pubs mit Biergärten, angesagte Cafés und der Grand Canal, der an Portobello entlangführt, ideal für einen späten Nachmittagsspaziergang.`,
      "Wicklow Mountains (excursion)": `Eine 40-minütige Fahrt südlich von Dublin bieten die Wicklow Mountains spektakuläres, hundefreundliches Wandern. Glendalough (zwei Gletscherseen) ist die beliebteste Sehenswürdigkeit, Hunde sind auf den Wegen erlaubt.`,
    },
  },
  dubrovnik: {
    history: `Dubrovnik, die "Perle der Adria", ist eine der meistbesuchten Städte Europas: Ihre UNESCO-gelisteten Altstadtmauern und das kristallklare Meer locken jährlich über zwei Millionen Touristen in eine Stadt mit nur 40.000 Einwohnern. Für Hundebesitzer belohnt Dubrovnik sorgfältige Planung: Die Altstadt selbst hat steile Marmorstufen und extreme Sommerhitze, doch die Umgebung bietet hundefreundliche Strände, bewaldete Hügel und die ruhigeren Elaphiten-Inseln in bequemer Fährdistanz. Die kroatische Einstellung zu Hunden in der Öffentlichkeit ist einladend, und die Adriaküste zählt zu Europas landschaftlich reizvollsten Wandergebieten.`,
    petTips: [`Die Sommerhitze ist extrem (Juli-August regelmäßig 38-40 °C). Gehen Sie nur vor 8 Uhr und nach 20 Uhr spazieren. Die Marmorpflastersteine der Altstadt speichern gefährlich viel Hitze, testen Sie sie mit der Hand, bevor Sie Ihren Hund darauf laufen lassen.`, `Die abschüssigen Straßen und engen Gassen der Altstadt sind für die meisten Hunde während der Touristensaison belastend. Wohnen Sie in Lapad oder Gruž und besuchen Sie die Altstadt früh morgens oder außerhalb der Saison.`, `Hundefreundliche Strände gibt es in der Bucht von Lapad und auf den Elaphiten-Inseln. Die meisten Hauptstadtstrände (Banje, Copacabana) haben im Sommer Haustierbeschränkungen, prüfen Sie die saisonale Beschilderung.`, `Kroatischer Satz: "Mogu li ući s psom?" ("Kann ich mit meinem Hund hereinkommen?"), Einheimische schätzen die Mühe und sagen oft ja.`, `Dubrovniks Wasser ist trinkbar, und Brunnen sind verbreitet. Führen Sie im Sommer immer zusätzliches Wasser mit, die Hitze in Kombination mit dem Gehen dehydriert Ihren Hund schnell.`],
    practicalInfo: [`Notfall-Tierarzt: Veterinarska Stanica Dubrovnik, Vukovarska ulica (+385 20 423 433), für Notfälle außerhalb der Öffnungszeiten liegt die nächste 24-Stunden-Einrichtung in Split (3,5 Std.), oder erkundigen Sie sich bei der örtlichen Polizei nach dem diensthabenden Tierarzt.`, `Anreise: Der Flughafen Dubrovnik liegt 20 km südlich. Die meisten Besucher reisen mit dem Flugzeug an. Fähren von Split, Rijeka und Italien (Jadrolinija) lassen Haustiere in Transportboxen oder mit Leine und Maulkorb an Deck zu.`, `Kroatien ist EU-Mitglied, der übliche EU-Heimtierausweis mit Mikrochip und Tollwutimpfung ist erforderlich.`, `Beste Saison für Hundebesitzer: Mai, Juni und September. Meiden Sie nach Möglichkeit Juli und August, die Kombination aus Menschenmassen, Hitze und begrenztem Zugang zu hundefreundlichen Stränden macht sie zur schwierigsten Jahreszeit.`],
    sights: {
      "Park Šuma Gradac": `Der bewaldete Park unmittelbar westlich der Altstadtmauern ist der beste Hundespaziergang im Zentrum von Dubrovnik. Schattige Pinienwege, Meerblick und eine wohltuend kühlere Temperatur machen ihn selbst im Sommer zum bevorzugten Morgenspaziergang.`,
      "Elaphiti Islands (Lopud & Šipan)": `Die autofreien Elaphiten-Inseln sind eine Offenbarung für Hundebesitzer. Lopud und Šipan haben Sandpfade, ruhige Buchten und eine winzige, ganzjährige Bevölkerung. Eine einstündige Fähre ab dem Hafen von Dubrovnik; Hunde reisen kostenlos.`,
      "Cavtat & the Konavle Valley": `Das reizvolle Küstendorf Cavtat, 20 Minuten südlich von Dubrovnik mit dem Bus, ist deutlich weniger überlaufen und hat eine schöne Uferpromenade. Das Hinterland Konavle-Tal bietet Radwege und Weinbergspaziergänge mit Hunden willkommen.`,
      "Stari Grad (Old Town Walls)": `Die Altstadtmauern sind ein UNESCO-Highlight, aber die engen, abschüssigen Straßen und die extreme Sommerhitze (40 °C+) machen sie für Hunde ungeeignet. Besuchen Sie die Mauern allein und planen Sie die Hundezeit für den frühen Morgen außerhalb der Mauern ein.`,
      "Lapad Peninsula": `Die Wohnhalbinsel Lapad, 3 km von der Altstadt entfernt, hat eine lange Uferpromenade (šetalište), pinienbeschattete Parks und mehrere hundefreundliche Strände. Die meisten haustierfreundlichen Hotels Dubrovniks befinden sich hier.`,
    },
  },
  dunkerque: {
    history: `Dünkirchen, in der Region Hauts-de-France (Nord), ist Frankreichs drittgrößter Hafen, an der Nordsee nahe der belgischen Grenze gelegen. Zwei Bilder prägten seinen Namen: die Evakuierung von 1940, als Hunderttausende alliierter Soldaten unter Beschuss von seinen Stränden geborgen wurden (Operation Dynamo), und sein riesiger vorösterlicher Karneval, einer der ausgelassensten Europas. Der Belle-Époque-Badeort Malo-les-Bains säumt einen langen Sandstrand und eine lebendige Promenade (die Digue). Das nach dem Krieg wiederaufgebaute Zentrum gruppiert sich um den Belfried Saint-Éloi, ein UNESCO-Weltkulturerbe. Im Osten bieten die Strände von Leffrinckoucke und die Dune Marchand geschützte Natur bis zur Grenze. Das Klima ist windig und mild, geprägt von der Nordsee. Frankreich, Eurozone. Notfälle: 112.`,
    petTips: [`Dünkirchens Karneval (Februar-März) zieht große Menschenmengen mit Blaskapellen, Knallkörpern und Trubel an: eine sehr laute, überfüllte Umgebung, die mit einem geräuschempfindlichen Hund komplett gemieden werden sollte. Planen Sie an diesem Tag stattdessen einen ruhigen Dünenspaziergang.`, `Wie überall an der französischen Küste verbieten überwachte Strände Hunde im Juli und August oft; außerhalb der Saison gewinnen die Promenade von Malo und der Sand viel Freiheit an der Leine zurück. Prüfen Sie die kommunale Verordnung.`, `Der Nordseewind weht häufig und kalt, besonders von Herbst bis Frühling: Ein Mantel hilft kälteempfindlichen Hunden auf der langen, exponierten Promenade.`, `Im Naturschutzgebiet Dune Marchand und Richtung Leffrinckoucke halten Sie Ihren Hund auf den Wegen an der Leine: Die brütende Dünenfauna ist geschützt, und das Verlassen der Pfade ist eingeschränkt.`, `Das Museum 1940, das Musée Portuaire und der Aufstieg des Belfrieds lassen nur Assistenzhunde zu; kombinieren Sie den Besuch mit einer Strandpause oder dem Skulpturenpark LAAC im Freien.`],
    practicalInfo: [`Die Einreise aus einem EU-Land nach Frankreich erfolgt mit dem europäischen Heimtierausweis: Mikrochip und aktuelle Tollwutimpfung. Die belgische Grenze liegt sehr nah, mit denselben EU-Regeln auf beiden Seiten.`, `Einzige europäische Notrufnummer: 112 (Polizei, Feuerwehr, Rettungsdienst). Es gibt keine nationale Tierarzt-Hotline; fragen Sie Ihre Unterkunft nach den Kontaktdaten des nächsten diensthabenden Tierarztes.`, `Fortbewegung: Das Zentrum und Malo-les-Bains sind flach und zu Fuß oder mit dem Rad leicht erkundbar; das Stadtbusnetz (in Dünkirchen kostenlos) lässt angeleinte Hunde nach Ermessen des Fahrers zu.`, `Örtliche Regel: Hunde in der Stadt an der Leine, und das Entsorgen des Kots ist Pflicht. Strandbeschränkungen gelten hauptsächlich im Juli und August; prüfen Sie die an den Strandzugängen ausgehängte kommunale Verordnung.`, `Beachten Sie den Karnevalskalender (Februar-März): Die Stadt ist dann sehr laut und überfüllt; planen Sie ruhige Ausflüge und eine Unterkunft abseits der Umzüge, wenn Ihr Hund Angst vor Lärm hat.`],
    sights: {
      "Plage et digue de Malo-les-Bains": `Der Belle-Époque-Badeort Malo-les-Bains säumt seine bunten Villen entlang eines riesigen Sandstrands und einer lebendigen Promenade (der Digue). Angeleinte Hunde sind auf der Digue ganzjährig willkommen; auf dem Sand gelten die französischen Regeln mit Sommerbeschränkungen und viel Freiheit außerhalb der Saison.`,
      "Musée Dunkerque 1940 Operation Dynamo": `In den alten befestigten Bastionen untergebracht, zeichnet dieses Museum die Evakuierung von 1940 mit Karten, Uniformen und militärischem Gerät nach. Im Inneren sind nur Assistenzhunde zugelassen; der Park und die Wehrmauern um das Museum können angeleint begangen werden, ebenso die nahe Uferpromenade.`,
      "Beffroi de Saint-Éloi": `Dieser Backsteinbelfried aus dem 15. Jahrhundert, als einer der Belfriede Belgiens und Frankreichs ein UNESCO-Weltkulturerbe, überragt das wiederaufgebaute Zentrum. Der Aufstieg und das Innere sind für Hunde nicht zugänglich, doch der Platz und die Fußgängerstraßen darum lassen sich leicht angeleint begehen.`,
      "LAAC et jardin de sculptures": `Das Lieu d'Art et Action Contemporaine ist von einem weitläufigen, offenen und kostenlosen Landschaftsskulpturengarten umgeben, mit Rasenhügeln und monumentalen Kunstwerken. Angeleinte Hunde sind im Außenpark willkommen; nur die Innengalerien des Museums bleiben ihnen verschlossen.`,
      "Dune Marchand et plage de Leffrinckoucke": `Richtung belgische Grenze schützt das Naturschutzgebiet Dune Marchand einen wilden Dünengürtel, fortgesetzt vom Strand von Leffrinckoucke. Angeleinte Hunde sind auf den Wegen erlaubt, um die brütende Fauna nicht zu stören; für den Strand gelten Frankreichs saisonale Regeln, außerhalb der Saison freier.`,
      "Port de Dunkerque": `Die Hafenfront, vom Môle 1 bis zum Musée Portuaire, säumt Becken, Trawler und die imposante Dreimaster-Duchesse Anne, die am Kai vertäut liegt. Die Kais und Außenwege werden angeleint begangen; die Museumsinnenräume und Schiffsführungen lassen nur Assistenzhunde zu.`,
    },
  },
  dusseldorf: {
    history: `Düsseldorf, seit 1946 Landeshauptstadt von Nordrhein-Westfalen, hat sich als eines der führenden Finanz- und Messezentren Deutschlands etabliert (Sitz der Eurex Clearing, des Energiekonzerns E.ON und Austragungsort der weltgrößten Bootsmesse, boot Düsseldorf). Das mittelalterliche Dorf des 13. Jahrhunderts entwickelte sich ab dem 19. Jahrhundert zu einem der bedeutendsten Kunstzentren Europas, die Kunstakademie bildete Joseph Beuys, Anselm Kiefer und Andreas Gursky aus. Die 1804 eröffnete Königsallee ist heute die teuerste Luxusmeile auf dem europäischen Festland. Die Stadt beherbergt zudem die größte japanische Gemeinschaft auf dem europäischen Festland (8.000 Daueraufenthalter, das 'Klein-Tokio' rund um die Immermannstraße). Für Reisende mit Hund ist Düsseldorf eine von Deutschlands praktischsten Städten: 21 offizielle eingezäunte Hundewiesen, hundefreundliche U-Bahnen und Straßenbahnen der Rheinbahn, zwei offizielle Seebadezonen (Unterbacher See und Elbsee), eine Hausbrauerei-Kultur (Schumacher, Füchschen, Uerige, Schlüssel), die Hunde das ganze Jahr über drinnen akzeptiert, und die große, rund um die Uhr geöffnete Tierärztliche Klinik in Stockum.`,
    petTips: [`Düsseldorf betreibt 21 offizielle eingezäunte Hundewiesen: Dies sind die einzigen Orte im Stadtgebiet, an denen Freilauf ohne Leine legal ist. Überall sonst ist die Leine Pflicht (35 €+ Bußgeld).`, `Rheinbahn (U-Bahn und Straßenbahnen): kleine Hunde in Transportboxen kostenlos; große Hunde benötigen ein Ticket zum Kindertarif, angeleint und mit Maulkorb, falls vom Personal verlangt.`, `Unterbacher See: zwei offizielle Hundebadestellen mit Schwimmen und Freilauf. Der Hauptstrand Strandbad Nord lässt nur Assistenzhunde zu.`, `24-Stunden-Notfall-Tierarzt: Tierärztliche Klinik Düsseldorf, Niederrheinstraße 312, Stockum, +49 211 4 35 14 0. Speichern Sie die Nummer vor der Ankunft.`, `Listenhunde: Das nordrhein-westfälische Landeshundegesetz schränkt bestimmte Rassen ein (Pit Bull, American Staffordshire, Bullterrier usw.), prüfen Sie dies vor der Reise, wenn Sie eine dieser Rassen besitzen.`],
    practicalInfo: [`Der Flughafen Düsseldorf (DUS) liegt 8 km vom Zentrum entfernt, S-Bahn S11 alle 20 Min., 13 Minuten, oder SkyTrain plus U70/U78/U79 zum Zentrum. Angeleinte Hunde zu Rheinbahn-Tarifen.`, `Deutsche Bahn ICE Düsseldorf-Köln 25 Min., ICE Düsseldorf-Frankfurt 1 Std. 25 Min., ICE Düsseldorf-München 4 Std. 30 Min. Große Hunde zu 50 % des Erwachsenenpreises; kleine Hunde in Transportboxen kostenlos.`, `boot Düsseldorf (weltgrößte Bootsmesse, Ende Januar) und die Drupa (Druckmesse, alle 4 Jahre) füllen die Hotels, buchen Sie 2 Monate im Voraus oder meiden Sie diese Wochen mit Hund.`, `Deutsche Tierarztgebühren: routinemäßige Konsultation etwa 50-70 €; 24-Stunden-Notfall in Stockum 150-250 €. EU-Tierkrankenversicherung akzeptiert, englischsprachige Einzelrechnung auf Anfrage.`, `Karneval (die Tage vor der Fastenzeit, Februar-März): empfindliche Hunde sollten die Altstadt am Rosenmontag, Altweiber Donnerstag und Veilchendienstag meiden, extremer Lärm und Menschenmassen.`],
    sights: {
      "Hofgarten": `Deutschlands erster öffentlicher Park (1769), 28 Hektar englischer Landschaftsrasen im Herzen Düsseldorfs zwischen der Königsallee und dem Rhein. Angrenzende Hundewiese ohne Leine am östlichen Rand.`,
      "Medienhafen": `Ein regenerierter ehemaliger Frachthafen, weltbekannt für Frank Gehrys drei Neuer-Zollhof-Gebäude. Fußgängerkai vollständig für angeleinte Hunde geöffnet.`,
      "Rheinuferpromenade": `2 km autofreie Promenade am rechten Rheinufer, zwischen Oberkasseler Brücke und Landtag, vorbei an der Altstadt und dem Schlossturm. Angeleinte Hunde willkommen.`,
      "Königsallee": `Baumgesäumter Luxusboulevard mit zentralem Kanal. Angeleinte Hunde auf der gesamten Länge willkommen; Luxusboutiquen lassen nur Assistenzhunde zu, doch die Cafés auf der Westseite sind hundefreundlich.`,
      "Unterbacher See": `83 Hektar großer See im Südosten, mit zwei offiziellen Hundebadestellen. Freilauf und Schwimmen innerhalb der markierten Zonen erlaubt (West- und Nordufer).`,
      "Volksgarten": `70 Hektar großer Landschaftspark südlich des Zentrums, mit zwei Teichen und einer großen eingezäunten Hundewiese nahe dem Eingang Auf'm Hennekamp.`,
    },
  },
  edinburgh: {
    history: `Edinburgh ist eine Stadt, die Geschichte atmet. Auf vulkanischem Fels erbaut, gekrönt von seiner Burg (11. Jahrhundert), war es die Hauptstadt des Königreichs Schottland und der Geburtsort der schottischen Aufklärung. Seine mittelalterliche Altstadt und die georgianische Neustadt des 18. Jahrhunderts sind gemeinsam als UNESCO-Weltkulturerbe eingetragen. Doch Edinburgh ist auch eine zutiefst hundefreundliche Stadt: Hunde sind in den meisten Pubs, auf den Hügeln des Arthur's Seat, in öffentlichen Gärten und in der Mehrheit der Cafés zugelassen. Die britische Tradition der Hunde in Pubs ist hier tägliche Realität, und Schottland ist neben Deutschland das haustierfreundlichste Land Europas.`,
    petTips: [`⚠️ WICHTIG: Großbritannien akzeptiert nach dem Brexit den EU-Heimtierausweis nicht mehr. Für die Einreise nach Großbritannien ist ein Animal Health Certificate (AHC) erforderlich. Buchen Sie 10 Tage vor der Abreise einen Tierarzttermin.`, `Hunde sind praktisch in allen schottischen Pubs willkommen, es ist eine nationale Tradition. Achten Sie am Eingang auf das Schild "Dogs Welcome".`, `Die Stena-Line- oder P&O-Fähre von Calais/Dünkirchen nach Dover ist die beste Option, um mit einem großen Hund vom Kontinent aus zu reisen.`, `Edinburgh ist selbst im Sommer oft windig und kühl, packen Sie eine Decke oder einen wasserdichten Mantel für Ihren Hund ein.`, `The Meadows (großer Park südlich des Zentrums) hat bei Einheimischen beliebte Freilaufzonen.`],
    practicalInfo: [`24-Stunden-Notfall-Tierarzt: Dick Vet Emergency Service, Easter Bush, Roslin, Midlothian, +44 131 650 7650`, `Zentrale Klinik: Vets4Pets Edinburgh, 12 Fountain Park, +44 131 443 7474`, `⚠️ EU-Heimtierausweis in Großbritannien nicht gültig, Animal Health Certificate (AHC) erforderlich, ausgestellt von einem zugelassenen Tierarzt.`, `Empfohlene Fähre: DFDS Dover-Calais oder Stena Line Fishguard-Rosslare (Irland), Tiere an Bord zugelassen.`],
    sights: {
      "Arthur's Seat": `Der erloschene Vulkan im Herzen Edinburghs (251 m) ist ein außergewöhnlicher Spielplatz für Hunde. Wege sind offen, und Hunde können in den meisten Bereichen ohne Leine laufen. Der Blick über die Stadt vom Gipfel aus ist spektakulär.`,
      "Water of Leith": `Der Fluss, der Edinburgh durchquert, wird von einem 12 km langen Fußweg vom Stadtzentrum bis Leith gesäumt. Hunde können in den meisten Abschnitten ohne Leine laufen. Eine grüne, ruhige Route fernab des touristischen Trubels.`,
      "Royal Mile & Vieille Ville": `Die Hauptstraße der mittelalterlichen Altstadt ist mit Hund zugänglich. Die meisten seitlichen Closes (Gassen) eignen sich hervorragend zum Erkunden mit einem Haustier. Edinburgh Castle lässt keine Tiere im Inneren zu.`,
      "Holyrood Park": `Der königliche Park rund um Arthur's Seat (263 ha) ist vollständig mit Hund zugänglich. Die Lochans (kleine Seen), die Klippen von Salisbury Crags und weite Wiesen machen ihn zu einem der schönsten städtischen Parks Europas.`,
      "Stockbridge & Dean Village": `Stockbridge ist Edinburghs charmantestes und hundefreundlichstes Viertel. Sonntagsmarkt, einladende Pubs, Metzgereien und Feinkostläden, die stets ein Leckerli für Ihren Hund bereithalten. Dean Village darunter ist ein architektonisches Juwel am Wasser.`,
    },
  },
  essaouira: {
    history: `Essaouira ist eine Hafenstadt an der Atlantikküste Marokkos, umgeben von wind-umtosten weiß-blauen Festungsmauern. In der Form, wie sie heute erscheint, im 18. Jahrhundert auf dem Gelände des alten portugiesischen Handelspostens Mogador errichtet, ist ihre befestigte Medina heute wegen ihres regelmäßigen Grundrisses und ihrer dem Ozean zugewandten Bastionen UNESCO-Weltkulturerbe. Die Skala de la Ville, eine lange, mit Kanonen bestückte Artillerieplattform, blickt auf die Wellen, während der Fischereihafen seine blauen Boote und Netze aufreiht. Essaouira, wegen der fast ununterbrochen wehenden Passatwinde "Stadt des Windes" genannt, ist kühler als das Landesinnere und bei Surfern und Kitesurfern entlang ihres weiten Strandes beliebt. Sie ist zudem die Hauptstadt der Gnaoua-Musik, jeden Sommer mit einem großen Festival gefeiert, sowie ein Tor zu den Argan-Öl-Kooperativen und dem benachbarten Dorf Diabat.`,
    petTips: [`Die starken Passatwinde, denen Essaouira ihren Beinamen Stadt des Windes verdankt, wehen im Frühling und Sommer meist nachmittags und wirbeln Sand auf: Führen Sie den Hund morgens spazieren, schützen Sie seine Augen und führen Sie Wasser mit, öffentliche Brunnen sind rar.`, `Streunende Hunde sind in Marokko verbreitet: Halten Sie Ihren Hund angeleint, auf dem aktuellen Stand seiner Tollwutimpfung, und vermeiden Sie Konfrontationen, besonders rund um den Hafen und die Medina.`, `Am Strand werden Hunde abseits des belebtesten zentralen Abschnitts im Allgemeinen geduldet, prüfen Sie dies aber vor Ort und halten Sie sie in der Nähe der Cafés und der Festungsmauern angeleint.`, `Marokko liegt außerhalb der Europäischen Union: Für die Rückkehr in die EU organisieren Sie rechtzeitig eine gültige Tollwutimpfung und einen Tollwut-Antikörpertitertest, der Vorgang dauert mehrere Wochen.`, `Respektieren Sie lokale Bräuche: Halten Sie den Hund in der Nähe von Moscheen, Essensständen und Gebetsbereichen der Medina fest und diskret und vermeiden Sie Tagesausflüge ins Landesinnere während der heißesten Stunden.`],
    practicalInfo: [`Notrufnummern in Marokko: Polizei 19, Rettungsdienst und SAMU 15, und 112 funktioniert ebenfalls von einem Mobiltelefon aus.`, `Essaouira hat keinen Bahnhof, die Anreise erfolgt auf der Straße ab Marrakesch (etwa 2 Std. 30 Min.) oder Agadir (etwa 3 Std.) mit Bus oder geteiltem Grand Taxi.`, `Nächster Flughafen: Essaouira-Mogador (ESU), etwa 15 km entfernt, oder Marrakesch Menara (RAK), etwa 190 km.`, `Halbtrockenes atlantisches Klima, mild und windig das ganze Jahr über, merklich kühler als das marokkanische Landesinnere, mit starken Passatwinden im Frühling und Sommer.`, `Fragen Sie in Ihrer Unterkunft nach der nächsten Tierklinik und überprüfen Sie jede Telefonnummer vor Ort, bevor Sie sich darauf verlassen.`],
    sights: {
      "Medina d'Essaouira": `Die UNESCO-gelistete befestigte Medina mit ihren weißen Gassen, monumentalen Toren und ihren dem Atlantik zugewandten Festungsmauern. Sie wird angeleint begangen, wobei der Hund in den belebten Souks nah gehalten und Menschenmenge und Stände respektiert werden.`,
      "Skala de la Ville": `Die lange, mit Bronzekanonen bestückte Artillerieplattform entlang der nördlichen Festungsmauern, mit großartigem Blick auf den Ozean und die Purpuraires-Inseln. Man begeht sie angeleint, sollte aber auf Wind und Gischt achten, die die Bastion umspülen.`,
      "Port de pêche": `Der lebendige Hafen, in dem die berühmten blauen Boote aufgereiht liegen, inmitten der Fischversteigerung, der Netzflickerei und dem Kommen und Gehen der Möwen. Die Kais werden angeleint im Freien begangen, doch der Ort ist laut und überfüllt, halten Sie den Hund also nahe den Fischständen gut fest.`,
      "Plage d'Essaouira": `Der weite windgepeitschte Strand, der sich nach Süden erstreckt, ein Paradies für Kitesurfen und Windsurfen. Hunde werden abseits des belebtesten zentralen Abschnitts im Allgemeinen geduldet, halten Sie sie angeleint und prüfen Sie dies vor Ort, da die Regeln je nach Saison variieren.`,
      "Diabat et Borj El Baroud": `Das Dorf Diabat, südlich des Flusses Ksob, und die sandverschütteten Ruinen von Borj El Baroud, einem alten Küstenfort, das die Legende mit Jimi Hendrix verbindet. Man erreicht es zu Fuß oder zu Pferd entlang von Strand und Dünen, angeleint, fernab des Trubels der Medina.`,
      "Coopératives d'argan": `Die Arganöl-Kooperativen in der Umgebung, wo Frauen die Nüsse dieses im Südwesten Marokkos endemischen Baumes von Hand knacken und pressen. Aus lebensmittelhygienischen Gründen sind Hunde in den Produktionswerkstätten nicht zugelassen, lassen Sie sie also während des Besuchs im Schatten.`,
    },
  },
  estepona: {
    history: `Estepona, ein Ort mit rund 70.000 Einwohnern an der Costa del Sol in der Provinz Málaga, hat sich als "Garten der Costa del Sol" neu erfunden und seine Altstadt mit Tausenden hängenden Blumentöpfen, handbemalten Wandmalereien und gefegten Kopfsteinpflastergassen gefüllt, was sie zu einem der reizvollsten Orte Andalusiens für einen Spaziergang macht. Dahinter erhebt sich die pinienbewachsene Sierra Bermeja, und entlang der Küste verläuft ein palmengesäumter Paseo Marítimo, der Strände, den Yachthafen und den Fischereihafen verbindet. Für Hundebesitzer sind die begehbare, leinenfreundliche Altstadt und die lange Uferpromenade die Attraktion, auch wenn das Orchidarium und der nahe gelegene Safaripark Selwo keine Haustiere zulassen. Die beiden Dinge, die man einplanen sollte, sind die Sommerhitze an der Costa del Sol und die saisonalen Strandregeln: Estepona hat keinen eigenen offiziellen Hundestrand, sodass Besitzer nach Westen zur Punta Paloma in Casares oder nach Osten zu Marbellas Hundestränden fahren.`,
    petTips: [`Estéponas Stadtstrände verbieten Hunde während der Badesaison (1. Juni bis 30. September); da es keinen offiziellen Hundestrand im Ort gibt, fahren Sie nach Westen zur Punta Paloma in Casares oder nach Osten zu Marbellas Hundestränden El Pinillo oder Ventura del Mar.`, `Die Sommerhitze an der Costa del Sol ist intensiv: Gehen Sie früh oder nach Sonnenuntergang spazieren, führen Sie Wasser mit und testen Sie Pflaster und Sand mit der Hand, bevor Sie Ihren Hund darauf laufen lassen.`, `Die Altstadt lässt sich wunderbar an der Leine erkunden, doch das Orchidarium und der Safaripark Selwo lassen keine Haustiere zu, planen Sie also für diese Stopps eine Begleitperson oder eine schattige Pause ein.`, `Leishmaniose ist an dieser Küste endemisch, fragen Sie einen örtlichen Tierarzt von Frühling bis Herbst, wenn Sandmücken aktiv sind, nach einem Repellent-Halsband oder Spot-on.`, `Halten Sie Hunde auf der Promenade und in der Altstadt angeleint, führen Sie Kotbeutel mit sich (Bußgelder drohen), und bedenken Sie, dass potenziell gefährliche Rassen (PPP) in der Öffentlichkeit einen Maulkorb tragen und lizenziert sein müssen.`],
    practicalInfo: [`EU-Heimtierausweis und eine gültige Tollwutimpfung sind beim Check-in in jedem haustierfreundlichen Hotel erforderlich.`, `Leinenpflicht gilt auf der Promenade, in der Altstadt und an den Stränden; potenziell gefährliche Rassen (PPP) müssen in der Öffentlichkeit einen Maulkorb tragen und lizenziert sein.`, `Das Entsorgen von Hundekot ist Pflicht und wird mit Bußgeld belegt; die Stadt patrouilliert die Promenade und die Altstadtstraßen.`, `Kein Bahnhof: Die meisten Besitzer reisen über den Flughafen Málaga (etwa 85 km) oder Gibraltar (etwa 45 km) an und fahren mit dem Auto weiter, obwohl die häufigen Avanza-Busse entlang der A-7 kleine Haustiere in einer Transportbox akzeptieren.`, `Geprüfte Tierärzte: Clínica Veterinaria Puerto Alto (nahe dem Yachthafen, +34 951 977 118, 24-Stunden-Notfalltelefon) und Clínica Veterinaria Estepona (C/ Monterroso 51, +34 951 518 244); allgemeine Notfälle 112.`],
    sights: {
      "Casco Antiguo": `Estéponas makellose Altstadt, in der Tausende blau-weiße Blumentöpfe weiß getünchte Gassen säumen und riesige handbemalte Wandbilder ganze Fassaden in Open-Air-Kunst verwandeln. Angeleinte Hunde sind in den Fußgängerstraßen, auf den Plätzen und den meisten Terrassen willkommen.`,
      "Orquidario de Estepona": `Ein eindrucksvoller Kuppel-Botanischer Garten in der Altstadt, der eine der größten Orchideensammlungen Europas unter Glas beherbergt, mit Innenwasserfällen und Tausenden tropischer Pflanzen. Haustiere sind im Inneren nicht erlaubt, besuchen Sie ihn also mit einer Begleitperson, die draußen mit dem Hund warten kann.`,
      "Paseo Marítimo": `Die lange, palmengesäumte Uferpromenade, die sich über die gesamte Länge Estéponas erstreckt und die Strände, den Yachthafen und den Fischereihafen verbindet. Es ist ein leichter, größtenteils flacher Spaziergang mit angeleintem Hund, am besten in der Kühle des frühen Morgens oder Abends.`,
      "Playa del Cristal": `Eine kleine, geschützte Bucht westlich des Hafens, beliebt wegen ihres ruhigen, klaren Wassers und ein Favorit für Spaziergänge außerhalb der Saison. Hunde werden außerhalb der Badesaison angeleint geduldet, obwohl wie überall an der Küste sommerliche Strandverbote gelten.`,
      "Selwo Aventura": `Ein großer Safaripark in den Hügeln direkt östlich der Stadt, Heimat Hunderter Tiere in nachgebildeten afrikanischen und asiatischen Lebensräumen. Es ist ein Tagesausflug, lässt aber keine Haustiere zu, ist also kein hundefreundlicher Plan.`,
      "Sierra Bermeja": `Das pinienbewachsene, eisenrote Gebirge, das sich hinter Estepona erhebt, durchzogen von Forstwegen und Aussichtspunkten mit Blick auf das Meer und an klaren Tagen bis nach Gibraltar und Afrika. Angeleinte Wanderungen hier sind in den kühleren Monaten am besten, mit Wasser für die Anstiege.`,
    },
  },
  ericeira: {
    history: `Ericeira ist ein Fischerdorf auf den Klippen der Atlantikküste, in der Gemeinde Mafra, etwa vierzig Kilometer nordwestlich von Lissabon. Seine blau umrandeten weißen Häuser fallen zum kleinen, noch aktiven Hafen von Baleia hin ab, während die Aussichtspunkte auf ein oft raues Meer blicken. 2011 wurde Ericeira Europas erstes World Surfing Reserve, ein Status, der eine Reihe berühmter Wellen schützt, von Ribeira d'Ilhas bis Praia do Norte. Der Ort bewahrt eine starke maritime Identität: Gassen mit Azulejo-Kacheln gepflastert, Fischauktionen und Meeresfrüchte-Restaurants. Im Landesinneren erinnert der riesige Nationalpalast von Mafra an die königliche Vergangenheit der Region. Wer mit Hund hierher reist, muss die Gezeiten und die starke atlantische Dünung, den Nortada-Wind und die sommerlichen Strandverbote einplanen.`,
    petTips: [`Sommerliches Strandverbot: Von Juni bis September sind Hunde an überwachten Stränden in Portugal wie São Sebastião oder Praia do Sul verboten, weichen Sie auf die wilderen nördlichen Strände aus, die außerhalb der Badezeiten geduldet werden.`, `Ericeiras Atlantik ist für seine heftige Brandung und Strömungen bekannt: Lassen Sie Ihren Hund an den Surfbreaks niemals ans Wasser und beobachten Sie am Fuß der Klippen die steigende Flut.`, `Der Nortada-Wind weht an Sommernachmittagen stark und wirbelt Sand auf: Bevorzugen Sie Morgenspaziergänge und führen Sie Wasser mit, Hunde vertragen in die Augen gewehten Sand schlecht.`, `Die portugiesische Sonne ist von Mai bis September intensiv, gehen Sie früh oder abends spazieren, testen Sie Sand und Pflaster mit der Hand und planen Sie Schatten ein, die Azulejo-Gassen bleiben kühler.`, `Viele Meeresfrüchte-Restaurants heißen einen Hund auf der Terrasse willkommen, halten Sie ihn im Ort angeleint und entsorgen Sie seinen Kot, das schreiben die portugiesischen kommunalen Regeln vor.`],
    practicalInfo: [`Einzige Notrufnummer in Portugal und in ganz Europa: 112.`, `Ericeira hat keinen Bahnhof, die Anreise erfolgt mit dem Auto oder Bus ab Lissabon (etwa 1 Stunde) über Mafra.`, `Nächster Flughafen: Lissabon Humberto Delgado (LIS), etwa 50 km entfernt.`, `Mildes atlantisches Klima: Sommer, durch den Meereswind gemäßigt, regnerische Winter, Frühling und Sommer sind für Reisen mit Hund am angenehmsten.`, `Fragen Sie in Ihrer Unterkunft nach der nächsten diensthabenden Tierklinik (Ericeira oder Mafra), bevor Sie ankommen.`],
    sights: {
      "Centro histórico e miradouros": `Das Herz des Dorfes, seine gepflasterten Gassen und blumengeschmückten Balkone öffnen sich zu Aussichtspunkten mit Blick auf den Atlantik. Alles wird angeleint begangen, und die Terrassen an den Plätzen heißen einen Hund gerne beim Sonnenuntergang über dem Ozean willkommen.`,
      "Porto da Baleia": `Der kleine, noch arbeitende Fischereihafen unterhalb der Klippen, wo bunte Boote die Slipanlage hinaufgezogen werden und der Tagesfang verkauft wird. Die Kais und der angrenzende Strand werden angeleint begangen, zwischen Reusen und Netzen.`,
      "Ribeira d'Ilhas": `Der berühmteste Strand des World Surfing Reserve, eine lange rechtsbrechende Welle, die internationale Wettkämpfe austrägt. Wilder und windiger, duldet er außerhalb der sommerlichen Badezeiten oft angeleinte Hunde, doch Vorsicht vor Brandung und starken Strömungen.`,
      "Praia de São Sebastião": `Einer der belebtesten Stadtstrände, goldener, von Felsen geschützter Sand, bei Familien beliebt. Von Juni bis September sind Hunde verboten, wie an den meisten überwachten Stränden Portugals, wechseln Sie also zu den wilderen nördlichen Stränden oder wandern Sie stattdessen die Klippen-Aussichtspunkte entlang.`,
      "Ruas de azulejos": `Die mit Azulejos bedeckten Fassaden und Gassen, den blau-weißen bemalten Kacheln, die für Portugal typisch sind und dem Dorf seinen Charme verleihen. Der Spaziergang erfolgt angeleint, im relativen Schatten der niedrigen Häuser, fernab der Strandsonne.`,
      "Palácio Nacional de Mafra": `Etwa zehn Kilometer im Landesinneren, der riesige barocke Palast-Konvent von Mafra, ein Weltkulturerbe, mit seiner Basilika und der monumentalen Bibliothek. Hunde sind im Inneren nicht erlaubt, können aber angeleint im weitläufigen bewaldeten Park der nahen Tapada spazieren geführt werden.`,
    },
  },
  evora: {
    history: `Évora, in römischer Zeit als Ebora Liberalitas Iulia gegründet (1. Jahrhundert v. Chr.), bewahrt einen dem Kaiser Augustus gewidmeten römischen Tempel, den am besten erhaltenen der Iberischen Halbinsel. Nacheinander westgotisch, maurisch (Yābora, 715-1166) und christlich, war Évora im 15. und 16. Jahrhundert königliche Residenz und beherbergte 1559 Portugals zweite Universität. Heute Hauptstadt des Alentejo (54.000 Einwohner) und seit 1986 UNESCO-Weltkulturerbe, ist es ein Freilichtmuseum, in dem der römische Tempel, die gotische Kathedrale, Renaissance-Paläste und die unheimliche Capela dos Ossos (5.000 Skelette säumen die Wände) auf 1,1 km² Centro Histórico nebeneinander bestehen. Für Reisende mit Hund ist Évora eines der zugänglichsten UNESCO-Reiseziele Europas: begehbares Centro Histórico in 20 Minuten, standardmäßig haustolerante Alentejano-Tasca-Kultur, Korkeichen-Montado-Wege direkt außerhalb der Mauern und direkte CP-Bahnverbindung ab Lissabon in 1 Std. 30 Min.`,
    petTips: [`Die Alentejano-Tasca-Kultur heißt Hunde standardmäßig willkommen, etwa 80 % der Cafés und Tabernas in Évora akzeptieren angeleinte Hunde ganzjährig auf der Terrasse.`, `Trevo-Busse plus kostenloser Innenstadt-Shuttle: angeleinte Hunde im Shuttle des Centro Histórico erlaubt; mittelgroße und große Hunde in regulären Bussen benötigen Maulkorb plus halben Fahrpreis.`, `CP-Intercidades-Züge Lissabon-Évora in 1 Std. 30 Min.: kleine Hunde in Transportbox kostenlos, größere zum halben Fahrpreis plus Maulkorb.`, `24-Stunden-Notfall-Tierarzt: Hospital Veterinário Évora, Estrada da Circunvalação 25 (+351 266 745 050), 10 Minuten mit dem Auto vom Zentrum entfernt.`, `Hohe Sommerhitze (35-40 °C Juli-August), beschränken Sie Hundespaziergänge auf die Zeit vor 9 Uhr und nach 19 Uhr; die steinernen Stadtmauern strahlen bis 22 Uhr Hitze ab.`],
    practicalInfo: [`Portugal ist EU- und Schengen-Mitglied: EU-Heimtierausweis plus gültige Tollwutimpfung plus ISO-Mikrochip genügt aus jedem EU-Land.`, `Direkte CP-Züge: Lissabon Oriente 1 Std. 30 Min. (Intercidades), Beja 45 Min., Faro 3 Std. 30 Min., kleine Hunde in Transportbox kostenlos, größere zum halben Fahrpreis plus Maulkorb.`, `Flughafen Lissabon (LIS) 1 Std. 30 Min. mit direktem CP-Zug plus 30 Min. Aerobus-Shuttle, der nächstgelegene haustierfreundliche internationale Knotenpunkt.`, `Währung: Euro. Tagesbudget haustierfreundlich: 50-75 €/Tag ohne Unterkunft, eines der niedrigsten in Südeuropa (auf Augenhöhe mit Faro).`, `Zu meidende Feste mit einem ängstlichen Hund: Feira de São João (Juni, Jahrmarkt), Festas de São Pedro (Juni), Karwochen-Prozessionen (April).`],
    sights: {
      "Templo Romano de Évora": `2.000 Jahre alter, Augustus gewidmeter römischer Tempel, der am besten erhaltene der Iberischen Halbinsel. Außenansicht rund um die Uhr, mit angeleinten Hunden zugänglich.`,
      "Praça do Giraldo": `Zentraler Hauptplatz, Brunnen, Arkaden aus dem 16. Jahrhundert, Café-Terrassen ringsum. Rund um die Uhr geöffnet, hundefreundlich.`,
      "Cromeleque dos Almendres": `Größter Megalith-Steinkreis der Iberischen Halbinsel (95 aufrechte Steine, ca. 6.000 v. Chr.), 7.000 Jahre älter als Stonehenge. 15 km westlich, mit angeleinten Hunden zugänglich.`,
      "Évora City Walls": `Mittelalterliche Stadtmauern aus dem 14. bis 17. Jahrhundert, die das Centro Histórico umgeben, 4 km haustierfreundlicher Spaziergang mit angeleinten Hunden.`,
      "Jardim Público": `3 Hektar großer zentraler Hauptgarten, pinienbeschattete Alleen, ruinöser Palast von Dom Manuel, Zierteiche. Mit angeleinten Hunden zugänglich.`,
      "Lago Alqueva": `Europas größter Stausee (250 km²), 50 Minuten östlich, Wasserqualität Klasse A, ganzjährige Hundestrände bei Monsaraz und Mourão.`,
    },
  },
  falmouth: {
    history: `Falmouth wuchs um einen der tiefsten natürlichen Häfen der Welt, am geschützten Carrick Roads, wo der River Fal auf das Meer trifft. Es erlangte im 17. Jahrhundert als Royal-Mail-Paketschiffhafen Bedeutung, der Postschiffe über den Atlantik schickte, und Heinrich VIII. hatte die Hafeneinfahrt bereits mit Pendennis Castle bewacht. Heute ist es eine lebhafte Hafen- und Universitätsstadt, berühmt für Segeln, das National Maritime Museum und eine Reihe von Sandstränden direkt unterhalb des Ortes. Für einen Hund ist es einer der einfachsten Ausgangsorte Cornwalls: Der Zug der Maritime Line fährt kostenlos mit Hund ins Zentrum, Pendennis Castle heißt Hunde an der Leine im Inneren willkommen, die Fähre nach St Mawes nimmt sie kostenlos mit, und es gibt sogar einen 24-Stunden-Notfall-Tierarzt im Ort. Die wichtigsten Dinge, die man einplanen sollte, sind die sommerlichen Hundeverbote an den Stränden Gyllyngvase, Swanpool, Castle Beach und Maenporth sowie für EU-Besucher das seit dem Brexit erforderliche GB Animal Health Certificate.`,
    petTips: [`Sunny Cove (Arthur's Beach), zwischen Swanpool und Maenporth, ist das ganze Jahr über 24 Stunden für Hunde geöffnet, sodass ein Hund selbst im Hochsommer immer einen Strand hat.`, `Sommerliche Strandverbote gelten nur von 10 bis 18 Uhr: Gyllyngvase vom 15. Mai bis 30. September und Swanpool, Castle Beach und Maenporth vom 1. Juli bis 31. August; Bußgelder des Cornwall Council betragen 100 Pfund. Gehen Sie vor 10 Uhr oder nach 18 Uhr an den Stadtstränden spazieren.`, `Der Zug der Maritime Line fährt von Truro nach Falmouth mit Hunden kostenlos (bis zu zwei pro Fahrgast, an der Leine), und die Fähre nach St Mawes nimmt Hunde kostenlos mit.`, `Pendennis Castle ist ungewöhnlich hundefreundlich und heißt Hunde an der Leine im Inneren der Gebäude und auf dem Gelände willkommen, es ist also eine seltene Regentag-Option mit Hund.`, `Falmouth hat einen 24-Stunden-Notfall-Tierarzt im Ort, Rosemullion Veterinary Hospital / MiNightVet an der Bickland Water Road (+44 1326 313991). Allgemeiner Notruf 999 oder 112.`],
    practicalInfo: [`Einreise nach Großbritannien nach dem Brexit: Großbritannien akzeptiert den EU-Heimtierausweis nicht; Hunde benötigen ein GB Animal Health Certificate (innerhalb von 10 Tagen ausgestellt), einen Mikrochip, eine Tollwutimpfung und eine Bandwurmbehandlung 24 bis 120 Stunden vor der Ankunft.`, `Anreise: Der Zug der Maritime Line fährt ab der Hauptstrecke in Truro nach Falmouth mit Hunden kostenlos; der Flughafen Newquay (NQY) ist der nächstgelegene, etwa eine Stunde mit dem Auto entfernt.`, `Fortbewegung: Das zentrale Falmouth ist flach und begehbar, und die hundefreundliche Fähre nach St Mawes sowie Enterprise Boats erkunden den Fal; im Sommer sind Parkplätze begrenzt.`, `Wetter: mildes ozeanisches Klima mit einigen der mildesten Winter Großbritanniens (9-10 °C), warme, aber nicht heiße Sommer (18-19 °C) und eine oft windige Küste. Frühling und Herbst sind ideal.`, `Nützliche Nummern: allgemeiner Notruf 999 oder 112; 24-Stunden-Tierarzt im Ort Rosemullion Veterinary Hospital / MiNightVet Falmouth +44 1326 313991.`],
    sights: {
      "Gyllyngvase Beach": `Falmouths Hauptstrand, ein weiter Halbmond aus goldenem Sand an der Küste unterhalb des Ortes. Hunde vom 15. Mai bis 30. September zwischen 10 und 18 Uhr verboten; davor und danach sind sie willkommen.`,
      "Sunny Cove (Arthur's Beach)": `Eine kleine, geschützte Sand-Kies-Bucht am Küstenweg zwischen Swanpool und Maenporth. Der einzige örtliche Strand, der das ganze Jahr über 24 Stunden für Hunde geöffnet ist; zu Fuß erreichbar.`,
      "Pendennis Castle": `Heinrich VIII.'s Tudor-Küstenfestung auf der Landzunge über dem Hafen. Ungewöhnlicherweise sind Hunde an der Leine überall willkommen, auch im Inneren der Gebäude und auf dem Gelände.`,
      "Falmouth Harbour": `Einer der tiefsten natürlichen Häfen der Welt, gesäumt von hundefreundlichen Pubs und Cafés. Ganzjährig im Freien und hundefreundlich, ist es das lebendige Herz des Ortes.`,
      "St Mawes Ferry": `Eine Passagierfähre vom Prince of Wales Pier zum hübschen Dorf St Mawes auf dem Roseland. Hunde sind willkommen und reisen kostenlos, an der Leine an Deck.`,
      "Fox Rosehill Gardens": `Ein kleiner, kostenloser, exotischer Garten voller subtropischer Pflanzen, das ganze Jahr über geöffnet, zwischen dem Ort und der Küste. Hunde an der Leine sind auf den kurvenreichen Wegen willkommen.`,
    },
  },
  faro: {
    history: `Faro, in römischer Zeit als Ossonoba gegründet, wurde von den Westgoten und dann den Mauren besetzt (die ihm seinen modernen Namen gaben, abgeleitet vom Gründer Harun ibn Habib), bis zur christlichen Rückeroberung durch Alfons III. von Portugal im Jahr 1249. Das Erdbeben von Lissabon 1755 verwüstete die Stadt, die in ihrem heutigen neoklassizistischen Stil rund um die noch stehende mittelalterliche Cidade Velha wiederaufgebaut wurde. Heute Verwaltungs- und Universitätshauptstadt der Algarve (66.000 Einwohner), ist Faro dank seines internationalen Flughafens (FAO) mit Direktflügen aus über 30 europäischen Städten auch das touristische Tor Südportugals. Für Reisende mit Hund ist Faro eines der vollständigsten haustierfreundlichen Ziele am Atlantik: ein in 15 Minuten begehbares Centro Histórico, der 18.000 Hektar große Naturpark Ria Formosa am Stadtrand, ganzjährige Hundestrände auf den Barriereinseln per Fähre, ein 24-Stunden-Tierkrankenhaus im Zentrum und Haustierzuschläge von 8-12 €/Nacht, unter den niedrigsten in Südeuropa.`,
    petTips: [`Die Café-/Tasca-Kultur der Algarve heißt Hunde standardmäßig willkommen, etwa 80 % der Restaurants in Faro akzeptieren angeleinte Hunde ganzjährig auf der Terrasse.`, `EVA-Busse und CP-Züge: mittelgroße und große Hunde zum halben Fahrpreis plus Maulkorb; kleine Hunde in Transportbox kostenlos.`, `Offizielle Hundestrände: Praia de Faro (westlicher Abschnitt), Ilha Deserta (35 Minuten mit der Fähre), Praia do Barril (35 km östlich), alle ganzjährig zugänglich.`, `24-Stunden-Notfall-Tierarzt: Hospital Veterinário do Algarve an der Estrada de São Brás (+351 289 880 100), zentrales Faro.`, `Große britische Auswanderergemeinde an der Algarve, etwa 70 % der Tiersitter und Tierärzte in Faro sprechen fließend Englisch.`],
    practicalInfo: [`Portugal ist EU- und Schengen-Mitglied: EU-Heimtierausweis plus gültige Tollwutimpfung plus ISO-Mikrochip genügt aus jedem EU-Land.`, `Direkte CP-Züge: Tavira 40 Min., Olhão 10 Min., Lagos 1 Std. 30 Min., Lissabon 3 Std. (Alfa Pendular), kleine Hunde in Transportbox kostenlos, größere zum halben Fahrpreis plus Maulkorb.`, `Flughafen Faro (FAO) 7 km westlich, EVA-Bus 14/16 (20 Min.) oder Taxi (15 Min.). Direktflüge aus London, Manchester, Dublin, Amsterdam, Berlin, Paris.`, `Währung: Euro. Tagesbudget haustierfreundlich: 50-75 €/Tag ohne Unterkunft, eines der niedrigsten in Westeuropa.`, `Zu meidende Feste mit einem ängstlichen Hund: Festival F (August, Musik), Algarve Bike Challenge (Februar), Karneval von Faro (Februar-März).`],
    sights: {
      "Cidade Velha": `Mittelalterliche ummauerte Altstadt, gepflasterte Gassen, Domplatz, Bischofspalast, römisch-maurische Fundamente. Rund um die Uhr geöffnet, hundefreundlich.`,
      "Arco da Vila": `Neoklassizistisches Tor von 1812 zur Cidade Velha, Carrara-Marmor, Storchennester obenauf im Frühjahr und Sommer. Rund um die Uhr geöffnet, hundefreundlich.`,
      "Faro Marina": `Yachthafen mit 1 km langer Uferpromenade entlang der Ria Formosa, Terrassen, Fähranleger, Blick auf die Salzmarschen. Rund um die Uhr geöffnet, hundefreundlich.`,
      "Ria Formosa Boardwalk": `Flacher, 2 km langer Holzsteg von der Marina bis nach Ludo, flamingoreiche Salzmarsch, ganzjährig für Hunde zugänglich.`,
      "Ilha Deserta": `10 km lange autofreie atlantische Barriereinsel, wilde Hundestrände, Fähre ab der Marina (35 Min.).`,
      "Jardim Manuel Bivar": `Der zentrale Hauptgarten, palmengesäumte Wege, Brunnen, Musikpavillon, Bänke am Hafenrand. Mit angeleinten Hunden hundefreundlich.`,
    },
  },
  florence: {
    history: `Florenz ist die Wiege der Renaissance. Hier finanzierten zwischen dem 14. und 16. Jahrhundert die Medici Botticelli, Leonardo da Vinci, Michelangelo und Brunelleschi und verwandelten eine wohlhabende Handelsstadt in das kulturelle und künstlerische Zentrum der Welt. Das heutige Florenz ist eine Stadt menschlichen Maßstabs (370.000 Einwohner), die dieses außergewöhnliche Erbe sorgfältig bewahrt: Schätzungsweise 70 % des Kulturerbes der Welt konzentrieren sich in Italien, ein beträchtlicher Anteil davon in Florenz. Doch Florenz ist auch eine lebendige Stadt mit ihren Märkten, Terrassencafés entlang des Arno und einer sehr ausgeprägten Hundekultur, Hunde begleiten ihre Besitzer in überdachte Märkte, Weinbars und historische Gärten.`,
    petTips: [`Hunde sind in Florenz' Bussen mit ermäßigtem Ticket zugelassen und müssen in einer Transportbox sein oder einen Maulkorb tragen. Für kurze Strecken im Zentrum gehen Sie zu Fuß, Florenz ist sehr kompakt.`, `Die meisten überdachten Märkte (Mercato Centrale, Sant'Ambrogio) heißen Hunde an der Leine willkommen, eine echte lokale Erfahrung.`, `Im Sommer ist Florenz eine der heißesten Städte Italiens (bis zu 38 °C). Der Parco delle Cascine und die Arno-Ufer bieten Schatten, vermeiden Sie Spaziergänge zwischen 12 und 17 Uhr.`, `Der Flohmarkt Mercato delle Pulci am Piazzale degli Uffizi ist hundefreundlich und für einen Sonntagmorgenspaziergang faszinierend.`, `Viele Restaurants in Florenz bringen von sich aus Wasser für Hunde, es gehört zur toskanischen Gastfreundschaftstradition.`],
    practicalInfo: [`24-Stunden-Notfall-Tierarzt: Clinica Veterinaria Firenze Sud, Via Senese 251, +39 055 204 9818`, `Zentrale Klinik: Clinica Veterinaria Scandicci, Via Strozzi 9, Scandicci, +39 055 756 4800`, `Züge aus Paris (Trenitalia Frecciarossa): Tiere in Transportboxen reisen mit einem Kinderticket. Große Hunde benötigen ein halbpreisiges Ticket.`, `Flughafen Florenz Peretola: EU-Haustiere mit gültigem Ausweis ohne Quarantäne zugelassen.`],
    sights: {
      "Jardins de Boboli": `Der italienische Garten hinter dem Palazzo Pitti (45.000 m²) ist mit Hunden an der Leine zugänglich. Terrassen, Grotten, Statuen und Panoramablicke über Florenz vom Belvedere aus. Hunde gegen Eintrittsgebühr zugelassen.`,
      "Parco delle Cascine": `Florenz' großer linearer Park (160 ha) entlang des Arno ist der beliebte Spielplatz der Florentiner und ihrer Hunde. Freilaufzonen in mehreren Bereichen, Radwege und Tennisplätze. Der Dienstagsmarkt hier ist lebhaft.`,
      "Oltrarno & Santo Spirito": `Das Viertel auf der anderen Seite des Arno (Oltrarno) ist Florenz' authentischstes und hundefreundlichstes. Piazza Santo Spirito ist ein lebhafter Platz mit Terrassen und Weinbars, auf denen Hunde willkommen sind. San Frediano ist das beliebte Viertel der Handwerker und Hunde gleichermaßen.`,
      "Lungarni (quais de l'Arno)": `Die Arno-Ufer durch Florenz sind der klassische Abendspaziergang. Goldenes Licht auf dem Ponte Vecchio, lebhafte Terrassen und angeleinte Hunde überall. Florenz' Passeggiata findet hier jeden Abend statt.`,
      "Offices & Académie": `Die Uffizien und die Accademia (Michelangelos David) lassen keine Tiere zu. Nutzen Sie diese Zeit, um Ihren Hund im Hotel oder bei einem Tiersitting-Service zu lassen, die Schlangen sind lang und die Besuche zeitaufwändig.`,
    },
  },
  formentera: {
    history: `Formentera ist die kleinste der vier großen Balearen-Inseln, ein flacher, 19 km langer Streifen aus blassem Sand, Wacholderbüschen und steingemauerten Feldern, 6 km südlich von Ibiza gelegen, nur per Fähre von Ibiza-Stadt zum Hafen La Savina erreichbar (30 bis 45 Minuten). Sie hat keinen Flughafen, keine Hochhäuser und nur 12.000 feste Einwohner - Zahlen, die im Spitzenmonat August auf fast 70.000 anschwellen, bevor sie bis November zur echten Inselruhe zurückkehren. Die Gewässer um die Insel sind Teil des UNESCO-Weltkulturerbes von Eivissa und Formentera, das 1999 für die außergewöhnlichen Posidonia-oceanica-Seegraswiesen anerkannt wurde, die das berühmt türkisfarbene Meer filtern. Seit der Vorgeschichte bewohnt, 1697 nach Jahrhunderten von Berberüberfällen wiederbesiedelt, verbindet die Insel heute ein arbeitendes landwirtschaftliches Hinterland mit dem weltberühmten Strand Ses Illetes, wiederholt zum besten Europas gewählt. Für den vierbeinigen Reisenden liegt der Sweet Spot in April-Mai oder Oktober-November: sanfte 18-23 °C, Strände noch oder wieder offen für angeleinte Hunde, Preise etwa halb so hoch wie im August, und eine ruhige Fähre, die Sie auf einer flachen, für langsame Spaziergänge geschaffenen Insel absetzt.`,
    petTips: [`Saisonales Strandverbot vom 1. Juni bis 30. September an jedem Badestrand Formenteras; kommunale Bußgelder erreichen 750 €, und die Polizei setzt dies durch. Angeleinte Hunde werden außerhalb dieses Zeitfensters auf Migjorn, Cala Saona und Es Caló geduldet.`, `Kein Flughafen: Jeder Hund kommt per Fähre von Ibiza-Stadt (Balearia, Aquabus, Trasmapi). Hunde reisen kostenlos auf dem offenen Außendeck; 5-10 € Aufpreis für Kabine oder Innensitze auf größeren Booten.`, `Kein 24-Stunden-Tierarzt auf Formentera. Die beiden lokalen Kliniken in Sant Francesc und Es Pujols sind nur tagsüber geöffnet. Für nächtliche Notfälle ist das einzige voll ausgestattete Krankenhaus das Hospital Veterinario Ibiza in Sant Antoni, +34 971 19 50 50, 30-45 Minuten per Fähre ab La Savina.`, `Schutz von Posidonia und Natura 2000: Die umliegenden Seegraswiesen und die Lagunen von Ses Salines stehen unter UNESCO- und EU-Schutz. Halten Sie Hunde innerhalb der Parkgrenzen ganzjährig an der Leine, lassen Sie sie niemals Dünen ausgraben oder Küstenvögel jagen.`, `Fahrradverleih-Korbregel: Die meisten Verleihe am Hafen La Savina akzeptieren einen Hund bis 10 kg nur in einem festen Frontkorb. Reservieren Sie den Korb im Juli-August eine Woche im Voraus separat; Körbe sind vor den Fahrrädern selbst ausverkauft.`],
    practicalInfo: [`Kein Flughafen auf Formentera. Zugang nur per Fähre von Ibiza-Stadt nach La Savina (30-45 Min.), ganzjährig betrieben von Balearia, Aquabus und Trasmapi.`, `Beste Jahreszeiten: April-Mai und Oktober-November. Meiden Sie Juli-August (Strandverbot, Hitze, Menschenmassen, 3-facher Preis). Der Winter ist mild, aber viele Restaurants und Fahrradverleihe schließen.`, `Kein 24-Stunden-Notfall-Tierarzt auf der Insel: der nächste ist das Hospital Veterinario Ibiza in Sant Antoni de Portmany auf Ibiza, +34 971 19 50 50.`, `EU-Heimtierausweis, Mikrochip und Tollwutimpfung erforderlich. Britische Haustiere benötigen ein von einem offiziellen Tierarzt innerhalb von 10 Tagen vor der Reise ausgestelltes Animal Health Certificate (AHC); führen Sie die Dokumente auf der Ibiza-Fährüberfahrt mit.`, `Währung EUR. Katalanisch ist neben Spanisch Amtssprache; die Beschilderung ist zweisprachig. Die kommunale Haustierverordnung des Consell Insular de Formentera setzt das Strandverbot vom 1. Juni bis 30. September mit Bußgeldern bis zu 750 € durch.`],
    sights: {
      "Far de la Mola": `Leuchtturm von 1861 auf der 142 m senkrechten Klippe an der Ostspitze Formenteras, dem östlichsten Punkt der Balearen. Berühmt aus Jules Vernes Roman Hector Servadac. Angeleinte Hunde auf der gesamten Außenplattform und den umliegenden Klippenpfaden willkommen; das Leuchtturminnere ist für Besucher geschlossen.`,
      "Far de Cap de Barbaria": `Leuchtturm von 1972 an der Südspitze Formenteras, erreichbar über 7 km unbefestigte Piste durch Wacholderbüsche und bronzezeitliche Siedlungsruinen. Der filmreichste Sonnenuntergangsort der Insel, ohne jede Bebauung in jeder Richtung. Angeleinte Hunde auf dem gesamten Weg und auf den Klippenplattformen um den Leuchtturm willkommen.`,
      "Ses Illetes & Trocadors": `Die schmale nördliche Halbinsel Formenteras, mit weißem Sand und türkisfarbenem Wasser auf beiden Seiten, regelmäßig zum besten Strand Europas gewählt. Hunde vom 1. Juni bis 30. September verboten; außerhalb dieses Zeitfensters dulden der Salzflächendamm und der unbefestigte Dienstweg über die Halbinsel angeleinte Hunde und bieten das ikonische Foto ohne den Strand selbst.`,
      "Sant Francesc Xavier": `Das weiß getünchte Hauptdorf, verankert um die 1726 befestigte Pfarrkirche, die auch als Zuflucht vor Berberkorsaren diente. Der Hauptplatz beherbergt die Kunsthandwerksmärkte am Mittwoch und Samstag und ist von Café-Terrassen gesäumt, die angeleinte Hunde willkommen heißen; das Kircheninnere ist für Hunde geschlossen, doch die Außentreppe und der ummauerte Garten sind hundefreundlich.`,
      "Camí Romà to La Mola": `Historischer, 5 km langer Erd- und Steinpfad, der von Es Caló de Sant Agustí die Klippe hinauf zum Plateau von La Mola führt, seit römischer Zeit genutzt. Pinienhaine, steingemauerte Felder und weite Ausblicke auf die Nordküste. Angeleinte Hunde ganzjährig willkommen; das sanfte Gefälle eignet sich auch für ältere Hunde.`,
      "Sant Ferran de ses Roques": `Das bohemische Binnendorf, berühmt für sein Hippie-Erbe, wo Bob Dylan und Joni Mitchell in den 1960er-Jahren im Fonda Pepe tranken. Der schattige Dorfplatz vor der Kirche von 1883 ist der soziale Mittelpunkt, mit ganzjährig hundefreundlichen Terrassen und wöchentlicher Live-Folkmusik im Sommer.`,
    },
  },
  frankfurt: {
    history: `Frankfurt am Main, eine Freie Reichsstadt des Heiligen Römischen Reiches und über fünf Jahrhunderte Krönungsort der Kaiser, ist heute Deutschlands Finanzhauptstadt und Sitz der Europäischen Zentralbank. Hinter seiner Skyline aus Wolkenkratzern (einzigartig auf dem europäischen Festland) verbirgt sich eine überraschend grüne Stadt: Mehr als 52 % ihres Gebiets sind Wald, Park oder Wasser, einschließlich des 4.200 Hektar großen Stadtwaldes, eines der größten stadteigenen Wälder Deutschlands. Das historische Viertel Sachsenhausen mit seinen Kopfsteinpflastergassen und jahrhundertealten Apfelweinwirtschaften verkörpert die andere Seite der Stadt: traditionell, einladend, konsequent hundefreundlich. Zwischen der 4 km langen Mainuferpromenade, den Stadtwaldwegen und den eingezäunten Freilaufzonen im Grüneburgpark und Niddapark bietet Frankfurt Hundebesitzern eine seltene Balance zwischen Großstadt und urbaner Natur.`,
    petTips: [`Der RMV-Nahverkehr nimmt kleine Hunde in Transportboxen kostenlos mit; größere Hunde benötigen eine Kinderfahrkarte.`, `Auf dem öffentlichen Nahverkehr ist für Listenhunde (Am. Staff, Pit Bull, Bullterrier, Rottweiler) ein Maulkorb vorgeschrieben, führen Sie vorsorglich einen weichen Maulkorb mit.`, `Bußgelder bis zu 150 € für nicht entsorgten Kot: kostenlose Kotbeutelspender stehen entlang der Hauptparkwege.`, `24-Stunden-Notfallkliniken: Kleintierklinik Bockenheim (069 97074955) und Tierklinik Kalbach (069 300651550).`, `Sommerliche Hitzewellen im Juli möglich (35 °C+): gehen Sie früh oder nach 19 Uhr spazieren, der Asphalt im Bankenviertel erreicht 55 °C.`],
    practicalInfo: [`EU-Heimtierausweis und gültige Tollwutimpfung von jedem haustierfreundlichen Hotel beim Check-in verlangt.`, `Leinenpflicht gilt in allen öffentlichen Parks außer den eingezäunten Hundeauslaufflächen, Bußgelder ab 35 €.`, `Stadtwald: Leinenpflicht vom 1. März bis 15. Juli (Brutzeit der Wildtiere), von Waldrangern durchgesetzt.`, `Animal Lounge am Flughafen FRA für Transittiere; hundefreundliche Auslaufflächen außerhalb der Terminals 1 und 2.`, `Speichern Sie Notfall-Tierarztnummern vor der Ankunft, Deutschland hat keine landesweite Tiernotfall-Hotline.`],
    sights: {
      "Grüneburgpark": `Ein 29 Hektar großer englischer Park im Westend mit einer der wenigen eingezäunten Freilaufzonen im Zentrum Frankfurts. Schattige Rasenflächen und reine Fußgängerwege, keine Radfahrer erlaubt.`,
      "Stadtwald": `Ein 4.200 Hektar großer städtischer Wald südlich der Stadt. Außerhalb der Brutzeit (16. Juli bis 28. Februar) ohne Leine, das größte innerstädtische Hundeauslaufgebiet Deutschlands.`,
      "Römerberg": `Der mittelalterliche Hauptplatz der Altstadt mit seinen Fachwerkfassaden aus der Nachkriegszeit. Weihnachtsmarkt und Open-Air-Veranstaltungen, angeleinte Hunde im Freien willkommen.`,
      "Eiserner Steg": `Eine 170 Meter lange eiserne Fußgängerbrücke über den Main, die die Altstadt mit Sachsenhausen verbindet. Vollständig mit Hund zugänglich, Panoramablick auf die Skyline.`,
      "Mainufer": `Eine 4 km lange Uferpromenade an beiden Seiten des Mains, vorbei am Museumsufer. Flach, breit, gepflastert, mit Bänken und öffentlichen Wasserzapfstellen im Sommer.`,
      "Niddapark": `Frankfurts größter innerstädtischer Park (168 ha) im Nordwesten. Ausgewiesene Freilaufzone am östlichen Rand, 6 km Rundwege zum Joggen mit Hund.`,
    },
  },
  freiburg: {
    history: `Freiburg im Breisgau, 1120 von den Zähringer Herzögen als freie Marktstadt am Fuß des Schwarzwaldes gegründet, wurde nach der Gründung der Albert-Ludwigs-Universität 1457 zu einer der wohlhabendsten Bergbau- und Universitätsstädte des Heiligen Römischen Reiches. Von 1368 bis 1805 habsburgischer Sitz im Breisgau und ab 1806 Teil von Baden, wurde die Stadt am 27. November 1944 durch alliierte Bombenangriffe fast vollständig zerstört, doch ihre Altstadt wurde originalgetreu wiederaufgebaut. Heute mit rund 236.000 Einwohnern, inoffizielle Hauptstadt des Schwarzwaldes und Deutschlands sonnenreichstes Stadtzentrum (1.740 Sonnenstunden pro Jahr, Quelle DWD), gilt Freiburg als eine der vorbildlichen Ökostädte Europas: Straßenbahnen, Fahrräder überall, passiver Städtebau. Für Reisende mit Hund ist es eine von Deutschlands einfachsten Städten: vollständig autofreie Altstadt, standardmäßig tolerante badische Kultur, die berühmten Bächle (kleine Wasserrinnen im Pflaster, aus denen Hunde im Sommer trinken) und direkter Seilbahnzugang zum Schwarzwald. Direkte ICE-Züge nach Basel in 45 Min., Frankfurt 2 Std., Paris 3 Std. 15 Min. über Karlsruhe.`,
    petTips: [`Die badische Stuben- und Gasthauskultur heißt Hunde standardmäßig willkommen, etwa 85 bis 90 % der Freiburger Lokale akzeptieren angeleinte Hunde drinnen und auf Terrassen.`, `VAG-Straßenbahnen und -Busse: große Hunde zur Kinderfahrkarte (etwa 1,50 €) plus Leine; Maulkorb nicht erforderlich; kleine Hunde in Transportbox kostenlos.`, `Das baden-württembergische Forstgesetz erlaubt ganzjährig Freilauf auf markierten Waldwegen; Mooswald, Schauinsland und der obere Schlossberg sind die wichtigsten Orte.`, `24-Stunden-Notfall-Tierarzt: Kleintierklinik Frank, Mooswaldallee 10i, +49 761 5036660; vorab anrufen zur Triage.`, `Sonniges Klima: Juli- und August-Nachmittage erreichen auf dem Pflaster 27 bis 30 Grad; testen Sie die Hitze mit der Hand und nutzen Sie die Kabine der Schauinslandbahn, um einen dickfelligen Hund abzukühlen.`],
    practicalInfo: [`Deutschland ist EU- und Schengen-Mitglied: EU-Heimtierausweis plus gültige Tollwutimpfung plus ISO-Mikrochip genügt aus jedem EU-Land.`, `Direkte DB-ICE/IC-Züge: Basel SBB 45 Min., Frankfurt 2 Std., Berlin 5 Std. 45 Min.; TGV-Anschluss in Karlsruhe nach Paris in 3 Std. 15 Min. Kleine Hunde in Transportbox kostenlos, größere zum Kindertarif.`, `Nächste Flughäfen: Basel EuroAirport (BSL/MLH/EAP) 70 km südlich (Lufthansa, easyJet, Wizz); Frankfurt-Hahn (HHN) 2 Std. nördlich (Ryanair).`, `Währung: Euro. Tagesbudget haustierfreundlich: 65 bis 95 € pro Tag ohne Unterkunft, etwa 20 % unter München.`, `Zu meidende Feste mit einem ängstlichen Hund: Freiburger Weinfest (Juli, Menschenmassen auf dem Münsterplatz), Weihnachtsmarkt Ende November bis 23. Dezember (nach 17 Uhr überfüllt).`],
    sights: {
      "Freiburger Münster": `Gotische Kathedrale, erbaut 1200 bis 1513, einzelner 116 m hoher Turm. Münsterplatz und Außenfassade rund um die Uhr für angeleinte Hunde geöffnet, Innenraum nur Assistenzhunden vorbehalten.`,
      "Schlossberg": `456 m hoher bewaldeter Hügel, der sich direkt aus der Altstadt erhebt, Buchen- und Tannenwege, Freilauf auf den oberen Waldpfaden geduldet.`,
      "Bächle": `Kleine Wasserrinnen im Pflaster der Altstadt, ein mittelalterliches Erbe; viele Hunde trinken im Sommer daraus, was Einheimische gerne sehen.`,
      "Schauinslandbahn": `Deutschlands längste durchgehende Seilbahn (3,6 km), fährt zum 1.284 m hohen Schauinsland-Gipfel. Hunde für etwa 3 € in der Kabine zugelassen.`,
      "Augustinerplatz": `Gestufter, gepflasterter Platz hinter dem Schwabentor, beliebter Treffpunkt der Einheimischen an warmen Abenden mit Hunden und Bier.`,
      "Mooswald": `Weitläufiger, 1.500 ha großer Feuchtwald westlich der Stadt, Freilauf nach baden-württembergischem Forstgesetz auf markierten Waldwegen erlaubt.`,
    },
  },
  frejus: {
    history: `Fréjus wurde um 49 v. Chr. von Julius Cäsar als Forum Julii gegründet, dem strategischen Hafen der westmediterranen römischen Flotte und der ältesten römischen Stadt Galliens. Das römische Erbe ist außergewöhnlich: das Amphitheater aus dem 1. Jahrhundert (eines der vollständigsten in Südfrankreich), ein Theater, ein 40 km langes Aquädukt, der Hafen und die augusteische Laterne. Das mittelalterliche Stadtzentrum konzentriert sich um die Kathedrale Saint-Léonce und ihr Baptisterium aus dem 5. Jahrhundert, eines der ältesten christlichen Bauwerke Frankreichs. Als Partnerstadt des benachbarten Saint-Raphaël verbindet Fréjus eine lange Küstenlinie (Frejus-Plage, Saint-Aygulf), ein weinbautreibendes Hinterland und direkten Zugang zum Massif de l'Estérel. Für reisende Haustiere verlangt Frankreich den EU-Heimtierausweis, den ISO-Mikrochip und eine gültige Tollwutimpfung. Das prägende Merkmal für Besucher mit Hund: Fréjus ist mit deutlichem Abstand die hundefreundlichste Gemeinde an der Côte d'Azur, mit drei ganzjährig geöffneten offiziellen Hundestränden, einer 100 Hektar großen Base Nature mit umzäuntem Woof Park, und angeleinten Hunden, die ausdrücklich im römischen Amphitheater zugelassen sind.`,
    petTips: [`Fréjus ist die hundefreundlichste Küstengemeinde an der Côte d'Azur: drei ganzjährig geöffnete offizielle Hundestrände (Argens bei Saint-Aygulf, die nördliche Zone von Esclamandes, Pacha Plage an der Base Nature).`, `Der Woof Park innerhalb der Base Nature François Léotard ist ein brandneuer, umzäunter Freilauf-Bereich, kostenlos, mit Agility-Hindernissen und einer Wasserstelle. Hunde der Kategorien 1 und 2 (französische Klassifikation für Kampfhundrassen) sind nicht zugelassen.`, `Estérel Côte d'Azur LeBus (ehemals Agglobus CAVEM) akzeptiert nur kleine Haustiere in einem Tragekorb sowie Blindenhunde; große Hunde sind auch angeleint mit Maulkorb nicht zugelassen. Gehen Sie zu Fuß, nehmen Sie ein Taxi oder nutzen Sie den TER.`, `Ungewöhnliches Merkmal: Das römische Amphitheater (Arènes) lässt angeleinte Hunde bei regulären Besuchen zu. Prüfen Sie den Veranstaltungskalender der Stadt, um Konzert- und Stierkampftage zu meiden, an denen die Stätte für allgemeine Besucher geschlossen ist.`, `An Tagen mit roter Waldbrandwarnung im Juli und August werden die Wanderwege im Massif de l'Estérel per Präfekturerlass für Wanderer gesperrt. Prüfen Sie die tägliche Karte, bevor Sie hinaufgehen.`],
    practicalInfo: [`Anreise: Bahnhof Fréjus SNCF an der Küstenlinie Marseille-Vintimille, TER nach Cannes (40 Min.), Nizza (1 Std.) und Toulon (1 Std.). TGV ab Saint-Raphaël-Valescure (eine Station östlich). Flughafen Nizza (NCE) 1 Stunde mit dem Taxi.`, `Strände: drei ganzjährig geöffnete offizielle Hundestrände (Argens bei Saint-Aygulf, nördliche Zone Esclamandes, Pacha Plage an der Base Nature). Alle anderen kommunalen Strände setzen das Verbot vom 15. Juni bis 15. September durch.`, `Parks: Base Nature François Léotard (100 ha mit dem umzäunten Woof Park), Jardins de la Villa Aurelienne (23 ha), Étangs de Villepey (260 ha Küstenlagune).`, `Tierärzte: Clinique des Arènes Fréjus (24-Stunden-Notfallbereitschaft), VET'AURELIA Saint-Raphaël (regionales Referenzzentrum), die kostenlose nationale Hotline 3115 sowie die regionale Nummer 0893020600.`, `Dokumente: EU-Heimtierausweis, ISO-Mikrochip und gültige Tollwutimpfung erforderlich. Reisende von außerhalb der EU (Großbritannien, USA) benötigen ein Animal Health Certificate oder eine USDA-APHIS-Bestätigung.`],
    sights: {
      "Arènes de Fréjus": `Das römische Amphitheater aus dem 1. Jahrhundert, restauriert und noch immer für Konzerte und Stierkämpfe genutzt, ist eines der vollständigsten in Südfrankreich. Ungewöhnlich für ein französisches Denkmal sind angeleinte Hunde bei regulären Besuchen im Inneren zugelassen, außerhalb besonderer Veranstaltungen.`,
      "Base Nature François Léotard et Woof Park": `Ein 100 Hektar großer Park auf dem Gelände der ehemaligen Marineflugstation, mit flachen Wegen, einem frei zugänglichen Strand und einem brandneuen, vollständig umzäunten Woof Park (Agility-Hindernisse, Wasserstelle, schattige Bänke). Hunde der Kategorien 1 und 2 sind im Woof Park nicht zugelassen.`,
      "Plage d'Argens (cani-plage)": `Der größte der drei offiziellen Hundestrände von Fréjus, in Saint-Aygulf, ganzjährig per kommunaler Verordnung reserviert. Feiner Sand, sanftes Gefälle, Leinenpflicht und Abfalleimer am Eingang.`,
      "Vieille Ville et cathédrale Saint-Léonce": `Das mittelalterliche Zentrum um die Place Formigé und die Kathedrale Saint-Léonce, deren Baptisterium aus dem 5. Jahrhundert eines der ältesten christlichen Bauwerke Frankreichs ist. Das Kircheninnere und der Kreuzgang lassen keine Hunde zu, doch der gesamte Rundgang ist für angeleinte Hunde geöffnet.`,
      "Massif de l'Estérel": `Das rot-porphyrische Gebirge östlich von Fréjus, durchzogen von markierten Wegen, einschließlich der 4 km langen Rundtour zum Pic du Cap Roux (453 m) mit einem 360-Grad-Panorama über die Bucht. Angeleinte Hunde willkommen, außer bei sommerlichen Waldbrand-Sperrungen.`,
      "Port Fréjus": `Der moderne Yachthafen südlich der Stadt, mit einem langen Kai, gesäumt von hundefreundlichen Brasserien auf der Terrasse. Eine flache, 1 km lange Promenade rund um das Becken und direkter Zugang zur 800 m entfernten Pacha Plage an der Base Nature.`,
    },
  },
  fuengirola: {
    history: `Fuengirola, ein Ferienort mit rund 80.000 Einwohnern an der Costa del Sol in der Provinz Málaga, wuchs von einem Fischerdorf unterhalb der maurischen Festung Sohail zu einem der internationalsten und familienfreundlichsten Ziele der andalusischen Küste heran. Sein Markenzeichen ist eine rund 7 km lange Uferpromenade, der längste Paseo Marítimo an der Costa del Sol, gesäumt von Palmengärten, Chiringuitos und Stränden. Für Hundebesitzer sticht Fuengirola deutlich hervor: Der Ort vermarktet sich als haustierfreundlich, mit einem ganzjährig geöffneten offiziellen Hundestrand unterhalb der Burg Sohail, rund sieben eingezäunten Hundeparks und einem Cercanías-Vorortzug, der Hunde direkt vom Flughafen Málaga aus kostenlos befördert. Die beiden Dinge, die man einplanen sollte, sind die andalusische Sommerhitze und das saisonale Verbot für Hunde an den nicht ausgewiesenen Stränden, vom 1. Juni bis 30. September.`,
    petTips: [`Die Playa Canina del Castillo de Sohail ist ganzjährig geöffnet, den Sommer eingeschlossen; an allen anderen Stränden Fuengirolas sind Hunde vom 1. Juni bis 30. September verboten (Bußgelder ab 100 Euro).`, `Außerhalb der Saison, von Oktober bis Ostern, erlaubt die kommunale Verordnung angeleinte Hunde an allen Stränden der Stadt.`, `Der Cercanías-Zug C-1 befördert Hunde jeder Größe kostenlos vom Flughafen Málaga und der Stadt Málaga aus, angeleint und mit Maulkorb (keine Transportbox erforderlich).`, `Andalusische Hitze: Gehen Sie im Sommer in der Morgendämmerung oder Abenddämmerung spazieren, testen Sie das Pflaster mit dem Handrücken und führen Sie Wasser mit, bei über 300 Sonnentagen im Jahr.`, `Die Costa del Sol ist ein Leishmaniose-Gebiet (Sandmücken): Fragen Sie Ihren Tierarzt nach einem Repellent-Halsband oder Spot-on; potenziell gefährliche Rassen (PPP) müssen in der Öffentlichkeit angeleint sein und einen Maulkorb tragen.`],
    practicalInfo: [`Strände: Nur der Hundestrand Castillo de Sohail lässt Hunde im Sommer zu; anderswo vom 1. Juni bis 30. September verboten, außerhalb der Saison überall angeleinte Hunde erlaubt.`, `Notfall-Tierarzt: URVET Fuengirola, Calle Molino de Viento 35, 24 Stunden geöffnet (+34 629 97 86 79); die nationale 112 ist auf Menschen ausgerichtet, rufen Sie also direkt einen Tierarzt an.`, `Transport: Cercanías-Zug C-1 ab Flughafen Málaga (AGP), Hunde kostenlos angeleint und mit Maulkorb; Busse auf kleine Hunde in einer Transportbox beschränkt, Taxis nach Ermessen des Fahrers.`, `Ohne Leine: nur innerhalb der eingezäunten parques caninos (etwa sieben) und am Hundestrand; Leinenpflicht auf allen Straßen, Promenaden und in Parks.`, `Einreise: EU-Besucher benötigen einen EU-Heimtierausweis, Mikrochip und gültige Tollwutimpfung; Besucher von außerhalb der EU benötigen ein Gesundheitszeugnis, prüfen Sie die MAPA-Regeln.`],
    sights: {
      "Playa Canina del Castillo de Sohail": `Fuengirolas offizieller Hundestrand, seit 2014 geöffnet und einer der ersten in der Provinz Málaga, ein eingezäuntes Areal von über 3.000 m² unterhalb der Burg Sohail, an dem Hunde ganzjährig schwimmen und laufen können, den Sommer eingeschlossen. Es gibt Hundeduschen, Pfotenwaschstellen und einen Süßwasserbrunnen für Haustiere.`,
      "Castillo Sohail": `Eine restaurierte Festung aus dem 10. Jahrhundert auf einem Hügel mit Blick auf die Flussmündung, den Strand und das Meer. Angeleinte Hunde sind auf dem Außengelände und dem Hügel um die Mauern willkommen, mit dem Hundestrand und dem Uferpark direkt darunter.`,
      "Paseo Marítimo Rey de España": `Mit rund 7 km die längste Uferpromenade an der Costa del Sol, die sich über die gesamte Länge Fuengirolas erstreckt, vorbei an Palmengärten, Spielplätzen und Chiringuitos. Ein flacher, windiger Spaziergang an der Leine, der die zentralen Strände mit dem Hundestrand am Castillo Sohail verbindet.`,
      "Parque del Río Fuengirola": `Ein großer grüner Uferpark an der Mündung des Río Fuengirola unterhalb der Burg Sohail, mit Sportplätzen, Spielplätzen und einer eingezäunten Hundezone. Er schließt direkt an den Hundestrand an, sodass Sie einen Lauf im Park mit einem Bad im Sand kombinieren können.`,
      "Parques Caninos de Fuengirola": `Fuengirola verfügt über rund sieben eingezäunte städtische Hundeparks in der Stadt, darunter Los Boliches, die einzigen Orte, an denen Hunde neben dem Hundestrand legal ohne Leine laufen dürfen. Sie bieten Hunden einen sicheren Raum abseits des Verkehrs.`,
      "Bioparc Fuengirola": `Fuengirolas gefeierter immersiver Zoo bildet tropische Lebensräume mitten in der Stadt nach und ist eine wichtige Attraktion. Wie fast alle Zoos lässt er keine Haustiere zu, planen Sie also eine Begleitperson ein, die draußen mit Ihrem Hund wartet.`,
    },
  },
  funchal: {
    history: `Funchal, 1424 von João Gonçalves Zarco kurz nach Portugals Entdeckung Madeiras gegründet, wuchs im 16. Jahrhundert zum aktivsten Atlantikhafen zwischen Lissabon und Amerika heran, dank seiner vorgeschobenen Lage an der Westindien-Route und seines Zuckerrohrs und später des Madeirawein, der die Höfe von London, Sankt Petersburg und Boston zierte. Heute Hauptstadt der Autonomen Region Madeira mit 105.000 Einwohnern, liegt die Stadt in einem steilen, südlich ausgerichteten vulkanischen Amphitheater zwischen dem Atlantik und den Bergen im Landesinneren, was ihr ein außergewöhnlich mildes Mikroklima verleiht: 16 bis 24 °C ganzjährig, kein Frost, keine drückende Hitze. Für Reisende mit Hunden ist Funchal eines der einladendsten Winterziele Europas: unzählige Esplanadas an der Avenida Arriaga, im Yachthafen und in der Zona Velha mit ihren bemalten Türen; eine 3 km lange Klippenpromenade Lido, die bis zur Praia Formosa führt; und leichter Bus- oder Fußzugang zur Levada dos Tornos, die den Berghang auf zig Kilometern Bewässerungskanal nachzeichnet. Die einzigen wirklichen Einschränkungen der Insel sind ein einziges rund um die Uhr geöffnetes Tierkrankenhaus (VetMedis, Caminho de Santo António), strenge sommerliche Strandverbote für Hunde an den Stadtstränden (Praia Formosa, Lido) und die Seilbahn nach Monte, die Hunde nur in einer vollständig geschlossenen Transportbox akzeptiert.`,
    petTips: [`Nur ein 24-Stunden-Tierkrankenhaus auf der Insel: VetMedis, Caminho de Santo António, +351 291 145 500, speichern Sie die Nummer bei Ankunft.`, `Busse von Horários do Funchal befördern kleine Hunde in Transportboxen kostenlos; große Hunde liegen im Ermessen des Fahrers, einfacher außerhalb der Stoßzeiten.`, `Stadtstrände (Praia Formosa, Lido) verbieten Hunde vom 1. Mai bis 30. September; nutzen Sie außerhalb der Saison die Praia de São Tiago oder ganzjährig Caniço.`, `Für die Seilbahn nach Monte ist für Hunde eine vollständig geschlossene Transportbox erforderlich; für einen mittelgroßen oder großen Hund nehmen Sie stattdessen den HF-Bus 21.`, `Basaltpflaster wird im Sommer nach 11 Uhr glühend heiß: Gehen Sie von Juni bis September vor 10 Uhr oder nach 18 Uhr spazieren.`],
    practicalInfo: [`Madeira ist EU-Gebiet: EU-Heimtierausweis plus gültige Tollwutimpfung plus ISO-Mikrochip bei Einreise in FNC erforderlich (keine Bandwurmbehandlung nötig).`, `Leinenpflicht gilt in allen Parks, Promenaden und auf öffentlichen Straßen, Bußgelder beginnen bei 60 €.`, `Gelistete gefährliche Rassen (Pit Bull, Rottweiler, Staffordshire, Tosa) benötigen in der Öffentlichkeit einen Maulkorb, eine erklärte Versicherung und eine Halterlizenz.`, `Der Jardim Botânico da Madeira lässt außer Blindenhunden keine Haustiere zu; haustierfreundliche Alternative: Parque de Santa Catarina.`, `Der Flughafen FNC ist bekanntermaßen windig mit kurzer Landebahn; für ängstliche Hunde bevorzugen Sie Morgenankünfte, wenn die Seitenwinde ruhiger sind.`],
    sights: {
      "Parque de Santa Catarina": `Ein 3 Hektar großer Hügelpark über dem Kreuzfahrthafen, mit einem von Schwänen bevölkerten See, der Kapelle Santa Catarina und weiten Blicken über die Bucht. Angeleinte Hunde auf allen Rasenflächen willkommen.`,
      "Levada dos Tornos": `Eine flache, niedrig gelegene Levada, die den Berghang oberhalb von Monte über zig Kilometer nachzeichnet. Der Abschnitt Monte-Camacha (~5 km) eignet sich ideal an kurzer Leine.`,
      "Zona Velha (Rua de Santa Maria)": `Historisches Fischerviertel mit einer fußgängerfreundlichen Straße bemalter Türen, Dutzenden Esplanada-Cafés und dem Forte de São Tiago an ihrem östlichen Ende. Vollständig mit Leine zugänglich.`,
      "Promenade do Lido": `Eine 3 km lange, flache Klippenpromenade, die den Lido-Komplex mit der Praia Formosa verbindet, mit öffentlichen Wasserbrunnen, die Hunde von niedrigen Zapfstellen aus nutzen können. Am besten bei Sonnenuntergang.`,
      "Monte (Igreja Nossa Senhora do Monte)": `Wallfahrtsdorf 560 m über Funchal; Kirchenvorplatz und Außengärten sind mit Leine zugänglich. HF-Bus 21 ab dem Zentrum oder Abstieg über die Levada.`,
      "Forte de São Tiago": `Gelbe Küstenfestung aus dem 17. Jahrhundert am östlichen Rand der Zona Velha, mit einem an der Leine zugänglichen Wehrgang im Freien und dem besten Bucht-Blick auf niedriger Höhe.`,
    },
  },
  fundao: {
    history: `Fundão, Sitz des Bezirks Castelo Branco im Herzen des portugiesischen Beira-Landesinneren, erstreckt sich am Fuß der Serra da Gardunha, nur wenige Kilometer von der Serra da Estrela entfernt. Diese kleine Granitstadt verdankt ihren Ruhm ihren Kirschbäumen: Jeden Juni feiert das Festa da Cereja eine Ernte, die die terrassierten Obstgärten des Berges tiefrot färbt. Rund um die Praça do Município und den Convento de Santo António bewahren die Straßen einen ruhigen ländlichen Rhythmus, in dem die Kultur der Landquintas und offenen Esplanadas Hunden sehr wohlgesinnt ist. Das portugiesische Landesinnere bringt heiße, trockene Sommer, aber kühlere Bergluft mit sich, ideal zum Wandern auf den Pfaden der Gardunha oder zum Erkunden der nahen Historischen Dörfer wie Castelo Novo, deren Granitgassen sich für einen ruhigen angeleinten Spaziergang eignen. Dies ist kein Küstenziel: Hier sind es die Hügel, die Dörfer und die Flüsse, die einen Aufenthalt prägen.`,
    petTips: [`Portugals einzige Notrufnummer ist 112; fragen Sie Ihre Unterkunft nach dem nächsten Tierarzt, da mehrere Praxen Fundão und die Cova da Beira bedienen.`, `Die Sommer im Landesinneren sind heiß und trocken: Gehen Sie früh oder spät spazieren und führen Sie auf den Gardunha-Pfaden immer Wasser mit.`, `Viele Quintas und ländliche Unterkünfte akzeptieren Hunde, bestätigen Sie dies aber immer bei der Buchung, besonders außerhalb des Stadtzentrums.`, `Auf Bergpfaden halten Sie Ihren Hund in der Nähe weidender Herden an der Leine und achten Sie im Spätwinter und Frühling auf Zecken und Pinienprozessionsspinner.`, `An den Flussstränden der Region (praias fluviais) sind Hunde in überwachten Zonen im Sommer oft verboten: Bevorzugen Sie die freien Abschnitte flussaufwärts.`],
    practicalInfo: [`Portugal ist EU-Mitglied: Ein EU-Heimtierausweis, ISO-Mikrochip und aktuelle Tollwutimpfung genügen zur Einreise.`, `Leinenpflicht gilt in öffentlichen Räumen; potenziell gefährliche Rassen müssen einen Maulkorb tragen und versichert sein.`, `Fundão liegt an der Bahnlinie Beira Baixa (Verbindungen nach Covilhã, Castelo Branco und Lissabon); CP befördert kleine Hunde in Transportboxen und große Hunde angeleint mit Maulkorb.`, `Dies ist kein Küstenziel: Das Bergklima ist kühler als an der Küste, packen Sie also für einen kleinen Hund an kühlen Bergabenden eine Schicht ein.`, `Die allgemeine Notrufnummer ist 112; prüfen Sie die Öffnungszeiten des örtlichen Tierarztes, da die nächtliche Abdeckung Sie möglicherweise nach Covilhã oder Castelo Branco umleitet.`],
    sights: {
      "Praça do Município": `Der Hauptplatz der Stadt, gesäumt vom Rathaus und belebt von Esplanadas und dem Markt. Angeleinte Hunde sind willkommen, ein idealer Ausgangspunkt, um das Zentrum zu Fuß zu erkunden.`,
      "Convento de Santo António": `Ein ehemaliges Franziskanerkloster aus dem 17. Jahrhundert, heute eine Kulturstätte, mit einem offenen Vorplatz und Gärten. Angeleinte Hunde sind in den Außenbereichen willkommen, wenn auch nicht im Inneren.`,
      "Serra da Gardunha": `Das Granitgebirge über der Stadt, durchzogen von Wanderwegen und Kirschgärten. Angeleinte Hunde sind willkommen; führen Sie Wasser mit, da der Schatten im Sommer lückenhaft ist.`,
      "Aldeia Histórica de Castelo Novo": `Ein Granit-Historisches-Dorf an den Hängen der Gardunha, mit seinem Pranger, dem königlichen Brunnen und gepflasterten Gassen. Angeleinte Hunde sind in den Straßen willkommen, etwa zwanzig Minuten von Fundão entfernt.`,
      "Alpedrinha": `Ein alter Kurort und Etappe auf der königlichen Straße, reich an Barockbrunnen und Granit-Herrenhäusern. Seine ruhigen Gassen lassen sich leicht angeleint erkunden.`,
      "Pomares de Cereja da Gardunha": `Terrassierte Kirschgärten, die die Hänge der Gardunha bedecken und im Juni für das Festa da Cereja rot werden. Ländliche Pfade, perfekt für einen angeleinten Frühlingsspaziergang.`,
    },
  },
  galway: {
    history: `Galway, im 13. Jahrhundert von den Anglonormannen dort gegründet, wo der River Corrib auf die Atlantikbucht trifft, war fünf Jahrhunderte lang der wohlhabendste Seehafen an Irlands Westküste, genannt "City of the Tribes" nach den vierzehn Kaufmannsfamilien, die ihn leiteten. Heute Hauptstadt der Provinz Connacht mit 85.000 Einwohnern, ist es vor allem eine Studentenstadt (25.000 an der University of Galway) und das böhmische Herz des gälischsprachigen Irlands: die Fußgängerzone Latin Quarter, Shop Street, Quay Street, High Street erklingt ständig von Live-Trad-Musik, und 30 % der Bewohner des benachbarten Gaeltacht sprechen noch immer täglich Irisch. Für Reisende mit Hund ist Galway eine von Europas einladendsten Städten: Die 2 km lange Salthill-Promenade entlang der Bucht akzeptiert ganzjährig angeleinte Hunde, der 10 Autominuten entfernte Silver-Strand-Strand ist außerhalb der Saison ohne Leine, und Connemara, 2.000 km² Moor, Berg und unbezäunte Seen, beginnt 30 Minuten westlich. Traditionelle Pubs (Tigh Neachtain, Crane Bar) heißen Hunde in ihren holzvertäfelten Snugs willkommen, und Bus Éireann plus Iarnród Éireann befördern angeleinte und mit Maulkorb versehene Hunde kostenlos. Die einzige Einschränkung: Irland verlangt für Hunde, die aus einem nicht-insularen EU-Land ankommen, eine Bandwurmbehandlung (Echinokokken) zwischen 24 und 120 Stunden vor der Ankunft.`,
    petTips: [`Bus Éireann und Iarnród-Éireann-Züge nehmen angeleinte und mit Maulkorb versehene Hunde kostenlos mit, nach Ermessen des Fahrers bzw. Schaffners.`, `Galways Strände (Silver Strand, Grattan, Salthill): Leinenpflicht vom 1. Juni bis 15. September, 11 bis 18 Uhr, sonst ohne Leine.`, `Traditionelle Pubs im Latin Quarter (Tigh Neachtain, Crane Bar, The Quays) heißen Hunde in ihren holzvertäfelten Snugs willkommen, rufen Sie zur Bestätigung vorher an.`, `Notfallkliniken: Galway Veterinary Specialists (091 765 555, rund um die Uhr nach Terminvereinbarung) und Anicare Galway Veterinary Hospital (091 752 022).`, `Beständiger Atlantikwind bei Salthill (50-70 km/h Böen im Winter): Für kleine Hunde auf der exponierten Promenade ist ein Geschirr einem Halsband vorzuziehen.`],
    practicalInfo: [`Einreise nach Irland: EU-Heimtierausweis plus Bandwurmbehandlung (Echinokokken), von einem EU-Tierarzt zwischen 24 und 120 Stunden vor der Ankunft verabreicht und im Ausweis vermerkt.`, `Flughafen Shannon (SNN) 90 km südlich (1 Std. Fahrt); Dublin (DUB) 200 km östlich (2 Std. 30 Min. mit dem Iarnród-Éireann-Zug, angeleinter Hund kostenlos).`, `4 in Irland eingeschränkte Rassen müssen in der Öffentlichkeit einen Maulkorb plus kurze Leine (≤2 m) tragen: Pit Bull Terrier, Bull Mastiff, Dobermann, Rottweiler, gilt in allen öffentlichen Räumen einschließlich der Salthill-Promenade.`, `Das Galway International Arts Festival (Mitte Juli) füllt die Hotels, buchen Sie 4 Monate im Voraus oder meiden Sie die letzte Juliwoche.`, `Ozeanisches Klima: Packen Sie ein saugfähiges Handtuch und einen Hunderegenmantel ein, es regnet an der irischen Westküste durchschnittlich an 225 Tagen im Jahr.`],
    sights: {
      "Salthill Promenade": `Ikonische, 2 km lange Uferpromenade entlang der Galway Bay, vom Claddagh bis zu den Blackrock-Sprungtürmen. Lokale Tradition: "kicking the wall" (das Treten der Mauer) am fernen Ende. Angeleinte Hunde ganzjährig, Bänke und Wasserbrunnen.`,
      "Silver Strand": `Blaue-Flagge-Weißsandstrand, 10 Min. mit dem Auto in Barna. Hunde außerhalb des Zeitraums 1. Juni bis 15. September ohne Leine erlaubt (dann gilt Leinenpflicht). Seichte Gewässer zum Schwimmen für Hunde.`,
      "Spanish Arch + Long Walk": `Erhaltenes Fragment der Stadtmauern von 1584 an der Mündung des Corrib, fortgesetzt von der farbenfrohen Häuserreihe Long Walk. Offener öffentlicher Raum, angeleinte Hunde willkommen, Ausgangspunkt des Uferspaziergangs.`,
      "South Park Claddagh": `Großer, 12 Hektar großer Küstenpark im historischen Claddagh-Viertel, mit Blick auf die Bucht. Angeleinte Hunde, Sportplätze, Fußweg mit Anschluss an die Salthill-Promenade.`,
      "Connemara National Park": `2.957 Hektar Moor, Grasland und Berge (Diamond Hill 442 m), 75 km westlich. Leinenpflicht für Hunde, frei weidende Schafe. Besucherzentrum in Letterfrack.`,
      "Eyre Square": `Galways zentraler Platz (John F. Kennedy Memorial Park), 1 Hektar Rasen und Brunnen im Herzen der Stadt. Angeleinte Hunde, idealer Ausgangspunkt zur Erkundung des Latin Quarter.`,
    },
  },
  gandia: {
    history: `Gandia verdankt seinen Ruhm der Familie Borgia: Im 15. Jahrhundert machten die Herzöge von Gandia, darunter der Heilige Franz von Borja, aus diesem Ort im Bezirk Safor einen kleinen Renaissance-Hof mit Palast, Kollegiatkirche und Universität. Der in der umliegenden Huerta angebaute Zuckerrohr finanzierte dieses goldene Zeitalter, bevor im 19. Jahrhundert Orangen übernahmen. Die moderne Stadt teilte sich später in zwei: das historische Zentrum etwas landeinwärts und Playa de Gandia, ein in den 1960er-Jahren entstandener Ferienort entlang eines der schönsten Sandstrände der Region Valencia. Heute verbindet Gandia herzogliches Erbe, eine lebendige Uferpromenade und ein Kalksteingebirge im Hinterland, eine leicht mit Hund zu erkundende Mischung, besonders außerhalb der Saison, wenn die Strände sich leeren und das Mittelmeerlicht alles weicher macht.`,
    petTips: [`Im Sommer sind Hunde am Hauptstrand von Gandia verboten: Die offizielle Hundezone liegt nördlich, an der Platja de l'Ahuir. Außerhalb der Saison ist die Toleranz größer, prüfen Sie aber die Schilder.`, `In der Stadt ist die Leinenpflicht vorgeschrieben, und als PPP (potenziell gefährlich) eingestufte Rassen müssen in Spanien in der Öffentlichkeit einen Maulkorb tragen.`, `Der Cercanías-Zug C1 nach Valencia akzeptiert kleine Hunde in Transportboxen sowie angeleinte, mit Maulkorb versehene Hunde nach den Renfe-Regeln.`, `Vermeiden Sie von Juni bis September glühenden Asphalt und Sand zwischen 12 und 18 Uhr: Testen Sie den Boden mit der Hand, bevor Sie mit Ihrem Hund spazieren gehen.`, `Führen Sie immer Wasser mit sich: Brunnen sind auf dem Serpis-Grünweg und auf dem Pfad zum Castell de Bairén rar.`],
    practicalInfo: [`Mehrere Tierarztpraxen im Ort und in Strandnähe; nächtliche Notfälle werden in Valencia behandelt, etwa eine Stunde mit dem Auto entfernt`, `Europäische Notrufnummer: 112; bei einem gefundenen oder verletzten Tier verweist Sie die örtliche Polizei an die richtige Stelle`, `Zoofachgeschäfte und Haustierregale in Supermärkten sowohl im Zentrum als auch an der Playa de Gandia`, `Stadtbusse: kleine Hunde in Transportboxen; bei Taxis liegt die Mitnahme im Ermessen des Fahrers`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung sind zum Reisen in Spanien erforderlich`],
    sights: {
      "Palau Ducal dels Borja": `Der Palast der Herzöge von Gandia, Heimat der Familie Borgia, vereint gotische, Renaissance- und Barockstile um spektakuläre vergoldete Säle. Hunde sind im Inneren nicht zugelassen, doch die Fassade und die Gassen der Altstadt eignen sich für einen schönen angeleinten Spaziergang.`,
      "Platja de l'Ahuir": `Nördlich der Playa de Gandia beherbergt dieser halbwilde, dünengesäumte Strand die offizielle Hundezone der Stadt, an der Hunde schwimmen können. Es ist einer der wenigen Strandbereiche der Region, an denen Hunde im Sommer erlaubt sind.`,
      "Passeig Marítim de Neptú": `Die große Promenade der Playa de Gandia verläuft mehrere Kilometer entlang des Sandes, gesäumt von Palmen und Terrassen. Perfekt für einen angeleinten Spaziergang morgens und abends, wenn die Hitze nachlässt und Terrassen Hunde gerne willkommen heißen.`,
      "Castell de Bairén": `Die Ruinen dieser Burg maurischen Ursprungs überblicken die Bucht von Gandia von einem Hügel zwischen Ort und Strand. Der kurze, aber steile Zugangsweg belohnt Sie mit einem schönen Panorama über das Mittelmeer und die Huerta, angeleint und mit Wasser für Ihren Hund.`,
      "Via Verda del Racó del Duc": `Dieser Grünweg folgt der alten Bahnlinie von Gandia nach Alcoi entlang der Schluchten des Flusses Serpis, durch Tunnel und Orangenhaine. Eine flache, teils schattige Route, ideal für einen langen autofreien Spaziergang mit Hund.`,
      "Col·legiata de Santa Maria": `Gandias gotische Kollegiatkirche, zur Basilika erhoben, wurde von den Borgias verschönert und bleibt das monumentale Herz der Altstadt. Hunde bleiben draußen, doch der angrenzende Platz und der nahe Markt machen den Spaziergang lohnenswert.`,
    },
  },
  ljubljana: {
    history: `Ljubljana, Sloweniens postkartenkleine Hauptstadt, schlängelt sich entlang der smaragdgrünen Ljubljanica unterhalb einer mittelalterlichen Burg auf dem Hügel. Hier stand einst das römische Emona, und Spuren seiner Mauern sind noch zwischen Jugendstilfassaden und den verspielten, drachenbewachten Brücken des Architekten Jože Plečnik zu finden. Mit knapp 300.000 Einwohnern wirkt die Stadt eher wie ein Dorf, seit 2007 für den Autoverkehr gesperrt und rundum von Wald umgeben. Die Slowenen sind ausgesprochen naturverbunden und bekanntermaßen hundevernarrt: Man begegnet ihnen auf Bergpfaden, in Cafés am Flussufer und zusammengerollt unter Tischen preisgekrönter Restaurants. Außerhalb der Stadt sind die Julischen Alpen und das Karstplateau echtes Bären- und Wolfsgebiet und verleihen jedem Freilauf-Traum einen wilden Reiz.`,
    petTips: [`Slowenien verlangt, dass Hunde im öffentlichen Raum an der Leine geführt werden, außer in ausgewiesenen Freilaufzonen; dazu zählen Tivoli, der Pot-Spominov-Weg und bestimmte eingezäunte Parks.`, `Es gelten keine Rasseverbote, doch Halter größerer Hunde müssen in öffentlichen Verkehrsmitteln einen Maulkorb mitführen; die Stadtbusse der LPP nehmen Hunde mit Maulkorb und Leine kostenlos mit.`, `Wer die Julischen Alpen oder die Wälder von Kočevje durchwandern möchte, sollte wissen, dass Slowenien Europas dichteste Braunbärenpopulation sowie Wölfe beherbergt; Hunde an der Leine halten und Grat-Wanderungen in der Dämmerung meiden.`, `Leitungswasser ist ausgezeichnet und überall in der Stadt kostenlos erhältlich; die von Plečnik gestalteten Brunnen am Prešeren-Platz und am Novi Trg sind trinkbar und werden von Einheimischen genutzt, um Hundeflaschen aufzufüllen.`, `Viele Restaurants in Ljubljana sind ausdrücklich haustierfreundlich, achten Sie auf den Aufkleber 'Pes je dobrodošel', besonders in den Vierteln rund um Mestni trg, Krakovo und Trnovo.`],
    practicalInfo: [`EU-Heimtierausweis, ISO-Mikrochip und eine mindestens 21 Tage alte Tollwutimpfung sind erforderlich; Slowenien folgt dem üblichen EU-Einreiserahmen.`, `Der Flughafen Ljubljana (LJU) befördert Haustiere bis 8 kg in der Kabine und darüber im Frachtraum gemäß IATA-Standards; kontaktieren Sie die Fluggesellschaft mindestens 48 Stunden vor dem Flug.`, `Die 24-Stunden-Klinik der Veterinärfakultät (Veterinarska fakulteta) in der Gerbičeva übernimmt Notfälle; die private Klinika Loka ist eine weitere Option außerhalb der regulären Zeiten.`, `Die Sommertemperaturen liegen bei 25-30 °C mit schwülen Phasen, im Winter herrschen durchschnittlich 0 bis -5 °C mit gelegentlichem Schnee; die Bora kann die gefühlte Temperatur stark senken.`, `Taxis (Metro Taxi, Cammeo) nehmen Haustiere mit, wenn dies bei der Buchung angegeben wird; das LPP-Busnetz befördert maulkorbtragende, angeleinte Hunde kostenlos, und die Fernzuggesellschaft SŽ verlangt für kleine Haustiere ein Ticket (etwa 3 €).`],
    sights: {
      "Tivoli Park": `Ljubljanas größte Grünfläche erstreckt sich nur wenige Minuten vom Zentrum entfernt über 500 Hektar, mit von Plečnik gestalteten kastanienbestandenen Promenaden, Rosengärten und einer eigenen Freilaufzone für Hunde nahe dem Teich Tivolski Ribnik. Bewaldete Wege führen hinauf zum Rožnik-Hügel.`,
      "Ljubljana Castle": `Eine drachenthemenreiche mittelalterliche Festung, die den Hügel über der Altstadt krönt. Die Standseilbahn heißt angeleinte Hunde ausdrücklich willkommen, und die äußeren Innenhöfe, Wehrgänge und Waldzugangswege sind haustierfreundlich. Das kostenpflichtige Innenmuseum und der Aussichtsturm lassen keine Hunde zu.`,
      "Ljubljanica Riverbank": `Plečniks für Fußgänger gesperrte Uferpromenaden bilden das Wohnzimmer der Stadt, mit weidenbeschatteten Cafés, der Tromostovje (Dreifachbrücke), der Drachenbrücke und Bootstouren. Wasserzugänge entlang der Ufer lassen Hunde sich im Sommer abkühlen. Der gesamte Abschnitt ist flach und vor den Cafés mit Wassernäpfen gesäumt.`,
      "Rožnik Hill": `Ein bewaldeter, 394 Meter hoher Hügel, der sich direkt aus dem Tivoli Park erhebt. Der Hauptweg steigt in 30 Minuten sanft durch Buchenwald zum Gasthaus Rožnik hinauf, einer klassischen slowenischen Gostilna, die Hunde auf ihrer Terrasse zulässt.`,
      "Metelkova Autonomous Quarter": `Eine ehemalige jugoslawische Kaserne, die zu einem alternativen Kunstviertel wurde, übersät mit Wandgemälden, Skulpturen und Untergrundclubs. Tagsüber ist es eine Freiluftgalerie, die sich hervorragend mit Hund erkunden lässt; nachts wird es zu Ljubljanas lautestem Nachtleben-Viertel, das man mit sensiblen Haustieren besser meidet.`,
      "Ljubljana Marsh (Ljubljansko barje)": `Ein UNESCO-gelistetes Feuchtgebiet südlich der Stadt, berühmt für prähistorische Pfahlbauten und 260 Vogelarten. Kiesdammwege erstrecken sich über Kilometer durch flaches, offenes Land, ideal für lange Läufe mit Hund. Von März bis Juli gilt Leinenpflicht zum Schutz bodenbrütender Vögel.`,
    },
  },
  locarno: {
    history: `Locarno liegt am Ufer des Lago Maggiore und ist die südlichste Stadt der Schweiz, im italienischsprachigen Kanton Tessin. Sein fast mediterranes, mildes und sonniges Klima lässt Palmen, Kamelien und Zitronenbäume entlang der Uferpromenade gedeihen. Im Herzen der Stadt beherbergt die von Arkaden gesäumte Piazza Grande jeden August das berühmte Filmfestival von Locarno, dessen riesige Leinwand die Sommernächte erleuchtet. Über den Dächern wacht seit dem 15. Jahrhundert die Wallfahrtskirche Madonna del Sasso über die Stadt, erreichbar per Standseilbahn oder über einen schattigen Pilgerweg. Seit jeher ein Handelsknotenpunkt zwischen Italien und den Alpen, lebt Locarno heute vom Tourismus, vom See und den wilden Tälern in seiner Umgebung, etwa dem smaragdgrünen Verzasca. Für den Reisenden mit Hund ist es ein sanfter Ausgangspunkt, der Spaziergänge am See, alpine Seilbahnen und Tessiner Dörfer miteinander verbindet.`,
    petTips: [`In den Schweizer öffentlichen Verkehrsmitteln reist der Hund zum halben Fahrpreis; auf manchen Regionalbussen und -zügen im Tessin kann ein Maulkorb verlangt werden, halten Sie also einen bereit.`, `Saisonaler Hinweis: Die Sommer am See sind warm und feucht (30 °C und mehr); gehen Sie früh oder spät mit dem Hund spazieren, und beachten Sie, dass im August das Filmfestival die Piazza Grande mit dichten Menschenmassen füllt, abends besser meiden.`, `Zum Abkühlen des Hundes eignen sich die ruhigeren Lidos und die Mündung der Verzasca bei Tenero besser; das bewachte Lido der Stadt kann Hunden im Sommer den Zutritt verwehren.`, `Die Cardada-Seilbahn nimmt Hunde gegen einen kleinen Aufpreis mit, und die Höhenwege bieten willkommene Kühle, wenn es am Seeufer schwül wird.`, `Im Verzasca-Tal sollten Sie den Hund nahe dem smaragdgrünen Fluss anleinen: starke Strömungen, rutschige Felsen und ein geschütztes Naturgebiet.`],
    practicalInfo: [`Die Schweiz liegt außerhalb der EU, akzeptiert aber EU-kompatible Heimtierdokumente: Ein EU-Heimtierausweis (oder eine EU-Gesundheitsbescheinigung nach EU-Muster) mit gültiger Tollwutimpfung und ISO-Mikrochip wird an der Grenze anerkannt.`, `Allgemeine Notrufnummer: 112 (144 für medizinische Einsätze); lassen Sie sich zum nächsten diensthabenden Tierarzt verbinden.`, `Anreise: Locarno hat keinen eigenen Flughafen; die nächstgelegenen sind Mailand-Malpensa (rund 85 km) und Lugano, mit häufigen Zugverbindungen über Bellinzona ins Schweizer Netz.`, `Sprache und Währung: Im Tessin wird Italienisch gesprochen, und die Währung ist der Schweizer Franken (CHF), nicht der Euro, wobei viele Geschäfte Euro akzeptieren.`, `Hunde reisen in Schweizer öffentlichen Verkehrsmitteln zum halben Fahrpreis; auf Promenaden, Seilbahnen und Booten wird eine Leine erwartet, und manche Lidos schließen Hunde im Hochsommer aus.`],
    sights: {
      "Piazza Grande": `Der große, von Arkaden gesäumte Platz im Herzen der Stadt, Schauplatz des Filmfestivals von Locarno jeden August. Angeleinte Hunde flanieren außerhalb der Stoßzeiten gerne hier, zwischen Cafés und lombardischen Fassaden.`,
      "Madonna del Sasso": `Die Wallfahrtskirche aus dem 15. Jahrhundert thront über der Stadt, erreichbar per Standseilbahn oder Pilgerweg, mit Panoramablick über den See. Angeleinte Hunde sind auf den Terrassen und in den Gärten willkommen; das Innere der Kirche bleibt ihnen verwehrt.`,
      "Lungolago e Parco delle Camelie": `Die Uferpromenade und der Kamelienpark, bepflanzt mit Tausenden Sorten, die im Frühling blühen. Ideal für einen angeleinten Spaziergang in der kühlen Morgenluft mit Blick auf den Lago Maggiore.`,
      "Cardada-Cimetta": `Die Seilbahn steigt von der Madonna del Sasso zu den Alpwiesen und Aussichtspunkten von Cardada und Cimetta auf. Hunde dürfen gegen einen kleinen Aufpreis mitfahren, und die hochgelegenen Wege bleiben im Sommer angenehm kühl.`,
      "Lago Maggiore": `Die Linienschiffe, die den Lago Maggiore in Richtung Ascona, der Brissago-Inseln oder des benachbarten Italiens durchqueren. Angeleinte Hunde reisen an Bord mit, oft zu einem ermäßigten Ticket.`,
      "Valle Verzasca": `Das wilde Tal nördlich von Locarno, berühmt für seinen smaragdgrünen Fluss und die römische Brücke von Lavertezzo. Angeleinte Wanderungen führen an den Ufern entlang; die Strömung ist stark und die Felsen sind rutschig.`,
    },
  },
  london: {
    history: `Londons Geschichte reicht vom römischen Londinium bis zur heutigen Weltmetropole mit knapp 9 Millionen Einwohnern, und seine Zuneigung zu Hunden ist ebenso tief verwurzelt. Großbritannien ist bekanntermaßen eine hundeliebende Nation mit schätzungsweise 13 Millionen Haushunden, und allein London beherbergt mehr als eine Million davon. Königliche Parks wie der Hyde Park und die Hampstead Heath erlauben seit über einem Jahrhundert Spaziergänge ohne Leine, und in Pubs in der ganzen Stadt hängen stolz Schilder mit der Aufschrift 'dogs welcome'. Seit dem Brexit können EU-Besucher nicht mehr mit dem EU-Heimtierausweis nach Großbritannien einreisen und müssen stattdessen ein Animal Health Certificate (AHC) vorweisen, das innerhalb von 10 Tagen vor der Reise ausgestellt wurde. Hunde benötigen zudem eine Bandwurmbehandlung 24-120 Stunden vor der Ankunft. Trotz des Papierkrams bleibt London eine der lohnendsten Städte Europas, um sie mit einem vierbeinigen Begleiter zu erkunden.`,
    petTips: [`Hunde reisen im gesamten TfL-Netz (U-Bahn, Overground, Busse, DLR) kostenlos, müssen aber auf Rolltreppen getragen oder kurz angeleint werden, sonst kann das Personal die Mitnahme verweigern.`, `Black Cabs (lizenzierte Hackney Carriages) müssen Hunde gesetzlich kostenlos befördern; Uber und private Mietwagenfirmen können ablehnen, also bei der Buchung nachfragen.`, `Die meisten Londoner Pubs heißen Hunde im Barbereich willkommen, aber nicht im Speiseraum, achten Sie auf den 'dog-friendly'-Aufkleber an der Tür oder prüfen Sie Doggie Pubs UK.`, `Für EU-Einreisende nach dem Brexit: Ihr Animal Health Certificate darf bei der Einreise nicht älter als 10 Tage sein, und Sie müssen einen ausgewiesenen Traveller Point of Entry wie St Pancras (Eurostar) oder Heathrow nutzen.`, `Die Hampstead Heath hat drei unumzäunte Schwimmteiche, in denen Hunde in bestimmten Bereichen erlaubt sind; beachten Sie die Beschilderung, denn der gemischte Badeteich ist im Sommer für Hunde gesperrt.`],
    practicalInfo: [`Hauptflughäfen: Heathrow (LHR) und Gatwick (LGW) sind offizielle Einreisepunkte für Haustiere; Hunde dürfen nicht in der Kabine ankommen und müssen als deklarierte Fracht über IAG Cargo oder ähnliche Dienste reisen.`, `Eurostar nimmt KEINE Hunde mit außer registrierten Assistenzhunden; die einzige Bahnoption von Paris/Brüssel mit Haustier führt über Folkestone (Eurotunnel Le Shuttle mit dem Auto).`, `Beste Reisezeit: April-Juni und September-Oktober bieten milde Temperaturen und eher trockenes Wetter; meiden Sie August wegen der Menschenmassen und Juli wegen gelegentlicher Hitzewellen über 30 °C.`, `24/7-Notfalltierarzt: Royal Veterinary College Hospital Camden, +44 20 7387 8134, oder The London Vet Clinic in Belgravia für zentrale Notfälle.`, `Bußgelder für Hundekot können in London bis zu 150 £ betragen (Bußgeldbescheid), und Bezirke wie Westminster kontrollieren aktiv; Kotbeutel sind jederzeit Pflicht.`],
    sights: {
      "Hyde Park": `Der 142 Hektar große königliche Park im Zentrum Londons erlaubt Hunden auf fast dem gesamten Gelände Freilauf, außer am Diana Memorial Fountain und in den Blumengärten. Ein klassischer Morgenspaziergang entlang der Serpentine.`,
      "Hampstead Heath": `Eine wilde, 320 Hektar große Heide im Norden Londons, bei Hundehaltern beliebt, mit Wäldern, Wiesen und Teichen. Hunde streifen frei über die meisten Wege, und der Parliament Hill bietet einen der besten Skyline-Blicke der Stadt.`,
      "Notting Hill & Portobello Road": `Pastellfarbene Stadthäuser, unabhängige Cafés und der berühmte samstägliche Antiquitätenmarkt machen Notting Hill zu einer Freude für Hundespaziergänger. Viele Cafés entlang der Portobello Road stellen draußen Wassernäpfe auf und heißen angeleinte Hunde auf ihren Terrassen willkommen.`,
      "Tower of London exterior": `Hunde dürfen diese Festung aus dem 11. Jahrhundert nicht betreten, aber die Gärten am Tower Hill und der nahe Themseweg bieten einen reizvollen Spaziergang von außen. Die Aussicht auf die Tower Bridge ist von draußen ohnehin fast schöner.`,
      "Regent's Canal (Little Venice to Camden)": `Ein flacher, 5 km langer Treidelpfad verbindet Little Venice mit Camden Lock entlang der Grenzen des Regent's Park. Hausboote, Weiden und zahlreiche hundefreundliche Pubs machen ihn zu einem von Londons charmantesten Spaziergängen.`,
      "Greenwich Park": `Londons ältester eingefriedeter königlicher Park steigt zum Royal Observatory und dem Nullmeridian an. Hunde sind nahe dem Hirschgehege an der Leine willkommen und andernorts frei laufend, mit Panoramablick über Canary Wharf.`,
    },
  },
  'los-angeles': {
    history: `Los Angeles erstreckt sich über fast 1.300 km² zwischen dem Pazifik und den San Gabriel Mountains und ist nach Einwohnerzahl die zweitgrößte Stadt der USA. 1781 als spanisches El Pueblo de Nuestra Señora la Reina de los Ángeles gegründet, ging es 1848 von Mexiko an die Vereinigten Staaten über, bevor das Öl und dann Anfang des 20. Jahrhunderts Hollywood die Stadt zur Filmhauptstadt der Welt machten. Eine mosaikartige Stadt ohne echtes Zentrum, die eine Hochhaus-Innenstadt, die Hügel des Griffith Park, die Strände von Venice und Santa Monica sowie ein Labyrinth aus Freeways miteinander verwebt, das einem klarmacht, dass hier fast alles mit dem Auto erledigt wird. Ihr mediterranes Klima bringt fast ständigen Sonnenschein, aber auch glühend heiße Sommer und eine Waldbrandsaison. Für den Reisenden mit Hund bietet Los Angeles weitläufige Stadtparks und Wanderwege, sofern man Hitze und eine für das Auto gebaute Stadt einplant.`,
    petTips: [`Die meisten Strände von LA County verbieten Hunde, einschließlich des Sandes von Venice und Santa Monica; die seltene Ausnahme ist Rosie's Dog Beach in Long Beach, der einzige offizielle Hundestrand des Countys.`, `Saisonaler Hinweis: Sommer und früher Herbst bringen extreme Hitze und Rauch aus der Waldbrandsaison, der die Lungen von Hunden schädigt; früh morgens oder abends spazieren gehen, Luftqualitätswarnungen beachten und den Belag mit der Hand testen: zu heiß für die Handfläche bedeutet zu heiß für Pfoten.`, `Die LA-Metro-Bahnen und -Busse lassen nur Assistenzhunde und kleine Haustiere in einer Transportbox zu; große Hunde sind nicht erlaubt, planen Sie also mit Auto oder einem hundefreundlichen Fahrdienst.`, `Griffith Park und Runyon Canyon bieten kilometerlange Wege (angeleint, im Runyon Canyon teilweise ohne Leine), aber nehmen Sie reichlich Wasser mit: Die Bergkämme bieten kaum Schatten.`, `Auf den Promenaden von Venice und Santa Monica müssen Hunde angeleint bleiben und sind vom Sand verbannt; bleiben Sie auf dem Boardwalk, um Bußgelder zu vermeiden.`],
    practicalInfo: [`Dies ist ein US-Inlandsziel: Der EU-Heimtierausweis gilt hier nicht; aus dem Ausland prüfen Sie die aktuellen CDC-Regeln für die Einreise von Hunden in die USA sowie die Haustierrichtlinien Ihrer Fluggesellschaft.`, `Notrufnummer: 911 für Polizei, Feuerwehr und Rettungsdienst; lassen Sie sich zur nächsten 24-Stunden-Tierklinik verbinden.`, `Anreise und Fortbewegung: Der Flughafen Los Angeles International (LAX) ist das Haupttor; die Stadt ist stark autoabhängig, und die LA Metro schränkt große Hunde ein, sodass ein Mietwagen oft notwendig ist.`, `Klima: mild und sonnig die meiste Zeit des Jahres, aber die Sommer sind heiß und trocken mit einer Waldbrandsaison im Spätsommer und Herbst; heißer Asphalt und Rauch sind die Hauptgefahren für Hunde.`, `Es gelten Leinenpflichten in Parks und an Stränden; Hunde sind an fast allen Stränden von LA County vom Sand verbannt, Rosie's Dog Beach in Long Beach ist die Hauptausnahme.`],
    sights: {
      "Griffith Park": `Einer der größten Stadtparks Nordamerikas, dessen Hügel von Wegen durchzogen sind. Hunde sind auf den angeleinten Wanderwegen willkommen, im Sommer sollten Wasser und Schatten eingeplant werden.`,
      "Griffith Observatory": `Das Art-déco-Observatorium auf dem Mount Hollywood bietet Ausblicke über die Stadt und das Hollywood-Zeichen. Angeleinte Hunde sind auf den Außenrasenflächen und Terrassen erlaubt, aber nicht im Gebäude.`,
      "Runyon Canyon": `Die berühmteste Wanderschlucht der Stadt, bei Hundehaltern beliebt. Auf einem Teil der Wege dürfen Hunde unter Stimmkontrolle ohne Leine laufen; es gibt kaum Schatten, also Wasser mitnehmen.`,
      "Venice Beach Boardwalk": `Die berühmte Uferpromenade, gesäumt von Straßenkünstlern und Geschäften. Angeleinte Hunde sind auf dem Boardwalk erlaubt, aber vom Sand verbannt, wie an den meisten Stränden des Countys.`,
      "Santa Monica Pier": `Der ikonische Pier mit seinem Vergnügungspark, verlängert durch eine breite Küstenpromenade. Angeleinte Hunde können hier entlangschlendern, doch der Sandstrand bleibt ihnen verwehrt.`,
      "Downtown Arts District & Grand Park": `Das Arts District und der städtische Grand Park zwischen der Innenstadt und dem Rathaus. Von Wandgemälden gesäumte Straßen, Straßencafés und Rasenflächen sind an der Leine begehbar.`,
    },
  },
  lucca: {
    history: `Lucca, eine toskanische Stadt mit rund 89.000 Einwohnern, wurde 180 v. Chr. als römische Kolonie (Luca) an der Via Cassia gegründet. Dank ihres Seidenmonopols im 13. Jahrhundert wurde sie zu einem mächtigen mittelalterlichen Handelszentrum und zeichnete sich vor allem durch ihren einzigartigen politischen Weg aus: eine unabhängige Republik von 1119 bis 1799, nie vom mediceischen Toskana absorbiert, einzigartig unter den toskanischen Städten. Diese Unabhängigkeit brachte ihr eine außergewöhnliche Krone ein: 4,2 km bastionierte Renaissancemauern (1545-1650), zu den besterhaltenen Italiens zählend, im 19. Jahrhundert in eine baumgesäumte öffentliche Promenade verwandelt. Das Oval der Piazza dell'Anfiteatro folgt den Fundamenten des römischen Amphitheaters aus dem 2. Jahrhundert, die romanisch-pisanische Kathedrale San Martino beherbergt den Volto Santo, und der Guinigi-Turm (14. Jh.) trägt Steineichen auf seinem Dach, das Wahrzeichen der Stadt. Lucca ist zudem der Geburtsort von Giacomo Puccini. Für Reisende mit Hund ist es wohl die einfachste Stadt Italiens: autofreies Zentrum innerhalb der Mauern (ZTL), 4,2 km flache Wallanlagen als täglicher Spaziergang, entspannte Trattoria-Kultur und die Hundestrände der Versilia nur 30 Minuten mit dem Zug entfernt.`,
    petTips: [`Das ummauerte Zentrum ist eine ZTL (Zone mit eingeschränktem Verkehr), praktisch autofrei, ideal für stadtnervöse Hunde.`, `Die 4,2 km lange Runde auf den Stadtmauern ist der wichtigste Hundespaziergang: flach, grasbewachsen, schattig. Auf Radfahrer achten.`, `Trenitalia-Regionalzug nach Pisa (30 Min.) oder Florenz (1 Std. 20 Min.): kleine Hunde in Transportboxen kostenlos, größere Hunde Kindertarif plus Maulkorb.`, `Hundestrände der Versilia 20-30 Min. mit dem Direktzug, Lido di Camaiore und Viareggio ganzjährig ausgeschildert.`, `Lucca Comics & Games (letzte Oktoberwoche) überflutet die Stadt mit 250.000 Besuchern, Hotels Monate im Voraus buchen oder meiden.`],
    practicalInfo: [`Nächstgelegener 24/7-Notfalltierarzt: Ospedale Veterinario Pisa San Concordio, +39 050 985 2222 (30 Min. mit dem Auto).`, `Zentrale Tagesklinik: Clinica Veterinaria Lucca Centro, Via dei Macelli 60, +39 0583 491 030`, `Trenitalia-Regionalzug ab Pisa Centrale: 30 Min.; ab Florenz SMN: 1 Std. 20 Min.`, `Nächstgelegener Flughafen: Pisa PSA (30 Min. mit Zug oder Taxi, Festpreis 50 EUR); Florenz FLR (1 Std. mit dem Auto).`],
    sights: {
      "Le Mura (Renaissance Walls)": `4,2 km perfekt erhaltene Renaissancemauern (1545-1650), in eine baumgesäumte Promenade verwandelt. Flach, grasbewachsen, verkehrsfrei, Italiens sinnbildlichste Hundespazier-Promenade.`,
      "Piazza dell'Anfiteatro": `Ovaler Platz entlang der Fundamente des römischen Amphitheaters aus dem 2. Jahrhundert. Vier schmale Torbögen als einzige Zugänge. Angeleinte Hunde rund um die Uhr willkommen, Cafés säumen den Rand.`,
      "Guinigi Tower": `Backsteinturm aus dem 14. Jahrhundert mit Steineichen in einem Hängegarten auf dem Dach. Der Aufstieg (230 Stufen) lässt keine Hunde zu; die Straße und der Platz an der Basis sind zugänglich.`,
      "Cattedrale di San Martino": `Romanisch-pisanische Kathedrale, 1063 begonnen, mit ihrer berühmten asymmetrischen Fassade. Hunde nicht im Inneren erlaubt (außer Assistenzhunde), doch das rechte Portal mit seinem geschnitzten Labyrinth aus dem 13. Jahrhundert ist ein schönes Fotomotiv im Freien.`,
      "Orto Botanico": `2 ha großer botanischer Garten, 1820 von Maria Luisa di Borbone gegründet. Angeleinte Hunde willkommen, selten für einen italienischen botanischen Garten. Die Libanonzeder von 1822 ist das Prunkstück.`,
      "Versilia Bau-Beaches": `Hundestrände an der toskanischen Küste, 25-30 km westlich. Lido di Camaiore und Viareggio haben jeweils ganzjährig ausgeschilderte Bau-Beach-Zonen, in 20-30 Min. mit dem Zug erreichbar.`,
    },
  },
  lucerne: {
    history: `Luzern liegt am nordwestlichen Zipfel des Vierwaldstättersees, zu Füßen von Pilatus und Rigi. Im 9. Jahrhundert als Hafenort am See gegründet, blühte die Stadt nach der Öffnung des Gotthardpasses im 13. Jahrhundert auf und wurde 1332 einer der drei Gründungskantone der Schweizerischen Eidgenossenschaft. Heute ist die Stadt mit rund 82.000 Einwohnern (220.000 in der Agglomeration) die Tourismushauptstadt der Zentralschweiz und eine der meistbesuchten Städte des Landes. In Sachen Hund verbindet Luzern schweizerische Rechtsstrenge (ISO-Mikrochip-Pflicht, kantonale Registrierung, Hundesteuer) mit einer überraschend entspannten Alltagskultur: Einheimische nehmen ihre Hunde überallhin mit, auf Seeterrassen, SGV-Raddampfer, die Zahnradbahnen von Pilatus und Rigi, in Kneipen, Geschäfte. Die schweizweite Hunde-Tageskarte für CHF 25 macht Mehrfach-Ausflüge auf Berge und See mühelos. Die einzigen Einschränkungen sind Leinenpflicht in Wäldern vom 1. April bis 31. Juli (Brutzeit), ein Hundeverbot innerhalb der Bade-Perimeter von Lido und Ufschötti vom 1. Mai bis 30. September sowie Altstadtpflaster, das in der Sommersonne aufheizt.`,
    petTips: [`Die Hunde-Tageskarte für CHF 25 ('Tageskarte für Hunde') gilt den ganzen Tag in jedem SBB-Zug, Bus, SGV-Schiff und den meisten Bergzahnradbahnen im ganzen Land, Europas bester Deal, um Luzern, Pilatus, Rigi und den See zu kombinieren.`, `Kleine Hunde (unter 30 cm Schulterhöhe) in einer geschlossenen Transportbox reisen im gesamten Schweizer Netz kostenlos, ohne Ticket.`, `Die kantonale Leinenpflicht gilt in Wäldern vom 1. April bis 31. Juli (Brutzeit bodenbrütender Vögel); Bußgelder für unangeleinte Hunde beginnen bei CHF 100.`, `Das Altstadtpflaster erreicht an August-Nachmittagen über 50 °C, gehen Sie früh vor 10:00 Uhr oder nach 18:00 Uhr spazieren, oder bleiben Sie auf den bewaldeten Sonnenberg-Wegen.`, `Hunde sind innerhalb der Bade-Perimeter von Lido und Ufschötti vom 1. Mai bis 30. September verboten; ganzjährig freies Schwimmen bei Tribschen und am Würzenbach-Ufer.`],
    practicalInfo: [`Die Schweiz gehört nicht zur EU, akzeptiert aber den EU-Heimtierausweis, ISO-Mikrochip, Tollwutimpfung mindestens 21 Tage alt, keine Bandwurmbehandlung erforderlich (anders als in Großbritannien).`, `Der Flughafen Zürich (ZRH, 50 Minuten mit dem Direktzug) ist die wichtigste Drehscheibe für die Einreise von Haustieren in die Zentralschweiz; Hunde in der Kabine sind bei den meisten Fluggesellschaften bis 8 kg zugelassen.`, `In Luzern selbst gibt es keine 24-Stunden-Tierklinik: nächtliche Notfälle laufen über den regionalen Bereitschaftsdienst (Anrufbeantworter der Tierklinik Obergrund) oder das AniCura Tierspital Zürich (50 Min. mit dem Auto, 24/7 geöffnet).`, `Klima: milde Sommer 18-25 °C mit gelegentlichen Gewittern, kalte Winter -2 bis +5 °C mit häufigem Schnee von Dezember bis Februar; Hochnebel kann die Stadt im Herbst tagelang einhüllen.`, `Tierarztkosten gehören zu den höchsten Europas: Konsultation CHF 80-120, Zuschlag außerhalb der Öffnungszeiten CHF 200-400, eine Reiseversicherung mit Tierarztdeckung wird dringend empfohlen.`],
    sights: {
      "Kapellbrücke": `Die überdachte Holzbrücke aus dem 14. Jahrhundert, die im Zickzack über die Reuss führt, ist Luzerns Wahrzeichen und Europas älteste erhaltene Holzbrücke mit Sprengwerk. Angeleinte Hunde überqueren sie ganzjährig; tragen Sie kleine Hunde an geschäftigen Sommernachmittagen, wenn die Brücke voller Reisegruppen ist.`,
      "Löwendenkmal": `Der 'sterbende Löwe', 1820 von Bertel Thorvaldsen direkt in den Sandsteinfelsen gehauen, erinnert an die 760 Schweizergardisten, die 1792 bei der Verteidigung der Tuilerien starben. Mark Twain nannte ihn 'das traurigste und bewegendste Stück Stein der Welt'. Im Freien, kostenlos, hundefreundlich mit kleinem Spiegelteich und schattigen Bänken.`,
      "Museggmauer": `Die 870 Meter lange mittelalterliche Stadtmauer nördlich der Altstadt mit neun Türmen, darunter der Zytturm, dessen Uhr von 1535 eine Minute vor allen anderen in der Stadt schlägt. Drei Türme sind von April bis Oktober begehbar; der Männliturm hat die breiteste Treppe und ist am einfachsten mit einem kleinen angeleinten Hund zu erklimmen.`,
      "Sonnenberg": `Ein 745 Meter hoher bewaldeter Grat direkt über der Stadt, durchzogen von 15 km Forstwegen und Panoramapfaden. Die Sonnenbergbahn von Kriens nimmt angeleinte Hunde mit und bringt Wanderer samt Hund in fünf Minuten auf den Gipfel für einen langen Waldabstieg zurück nach Luzern.`,
      "Pilatus Kulm": `Der ikonische 2.132 m hohe Alpengipfel über Luzern, erreichbar per Seilbahn ab Kriens (ganzjährig, Hunde kostenlos) oder mit der steilsten Zahnradbahn der Welt ab Alpnachstad (Mai-November, halber Fahrpreis). Panoramawege am Gipfel und Wassernäpfe auf der Terrasse, an klaren Tagen sind 73 Alpengipfel sichtbar.`,
      "Rigi Kulm": `Die 'Königin der Berge' auf 1.798 m, erreichbar mit Europas erster Bergzahnradbahn (1871) ab Vitznau oder Goldau. Hunde fahren ganzjährig kostenlos mit Zahnradbahn, Seilbahn und Gondel. Breite, flache Panoramawege am Gipfel, ideal für ältere oder weniger mobile Hunde.`,
    },
  },
  lugano: {
    history: `Lugano ist die größte Stadt im italienischsprachigen Kanton Tessin, am Ostufer des Luganersees zu Füßen von Monte San Salvatore und Monte Brè gelegen. Mit rund 63.000 Einwohnern und einer Agglomeration von 150.000 ist sie die südlichste Großstadt der Schweiz und die einzige größere, in der Italienisch die Alltagssprache ist, eine einzigartige kulturelle Enklave, in der lombardische Architektur, Palmen, Zitrusfrüchte und mediterranes Licht auf Schweizer Präzision treffen. Historisch ein lombardisches Bistum, trat sie 1798 der Schweizerischen Eidgenossenschaft bei und wuchs durch den Belle-Époque-Tourismus. Heute ist Lugano ein Finanzzentrum (nach Zürich und Genf das drittgrößte der Schweiz), ein Kunstzentrum mit dem Kulturkomplex LAC und dank seines milden Klimas, Seeuferpromenaden, hundetauglicher Standseilbahnen und einer italienisch-tessinischen Restaurantkultur, die Haustiere wirklich willkommen heißt, ein ganzjährig hundefreundliches Reiseziel. Für Einwohner ist eine schweizerische Hundehaftpflichtversicherung Pflicht, und die Hundegesetze des Kantons Tessin sind milder als in den deutschsprachigen Kantonen (keine Maulkorbpflicht). Die Kombination aus See, Bergen, italienischem Charme und Schweizer Infrastruktur macht Lugano zu einer der unkompliziertesten großen Schweizer Städte für einen Besuch mit Hund.`,
    petTips: [`Die Schiffe auf dem Luganersee (Società Navigazione del Lago di Lugano) befördern angeleinte Hunde ganzjährig KOSTENLOS. Die offenen Heckdecks sind die besten Hundeplätze; die Tageskarte (CHF 60) erlaubt es, Gandria, Morcote und Campione ohne zusätzliche Hundetickets zu kombinieren.`, `Der Kanton Tessin verzichtet auf die österreichisch anmutende Maulkorbpflicht, die meisten TPL-Busfahrer und SBB-Schaffner verlangen im Tessin selbst keinen Maulkorb für große Hunde. Führen Sie dennoch einen mit für grenzüberschreitende italienische Züge (Trenord) und weiterführende deutschschweizer Züge, wo strengere Regeln gelten.`, `Luganos mediterrane Sommer (30-34 °C, über 65 % Luftfeuchtigkeit) sind für Hunde deutlich unangenehmer als die trockenen Alpenstädte. Gehen Sie im Juli und August vor 09:00 oder nach 19:00 Uhr spazieren; das Kopfsteinpflaster rund um die Piazza della Riforma kann mittags Pfoten verbrennen. Nutzen Sie die Monte-Brè-Standseilbahn, um der Hitze zu entkommen.`, `Der Grenzübertritt nach Italien (Como, Mailand) ist innerhalb des Schengen-Raums problemlos, doch die italienischen Verkehrsregeln unterscheiden sich: In italienischen Bussen sind große Hunde maulkorb- und leinenpflichtig; bei Trenord reisen Hunde unter 10 kg in der Transportbox kostenlos, größere Hunde zum halben Fahrpreis. Führen Sie Ihren EU-Heimtierausweis über die Grenze mit.`, `Speichern Sie +41 91 921 30 30 (Clinica Veterinaria Lugano, 24/7) und Rega 1414 (Schweizer Rettungsflugwacht, Hunde für Mitglieder inbegriffen, CHF 40/Jahr). Luganos ansässige Notfallklinik ist das Referenzzentrum des Kantons mit Röntgen, CT, Ultraschall und Operationskapazität.`],
    practicalInfo: [`Nächstgelegener internationaler Flughafen: Mailand Malpensa (MXP, 80 km / 1,5 Std. mit dem Auto oder direktem ALSA/FlixBus-Shuttle). Lugano-Agno (LUG) bietet nur eingeschränkten Betrieb. Zürich (ZRH) liegt rund 2 Std. mit dem direkten SBB-Zug entfernt.`, `Direkte SBB-Züge aus Zürich (~2 Std.), Genf (~3,5 Std. über Mailand oder Zürich-Anschluss) und italienische Trenord-Züge aus Mailand Centrale (~1 Std.). Kleine Hunde in Transportbox kostenlos; größere Hunde angeleint zum halben Erwachsenenpreis. Der Swiss Travel Pass lässt Hunde mit einem zahlenden Erwachsenen kostenlos reisen.`, `Lugano ist offiziell italienischsprachig; Italienisch ist die Alltagssprache. Englisch wird in Tourismus- und Geschäftsvierteln weit verbreitet genutzt; Deutsch und Französisch sind in Hotels und zentralen Restaurants verfügbar. Tierärztliche Dienste erfolgen meist zunächst auf Italienisch mit gutem Englisch.`, `Für Einwohner ist eine schweizerische Hundehaftpflichtversicherung Pflicht. Besuchern wird dringend eine Reisetierversicherung mit Bergrettungsdeckung empfohlen; eine Rega-Mitgliedschaft (CHF 40/Jahr) fliegt Hunde zusammen mit ihren Haltern aus.`, `EU-/Schweizer Heimtierausweis, Mikrochip und Tollwutimpfung sind erforderlich. Britische Reisende benötigen seit dem Brexit ein Animal Health Certificate (AHC), ausgestellt von einem amtlichen Tierarzt innerhalb von 10 Tagen vor der Reise.`],
    sights: {
      "Parco Ciani": `Luganos zentraler, 63.000 m² großer öffentlicher Park am Seeufer, mit ausgewachsenen Platanen, jahrhundertealten Magnolien und einer eingezäunten Area cani im östlichen Teil. Angeleinte Hunde überall willkommen; der tägliche Treffpunkt der Hundehalter der Stadt.`,
      "Lakeside Promenade Lugano-Paradiso": `Ein 3 km langer gepflasterter Uferweg von Luganos Piazza Manzoni südwärts bis zum Stadtteil Paradiso, mit durchgehendem Seeblick, Palmen und Kunstinstallationen. Angeleinte Hunde überall willkommen; mehrere Kiesbuchten lassen Hunde die Pfoten eintauchen.`,
      "Monte Brè Funicular": `Die 12-minütige Standseilbahn von Cassarate zum 925 m hohen Gipfel nimmt angeleinte Hunde mit (CHF 5 retour). Die Gipfelterrasse bietet ein 360°-Panorama, und das hundefreundliche Restaurant heißt angeleinte Hunde willkommen. Die Luft am Gipfel ist 5-8 °C kühler als in der Stadt.`,
      "Sentiero dell'Olivo to Gandria": `Ein 3,5 km langer Uferpfad von Castagnola zum malerischen Fischerdorf Gandria, vorbei an 18 Lehrtafeln über den mediterranen Olivenanbau. Fast eben, teilweise schattig, angeleinte Hunde willkommen. Das Seeschiff zurück (Hunde kostenlos) schließt einen perfekten Hundetag-Rundweg ab.`,
      "Lido di Caslano Dog Beach": `Der einzige offiziell ausgewiesene Hundeschwimmstrand auf Schweizer Seite des Luganersees, eine kleine, eigene Kiesbucht mit flachem Ufer, getrennt vom Hauptbadebereich der Menschen. Ganzjährig geöffnet, freier Eintritt. Erreichbar mit dem TPL-Postbus 431 (25 Min. ab Zentrum Lugano).`,
      "Morcote Lakeside Village": `Oft als schönstes Dorf der Schweiz bezeichnet, liegt Morcote am südlichen Zipfel des Luganersees mit Häusern mit Terrakottadächern, die sich im Wasser spiegeln. Erreichbar mit dem Seeschiff (25 Min., Hunde kostenlos); das gesamte Fußgängerdorf heißt angeleinte Hunde willkommen, und die meisten Terrassenrestaurants akzeptieren sie.`,
    },
  },
  luxembourg: {
    history: `Luxemburg-Stadt ist die Hauptstadt des Großherzogtums Luxemburg, eines souveränen Staates seit 1815 und eines der Gründungsmitglieder der Europäischen Union. Auf einem Felsvorsprung am Zusammenfluss von Alzette und Pétrusse erbaut, wurde die Festungsstadt als 'Gibraltar des Nordens' bezeichnet, und ihre Befestigungsanlagen stehen seit 1994 auf der UNESCO-Liste. Mit rund 130.000 Einwohnern innerhalb der Stadtgrenzen (50 % der Bevölkerung nicht luxemburgisch, einer der internationalsten Anteile Europas) ist sie zudem ein bedeutendes Finanzzentrum. In Sachen Hund verbindet Luxemburg deutsche Strenge (EU-Heimtierausweis, Tollwutimpfung) mit französischer Lockerheit (Hunde oft in Restaurants willkommen). Weltweit einzigartig: Seit dem 1. März 2020 sind alle öffentlichen Verkehrsmittel für jedermann kostenlos, Haustiere eingeschlossen, Busse, Trams, CFL-Züge, kein Ticket nötig. Die Stadt verfügt über neun eingezäunte Hundeauslaufflächen, zwei 24-Stunden-Tierkliniken und Europas strengste Tierschutzgesetze.`,
    petTips: [`Kostenlose öffentliche Verkehrsmittel seit 2020, Hunde fahren kostenlos in allen Bussen, Trams und CFL-Landeszügen mit, kein Ticket nötig.`, `9 eingezäunte städtische Hundeauslaufflächen, kartiert auf vdl.lu unter 'Vivre en ville → Enclos réservé aux chiens'; die beiden im Parc de la Pétrusse liegen am zentralsten.`, `24/7-Notfalltierarzt: Clinique Vétérinaire Bereldange, 73 rue de Bridel, +352 33 99 28; wählen Sie 112, falls die diensthabende Klinik der nationalen Bereitschaft näher liegt.`, `Außerhalb der Auslaufflächen und Waldwege gilt in der ganzen Stadt Leinenpflicht, 49 € Bußgeld für einen unangeleinten Hund auf der Straße.`, `Der kostenlose Pfaffenthal-Lift von der Ville-Haute ins Tal ist für kleine oder ältere Hunde viel einfacher als die steilen Festungstreppen.`],
    practicalInfo: [`Der Flughafen Findel (LUX) liegt 6 km vom Zentrum entfernt, kostenloser Bus 16 zum Hamilius in 25 Minuten; Tram und dann CFL erreichen den Rest des Landes.`, `Hundefreundliche Hotelpreise: ab 130 € pro Nacht für 4*, durchschnittlicher Haustierzuschlag 20-30 € pro Nacht; die Hotelkosten liegen höher als im nahen Brüssel oder Trier.`, `Gemäßigtes kontinentales Klima: kühle Sommer (19 °C im Juli), nasse, aber milde Winter (1,5 °C im Januar); die Täler von Pétrusse und Alzette sind im Sommer 2-3 °C kühler als die Ville-Haute.`, `Pawshake.com und PetBacker dominieren Betreuung und Gassi-Service; rechnen Sie mit 15-20 € pro Spaziergang, 30-45 € für einen ganzen Tag, 40-55 € pro Nacht, Preise über Brüssel, ähnlich wie Genf.`, `Luxemburg ist 2 Std. 30 Min. von Brüssel mit dem Zug entfernt, 1 Std. 45 Min. von Trier und 1 Std. 30 Min. von Metz, ein idealer Ausgangspunkt für eine Hunderundreise durch Belgien, Deutschland und Frankreich.`],
    sights: {
      "Chemin de la Corniche": `600 Meter lange Klippenpromenade über dem Alzette-Tal, genannt 'Europas schönster Balkon'. Panoramablick auf Grund, Clausen und die Bockfestung; angeleinte Hunde ganzjährig willkommen, Tag und Nacht.`,
      "Parc de la Pétrusse": `30 Hektar großer Flusstalpark, der sich unterhalb der UNESCO-Festungsanlagen mitten durch die Stadt zieht, mit zwei eingezäunten städtischen Hundeauslaufflächen. Angeleinte Hunde auf der gesamten Länge willkommen; 24/7 geöffnet, kostenlos.`,
      "Grund Quarter": `Die bildschöne Unterstadt, ein Kopfsteinpflasterviertel aus dem 18. Jahrhundert entlang der Alzette unterhalb der Festungsanlagen, mit Uferlokalen, dem Kulturzentrum Neumünster und der Kirche Saint-Jean-du-Grund. Angeleinte Hunde überall willkommen.`,
      "Bambësch Forest": `600 Hektar großer Buchenwald am nordwestlichen Stadtrand, der größte Stadtwald Luxemburgs. Markierte Wanderwege, auf denen Freilauf auf den inneren Pfaden toleriert wird; kostenloser Bus 14 ab Hamilius.`,
      "Place d'Armes": `Baumbestandener Fußgängerplatz im Herzen der Altstadt, umgeben von hundefreundlichen Cafeterrassen, zwei Minuten vom Großherzoglichen Palast und der Kathedrale Notre-Dame entfernt. Ein lebendiges Stadtzentrum, leinenfreundlich.`,
      "Lac de la Haute-Sûre": `380 Hektar großer Stausee in den Ardennen, 45 Minuten mit dem Auto entfernt, das größte Gewässer des Landes und der einzige Ort in Luxemburg, an dem Hunde ganzjährig frei an den bewaldeten Ufern schwimmen können.`,
    },
  },
  lyon: {
    history: `Lyon, Frankreichs zweite Stadt nach Wirtschaftskraft, oft als gastronomische Hauptstadt der Welt bezeichnet, liegt am Zusammenfluss von Rhône und Saône. Mit 500.000 Einwohnern und einem dichten Netz aus Traboules (überdachten Passagen), Hügelparks und Flussufern ist Lyon für Hundehalter ebenso gut geeignet wie für Feinschmecker. Das UNESCO-gelistete Vieux Lyon und der Hügel Fourvière bieten gegensätzliche Umgebungen für Hundespaziergänge: enge mittelalterliche Gassen unten, offene Gärten und römische Ruinen oben. Die Lyoner nehmen ihre Hunde selbstverständlich mit in die Bouchons (traditionelle Bistros).`,
    petTips: [`Lyons U-Bahn- und Tramnetz TCL erlaubt Hunde nur in Transportboxen. Das umfangreiche Busnetz lässt kleine Hunde in Transportboxen zu; größere Hunde mit Maulkorb nach Ermessen des Fahrers.`, `Bouchons (traditionelle Lyoner Bistros) gehören zu Frankreichs hundefreundlichsten Restaurants, es ist üblich, beim Mittagessen Hunde unter dem Tisch zu sehen. Fragen Sie immer zuerst 'Est-ce que je peux venir avec mon chien?'`, `Der Hügel Croix-Rousse (der 'arbeitende Hügel', historisch das Seidenweberviertel) hat hervorragende Straßen zum Hundespazieren, unabhängige Cafés und einen tollen Samstagsmarkt. Deutlich ruhiger als Fourvière.`, `Der Parc de la Tête d'Or verfügt überall über kostenlose Wasserstellen. Der Seebereich ist beliebt zum Schwimmen (Hunde in manchen Bereichen früh morgens erlaubt, bevor sich der Park füllt).`, `Lyon wird im Winter kalt, aber die überdachten Traboules und die Bouchon-Kultur drinnen machen es zu einem von Frankreichs besten Städtezielen für Hundehalter außerhalb der Saison.`],
    practicalInfo: [`Notfalltierarzt: VetaLyon, 79 Rue des Mûriers, Lyon 8e (+33 4 37 47 00 00), 24-Stunden-Fachtierklinik.`, `Anreise: Die Bahnhöfe Lyon Part-Dieu und Lyon Perrache verbinden mit Paris (2 Std. TGV), Marseille (1 Std. 40 Min.), Genf (2 Std.) und darüber hinaus. Hunde in Transportboxen kostenlos im TGV; größere Hunde zahlen einen ermäßigten Tarif.`, `Lyon liegt ideal für eine Mehrstädtereise: Grenoble (1 Std. 30 Min.), Annecy (2 Std. mit dem Auto) und das Burgund-Weinland (1 Std. nördlich) eignen sich hervorragend für hundefreundliche Tagesausflüge.`, `Markt-Tipp: Les Halles de Lyon Paul Bocuse erlauben Hunde in der überdachten Markthalle, ein seltenes Privileg für einen Feinkostmarkt dieser Größenordnung.`],
    sights: {
      "Parc de la Tête d'Or": `Lyons prächtiger, 117 Hektar großer Park mit See, Rosengarten und einem kostenlosen Zoo ist das wichtigste Hundeziel der Stadt. Hunde an der Leine überall willkommen; die Uferwege und offenen Wiesen eignen sich ideal für lange Spaziergänge morgens oder abends.`,
      "Colline de Fourvière": `Der Hügel über dem alten Lyon, gekrönt von der Basilika Fourvière und römischen Amphitheaterruinen, bietet einen hervorragenden erhöhten Hundespaziergang. Der Jardin du Rosaire führt über terrassierte Gärten mit Blick über die Stadt hinauf. Die meisten Gärten des Hügels sind mit angeleintem Hund zugänglich.`,
      "Quais du Rhône & Saône": `Die neugestalteten Uferkais an beiden Flüssen sind Lyons beliebteste Freiflächen. Flach, breit, teils schattig und mit Cafés und Food-Trucks gesäumt, sind die Berges du Rhône am linken Ufer besonders hundefreundlich, mit Wasserstellen und offenen Rasenflächen.`,
      "Vieux-Lyon (St-Jean & St-Georges)": `Das UNESCO-gelistete Renaissanceviertel unterhalb von Fourvière lässt sich mit Hund gut erkunden, besonders am frühen Morgen oder außerhalb der Saison. Die Traboules (versteckten Passagen) sind zugänglich; in den engen Gassen müssen Hunde angeleint sein. Bouchons heißen Hunde an den Außentischen meist willkommen.`,
      "Musée des Beaux-Arts & Musée Lumière": `Museen in Lyon lassen keine Hunde zu. Der Innenhof des Musée des Beaux-Arts (ehemalige Benediktinerabtei) ist von der Gartenseite aus für einen Blick zugänglich. Die Lumière-Gärten sind hundefreundlich.`,
    },
  },
  maastricht: {
    history: `Maastricht ist die älteste Stadt der Niederlande, im 1. Jahrhundert n. Chr. von den Römern als 'Mosae Trajectum' (die Furt über die Maas) gegründet. Im Mittelalter eine freie Reichsstadt, im 17. Jahrhundert von Vauban befestigt und Schauplatz des Vertrags von Maastricht 1992, der die Europäische Union schuf, ist sie zudem die burgundische Kulturhauptstadt Limburgs. Das kompakte mittelalterliche Zentrum, umringt von weitgehend erhaltenen Stadtmauern (Helpoort, Hoge Fronten), zentriert sich um den Vrijthof und die Sint-Servaasbasiliek. Für Reisende mit Hund ist Maastricht eine der zugänglichsten Städte Europas: ein begehbares Zentrum, das man in 20 Minuten von einem Ende zum anderen durchquert, eine burgundische Café-Kultur, die angeleinte Hunde selbstverständlich willkommen heißt, der Waldhügel Sint-Pietersberg direkt südlich des Zentrums mit 8 km Freilaufwegen, 22 eingezäunte städtische Losloopgebieden und eine in Europa einzigartige Dreiländer-Lage (Belgien 5 km, Deutschland 25 km).`,
    petTips: [`Die burgundische Café-Kultur heißt Hunde standardmäßig willkommen, rund 80 % der Cafés und Bistros in Maastricht lassen angeleinte Hunde im Hauptraum zu.`, `Arriva-Busse und NS-Züge: kleine Hunde in Transportbox kostenlos; mittlere und große Hunde mit einer Hond Dagkaart für 3,10 € (kein Maulkorb erforderlich, anders als in Deutschland).`, `22 eingezäunte städtische Losloopgebieden, offizielle Karte auf gemeentemaastricht.nl.`, `Nächstgelegener 24/7-Notfalltierarzt: Dierenkliniek Heerlen (+31 45 571 0001), 25 Min. Fahrt über die A2.`, `Einzigartige Dreiländer-Lage: Lüttich (BE) 33 Min. mit dem Zug, Aachen (DE) 50 Min. mit dem Zug, ermöglicht mehrere Hunde-Tagesausflüge, ohne den Standort zu wechseln.`],
    practicalInfo: [`Die Niederlande gehören zur EU und zum Schengen-Raum: EU-Heimtierausweis plus gültige Tollwutimpfung plus ISO-Mikrochip genügen aus jedem EU-Land.`, `Direkte NS-Züge: Lüttich 33 Min., Aachen 50 Min., Eindhoven 1 Std., Amsterdam 2 Std. 30 Min., Brüssel 1 Std. 45 Min. (über Lüttich).`, `Flughafen Maastricht Aachen Airport (MST) 12 km nordöstlich; Flughafen Lüttich (LGG) 35 Min. mit dem Auto für Billigflüge.`, `Währung: Euro. Tägliches hundefreundliches Budget: 60-90 €/Tag ohne Unterkunft, im Rahmen des EU-Medians.`, `Wichtige Veranstaltungen, die man mit einem ängstlichen Hund meiden sollte: Karneval (Mitte Februar), TEFAF (März, internationale Kunstmesse), André-Rieu-Konzerte auf dem Vrijthof (Juli).`],
    sights: {
      "Vrijthof": `Maastrichts großer Hauptplatz, flankiert von der Sint-Servaasbasiliek und der Sint-Janskerk. 24/7 geöffnet, hundefreundlich, ringsum Terrassen.`,
      "Sint-Pietersberg": `Ein 250 ha großer bewaldeter Kalksteinhügel südlich des Zentrums, 8 km Freilaufwege, Panoramen über Maastricht und das belgische Voer-Tal.`,
      "Helpoort": `Das älteste erhaltene Stadttor der Niederlande (um 1229), hundefreundlicher Mauerspaziergang mit angeleinten Hunden kostenlos.`,
      "Maas Riverside": `Der Treidelpfad an der Maas, 14 km autofrei bis zur belgischen Grenze, Hundebadebucht Pietersplas 5 km südlich.`,
      "Stadspark": `Ein im 19. Jahrhundert angelegter Landschaftspark entlang der westlichen Stadtmauern, 9 ha mit eingezäunter Losloopgebied in der Südecke.`,
      "Onze-Lieve-Vrouweplein": `Maastrichts ruhigster und malerischster Platz, hundefreundliche Cafeterrassen rund um die Onze-Lieve-Vrouwebasiliek aus dem 11. Jahrhundert.`,
    },
  },
  madrid: {
    history: `Madrid entstand aus einer maurischen Festung namens Mayrit im 9. Jahrhundert und wurde 1561 unter Felipe II. zur spanischen Hauptstadt, wobei es sich von einer bescheidenen mittelalterlichen Stadt zum politischen und kulturellen Herzen des Habsburgerreichs wandelte. Heute balanciert sie bourbonische Pracht mit einem hektischen, nachtaktiven urbanen Puls. Madrid ist eine bemerkenswert hundeaffine Hauptstadt: Das Ayuntamiento zählt über 300.000 registrierte Hunde, und die Stadt hat stark in eigene Hundeauslaufzonen (zonas de esparcimiento canino) in jedem Bezirk investiert. An Wochenendmorgen füllen sich die Kieswege im Retiro mit Galgos, Podencos und Rettungshunden aus Spaniens weitverzweigten Galgo-Vermittlungsnetzwerken. Cafés in Malasaña, Chueca und La Latina heißen Hunde auf ihren Terrassen routinemäßig willkommen, und der riesige Casa de Campo, fünfmal so groß wie ein zentraler Stadtpark, gibt Stadthunden Raum, sich wirklich auszutoben.`,
    petTips: [`Die Metro Madrid erlaubt pro Fahrgast einen mittelgroßen Hund außerhalb der Stoßzeiten (vor 07:30, 09:30-14:00, nach 19:00 Uhr werktags; ganztägig am Wochenende), der Hund muss Maulkorb und Leine tragen.`, `Von Juli bis August kann der Nachmittagsbelag über 55 °C erreichen, gehen Sie vor 10:00 oder nach 21:00 Uhr spazieren und testen Sie den Asphalt 7 Sekunden lang mit der Hand, bevor Sie Pfoten aufsetzen lassen.`, `In Madrid müssen Hunde in öffentlichen Bereichen angeleint sein; als PPP eingestufte Rassen (Rottweiler, Pitbull-artige usw.) müssen Maulkorb tragen, und der Halter benötigt eine städtische Lizenz.`, `Alle Terrassen, die Hunde akzeptieren, müssen einen Aufkleber zeigen, drinnen hängt es vom Wirt ab, aber Tapas-Bars in La Latina und Malasaña sind überwältigend hundefreundlich.`, `Führen Sie überall Wasser mit: Madrid hat über 180 öffentliche Brunnen (viele mit Trinkbecken auf Hundehöhe), kartiert in der App 'Canes Madrid'.`],
    practicalInfo: [`Flughafen: Madrid-Barajas (MAD) hat eine Auslaufzone für Haustiere in Terminal 4; Taxis nehmen angeleinte Hunde nach Ermessen des Fahrers mit.`, `Tierärzte: 24-Stunden-Notfallkliniken in jedem Bezirk, das Hospital Veterinario Puchol (Chamartín) und Los Madrazo (Sol) sind zentrale Anlaufstellen.`, `Alternative zum Strand: der städtische Dehesa de la Villa und der Pinar de Chamartín bieten Waldspaziergänge, wenn die Stadt überhitzt.`, `Öffentlicher Nahverkehr: Busse (EMT) lassen kleine Hunde in Transportboxen zu; Cercanías-Regionalzüge akzeptieren Hunde bis 10 kg in einer Transportbox, größere Hunde außerhalb der Stoßzeiten mit Maulkorb.`, `Zubehör für Haustiere: Kiwoko, Tiendanimal und die lokale Kette Masquepet haben zentrale Filialen.`],
    sights: {
      "Parque del Retiro": `Madrids 125 Hektar großer königlicher Park heißt Hunde überall an der Leine willkommen, mit ausgewiesenen Freilaufzonen nahe der Puerta de Madrid und der Puerta de Mariano de Cavia. Meiden Sie den Rosengarten Rosaleda und das Innere des Crystal Palace, wo Haustiere eingeschränkt sind.`,
      "Casa de Campo": `Mit 1.700 Hektar Madrids größte Grünfläche ist ein Hundeparadies mit kilometerlangen Wegen, einem See und weitreichender Freilauftoleranz abseits von Picknickzonen. Erreichbar mit der Metrolinie 10 (Lago) oder der Seilbahn ab Parque del Oeste.`,
      "Plaza Mayor & Madrid dos Austrias": `Der von Arkaden gesäumte Platz aus dem 17. Jahrhundert und das umliegende Habsburgerviertel eignen sich ideal für angeleinte Spaziergänge, mit zahllosen hundefreundlichen Terrassen in der Cava Baja und der rua Mayor. Das Kopfsteinpflaster kann sich im Juli und August stark aufheizen, bleiben Sie unter den schattigen Arkaden.`,
      "Museo del Prado": `Spaniens Flaggschiff-Museum verbietet Hunde außer zertifizierten Assistenztieren, doch der umliegende Paseo del Prado und der Eingang der Jardines del Buen Retiro eignen sich wunderbar für einen Spaziergang vor dem Besuch. Nahe gelegene Hundebetreuungsdienste befinden sich in der rua Alfonso XII.`,
      "Templo de Debod": `Dieser authentische ägyptische Tempel aus dem 2. Jahrhundert v. Chr., 1968 an Spanien verschenkt, liegt im Parque del Oeste mit Madrids schönsten Sonnenuntergängen. Hunde sind an der Leine im umliegenden Park willkommen; der Zutritt zum Tempel selbst ist nicht gestattet.`,
      "Madrid Río": `Der zurückgewonnene Uferkorridor am Manzanares erstreckt sich über 10 km mit Hundeparks, Brunnen und der historischen Puente de Toledo. Seine schattigen linearen Wege und Wassermerkmale machen ihn zum klügsten Spaziergang bei Hitze im Zentrum Madrids.`,
    },
  },
  mahon: {
    history: `Als Hauptstadt Menorcas, der ruhigsten der Balearen-Inseln, erstreckt sich Mahón (katalanisch Maó) am äußersten Ende eines der größten Naturhäfen der Welt, einer felsigen, fast fünf Kilometer langen Bucht. Lange von den Briten begehrt, die es im 18. Jahrhundert besetzten, zeigt die Stadt noch heute Schiebefenster, eine Vorliebe für Gin und eine Brennerei, Xoriguer, die immer noch am Kai arbeitet. Ihre weißen Gassen steigen vom Hafen hinauf zur Placa de s'Esplanada, dem lebendigen Herzen des örtlichen Lebens. Die gesamte Insel ist UNESCO-Biosphärenreservat, umrundet vom Cami de Cavalls, einem alten Küstenreitweg, der sie über 185 Kilometer umkreist. Für den Reisenden mit Hund bietet Mahón Uferspaziergänge, wilde Buchten und einen entspannenden Inselrhythmus, fernab der Menschenmassen von Ibiza.`,
    petTips: [`Saisonaler Hinweis: Von Mai/Juni bis September verbieten viele Balearen-Strände Hunde tagsüber; erkundigen Sie sich beim Rathaus und zielen Sie auf die Nebensaison oder tolerante Buchten außerhalb der Saison ab.`, `Die Sommer auf Menorca sind heiß und die Sonne stark: gehen Sie früh oder abends mit dem Hund spazieren, führen Sie Wasser mit und testen Sie die Temperatur von Sand und Asphalt, bevor Sie losgehen.`, `Auf dem Cami de Cavalls sollten Sie den Hund anleinen und Wasser mitführen: Lange Abschnitte bieten weder Schatten noch Wasserstellen, und die geschützte Tierwelt ist empfindlich.`, `Die Tramontana, der Nordwind, kann entlang der Küste und an der Fortalesa de La Mola stark wehen; achten Sie bei einem nervösen Hund auf die Klippen und das aufgewühlte Wasser.`, `Für die Überfahrt nach Mallorca oder aufs Festland nehmen die Fähren (Baleària, Trasmediterranea) angeleinte, mit Maulkorb versehene Hunde auf den Außendecks oder in Boxen mit; buchen Sie den Tierplatz im Voraus.`],
    practicalInfo: [`Spanien folgt EU-Regeln: Ein EU-Heimtierausweis, ein ISO-Mikrochip und eine aktuelle Tollwutimpfung genügen für Einreise und Reise.`, `Allgemeine Notrufnummer: 112, europaweit gültig; fragen Sie nach der nächsten diensthabenden Tierklinik in Mahón.`, `Anreise: Der Flughafen Menorca (MAH) liegt wenige Kilometer von Mahón entfernt, mit saisonalen Flügen; Fähren verbinden zudem Mallorca, Barcelona und Valencia.`, `Die gesamte Insel ist UNESCO-Biosphärenreservat: Sammeln Sie den Kot Ihres Hundes auf und leinen Sie ihn nahe den Talayot-Ausgrabungsstätten und brütenden Tieren an.`, `Sprache und Währung: Man spricht Katalanisch und Spanisch, die Währung ist der Euro; die Insel erkundet man am besten mit dem Auto, in der Stadt und auf den Wegen gilt Leinenpflicht.`],
    sights: {
      "Port de Mao": `Der große Naturhafen, der der Stadt ihren Namen gibt, gesäumt von einem lebendigen Kai mit Restaurants und Ausflugsbooten. Angeleinte Hunde folgen morgens im Schatten gerne der Uferpromenade.`,
      "Casco antiguo & Placa de s'Esplanada": `Alt-Mahón mit seinen weißen Gassen, Kirchen und der breiten Placa de s'Esplanada im Herzen der Stadt. Angeleinte Hunde streifen frei durch die Straßen und über den platanenbeschatteten Platz.`,
      "Xoriguer Gin Distillery": `Die Brennerei Xoriguer am Kai, Hüterin des menorquinischen Gins, der aus der britischen Besatzungszeit stammt. Laden und Verkostungsraum sind drinnen und lassen keine Hunde zu, aber man kann sich beim kurzen Halt abwechseln.`,
      "Fortalesa de La Mola": `Die Festung aus dem 19. Jahrhundert bewacht die Hafeneinfahrt auf einer windgepeitschten Landzunge. Die Freiluftanlage kann mit angeleintem Hund besichtigt werden, zwischen Wällen, Tunneln und Meerblick.`,
      "Cami de Cavalls (GR-223)": `Der historische GR-223-Weg, der Menorca über 185 Kilometer umrundet, durch Buchten, Klippen und Pinienwälder. Angeleinte Hunde sind hier in ihrem Element; führen Sie Wasser mit, da Schatten und Wasserstellen im Sommer knapp sind.`,
      "Cales Fonts (Es Castell)": `Der kleine Hafen von Cales Fonts im benachbarten Es Castell, wo alte Fischerbootshäuser zu Terrassen wurden. Angeleinte Hunde sind auf den Außenterrassen willkommen, besonders bei Sonnenuntergang.`,
    },
  },
  malaga: {
    history: `Um 770 v. Chr. von den Phöniziern als Malaka gegründet, ist Málaga eine der ältesten durchgehend bewohnten Städte Europas, geschichtet mit römischem, maurischem und spanischem Goldenem-Zeitalter-Erbe unter ihrer sonnigen Costa-del-Sol-Fassade. Picassos Geburtsstadt hat sich in den letzten zwei Jahrzehnten zu einer ernstzunehmenden Kulturhauptstadt mit dem Pompidou-, Thyssen- und Picasso-Museum gewandelt, während sie im Kern eine Strandstadt geblieben ist. Málagas Beziehung zu Hunden ist geprägt von andalusischer Dorftradition und moderner Costa-del-Sol-Expat-Kultur: Podencos und Galgos aus Rettungsstiftungen wie APAM teilen sich die Promenaden mit den Retrievern der Urlauber. Die Stadt betreibt vier offiziell anerkannte Hundestrände, allen voran die Playa del Peñón del Cuervo, und das subtropische Klima macht das Café-Leben im Freien mit Hund zu den Füßen zum ganzjährigen Standard.`,
    petTips: [`Die städtischen Strände verbieten Hunde vom 1. Juni bis 30. September zwischen 09:00 und 20:00 Uhr, außerhalb dieses Zeitfensters können Sie die meisten Strände frei begehen, prüfen Sie aber immer das Schild an der Zufahrtsrampe.`, `Der mediterrane Sommer birgt echte Hitzschlaggefahr: Vermeiden Sie Spaziergänge zwischen 12:00 und 18:00 Uhr völlig von Juli bis September; das Málaga-Notdienstnetz für Tierärzte verzeichnet jeden August einen Anstieg an Hitzschlag-Behandlungen bei Hunden.`, `Die Sandtemperatur überschreitet an Sommernachmittagen regelmäßig 60 °C, selbst an hundefreundlichen Stränden, gehen Sie bei Sonnenaufgang oder nach 19:00 Uhr und spülen Sie die Pfoten sofort ab, da das mediterrane Salz die Ballen reizt.`, `Die Metro Málaga (zwei Linien) nimmt einen Hund pro Fahrgast in einer Transportbox oder größere Hunde angeleint/mit Maulkorb außerhalb der Stoßzeiten mit, kostenlose Fahrt außerhalb der Hauptverkehrszeiten.`, `Die historische Altstadt ist fast vollständig für Fußgänger gesperrt und gepflastert, angenehm zum Laufen, aber rutschig bei Nässe.`],
    practicalInfo: [`Flughafen: Málaga-Costa del Sol (AGP) ist Spaniens viertgrößter Flughafen, mit Auslaufzonen für Haustiere außerhalb der Ankunftsbereiche von T2 und T3.`, `Strandsaison-Aufteilung: Die 'temporada alta' Juni-September bringt strenge Hundeverbote an den meisten Stränden; von Oktober bis Mai sind fast alle Strände am frühen Morgen de facto hundefreundlich.`, `Tierärzte: Hospital Veterinario Málaga (24h) in der rua Demóstenes und die Vetersalud-Kliniken in der ganzen Stadt.`, `Öffentlicher Nahverkehr: EMT-Stadtbusse nehmen kleine Hunde in Transportboxen mit; die Cercanías-Linie C-1 nach Fuengirola erlaubt angeleinte Hunde außerhalb der Stoßzeiten.`, `Wasser auffüllen: Der Paseo marítimo und der Parque de Málaga haben in regelmäßigen Abständen Trinkbrunnen auf Hundehöhe.`],
    sights: {
      "Alcazaba": `Der maurische Palast-Festungskomplex aus dem 11. Jahrhundert verbietet Hunde im Inneren, doch die terrassierten Außengärten und der angrenzende Platz des Römischen Theaters sind an der Leine begehbar. Der Aufstieg von der rua Alcazabilla bietet postkartenreife Ausblicke, den Umweg wert, auch ohne Eintritt.`,
      "Playa del Peñón del Cuervo": `Málagas Flaggschiff-Hundestrand liegt 6 km östlich des Zentrums, eine markante Felsenbucht mit schattigen Pinienbereichen. Ganzjährig für Hunde unter Stimmkontrolle geöffnet; bringen Sie eigenes Wasser mit, da Brunnen im Sommer knapp sind.`,
      "Parque de Málaga": `Die botanische Promenade aus dem 19. Jahrhundert erstreckt sich 800 m zwischen Hafen und Altstadt, beschattet von riesigen Ficus- und Palmenbäumen. Hunde sind an der Leine auf den zentralen Wegen willkommen, ideal bei Mittagshitze, wenn der Strand zu heiß ist.`,
      "Muelle Uno & Port": `Die umgestaltete Hafenpromenade verbindet Einkaufsmöglichkeiten und Meerblick mit zahlreichen hundefreundlichen Terrassen. Der Paseo de la Farola zum Leuchtturm ist ein beliebtes abendliches Ritual für die einheimischen Hundespaziergänger.`,
      "Castillo de Gibralfaro": `Angeleinte Hunde können den schattigen, pinienbewaldeten Pfad zur Burg aus dem 14. Jahrhundert hinaufsteigen (nur Außenwege, das Innere der Festung ist gesperrt). Der Panoramablick am Gipfel reicht über die Stierkampfarena und die Mittelmeerküste.`,
      "Soho Málaga": `Das Straßenkunstviertel zwischen Hafen und Alameda beherbergt riesige Wandgemälde von D*Face, Obey und Boa Mistura, durchzogen von hundefreundlichen Cafés und dem Vorplatz des Centre Pompidou. Perfekt für einen kühlen Morgen-Fotospaziergang.`,
    },
  },
  makarska: {
    history: `Eingeklemmt zwischen dem Meer und der Kalksteinmauer des Biokovo-Massivs, das sich direkt über den Dächern bis auf 1.762 m erhebt, ist Makarska die Hauptstadt einer Riviera mit 60 km pinienbestandener Kieselküste. Als von Venedig und dem Osmanischen Reich umkämpfter Marinestützpunkt bewahrte die Stadt ihren Kačić-Platz und die barocke Uferpromenade aus der venezianischen Zeit, bevor sie in den 1930er-Jahren zu einem der ersten dalmatinischen Seebäder wurde. Heute ist sie eine ideale Basis mit Hund: Die Marineta-Promenade verläuft unter den Palmen, die Halbinsel Sveti Petar bietet einen schattigen Pinienwald am Wasser, und hundetolerante Buchten reihen sich bis nach Tučepi. Wenn die Sommerhitze die Küste erdrückt, führt die Straße in den Naturpark Biokovo in zwanzig Minuten zu kühleren Wegen hinauf, ein seltenes Entlastungsventil an dieser Küste. Die Jadrolinija-Fähre setzt in etwa einer Stunde auf die Insel Brač über.`,
    petTips: [`Sommerwarnung: über 30 °C im Juli und August, Kieselsteine werden zwischen 11 und 18 Uhr glühend heiß für Pfoten; machen Sie den Handrückentest, gehen Sie bei Sonnenaufgang und abends spazieren und führen Sie stets Wasser mit.`, `Das kroatische Recht verbietet Hunde vom 15. Mai bis 15. September an nicht ausgewiesenen Badestränden; weichen Sie am frühen Morgen auf die Buchten außerhalb des überwachten Bereichs Richtung Nugal und Tučepi aus.`, `Erdrückt die Hitze die Riviera? Fahren Sie hinauf in den Naturpark Biokovo: Angeleinte Hunde sind auf den Wegen erlaubt, und die Höhenlage ist zehn Grad kühler, doch auf dem Karst gibt es kein Wasser, füllen Sie die Flaschen also vorher auf.`, `Jadrolinija-Fähre Makarska-Sumartin (Brač): Hunde reisen mit Maulkorb und Leine an Deck, nicht in den Innenlounges; die Überfahrt dauert etwa eine Stunde, meiden Sie die Mittagsabfahrten im Sommer.`, `In der Stadt und auf der Marineta gilt Leinenpflicht; die Promenade wird an Sommerabenden sehr voll, wählen Sie bei einem menschenscheuen Hund lieber die schattige Runde um Sveti Petar.`],
    practicalInfo: [`Europäische Notrufnummer: 112; in Kroatien Polizei 192, Feuerwehr 193, Rettungsdienst 194, nicht mit einer Tierarzt-Notrufnummer zu verwechseln.`, `Tierarztpraxen in Makarska für die Routineversorgung; die nächsten 24-Stunden-Tierkliniken befinden sich in Split, rund eine Stunde entfernt an der Küstenstraße.`, `Haustierabteilungen in den Supermärkten Tommy, Konzum und Studenac der Stadt; besser sortierte Zoohandlungen in den Gewerbegebieten rund um Split.`, `Jadrolinija-Fähre Makarska-Sumartin (Brač) ab dem Haupthafen, Maulkorb und Leine an Deck Pflicht; Küstenbusse der Riviera nach Ermessen des Fahrers, kleine Hunde in Transportbox werden leichter akzeptiert.`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich; Kroatien gehört zur EU, keine zusätzlichen Formalitäten bei Einreise aus Frankreich, Spanien oder Portugal.`],
    sights: {
      "Park prirode Biokovo": `Der Naturpark Biokovo erhebt sich 1.762 m über Makarska, sein gläserner Skywalk ragt hoch über die Riviera hinaus. Angeleinte Hunde sind auf den Wegen erlaubt, und die Panoramastraße lässt sich bis ganz nach oben befahren; im Sommer bringt die Höhenlage willkommene Erleichterung vom Backofen an der Küste.`,
      "Marineta": `Die Marineta-Promenade verläuft entlang von Hafen und Bucht unter einer doppelten Palmenreihe, vorbei an Terrassen, Eisdielen und Bänken mit Blick auf die Inseln. Sie ist Makarskas klassischer abendlicher Hundespaziergang, an der Leine, sobald der Stein abgekühlt ist und die ganze Stadt zum Flanieren herauskommt.`,
      "Poluotok Sveti Petar": `Die Halbinsel Sveti Petar schließt den Hafen mit ihrem Pinienwald, Leuchtturm und einer kleinen Kapelle ab, fünf Minuten von der Marineta entfernt. Der Rundweg, den größten Teil des Tages schattig, ist der beste Ort der Stadt, um in den heißen Stunden mit Hund spazieren zu gehen, mit Blick auf Biokovo und die Bucht.`,
      "Plaža Nugal": `Ein 40-minütiger Spaziergang Richtung Tučepi entlang des Küstenwegs, die Bucht Nugal reiht blasse Kieselsteine und Klippen unterhalb des Waldes auf. Außerhalb des Bereichs der überwachten Strände ist sie einer der Abschnitte, an denen Hunde toleriert werden, besonders am frühen Morgen; der Zugang erfordert etwas Anstrengung, also Wasser und passendes Schuhwerk mitnehmen.`,
      "Svetište Vepric": `Zwei Kilometer vom Zentrum entfernt bildet das Heiligtum Vepric die Grotte von Lourdes in einem Tal aus Pinien und Zypressen am Fuß des Biokovo nach. Ein friedlicher, schattiger Ort im Freien, der außerhalb der Gottesdienste mit einem diskreten, angeleinten Hund besucht werden kann; meiden Sie die großen Wallfahrtstage.`,
      "Gradska plaža Makarska": `Der Hauptstadtstrand erstreckt sich fast 2 km mit feinen Kieseln zwischen der Marineta und den Hotels der Bucht, mit Biokovo im Hintergrund. Hunde sind hier während der Badesaison verboten; weichen Sie auf die Buchten Richtung Nugal und Tučepi aus oder kommen Sie außerhalb der Saison, wenn es sich leert.`,
    },
  },
  malmo: {
    history: `Malmö liegt an der südwestlichen Spitze Schwedens, eine 35-minütige Öresundståg-Zugfahrt von Kopenhagen entfernt über die 16 km lange Öresundbrücke, die 2000 eröffnet wurde und die wirtschaftliche Schwerkraft der Stadt über Nacht veränderte. Im 13. Jahrhundert als Hansehafen gegründet, dann bis zum Frieden von Roskilde 1658, der es an Schweden übergab, eine dänische königliche Stadt, durchlief Malmö ein schweres Industrie-Jahrhundert mit dem Bau der Kockums-Werften und der Textilfabriken um Möllevången. Der Kockums-Kran ging 2002 nach Südkorea, symbolisch ersetzt durch Santiago Calatravas 190 m hohen Turning Torso, fertiggestellt 2005, das sichtbare Herzstück einer 25 Jahre dauernden Erneuerung, die den alten Hafen in das nachhaltige Viertel Västra Hamnen verwandelte. Heute ist Malmö mit 360.000 Einwohnern, die Hälfte davon unter 35, Schwedens drittgrößte Stadt und eine der jüngsten urbanen Demografien Europas. Die Hundekultur ist außergewöhnlich verankert: Die Stadt betreibt 61 eingezäunte Hundeparks, einen eigenen ganzjährigen Hundestrand bei Ribersborg und freie Beförderung für Haustiere im gesamten Skånetrafiken-Netz. Die schwedische landesweite Leinenpflicht (kopplingstvång) vom 1. März bis 20. August schützt die Wildtiere; außerhalb dieses Zeitraums laufen Hunde unter Stimmkontrolle frei durch Wälder und Wiesen in ganz Schonen.`,
    petTips: [`Hunde reisen im gesamten Skånetrafiken-Netz (Stadtbusse, Regionalbusse und Pågatåg-/Öresundståg-Züge innerhalb Schwedens) kostenlos mit, bis zu zwei Haustiere pro Fahrgast, angeleint und nicht auf den Sitzen. Die Pågatåg-Züge haben einen an der Tür markierten 'Haustierwagen'.`, `Vom 1. März bis 20. August gilt Schwedens landesweite Leinenpflicht (kopplingstvång) verpflichtend in Wäldern, Feldern und Naturschutzgebieten, auch wenn der Weg leer wirkt. Stimmkontrolle ist in diesem Zeitraum kein rechtlicher Ersatz.`, `Hunde sind zwischen dem 15. März und 30. September an allen üblichen Stadtbadestränden verboten. Die Ausnahme ist der ganzjährige Hundestrand (hundbad) am nördlichen Ende von Ribersborg, mit einem zweiten informellen Platz bei Sibbarp.`, `Bei der Überfahrt nach Kopenhagen mit dem Öresundståg reisen kleine Hunde in geschlossener Transportbox in beide Richtungen kostenlos; größere Hunde benötigen ab der Einreise nach Dänemark ein dänisches Kinderhalbtarifticket vom Schaffner.`, `Die nächste 24/7-Notfalltierklinik ist Evidensia Djursjukhuset Malmö (Cypressvägen 11, Fosie), mit Bereitschaftsärzten, Intensivstation und Bildgebung. Rufen Sie die Triage-Hotline +46 40 55 22 55 an, bevor Sie hinfahren.`],
    practicalInfo: [`Nächstgelegener Flughafen: Der Flughafen Kopenhagen (CPH) ist de facto der Malmö-Flughafen, 22 Minuten mit dem Öresundståg vom Malmö Central Station entfernt; der Flughafen Malmö (MMX) bedient nur Inland und einige wenige europäische Flüge.`, `Der Bahnhof Malmö Central (Malmö C) ist der Eisenbahnknoten, hier halten Pågatåg-Regionalzüge, Öresundståg nach Kopenhagen und SJ-Fernzüge nach Stockholm und Göteborg.`, `Leitungswasser ist trinkbar, und Auffüllstationen (vattenpost) sind von Mai bis September entlang der Sundspromenaden, im Pildammsparken und auf dem Lilla Torg in Betrieb.`, `Schwedens Bandwurm-(Echinococcus-)Behandlungspflicht gilt weiterhin für Hunde, die von außerhalb Finnlands, Großbritanniens, Irlands, Maltas oder Norwegens einreisen, verabreicht von einem amtlichen Tierarzt 24-120 Stunden vor der Grenzüberquerung.`, `Britische Besucher: Nach dem Brexit ist der EU-Heimtierausweis nicht mehr gültig. Sie benötigen ein Animal Health Certificate (AHC), ausgestellt von einem amtlichen Tierarzt innerhalb von 10 Tagen vor der Reise.`],
    sights: {
      "Ribersborg Hundbad": `Malmös offizieller ganzjähriger Hundestrand am nördlichen Ende des Ribersborg-Sandstreifens. Hunde schwimmen und laufen innerhalb der markierten Zone ohne Leine, mit sanftem Einstieg und ruhigem Øresund-Wasser, das sich für Erstschwimmer unter den Hunden eignet.`,
      "Turning Torso": `Santiago Calatravas 190 m hoher Wohnturm (2005), fünfzehn Jahre lang das höchste Gebäude Skandinaviens und Anker der Erneuerung von Västra Hamnen. Das Innere des Turms ist privat, doch die Uferpromenade und die Treppen des Meeresschwimmbads Scaniabadet sind öffentlich zugänglich und mit Leine hundefreundlich.`,
      "Pildammsparken": `Malmös größter Landschaftspark, 45 Hektar mit Teichen, ausgewachsenen Bäumen und breiten Rasenflächen, angelegt für die Baltische Ausstellung 1914. Leinenpflicht überall, außer im eingezäunten hundrastgård am Südende, wo Freilauf in einem umzäunten Bereich erlaubt ist.`,
      "Malmöhus Slottspark": `Die Gärten rund um Schloss Malmöhus, Schwedens ältestes erhaltenes Renaissanceschloss (1537), einschließlich der Windmühle, der wassergrabenumringten Schlossgärten und des weiteren Slottsparken. Das Schlossinnere beherbergt das Moderna Museet und ist für Hunde geschlossen; die Gärten sind durchgehend mit angeleintem Hund freundlich.`,
      "Lilla Torg & Gamla Staden": `Der kopfsteingepflasterte kleine Platz im Herzen der Altstadt, umgeben von Fachwerkgebäuden und hundefreundlichen Cafeterrassen. Das mittelalterliche Straßenraster von Gamla Staden ringsum ist kompakt und flach, ideal für einen entspannten Spaziergang mit Hund.`,
      "Sundspromenaden": `Eine 4 km lange Uferpromenade von Västra Hamnen bis Ribersborg, mit Meer auf der einen und einem niedrigen Wohnstreifen auf der anderen Seite. Angeleinte Hunde sind auf der gesamten Länge willkommen; Bänke und die Treppen des Meeresschwimmbads Scaniabadet bieten regelmäßige Rastplätze.`,
    },
  },
  manchester: {
    history: `Manchester war die erste Industriestadt der Welt, die Industrielle Revolution fand hier statt, aufgebaut auf Baumwollspinnereien und dem 1761 fertiggestellten Bridgewater-Kanal, Großbritanniens erstem Industriekanal. Heute hat die Stadt mit 553.000 Einwohnern im Herzen von Greater Manchester (2,8 Millionen Menschen) ihr industrielles Erbe in kreative Viertel verwandelt: das Northern Quarter für unabhängige Läden, Ancoats mit seinem ehemaligen Little Italy, Castlefield mit seinem Kanalbecken. Die nordenglische Hundekultur ist eine der großzügigsten: hundefreundliche Pubs an jeder Straßenecke, kostenlose Haustierbeförderung in den Metrolink-Trams (seit 2023 dauerhaft) und Bee-Network-Bussen sowie 240 Hektar Freilauffläche allein im Heaton Park. Eine Brexit-Eigenheit: Besucher aus der EU benötigen ein Animal Health Certificate (AHC) vor der Ankunft, der EU-Heimtierausweis reicht nicht mehr aus.`,
    petTips: [`Nach dem Brexit: EU-Heimtierausweise gelten nicht mehr für die Einreise nach Großbritannien, Sie benötigen ein Animal Health Certificate (AHC), ausgestellt von einem EU-Tierarzt innerhalb von 10 Tagen vor der Reise, zusätzlich Tollwutimpfung und Bandwurmbehandlung.`, `Haustiere sind im gesamten Bee-Network (Metrolink, Busse) kostenlos, bis zu 2 angeleinte Hunde pro Fahrgast; dauerhafte Regelung seit 2023.`, `Northern-Rail-Züge: bis zu 2 Hunde kostenlos pro Erwachsenenticket; kleine Haustiere in Transportboxen reisen kostenlos ohne Größenbegrenzung der Box.`, `24/7-Notfalltierarzt: Vets Now Manchester, 98 Bury Old Road, Whitefield, +44 161 222 6004, etwa 20 Minuten mit Bolt vom Zentrum entfernt.`, `Manchester ist regenreich (830 mm/Jahr, mehr als jede andere britische Großstadt), packen Sie einen wasserdichten Hundemantel und ein Mikrofaser-Handtuch ein.`],
    practicalInfo: [`Der Flughafen Manchester (MAN) liegt 14 km vom Zentrum entfernt, Metrolink-Airport-Linie in 25 Minuten (Hunde kostenlos). Ein Northern-Rail-Direktzug verbindet zudem Piccadilly in 20 Minuten mit dem Flughafen.`, `Hundefreundliche Hotelpreise: ab 90 £ pro Nacht für 4*, durchschnittlicher Haustierzuschlag 20-50 £ pro Aufenthalt oder pro Nacht.`, `Ozeanisches Klima: kühle Sommer (17 °C im Juli), milde, aber nasse Winter (5 °C im Januar); Wind und Feuchtigkeit lassen die Kälte schärfer wirken als die Zahlen vermuten lassen.`, `Tailster.com und BorrowMyDoggy.com sind die zwei Referenzplattformen für Betreuung und Gassi-Service; rechnen Sie mit 12-18 £ pro Spaziergang, 30-45 £ für einen ganzen Tag.`, `Manchester liegt 2 Stunden von London mit dem Zug entfernt (Avanti West Coast), 50 Min. von Liverpool und 1 Std. 45 Min. von Windermere, ein idealer Ausgangspunkt für eine Hunderundreise durch den Lake District oder Yorkshire.`],
    sights: {
      "Northern Quarter": `Manchesters kreatives Viertel, unabhängige Läden, Vintage-Geschäfte, hundefreundliche Pubs und das berühmte Kaufhaus Affleck's in der Tib Street. Angeleinte Hunde in fast jedem unabhängigen Laden willkommen; der Wochenendmarkt am Stevenson Square akzeptiert Hunde.`,
      "Heaton Park": `Manchesters Flaggschiffpark (240 Hektar), einer der größten Stadtparks Europas, mit der denkmalgeschützten Heaton Hall (1772). Freilauf auf den offenen Rasenflächen; direkte Metrolink-Tram vom Zentrum in 25 Minuten.`,
      "Castlefield Basin": `Historisches Kanalbecken, von dem aus die Industrielle Revolution ihre erste Baumwolle verschiffte, heute ein grünes Viertel mit Kanal-Bars, der Castlefield Bowl und römischen Fortresten. Der Treidelpfad des Bridgewater-Kanals führt an der Leine bis nach Sale (9 km).`,
      "Fletcher Moss Botanical Gardens": `36 Hektar großes Anwesen im grünen Didsbury, mit Wald, Wassergärten, Wiesen und dem Uferweg am Mersey. Freilauf auf den hinteren Wiesen toleriert; Café-Teestube vor Ort.`,
      "Wythenshawe Park": `109 Hektar großer Park im Süden mit ausgewiesener Freilaufzone, hundefreundlichen Wegen und einer Café-Terrasse an der Wythenshawe Hall, die Hunde draußen zulässt. Bus 41 ab Piccadilly Gardens.`,
      "Formby Beach": `Küste mit Pinien und Dünen im Besitz des National Trust, 90 Minuten mit dem Zug von Manchester (über Liverpool). Ganzjährig Freilauf am 4 km langen Strand und auf den Dünenwegen; Leinenpflicht auf den Wegen des Eichhörnchen-Schutzgebiets.`,
    },
  },
  marbella: {
    history: `Marbella liegt im Herzen der andalusischen Costa del Sol, gegründet als römische Siedlung Salduba und über fünf Jahrhunderte maurischer Herrschaft geprägt, bevor die Katholischen Könige sie 1485 eroberten, die erhaltene Stadtmauer und die weiß getünchte Casco Antiguo rund um die Plaza de los Naranjos zeichnen noch immer die mittelalterliche christlich-maurische Schichtung nach. Ab den 1950er-Jahren verwandelte Prinz Alfonso von Hohenlohe mit seinem Marbella Club das Dorf in Europas Referenz für Luxusresorts, wobei die Golden Mile und der Puerto Banús (1970) die internationale Jetset-Identität zementierten. Die Beziehung zu Hunden ist für Südspanien ungewöhnlich pragmatisch: Das Ayuntamiento betreibt zwei offiziell ausgeschilderte, ganzjährige Hundestrände (Pinillo und Ventura del Mar) mit Süßwasserduschen und Brunnen, die 7 km lange Küstenpromenade Senda Litoral verläuft ununterbrochen vom Zentrum bis zum Puerto Banús, und die große internationale Expat-Gemeinde hat eines von Andalusiens dichtesten Netzen an 24-Stunden-Tierärzten und englischsprachigen Haustiersittern aufgebaut. Der andalusische Sommer verlangt eine entscheidende Anpassung: Gehwege und hölzerne Boardwalk-Oberflächen erreichen zwischen 11:00 und 19:00 Uhr von Juni bis September 50-60 °C, genug, um Pfotenballen in weniger als einer Minute zu verbrennen, weshalb Einheimische von Spätfrühling bis Frühherbst ihre Hunde vor 09:30 oder nach 20:00 Uhr ausführen.`,
    petTips: [`Wenden Sie vor jedem Sommerspaziergang die Sieben-Sekunden-Regel an: Wenn Sie Ihren Handrücken nicht sieben Sekunden lang auf dem Gehweg oder dem hölzernen Boardwalk halten können, gehen Sie dort nicht mit Ihrem Hund spazieren, im Juni-September erreicht andalusischer Asphalt zwischen 11:00 und 19:00 Uhr regelmäßig 50-60 °C und verbrennt Pfotenballen in unter 60 Sekunden.`, `Gehen Sie von Ende Mai bis Anfang Oktober vor 09:30 oder nach 20:00 Uhr spazieren, und bleiben Sie auf schattigem Sand, Rasen oder den gepflasterten Gassen der Casco Antiguo, die den größten Teil des Tages kühl bleiben.`, `Die überwachten andalusischen Strände verbieten Hunde vom 1. Juni bis 30. September; außerhalb dieses Zeitraums ist fast jeder Strand von Marbella mit der Leine begehbar, und die beiden offiziellen Hundestrände (Pinillo und Ventura del Mar) bleiben ganzjährig geöffnet.`, `Speichern Sie bei Ankunft Urvet Marbella (+34 951 70 48 57), eine englischsprachige 24-Stunden-Notfallklinik am Camino del Ángel, am nächsten zu den meisten Strandhotels gelegen.`, `Mikrochip und aktuelle Tollwutimpfung sind für alle Hunde in Spanien Pflicht und können an AVE-Hochgeschwindigkeitszug-Einreisepunkten gescannt werden.`],
    practicalInfo: [`Kein Bahnhof: Die nächste AVE-Hochgeschwindigkeitslinie hält 60 km östlich in Málaga María Zambrano, die einfachste Verbindung ab dem Flughafen Málaga ist der Fernbus Avanza (8-10 €, 45-75 Min.) oder ein privater Transfer/Uber.`, `Zwei ganzjährige offizielle Hundestrände: Playa Canina El Pinillo (östlich des Zentrums) und Playa Canina Ventura del Mar (Nueva Andalucía); 250 m große Freilaufzonen mit Duschen und Brunnen, ausgeschildert 09:00-22:00 Uhr.`, `24-Stunden-Notfalltierärzte: Urvet Marbella (+34 951 70 48 57, Camino del Ángel), Clínica Veterinaria La Campana (+34 952 81 15 94, Nueva Andalucía), GreenVet San Pedro de Alcántara, alle mit englischsprachigem Personal.`, `Regeln für öffentliche Verkehrsmittel: Kleine Hunde in geschlossener Transportbox (max. 60x35x35 cm) reisen kostenlos in den M-220-Bussen und dem Fernbus Avanza; große Hunde im Einzelfall, angeleint und mit Maulkorb.`, `Beste Reisezeit: Ende September bis Mai, außerhalb der Saison entfällt das Strandverbot, das Verbrennungsrisiko für Pfoten sinkt, und Wanderungen im Landesinneren rund um La Concha werden angenehm.`],
    sights: {
      "Playa Canina El Pinillo": `Marbellas Flaggschiff-Hundestrand, ein ausgeschilderter, ganzjähriger 250 m langer Freilaufstreifen östlich des Zentrums, mit Süßwasser-Hundeduschen und Trinkbrunnen, installiert vom Ayuntamiento.`,
      "Casco Antiguo & Plaza de los Naranjos": `Marbellas weiß getünchte Altstadt rund um einen von Orangenbäumen gesäumten Platz mit dem Rathaus aus dem 16. Jahrhundert, vollständig an der Leine begehbar, die meisten Cafeterrassen akzeptieren Hunde standardmäßig.`,
      "Avenida del Mar (Dalí promenade)": `Ein Freiluftmuseum: eine kostenlose Marmorpromenade, gesäumt von zehn originalen Bronzeskulpturen Salvador Dalís (Perseus, Mercurio und andere), die den Alameda-Park mit der Uferpromenade verbindet und 24/7 an der Leine begehbar ist.`,
      "Senda Litoral & Puerto Banús boardwalk": `Ein durchgehender, 7 km langer Holz- und Betonboardwalk, der das Zentrum Marbellas mit dem Puerto Banús verbindet und den Strand die ganze Strecke säumt, der längste ununterbrochene Hundespaziergang der Stadt, komplett flach, verbindet die beiden offiziellen Hundestrände.`,
      "Parque Canino Arroyo de la Represa": `Marbellas Referenz-Hundepark, vollständig eingezäunt für Freilauf, mit Trinkbrunnen, Agility-Geräten und kostenlosem Parkplatz, vom Ayuntamiento am Stadtrand betrieben.`,
      "Puerto Banús marina": `Europas Referenz-Luxusmarina, vollständig an der Leine entlang ihrer glamourösen Uferpromenade begehbar, in der Hauptsaison belebt und voll, aber flach und für ruhige Hunde einfach, mit mehreren hundefreundlichen Cafeterrassen.`,
    },
  },
  marrakech: {
    history: `Um 1070 von den Almoraviden gegründet, war Marrakesch zweimal Hauptstadt eines Reiches, das sich von Spanien bis in den Senegal erstreckte. Die Almohaden hinterließen die Koutoubia, Zwillingsminarett der Giralda von Sevilla; die Saadier ihre vergoldeten Gräber und den El-Badi-Palast. Eine Oasenstadt, entstanden an einer Karawanenkreuzung, verdankt die 'Rote Stadt' ihre Farbe der gestampften Erde ihrer 19 km langen Wallanlagen. Die UNESCO-gelistete Medina kreist um die Jemaa el-Fnaa, ein dauerhaftes Theater aus Geschichtenerzählern und Musikern, während Palmenhaine und Gärten die Luft kühl halten. Mit Hund hierher zu reisen ist nach lokalem Maßstab ungewöhnlich: Haustiere bleiben in der Medina selten, doch Riads mit Innenhöfen, die Menara-Gärten und der Palmenhain bieten echten Freiraum, besonders von Oktober bis April, wenn die Hitze nachlässt.`,
    petTips: [`Von Mai bis September übersteigt die Hitze regelmäßig 40 °C: Ausflüge nur bei Sonnenaufgang und nach Sonnenuntergang, lassen Sie Pfoten nie den Nachmittagsasphalt berühren, führen Sie stets Wasser mit und wählen Sie ein Riad mit schattigem Innenhof.`, `Die Haustierregeln unterscheiden sich enorm von Riad zu Riad: Bestätigen Sie sie schriftlich vor der Buchung, viele akzeptieren nur kleine Hunde oder verlangen, dass das Tier nie allein bleibt.`, `In der Medina erfordern enge Gassen, Mopeds und streunende Katzen eine kurze Leine und einen menschenmengengewohnten Hund; die überdachten Souks meidet man mit Tier besser.`, `Marokko ist nicht tollwutfrei: Vermeiden Sie jeden Kontakt zwischen Ihrem Hund und Straßenhunden und prüfen Sie vor der Abreise, dass die Impfungen aktuell sind.`, `Für die Rückkehr in die EU ist ein mindestens 3 Monate vor der Rückreise durchgeführter Tollwut-Antikörpertiter-Test Pflicht: Erledigen Sie ihn VOR der Abreise, sonst bleibt Ihr Hund hängen.`],
    practicalInfo: [`Ordentliche Tierkliniken in Gueliz und Hivernage; die Versorgungsqualität in der Stadt ist gut, aber nachts eingeschränkt, speichern Sie also die Kontaktdaten Ihrer Klinik vor jedem Ausflug.`, `Marokkanische Notrufnummern: 19 (Polizei) und 15 (Feuerwehr); es gibt keinen zentralen tierärztlichen Bereitschaftsdienst, Ihr Riad oder Hotel ist die beste Anlaufstelle.`, `Zoohandlungen und Hundefutter in Gueliz und den modernen Hypermärkten; gängige europäische Marken sind erhältlich.`, `Keine Hunde in Stadtbussen; kleine Taxis (petits taxis) nach Ermessen des Fahrers, während Großtaxis und private Fahrer problemlos mit Haustier buchbar sind.`, `Einreise nach Marokko: Mikrochip, Tollwutimpfung und ein internationales Gesundheitszeugnis; Rückreise in die EU: ein vorheriger Tollwut-Titer-Test ist Pflicht, organisieren Sie ihn vor der Abreise.`],
    sights: {
      "Jemaa el-Fnaa": `Der große Platz der Medina, als immaterielles UNESCO-Kulturerbe gelistet, verwandelt sich jeden Abend in ein Freilufttheater. Gehen Sie mit Hund morgens hin, wenn der Platz ruhig ist: die abendlichen Menschenmassen, Schlangenbeschwörer und Affen machen ihn zu einem stressigen Ort für ein Tier.`,
      "Jardin Majorelle": `Jacques Majorelles kobaltblauer Garten, restauriert von Yves Saint Laurent, ist einer der meistbesuchten Orte Marokkos. Hunde sind nicht zugelassen: Besuchen Sie ihn abwechselnd und treffen Sie sich danach auf den breiten schattigen Alleen des benachbarten Gueliz wieder.`,
      "Jardins de la Ménara": `Dieser weitläufige Olivengarten aus dem 12. Jahrhundert umgibt ein almohadisches Wasserbecken mit dem verschneiten Atlas im Hintergrund. Seine breiten, ruhigen Alleen gehören zu den wenigen Orten der Stadt, an denen man einen angeleinten Hund gelassen spazieren führen kann, am besten früh morgens.`,
      "La Palmeraie": `Nördlich der Stadt, 13.000 Hektar Dattelpalmen, gepflanzt seit almoravidischer Zeit, durchzogen von Pisten. Es ist das beste Gelände für Hundespaziergänge in Marrakesch: Platz, relativer Schatten und Ruhe, meiden Sie die Quad-Bike- und Kamelrouten.`,
      "Koutoubia": `Das 77 Meter hohe Minarett der größten Moschee der Stadt ist seit dem 12. Jahrhundert Marrakeschs Wahrzeichen. Die Moschee ist Gläubigen vorbehalten; die Gärten und die Esplanade darum, angenehm bei Sonnenuntergang, lassen sich jedoch an der Leine umrunden.`,
      "Remparts et Bab Agnaou": `Die 19 km langen, rot-erdfarbenen Wallanlagen, unterbrochen von monumentalen Toren, darunter das prächtige almohadische Bab Agnaou, lassen sich zu Fuß oder mit der Kutsche verfolgen. Ein angeleinter Spaziergang bei Tagesanbruch, wenn das Licht die Mauern zum Glühen bringt, zeigt die Rote Stadt von ihrer besten Seite.`,
    },
  },
  marseille: {
    history: `Marseille ist Frankreichs älteste Stadt, 600 v. Chr. von phokäischen Griechen gegründet, sie trägt 2.600 Jahre mediterrane Hafenkultur in sich. Eine kosmopolitische Arbeiterstadt, Marseille pflegt einen unprätentiösen Umgang mit Tieren: Hunde begleiten ihre Halter an den Kais des Vieux-Port, in den Bars des Panier und auf den Wegen der Calanques. Der Nationalpark Calanques, 2012 am Stadtrand geschaffen, bietet eine in Europa unvergleichliche Kulisse: 20 km wilde Küste, zu Fuß oder per Boot erreichbar, wo angeleinte Hunde erlaubt sind. Die Stadt verfügt zudem über 70 km Küste und mehr als 30 Parks, einige mit eigenen Hundezonen.`,
    petTips: [`Sengende Sommer: Bodentemperaturen übersteigen mittags im Juli-August 55 °C. Gehen Sie mit Ihrem Hund nur vor 9 Uhr oder nach 18 Uhr spazieren.`, `Große Hunde sind in der RTM-Metro und den Bussen VERBOTEN, planen Sie Uber, Bolt oder ein hundefreundliches Taxi ein.`, `Der Parc Longchamp hat eine 6.000 m² große Hundezone, nur über den Eingang Métro 5 Avenues zugänglich.`, `Stadtstrände (Prado, Catalans, Prophète) verbieten Hunde vom 1. Juni bis 30. September, weichen Sie stattdessen auf die Frioul-Inseln aus.`, `Notfalltierarzt: Vétérinaires 2 Toute Urgence unter +33 4 91 13 44 44 (La Valentine), oder wählen Sie 3115 kostenlos von jedem französischen Telefon.`],
    practicalInfo: [`Der Flughafen Marseille Provence (MRP) liegt 27 km nördlich, der Flughafenshuttlebus nimmt Hunde in Transportboxen mit (8 €).`, `Ab Paris: direkter TGV (3 Std. 15 Min.), Hunde mit einem speziellen Ticket willkommen (7 € für kleine Hunde, Kindertarif für große Hunde).`, `Beste Reisezeit: April-Juni und September-Oktober. Meiden Sie Juli-August wegen extremer Hitze und Touristenmassen.`, `Bootscharter ab Vieux-Port mit Hund: auf ausgewählten Katamaranen möglich, buchen Sie bei Les Bateaux Marseillais.`, `Tierapotheken im 1. und 8. Arrondissement, die meisten von Montag bis Samstag 9-19 Uhr geöffnet.`],
    sights: {
      "Vieux-Port": `Das schlagende Herz Marseilles seit 26 Jahrhunderten. Die Kais sind durchweg hundefreundlich, mit haustierfreundlichen Cafeterrassen und einem Morgen-Fischmarkt. Ikonischer Blick hinauf zur Notre-Dame de la Garde.`,
      "Calanques National Park": `20 km wilde Küste direkt vor der Stadt. Hunde sind angeleint auf allen Wegen erlaubt, Sugiton, En-Vau, Marseilleveyre. Achten Sie auf sommerliche Sperrungen bei hoher Waldbrandgefahr.`,
      "Le Panier": `Marseilles ältestes Viertel, ein Labyrinth aus Kopfsteinpflastergassen, Street Art und Cafés. Mit Hund vollständig begehbar; mehrere Terrassen heißen Haustiere willkommen.`,
      "Corniche Kennedy": `5 km Küstenstraße zwischen dem Strand Catalans und dem Vallon des Auffes. Eigener Fußgängerweg und ständiger Meerblick, der beste Abendspaziergang der Stadt.`,
      "MuCEM": `Museum für europäische und mediterrane Zivilisationen. Hunde sind auf der Esplanade und den Außenwegen erlaubt, nur das Innere bleibt ihnen verwehrt.`,
      "Îles du Frioul": `Archipel, erreichbar per Fähre ab dem Vieux-Port (10 € Hin- und Rückfahrt, Hunde kostenlos). 10 Strände heißen angeleinte Hunde willkommen, die türkisfarbene Calanque de la Crine belohnt den einstündigen Fußweg.`,
    },
  },
  maspalomas: {
    history: `Maspalomas verdankt seine Existenz dem Tourismus: Bis in die 1960er-Jahre war die Südspitze Gran Canarias nur ein isolierter Leuchtturm, der Faro de Maspalomas, und ein weites Dünenfeld. Ein internationaler Planungswettbewerb 1961 begründete das Resort, das sich heute von Playa del Inglés bis Meloneras erstreckt und das Naturschutzgebiet der Dünen von Maspalomas sowie die Lagune La Charca umschließt. Es ist Europas Hauptstadt des Wintersonnenscheins, mit mildem subtropischem Klima das ganze Jahr über, trocken und hell. Für Hundehalter ist es ein ehrliches Paradox: Die berühmten Strände und geschützten Dünen sind für Hunde tabu, doch die langen Uferpromenaden eignen sich hervorragend für angeleinte Spaziergänge, besonders außerhalb der Saison, und die Nachbargemeinde Mogán eröffnete im Februar 2026 fünf offizielle Hundestrände.`,
    petTips: [`Die berühmten Strände (Playa de Maspalomas, Playa del Inglés) und die Dünen verbieten Hunde das ganze Jahr über, mit Bußgeldern bis zu 1.500 Euro.`, `Für einen Strandtag steuern Sie die offiziellen Hundestrände von Mogán an (El Perchel, Los Frailes) oder Los Tres Peos bei Agüimes.`, `Sommerhitze: Gehen Sie früh oder nach Sonnenuntergang mit dem Hund spazieren und führen Sie Wasser mit, da Sand und Pflaster mittags sehr heiß werden.`, `In den Global-Bussen reisen Haustiere unter 10 kg in einer Transportbox (max. 60x35x35 cm) auf Ihrem Schoß in der Kabine mit; größere Hunde fahren im Laderaum.`, `Notfälle: Die Clínica Veterinaria Maspalomas in San Fernando betreibt eine 24-Stunden-Notrufnummer unter +34 928 76 58 96.`],
    practicalInfo: [`Der Flughafen Gran Canaria (LPA) liegt etwa 30 bis 40 Minuten mit dem Auto entfernt; die Insel hat keine Eisenbahn, man fliegt also ein und bewegt sich mit Bus, Taxi oder Auto fort.`, `Spanien gehört zur EU und zum Schengen-Raum: Ein EU-Heimtierausweis mit Mikrochip und gültiger Tollwutimpfung ist erforderlich.`, `Beste Reisezeit: Oktober bis April, Tageshöchsttemperaturen um 20 °C, ruhige Promenaden und keine Mittagshitze.`, `Wenige klassische Parks: die wichtigste Grünfläche ist der Parque Tony Gallardo, ansonsten die Promenaden von Meloneras und dem Leuchtturm nutzen.`, `Hundebetreuung: Plattformen wie Gudog und die Residencia Canina Maspalomas für Tage oder Nächte ohne Ihren Hund.`],
    sights: {
      "Faro de Maspalomas": `Der Leuchtturm aus dem 19. Jahrhundert markiert die Südspitze der Insel. Der umliegende Boulevard El Faro ist eine Freiluftpromenade, auf der angeleinte Hunde willkommen sind. Kostenlos und bei Sonnenuntergang wunderschön.`,
      "Dunas de Maspalomas": `Das ikonische Dünenfeld, ein geschütztes Naturschutzgebiet. Hunde sind hier wie am Strand verboten: Bewundern Sie es von den Aussichtspunkten und markierten Wegen am Rand.`,
      "La Charca de Maspalomas": `Eine Salzwasserlagune und ein Vogellebensraum am Fuß des Leuchtturms. Angeleinte Hunde sind auf dem Steg und den umliegenden Wegen erlaubt, nicht aber im Schutzgebiet selbst. Bringen Sie ein Fernglas mit.`,
      "Paseo de Meloneras": `Eine breite gepflasterte Uferpromenade zwischen Leuchtturm und Klippen, gesäumt von Terrassen. Der einfachste Ort in Maspalomas, um mit angeleintem Hund und Meerblick zu flanieren.`,
      "Playa de El Perchel (Arguineguín, Mogán)": `Der nächstgelegene offizielle Hundestrand, etwa 20 Minuten westlich, im Februar 2026 von Mogán eröffnet. Begrenzte Öffnungszeiten, etwa 07:00 bis 10:00 und 18:00 bis 21:00 Uhr, innerhalb einer markierten Zone.`,
      "San Fernando de Maspalomas": `Die Wohnstadt hinter den Resorts, mit Geschäften, Tierkliniken und dem Parque Tony Gallardo. Hier findet man das lokale Leben und die praktischen Dienstleistungen für einen Hund.`,
    },
  },
  matera: {
    history: `Matera, rund 60.000 Einwohner in der Basilikata, Süditalien, ist eine der ältesten durchgehend bewohnten Siedlungen der Welt, seit dem Paläolithikum besiedelt. Seit 1993 UNESCO-Weltkulturerbe und 2019 Europäische Kulturhauptstadt, ist es berühmt für die Sassi, zwei Höhlenwohnviertel (Sasso Caveoso und Sasso Barisano), die aus dem Kalkstein über der Schlucht Gravina gehauen wurden. Einst als Schande Italiens gebrandmarkt wegen der Armut seiner Höhlen, die in den 1950er-Jahren geräumt wurden, hat sich die Stadt als Filmkulisse (Die Passion Christi, Keine Zeit zu sterben) und gehobenes Reiseziel neu erfunden. Bei Hunden gelten die italienischen Regeln: Leinenpflicht im öffentlichen Raum, ein Maulkorb muss mitgeführt werden (auf Aufforderung des Personals in Verkehrsmitteln anzulegen) und Kot muss aufgesammelt werden. Die Steingassen und Treppen der Sassi sind mit Hund begehbar, verschleißen aber schnell die Pfoten; der weitläufige Parco della Murgia Materana auf der anderen Seite der Schlucht bietet dagegen hervorragende, für angeleinte Hunde offene Wanderwege.`,
    petTips: [`Steintreppen der Sassi: Der polierte Kalkstein ist bei Nässe rutschig und heizt sich an Sommernachmittagen glühend auf. Bei älteren oder kurzbeinigen Hunden früh morgens absteigen und planen Sie, sie auf den steilsten Treppen zu tragen.`, `Italienische Regeln: In der gesamten Öffentlichkeit gilt Leinenpflicht, ein Maulkorb muss mitgeführt werden (auf Anfrage in Bussen und Zügen anzulegen) und Kotbeutel sind Pflicht.`, `Tierärzte: Ambulatorio Veterinario Vetland (Via Cicerone 31, +39 333 698 9063) und Centro Veterinario Croce Blu (Via della Croce 29/31, +39 0835 262584, Notfälle). Die zentrale 24-Stunden-Klinik bleibt das Ospedale Veterinario Santa Fara in Bari (+39 080 504 6965), 65 km entfernt.`, `Parco della Murgia: Auf dem Plateau gibt es keine Wasserstelle, und der Kalksteinboden ist scharfkantig und ohne Schutz. Führen Sie 1,5 l Wasser pro Hund mit, brechen Sie im Sommer vor 9:00 Uhr auf und achten Sie im Frühling auf Grannen im Gras.`, `Menschenmassen und Filmdrehs: Die Sassi füllen sich mittags und während Filmdrehs. Gehen Sie mit dem Hund bei Tagesanbruch oder abends spazieren für ruhige Gassen und kühlen Stein.`],
    practicalInfo: [`Anreise: Matera hat keinen eigenen Flughafen; der nächste ist Bari (BRI, 65 km), verbunden durch den Pugliairbus-Shuttle in 1 Std. 15 Min. Der FAL-Zug ab Bari Centrale (1 Std. 15 Min. bis 1 Std. 30 Min.) befördert Hunde kostenlos; Marozzi-Fernbusse fahren aus Rom und Neapel.`, `Dokumente: EU-Heimtierausweis, ISO-Mikrochip und eine mindestens 21 Tage alte Tollwutimpfung für EU-Besucher; ein Animal Health Certificate (AHC), ausgestellt innerhalb von 10 Tagen, für Besucher außerhalb der EU (Großbritannien nach dem Brexit eingeschlossen).`, `Örtlicher Nahverkehr: Die Altstadt und die Sassi werden zu Fuß erkundet; Stadtbusse akzeptieren angeleinte Hunde mit mitgeführtem Maulkorb, kleine Hunde in geschlossener Transportbox reisen kostenlos. Viele Gassen sind nur zu Fuß erreichbar.`, `Hundebetreuung: Rover, Pawshake und DogHero decken Matera ab; rechnen Sie mit etwa 15 € pro Nacht für die Betreuung zu Hause und 12 € pro Spaziergang; buchen Sie frühzeitig für Frühlingswochenenden und Ferragosto (15. August).`, `Klima: sehr heiße, trockene Sommer 27-32 °C, milde Winter 7-10 °C mit Regen von November bis Februar; beste Monate mit Hund: April-Mai und Ende September-Oktober, wenn der Stein nicht glüht.`],
    sights: {
      "Sasso Caveoso": `Das dramatischere der beiden Höhlenviertel, ein Amphitheater über der Schlucht mit terrassierten Höhlenhäusern und in den Fels gehauenen Kirchen. Zu jeder Tageszeit frei angeleint begehbar; halten Sie den Hund auf den polierten Steintreppen kurz und führen Sie Wasser mit, da es fast keinen Schatten gibt.`,
      "Parco della Murgia Materana": `Ein 8.000 Hektar großer Regionalpark auf der anderen Seite der Schlucht Gravina, gesprenkelt mit mehr als 150 Felskirchen und prähistorischen Höhlen. Die Wege stehen angeleinten Hunden offen und bieten Materas schönsten Naturausflug; brechen Sie früh auf, da das Kalksteinplateau der Sonne voll ausgesetzt ist.`,
      "Belvedere di Murgia Timone": `Ein Aussichtspunkt auf dem Murgia-Plateau mit dem postkartenreifen Panorama über die gesamten Sassi, berühmt als Filmkulisse. Frei angeleint erreichbar, am schönsten bei Sonnenuntergang; erreichbar mit dem Auto oder über den Pfad, der in die Schlucht hinab und wieder hinaufführt, also Wasser und gutes Schuhwerk mitbringen.`,
      "Piazza Vittorio Veneto": `Der große, lebendige Platz der Oberstadt (des Piano), Treffpunkt der Einheimischen und offener Balkon über dem Sasso Barisano. Immer geöffnet und ideal an der Leine, mit hundetoleranten Cafeterrassen und Zugang zur unterirdischen Zisterne Palombaro Lungo (Hunde im Inneren nicht zugelassen).`,
      "Piazza San Pietro Caveoso": `Ein kleiner Platz am Rand des Abgrunds, beherrscht von der Kirche San Pietro Caveoso und dem Felsen Madonna de Idris, einer der meistfotografierten Aussichtspunkte der Stadt. Der offene Platz ist zu jeder Tageszeit an der Leine frei zugänglich; die Innenräume der Felskirchen bleiben Hunden verschlossen.`,
      "Cattedrale di Matera": `Eine apulisch-romanische Kathedrale aus dem 13. Jahrhundert auf dem höchsten Tuffsteinsporn der Stadt zwischen den beiden Sassi, mit einem Vorplatz, der über die Dächer abfällt. Der Vorplatz und die umliegenden Gassen sind an der Leine frei zugänglich; das Innere der Kathedrale ist Assistenzhunden vorbehalten.`,
    },
  },
  melbourne: {
    history: `Hauptstadt von Victoria und mit rund 5,2 Millionen Menschen Australiens zweitgrößte Stadt, wuchs Melbourne 1835 aus einem Lager am Yarra, auf dem Land der Wurundjeri und Boonwurrung des Kulin-Nation-Verbunds. Der Goldrausch der 1850er-Jahre machte es innerhalb weniger Jahrzehnte zu einer der reichsten Städte der Erde, weshalb es monumentale Boulevards, viktorianische Arkaden und einen Ring großer öffentlicher Parks besitzt. Das 20. Jahrhundert schichtete griechische, italienische und vietnamesische Migration darüber, die seine Kaffee- und Gassenkultur begründete. Für einen Hund ist es wohl die praktikabelste Großstadt Australiens: S-Bahnen nehmen Hunde jeder Größe mit Maulkorb und Leine mit, an der Port Phillip Bay reihen sich ruhige Hundestrände, und die innenstadtnahen Parks haben ausgeschilderte Freilaufzonen. Der Preis: Victoria verlangt überall sonst standardmäßig eine Leine, und die Einreise nach Australien führt zwingend über die Quarantäneeinrichtung Mickleham nördlich der Stadt.`,
    petTips: [`Verkehrsmittel: S-Bahnen befördern Hunde jeder Größe kostenlos, ein großer Hund braucht dabei sowohl Maulkorb ALS AUCH Leine; Trams und Busse akzeptieren nur kleine Tiere in einer Transportbox. Mit einem großen Hund planen Sie den Tag um Züge und Fußwege.`, `Strände: Vom 1. April bis 31. Oktober sind die Strände der City of Port Phillip für Hunde geöffnet; vom 1. November bis 31. März verengt sich der Zugang auf ausgewiesene Abschnitte oder das Zeitfenster von 19:30 bis 10:00 Uhr. Sandown Street (Brighton) und St Kilda West bleiben ganzjährig geöffnet.`, `Leine: In Victoria gilt standardmäßig überall im öffentlichen Raum Leinenpflicht. Freilauf gilt nur innerhalb einer markierten Zone, und Sie müssen selbst dann eine Leine mitführen, während der Hund frei läuft.`, `Hitze: Melbourne kann im Januar und Februar 35 °C überschreiten und bei einem Südwechsel innerhalb einer Stunde um 15 Grad fallen. Testen Sie den Asphalt mit der Hand, gehen Sie vor 9 Uhr oder nach 18 Uhr spazieren und lassen Sie einen Hund nie im Auto zurück.`, `Schlangen: Die Saison läuft grob von September bis April im urbanen Buschland (Yarra Bend, Westerfolds, Bachläufe). Bleiben Sie auf angelegten Wegen und kennen Sie Ihre nächste 24-Stunden-Tierklinik, bevor Sie losgehen, denn ein Biss ist ein lebensbedrohlicher Notfall.`],
    practicalInfo: [`Anreise: Flughafen Melbourne (MEL, Tullamarine), 23 km nordwestlich der Innenstadt. Er ist der EINZIGE Einreisepunkt für Hunde und Katzen nach Australien, die alle durch die Quarantäneeinrichtung Mickleham (135 Donnybrook Road) müssen, rund 30 km vom Flughafen entfernt.`, `Papierkram: Die Einfuhr erfordert einen ISO-Mikrochip, Tollwutimpfung, einen Antikörper-Titer-Test mit strenger Identitätsprüfung, eine Wartefrist, eine Einfuhrgenehmigung sowie mindestens 10 Tage in Mickleham. Rechnen Sie mit fast einem Jahr und bestätigen Sie die aktuellen Schritte beim Department of Agriculture, Fisheries and Forestry.`, `Örtlicher Nahverkehr: S-Bahnen kostenlos für Haustiere jeder Größe (Maulkorb plus Leine für große Hunde); Trams und Busse nur für kleine Tiere in Transportbox; V/Line-Regionalzüge nur mit Transportbox, keine Tiere in V/Line-Fernbussen. Taxis und Fahrdienste nach Ermessen des Fahrers.`, `Betreuung: städtische Tagesstätten (Dogs HQ, 86-88 Hoddle Street in Abbotsford; Diggiddy Doggy Daycare, 41 Brady Street in South Melbourne) und private Betreuer über Mad Paws. Aktuelle Impfungen einschließlich Zwingerhusten sowie ein Probetag werden generell verlangt.`, `Tierärztliche Notfälle: Advanced Vetcare, 26 Robertson Street, Kensington, +61 3 9092 0400, 24/7 geöffnet; Greencross Vet Hospital, Gate 2, 250 Princes Highway, Werribee, +61 3 8721 1414, 24/7 geöffnet; Advanced Vetcare Kew, 2-6 Chandler Highway, +61 3 9020 3555, Notfallsprechstunden 16 bis Mitternacht werktags und 7 bis Mitternacht am Wochenende und an Feiertagen. 000 ist nur für Menschen.`],
    sights: {
      "Royal Botanic Gardens Melbourne": `Achtunddreißig Hektar gestalteter Garten am Südufer des Yarra, angelegt um einen Ziersee. Hunde an kurzer Leine sind während der Öffnungszeiten kostenlos und ohne Größenbegrenzung zugelassen, und beim Punting on the Lake nimmt man sogar einen wohlerzogenen Hund mit an Bord.`,
      "St Kilda Pier and Esplanade": `Melbournes klassischer Meeresausflug: ein langer Pier hinaus in die Bucht, eine palmengesäumte Promenade und sonntags der Kunst- und Handwerksmarkt der Esplanade. Hunde an der Leine willkommen auf dem Pier und über den Markt hinweg; die Zwergpinguinkolonie im Wellenbrecher steht unter Schutz, halten Sie den Hund also auf dem Steg.`,
      "Yarra Bend Park and Dights Falls": `260 Hektar natürliches Buschland 4 km von der Innenstadt entfernt, mit ausgewiesenen Freilaufzonen und einem einfachen Uferweg zu den Dights Falls, wo eine Felsböschung Zugang zum Wasser gibt. Bleiben Sie von September bis April auf den Wegen: Am Flusskorridor leben Tigerottern-Schlangen.`,
      "Brighton Dog Beach (Sandown Street)": `Der einzige Strand Melbournes, der vollständig eingezäunt ist mit selbstschließendem Tor, an dem Hunde ganzjährig 24 Stunden ohne saisonale Einschränkung frei laufen. Das Buchtwasser ist flach und wellenfrei; kostenlose Parkplätze sind sehr begrenzt, planen Sie mit dem gebührenpflichtigen Bereich bei den Middle Brighton Baths.`,
      "Hosier Lane and the CBD laneways": `Melbournes Straßenkunst ist ein kostenloses Freilufterlebnis, und ein angeleinter Hund passt perfekt dazu: Hosier Lane, AC/DC Lane und Degraves Street ergeben eine einstündige Runde ab der Flinders Street. Die Cafés in den Gassen servieren draußen, sodass die Kaffeepause auch mit Hund funktioniert.`,
      "Melbourne Zoo": `Der Zoo liegt als Enklave mitten im Royal Park und lässt keine Haustiere zu, akkreditierte Assistenztiere ausgenommen. Der umliegende Park bleibt geöffnet und hat drei Freilaufzonen, überlassen Sie den Hund also einem Betreuer oder teilen Sie die Gruppe für den Besuch.`,
    },
  },
  menton: {
    history: `Als letzte französische Stadt vor Italien war Menton jahrhundertelang Besitz der Grimaldis von Monaco, bevor es sich 1861 für Frankreich entschied. Sein Mikroklima, das mildeste des Landes, machte es zum bevorzugten Winterkurort der englischen und russischen Aristokratie der Belle Époque, die Akklimatisationsgärten anlegte, die legendär wurden: Serre de la Madone, Val Rahmeh, die Citronneraie. Die Zitrone ist hier König, gefeiert jeden Februar beim Fête du Citron mit seinen Zitrusumzügen. Die Altstadt, eine Kaskade ockerfarbener Fassaden und Treppengassen, gekrönt von der Basilika Saint-Michel-Archange, fällt hinunter zur Promenade du Soleil und den Stränden. Zwischen dem Ufer, den Wegen des Cap Martin und den Bergdörfern im Landesinneren eignet sich Menton hervorragend zum Reisen mit Hund, in einer fast italienischen Süße des Lebens.`,
    petTips: [`Mentons überwachte Strände sind während der Badesaison für Hunde gesperrt: Weichen Sie für ein Bad in der Bucht auf den Cap-Martin-Weg am frühen Morgen aus und beachten Sie die Beschilderung, die sich jedes Jahr ändert.`, `Von Mitte Februar bis Anfang März füllt das Fête du Citron drei Wochen lang das Zentrum mit Umzugswagen, Blaskapellen und Menschenmassen: Wenn Ihr Hund Lärm nicht mag, bleiben Sie auf der Garavan-Seite und meiden Sie die Jardins Bioves während der Umzüge.`, `Die botanischen Gärten, die Menton berühmt gemacht haben (Serre de la Madone, Val Rahmeh), lassen keine Hunde zu: Organisieren Sie den Besuch im Wechsel, oder bevorzugen Sie die Olivenhaine des Parc du Pian, offen für angeleinte Hunde.`, `Italien ist zu Fuß zwanzig Minuten entfernt über die Grenze bei Garavan: ein EU-Ausweis und aktuelle Impfunterlagen reichen für den Spaziergang nach Ventimiglia, aber freitags, dem Markttag, lassen Sie den Hund besser an einem kühlen Ort, das Gedränge ist heftig.`, `Im Sommer speichern die Treppengassen der Altstadt Hitze: Steigen Sie vor 10 Uhr zur Basilika hinauf, bieten Sie oft Wasser an und ziehen Sie sich in den heißen Stunden ins Landesinnere zurück (Sainte-Agnès, Gorbio), dort ist es 5 bis 8 Grad kühler.`],
    practicalInfo: [`Mehrere Tierarztpraxen in Menton und Roquebrune-Cap-Martin; für nächtliche Notfälle wählen Sie 3115, die kostenlose französische Landesnummer, die Sie zum nächsten diensthabenden Dienst verbindet.`, `Europäische Notrufnummer: 112; die Gemeindepolizei kann Ihnen sagen, welche Strände und Zeiten Hunde erlauben.`, `Zoohandlungen und Haustierabteilungen in den Supermärkten des Zentrums und des Carei-Viertels; Hundesalons in der Stadt.`, `TER-Züge auf der Linie Nizza-Ventimiglia: kleine Hunde in Taschen reisen kostenlos, große Hunde angeleint und mit Maulkorb zum halben Fahrpreis; Zest-Busse: kleine Hunde in Transportboxen.`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung sind erforderlich, auch für den Spaziergang hinüber nach Italien und zurück; Vorbeugung gegen Leishmaniose und Sandmücken wird von April bis November an der Riviera empfohlen.`],
    sights: {
      "Promenade du Soleil": `Mentons Uferpromenade verläuft von den Sablettes-Stränden bis zum Casino, gegenüber der Altstadt, die bei Sonnenuntergang leuchtet. An der Leine ist sie der rituelle Morgen- und Abendspaziergang, verlängert durch die Eugenie-Mole, die die perfekte Postkartenansicht der ockerfarbenen Fassaden einrahmt.`,
      "Vieille Ville": `Gewölbte Gassen, Kieselsteintreppen und genuesische Fassaden: Alt-Menton steigt vom Meer zum Vorplatz der Basilika Saint-Michel-Archange hinauf, einem Barockmeisterwerk, dessen Kieselstein-Mosaikplatz gen Italien blickt. Der angeleinte Aufstieg ist steil, aber kurz, und die Belohnung total.`,
      "Jardin Serre de la Madone": `Von Lawrence Johnston im Tal von Gorbio angelegt, staffelt dieser denkmalgeschützte Garten Wasserbecken, Terrassen und seltene Pflanzen aus fünf Kontinenten. Wie die meisten botanischen Gärten Mentons, einschließlich Val Rahmeh, lässt er keine Hunde zu: Planen Sie einen Betreuerwechsel für den Besuch.`,
      "Sentier du littoral du Cap-Martin": `Ab der Bucht von Roquebrune umrundet der Zollweg das Cap Martin zwischen Pinien, versteckten Villen und weißen Kalksteinbuchten, mit Menton und den italienischen Alpen im Hintergrund. An der Leine ist es die schönste Küstenwanderung der Gegend, selbst im Sommer dank der Brise kühl.`,
      "Plage des Sablettes": `Am Fuß der Altstadt ist dieser umgestaltete Kieselstrand Mentons fotogenster. Hunde sind hier während der Badesaison verboten, wie an den meisten überwachten Stränden der Stadt; außerhalb der Saison kehrt die morgendliche Toleranz zurück, prüfen Sie die Schilder vor Ort.`,
      "Sainte-Agnès": `800 Meter über Menton konkurriert dieses mittelalterliche, an die Klippe geklammerte Dorf mit Gorbio um den Titel des schönsten Balkons der Küste. Kopfsteinpflastergassen, Burgruinen und Panoramawege funktionieren alle sehr gut an der Leine, angenehm kühl, wenn die Küste schwitzt.`,
    },
  },
  miami: {
    history: `Zwischen Atlantik und Everglades gelegen, ist Miami eine tropische Metropole in Florida, entstanden um die Wende zum 20. Jahrhundert und geprägt von aufeinanderfolgenden Migrationswellen, insbesondere von Kubanern, die ihr ihre lateinisch-karibische Seele gaben. South Beach reiht seine pastellfarbenen Art-déco-Hotels entlang des Ocean Drive auf, während Wynwood seine Wände mit riesigen Wandgemälden bedeckt und Little Havana im Rhythmus von Domino und kubanischem Kaffee lebt. Es ist eine heiße, feuchte, weitläufige Stadt, in der man sich meist mit dem Auto fortbewegt, auch wenn South Beach zu Fuß erkundbar ist. Für Hunde ist Florida anspruchsvoll: Die meisten Strände verbieten Tiere, Hitze und Feuchtigkeit können gefährlich werden, und die Hurrikansaison läuft von Juni bis November. Gut vorbereitet findet der Reisende mit Hund lebendige Gehwege, Parks, einladende Terrassen und einige eigene Hundestrände entlang der Küste.`,
    petTips: [`Saisonaler Hinweis: Die Sommer in Florida sind sengend heiß und feucht, und die Hurrikansaison läuft von Juni bis November; verfolgen Sie Wetterwarnungen und vermeiden Sie Hundespaziergänge in den heißesten Stunden.`, `Sand und Asphalt können Temperaturen erreichen, die Pfotenballen verbrennen: Testen Sie den Boden mit der Hand, gehen Sie früh oder spät spazieren und führen Sie reichlich Wasser mit.`, `Die meisten Strände Miamis verbieten Hunde; für ein Bad steuern Sie eigene Hundestrände wie den Hollywood Dog Beach mit eigenen Zeiten und Genehmigungen an.`, `Miami ist weitläufig und autoabhängig: Halten Sie den Hund im klimatisierten Komfort und lassen Sie ihn nie allein im Auto, auch nicht für wenige Minuten.`, `Führen Sie überall Wasser und Schatten mit, achten Sie auf Anzeichen von Hitzschlag (starkes Hecheln, Antriebslosigkeit) und suchen Sie sich im Voraus eine tierärztliche Notfallklinik.`],
    practicalInfo: [`Allgemeine Notrufnummer in den Vereinigten Staaten: 911; es gibt keine einzelne tierärztliche Notrufnummer, suchen Sie sich also im Voraus eine 24-Stunden-Notfallklinik.`, `Papierkram: Miami liegt in den Vereinigten Staaten, außerhalb der EU-Heimtierausweis-Zone; internationale Besucher müssen die US-Einfuhrregeln (CDC) für Hunde befolgen.`, `Anreise: Der Flughafen Miami International (MIA) und Fort Lauderdale (FLL) bedienen die Region; außerhalb von South Beach ist ein Auto praktisch unverzichtbar.`, `Die meisten öffentlichen Strände verbieten Hunde: Prüfen Sie das von Stadt zu Stadt und bevorzugen Sie offizielle Hundestrände und erlaubte Parks.`, `Planen Sie mit Klimaanlage, reichlich Wasser und frühmorgendlichen oder abendlichen Ausflügen; in der Stadt und in Parks gilt Leinenpflicht.`],
    sights: {
      "South Beach & Art Deco Historic District": `Das Art-déco-Viertel von South Beach mit dem Ocean Drive und seinen pastellfarbenen Fassaden aus den 1930er-Jahren. Angeleinte Hunde sind auf den Gehwegen und der Promenade erlaubt, aber nicht auf dem größten Teil des Sandes, wo sie verboten sind.`,
      "Wynwood Walls": `Das Kunstviertel Wynwood, berühmt für seine riesigen Open-Air-Wandgemälde. Angeleinte Hunde schlendern durch die Straßen und an den bemalten Wänden vorbei; das kostenpflichtige Wynwood-Walls-Areal kann sie jedoch abweisen.`,
      "Bayfront Park & Miami Riverwalk": `Der Bayfront-Park in der Innenstadt und der Weg entlang des Miami River, mit Blick auf Wolkenkratzer und Boote. Offene Flächen, auf denen angeleinte Hunde willkommen sind, am besten früh morgens bei der Hitze begangen.`,
      "Vizcaya Museum & Gardens": `Die Villa im italienischen Renaissancestil und ihre formalen Gärten an der Biscayne Bay. Das Anwesen lässt nur Assistenztiere zu; Haustiere sind nicht erlaubt, auch nicht in den Gärten.`,
      "Key Biscayne & Crandon Park": `Die Insel Key Biscayne und der weitläufige Crandon Park, beliebt wegen ihrer Strände und Radwege. Hunde sind auf dem Sand und den Parkstränden verboten; prüfen Sie die örtlichen Regeln, bevor Sie hinfahren.`,
      "Hollywood Dog Beach": `Hollywoods offizieller Hundestrand nördlich von Miami, einer der wenigen, an denen Hunde zu festgelegten Zeiten und mit Genehmigung auf den Sand dürfen. Ideal für ein beaufsichtigtes Bad außerhalb der heißesten Stunden.`,
    },
  },
  milan: {
    history: `Mailand, Hauptstadt der Lombardei und Italiens Finanz- und Modekraftwerk, führt seine Ursprünge auf die keltische Siedlung Medhelan um 600 v. Chr. zurück, bevor es 286 n. Chr. römische Kaiserresidenz wurde. Heute vereint es gotische Pracht, der Dom mit seinen 135 Türmchen brauchte fast sechs Jahrhunderte zur Vollendung, mit den eleganten Wolkenkratzern von Porta Nuova und den restaurierten Navigli-Kanälen. Der Mailänder Lebensstil ist bekanntermaßen hundefreundlich: Italiens höchste Haustierdichte pro Kopf zeigt sich in makellos gestylten Hunden in den Boutiquen des Quadrilatero, auf Aperitivo-Terrassen entlang der Navigli und bei Sonntagsspaziergängen im Parco Sempione. Die Stadt beherbergt sogar die jährliche Haustiermesse 'Quattrozampeinfiera' in der Fiera Milano. Haustiere sind in den ATM-Verkehrsmitteln, U-Bahn, Tram und Bus, vollständig willkommen, sofern sie sowohl Leine als auch Maulkorb tragen, eine Regel, die hier strenger durchgesetzt wird als in den meisten italienischen Städten.`,
    petTips: [`Die ATM-Verkehrsmittel erlauben Hunde in U-Bahn, Tram und Bus nur mit Leine UND Maulkorb, führen Sie also selbst für winzige Hunde einen Beißkorb mit; Fahrscheinkontrolleure prüfen das.`, `Kleine Hunde in vollständig geschlossenen Transportboxen fahren kostenlos mit ATM; größere Hunde benötigen ein normales Stadtticket (2,20 EUR).`, `Die Stadt verbietet Hunde auf dem Rasen der Piazza della Scala und im Innenhof der Pinacoteca di Brera, nutzen Sie stattdessen die umliegenden Straßen.`, `Mailänder Sommer erreichen 36 °C bei hoher Luftfeuchtigkeit; die U-Bahn-Stationen bleiben kühl, aber nur zum Durchgehen, nicht zum Verweilen.`, `Aperitivo-Terrassen entlang des Corso Como und der Navigli heißen Hunde willkommen, buchen Sie aber Innenrestaurants im Voraus, da nicht alle die Hundefreundlichkeit ausweisen.`],
    practicalInfo: [`Zwei Hauptflughäfen: Malpensa (MXP, 50 km) und Linate (LIN, 7 km); der Malpensa-Express-Zug akzeptiert angeleinte, mit Maulkorb versehene Hunde für 2,50 EUR.`, `Die Clinica Veterinaria Gran Sasso (Via Donatello) ist 24/7 geöffnet mit spezialisierter Notfallversorgung, etwa 2 km vom Dom entfernt.`, `Das italienische Recht begrenzt Leinen im öffentlichen Raum auf 1,5 m und verlangt einen mitgeführten Maulkorb; Mailand verhängt zudem Bußgelder für unterlassenes Aufsammeln von 100-450 EUR.`, `Hundetrinkbrunnen gibt es überall im Parco Sempione, in den Giardini Montanelli und in CityLife, Leitungswasser ist stadtweit unbedenklich.`, `Wintersmog und Januarkälte können die Temperatur nahe 0 °C bringen; Pfotenwachs schützt vor dem Streusalz auf vereisten Gehwegen.`],
    sights: {
      "Parco Sempione": `1888 hinter dem Castello Sforzesco angelegt, ist dieser 47 Hektar große Park Mailands grüne Lunge, mit einem See, dem Arco della Pace und vier eingezäunten Freilaufzonen für Hunde. Jeden Morgen vor Bürobeginn füllt er sich mit Mailändern und ihren Hunden.`,
      "Navigli (Naviglio Grande & Pavese)": `Das im 12. Jahrhundert teilweise von Leonardo da Vinci entworfene Kanalviertel ist heute Mailands Nachtlebenader, mit Treidelpfaden, perfekt für abendliche Spaziergänge. Fast jede Aperitivo-Bar am Wasser akzeptiert nach 18:00 Uhr angeleinte Hunde auf der Terrasse.`,
      "Duomo di Milano": `Die viertgrößte Kathedrale Europas, 1386 begonnen, beherrscht mit ihren Türmen aus Candoglia-Marmor den Stadtplatz. Hunde sind auf der Piazza del Duomo willkommen, aber nicht in der Kathedrale, dem Baptisterium oder auf den Dachterrassen.`,
      "Brera District": `Ein bohemisches Gassenraster aus Kopfsteinpflaster rund um den Palazzo Brera aus dem 17. Jahrhundert, voller Galerien, Boutiquen und Cafés. Viele Geschäfte stellen Wassernäpfe auf, und der Orto Botanico di Brera lässt kleine angeleinte Hunde während seiner Öffnungszeiten zu.`,
      "CityLife Park": `Mailands neueste Grünfläche, 2018 rund um die Türme von Hadid, Isozaki und Libeskind eröffnet, erstreckt sich über 17 Hektar mit einer eigenen eingezäunten Hundeauslaufzone. Ihr flaches, verkehrsfreies Design eignet sich ideal für ältere Hunde und kleine Rassen.`,
      "Parco Nord Milano": `Ein 640 Hektar großer, wiederhergestellter Industriepark nördlich der Stadt, erreichbar mit der Tram 4 ab Cairoli in 25 Minuten. Weite Wiesen, Radwege und eine große eingezäunte Freilaufzone machen ihn zum beliebten Wochenendausflug der Mailänder Hundehalter.`,
    },
  },
  naxos: {
    history: `Die größte und fruchtbarste Insel der Kykladen war einst ein bedeutendes Zentrum der kykladischen Kultur und später die Macht, die die archaische Ägäis beherrschte: Ihre Steinbrüche lieferten marmorne Kolosse und die berühmten unvollendeten Kuroi, die noch heute bei Apollonas und Melanes liegen. 1207 machte der Venezianer Marco Sanudo die Insel zur Hauptstadt des Herzogtums Archipelago und hinterließ der Chora ihre Burg auf dem Hügel und die Herrenhäuser mit Wappen. Naxos ist ebenso eine Insel der Bauern wie der Seefahrer und lebt von seinen Kartoffeln, Käsesorten und der Viehzucht ebenso wie vom Tourismus, was ihr ein authentisches Hinterland mit Bergdörfern wie Halki und Apiranthos verleiht. Zwischen der Portara, die sich gegen den Sonnenuntergang abzeichnet, den kilometerlangen Sandstränden der Westküste und den byzantinischen Pfaden im Landesinneren ist Naxos eine großzügige Insel für alle, die mit Hund unterwegs sind.`,
    petTips: [`Im Sommer dulden die ausgestatteten und bewachten Strände der Westküste tagsüber kaum Hunde: Zielen Sie früh morgens auf die wilden Enden von Plaka, Aliko oder Pyrgaki, und genießen Sie außerhalb der Saison, von Oktober bis Mai, völlige Freiheit.`, `Der Meltemi weht im Juli und August kräftig, besonders am Nachmittag: Aufgewirbelter Sand an den exponierten Stränden reizt die Augen der Hunde, bevorzugen Sie dann die geschützten südlichen Buchten oder die Dörfer im Landesinneren.`, `Auf den Fähren von Blue Star und ähnlichen Reedereien reisen Hunde mit Maulkorb und an der Leine auf den Außendecks oder in Haustierkabinen; schnelle Katamarane akzeptieren oft nur kleine Hunde in Transportboxen, prüfen Sie dies bei der Buchung.`, `Die byzantinischen Pfade der Tragea kreuzen Ziegenherden, Esel und Hofhunde: Behalten Sie im Landesinneren die Leine an und überlassen Sie die Wassertröge der Kapellen den einheimischen Tieren.`, `In der Chora und den Dörfern leben viele streunende Katzen, die von den Einwohnern gefüttert werden: Halten Sie die Leine in den engen Gassen kurz, besonders in der Dämmerung, wenn sie zahlreich auftauchen.`],
    practicalInfo: [`Tierarztpraxen in der Chora für die routinemäßige Versorgung; für ernste Notfälle befinden sich die bestausgestatteten Kliniken der Kykladen auf Syros oder in Athen, per Fähre erreichbar`, `Europäische Notrufnummer: 112; der örtliche Tierschutzverein kann helfen, wenn Sie ein Streunertier finden`, `Tierbedarfsregale in den Supermärkten der Chora und von Agios Georgios; Zoofachgeschäfte in Hafennähe`, `Blue-Star-Fähren: Hunde kostenlos auf den Außendecks, Maulkorb und Leine Pflicht, Haustierkabinen auf manchen Routen; KTEL-Inselbusse: kleine Hunde in der Transportbox`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich; verstärkter Parasitenschutz empfohlen, Zecken und Sandmücken sind von April bis Oktober auf den Kykladen aktiv`],
    sights: {
      "Portara": `Das monumentale Portal des im 6. Jahrhundert v. Chr. nie vollendeten Apollontempels steht auf der kleinen Insel Palatia, die durch einen Damm mit dem Hafen verbunden ist. Angeleinte Hunde schließen sich gerne der abendlichen Prozession zum Sonnenuntergang an: Es ist das abendliche Ritual der ganzen Insel, kostenlos und unvergesslich.`,
      "Kastro de la Chora": `Oben in der Altstadt bewahrt das befestigte Viertel der Venezianer seine Wappentore, katholischen Herrenhäuser und weiß gekalkten Gassen, in denen sich Verlaufen ein Vergnügen ist. Ein Spaziergang an der Leine ist am frühen Morgen ideal; die Museen des Viertels lassen keine Hunde zu.`,
      "Plaka": `Vier Kilometer blonder Sand und mit Wacholder bewachsene Dünen machen Plaka zum schönsten Strand der Insel. Außerhalb der Saison läuft Ihr Hund hier fast allein; im Sommer halten Sie sich an die unerschlossenen Enden, fernab von Liegen und bewachten Badezonen.`,
      "Halki": `Die frühere Hauptstadt der Insel im Herzen des Tragea-Tals reiht klassizistische Herrenhäuser, byzantinische Kirchen und die historische Brennerei von Kitron, dem Naxos-Zitronenlikör, aneinander. Die schattigen Gassen und umliegenden Olivenhaine eignen sich sehr gut für einen Spaziergang an der Leine.`,
      "Apiranthos": `Apiranthos, ein Marmordorf an den Hängen des Mount Fanari, besitzt blank polierte Pflastergassen, gewölbte Durchgänge und Terrassen mit Blick auf die Täler. Der Spaziergang an der Leine ist herrlich, und die Cafés an der Hauptstraße heißen ruhige Hunde gerne willkommen.`,
      "Kouros de Melanes": `In einem Obstgartental bei Melanes liegen zwei marmorne Kolosse aus dem 6. Jahrhundert v. Chr. unvollendet dort, wo ihre Bildhauer sie zurückließen. Die Freiluftstätte kann frei mit einem angeleinten Hund besucht werden, und der Weg zwischen den beiden Kuroi führt durch einen herrlichen mediterranen Garten.`,
    },
  },
  nazare: {
    history: `Nazaré verdankt seinen Namen einer Marienstatuette, die der Legende nach im 4. Jahrhundert aus Nazareth mitgebracht wurde, und seine Legende dem Wunder von 1182: Der Ritter D. Fuas Roupinho, der im Nebel einem Hirsch nachjagte, wurde von der Muttergottes vor dem Absturz gerettet. Die Einsiedelei Memória und das Heiligtum Sítio, hoch oben auf der Klippe 110 Meter über dem Strand, erinnern an dieses Ereignis. Unten lebte das Dorf jahrhundertelang vom Fischfang: Ochsen zogen Boote den Sand hinauf, Frauen in sieben Röcken trockneten Fisch auf Gestellen, eine Tradition, die am Strand noch lebendig ist. Seit 2011 hat der auf Nazaré gerichtete Unterwassercanyon Praia do Norte zur Welthauptstadt der Riesenwellen gemacht, die vor dem Fort São Miguel Arcanjo mit über 25 Metern gesurft werden. Zwischen der jahrhundertealten Standseilbahn, den Aussichtspunkten und dem riesigen Strand funktioniert Nazaré sehr gut mit Hund.`,
    petTips: [`Während der Badesaison von Juni bis September sind Hunde an bewachten portugiesischen Stränden verboten, Praia da Nazaré eingeschlossen: Weichen Sie auf die unbewachten Enden der Praia do Norte oder die Strandpromenade aus, und genießen Sie den Sand von Oktober bis Mai frei.`, `Lassen Sie Ihren Hund an der Praia do Norte niemals ans Wasser: Selbst wenn das Meer ruhig aussieht, sind die Strömungen des Unterwassercanyons tückisch, und im Winter überspülen die Riesenwellen ganze Sandabschnitte ohne Vorwarnung.`, `Die Standseilbahn akzeptiert Hunde, kleine in Taschen, große an der Leine und mit Maulkorb: Das ist die Regel in den öffentlichen Verkehrsmitteln Portugals, tragen Sie den Maulkorb also immer in Ihrer Tasche mit, auch wenn er selten benötigt wird.`, `Die Esplanade von Suberco und der Weg zum Leuchtturm verlaufen am Klippenrand entlang und sind oft sehr windig: Halten Sie die Leine in der Nähe der Geländer kurz, Windböen können kleine Hunde überraschen.`, `Die Fischtrockengestelle am Strand sind eine maximale geruchliche Versuchung: Halten Sie die Leine in diesem Bereich fest, die Verkäufer schätzen allzu neugierige Nasen nicht.`],
    practicalInfo: [`Tierkliniken in Nazaré sowie in den nahegelegenen Städten Caldas da Rainha und Leiria, wo sich die bestausgestatteten Notfalleinrichtungen der Region befinden`, `Europäische Notrufnummer: 112; die örtliche GNR kann Ihnen die geltenden Strandregeln mitteilen`, `Tierbedarfsregale in den Supermärkten Continente, Pingo Doce und Intermarché der Stadt; Zoofachgeschäfte in Caldas da Rainha`, `Standseilbahn und Stadtbusse: kleine Hunde in Taschen, große Hunde an der Leine und mit Maulkorb; Rede-Expressos-Fernbusse nach Lissabon: Tiere nur in der Transportbox, je nach Strecke im Gepäckraum`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich; Leishmaniose-Prophylaxe in Portugal von April bis November empfohlen, fragen Sie vor der Abreise Ihren Tierarzt`],
    sights: {
      "Sítio da Nazaré": `Das obere Viertel, hoch auf der Klippe, vereint das Heiligtum Unserer Lieben Frau von Nazaré, die Einsiedelei Memória und den Aussichtspunkt Suberco, 110 Meter über dem Ozean. Esplanade und Gassen können an der Leine begangen werden; die Kirchen lassen keine Hunde zu.`,
      "Ascensor da Nazaré": `Seit 1889 erklimmt die Standseilbahn die Klippe zwischen Strand und Sítio in wenigen Minuten. Begleitete Hunde sind zugelassen, kleine in Taschen und große nach portugiesischer Regel an der Leine und mit Maulkorb, manchmal gegen eine kleine Gebühr: Die Fahrt erspart allen einen mühsamen Aufstieg.`,
      "Farol da Nazaré": `Der auf dem Fort São Miguel Arcanjo gelegene Leuchtturm ist der Balkon der Riesenwellen von Praia do Norte: Im Winter beobachten Sie Surfer, die sich 20 Meter hohen Wänden stellen. Der Klippenweg funktioniert an der Leine; das Innere des Forts und sein Surfmuseum akzeptieren keine Hunde.`,
      "Praia do Norte": `Hinter der Klippe von Sítio empfängt dieser wilde, von den Dünen des Pinhal de Leiria gesäumte Strand die größten je gesurften Wellen. Außerhalb der Badesaison und abseits bewachter Zonen ist er ein riesiges, windgepeitschtes und spektakuläres Spazierrevier an der Leine; hier nicht baden, die Strömungen sind gefährlich.`,
      "Praia da Nazaré": `Der große Strand des Dorfes, gesäumt von Promenade und Reihen von Sonnenschirmen, hält die Tradition der Fischtrockengestelle und bemalten Boote lebendig. In der Badesaison sind Hunde verboten, wie an allen bewachten portugiesischen Stränden; die Strandpromenade bleibt das ganze Jahr über an der Leine geöffnet.`,
      "Miradouro da Pederneira": `Auf Nazarés drittem Hügel bietet die mittelalterliche Altstadt Pederneira einen ruhigen Blick über die gesamte Bucht, den Hafen und das Sítio. Fernab der Menschenmassen ist er der ideale abendliche Spaziergang an der Leine, zwischen einer manuelinischen Kirche, ruhigen Gassen und goldenem Licht über dem Ozean.`,
    },
  },
  'new-york': {
    history: `New York, 1624 als niederländischer Handelsposten New Amsterdam gegründet und 1664 von den Engländern umbenannt, ist in vier Jahrhunderten zur einflussreichsten Finanz-, Kultur- und Migrationsmetropole der Welt geworden. Ihre 8,3 Millionen Einwohner teilen sich 783 km² auf fünf Stadtbezirke (Manhattan, Brooklyn, Queens, Bronx, Staten Island) auf, eine Dichte, die die Stadt paradoxerweise zu einer der haustierbewusstesten Städte der USA macht. Für Hundebesitzer bietet New York eine einzigartige Mischung: über 70 vom Parks Department unterhaltene Dog Runs, die großzügigsten städtischen Freilaufzeiten Amerikas (Central und Prospect Park, 5-9 Uhr und 21-1 Uhr), ein dichtes 24-Stunden-Tierarzt-Notfallnetz und eine Luxushotelkultur, die Haustiere aktiv willkommen heißt. Die Einschränkungen: die MTA-Transportbox-Pflicht in der U-Bahn, sommerlicher Asphalt, der nachmittags 50 °C erreicht, und ein Gesundheitskodex, der Hunde aus Restaurantinnenräumen ausschließt (auf Terrassen jedoch seit 2015 erlaubt).`,
    petTips: [`Die MTA-U-Bahn akzeptiert Hunde nur in einer Transportbox (MTA Code §1050.9). Große Hunde sind offiziell verboten; in der Praxis werden viele in übergroßen, umgebauten IKEA-artigen Taschen befördert.`, `Offizielle Freilaufzeiten im Central Park und Prospect Park: 5-9 Uhr und 21-1 Uhr (im Prospect Park nur 5-9 Uhr). Außerhalb dieser Zeiten ist die Leine Pflicht, Bußgelder bis zu 100 Dollar werden verhängt.`, `Sommerlicher Asphalt: 50-60 °C an Nachmittagen im Juli und August. Gehen Sie vor 9 Uhr oder nach 20 Uhr spazieren, oder bleiben Sie auf dem Kopfsteinpflaster von SoHo und Greenwich Village.`, `Drei rund um die Uhr geöffnete Notfalltierärzte nehmen ohne Termin an: Animal Medical Center (510 E 62nd St), BluePearl Midtown West (410 W 55th St), VEG West Village (270 W 4th St).`, `Uber Pet ist stadtweit verfügbar (3-5 Dollar Aufpreis) für größere Hunde; die NYC Ferry nimmt angeleinte Hunde auf allen Linien (East River, Astoria, South Brooklyn) kostenlos mit.`],
    practicalInfo: [`Einreise in die USA aus der EU: gültige Tollwutimpfung, Mikrochip und online vor der Reise ausgefülltes CDC Dog Import Form. Die Regeln wurden im August 2024 verschärft, die Ankunft muss an einem zugelassenen Flughafen erfolgen (JFK qualifiziert sich).`, `Leinenpflicht (NYC Admin Code §161.05) auf allen öffentlichen Straßen und in Parks außerhalb der offiziellen Freilaufzeiten, maximal 1,80 Meter.`, `Aufsammeln von Hundekot ist Pflicht (Health Code §161.03), 250 Dollar Bußgeld, die Sanitation Police kontrolliert häufig.`, `Kein stadtweites Rasseverbot, aber viele Hotels lehnen Pitbulls, Rottweiler, Dobermänner und Deutsche Schäferhunde ab, bestätigen Sie dies vor der Buchung.`, `Haustierfreundliche Hotels: Die Marke Kimpton, Loews und die meisten Boutique-Hotels akzeptieren Haustiere ohne Gebühr; Hotels der mittleren Preisklasse verlangen üblicherweise 50-150 Dollar pro Aufenthalt.`],
    sights: {
      "Central Park": `Manhattans ikonischer, 341 Hektar großer Park. Offizielle Freilaufzeiten 5-9 Uhr und 21-1 Uhr, ganzjährig in den meisten Teilen des Parks.`,
      "Prospect Park": `Von Olmsted und Vaux gestalteter Park in Brooklyn, 213 Hektar. Freilauf 5-9 Uhr, und der einzige städtische Hundestrand in New York, an dem Hunde von April bis November schwimmen können.`,
      "Brooklyn Bridge": `Ikonische Hängebrücke von 1883, 1,8 km lang. Das obere Fußgängerdeck steht angeleinten Hunden rund um die Uhr offen, seit 2021 vom Radweg getrennt.`,
      "The High Line": `Ein 2,3 km langer, erhöhter linearer Park auf einem ehemaligen Güterbahnviadukt, eröffnet 2009. Angeleinte Hunde sind auf der gesamten Länge willkommen, Wassernäpfe an den Zugängen der 16th und 23rd Street.`,
      "Staten Island Ferry": `Kostenlose 25-minütige Fähre zwischen Whitehall (Manhattan) und St. George (Staten Island). Angeleinte Hunde fahren kostenlos mit, vorbei an der Freiheitsstatue.`,
      "Hell's Kitchen and the West Village": `Zwei der hundefreundlichsten Viertel Manhattans. Hunderte Terrassen, der Hudson River Park nur einen Block entfernt und eine rund um die Uhr geöffnete Veterinary Emergency Group in der West 4th Street.`,
    },
  },
  neringa: {
    history: `Neringa ist eine zum UNESCO-Weltkulturerbe gehörende Kurgemeinde entlang der litauischen Hälfte der Kurischen Nehrung, einem 52 km langen Streifen aus Kiefernwald und wandernden Sanddünen, der das Kurische Haff von der Ostsee trennt und nur per Fähre von Klaipeda aus erreichbar ist. Die vier kleinen Ortschaften (Nida, Juodkrantė, Preila, Pervalka) teilen sich eine ständige Bevölkerung von rund 2.500 Einwohnern, die im Juli und August auf mehrere Zehntausend anschwillt. Nida, der südlichste und größte Ort, ist berühmt für seine 52 Meter hohe Sonnenuhrdüne Parnidis, die bunten Wetterfahnen-Fischerhäuser und das 1930 erbaute Sommerhaus des Nobelpreisträgers Thomas Mann. Fast die gesamte Nehrung ist Nationalpark, sodass angeleinte Hunde auf Kiefernpfaden, Haff-Promenaden und außersaisonalen Stränden umherstreifen können, während empfindliche Dünenrenaturierungszonen streng eingezäunt bleiben.`,
    petTips: [`Die gesamte Kurische Nehrung ist ein UNESCO-Biosphären-Nationalpark: Angeleinte Hunde sind auf markierten Pfaden, Bohlenwegen und Haff-Promenaden willkommen, aber niemals in den eingezäunten Dünenrenaturierungszonen, wo Bußgelder drohen.`, `Auf der Nehrung gibt es keinerlei eingezäunte Freilaufflächen; die nächsten befinden sich am Trinyčiai-Teich und im Draugystes-Park in Klaipeda, auf der anderen Seite des Haffs.`, `Halten Sie an Café- und Ladentüren nach dem grünen Aufkleber „Draugiški Gyvūnams" mit Hundepfote Ausschau, dem 2017 landesweit eingeführten litauischen Zeichen für Haustierfreundlichkeit, um Lokale zu finden, die Hunde auch drinnen zulassen.`, `Auf der Nehrung gibt es keinen Tierarzt. Speichern Sie die Nummer des rund um die Uhr geöffneten Überweisungs-Tierkrankenhauses in Klaipeda, bevor Sie übersetzen, und berücksichtigen Sie die Wartezeit der Fähre (5 Minuten auf der Alte-Burg-Linie, 15-30 Minuten bei der Neuen Fähre) bei der Einschätzung der Notfallreaktionszeit.`, `Durch Zecken übertragene Krankheiten kommen in den Kiefernwäldern vor und erreichen von Mai bis Juli ihren Höhepunkt; fragen Sie Ihren Tierarzt nach einem Zeckenschutz, bevor Sie die Pfade der Nehrung begehen.`],
    practicalInfo: [`Neringa ist nur per Fähre von Klaipeda aus erreichbar: Fußgänger und Radfahrer nutzen die kostenlose Alte-Burg-Fähre, während Autos (und die mit ihnen reisenden Hunde) die weiter südlich gelegene Neue Fähre nutzen, deren Preis sich nach der Fahrzeuglänge richtet.`, `Nächster Flughafen: Palanga (PLQ), etwa 60 km nördlich von Nida über Klaipeda und die Neue Fähre. Kaunas (KUN), 245 km östlich, verfügt über ein breiteres europäisches Streckennetz.`, `Litauisch ist die Amtssprache; Englisch wird in den Tourismusbetrieben von Nida und Juodkrantė weitgehend gesprochen, jüngeres Personal ist meist fließend darin.`, `Litauen trat 2015 der Eurozone bei; alle Preise sind in EUR. Die Badesaison ist kurz (Mitte Juni bis Ende August), sodass die gesamte Küste außerhalb dieser Zeit praktisch an der Leine hundefreundlich ist.`, `EU-Heimtierausweis, ISO-11784/11785-Mikrochip und gültige Tollwutimpfung sind für die Einreise erforderlich; bei Anreise aus einem anderen EU-Staat ist keine Bandwurmbehandlung nötig.`],
    sights: {
      "Parnidis Dune & Sundial": `Ein hölzerner Bohlenweg und ein Schotterpfad führen auf die 52 Meter hohe Parnidis-Düne am Südrand von Nida hinauf, gekrönt von einer Granit-Sonnenuhr mit 360-Grad-Panorama über die Ostsee, das Haff und das russische Kaliningrad. Rund 1,5 km Hin- und Rückweg mit leichter Steigung; angeleinte Hunde sind auf dem Bohlenweg und dem markierten Sandpfad willkommen, jedoch niemals in den beidseitig eingezäunten Dünenrenaturierungszonen.`,
      "Hill of Witches (Raganu kalnas)": `Ein Freiluft-Skulpturenpfad durch den Kiefernwald oberhalb von Juodkrantė mit über 80 hölzernen Schnitzereien von Hexen, Teufeln und Figuren aus der litauischen Folklore, erstmals 1979 zusammengestellt. Eine sanfte 1,5 km lange Waldschleife, kostenlos und rund um die Uhr zugänglich; angeleinte Hunde sind überall willkommen, der Weg hat einige Wurzelstufen, eignet sich aber für die meisten Hunde.`,
      "Nida Lagoon Promenade": `Eine gepflasterte Uferpromenade, die mehrere Kilometer nördlich der Marina von Nida am Kurischen Haff entlangführt, vorbei an restaurierten Fischerhäusern, Kiefernschatten und zahlreichen Bänken mit weiten Blicken auf die Dünen. Dies ist der tägliche Standard-Hundespaziergang in Nida: flach, malerisch und komplett an der Leine, mit Abfalleimern entlang der Strecke und Caféterrassen am Ende bei der Marina.`,
      "Thomas Mann House garden": `Das 1930 erbaute Sommerhaus des deutschen Nobelpreisträgers Thomas Mann am Haffhang, das er als „ein italienisches Erlebnis inmitten litauischer Kiefern" bezeichnete. Das Museumsinnere ist für Hunde tabu, aber Garten, Terrasse und der umliegende Kiefernwald sind an der Leine zugänglich und bieten denselben legendären Blick über das Haff, sodass ein Partner drinnen die Besichtigung machen kann, während der andere auf der Bank wartet.`,
      "Nida Central Beach": `Ein breiter, weißer Sandstrand mit Blauer Flagge auf der Ostseeseite der Nehrung, erreichbar über einen 1 km langen Bohlenweg durch den Kiefernwald und über die Dünen vom Dorf Nida aus. Der zentrale, bewachte Abschnitt verbietet Hunde von Mitte Juni bis August, doch fünf Minuten nördlich oder südlich davon erreichen Sie ruhigen Sand, auf dem angeleinte Hunde willkommen sind; außerhalb der Saison ist praktisch der gesamte Strand hundefreundlich.`,
      "Smiltyne Ferry & Curonian Spit forest": `Die kostenlose, fünfminütige Fußgängerfähre vom Terminal Alte Burg in Klaipeda über das Haff nach Smiltynė, an der Nordspitze der Nehrung, mit angeleinten Hunden kostenlos an Bord. Auf der anderen Seite führen weiche Sandpfade durch Kiefern- und Laubwald zu den Dünen und dem Ostseestrand, das Tor, durch das jeder Neringa-Besucher auf der Anreise fährt.`,
    },
  },
  nerja: {
    history: `Nerja, eine weiß getünchte Stadt mit rund 22.000 Einwohnern an der östlichen Costa del Sol in der Provinz Málaga, entwickelte sich von einem maurischen Bauerndorf zu einem der beliebtesten Badeorte Andalusiens, berühmt geworden durch die spanische Fernsehserie „Verano Azul" aus den 1980er-Jahren, die an ihren Stränden gedreht wurde. Herzstück ist der Balcón de Europa, ein von Palmen gesäumtes Vorgebirge, das auf den Ruinen einer Klippenfestung errichtet wurde und von dem aus sich die Altstadt in einem Gewirr enger, weiß getünchter Gassen zum Mittelmeer hin ausbreitet. Für Hundebesitzer ist Nerja entspannt und gut zu Fuß zu erkunden: Angeleinte Hunde sind auf Terrassen, der Promenade und den Straßen der Altstadt willkommen, und die Stadt eröffnete Ende 2024 zwei eingezäunte städtische Hundeparks. Zwei Dinge sollte man einplanen: die sommerliche Hitze der Costa del Sol und das saisonale Strandverbot (1. Juni bis 30. September), das Hundebesitzer zum ganzjährig geöffneten Hundestrand im nahen Torrox schickt.`,
    petTips: [`Nerjas eigene Strände, einschließlich der Playa de Burriana, verbieten Hunde während der andalusischen Badesaison vom 1. Juni bis 30. September; nutzen Sie den offiziellen Hundestrand in Torrox (8 km westlich), der ganzjährig geöffnet ist.`, `Hitze an der Costa del Sol: Gehen Sie im Sommer früh morgens oder nach Sonnenuntergang spazieren, und testen Sie den Belag mit der Hand, ist er für Ihre Handfläche zu heiß, ist er es auch für Pfoten.`, `Ende 2024 eröffneten zwei eingezäunte städtische Hundeparks, der Parque Canino Verano Azul im Zentrum und der Park bei der Ciudad Deportiva, beide mit Freilauffläche.`, `Der Spaziergang am Río Chíllar ist die beste sommerliche Abkühlung, seine schattige Schlucht und das flache Wasser halten Hunde angenehm kühl, wenn es an der Küste zu heiß ist; halten Sie sie angeleint.`, `Leishmaniose-Prophylaxe: Die Sandmücke, die sie überträgt, ist an der Costa del Sol endemisch, fragen Sie einen örtlichen Tierarzt von Frühjahr bis Herbst nach einem Repellent-Halsband oder Spot-on-Präparat.`],
    practicalInfo: [`EU-Heimtierausweis und gültige Tollwutimpfung sind beim Check-in in jedem haustierfreundlichen Hotel erforderlich.`, `Leinenpflicht im öffentlichen Raum gemäß andalusischer und städtischer Vorschriften; potenziell gefährliche Rassen (PPP) benötigen Maulkorb und eine Lizenz.`, `Das Aufsammeln von Hundekot ist Pflicht und wird mit Bußgeld belegt, die Stadt kontrolliert den Balcón de Europa und die Promenade.`, `Kein Bahnhof: Die meisten Besitzer reisen über den Flughafen Málaga (60 km) an und nehmen dann ein Auto oder einen ALSA-Fernbus (nur kleine Haustiere, feste Transportbox im Gepäckraum); die Málaga-Cercanías-Nahverkehrszüge sind flexibler bei Haustieren.`, `Geprüfte Tierärzte: Clínica Veterinaria Nerja (C. El Chaparil 3, +34 952 521 401), 24-Stunden-Notdienst 609 982 941; Clínica Veterinaria Laguna in Torrox-Costa.`],
    sights: {
      "Balcón de Europa": `Nerjas ikonisches Vorgebirge auf der Klippe mit palmengesäumter Promenade, errichtet auf den Ruinen einer alten Festung dort, wo die Altstadt auf das Meer trifft. Angeleinte Hunde sind auf der offenen gepflasterten Esplanade und ihren weiten Blicken über das Mittelmeer willkommen.`,
      "Río Chíllar": `Nerjas typische Sommerwanderung folgt dem Bett des Río Chíllar durch eine kühle, schattige Schlucht mit knöchel- bis kniehohem Wasser, ein natürlicher Zufluchtsort für Hunde vor der Sommerhitze. Halten Sie Hunde angeleint und bringen Sie Wasser für die trockenen Abschnitte mit.`,
      "Parque Canino Verano Azul": `Ein vollständig eingezäunter städtischer Hundepark neben dem Parque Verano Azul im Herzen der Stadt, im Dezember 2024 vom Rathaus Nerja eröffnet, damit Hunde ohne Leine laufen können. Ein zweiter eingezäunter Hundepark befindet sich neben dem Sportkomplex Ciudad Deportiva.`,
      "Playa Canina de Torrox": `Der nächstgelegene offizielle Hundestrand zu Nerja, eine kleine Bucht an der Mündung des Torrox-Flusses zwischen dem Leuchtturm und der Playa El Peñoncillo, etwa 8 km westlich. Er ist die verlässliche ganzjährige Schwimmoption, da Nerjas eigene Strände im Sommer Hunde verbieten.`,
      "Iglesia de El Salvador": `Die weiß getünchte Kirche aus dem 17. Jahrhundert, die den Kern von Nerjas Altstadt bildet, die sich vom Balcón de Europa aus in einem Gewirr enger Gassen, Plätze und Tapas-Terrassen ausbreitet. Angeleinte Hunde sind willkommen, die Fußgängerstraßen und die meisten Caféterrassen zu erkunden.`,
      "Cuevas de Nerja": `Ein riesiges prähistorisches Höhlensystem 4 km östlich der Stadt und eine der meistbesuchten Sehenswürdigkeiten Andalusiens, mit einer berühmten zentralen Kammer und uralten Felsmalereien. Hunde dürfen nicht hinein, besuchen Sie die Höhlen daher zu zweit, damit jemand draußen bei Ihrem Haustier warten kann.`,
    },
  },
  newquay: {
    history: `Newquay, das wichtigste Seebad an der Nordküste Cornwalls, war ein kleiner Fischerhafen für Pilchards, bevor 1876 die Eisenbahn ankam und aus dem Ort einen Urlaubsort machte. Heute ist es Großbritanniens Surfhauptstadt, berühmt für den Fistral Beach und das gute Dutzend Sandstrände drum herum. Für einen Hund ist es eines der einfachsten Reiseziele Cornwalls: Die meisten Strände, darunter Fistral, Crantock und Watergate Bay, erlauben Hunde ganzjährig, der South West Coast Path ist immer geöffnet, die Pubs am Hafen heißen Hunde willkommen, und die Stadt hat sogar einen eigenen Notdienst-Tierarzt außerhalb der Öffnungszeiten. Zu beachten sind lediglich einige saisonale Strandregeln (Porth im Hochsommer gesperrt, Tolcarne an der Leine), die vom Cornwall Council festgelegt werden, sowie für EU-Besucher das seit dem Brexit erforderliche britische Tiergesundheitszeugnis (GB Animal Health Certificate) anstelle des EU-Heimtierausweises.`,
    petTips: [`Die meisten Strände erlauben Hunde ganzjährig: Fistral, Towan, Great Western, Crantock, Watergate Bay, Lusty Glaze und Whipsiderry. Newquay ist eines der einfachsten britischen Seebäder für den Zugang zu Hundestränden.`, `Die wichtigste Sommereinschränkung betrifft den Porth Beach, dort sind Hunde vom 1. Juli bis 31. August von 10 bis 18 Uhr verboten (Cornwall Council PSPO); am Tolcarne Leinenpflicht von Mai bis September. Bußgelder bis zu 100 Pfund.`, `Hunde reisen kostenlos mit der Atlantic Coast Line von Par (bis zu zwei pro Fahrgast, an der Leine); First-Kernow-Busse akzeptieren sie nach Ermessen des Fahrers.`, `Halten Sie Ihren Hund auf dem South West Coast Path in der Nähe der ungesicherten Klippenkanten und des Weideviehs an der Leine; achten Sie auf die schnelle Flut im Gannel-Ästuar.`, `Ungewöhnlich für Cornwall gibt es in der Stadt einen Notfalltierarzt bei MiNightVet, Henver Road (+44 1637 851122). Allgemeiner Notruf 999 oder 112.`],
    practicalInfo: [`Einreise nach Großbritannien nach dem Brexit: Großbritannien akzeptiert den EU-Heimtierausweis nicht; Hunde benötigen ein britisches Tiergesundheitszeugnis (innerhalb von 10 Tagen ausgestellt), einen Mikrochip, eine Tollwutimpfung und eine Bandwurmbehandlung 24 bis 120 Stunden vor der Ankunft.`, `Anreise: Atlantic Coast Line-Zug ab Par (Hunde kostenlos); der Flughafen Newquay (NQY) direkt außerhalb der Stadt ist der bequemste Flughafen in Cornwall.`, `Fortbewegung: Die Stadt ist kompakt, liegt aber auf Klippen, rechnen Sie also mit Steigungen; Parkplätze sind im Sommer sehr begrenzt, bevorzugen Sie daher Zug und Fußwege.`, `Wetter: mildes ozeanisches Klima, milde Winter (9-10 °C) mit seltenem Frost, warme, aber nicht heiße Sommer (18 °C), oft windige Küste. Frühling und Herbst sind ideal.`, `Nützliche Nummern: allgemeiner Notruf 999 oder 112; Notdienst-Tierarzt in der Stadt MiNightVet +44 1637 851122; Tagestierarzt Penmellyn +44 1637 871695.`],
    sights: {
      "Fistral Beach": `Großbritanniens berühmtester Surfstrand, ein weiter Bogen aus goldenem Atlantiksand auf der Pentire-Seite. Hunde ganzjährig erlaubt; Vorsicht vor starker Brandung und Strömungen.`,
      "Crantock Beach": `Ein herrlicher National-Trust-Strand mit hellem Sand, Dünen und dem türkisfarbenen Gannel-Ästuar gleich westlich der Stadt. Ganzjährig hundefreundlich; Vorsicht vor der schnellen Gannel-Flut.`,
      "Watergate Bay": `Drei Kilometer offener Atlantiksand nordöstlich der Stadt, ganzjährig vollständig hundefreundlich. Die riesige Fläche bei Ebbe gibt Hunden kilometerweit Auslauf.`,
      "Newquay Harbour": `Der historische Arbeitshafen unterhalb der Stadt, umgeben von hundefreundlichen Pubs. Sein kleiner Strand ist ganzjährig hundefreundlich und Ausgangspunkt für die Bootsausflüge.`,
      "South West Coast Path": `Dramatische Klippenwanderung um Towan und Pentire Head mit weiten Atlantikblicken. Ganzjährig für Hunde geöffnet; an der Leine in der Nähe von Klippenkanten und Weidevieh.`,
      "The Gannel Estuary": `Ein wunderschönes Gezeiten-Ästuar, das Newquay von Crantock trennt, mit Sandufern und Fußwegen. Ganzjährig für Hunde geöffnet; Vorsicht vor der schnell einsetzenden Flut.`,
    },
  },
  nice: {
    history: `Nizza, die Hauptstadt der Côte d'Azur und Frankreichs fünftgrößte Stadt, ist seit dem 19. Jahrhundert ein Zufluchtsort für wohlhabende Reisende und ihre Haustiere, seit englische Aristokraten, die den Winter an der Côte d'Azur verbrachten, die Promenade des Anglais zu ihrem täglichen Spaziergang machten. Heute teilen sich die 342.000 Einwohner der Stadt diese mit einer beträchtlichen Hundepopulation, angezogen vom Mittelmeerklima, dem langen Kieselstrand und dem leichten Zugang zu den Hügeln der Alpes-Maritimes. Hunde sind auf den zahlreichen Caféterrassen und in den Restaurants der Stadt willkommen; die Altstadt (Vieux-Nice) ist lebendig und mit einem gut sozialisierten Hund das ganze Jahr über gut zu erkunden.`,
    petTips: [`Die Strände von Nizza bestehen meist aus Kies und sind im Sommer privat konzessioniert. Von Juni bis September sind Hunde an den meisten Hauptstränden verboten. Am Coco Beach (östlich des Hafens) gibt es saisonal einen kleinen Hundebereich.`, `Die Straßenbahn der Stadt (Linie 1 und 2) lässt keine Hunde zu, nutzen Sie sie allein für Museumsbesuche. Taxis und Fahrdienst-Apps erlauben Hunde nach Ermessen des Fahrers.`, `Ausflug ins Hinterland: Die Dörfer im Hinterland (Èze, La Turbie, Peille) sind hervorragende Halbtagesausflüge mit Hund, kühle Luft, ruhige Wege und durchweg hundefreundliche Terrassen.`, `Die Sommerhitze auf der Promenade kann 38 °C erreichen. Gehweg und Kiesel heizen sich schnell auf. Gehen Sie vor 9 Uhr spazieren; führen Sie stets Wasser und einen tragbaren Napf mit.`, `Tagesausflug nach Monaco (20 Minuten mit dem Zug): Angeleinte Hunde sind in den Jardins Exotiques und auf dem Rocher erlaubt. Kasino und Palastgärten sind strikt hundefrei.`],
    practicalInfo: [`Notfalltierarzt: Centre Hospitalier Vétérinaire Saint-Martin, Nizza (+33 4 93 53 04 04), 24-Stunden-Einrichtung am östlichen Stadtrand.`, `Anreise: Der Flughafen Nice Côte d'Azur liegt 7 km vom Zentrum entfernt. Die Straßenbahnlinie 2 verbindet in 25 Minuten. Hunde in Transportboxen sind in der Straßenbahn erlaubt.`, `Bahnverbindungen: Der Bahnhof Nice-Ville verbindet mit Paris (5,5 Std. TGV), Marseille (2,5 Std.) und der malerischen Küstenlinie der Côte d'Azur (Menton, Monaco, Cannes, Antibes, alle mit Hund erreichbar).`, `Beste Reisezeit: Mai-Juni und September-Oktober. Die Promenade ist zu jeder Jahreszeit spektakulär, aber der Sommerandrang und die Strandbeschränkungen machen den Herbst zum idealen Zeitpunkt für Hundebesitzer.`],
    sights: {
      "Promenade des Anglais": `Die ikonische, 7 km lange Strandpromenade ist einer der großartigsten Hundespaziergänge Europas. Breit, flach, mit Meeresbrise und zu jeder Tageszeit belebt von Einheimischen. Hunde an der Leine; der Kieselstrand ist zugänglich, im Sommer jedoch meist ohne eigene Hundebereiche.`,
      "Colline du Château": `Der Hügelpark mit Blick über die Altstadt und das Meer ist bei Hundebesitzern in Nizza sehr beliebt. Schattige Wege, ein Wasserfall, offene Terrassen und weite Ausblicke, fast immer eine Brise, selbst im Juli. Zu Fuß vom alten Hafen aus oder mit dem kostenlosen Aufzug erreichbar.`,
      "Vieux-Nice (Altstadt)": `Die barocke Altstadt mit ihren orange- und ockergelben Fassaden, dem Blumenmarkt und den Socca-Ständen lässt sich mit einem ruhigen Hund gut erkunden. Die meisten Caféterrassen heißen Hunde willkommen, und die Gassen sind eng, aber außerhalb des August nicht überwältigend.`,
      "Parc du Mont-Boron": `Der 340 Hektar große Waldpark östlich der Stadt ist Nizzas beste Flucht vor der Hitze. Kiefernwaldwege, Meerblick und ein Fort auf dem Gipfel. Hunde meist ohne Leine, an Wochenenden sehr beliebt bei lokalen Läufern und ihren Hunden.`,
      "Musée Matisse & Musée d'Art Moderne": `Die Museen von Nizza sind für Hunde nicht zugänglich. Die Gärten des Matisse-Museums (im Freien) sind hundefreundlich und bieten einen angenehmen Spaziergang im Viertel Cimiez.`,
    },
  },
  nimes: {
    history: `Nîmes, wegen seines antiken Erbes das französische Rom genannt, war eine um 28 v. Chr. unter Augustus gegründete römische Kolonie, der die Münze COL NEM prägen ließ, auf der ein an eine Palme gekettetes Krokodil zu sehen ist, bis heute das ewige Wahrzeichen der Stadt. Sie besitzt das am besten erhaltene römische Amphitheater der Welt (die Arènes, um 70 n. Chr.), den vollständigsten römischen Tempel überhaupt (die Maison Carrée, 2023 UNESCO-gelistet), den Tour Magne auf dem Gipfel des Mont Cavalier und den Pont du Gard 25 km nördlich. Im 18. Jahrhundert erfand Nîmes den Serge de Nîmes, den Denim-Stoff, der 1853 zu den kalifornischen Minenarbeitern auszog. Für reisende Haustiere schreibt Frankreich den EU-Heimtierausweis, einen ISO-Mikrochip und eine gültige Tollwutimpfung vor. Die Arènes tragen das Qualidog-Siegel und lassen ausdrücklich angeleinte Hunde jeder Größe kostenlos zu, eine französische Seltenheit; die 15 Hektar großen Jardins de la Fontaine sind für angeleinte Hunde geöffnet; und der Pont du Gard akzeptiert angeleinte Hunde auf der Brücke, an den Ufern und im Fluss (außerhalb einer 30-Meter-Sperrzone um die Brücke).`,
    petTips: [`Die Arènes de Nîmes tragen das Qualidog-Siegel: Angeleinte Hunde jeder Größe sind im Inneren des Monuments kostenlos zugelassen, eine in Frankreich seltene Ausnahme, die man nutzen sollte.`, `Der Pont du Gard erlaubt angeleinte Hunde auf der Brücke, an den Ufern und beim freien Schwimmen im Gardon (außer innerhalb der 30-m-Sperrzone um die Brücke). Das Museumsinnere, das Ciné, das Ludo und das Innere des römischen Kanals sind jedoch für Hunde gesperrt.`, `Die Tango-Stadtbusse akzeptieren nur kleine Haustiere in einer geschlossenen Box sowie Blindenhunde; mit einem mittelgroßen oder großen Hund planen Sie am besten, im Zentrum (1 km Durchmesser) zu Fuß zu gehen oder ein Taxi zu nehmen.`, `Meiden Sie das Zentrum während der Féria de Pentecôte (Anfang Juni) und der Féria des Vendanges (Mitte September): über 500.000 Besucher in 6 Tagen, Blaskapellen, Feuerwerk und Menschenmassen bis in die Morgenstunden, ungeeignet für Hunde.`, `Rund-um-die-Uhr-Bereitschaftstierarzt: 04 27 04 02 72 (Vétérinaires 2 Toute Urgence, route de Montpellier) deckt Nîmes, Arles und die Camargue ab.`],
    practicalInfo: [`Anreise: Der Bahnhof Nîmes SNCF liegt 8 Gehminuten vom Zentrum entfernt, TGV nach Paris in 2 Std. 50, TER alle 30 Minuten nach Avignon, Arles, Montpellier und Marseille. Der Flughafen Nîmes Garons (FNI) liegt 15 Minuten südlich (saisonal) oder Marseille Provence (MRS, 1 Std. 15) / Montpellier (MPL, 50 Min.).`, `Strände/Baden: kein Stadtstrand; der Gardon-Fluss beim Pont du Gard (25 km nördlich) erlaubt angeleinte Hunde und freies Schwimmen (außerhalb der 30-m-Sperrzone um die Brücke). Die Plage de l'Espiguette (Grau-du-Roi, 50 Min. südlich) und Piémanson (Camargue, 1 Std. südlich) für das Meer.`, `Parks: Jardins de la Fontaine (15 ha, kostenlos, an der Leine), Parc du Mont Duplan, Bois des Espeisses (165 ha, an Tagen mit roter Waldbrandwarnung geschlossen); kein Hundeauslaufplatz innerhalb der Stadtmauern.`, `Tierärzte: Vétérinaires 2 Toute Urgence (04 27 04 02 72, route de Montpellier, 24/7-Notdienst nachts + am Wochenende), Clinique RAJAUT-CAMALLONGA (Zentrum, 04 66 67 71 70), Clinique Nemovet (Mitra, 04 66 67 17 17); kostenlose landesweite Hotline 3115.`, `Dokumente: EU-Heimtierausweis, ISO-Mikrochip und gültige Tollwutimpfung erforderlich. Reisende von außerhalb der EU (UK, USA) benötigen ein Tiergesundheitszeugnis oder eine USDA-APHIS-Bestätigung.`],
    sights: {
      "Arènes de Nîmes (Qualidog)": `Das am besten erhaltene römische Amphitheater der Welt, um 70 n. Chr. erbaut und noch heute Schauplatz von Stierkämpfen, Opern und Konzerten. Die Stätte trägt das Qualidog-Siegel und lässt während der normalen Öffnungszeiten ausdrücklich angeleinte Hunde jeder Größe zu, einschließlich Listenhunden, kostenlos. Das Amphitheater ist während Ferias und Konzerten für Besucher gesperrt.`,
      "Maison Carrée (Außenbereich)": `Der um 4-7 n. Chr. erbaute römische Tempel, den Augustus seinen Enkeln widmete, der vollständigste römische Tempel überhaupt, 2023 UNESCO-gelistet. Hunde sind vom 3D-Kino und der Ausstellung im Inneren ausgeschlossen (nur Assistenzhunde). Der Fußgängerplatz drum herum und die Tempeltreppen sind angeleinten Hunden jederzeit frei zugänglich.`,
      "Jardins de la Fontaine & Tour Magne": `Frankreichs erster öffentlicher Garten, 1750 rund um die römische Heiligtumsquelle auf dem Mont Cavalier angelegt, 15 Hektar mit terrassierten Beeten und einem bewaldeten Aufstieg zum römischen Tour Magne an der Spitze. Freier Eintritt. Das Tourismusbüro bestätigt, dass angeleinte Hunde überall willkommen sind; das Innere des römischen Tour Magne ist jedoch außer für Blinden- und Assistenzhunde gesperrt.`,
      "Pont du Gard": `Das dreistöckige römische Aquädukt aus dem 1. Jahrhundert, UNESCO-gelistet und das meistbesuchte Monument des Gard. Die offizielle Ordnung der Anlage erlaubt angeleinte Hunde auf der Brücke, an den Ufern, auf den Außenwegen und beim freien Schwimmen im Gardon außerhalb einer 30-Meter-Sperrzone ober- und unterhalb der Pfeiler. Das Museumsinnere, das Ciné, das Ludo und der römische Kanal sind für Hunde gesperrt.`,
      "Bois des Espeisses": `Ein 165 Hektar großer städtischer Wald am Nordwestrand von Nîmes, die größte Grünfläche der Stadt, mit markierten Wegen, Garrigue und Steinkiefern. Hunde an der Leine auf allen Wegen; Listenhunde (Kategorien 1 und 2 nach französischem Recht) mit Maulkorb. Bei roter Waldbrandwarnung der Präfektur Gard für Wanderer gesperrt.`,
      "Place du Forum & Esplanade Charles-de-Gaulle": `Das gesellschaftliche Herz von Nîmes, mit Place du Marché und der Esplanade Charles-de-Gaulle, die die Terrassen vor den Arènes verlängert. Breite Terrassen, Brunnen, ein von Platanen gesäumter Mittelstreifen. Angeleinte Hunde fühlen sich hier ganz zu Hause, und Kellner bringen im Sommer oft von selbst einen Wassernapf.`,
    },
  },
  nuremberg: {
    history: `Nürnberg, die inoffizielle Hauptstadt Frankens, war vom 13. bis zum 18. Jahrhundert eine der großen Freien Reichsstädte des Heiligen Römischen Reiches, häufiger Ort von Reichstagen und beliebter Aufenthaltsort mehrerer Kaiser. Die auf ihrem Sandsteinfelsen thronende Kaiserburg und die Fachwerk-Altstadt (als bayerisches Denkmalensemble gelistet) zeugen von diesem goldenen Zeitalter. Geburtsort von Albrecht Dürer und des Lebkuchens, veranstaltet Nürnberg seit 1628 Deutschlands berühmtesten Weihnachtsmarkt, den Christkindlesmarkt, der heute jährlich 2 Millionen Besucher anzieht. Die Stadt wurde 1945 fast vollständig zerstört und originalgetreu wiederaufgebaut. Heute, als Bayerns zweitgrößte Stadt mit 520.000 Einwohnern, verbindet Nürnberg mittelalterliches Erbe, eine Wirtshauskultur, die Hunde im Inneren willkommen heißt, und direkten Zugang zu 25.000 Hektar Reichswald. Nur 1 Std. 05 von München und 4 Stunden von Berlin mit dem ICE entfernt, ist es eine der einfachsten deutschen Städte für Reisen mit Hund.`,
    petTips: [`Deutsche Wirtshäuser heißen angeleinte Hunde im Inneren in großem Umfang willkommen, weit mehr als in Südeuropa.`, `Das VGN-Netz (U-Bahn, Straßenbahn, Bus) nimmt kleine Hunde kostenlos in der Transportbox mit; größere Hunde benötigen ein Kinderticket und eine Leine.`, `Der Reichswald am Stadtrand bietet 25.000 Hektar Wald mit Freilaufwegen, erreichbar mit der Straßenbahnlinie 4 bis zur Endhaltestelle.`, `Das bayerische Listenhundegesetz beschränkt Pitbull, Bullterrier und Staffordshire-Varianten, führen Sie bei einem solchen Hund die Papiere mit.`, `Streusalz auf dem Kopfsteinpflaster der Altstadt im Dezember kann Pfotenballen verletzen, Schutzschuhe oder Vaseline vor dem Ausgehen verwenden.`],
    practicalInfo: [`24/7-Notfalltierärzte: Tierklinik Nürnberg-Hafen, Hafenstraße 5, +49 911 64 87 60; Anicura Tierklinik, Stresemannplatz 5, +49 911 58 78 50`, `Zentrale Tagesklinik: Tierarztpraxis Altstadt, Ludwigsplatz 8, +49 911 22 47 73`, `ICE ab München: 1 Std. 05; ab Frankfurt: 2 Std. 15; ab Berlin: 4 Std. Kleine Hunde in der Transportbox kostenlos; größere Hunde benötigen ein Kinderticket (50 %) und einen Maulkorb.`, `Flughafen Nürnberg NUE 7 km nördlich, 12 Minuten mit der U-Bahn-Linie U2 vom Hauptbahnhof.`],
    sights: {
      "Kaiserburg": `Mittelalterliche Kaiserburg auf dem Sandsteinfelsen. Die Außenhöfe und der Burggarten (April-Oktober) sind angeleinten Hunden zugänglich; die Museumsinnenräume nicht.`,
      "Hauptmarkt & Schöner Brunnen": `Zentraler Marktplatz, beherrscht vom gotischen Schönen Brunnen (1385-96) und der Frauenkirche. Täglicher Markt 09:00-18:00 Uhr; im Dezember Schauplatz des Christkindlesmarkts.`,
      "Tiergärtnertorplatz & Albrecht-Dürer-Haus": `Nürnbergs fotogenster Kopfsteinpflasterplatz, am Fuß der Kaiserburg. Das Fachwerkhaus, in dem Dürer lebte (1509-1528), ist ein Museum, Hunde nicht erlaubt; der Platz im Freien steht ihnen offen.`,
      "Wöhrder See": `44 Hektar großer künstlicher See mit ausgewiesener Hundebadestelle am Nordufer. 4 km Rundweg, flaches Wasser, ideal zum Schwimmen mit Hund im Sommer.`,
      "Sebalder Reichswald": `25.000 Hektar großer Reichswald am Stadtrand. Das bayerische Waldrecht erlaubt Hunde ohne Leine auf markierten Wegen außerhalb der Jagdzeiten (Dämmerung, April-Juli).`,
      "Christkindlesmarkt": `Weihnachtsmarkt seit 1628, vom 28. November bis 24. Dezember. Angeleinte Hunde sind auf dem gesamten Hauptmarkt willkommen, aber der Andrang ist dicht (2 Mio. Besucher in 4 Wochen), Werktagnachmittage oder nach 21:00 Uhr bevorzugen.`,
    },
  },
  olbia: {
    history: `Olbia an der Nordostküste Sardiniens trägt den Gedanken des Wohlstands bereits in seinem griechischen Namen: Ein zunächst phönizischer, dann römischer Hafen namens Terranova, hat die Stadt schon immer das Tor nach Gallura und zum Tyrrhenischen Meer beherrscht. Um sie herum erinnern bronzezeitliche Nuraghen an eine viel ältere Besiedlung, während die romanische Basilika San Simplicio, im 11. Jahrhundert aus örtlichem Granit erbaut, seit fast tausend Jahren über das Zentrum wacht. Heute ist Olbia mit seinem Flughafen und Fährhafen das wichtigste Tor zum Norden Sardiniens und zur nahegelegenen Costa Smeralda. Der Corso Umberto, eine belebte, mit Cafés gesäumte Fußgängerstraße, führt vom alten Kern zum Hafen mit Blick auf die Insel Tavolara. Für alle, die mit Hund unterwegs sind, verbindet Olbia eine flache, leicht zu begehende Stadt, Sandstrände wie Pittulongu und Porto Istana sowie prähistorische Nuragen-Stätten mitten im offenen Land, nur Minuten entfernt.`,
    petTips: [`Extreme Sommerhitze in Gallura, oft über 35 °C: Sand und Gehweg verbrennen die Pfoten, gehen Sie daher früh morgens oder abends spazieren und führen Sie stets Wasser mit.`, `Saisonales Hundeverbot an den meisten Stränden in der Hochsaison; einige ausgestattete Hundestrände (spiaggia per cani) gibt es in Gallura, prüfen Sie deren Lage vor Ort.`, `Das italienische Gesetz verlangt, einen Maulkorb mitzuführen und ihn auf Verlangen an öffentlichen Orten und in Verkehrsmitteln verwenden zu können; führen Sie einen weichen Maulkorb in Ihrer Tasche mit.`, `Der August ist überlaufen, und haustierfreundliche Unterkünfte sind schnell ausgebucht: Buchen Sie frühzeitig, auch Fähren und Hotels.`, `Im Notfall wählen Sie 112; suchen Sie sich bei Ankunft eine diensthabende Tierklinik, das Angebot konzentriert sich in der Stadt und entlang der Costa Smeralda.`],
    practicalInfo: [`EU-Heimtierausweis und gültige Tollwutimpfung sind beim Check-in in jedem haustierfreundlichen Hotel erforderlich.`, `Leinenpflicht im öffentlichen Raum und ein Maulkorb ist mitzuführen (eine italienische Vorschrift), auf Verlangen zu zeigen oder zu verwenden.`, `Das Aufsammeln von Kot wird überall kontrolliert, mit Bußgeldern bei Nichteinhaltung und häufigen Kontrollen auf dem Corso Umberto und an der Uferpromenade.`, `Olbia ist ein Luft- und Fährhafen-Drehkreuz für Nordsardinien; die Reedereien (Moby, Tirrenia, GNV, Grimaldi) akzeptieren angeleinte Hunde mit Maulkorb, eine Buchung für das Haustier wird empfohlen.`, `Europäische Notrufnummer 112; planen Sie bei jedem Strandausflug mit Hund die starke Sommerhitze und den glühend heißen Sand mit ein.`],
    sights: {
      "Corso Umberto I": `Die zentrale Fußgängerstraße mit Cafés, Geschäften und Palmen, die den alten Kern mit dem Hafen verbindet. Sie geht sie an der Leine entlang, und viele Terrassen heißen Hunde willkommen.`,
      "Basilica di San Simplicio": `Eine romanische Granitkirche aus dem 11. Jahrhundert, das bedeutendste mittelalterliche Bauwerk in Gallura. Hunde dürfen nicht hinein; Platz und Vorplatz können an der Leine besichtigt werden.`,
      "Spiaggia di Pittulongu": `Ein langer, heller Sandstrand wenige Minuten nördlich der Stadt, mit Blick auf die Insel Tavolara. Schwimmen und Spielen außerhalb der Sommersaison; im Sommer nach den Bereichen mit Hundeerlaubnis suchen.`,
      "Porto Istana": `Eine Kette weißer Sandbuchten mit türkisfarbenem Wasser, etwa fünfzehn Minuten entfernt, mit Blick auf Tavolara. Ein hervorragender Rahmen für einen Strandspaziergang außerhalb der Hauptsaison.`,
      "Nuraghe Riu Mulinu": `Eine bronzezeitliche Nuragen-Siedlung auf dem Hügel Cabu Abbas mit Blick über den Golf von Olbia. Eine Freiluftstätte, zu Fuß erreichbar, Hunde an der Leine auf dem Weg willkommen.`,
      "Museo Archeologico di Olbia": `Ein Museum auf einer kleinen Hafeninsel, das römische Schiffswracks und die Geschichte des antiken Terranova zeigt. Ein Innenraum, in dem Hunde nicht zugelassen sind; die umliegenden Kais können an der Leine begangen werden.`,
    },
  },
  olhao: {
    history: `Olhão hat weder Burg noch Kathedrale: Die Stadt entstand im 18. Jahrhundert aus dem Meer, als Fischerfamilien sich auf diesen Sandbänken gegenüber der Ria Formosa niederließen. Ihr goldenes Zeitalter verdankte sie dem Konservieren von Thunfisch und Sardinen, deren Fabriken die Arbeiterstadt des 19. Jahrhunderts prägten. Der direkte Handel mit Nordafrika hinterließ eine im Algarve einzigartige Spur: das Bairro da Barreta, ein Labyrinth aus weiß getünchten, flachdachigen Würfelhäusern mit Dachterrassen (açoteias), die Olhão den Spitznamen „kubistische Stadt" einbrachten. 1808 segelte ein kleines Boot, die Bom Sucesso, von hier über den Atlantik nach Brasilien, um dem König vom Aufstand gegen Napoleons Truppen zu berichten, eine Tat, die Olhão sein Stadtrecht einbrachte. Heute bilden die zwei roten Backsteinmarkthallen von 1916 nach wie vor das schlagende Herz der Stadt, und der Steg daneben lässt Boote nach Armona, Culatra und Farol ablegen. Für einen Hund ist Olhão eine echte Alltagsstadt, flach und lebendig, dem Meer zugewandt.`,
    petTips: [`Badesaison 1. Juni bis 30. September: Hunde sind an Olhãos bewachten Stränden verboten, mit Bußgeldern. Von Oktober bis Mai eignet sich die Zeit besser für die Inseln.`, `Planmäßige Inselfähren: Hunde nur in einer Transportbox. Für einen großen Hund buchen Sie ein Wassertaxi (Hunde an Deck erlaubt).`, `Sie befinden sich innerhalb des Naturparks Ria Formosa: Halten Sie die Leine in der Nähe von Dünen und Wattflächen an, ein geschütztes Vogelhabitat.`, `Die Algarve ist Leishmaniose-Endemiegebiet: Verwenden Sie von Frühjahr bis Herbst, besonders in der Dämmerung, ein Repellent-Halsband oder Spot-on-Präparat.`, `Listenhunde (Pitbull, Rottweiler usw.): Leine und Maulkorb sind in der Öffentlichkeit Pflicht, und sie sind von den meisten Verkehrsmitteln ausgeschlossen.`],
    practicalInfo: [`Tierärztliche Notdienste: Centro Veterinário Porto Seguro (+351 289 707 303, Notfall +351 967 721 777) und 115 Animal (+351 289 715 115), beide 24 Stunden; 24/7-Krankenhaus in Faro (+351 289 880 100).`, `Es gibt keinen offiziellen Hundestrand in der Gemeinde Olhão: Folgen Sie den Hinweisschildern vor Ort, Duldung ist kein Recht.`, `CP-Regionalzug: Ein kleiner Hund reist kostenlos in einer geschlossenen Box, ein großer Hund mit Maulkorb und Leine zum halben Fahrpreis (Ticket am Schalter, Impfheft + Mikrochip erforderlich). Faro ist 10 Minuten entfernt.`, `Portugal ist EU-Mitglied: Ein EU-Heimtierausweis, Mikrochip und gültige Tollwutimpfung genügen für die Einreise aus einem anderen EU-Land.`, `Zwei städtische Hundeparks (Levante und Pinheiros de Marim), weitere sind für die ganze Gemeinde geplant. Im Sommer wenig Schatten, gehen Sie daher früh oder spät spazieren.`],
    sights: {
      "Mercados de Olhão": `Die zwei roten Backsteinmarkthallen von 1916, auf der einen Seite Fisch, auf der anderen Obst und Gemüse, sind das Wahrzeichen von Olhão. Hunde dürfen die Hallen nicht betreten, doch die überdachten Arkaden außen und die Esplanade sind an der Leine begehbar.`,
      "Bairro da Barreta": `Die kubistische Altstadt: enge Gassen, weiße Flachdachhäuser und Dachterrassen, ein im Algarve einzigartiger nordafrikanischer Einfluss. Ein hervorragender Spaziergang an der Leine, am besten früh, wenn die Tünche die Hitze noch nicht zurückwirft.`,
      "Ilha da Armona": `Eine Barriereinsel der Ria Formosa, 20 Minuten mit dem Boot entfernt, mit einem riesigen, außerhalb der Saison fast menschenleeren Atlantikstrand. Angeleinte Hunde willkommen von Oktober bis Mai; vom 1. Juni bis 30. September in der bewachten Zone verboten.`,
      "Ilha da Culatra e Farol": `Eine lebendige Fischerinsel mit dem Leuchtturm von 1851 und langen, durch Dünen-Bohlenwege verbundenen Ozeanstränden. Hunde an der Leine (Naturpark); dieselben Sommerbeschränkungen wie überall in Portugal.`,
      "Jardim Pescador Olhanense": `Der zentrale Uferpark zwischen den Markthallen und der Lagune, mit altem Baumbestand und einer flachen Promenade am Wasser. Eine leichte Leinenrunde, die zum Inselsteg führt; morgens im Schatten.`,
      "Parque Canino do Levante": `Ein 2023 im Levante-Park eröffneter städtischer Hundepark: über 4.000 m² eingezäunt mit Tunnel, Sprungring, Brücken und Agility-Hindernissen. Ein sicherer Freilaufbereich, im Sommer am besten früh oder spät zu besuchen.`,
    },
  },
  olomouc: {
    history: `Olmütz (Olomouc), die historische Hauptstadt Mährens, war eine der mächtigsten Städte der böhmischen Länder: Bischofssitz seit 1063, eine 1573 gegründete Universität und eine kaiserliche Festung, die 1848 dem vor der Revolution fliehenden Habsburger Hof Zuflucht bot. Ihre Heilige-Dreifaltigkeits-Säule, 35 Meter barocker Bildhauerkunst, 1754 vollendet, steht seit 2000 auf der UNESCO-Liste, und ihre sechs barocken Brunnen prägen die Plätze, auf denen die astronomische Uhr aus der kommunistischen Ära von 1955 dem gotischen Rathaus antwortet. Als Universitätsstadt mit rund 100.000 Einwohnern bleibt Olmütz Mitteleuropas großes Geheimnis abseits des Übertourismus: Prags Denkmäler ohne die Menschenmassen. Mit Hund ist die Ausgangslage ideal: ein Gürtel aus Parks auf den ehemaligen Wallanlagen (Leinenpflicht), die March-Flussaue zum freien Laufen, der bewaldete Hügel Svatý Kopeček und eine absolute Seltenheit, ein Zoo, der angeleinte, maulkorbtragende Hunde für 100 CZK zulässt.`,
    petTips: [`Leinenpflicht in den drei Wallpark-Anlagen (Smetanovy, Čechovy, Bezručovy sady): Die Stadtpolizei verhängt Bußgelder vor Ort.`, `Der Zoo Olmütz lässt Hunde (100 CZK) mit Maulkorb und Leine zu; Maulkörbe können am Eingang gegen 200 CZK Pfand gemietet werden, Tierhäuser sind tabu.`, `In den DPMO-Straßenbahnen und -Bussen: geschlossene Transportbox oder Maulkorb und kurze Leine, ermäßigtes Hundeticket.`, `Freilaufen: die March-Flussaue, die Waldwege am Svatý Kopeček und die Ufer der Kiesseen außerhalb der Brutzeit.`, `Kontinentale Sommer: Das Pflaster der Plätze heizt sich am Nachmittag auf, gehen Sie früh spazieren und zielen Sie auf die schattigen Wallparks.`],
    practicalInfo: [`Klima: kontinental, warme Sommer um 20 Grad im Juli mit Gewittern, kalte, nebelige Winter um -1 bis 0 Grad.`, `Transport: DPMO-Straßenbahnen und -Busse (Transportbox oder Maulkorb und Leine, ermäßigtes Hundeticket), direkte Buslinie 11 zum Svatý Kopeček und Zoo.`, `Anreise: Bahnhof Olomouc hl.n. an der Hauptstrecke Prag-Ostrava, Prag etwa 2 Std., Wien 3 Std. über Břeclav.`, `Währung: tschechische Krone (CZK, 1 EUR = etwa 25 CZK); Karten werden fast überall akzeptiert.`, `Tierärztlicher Notdienst: Klinik MVDr. Mazoch (Čechova 5, +420 585 428 351, 24-Stunden-Bereitschaft) und Klinik Špruček (Brněnská 501/82, Notruflinie +420 728 308 803); EU-Notrufnummer 112.`],
    sights: {
      "Sloup Nejsvětější Trojice": `Die Heilige-Dreifaltigkeits-Säule, 35 UNESCO-gelistete barocke Meter mitten auf dem Hauptplatz. Terrassen, die astronomische Uhr und ein angeleinter Hund kommen problemlos miteinander aus.`,
      "Zoo Olomouc": `Einer von Europas seltenen Zoos, der Besucherhunde zulässt: 100 CZK Hundeticket, Maulkorb und Leine Pflicht, Tierhäuser ausgeschlossen. Auf dem Svatý-Kopeček-Hügel, mit einem 32 Meter hohen Aussichtsturm.`,
      "Bezručovy sady": `Der Schluchtenpark, eingezwängt zwischen den mittelalterlichen Mauern und dem Bach Mlýnský, der stimmungsvollste des grünen Gürtels. Leinenpflicht, und die Stadtpolizei setzt sie auch durch.`,
      "Svatý Kopeček": `Der bewaldete Wallfahrtshügel, gekrönt von der barocken Basilika, 20 Minuten entfernt mit Buslinie 11. Waldwege, eine panoramische Esplanade über die Haná-Ebene und das hundefreundliche Restaurant u Macků.`,
      "Horní náměstí": `Der Hauptplatz mit dem gotischen Rathaus, der astronomischen Uhr aus der kommunistischen Ära und zwei der sechs barocken Brunnen. Der Brunnenrundgang über die Plätze ist der klassische Stadtspaziergang an der Leine.`,
      "Chomoutovské jezero": `Ein großer Kiesgrubensee 10 km nördlich, mit einer leichten Wanderrunde und tolerierten Stellen zum Hundeschwimmen. Ein Vogelschutzgebiet: Leinenpflicht und Abstandsregeln in der Brutzeit.`,
    },
  },
  opatija: {
    history: `Opatija an der kroatischen Kvarner-Küste in der nördlichen Adria entwickelte sich zum großen Kurort der österreichisch-ungarischen Aristokratie, nachdem 1844 die Villa Angiolina erbaut und die Eisenbahn eröffnet wurde. Innerhalb weniger Jahrzehnte füllte sich der Ort mit Belle-Époque-Grandhotels, Villen und gepflegten Parkanlagen und erhielt den Beinamen „das Nizza der Adria". Sein Wahrzeichen ist noch immer die Statue des Mädchens mit der Möwe, die auf einem Felsen am Anfang des Lungomare thront, der 12 km langen Küstenpromenade, die das alte Fischerdorf Volosko über das Stadtzentrum mit Lovran verbindet. Für Hundebesitzer ist Opatija eine der einfachsten Städte Kroatiens: Der Lungomare ist ganzjährig an der Leine begehbar, zwei ausgewiesene Hundestrände erlauben das Baden, und der Naturpark Učka bietet echte Bergpfade hinter der Stadt. Zwei Dinge sollte man einplanen: die sommerliche Hitze der Kvarner-Bucht und die kroatische Regel, die das Baden mit Hund nur an ausgewiesenen Stränden erlaubt.`,
    petTips: [`Hunde sind nur an den beiden ausgewiesenen Hundestränden erlaubt (Opatija/Punta Kolova und Gornja Ika bei Lovran); öffentliche Badestrände wie Slatina verbieten Hunde.`, `Gehen Sie im Sommer früh morgens oder abends am Lungomare spazieren: Das Steinpflaster wird mittags sehr heiß, und die Kvarner-Sommer übersteigen regelmäßig 30 °C.`, `Führen Sie für die Autotrolej-Busse einen weichen Maulkorb und eine kurze Leine mit: Für größere Hunde wird in kroatischen öffentlichen Verkehrsmitteln ein Maulkorb erwartet.`, `Der Naturpark Učka ist an heißen Tagen die kühle Fluchtmöglichkeit: schattige Wege an der Leine, aber bringen Sie Wasser mit, da Brunnen dort oben rar sind.`, `Tierärzte: Veterinarska Ambulanta Opatija (Stubište Ivana Zavidića 3, +385 51 701 280, abwechselnde Sprechzeiten an geraden/ungeraden Tagen); 24-Stunden-Notdienst Veterinarska stanica Rijeka +385 91 214 9922.`],
    practicalInfo: [`Kroatien ist EU-Mitglied: EU-Heimtierausweis, Mikrochip und gültige Tollwutimpfung sind beim Check-in im haustierfreundlichen Hotel erforderlich.`, `Leinenpflicht im öffentlichen Raum; für größere Hunde wird in den Autotrolej-Bussen ein Maulkorb erwartet.`, `Das Baden mit Hund ist auf ausgewiesene Strände beschränkt (Punta Kolova, Gornja Ika); an öffentlichen Badestränden verboten.`, `Kein Bahnhof und keine örtliche Fähre: Anreise über den Flughafen Rijeka (Insel Krk, ca. 1 Std.) oder über das 15 km entfernte Rijeka; vor Ort zu Fuß am Lungomare oder mit dem Autotrolej-Bus.`, `Notfälle: allgemeine Nummer 112; 24-Stunden-Tierarzt Veterinarska stanica Rijeka +385 91 214 9922 (etwa 15 km entfernt).`],
    sights: {
      "Lungomare": `Opatijas ikonische, 12 km lange Küstenpromenade, die Volosko über das Stadtzentrum mit Lovran verbindet, direkt am Wasser. Angeleinte Hunde sind das ganze Jahr über willkommen, und es ist die beste Art, die Riviera zu Fuß zu erkunden.`,
      "Park Angiolina": `Der historische Park im Herzen von Opatija, in den 1880er-Jahren rund um die Villa Angiolina angelegt, mit Kamelien, Magnolien und exotischen Bäumen. Die schattigen Kieswege eignen sich für einen kühlen Morgenspaziergang, angeleinte Hunde sind überall willkommen.`,
      "Djevojka s galebom": `Die Statue des Mädchens mit der Möwe, das Symbol von Opatija, auf einem Felsen über dem Meer am Anfang des Lungomare. Vollständig im Freien, ein klassischer Fotostopp bei Sonnenuntergang und völlig unproblematisch für angeleinte Hunde.`,
      "Volosko": `Das alte Fischerdorf am nördlichen Ende des Lungomare, mit steilen Steingassen, die zu einem noch aktiven Hafen führen, und den besten Konoba-Tavernen der Riviera. Eine malerische Kulisse für einen abendlichen Spaziergang mit angeleintem Hund.`,
      "Park prirode Učka": `Der Naturpark des Učka-Massivs, das sich über Opatija erhebt, durchzogen von markierten Wegen durch Buchen- und Kastanienwälder bis zum Gipfel Vojak (1.401 m). Kühler und schattiger als die Küste, Hunde sind auf den Wegen an der Leine willkommen.`,
      "Slatina & Stadtstrände": `Opatijas zentrale Strände wie Slatina sind belebte Betonbadeplattformen, an denen Hunde nach kroatischen Vorschriften nicht erlaubt sind. Nutzen Sie stattdessen die ausgewiesenen Hundestrände bei Punta Kolova oder Gornja Ika zum Baden.`,
    },
  },
  'oropesa-del-mar': {
    history: `Oropesa del Mar, valencianisch Orpesa, wacht von seiner hügeligen Altstadt mit weißen Gassen aus über die Costa del Azahar, in der Provinz Castellón. Der Torre del Rey, ein im 16. Jahrhundert gegen Berberüberfälle errichteter Küstenwachturm, bleibt sein Wahrzeichen, während der Leuchtturm die Landzunge krönt und die Playa de la Concha sowie die mit der Blauen Flagge ausgezeichnete Playa Morro de Gos ihren Sand am Fuß der Stadt ausbreiten. Lange ein Fischerdorf, ist Oropesa zu einem familienfreundlichen Badeort am Mittelmeer geworden, geprägt durch den riesigen Komplex Marina d'Or direkt südlich davon. Drum herum laden der Küsten-Grünzug Vía Verde und der Voramar-Pfad zu Spaziergängen am Wasser ein, während das nahegelegene Feuchtgebiet Prat de Cabanes-Torreblanca Lagunen und Vögel beherbergt. Mit Hund lässt sich die flache Küstenstadt außerhalb der Sommerhitze leicht erkunden.`,
    petTips: [`Intensive Mittelmeerhitze von Juni bis September: Sand und Gehweg verbrennen die Pfoten, gehen Sie daher früh morgens oder abends spazieren und führen Sie stets Wasser mit.`, `Sommerliches Hundeverbot an den städtischen Stränden (La Concha, Morro de Gos) in der Hochsaison; fragen Sie vor Ort nach, an der Küste von Castellón gibt es einige Hundestrände (playas caninas), an denen sie erlaubt sind.`, `Als PPP gelistete Rassen (potenziell gefährliche Hunde) müssen in der Öffentlichkeit eine kurze Leine und einen Maulkorb tragen, mit Papieren in Ordnung.`, `Leishmaniose-Prophylaxe wird empfohlen: Die Sandmücke ist von Frühjahr bis Herbst entlang der gesamten Mittelmeerküste aktiv, verwenden Sie daher ein geeignetes Repellent-Präparat.`, `Einheitliche Notrufnummer 112; suchen Sie sich bei Ankunft eine diensthabende Tierklinik, das Angebot konzentriert sich in Oropesa und Richtung Benicàssim und Castellón.`],
    practicalInfo: [`EU-Heimtierausweis und aktuelle Tollwutimpfung sind beim Check-in in haustierfreundlichen Hotels erforderlich.`, `Leinenpflicht in der Öffentlichkeit; für PPP-Rassen ist ein Maulkorb vorgeschrieben, und das Aufsammeln von Kot wird unter Androhung eines städtischen Bußgelds durchgesetzt.`, `Städtische Strände sind im Sommer für Hunde gesperrt (ungefähr Mitte Juni bis Mitte September); außerhalb der Saison wird der Zugang zum Sand im Allgemeinen geduldet, prüfen Sie daher die Schilder.`, `Eine sehr flache, gut zu Fuß erkundbare Küstenstadt; Renfe-Züge auf der Strecke Castellón-Barcelona akzeptieren kleine Hunde in der Transportbox und größere Hunde mit Maulkorb gemäß den geltenden Regeln.`, `Europäische Notrufnummer 112; planen Sie bei jedem Ausflug mit Hund die starke Sommerhitze und den glühend heißen Sand mit ein.`],
    sights: {
      "Torre del Rey": `Ein Wachturm aus dem 16. Jahrhundert über dem Meer, errichtet zum Schutz der Küste vor Berberpiraten. Von außen frei zugänglich, Sie können ihn an der Leine entlang der Uferpromenade umrunden.`,
      "Casco Antiguo de Oropesa": `Die hügelige Altstadt mit weißen Gassen, Kirchplatz und Überresten der alten Burg mit Blick über die Bucht. Sie erkunden sie an der Leine, zwischen Terrassen und Meerblicken.`,
      "Faro de Oropesa": `Ein Leuchtturm, der die Landspitze am Ende der Altstadt krönt und ein weites Mittelmeerpanorama eröffnet. Das Innere ist nicht zugänglich, aber die Esplanade und der umliegende Weg können an der Leine begangen werden.`,
      "Playa de la Concha": `Ein städtischer Sandstrand am Fuß der Altstadt, eine geschützte Bucht mit lebhafter Promenade dahinter. Schwimmen und Spielen außerhalb der Saison; im Sommer sind Hunde auf dem bewachten Sand verboten, suchen Sie also die erlaubte Zone.`,
      "Vía Verde del Mar": `Eine ehemalige Bahnstrecke, die zu einem flachen Küstenweg wurde und Oropesa entlang der Buchten mit Benicàssim verbindet. Ideal zum Spazierengehen oder Laufen mit angeleintem Hund, im Schatten von Pinien und mit Blick aufs Meer.`,
      "Prat de Cabanes-Torreblanca": `Ein Naturpark aus Küstenlagunen und Sumpfgebiet nördlich von Oropesa, ein Rückzugsort für Wasservögel und Schildkröten. Wege und Beobachtungshütten können an der Leine begangen werden; bleiben Sie zum Schutz der Tierwelt auf den Pfaden.`,
    },
  },
  osaka: {
    history: `Osaka entwickelte sich von der mittelalterlichen Tempelstadt und dem Hafen Naniwa zur Handelshauptstadt Japans, der „Küche der Nation", deren Kaufleute das Land finanzierten, während die Tokugawa-Macht in Edo saß. Toyotomi Hideyoshis große Burg, nach Kriegen und Bränden wiederaufgebaut, verankert die Stadt noch heute, und die Kanäle, die einst Reis und Waren transportierten, ließen die Esskultur von Dotonbori und Kuromon entstehen. Heute ist Osaka das pulsierende Herz der Kansai-Region, direkter und verspielter als Tokio. Für einen Hundebesitzer ist die Stadt machbar, aber regelgebunden: Hunde fahren in U-Bahn und JR-Zügen nur in einer geschlossenen Transportbox, und die meisten Tempel, Einkaufszentren und Food-Hallen schließen sie aus. Das Vergnügen liegt im Freien, in den Uferparks von Nakanoshima, den präfekturalen Hundeauslaufplätzen wie Hamadera und den kanalgesäumten Straßen, wobei der Shinkansen Kyoto in etwa 15 Minuten und Tokio in etwa 2 Stunden 30 Minuten verbindet.`,
    petTips: [`Die meisten Tempel, Einkaufszentren und Food-Hallen Osakas schließen Hunde aus; auf offenem öffentlichem Gelände werden sie an der Leine geführt, und die Osaka-Burg lässt keine Haustiere in den Burgturm.`, `Zwei Transportregeln: In der U-Bahn und den Bussen Osakas fährt ein Hund kostenlos in einer geschlossenen, verdeckten Transportbox mit, die auf den Schoß passt (keine veröffentlichte Größenangabe); bei JR West ist eine Box bis 70 cm, unter 10 kg, gegen eine Gebühr von etwa 290 Yen erlaubt.`, `Die offiziellen präfekturalen Hundeauslaufplätze (darunter Hamadera in Sakai) sind die verlässliche Option ohne Leine, kostenlos, erfordern jedoch einen Nachweis über eine Tollwutimpfung und eine jährliche Impfung innerhalb des letzten Jahres.`, `Der Sommer in Osaka ist heiß und sehr feucht: Gehen Sie im Morgengrauen oder nach Einbruch der Dunkelheit spazieren, testen Sie den Gehweg mit der Hand und führen Sie überall Wasser mit.`, `Nächtlicher Notfalltierarzt: Osaka Animal Night-Time Emergency Medical Center in Higashinari (06-4259-1212), etwa von 21:00 bis 05:00 Uhr; rufen Sie zur Bestätigung an und halten Sie medizinische Details schriftlich fest.`],
    practicalInfo: [`Japan gehört weder zur EU noch zum Schengen-Raum: Die Einfuhr eines Hundes erfordert einen ISO-Mikrochip, zwei Tollwutimpfungen, einen FAVN-Serologietiter von mindestens 0,5 IU/ml, danach eine Wartezeit von 180 Tagen sowie eine vorherige Einfuhrmeldung beim Animal Quarantine Service mindestens 40 Tage vor Ankunft.`, `Flughäfen: Kansai International (KIX) ist das wichtigste internationale Tor, mit Itami (ITM) für Inlandsflüge; prüfen Sie die Tiertransportregeln Ihrer Fluggesellschaft rechtzeitig vor der Abreise.`, `Währung: der japanische Yen. Das tägliche haustierfreundliche Budget liegt hoch, planen Sie also einen Spielraum für Haustiertaxis ein, die für große Hunde, die von U-Bahn und Zügen ausgeschlossen sind, unerlässlich sind.`, `Beste Reisezeit: Frühling und Herbst sind mild zum Spazierengehen; meiden Sie den heißen, feuchten Sommer und die Regenzeit von Juni bis Juli; der Winter ist kühl, aber meist mild und trocken.`, `Japan-Cluster: Der Shinkansen verbindet Osaka mit Kyoto in etwa 15 Minuten und mit Tokio in etwa 2 Stunden 30 Minuten und schließt damit das Dreieck Tokio-Kyoto-Osaka für eine größere Japanreise mit Hund.`],
    sights: {
      "Osaka Castle Park (Osaka-jo Koen)": `Der weitläufige Park rund um die Burg von Osaka ist das grüne Wahrzeichen der Stadt. Angeleinte Hunde werden häufig auf dem offenen Außengelände geführt; der Burgturm und das Museum schließen Haustiere jedoch aus.`,
      "Nakanoshima": `Die Flussinsel im Herzen von Osaka mit ihren Parks, Uferterrassen und bepflanzten Böschungen. Eine natürliche Route zum Spazierengehen an der Leine, gesäumt von hundefreundlichen Cafés, die im offiziellen Tourismusführer der Stadt aufgeführt sind.`,
      "Hamadera Park Dog Run": `Ein offizieller Hundeauslaufplatz der Präfektur Osaka im Hamadera-Park in Sakai, mit getrennten Bereichen für kleine und größere Hunde. Kostenloser Eintritt von 10:00 bis 16:30 Uhr, gegen Nachweis aktueller Impfungen.`,
      "Dotonbori": `Der Neonkanal und seine Restaurantgassen sind das Bild Osakas. Sie können ihn mit angeleintem Hund durchqueren, doch die meisten Geschäfte und Street-Food-Stände schließen sie aus, betrachten Sie es also eher als Spaziergang denn als Essstopp.`,
      "Sukunahikona Shrine": `Ein kleiner Schrein im historischen Medizinviertel nahe Nakanoshima, im offiziellen Osaka-Führer als Ort für Haustiersegnungen aufgeführt. Ein leichter Stopp an der Leine, der Ihren Hund ruhig hält.`,
      "the Farm UNIVERSAL OSAKA": `Ein großes Gartencenter mit Café in Ibaraki, nördlich von Osaka, auf den offiziellen Tourismus-Haustierseiten aufgeführt, mit hundefreundlicher Terrasse und kleinem Hundeauslauf. Am besten mit dem Auto oder Haustiertaxi von der Stadt aus erreichbar.`,
    },
  },
  oslo: {
    history: `Oslo wurde um 1040 am Kopf seines Fjords gegründet, nach dem Brand von 1624 von Christian IV. als Christiania wiederaufgebaut und 1925 in Oslo umbenannt. Die Hauptstadt mit rund 710.000 Einwohnern wird vom Waldgürtel Marka umschlossen und hat eine der höchsten Hundebesitzerquoten Europas, mit etwa 75.000 in der Gemeinde registrierten Hunden. Norweger behandeln Hunde als Familienmitglieder: Das landesweite Gesetz zur Leinenpflicht (båndtvang) schreibt vom 1. April bis 20. August Leinen vor, um Wildtiere und weidende Schafe zu schützen, doch außerhalb dieses Zeitraums werden die Pfade von Nordmarka zu einem Paradies für Wanderungen ohne Leine. Oslo hat Dutzende von Hundeparker (eingezäunte Hundeparks), Torshovdalen, Sofienbergparken und St. Hanshaugen zählen zu den besten, und Hunde fahren mit Straßenbahn, U-Bahn, Bus und Fähre zum Kindertarif. Cafés, Hotels und sogar einige Museen heißen sie willkommen; das Aufsammeln nach dem Hund wird mit Bußgeldern von 1.600 NOK streng durchgesetzt.`,
    petTips: [`Kaufen Sie für Ihren Hund ein Ruter-Ticket zum Kindertarif für U-Bahn, Straßenbahn und Bus, auf den Fähren nach Bygdøy oder zu den Inseln ist kein Ticket nötig.`, `Beachten Sie die Leinenpflicht (båndtvang): Vom 1. April bis 20. August muss jeder Hund außerhalb eingezäunter Parks angeleint sein, auch in Nordmarka, mit Bußgeldern bis zu 2.000 NOK.`, `Der 24-Stunden-Notfalltierarzt ist AniCura Oslo Dyresykehus in der Ensjøveien 14 (+47 22 68 35 00); halten Sie den Heimtierausweis bereit.`, `Führen Sie Kotbeutel mit: Oslo verhängt 1.600 NOK Bußgeld für nicht aufgesammelten Hundekot, und Parkaufseher kontrollieren die zentralen Parks aktiv.`, `Wachsen Sie im Winter die Pfoten Ihres Hundes vor Spaziergängen, Oslo verwendet eine Mischung aus Splitt und Sole, die die Ballen bei -15 °C aufreißen lässt.`],
    practicalInfo: [`Der Flughafen Oslo Gardermoen (OSL) ist mit dem Flughafenexpress Flytoget 19 Minuten vom Zentrum entfernt; Hunde reisen kostenlos in Transportboxen oder mit einem 50 %-Ticket.`, `Beste Reisezeit: September-Oktober für klare Waldwanderungen ohne Leine, Februar-März für Skijöring und Spaziergänge auf zugefrorenen Seen.`, `24-Stunden-Notfalltierarzt: AniCura Dyresykehus, Ensjøveien 14, +47 22 68 35 00.`, `Die Bygdøy-Fähre (Linie B9, April-Oktober) ab Rådhusbrygge 3 lässt Hunde kostenlos an Bord und führt in 15 Minuten zu Museen und Stränden.`, `Leitungswasser von Oset kommt direkt aus dem Maridalsvannet-See und ist überall trinkbar, kein Flaschenwasser nötig.`],
    sights: {
      "Nordmarka Forest": `Ein 430 km² großes Waldgebiet, direkt mit der U-Bahn-Linie 1 bis Frognerseteren erreichbar. Außerhalb der Leinenpflicht-Saison (21. August-31. März) können Hunde auf Hunderten Kilometern Wegen frei laufen, und im Winter umfassen markierte Loipen parallele Spuren für Schlittenhunde und Skijöring.`,
      "Ekebergparken": `Ein 25 Hektar großer Hangpark über dem Fjord mit 45 Skulpturen von Rodin, Dalí und Louise Bourgeois. Angeleinte Hunde sind auf allen Wegen willkommen, und der Aussichtspunkt bei Salvador Dalís Venus liefert das klassische Skyline-Foto.`,
      "Sørenga Seawater Pool & Promenade": `Eine Hafenpromenade im Stadtteil Bjørvika mit einem schwimmenden Meerwasserbecken. Hunde dürfen die Schwimmplattform nicht betreten, aber die angrenzende Treppe Sørengkaia lässt sie im Fjord planschen, und die gesamte Promenade ist im Sommer eine lebendige Parade aus Menschen und Hunden.`,
      "Frognerparken": `Der größte Skulpturenpark der Welt eines einzelnen Künstlers, mit 212 Bronze- und Granitfiguren von Gustav Vigeland im 45 Hektar großen Frognerparken. Angeleinte Hunde sind überall im Freien willkommen, und die Rasenflächen südlich des Monoliths sind mit ihnen ein beliebter Picknickplatz.`,
      "Akershus Fortress": `Eine um 1290 begonnene mittelalterliche Festung, noch immer aktives militärisches Hauptquartier, hoch über dem Oslofjord. Angeleinte Hunde dürfen die Wälle, Höfe und die Uferpromenade kostenlos begehen, jedoch nicht das Schlossmuseum betreten.`,
      "Grünerløkka & Sofienbergparken": `Oslos vom Hipster- zum Familienviertel gewandelter Stadtteil, gesäumt von Vintage-Läden, veganen Cafés und unabhängigen Buchhandlungen. Sein grünes Herz, der Sofienbergparken, umfasst ein großes eingezäuntes Freilaufgehege, das sich jeden Abend mit örtlichen Hunden und ihren Besitzern füllt.`,
    },
  },
  ostend: {
    history: `Ostende, niederländisch Oostende, wird die Königin der belgischen Küste genannt. Der ehemals befestigte Fischerhafen in Westflandern wurde im 19. Jahrhundert zum bevorzugten Seebad der belgischen Könige, die seine Deiche, Galerien und den prächtigen Kursaal errichten ließen. Leopold II. hinterließ die Königlichen Galerien, eine lange überdachte Promenade mit Blick auf die Nordsee, und die Stadt ist bis heute geprägt vom Maler James Ensor, einem ihrer Söhne. Der breite Sandstrand und der gerade, windumtoste Deich erstrecken sich über Kilometer, während der Dreimaster Mercator und der Yachthafen an die maritime Vergangenheit erinnern. Die Kusttram, die längste Straßenbahnlinie der Welt, bedient von Ostende aus die gesamte Küste, und die Atlantikwall-Stätte in Raversyde bewahrt die Spuren des Krieges. Mit Hund bietet der Strand außerhalb der Saison weite erlaubte Bereiche und im Sommer ausgewiesene Hundezonen, und der Deich kann ganzjährig an der Leine begangen werden.`,
    petTips: [`Nordseewind und Kälte selbst im Sommer: Bringen Sie etwas mit, um einen nassen Hund abzutrocknen und zu wärmen, da das Wasser das ganze Jahr über kühl bleibt.`, `Saisonale Strandregeln: Im Sommer (etwa Mai bis September) sind Hunde auf ausgeschilderte Hundezonen beschränkt, außerhalb der Saison genießen sie den Strand jedoch frei, oft ohne Leine am frühen Morgen.`, `Sand und Treibgut können Angelhaken oder Trümmer verbergen; spülen Sie nach dem Strand die Pfoten ab und achten Sie darauf, was der Hund verschluckt.`, `Die Kusttram und die SNCB-Züge akzeptieren Hunde (kleiner Hund kostenlos in einer Tasche, großer Hund mit Ticket und oft Maulkorb): ideal, um die Küste ohne Auto zu erkunden.`, `Einheitliche Notrufnummer 112; suchen Sie sich bei Ankunft eine diensthabende Tierklinik, mehrere Praxen bedienen Ostende und die Küste.`],
    practicalInfo: [`EU-Heimtierausweis und aktuelle Tollwutimpfung sind beim Check-in in haustierfreundlichen Hotels erforderlich.`, `Leinenpflicht in der Stadt und Kotaufsammlung unter Bußgeldandrohung durchgesetzt; einige mastiffartige Rassen werden je nach Gemeinde reguliert.`, `Strand mit saisonalen Regeln: ausgewiesene Hundezonen im Sommer, nahezu freier Zugang außerhalb der Saison, mit Schildern an jedem Zugang.`, `Ostende ist ein Knotenpunkt der Kusttram und der SNCB; Hunde werden bei beiden akzeptiert, sodass Sie Brügge, Brüssel und die gesamte Küste ohne Auto erreichen können.`, `Europäische Notrufnummer 112; rechnen Sie mit häufigem Wind und Regen und bringen Sie frisches Wasser mit, um den Hund nach dem Strand abzuspülen.`],
    sights: {
      "Zeedijk en strand": `Eine lange, gerade Deichpromenade und ein weiter Nordsee-Sandstrand, das Herz des Küstenlebens. Außerhalb der Saison laufen Hunde frei auf weiten Abschnitten; im Sommer sind sie auf ausgeschilderte Hundezonen beschränkt.`,
      "Kursaal": `Ein monumentales Kasino- und Konzerthaus an der Uferpromenade, Erbe der königlichen Pracht des 19. Jahrhunderts. Das Innere ist für Hunde tabu; Sie gehen an der Leine am Gebäude und seiner Panoramaterrasse vorbei.`,
      "James Ensorhuis": `Das Wohnmuseum des Malers James Ensor, einer Figur des Expressionismus, mit rekonstruiertem Atelier und seinem Laden für maritime Kuriositäten. Hunde dürfen nicht hinein; das Einkaufsviertel drum herum lässt sich an der Leine erkunden.`,
      "Mercator": `Ein ehemaliges Dreimast-Schulschiff, das im Yachthafen liegt und zu einem schwimmenden Museum umgebaut wurde. Hunde sind an Bord nicht zugelassen, aber die Hafenkais bieten einen angenehmen Spaziergang an der Leine.`,
      "Venetiaanse Gaanderijen": `Venezianische Galerien aus dem frühen 20. Jahrhundert, weiße Arkaden, die sich zum Deich und zur Nordsee hin öffnen. Ein überdachter, an der Leine begehbarer Durchgang, geschützt vor dem Wind während der Strandspaziergänge.`,
      "Kusttram": `Die Küstenstraßenbahn, die die gesamte belgische Küste befährt, von De Panne bis Knokke, die längste Straßenbahnlinie der Welt. Hunde sind mit Ticket erlaubt, praktisch, um Nachbarstrände ohne Auto zu erreichen.`,
    },
  },
  oviedo: {
    history: `Oviedo, Hauptstadt Asturiens, wacht über das grüne Landesinnere Nordspaniens, dem Gebirge zugewandt statt dem Meer. Als Wiege des mittelalterlichen asturischen Königreichs bewahrt die Stadt ein von der UNESCO gelistetes Juwel der vorromanischen Kunst: Auf dem Monte Naranco erheben Santa María del Naranco und San Miguel de Lillo ihre Gewölbe aus dem 9. Jahrhundert über die Stadt. Darunter thront die gotische Kathedrale San Salvador über einer Altstadt aus gepflasterten Gassen, Plätzen und dem Fontán-Markt. Oviedo ist zudem eine Stadt des Ciders: Die Sidrerías der Calle Gascona schenken ihren Cider aus großer Höhe auf Terrassen aus, die sehr hundefreundlich sind, und eine Statue von Woody Allen erinnert an seine Vorliebe für den Ort. Sein ozeanisches Klima, mild und feucht, bringt kühle Sommer mit sich, die für einen Hund angenehm sind, während die Picos de Europa und die asturischen Strände als Tagesausflug erreichbar sind.`,
    petTips: [`Grünes, feuchtes Klima das ganze Jahr über: Bringen Sie etwas mit, um einen nassen Hund abzutrocknen, aber die kühlen Sommer bleiben zum Spazierengehen sehr angenehm.`, `Saisonaler Hinweis: Die Strände der asturischen Küste (Gijón, Salinas, San Lorenzo) verbieten von Juni bis September häufig Hunde; prüfen Sie dies vor einem Tagesausflug und weichen Sie im Sommer auf die Stadtparks aus.`, `Die Sidrerías der Calle Gascona und viele Terrassen akzeptieren gerne wohlerzogene, angeleinte Hunde, ideal für eine gesellige Pause.`, `Auf dem Monte Naranco genießen angeleinte Hunde den Hang und das Äußere der vorromanischen Kirchen, jedoch nicht deren Innenräume; die Straße steigt an, führen Sie also Wasser mit.`, `Einheitliche Notrufnummer 112; EU-Heimtierausweis und aktuelle Tollwutimpfung sind im Hotel erforderlich, und suchen Sie sich bei Ankunft eine diensthabende Tierklinik.`],
    practicalInfo: [`EU-Heimtierausweis und aktuelle Tollwutimpfung sind beim Check-in in haustierfreundlichen Hotels erforderlich.`, `Leinenpflicht in der Stadt und Kotaufsammlung unter Bußgeldandrohung durchgesetzt; als PPP gelistete Rassen müssen Leine und Maulkorb tragen.`, `Mildes, regnerisches ozeanisches Klima das ganze Jahr über, mit für einen Hund angenehmen kühlen Sommern; bringen Sie Regenschutz mit.`, `Oviedo ist per Renfe, der FEVE-Linie und ALSA-Fernbussen mit Gijón, der Küste und den Picos de Europa verbunden; Hunde werden gemäß den Regeln jedes Betreibers akzeptiert.`, `Europäische Notrufnummer 112; die Küstenstrände verhängen sommerliche Verbote, während Parks und Altstadt das ganze Jahr über geöffnet bleiben.`],
    sights: {
      "Catedral de San Salvador": `Eine gotische Kathedrale im Herzen der Altstadt, Heimat der von der UNESCO gelisteten vorromanischen Cámara Santa. Das Innere ist für Hunde gesperrt, aber der Platz und die umliegenden Gassen lassen sich leicht an der Leine erkunden.`,
      "Santa María del Naranco": `Ein vorromanisches Meisterwerk aus dem 9. Jahrhundert an den Hängen des Monte Naranco, neben San Miguel de Lillo. Angeleinte Hunde genießen den Hang und den Blick über die Stadt, wobei das Innere des Monuments für sie nicht zugänglich ist.`,
      "Plaza del Fontán": `Ein arkadengesäumter Platz in der Altstadt, Heimat eines lebhaften Marktes und von Terrassen gesäumt. Sie schlendern hier an der Leine zwischen den Ständen, dem seit Jahrhunderten beliebten Herzen von Oviedo.`,
      "Campo de San Francisco": `Ein großer zentraler Park mit schattigen Alleen, die grüne Lunge der Stadt, wenige Gehminuten von der Kathedrale entfernt. Angeleinte Hunde sind entlang der Wege, Brunnen und Blumenbeete willkommen.`,
      "Calle Gascona": `Der Cider-Boulevard, gesäumt von Sidrerías, in denen asturischer Cider aus großer Höhe ausgeschenkt wird. Die Terrassen sind sehr tolerant gegenüber wohlerzogenen, angeleinten Hunden, mit garantiert geselliger Atmosphäre.`,
      "Picos de Europa": `Ein spektakuläres Gebirgsmassiv, unter einer Stunde von Oviedo entfernt, mit Wanderwegen, den Seen von Covadonga und grünen Schluchten. Ein Tagesausflug, bei dem angeleinte Hunde die Bergpfade und die frische Luft genießen.`,
    },
  },
  oxford: {
    history: `Oxford heißt Hunde seit dem Mittelalter willkommen, bereits das Domesday-Buch von 1086 erwähnt das Port Meadow, die 162 Hektar große Gemeindewiese am Rand der Stadt entlang der Themse, die seither ununterbrochen beweidet und begangen wird. Die Universitätsstadt selbst wuchs um die ab dem 12. Jahrhundert gegründeten Colleges herum, und die englische Tradition von „Town and Gown", Pubs, Märkten und Geschäften, die Arbeitern wie Akademikern gleichermaßen offenstehen, hat immer auch Hunde eingeschlossen. Heute ist Oxford eine der hundefreundlichsten Kleinstädte Englands: Über 80 % der Pubs heißen Hunde im Inneren willkommen, Stadtbusse und die Oxford-Tube-Fernbusse nach London befördern sie kostenlos, und die drei großen Wiesen (Port Meadow, Christ Church Meadow, University Parks) bieten mehr als 200 Hektar Freiraum für Hunde innerhalb von 20 Gehminuten vom Carfax. Nur die College-Innenhöfe und -Gärten sowie die Gebäude der Bodleian bleiben Hunden verschlossen, ein vertretbarer Kompromiss angesichts der Fülle an Alternativen im Freien.`,
    petTips: [`Einreise nach dem Brexit: Aus der EU benötigen Sie eine gültige Tollwutimpfung (≥21 Tage alt), einen Mikrochip, eine Bandwurmbehandlung (24-120 Stunden vor der Einreise) und ein innerhalb von 10 Tagen vor der Reise ausgestelltes Tiergesundheitszeugnis, der EU-Heimtierausweis wird nicht mehr akzeptiert.`, `Alle 39 Oxford-Colleges verweigern Hunden ihre Innenhöfe und Gärten (außer Blindenhunden), einschließlich Christ Church, Magdalen, Merton, New College; Christ Church Meadow ist die eine Ausnahme.`, `Blaualgen: von Juli bis September lebensgefährliches Risiko in Themse und Cherwell; prüfen Sie vor dem Schwimmenlassen die Vorfallkarte der Environment Agency.`, `Nächtliche Tierarzt-Notfälle: Medivet 24 Hour Woodstock, +44 1993 811355, 25 Minuten nördlich des Zentrums, Oxfordshires einziges echtes 24/7-Krankenhaus.`, `Oxford Bus Company und Stagecoach: Hunde reisen kostenlos, maximal 2 pro Fahrgast und Deck, an der Leine oder mit Maulkorb nach Ermessen des Fahrers.`],
    practicalInfo: [`Oxford ist kompakt: Ein 30-minütiger Spaziergang durchquert das Zentrum, es gibt keine U-Bahn oder Straßenbahn; Busse bedienen hauptsächlich die Park-and-Ride-Plätze und Vororte.`, `Über 80 % der Oxford-Pubs heißen Hunde an der Leine im Inneren willkommen; keiner erhebt einen Aufpreis, und die meisten stellen Wassernäpfe und Kekse bereit.`, `Port Meadow wird ganzjährig von frei umherziehendem Vieh und Pferden beweidet, ein zuverlässiger Rückruf ist gemäß dem Countryside Code erforderlich, und ein wilderndes Tier kann vom Landbesitzer rechtmäßig erschossen werden.`, `XL-Bully-Gesetz (seit 2024 in Kraft): Besitzer von XL Bullies müssen sie an allen öffentlichen Orten mit Maulkorb und Leine führen und eine Ausnahmegenehmigung besitzen; Besucher ohne diese Genehmigung dürfen einen XL Bully nicht rechtmäßig nach England bringen.`, `Hundefreundliches Punting bei Cherwell Boathouse und Magdalen Bridge Boat House: Hunde fahren kostenlos an kurzer Leine mit, März-Oktober 10:00 Uhr bis Einbruch der Dunkelheit.`],
    sights: {
      "Port Meadow": `162 Hektar große uralte Gemeindewiese nördlich der Stadt, ohne Leine, mit direktem Themse-Zugang zum Schwimmen für Hunde.`,
      "Christ Church Meadow": `16 Hektar große Flussauenwiese im Besitz des Christ Church College, 2,4 km lange Runde an der Leine mit dem Postkartenblick auf Oxfords Türme.`,
      "University Parks": `37 Hektar Grasland und Wald zwischen dem Cherwell und der Parks Road, nur an der Leine; Karl II. führte hier in den 1680er-Jahren seine Hunde spazieren.`,
      "Radcliffe Square": `Oxfords meistfotografierter Kopfsteinpflasterplatz mit der Radcliffe Camera, rund um die Uhr für angeleinte Hunde geöffnet; das Innere ist für Besucher gesperrt.`,
      "Magdalen Bridge": `Brücke über den Cherwell, von der die Stocherkähne ablegen; Hunde fahren bei Cherwell Boathouse oder Magdalen Bridge Boat House kostenlos an kurzer Leine mit.`,
      "Oxford Castle": `Sächsischer Burghügel und viktorianisches Gefängnis, dessen Außenhof frei zugänglich und hundefreundlich ist; die Gefängnisführung im Inneren ist für Hunde gesperrt.`,
    },
  },
  padstow: {
    history: `Padstow entwickelte sich als Fischerei- und Handelshafen am geschützten Camel-Ästuar, einem der wenigen sicheren Häfen an Cornwalls rauer Nordküste, und seine alte Stadt mit engen Gassen windet sich noch immer um den Arbeitskai. Die Eisenbahn erreichte den Ort 1899 und wurde in den 1960er-Jahren stillgelegt, und dieses ehemalige Gleisbett ist heute der Camel Trail, eine flache Wander- und Radroute entlang des Ästuars. Heute ist Padstow vor allem für seine Meeresfrüchte bekannt und als entspannte Basis für einen Hundeurlaub. Für einen Hund ist es eine der einfachsten Städte Cornwalls: Hafen, Pubs, Camel Trail und Küstenpfad sind alle hundefreundlich, und Harbour Cove, Hawker's Cove und Daymer Bay bleiben ganzjährig für Hunde geöffnet. Zu beachten sind die sommerlichen Strandverbote in Trevone und St George's Cove, die schnellen Ästuar-Gezeiten sowie für EU-Besucher das seit dem Brexit erforderliche britische Tiergesundheitszeugnis.`,
    petTips: [`Harbour Cove (Tregirls), Hawker's Cove und Daymer Bay bleiben ganzjährig hundefreundlich, sodass ein Hund selbst im Hochsommer immer einen Strand hat.`, `Sommerliche Strandverbote: Trevone verbietet Hunde vom 15. Mai bis 30. September, 10 bis 18 Uhr; St George's Cove vom 1. Juli bis 31. August, 10 bis 18 Uhr; das Cornwall Council verhängt Bußgelder von 100 Pfund. Die benachbarten Strände Rock Beach und Polzeath haben eigene, strengere Verbote.`, `Padstow hat keinen Bahnhof: Hunde reisen kostenlos mit National Rail (bis zu zwei pro Fahrgast, an der Leine) nach Bodmin Parkway, dann mit dem Go-Cornwall-Bus 57 nach Padstow.`, `Führen Sie Hunde auf dem Camel Trail an der Leine, da es sich um einen gemeinsam genutzten Radweg handelt, und achten Sie auf die schnelle Flut im Camel-Ästuar, die weite Sandflächen rasch bedeckt.`, `Die nächstgelegenen Tierärzte sind Penmellyn in St Merryn (+44 1841 520647) und Nute Veterinary Centre in Wadebridge (+44 1208 813258); Notfälle außerhalb der Öffnungszeiten gehen an MiNightVet in Newquay. Allgemeiner Notruf 999 oder 112.`],
    practicalInfo: [`Einreise nach Großbritannien nach dem Brexit: Großbritannien akzeptiert den EU-Heimtierausweis nicht; Hunde benötigen ein britisches Tiergesundheitszeugnis (innerhalb von 10 Tagen ausgestellt), einen Mikrochip, eine Tollwutimpfung und eine Bandwurmbehandlung 24 bis 120 Stunden vor der Ankunft.`, `Anreise: Padstow hat keinen Bahnhof, nehmen Sie also einen Zug nach Bodmin Parkway und dann den Go-Cornwall-Bus 57 über Wadebridge; der Flughafen Newquay (NQY) ist der nächstgelegene Flughafen, etwa 19 km entfernt.`, `Fortbewegung: Die Stadt ist winzig und gut zu Fuß erkundbar; die hundefreundliche Black-Tor-Fähre setzt nach Rock zu den Ästuar-Stränden über, und Parkplätze sind im Sommer schnell belegt.`, `Wetter: mildes ozeanisches Klima, milde Winter (9-10 °C) mit seltenem Frost, warme, aber nicht heiße Sommer (18 °C) und eine oft windige Küste. Frühling und Herbst sind ideal.`, `Nützliche Nummern: allgemeiner Notruf 999 oder 112; Tagestierarzt Penmellyn St Merryn +44 1841 520647; Nute Veterinary Centre Wadebridge +44 1208 813258.`],
    sights: {
      "Padstow Harbour": `Der Arbeitsfischereihafen im Herzen der Stadt, umgeben von hundefreundlichen Pubs und Cafés. Im Freien und ganzjährig hundefreundlich, Ausgangspunkt für den Camel Trail und den Küstenpfad.`,
      "Harbour Cove (Tregirls Beach)": `Ein weiter, geschützter Bogen aus goldenem Sand am Camel-Ästuar direkt nördlich der Stadt. Der wichtigste ganzjährige Hundestrand; Vorsicht vor der schnell einsetzenden Flut, die den Sand rasch bedeckt.`,
      "The Camel Trail": `Eine stillgelegte Eisenbahnstrecke, die zu einem flachen, autofreien Weg entlang des Ästuars von Padstow nach Wadebridge und darüber hinaus wurde. Einer der einfachsten Hundespaziergänge Cornwalls; Hunde an der Leine unter den Radfahrern.`,
      "Black Tor Ferry to Rock": `Die kleine Passagierfähre über das Camel-Ästuar nach Rock, eine kurze, malerische Fahrt. Hunde sind gegen einen kleinen Aufpreis an Bord willkommen; sie setzt Sie nahe den Hundestränden von Rock und Daymer Bay ab.`,
      "South West Coast Path to Stepper Point": `Klippenwanderung ab dem Hafen, vorbei an Harbour Cove zum Seezeichenturm bei Stepper Point. Ganzjährig für Hunde geöffnet; an der Leine in der Nähe von Klippenkanten und Weidevieh.`,
      "Daymer Bay": `Eine große, ruhige Sandfläche, von den Dünen von St Enodoc auf der Rock-Seite des Ästuars gesäumt. Ganzjährig hundefreundlich, anders als der benachbarte Rock Beach; schnell mit der Fähre erreichbar.`,
    },
  },
  padua: {
    history: `Padua, eine der ältesten Universitätsstädte Europas (gegründet 1222), pflegt seit Jahrhunderten eine besondere Beziehung zu Tieren: Hier soll der heiligen Franziskanerlegende zufolge der heilige Antonius zu den Fischen gepredigt haben, und hier lehrte Galileo 18 Jahre lang, bevor er nach Florenz ging. Die 2021 von der UNESCO zum Weltkulturerbe erklärte historische Altstadt Venetiens mit ihren Fresken aus dem 14. Jahrhundert (insbesondere Giottos Scrovegni-Kapelle) ist um drei aneinandergrenzende Plätze herum gebaut, Erbe, Frutta und Signori, sowie um die berühmte Prato della Valle, mit 88.620 m² einer der größten Plätze Europas. Heute ist Padua eine der ruhigsten haustierfreundlichen Basen im Nordosten Italiens: weniger überlaufen als Venedig oder Verona, gesegnet mit über 25 km Arkadengängen, die Hunde und Besitzer sowohl vor Winterregen als auch vor Sommerhitze schützen, und in 25 Minuten mit dem Regionalzug mit Venedig verbunden (5 € Pauschalpreis für angeleinte, maulkorbtragende Hunde). Offizielle Hundeauslaufplätze (aree cani) in fast jedem Stadtteil, das tiermedizinische Universitätsklinikum OVUD in Legnaro und eine lebendige Terrassen-Aperitivo-Kultur runden das Bild einer für hundetragende Besucher gebauten Stadt ab.`,
    petTips: [`Trenitalia-Regionalzug-Hundetarif: 5 € Pauschale für mittelgroße/große Hunde an Leine mit Maulkorb (Kauf am Automaten VOR dem Einsteigen, +5 € Aufschlag im Zug); kleine Hunde in Transportboxen reisen kostenlos.`, `Offizieller Hundeauslaufplatz (area cani) in fast jedem Stadtteil: Parco Iris (Mandria), Parco Europa (Arcella), Parco Milcovich (Stanga), alle eingezäunt.`, `24/7-Tierarzt-Notfallreferenz: Ospedale Veterinario Universitario (OVUD), Legnaro, +39 049 827 2500; das italienische Recht schreibt einen Anruf vor der Ankunft vor.`, `Scrovegni-Kapelle, Eremitani-Museen, Innenraum der Basilika des heiligen Antonius, Orto Botanico: Hunde verboten (außer Assistenzhunde); planen Sie einen Petsitter oder wechseln Sie sich beim Besuch ab.`, `Vipern (Vipera aspis) auf südexponierten Felspfaden in den Euganeischen Hügeln (April-Oktober): Halten Sie Hunde in der Nähe von Steinmauern an kurzer Leine und vermeiden Sie das freie Erkunden von Geröllfeldern.`],
    practicalInfo: [`Padua ist kompakt: 25 Gehminuten von der Prato della Valle zur Scrovegni-Kapelle über die drei zentralen Plätze, mit für Hunde durchweg zugänglichem flachem Gelände.`, `Eine einzige Straßenbahnlinie (SIR1, 10,5 km, Stazione FS – Pontevigodarzere): angeleinte, maulkorbtragende Hunde zugelassen, ein großer Hund pro Fahrgast; kleine Hunde in Transportboxen reisen kostenlos.`, `Über 25 km Arkadengänge in der Altstadt, ein wertvoller Vorteil gegen den Winternebel (November-Januar) und den feuchtschwülen Sommer (Juni-August, 32-35 °C bei über 80 % Luftfeuchtigkeit).`, `Trenitalia-Regionalzüge: Venedig 25 Min., Verona 40 Min., Vicenza 15 Min., Bologna 60 Min.; 5 € Pauschale für mittelgroße/große Hunde, kostenlos in Transportboxen.`, `Euganeische Hügel (Regionalpark, 20-30 km südlich): über 150 km Wanderwege für angeleinte Hunde geöffnet, hundefreundliche Agriturismi; die Thermalbäder von Abano und Montegrotto schließen Hunde von den Spa-Innenräumen aus.`],
    sights: {
      "Prato della Valle": `88.620 m² großer elliptischer Platz, einer der größten Europas, mit einem von 78 Statuen gesäumten Kanal und einer flachen 1,2 km langen Runde, ideal für Spaziergänge an der Leine.`,
      "Piazza delle Erbe": `Mittelalterlicher Marktplatz mit täglichem Obst- und Gemüsemarkt und abendlichen Aperitivo-Terrassen; angeleinte Hunde streifen frei unter den Arkaden umher.`,
      "Basilica di Sant'Antonio": `Weiter Platz rund um die Basilika (Inneres für Hunde gesperrt) mit Donatellos Reiterstatue des Gattamelata; Außenplatz und äußere Kreuzgänge für angeleinte Hunde geöffnet.`,
      "Parco Iris": `Offizieller eingezäunter Hundeauslaufplatz (area cani) im Süden Paduas, einer der größten der Stadt, morgens von den Bewohnern des Viertels rege genutzt.`,
      "Parco Treves de' Bonfili": `Landschaftsgarten von Giuseppe Jappelli aus dem 19. Jahrhundert hinter den Eremitani-Museen; angeleinte Hunde willkommen auf gewundenen Pfaden und an Zierteichen.`,
      "Bacchiglione Canal Loop": `Flache, 4 km lange Runde entlang der Kanäle, die die Altstadt umgeben, durchgehend schattig; ideal für einen kühlen Morgenspaziergang.`,
    },
  },
  palamos: {
    history: `Palamós ist ein lebendiger Fischerhafen an der Costa Brava in der Provinz Girona, berühmt für seine roten Garnelen, die gefeierten gambes de Palamós, um die sich Küchen in ganz Katalonien reißen. Die abendliche Auktion, wenn die Trawler einlaufen, bleibt ein beliebtes Schauspiel neben dem Arbeitshafen, und das Fischereimuseum erzählt diese maritime Geschichte. Hinter dem Hafen steigt die Altstadt den Hügel zur Kirche Santa Maria hinauf, während die Küste ihre Buchten entfaltet: La Fosca mit seiner Festungsruine, der wilde, unerschlossene Strand von Castell und der Camí de Ronda, der die Buchten hoch über dem Meer verbindet. Dieser Küstenpfad, ganzjährig an der Leine begehbar, ist der wahre Schatz für Hundebesitzer. Das Mittelmeerklima bringt heiße Sommer und saisonale Strandverbote mit sich, doch die Nebensaison bietet ideale Küstenwanderungen, und die benachbarte Costa Brava, von Calella de Palafrugell bis Cadaqués, ist als Tagesausflug erreichbar.`,
    petTips: [`Sommerliche Strandverbote: Hunde sind von etwa Mitte Juni bis Mitte September an La Fosca, Castell und den Stadtstränden verboten; außerhalb der Saison kehrt der Zugang an der Leine zurück, und der Camí de Ronda bleibt ganzjährig geöffnet.`, `Mediterrane Sommerhitze: Gehen Sie früh morgens oder abends spazieren, da Sand und Fels mittags die Pfotenballen verbrennen, und führen Sie stets Wasser mit.`, `Der Camí de Ronda zwischen den Buchten ist der herausragende Hundespaziergang, doch Schatten ist rar: Meiden Sie die heißesten Stunden und achten Sie auf Anzeichen eines Hitzschlags.`, `Die Kais des Fischereihafens können an der Leine begangen werden, und die abendliche Auktion ist einen Blick wert; das Innere des Fischereimuseums akzeptiert keine Hunde.`, `Einheitliche Notrufnummer 112; EU-Heimtierausweis und aktuelle Tollwutimpfung sind im Hotel erforderlich, und suchen Sie sich bei Ankunft eine diensthabende Tierklinik.`],
    practicalInfo: [`EU-Heimtierausweis und aktuelle Tollwutimpfung sind beim Check-in in haustierfreundlichen Hotels erforderlich.`, `Leinenpflicht und Kotaufsammlung unter Bußgeldandrohung durchgesetzt; als PPP gelistete Rassen müssen Leine und Maulkorb tragen, und die Strände setzen sommerliche Hundeverbote durch.`, `Mittelmeerklima: heiße, trockene Sommer (achten Sie auf Pfotenballen und Hitzschlag), mit einer milden Nebensaison, ideal für Küstenwanderungen.`, `Kein Zug nach Palamós; Moventis-Fernbusse verbinden Girona, Barcelona und die Costa-Brava-Dörfer (Calella de Palafrugell, Cadaqués), Hunde gemäß den Regeln des Betreibers, mit dem Flughafen Girona etwa 50 km entfernt.`, `Europäische Notrufnummer 112; der Camí de Ronda bietet einen ganzjährig geöffneten Küstenspaziergang an der Leine zwischen den Buchten.`],
    sights: {
      "Port de Palamós": `Ein Arbeitsfischereihafen, an dem Sie die abendliche Auktion und die einlaufenden Trawler beobachten können. Kais und Hafenterrassen werden an der Leine begangen, eine authentische maritime Szene, weit entfernt von den Freizeitmarinas.`,
      "Museu de la Pesca": `Ein am Kai gelegenes Fischereimuseum, das der Tradition der gambes de Palamós und den Berufen des Meeres gewidmet ist. Das Innere akzeptiert keine Hunde, aber die Hafenesplanade bietet einen angenehmen Spaziergang an der Leine.`,
      "Camí de Ronda": `Ein Küstenpfad, der die Buchten hoch über dem Meer verbindet, ganzjährig an der Leine begehbar. Es ist der schönste Spaziergang mit Hund in Palamós, zwischen Kiefern, Felsen und türkisfarbenem Wasser; Schatten ist rar, meiden Sie also die Mittagshitze.`,
      "Platja de la Fosca": `Ein Familienstrand unter den Ruinen der Festung Sant Esteve de Mar, mit ruhigem, flachem Wasser. Im Sommer (etwa Mitte Juni bis Mitte September) sind Hunde verboten, erhalten außerhalb der Saison jedoch wieder Zugang an der Leine.`,
      "Platja de Castell": `Ein wilder Strand, durch einen Bürgerentscheid vor der Bebauung gerettet, gesäumt von Kiefern und einer iberischen Fundstätte. Im Hochsommer für Hunde gesperrt, genießt man ihn am besten im Frühling und Herbst an der Leine, zu Fuß vom Parkplatz aus erreichbar.`,
      "Cap de Planes": `Ein felsiges Kap und eine Kette von Buchten zwischen La Fosca und den nördlichen Stränden, durchzogen vom Camí de Ronda. Aussichtspunkte über das Mittelmeer und ruhige kleine Buchten, an der Leine außerhalb der heißen Stunden zu begehen.`,
    },
  },
  palma: {
    history: `Palma de Mallorca pflegt eine lange und entspannte Beziehung zu Haustieren. Als Hauptstadt der Balearen seit dem 14. Jahrhundert war die Stadt schon immer eine weltoffene Handelsstadt für Reisende aus dem ganzen Mittelmeerraum, und deren Tiere. Heute ist Palma eines der wirklich haustierfreundlichsten Reiseziele Spaniens. Die balearischen Vorschriften sind klar und werden durchgesetzt: Leinenpflicht überall, seit 2023 Tierhaftpflichtversicherung Pflicht und offizielle, ganzjährig geöffnete Hundestrände wie Es Carnatge. Der alte Hafen und das Viertel Santa Catalina sind zum gesellschaftlichen Herz der Stadt für Hundebesitzer geworden, mit Terrassen, die ausdrücklich mit Hunde-willkommen-Schildern werben und deren Personal einen Wassernapf bringt, bevor man danach fragt.`,
    petTips: [`Die Tierhaftpflichtversicherung ist auf den Balearen seit September 2023 für Hunde Pflicht, prüfen Sie, ob Ihre Police Spanien abdeckt, bevor Sie reisen.`, `Leinenpflicht auf allen öffentlichen Straßen und in Parks, außer in ausgewiesenen Pipican-Zonen; Bußgelder beginnen bei 150 €.`, `Hunde sind vom 1. April bis 31. Oktober an den meisten Stränden verboten; Es Carnatge und Cala Gamba sind die gesetzlichen ganzjährigen Ausnahmen bei Palma.`, `Intensive Hitze im Juli-August (bis zu 32 °C): Gehen Sie mit Hunden vor 9 Uhr oder nach 20 Uhr spazieren, um einen Hitzschlag zu vermeiden.`, `EMT-Bus: Hundeticket 0,30 € auf allen Linien seit 2024; Hunde müssen einen Maulkorb tragen und angeleint sein.`],
    practicalInfo: [`Notfalltierarzt: Clínica Veterinaria San Fernando, Avda. Sant Ferran 49, 971 730 546 (Notfall außerhalb der Öffnungszeiten: 601 200 320).`, `24-Stunden-Intensivtierklinik: CalviaVet, Gran Vía Puig des Castellet 1, Santa Ponsa, 971 695 108.`, `Transport: EMT-Bus alle Linien, Hund mit Maulkorb + Leine + 0,30 €-Ticket. SFM-Zug: Hund in Transportbox kostenlos.`, `Offizieller ganzjähriger Hundestrand: Es Carnatge (zwischen Palma und Can Pastilla). Cala Gamba: eine weitere ganzjährige Option.`, `Flughafen Palma (PMI) 10 km vom Zentrum entfernt. Taxi vom Flughafen: etwa 20-25 €, 15-25 Minuten.`],
    sights: {
      "La Seu": `Palmas gotische Kathedrale erhebt sich direkt aus der Stadtmauer am Meer, das Äußere und der darunterliegende Parc de la Mar sind hundefreundlich. Perfekt für einen Spaziergang bei Sonnenuntergang mit außergewöhnlichem Ausblick.`,
      "Castell de Bellver": `Europas einzige kreisrunde mittelalterliche Burg, auf einem bewaldeten Hügel mit Panoramablick über die Bucht. Das Gelände und der umliegende Kiefernpark heißen angeleinte Hunde willkommen.`,
      "Santa Catalina": `Palmas lebendigstes Viertel, voller Tapas-Bars, Märkte und hunde-willkommener Terrassen. Der Markt von Santa Catalina ist bei einem Morgenspaziergang mit Hund unverzichtbar.`,
      "Passeig des Born": `Palmas eleganter Hauptboulevard mit breiten, schattigen Gehwegen und hunde-willkommenen Terrassencafés. Perfekt für einen Abendspaziergang, wenn Einheimische ihre eigenen Hunde ausführen.`,
      "Es Carnatge": `Palmas offizieller ganzjähriger Hundestrand, ohne Leine, der einzige stadtnahe Strand, der im Sommer legal ist. Wildes Gelände mit kristallklarem, türkisfarbenem Wasser.`,
      "Portixol": `Palmas schickes Uferviertel, mit hundefreundlichen Restaurants am Meer und einem angenehmen Spaziergang entlang des Fischereihafens. Einer der besten Orte für ein Abendessen mit Hund mit Blick auf die Bucht.`,
    },
  },
  palermo: {
    history: `Palermo, die Hauptstadt Siziliens (~660.000 Einwohner), wurde im 8. Jahrhundert v. Chr. von den Phöniziern gegründet, bevor es unter arabischer (831-1072) und normannischer (1072-1194) Herrschaft zu einer der bevölkerungsreichsten und wohlhabendsten Städte Europas wurde. Diese einzigartige arabisch-normannische Verschmelzung hinterließ der Stadt ihre Kathedrale (1185, UNESCO 2015), die mit Mosaiken verkleidete Cappella Palatina (1140), den normannischen Königspalast und den Palazzo della Zisa. Der sizilianische Barock des Quattro Canti (1620) und der malerische, von Renato Guttuso gemalte Vucciria-Markt vervollständigen das Bild. Für Reisende mit Hund ist dies die hundefreundlichste größere Stadt Süditaliens mit der besten Infrastruktur: der ausgeschilderte Bau-Beach von Mondello, 11 km entfernt, der 400 Hektar große Parco della Favorita am Fuß des Monte Pellegrino und eine ungewöhnlich entspannte sizilianische Tavernenkultur. Einzige Einschränkungen: Sommerhitze (28-32 °C im Juli-August), Scirocco-Wind und chaotischer Verkehr im Zentrum.`,
    petTips: [`Die sizilianische Tavernenkultur heißt Hunde auf Terrassen massiv willkommen, seit jeher üblich.`, `Der Bau-Beach von Mondello ist ein Muss, 11 km nördlich, Buslinie 806 (20 Min., kleine Hunde in Transportboxen kostenlos).`, `Juli-August meiden: Scirocco + 28-32 °C + Kopfsteinpflaster bei 60 °C zur Mittagszeit. Mai-Juni oder September-Oktober bevorzugen.`, `Sizilianische archäologische Stätten (Cappella Palatina, Zisa, Katakomben) verbieten Haustiere, buchen Sie für 1-2 Std. einen Pawshake-Sitter.`, `Nachtfähre GNV/Grimaldi von Neapel: haustierfreundliche Kabinen mit ca. 30 € Aufpreis, im Sommer frühzeitig buchen.`],
    practicalInfo: [`24/7-Notfalltierarzt: Clinica Veterinaria Borgo Nuovo, Via Castellana 124, +39 091 224 3434`, `Zentrale Tagesklinik: Studio Veterinario Vucciria, Via Maqueda 250, +39 091 332 200`, `Flughafen Palermo PMO (Falcone-Borsellino) 32 km westlich, Trinacria Express 45 Min., Taxi zum Festpreis 50 €.`, `Nachtfähre Neapel-Palermo: 10 Std., haustierfreundliche Kabinen mit ca. 30 € Aufpreis.`],
    sights: {
      "Quattro Canti": `Barocke oktogonale Kreuzung (1620), an der Via Maqueda auf Corso Vittorio Emanuele trifft, Palermos symbolisches Zentrum. Angeleinte Hunde rund um die Uhr willkommen.`,
      "Mondello Bau-Beach": `Offizieller Hundestrand, 11 km nördlich, ausgeschildert am westlichen Ende (Valdesi). Feiner Sand, kristallklares Wasser, ganzjährig geöffnet. Buslinie 806 vom Politeama in 20 Minuten.`,
      "Parco della Favorita": `Siziliens größter Stadtpark, 400 Hektar am Fuß des Monte Pellegrino. Königliches Reservat, 1799 von Ferdinand III. angelegt, heute ein Gewirr aus Wegen, Zitrushainen und Pinienwäldern. Der beliebteste Hundespaziergang der Palermitaner.`,
      "Cathedral of Palermo": `1185 begonnene arabisch-normannische UNESCO-Kathedrale, mit gotischen, Renaissance- und klassizistischen Ergänzungen überlagert. Hunde im Inneren nicht erlaubt (außer Assistenzhunde); Außenplatz und normannische Mauern zugänglich.`,
      "Mercato di Ballarò": `Palermos ältester und lebendigster Straßenmarkt, aus der arabischen Ära des 10. Jahrhunderts stammend. Gemüse-, Fisch- und Street-Food-Stände, traditionelle 'abbanniate'-Verkaufsrufe. Mit kurz angeleintem Hund begehbar.`,
      "Foro Italico": `2 km autofreie Uferpromenade vom Hafen bis zum Viertel Kalsa. Rasenstreifen, Palmen, Meeresbrise. Palermos sommerabendlicher Hunde-Treffpunkt.`,
    },
  },
  pamplona: {
    history: `Pamplona (baskisch Iruña), Hauptstadt Navarras (~205.000 Einwohner), wurde 75 v. Chr. von den Römern als Pompaelo gegründet. Als Hauptstadt des mittelalterlichen Königreichs Navarra (824-1620) vor dessen Eingliederung in Kastilien bewahrt die Stadt eine historische Altstadt, die vollständig von den im 16. Jahrhundert von Philipp II. errichteten Mauern umgeben ist. Hemingway machte die Stadt mit „Fiesta" (1926) weltberühmt, basierend auf seinen jährlichen Besuchen bei den San Fermines (6.-14. Juli), dem Stierlauf-Fest, bei dem er von 1923 bis 1959 im Gran Hotel La Perla wohnte. Pamplona ist zudem eine wichtige Etappe auf dem Jakobsweg auf der französischen Route. Für Reisende mit Hund ist es eine der einfachsten Städte Nordspaniens: der 28 Hektar große Zitadellenpark mit eingezäunter Freilaufzone, die 11 km lange Grünanlage am Río Arga, entspannte Pintxo-Bars auf Terrassen, milde Sommer (22 °C im Durchschnitt). Einzige Ausnahme: Meiden Sie die San Fermines mit Hund (über 1 Mio. Besucher, ständiges Feuerwerk).`,
    petTips: [`Die navarresische Pintxo-Kultur ist auf Terrassen massiv hundefreundlich, Bars und Tavernen akzeptieren Hunde standardmäßig.`, `Der 28 Hektar große Zitadellenpark im Stadtzentrum ist ein Muss, mit eingezäunter Freilaufzone im Südwesten.`, `Meiden Sie die San Fermines (6.-14. Juli) mit Hund: über 1 Mio. Besucher, jeden Abend Feuerwerk, gesperrte Straßen, konstant 80-90 dB Lärm.`, `Mildes Sommerklima (22 °C Durchschnitt im Juli-August), weit angenehmer für Hunde als Madrid oder Barcelona.`, `Der französische Jakobsweg führt durch Pamplona, Pilger mit Hund übernachten hier häufig 1-2 Nächte; hundefreundliche Pilgerherbergen gibt es.`],
    practicalInfo: [`24/7-Notfalltierarzt: Hospital Veterinario UCV Pamplona, Polígono Mutilva Baja, +34 948 23 03 03`, `Zentrale Tagesklinik: Clínica Veterinaria Iruña Centro, Calle Olite 7, +34 948 22 87 90`, `Renfe Alvia ab Madrid Chamartín: 3 Std. direkt; neue AVE-Strecke Madrid-Pamplona (2024) in 1 Std. 45.`, `Flughafen Pamplona PNA 7 km südlich, Buslinie 16 alle 30 Minuten (1,30 €), Taxi zum Festpreis 15 €. Bilbao BIO (1,5 Std. mit dem Bus) bietet bessere internationale Anbindung.`],
    sights: {
      "Parque de la Ciudadela": `Sternförmige Renaissance-Zitadelle, 1571 von Philipp II. erbaut, Spaniens am besten erhaltene. 28 Hektar großer Park mit freiem Eintritt und eingezäunter Freilaufzone im Südwesten.`,
      "Plaza del Castillo & Café Iruña": `Pamplonas zentraler Platz, beherrscht vom Belle-Époque-Café Iruña (1888), in dem Hemingway schrieb. Ikonische Terrasse, angeleinte Hunde auf dem Platz und dem Außencafé willkommen.`,
      "Río Arga Greenway": `11 km autofreie Grünanlage entlang des Flusses Arga rund um die Altstadt. Flach, schattig, mit drei mittelalterlichen Brücken. Der tägliche Hundespaziergang der Pamploneser.`,
      "Cathedral of Pamplona": `Spätgotische Kathedrale (14.-15. Jh.) mit klassizistischer Fassade (1799). Hunde im Inneren nicht erlaubt (außer Assistenzhunde), doch die umliegende Plaza Santa María ist zugänglich.`,
      "Calle Estafeta (San Fermines bull-run street)": `500 m lange Fußgängerstraße, durch die vom 7.-14. Juli jeden Morgen der Stierlauf (Encierro) führt. Außerhalb des Festes ist sie Pamplonas dichteste Pintxo-Straße mit über 20 Bars auf 400 m. Angeleinte Hunde ganzjährig willkommen, außer während der San Fermines.`,
      "Yamaguchi Japanese Park": `Japanisch inspirierter Park (1997) in Partnerschaft mit der Partnerstadt Yamaguchi (Japan). 8,5 Hektar mit Kirschbäumen, Koiteich, Aussichtshügel. Angeleinte Hunde willkommen.`,
    },
  },
  paphos: {
    history: `Paphos an der Südwestküste Zyperns vereint ein Seebad mit einer zum UNESCO-Weltkulturerbe zählenden Archäologie. Der Archäologische Park von Kato Paphos beherbergt außergewöhnliche römische Mosaiken, während die Königsgräber ihre in den Fels gehauene Nekropole mit Blick auf das Meer entfalten. Der von einer kleinen mittelalterlichen Burg überwachte Hafen öffnet sich zu einer lebhaften Promenade, und die Uferpromenade von Kato Paphos reiht Tavernen und Terrassen aneinander. Weiter draußen verortet die Legende die Geburt der Aphrodite im Schaum bei Petra tou Romiou, dem Felsen der Göttin. Im Nordwesten bieten die wilde Halbinsel Akamas und die Lara Bay, wo Meeresschildkröten nisten, unberührte Landschaften. Das Klima ist trocken-mediterran: Die Sommer übersteigen oft 35 °C, und Sand und Stein verbrennen die Füße, doch Herbst und Frühling sind mild und perfekt für lange Küstenspaziergänge an der Leine. Auf Zypern herrscht Linksverkehr, ein Detail, das man mit Hund im Auto im Hinterkopf behalten sollte.`,
    petTips: [`Nur ausgewiesene Hundestrände: Im Bezirk Paphos erlauben nur Acheleia (nahe dem Flughafen) und Pitili Hunde; anderswo, an einem bewachten Strand, beträgt das Bußgeld 85 Euro.`, `Extreme Sommerhitze: Die Sommer übersteigen oft 35 °C, und Sand und Stein verbrennen mittags die Pfotenballen, gehen Sie also früh morgens oder abends spazieren und führen Sie stets Wasser mit.`, `Auf Zypern herrscht Linksverkehr: Achten Sie mit Ihrem Hund beim Überqueren der Straße und beim Öffnen der Autotüren auf der Verkehrsseite.`, `Die großen archäologischen Stätten (Archäologischer Park Kato Paphos, Königsgräber) lassen im Inneren ihrer Anlagen keine Hunde zu; heben Sie sich die Hafenpromenade und die Küstenpfade von Akamas für Ihren Begleiter auf.`, `Einheitliche Notrufnummer 112; EU-Heimtierausweis und aktuelle Tollwutimpfung sind im Hotel erforderlich, und suchen Sie sich bei Ankunft eine diensthabende Tierklinik.`],
    practicalInfo: [`EU-Heimtierausweis und aktuelle Tollwutimpfung sind beim Check-in in haustierfreundlichen Hotels erforderlich (Zypern ist EU-Mitglied).`, `Leine und Kotaufsammlung werden erwartet; das Baden mit Hund ist auf die ausgewiesenen Hundestrände des Bezirks beschränkt (Acheleia, Pitili), mit 85 Euro Bußgeld an einem bewachten Strand.`, `Trocken-mediterranes Klima: sehr heiße Sommer (oft über 35 °C, achten Sie auf Pfotenballen und Hitzschlag), mit mildem Frühling und Herbst, ideal für Küstenspaziergänge.`, `Auf Zypern herrscht Linksverkehr; es gibt keine Züge auf der Insel, der internationale Flughafen Paphos liegt etwa 15 km entfernt, und Busse bedienen Stadt und Küste.`, `Europäische Notrufnummer 112; die Hafenpromenade und die Akamas-Pfade bieten schöne Spaziergänge an der Leine außerhalb der heißen Stunden.`],
    sights: {
      "Kato Paphos Harbour & Castle": `Der historische Hafen, überwacht von seiner kleinen mittelalterlichen Festung, säumt eine lebhafte Promenade mit Tavernen und Fischerbooten. Kais und Uferpromenade bieten einen angenehmen Spaziergang an der Leine, wobei das Innere der Burg für Hunde weniger geeignet ist.`,
      "Kato Paphos Archaeological Park": `Eine UNESCO-gelistete Stätte, berühmt für die römischen Mosaiken der Häuser des Dionysos und Theseus. Hunde sind im Inneren der archäologischen Anlage nicht zugelassen, planen Sie also die nahegelegene Hafenpromenade für Ihren Begleiter.`,
      "Tombs of the Kings": `Eine ausgedehnte hellenistische und römische, in den Fels gehauene Nekropole mit Blick auf das Meer, Teil der UNESCO-Liste. Hunde sind im Inneren der eingezäunten Anlage nicht erlaubt, aber der daran entlangführende Küstenpfad kann außerhalb der heißen Stunden an der Leine begangen werden.`,
      "Akamas Peninsula & Lara Bay": `Eine wilde Halbinsel mit unberührten Pfaden und Buchten, wo in der Lara Bay Meeresschildkröten nisten. Halten Sie Hunde an der Leine und weit entfernt von Nistzonen zur Saison (Sommer), und führen Sie reichlich Wasser mit, da Schatten rar ist.`,
      "Petra tou Romiou": `Der Felsen der Aphrodite, an dem die Legende die Geburt der Göttin verortet, erhebt sich über einem von Wellen umspülten Kieselstrand. Aussichtspunkt und Ufer können an der Leine begangen werden, doch dies ist kein ausgewiesener Hundestrand, das Baden mit Hund sollte hier daher besser vermieden werden.`,
      "Coral Bay": `Ein großer, sehr belebter Sandstrand mit goldenem Sand nördlich von Kato Paphos, beliebt bei Familien. Hunde sind hier wie an allen bewachten Stränden verboten, weichen Sie also auf die ausgewiesenen Hundestrände des Bezirks aus (Acheleia, Pitili).`,
    },
  },
  paris: {
    history: `Paris ist eine Stadt der Hunde, und die Pariser wissen das schon lange. In der Hauptstadt leben über 500.000 Hunde, etwa einer auf acht Einwohner. Diese langjährige Beziehung zwischen Paris und seinen Tieren reicht bis in die Café-Kultur des 18. Jahrhunderts zurück, als Hunde neben ihren Besitzern auf den Bänken lagen. Obwohl Paris die meistbesuchte Stadt der Welt ist, bewahrt sie diese Vertrautheit: Hunde sind in den meisten Brasserien, Geschäften und ausgewiesenen Freilaufzonen in Gärten willkommen. Der Bois de Boulogne (846 ha) und der Bois de Vincennes (995 ha) bieten zwei riesige grüne Lungen, jeden Morgen belebt von Hunden ohne Leine.`,
    petTips: [`Hunde sind in der Pariser Metro erlaubt, wenn sie in einer Tasche oder Transportbox getragen werden. Größere Hunde können mit einem Kinderticket reisen, angeleint und mit Maulkorb.`, `Die meisten Brasserien und Bistros akzeptieren Hunde auf den Terrassen und oft auch drinnen, fragen Sie einfach an der Tür.`, `Achten Sie auf die Gehwege: Paris bleibt eine Stadt mit uneinheitlicher Straßensauberkeit. Halten Sie Ihren Hund in Einkaufsvierteln an kurzer Leine.`, `Wasser wird auf vielen Terrassen kostenlos angeboten, fragen Sie nach einem Napf für Ihren Hund.`, `Die Tuileriengärten, der Jardin du Luxembourg und der Palais-Royal-Garten sind für Hunde gesperrt. Planen Sie in diesen Gegenden alternative Routen.`],
    practicalInfo: [`24/7-Notfalltierarzt: Clinique Vétérinaire Frégis, 43 avenue Aristide Briand, Arcueil, +33 1 46 15 20 00`, `Tierapotheken gibt es in jedem Arrondissement, besonders im Marais und in Montparnasse`, `Eurostar ab London: Hunde in Taschen oder Transportboxen werden akzeptiert. Große Hunde sind im Eurostar nicht zugelassen, erwägen Sie stattdessen Fähre plus Zug.`, `Flughafen Charles de Gaulle: EU-Haustiere mit gültigem Heimtierausweis können ohne Quarantäne einreisen.`],
    sights: {
      "Bois de Boulogne": `846 Hektar Wald am westlichen Stadtrand von Paris. In vielen Bereichen dürfen Hunde morgens frei laufen. Der Lac Inférieur und der Pré Catelan sind unverzichtbare Stationen für einen langen Morgenspaziergang.`,
      "Le Marais": `Paris' hundefreundlichstes Viertel. Unabhängige Geschäfte, Caféterrassen und Tierapotheken in jeder Straße. Die Place des Vosges ist beeindruckend, aber Hunde müssen im Inneren angeleint bleiben.`,
      "Jardin du Luxembourg": `Einer der schönsten Gärten von Paris, doch Hunde sind im Inneren nicht erlaubt. Umrunden Sie ihn über den Boulevard Saint-Michel oder genießen Sie stattdessen die Fußgängerstraßen des Quartier Latin mit Ihrem Haustier.`,
      "Canal Saint-Martin": `Der beliebte Kanal der Pariser für einen entspannten Spaziergang. Die schattigen Kaimauern eignen sich perfekt für einen Hundespaziergang, Caféterrassen und Feinkostläden säumen die Strecke. Meiden Sie den Wochenendandrang.`,
      "Tour Eiffel & Champ-de-Mars": `Die Rasenflächen des Champ-de-Mars heißen angeleinte Hunde willkommen, mit garantiert unschlagbarem Blick auf den Eiffelturm. Der Turm selbst ist für Tiere tabu, aber die Gärten sind ein ikonischer Hundespaziergang.`,
      "Montmartre & Sacré-Cœur": `Die Kopfsteinpflastergassen von Montmartre eignen sich perfekt für einen Hundespaziergang. Die Treppen zur Sacré-Cœur sind mit Hund zugänglich, der Ausblick ist die Mühe wert. Der Square Louise Michel darunter ist ein guter Ort zum Ausruhen.`,
    },
  },
  paros: {
    history: `Paros schenkte der Welt den Lychnites, den reinsten Marmor der Antike, den Stein der Venus von Milo und des Hermes von Praxiteles, gebrochen in den unterirdischen Stollen von Marathi, die noch heute am Hang sichtbar sind. Parikia, über der antiken Stadt erbaut, bewahrt die Panagia Ekatontapiliani, die Kirche der hundert Türen, der Legende nach im 4. Jahrhundert von der heiligen Helena gegründet, sowie ein venezianisches Kastro, zusammengesetzt aus den Säulentrommeln eines archaischen Tempels. Lefkes, die Hauptstadt der Insel zur Zeit der Piraten, wacht von seinen Marmorgassen aus über das Landesinnere und ist über eine gepflasterte byzantinische Straße mit Prodromos verbunden. Naoussa, ein alter Fischerhafen, geduckt hinter seiner halb versunkenen Festung, ist zu einem der schönsten Häfen der Kykladen geworden. Als bedeutendes Drehkreuz für die Ägäis-Fähren vereint Paros Sandstrände, weiß getünchte Dörfer und Maultierpfade: eine sehr leicht mit Hund zu genießende Insel.`,
    petTips: [`Paros ist die große Fährkreuzung der Kykladen: Auf den Außendecks der Blue-Star-Schiffe sind Maulkorb und Leine Pflicht, und schnelle Katamarane akzeptieren oft nur kleine Hunde in Transportboxen, prüfen Sie dies bei der Buchung.`, `Im Juli und August dulden die ausgestatteten Strände tagsüber kaum Hunde: Zielen Sie früh morgens auf die wilden Enden von Chrysi Akti, Santa Maria oder Molos, und genießen Sie von Oktober bis Mai völlige Freiheit.`, `Vorsicht vor der Sommerhitze: Sand und die Marmorplatten von Lefkes oder Parikia verbrennen zwischen 11 und 18 Uhr die Pfoten, testen Sie mit dem Handrücken und heben Sie sich die byzantinische Straße für die kühlen Stunden auf.`, `Der Meltemi weht nachmittags an der Ostküste kräftig: Aufgewirbelter Sand reizt an der Chrysi Akti die Augen der Hunde, weichen Sie also auf die geschützte Bucht von Naoussa oder die Dörfer im Landesinneren aus.`, `In den Gassen von Naoussa und Parikia leben viele halbwilde, von Anwohnern gefütterte Katzen: Halten Sie die Leine in der Dämmerung kurz, wenn sie rund um die Tavernen zahlreich auftauchen.`],
    practicalInfo: [`Tierarztpraxen in Parikia und bei Naoussa für die routinemäßige Versorgung; für ernste Notfälle befinden sich die bestausgestatteten Kliniken auf Syros oder in Athen, per Fähre erreichbar`, `Europäische Notrufnummer: 112; der örtliche Tierschutzverein kann helfen, wenn Sie ein Streunertier finden`, `Tierbedarfsregale in den Supermärkten von Parikia und Naoussa; Zoofachgeschäfte nahe dem Hafen von Parikia`, `Blue-Star-Fähren: Hunde kostenlos auf den Außendecks, Maulkorb und Leine Pflicht, Haustierkabinen auf manchen Routen; KTEL-Inselbusse: kleine Hunde in der Transportbox`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich; verstärkter Parasitenschutz empfohlen, Zecken und Sandmücken sind von April bis Oktober auf den Kykladen aktiv`],
    sights: {
      "Parikia": `Die Hauptstadt der Insel entfaltet eine Altstadt aus weiß gekalkten Gassen, Bougainvillea und Kapellen rund um die Überreste des venezianischen Kastro, das aus antiken Säulentrommeln erbaut wurde. An der Leine, früh morgens oder bei Sonnenuntergang, ist es ein köstliches Labyrinth, und die Uferpromenade bietet eine lange, flache Strecke.`,
      "Naoussa": `Der fotogenste kleine Fischerhafen der Kykladen drängt seine bunten Kaikis gegen eine halb versunkene venezianische Festung. Angeleinte Hunde streifen gerne durch die Kais und Gassen, und viele Tavernen am Hafen akzeptieren ruhige Begleiter an den Außentischen.`,
      "Chaussée byzantine de Lefkes": `Die alte, mit Marmorplatten gepflasterte Straße verbindet Lefkes in einer Stunde sanften Abstiegs mit Prodromos, zwischen Olivenbäumen, Trockenmauern und Kapellen, mit dem Meer und Naxos als Kulisse. Es ist der schönste Spaziergang der Insel für einen angeleinten Hund; starten Sie früh, mittags ist Schatten rar.`,
      "Chrysi Akti (Golden Beach)": `Siebenhundert Meter goldener Sand an der Ostküste, vom Meltemi umweht, der ihn zu einem Weltklasse-Windsurfspot gemacht hat. Halten Sie sich im Sommer an die unerschlossenen Enden, fernab von Liegen und Segelschulen; außerhalb der Saison gehört der ganze Strand Ihnen und Ihrem Hund.`,
      "Panagia Ekatontapiliani": `Die Kirche der hundert Türen, der Überlieferung nach im 4. Jahrhundert von der heiligen Helena gegründet, ist eines der bedeutendsten frühchristlichen Heiligtümer Griechenlands. Hunde betreten weder die Kirche noch den Kreuzgang: Wechseln Sie sich beim Besuch ab, während der andere im Schatten des Vorplatzes wartet.`,
      "Kolymbithres": `In der Bucht von Naoussa formen windgeschliffene Granitfelsen eine Reihe winziger Buchten mit klarem Wasser. Außerhalb der Saison und früh morgens erkunden Hunde diese Mondlandschaft frei; im Hochsommer zielen Sie auf die Buchten am weitesten von den Liegen entfernt.`,
    },
  },
  parnu: {
    history: `1251 von den Rittern des Livländischen Ordens gegründet, wuchs Pärnu zu einem Hansehandelsposten heran, dessen Hafen Flachs und Holz durch ganz Europa verschiffte. Die Schweden befestigten die Stadt im 17. Jahrhundert: Der Wallgraben Vallikäär und das Tallinner Tor, das einzige erhaltene Stadttor aus der schwedischen Zeit im Baltikum, zeugen noch heute davon. 1838 eröffnete die erste Badeeinrichtung, und die Stadt wurde zum Seebad des Russischen Reiches, später zu Estlands offizieller Sommerhauptstadt, ein Titel, den sie bis heute trägt. Heute ziehen ihre pastellfarbenen Holzvillen, die preisgekrönte Promenade und die riesige Sandbucht Kurgäste und Festivalbesucher an. Mit Hund ist Pärnu überraschend einfach: vier offizielle Hundebadestellen, ein eingezäunter Hundepark mit Agility-Geräten nahe dem Mai-Strand und ein Tourismusamt, das eine eigene Liste hundefreundlicher Cafés und Hotels veröffentlicht.`,
    petTips: [`Der zentrale Strand verbietet Hunde in der Badesaison: Nutzen Sie stattdessen die vier offiziellen Hundebadestellen (linkes Flussufer bei der Mole, Mai, Vana-Pärnu, Raeküla).`, `Leinenpflicht überall im öffentlichen Raum; Freilauf ist nur im eingezäunten Mai-Hundepark (zwei Zonen, Agility-Geräte) und auf dem Trainingsgelände legal.`, `Während der großen Sommerfestivals empfiehlt die Stadt in dichten Menschenmengen Leine UND Maulkorb; die Konzerte am Vallikäär ziehen Zehntausende an.`, `Vom Tourismusamt als hundefreundlich gelistete Cafés (Supelsaksad, Steffani, Jahtklubi) stellen gerne einen Wassernapf bereit, fragen Sie einfach.`, `Tierärzte: Terveks, Riia mnt 109 (+372 4470023, Mo-Sa 9:00-18:00) und PetCity im Pärnu Keskus, Aida 7 (+372 4401006, täglich geöffnet); Notfälle über Nacht über die nationale Kurzwahlnummer 15222 (Tierrettung mit Sitz in Tallinn, 2 Stunden Fahrt entfernt).`],
    practicalInfo: [`Anreise: kein Personenzug nach Pärnu; Lux Express und andere Fernbusse verkehren ab Tallinn (2 Std.) und Riga (2,5 Std.). Lux Express befördert Haustiere nur in einer geschlossenen Transportbox bis 40 x 40 cm, mit ermäßigtem Haustierticket, und nur auf estnischen Inlandsstrecken.`, `Fortbewegung: flache, kompakte Stadt, alles zu Fuß oder mit dem Rad erreichbar; in Stadtbussen reisen kleine Haustiere in der Transportbox und große Hunde an kurzer Leine mit Maulkorb.`, `Klima: milde Sommer (22 °C im Juli, flache Bucht, die sich schnell erwärmt), aber gefrorene Winter um -2 °C; die Bucht kann zufrieren, wunderschön für Spaziergänge, aber schützen Sie die Pfoten vor Streusalz.`, `Tierarzt: Terveks, Riia mnt 109, +372 4470023; PetCity Pärnu Keskus, Aida 7, +372 4401006; nationale 24/7-Leitung 15222; allgemeine Notrufnummer 112.`, `EU-Reise: Ein EU-Heimtierausweis, Mikrochip und gültige Tollwutimpfung genügen für die Einreise nach Estland; Hunde müssen im öffentlichen Raum angeleint sein und der Kot muss aufgesammelt werden, andernfalls droht ein Bußgeld.`],
    sights: {
      "Rüütli tänav": `Die Fußgängerachse der Altstadt, gesäumt von pastellfarbenen Holzhäusern, barocken Kaufmannshäusern und Cafés. Ein perfekter Spaziergang an der Leine, mit Wassernäpfen auf vielen Terrassen im Sommer.`,
      "Vallikäär": `Der Wallgraben der schwedischen Bastionen aus dem 17. Jahrhundert, heute ein geschwungener Park mit Rasenflächen, Fußgängerbrücken und Estlands höchstem Brunnen. Eine klassische Leinenrunde zwischen Altstadt und Meer.`,
      "Tallinna värav": `Das Tallinner Tor aus dem 17. Jahrhundert ist das einzige erhaltene Stadttor aus der schwedischen Zeit im Baltikum. Sein gewölbter Durchgang verbindet die Altstadt mit dem Park und ist mit angeleintem Hund frei begehbar.`,
      "Rannapromenaad": `Die preisgekrönte Holzpromenade am Strand verbindet historische Badehäuser, Art-déco-Kabinen und Wellenbänke entlang der Bucht. Ganzjährig für angeleinte Hunde geöffnet, selbst wenn der zentrale Sand saisonal gesperrt ist.`,
      "Pärnu rannaniidu matkarada": `Ein 600 m langer Bohlenweg mit Aussichtsplattform durchquert die 341 Hektar große geschützte Küstenwiese, beweidet von den berühmten Stadtkühen. Hunde an kurzer Leine willkommen; im Frühling nistende Vögel.`,
      "Pärnu muul": `Die steinerne Mole an der Flussmündung bietet einen salzigen Spaziergang mit Blick auf die Bucht, und ihr linkes Ufer ist eine der vier offiziellen Hundebadestellen der Stadt. An Tagen mit rauer See meiden.`,
    },
  },
  peniche: {
    history: `Peniche war lange eine Insel: Erst im 16. Jahrhundert verbanden abdriftende Sande sie endgültig mit dem Festland und schufen diese befestigte, in den Atlantik ragende Halbinsel. Ihre Festung, zur Abwehr von Korsaren erbaut, diente unter der Salazar-Diktatur als politisches Gefängnis; die Flucht des kommunistischen Anführers Álvaro Cunhal im Jahr 1960 ist bis heute legendär. Als bedeutender Sardinenhafen lebt die Stadt noch immer vom Fischfang und der Konservenherstellung, und ihre Restaurants servieren einige der besten Fischgerichte Portugals. Seit den 2000er-Jahren ist Peniche zudem eine Weltsurfhauptstadt geworden, mit der Welle Supertubos und einer Station der Weltmeisterschaftstour. Für einen Reisenden mit Hund ist dies raue, windgepeitschte Küste: die spektakulären Klippen von Cabo Carvoeiro, die Dünen von Baleal und riesige Strände außerhalb der Saison.`,
    petTips: [`Während der Badesaison (etwa Juni bis September) sind Hunde an den bewachten portugiesischen Stränden verboten: Zielen Sie auf die Morgen- und Abendstunden oder die langen Abschnitte außerhalb der Badezonen, und genießen Sie die Strände außerhalb der Saison frei.`, `Wind und Strömungen in Peniche sind stark: Lassen Sie Ihren Hund nicht in den Supertubos-Wellen oder in der Nähe der Klippen schwimmen, die Strömungen sind gnadenlos.`, `Leinen sind an öffentlichen Orten in Portugal Pflicht, und als gefährlich eingestufte Rassen benötigen einen Maulkorb.`, `Halten Sie auf den Klippenpfaden (Cabo Carvoeiro, Papôa) die Leine kurz: Die Kanten sind stellenweise brüchig und ungesichert.`, `Packen Sie ein Handtuch und frisches Wasser ein: Salz, Sand und Gischt haften im Fell, und Brunnen sind an der Uferpromenade rar.`],
    practicalInfo: [`Tierkliniken in Peniche und der Umgebung (Caldas da Rainha, Óbidos); ernste Notfälle werden an Tierkliniken in der Region Leiria oder Lissabon überwiesen`, `Europäische Notrufnummer: 112; Ihre Unterkunft kennt den diensthabenden Tierarzt`, `Zoofachgeschäfte und Tierbedarfsregale in den Supermärkten der Stadt; Surfshops sind oft tolerant gegenüber Hunden`, `Kein Bahnhof in Peniche: Regionalbusse befördern kleine Haustiere in Transportboxen; erwähnen Sie den Hund bei der Taxibuchung`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung sind in Portugal Pflicht`],
    sights: {
      "Cabo Carvoeiro": `An der Spitze der Halbinsel reiht das Kap zerklüftete Klippen, einen Leuchtturm und vom Meer geformte Felsen aneinander, darunter der berühmte Nau dos Corvos. Der Küstenpfad wird an der Leine begangen, halten Sie Ihren Hund an windigen Tagen fest.`,
      "Baleal": `Dieses durch eine Sandnehrung mit der Küste verbundene Inselchen ist das Herz der örtlichen Surfkultur, mit Surfschulen, Cafés und Sonnenuntergängen. Außerhalb der Badesaison sind die riesigen umliegenden Strände ein Laufparadies für Hunde.`,
      "Praia dos Supertubos": `Europas „Pipeline" rollt südlich der Stadt ihre perfekten Röhrenwellen aus und ist jeden Herbst Schauplatz der Surfelite der Welt. Außerhalb der bewachten Badesaison ist ein Spaziergang mit angeleintem Hund über diesen riesigen Sand großartig, inklusive Surfer-Show.`,
      "Fortaleza de Peniche": `Die Festung aus dem 16. Jahrhundert, unter dem Estado Novo politisches Gefängnis, beherbergt heute das Nationalmuseum für Widerstand und Freiheit. Hunde dürfen das Museum nicht betreten, aber der Rundgang entlang der meerseitigen Wälle ist ein schöner Spaziergang an der Leine.`,
      "Papôa": `Diese kleine Halbinsel nördlich der Stadt erhebt ihre geschichteten Klippen und einen Felsbogen über ein oft aufgewühltes Meer. Ein kurzes, eindrucksvolles Wanderziel, an der Leine und mit Abstand zur Kante, die Böen hier sind ernst zu nehmen.`,
      "Ilhas Berlengas": `Zehn Kilometer vor der Küste beherbergt dieses Biosphärenreservat-Archipel eine im Wasser errichtete Festung und Seevogelkolonien. Ausflugsboote akzeptieren in der Regel keine Hunde, und das Reservat schützt seine Tierwelt streng: Bewundern Sie die Inseln stattdessen vom Kap aus.`,
    },
  },
  perpignan: {
    history: `Perpignan, Hauptstadt des Roussillon und lange eher katalanisch als französisch, war im 13. Jahrhundert die kontinentale Hauptstadt des Königreichs Mallorca, dessen Herrscher Jakob II. 1276 mit dem Bau des Palais des Rois de Majorque begann, einer weitläufigen katalanisch-gotischen Zitadelle. Im 17. Jahrhundert von Frankreich annektiert, bewahrt die Stadt eine tiefe katalanische Identität, sichtbar in Sprache, Küche und Festen. Le Castillet, ein 1368 begonnenes befestigtes Backsteintor, und die aufstrebende katalanisch-gotische Kathedrale Saint-Jean verankern eine kompakte, farbenfrohe Altstadt. Für den Reisenden mit Hund ist Perpignan überraschend einladend: rund 37 ausgewiesene Hundezonen über die Stadt verteilt, eine tolerante mediterrane Terrassenkultur, eines der sonnigsten Klimata Frankreichs und leichter Zugang zu den hundefreundlichen Roussillon-Stränden bei Canet, Sainte-Marie und Torreilles.`,
    petTips: [`Rund 37 ausgewiesene Hundezonen über die Stadt verteilt (offizielle Karte auf mairie-perpignan.fr) sind die einzige legale Möglichkeit, einen Hund ohne Leine laufen zu lassen; anderswo Leinenpflicht.`, `Strände: Die meisten Roussillon-Strände verbieten Hunde vom 15. Juni bis 15. September; der Lido von Canet (Fischerhütten) erlaubt angeleinte Hunde das ganze Jahr über.`, `Hitze und Wind: Perpignan ist eine der sonnigsten Städte Frankreichs, und der trockene Tramontane-Wind kann stark sein; gehen Sie früh oder spät spazieren und führen Sie Wasser mit.`, `Transport: Sankéo (kleine Hunde kostenlos in einer Tasche, größere angeleint und mit Maulkorb), TER liO (Haustierticket am Bahnhof, Maulkorb für größere Hunde).`, `Notfalltierarzt: NEOVET Tecnosud, rund um die Uhr (+33 4 68 50 38 29); nationale Bereitschaftslinie 3115 für das gesamte Departement.`],
    practicalInfo: [`Frankreich gehört zur EU und zum Schengen-Raum: EU-Heimtierausweis + gültige Tollwutimpfung + ISO-Mikrochip genügen aus jedem EU-Land.`, `Bahnhof Perpignan im Occitanie-Netz: häufige TER-Verbindungen nach Montpellier, Narbonne und zur spanischen Grenze; kaufen Sie das Haustierticket am Bahnhof.`, `Der Flughafen Perpignan-Rivesaltes (PGF) ist etwa 10 Minuten entfernt; Barcelona-El Prat liegt mit dem Auto etwa 2 Stunden entfernt und bietet mehr internationale Flüge.`, `Währung: Euro. Starke katalanische Identität: Sprache, Küche (Bullinada, Escalivada) und Feste; renommierte Roussillon-Weine.`, `Mit Hund meiden: die konzessionierten Strände auf dem Höhepunkt der Badesaison (15. Juni bis 15. September); Frühling und Herbst bevorzugen, mit mildem Klima und für Hunde geöffneten Stränden.`],
    sights: {
      "Le Castillet": `Das ikonische, 1368 begonnene befestigte Backsteintor, das einzige erhaltene Fragment der mittelalterlichen Stadtmauer. Außen an der Leine hundefreundlich; das Casa-Pairal-Museum nur für Assistenzhunde.`,
      "Palais des Rois de Majorque": `Eine weitläufige, 1276 von Jakob II. von Mallorca begonnene katalanisch-gotische Zitadelle. Wälle und Gärten an der Leine hundefreundlich mit Panoramablick; Innengalerien nur für Assistenzhunde.`,
      "Cathédrale Saint-Jean": `1324 begonnene katalanisch-gotische Kathedrale mit einem einzigen, aufstrebenden Kirchenschiff. Außenbereich und Platz an der Leine hundefreundlich; Inneres nur für Assistenzhunde.`,
      "Parc Sant Vicens": `Ein entspannender Park mit schattigen Wegen und offenen Flächen, mit eigener Hundezone, in der Hunde ohne Leine laufen können. Einer der angenehmsten der Stadt.`,
      "Berges de la Têt": `Eine Uferpromenade entlang der Têt, flach und stellenweise schattig, beliebt zum Spazierengehen, Laufen und Radfahren. Ideal früh oder spät an der Leine, um der Hitze zu entgehen.`,
      "Plage du Lido, Canet-en-Roussillon": `Der nächstgelegene ganzjährige Hundestrand, 15-20 Minuten entfernt, mit angeleinten Hunden das ganze Jahr über nahe den Fischerhütten erlaubt. Ein langer mediterraner Sandstrand.`,
    },
  },
  'san-diego': {
    history: `San Diego liegt in der äußersten südwestlichen Ecke Kaliforniens, geschmiegt an eine tiefe natürliche Bucht und nur durch eine urbane Grenze von Mexiko getrennt. Der Seefahrer Juan Rodríguez Cabrillo landete hier 1542, doch die eigentliche Geschichte der Stadt begann 1769 mit der Gründung der Mission San Diego de Alcalá, der ersten in der Kette der kalifornischen Missionen. Lange Zeit ein verschlafenes Städtchen, wurde es im 20. Jahrhundert durch die Ankunft der US-Marine verwandelt, deren Stützpunkte auf Point Loma und North Island den Ort bis heute prägen. Die Panama-California Exposition von 1915 hinterließ den Balboa Park mit seiner außergewöhnlichen spanisch-kolonialen Architektur. Das moderne San Diego lebt vom Tourismus, der Biotechnologie und dem Meer und hat sich zu einer der hundefreundlichsten Städte der Vereinigten Staaten entwickelt: Der Dog Beach in Ocean Beach ist seit 1972 legal ohne Leine begehbar, einer der allerersten offiziellen Strände dieser Art im Land.`,
    petTips: [`An den Stadtstränden außerhalb der leinenfreien Bereiche sind Hunde erlaubt, jedoch nur an der Leine, von April bis Oktober vor 9 Uhr und nach 18 Uhr und von November bis März vor 9 Uhr und nach 16 Uhr. Das ist die Regel, gegen die die meisten Besucher unwissentlich verstoßen.`, `Die maximale Leinenlänge beträgt in den Stadtparks und an den Stränden 2,4 Meter, doch die Vorschrift des County verlangt abseits zu Hause eine handgehaltene Leine von 1,8 Metern, sodass eine 1,8-Meter-Leine Sie überall auf der sicheren Seite hält. Ein erster Verstoß kostet mit Zuschlägen rund 195 Dollar.`, `Die öffentlichen Verkehrsmittel des MTS (Bus und Trolley) verlangen, dass jedes Tier, das kein Servicehund ist, vollständig in einer geschlossenen Transportbox auf dem Schoß mitgeführt wird, sodass mittelgroße oder große Hunde zu keiner Uhrzeit mitfahren können. Planen Sie ein Auto oder Uber Pet ein.`, `Die Fähre nach Coronado befördert nur Servicehunde. Um den Coronado Dog Beach zu erreichen, fahren Sie über die San Diego-Coronado Bridge oder nehmen Sie den MTS-Bus 901.`, `Die Lufttemperatur liegt im Schnitt nie über 23 Grad, doch von Mai bis Oktober ist die Sonne stark und der dunkle Sand heizt sich auf: Gehen Sie früh morgens oder nach 17 Uhr spazieren, testen Sie den Boden mit dem Handrücken und führen Sie Wasser mit, da Fiesta Island weder Toiletten noch Schatten bietet.`],
    practicalInfo: [`Die Vereinigten Staaten liegen außerhalb der EU: Ein EU-Heimtierausweis ist dort nicht gültig. Seit August 2024 muss jeder einreisende Hund mindestens 6 Monate alt und gechippt sein und ein vor der Abreise ausgefülltes CDC Dog Import Form mitführen; prüfen Sie Ihr Herkunftsland auf der Website der CDC.`, `Der San Diego International Airport (SAN) liegt 5 km von der Innenstadt entfernt, mit Auslaufflächen im Freien auf den Ground Transportation Plazas der Terminals 1 und 2 sowie einem Innenbereich hinter der Sicherheitskontrolle in Terminal 2 zwischen den Gates 46 und 47.`, `Der Amtrak Pacific Surfliner nimmt Hunde und Katzen bis 9 kg inklusive Transportbox für 29 Dollar mit, nur in den Coach-Wagen und mit fünf Plätzen pro Zug: Buchen Sie für einen Tagesausflug nach Los Angeles frühzeitig.`, `24-Stunden-Notfalltierärzte: VCA Emergency Animal Hospital, 7675 Mission Valley Road (+1 619 299 2400) und Veterinary Emergency Group, 980 Camino De La Reina (+1 619 346 4249), beide in Mission Valley; Veterinary Specialty Hospital, 10435 Sorrento Valley Road (+1 858 875 7500) für den Norden.`, `Währung: US-Dollar; ein Trinkgeld von 15 bis 20 Prozent ist üblich. Beste Reisezeit mit Hund: September und Oktober, warmes Meer und die Menschenmassen sind verschwunden; der Winter bleibt mit 14 bis 15 Grad mild und bietet größere Zeitfenster am Strand.`],
    sights: {
      "Dog Beach, Ocean Beach": `Der historische Hundestrand der Stadt am Fuß der Voltaire Street, seit 1972 legal ohne Leine begehbar. Die Stadt führt ihn als ganzjährig rund um die Uhr geöffnet mit kostenlosen Parkplätzen, Duschen und öffentlichen Toiletten.`,
      "Fiesta Island": `Eine ganze Insel im Mission Bay Park, an deren gesamter Uferlinie und im Inneren Freilauf erlaubt ist, mit einer 8,4 km langen Rundstrecke. Das Buchtwasser ist ruhig und flach, das einzig wirklich sichere Schwimmrevier für Hunde in San Diego.`,
      "Balboa Park": `Der große, 486 Hektar umfassende Kulturpark, der von der Weltausstellung 1915 übrig blieb, ist auf allen Außenanlagen für Hunde an der Leine geöffnet. Er beherbergt drei leinenfreie Hundeparks: Nate's Point, Morley Field und Grape Street. Die Museen und der Zoo lassen nur Servicehunde zu.`,
      "Sunset Cliffs Natural Park": `Siebenundzwanzig Hektar zerklüfteter Klippen am Pazifikrand von Point Loma, 1983 angelegt, mit Bögen und Meereshöhlen darunter. Hunde an der Leine sind auf den Klippenwegen erlaubt; die Ränder sind ungesichert und bröckelig, halten Sie die Leine daher kurz.`,
      "Coronado Dog Beach": `Der leinenfreie Bereich am Nordende von North Beach, 200 Ocean Boulevard, mit dem berühmten hellen Sand von Coronado und dem Hotel del Coronado im Hintergrund. Beachten Sie, dass die Fähre keine Haustiere befördert, Sie müssen also mit dem Auto oder dem MTS-Bus 901 anreisen.`,
      "Cabrillo National Monument": `Das Bundesdenkmal an der Spitze von Point Loma bietet einen Panoramablick über die Bucht und die Stadt. Nur ein Weg ist für Hunde geöffnet, der Coastal Trail, an einer maximal 1,8 Meter langen Leine; der Leuchtturm, die Gezeitentümpel und der Bayside Trail sind für Hunde gesperrt.`,
    },
  },
  'san-francisco': {
    history: `San Francisco liegt an der Spitze einer hügeligen Halbinsel zwischen dem Pazifik und seiner großen Bucht in Nordkalifornien. Zunächst eine spanische Mission und ein Presidio, explodierte die Stadt mit dem Goldrausch von 1849, der Goldsucher aus aller Welt anzog. Nach dem Erdbeben und Brand von 1906 wieder aufgebaut, wurde sie zu einer kosmopolitischen Metropole, berühmt für ihre steilen, von Cable Cars erklommenen Hügel, ihre bunten viktorianischen Häuser, das Chinatown-Viertel und die ikonische Golden Gate Bridge, die 1937 eröffnet wurde. Als historisches Herz der Gegenkultur und heute Hauptstadt der Tech-Branche zählt San Francisco zu den hundefreundlichsten Städten der Vereinigten Staaten: riesige Parks, viele leinenfreie Bereiche, Hundestrände und tolerante Terrassen. Sein kühles, nebliges Mikroklima, verkörpert vom berühmten „Karl the Fog“, macht das Spazierengehen fast das ganze Jahr über angenehm, auch wenn das Gelände entschieden steil ist.`,
    petTips: [`San Francisco ist wirklich hundefreundlich: Es gibt viele leinenfreie Bereiche und Hundestrände, doch auf Wanderwegen sollte die Leine standardmäßig angelegt bleiben, und wo Rückrufkontrolle vorgeschrieben ist, sollte sie eingehalten werden.`, `Kühles, nebliges Mikroklima das ganze Jahr über ('Karl the Fog'): Packen Sie auch im Sommer eine leichte Schicht ein, denn der Ozeanwind am Ocean Beach und am Golden Gate kann bissig sein.`, `Saisonale Warnung: Die kurzen Hitzeperioden im September/Oktober ('Indian Summer') überraschen viele nach den kühlen Monaten; meiden Sie an heißen Tagen den Asphalt zu Stoßzeiten und führen Sie Wasser mit.`, `Das Gelände ist sehr steil: Gehen Sie mit älteren oder kleinen Hunden bei steilen Anstiegen und langen Treppen vorsichtig vor und achten Sie auf die Pfotenballen bei heißen oder rauen Gehwegen.`, `Transport: BART nimmt nur kleine Haustiere in einer Transportbox mit; im Notfall wählen Sie 911, und mehrere 24-Stunden-Tierkliniken sind in der Stadt tätig.`],
    practicalInfo: [`Die Vereinigten Staaten liegen außerhalb der EU: kein EU-Heimtierausweis; prüfen Sie bei Einreise aus dem Ausland vor der Reise die aktuellen CDC-Einfuhrregeln für Hunde (Mikrochip, Tollwutimpfung, Formulare).`, `Transport: BART nimmt nur kleine Haustiere in einer Tasche mit; das Muni-Netz (Bus, Straßenbahn, Cable Car) erlaubt angeleinte und mit Maulkorb versehene Hunde oder Hunde in einer Transportbox, oft außerhalb der Stoßzeiten.`, `Der San Francisco International Airport (SFO) liegt etwa 20 km südlich; Fahrer von Mitfahrdiensten dürfen andere Tiere als Servicehunde ablehnen, informieren Sie den Fahrer daher im Voraus.`, `Währung: US-Dollar; Trinkgeld (15 bis 20 Prozent) ist in Restaurants und bei vielen Dienstleistungen üblich.`, `Beste Reisezeit: September/Oktober, oft die sonnigsten und nebelärmsten Monate; im Sommer bleibt es an der Ozeanseite kühl und neblig.`],
    sights: {
      "Golden Gate Park": `Ein riesiger Stadtpark, größer als der Central Park, mit Gärten, Seen und Wiesen. Hunde sind auf den meisten Wegen an der Leine erlaubt, dazu einige ausgeschilderte, eingezäunte leinenfreie Hundeauslaufflächen.`,
      "Crissy Field": `Ein ehemaliges Flugfeld, das zu einer Uferpromenade mit direktem Blick auf die Golden Gate Bridge umgestaltet wurde. Bei Hunden sehr beliebt: an der Leine entlang der Promenade, mit einem Strandabschnitt, der Freilauf erlaubt.`,
      "Fort Funston": `Wilde Klippen im Südwesten der Stadt, ein berühmtes leinenfreies Hundeparadies über dem Ozean. Sandige Wege, Drachenflieger und lange Strände: einer der besten Hundeorte Kaliforniens.`,
      "Ocean Beach": `Ein langer Sandstrand, an dem der Pazifik am Westrand der Stadt tost. Hunde sind auf weiten Abschnitten erlaubt, an der Leine oder unter Rückrufkontrolle; starke Strömungen machen das Schwimmen nicht ratsam.`,
      "Dolores Park": `Ein lebendiger, abschüssiger Park im Mission District mit Blick über die Skyline. Angeleinte Hunde sind auf den sonnigen Wiesen willkommen, mit einem eigenen Hundebereich; an schönen Wochenenden sehr belebt.`,
      "Embarcadero et Ferry Building": `Eine neugestaltete Uferpromenade an der Bucht, vom Ferry Building bis zu den Piers, ideal für einen langen, ebenen Spaziergang. Angeleinte Hunde sind im Freien willkommen; der Zutritt zur Markthalle im Ferry Building kann je nach Anbieter variieren.`,
    },
  },
  'san-sebastian': {
    history: `Donostia-San Sebastián begann als mittelalterlicher Fischerhafen, der 1180 das Stadtrecht erhielt, wurde 1813 von anglo-portugiesischen Truppen niedergebrannt und als Belle-Époque-Sommerhauptstadt Spaniens unter Königin María Cristina wiederaufgebaut, die 1845 die königliche Gewohnheit des Badens an La Concha einführte. Das daraus entstandene Raster eleganter Boulevards des 19. Jahrhunderts, drei perfekte Stadtstrände und eine Dichte an Michelin-Sternen, die es mit Paris aufnehmen kann, machen es wohl zur am besten herausgeputzten Kleinstadt Europas. Die baskische Kultur behandelt Hunde wie Familienmitglieder: Der Euskal Artzain Txakurra (Baskischer Hirtenhund) ist ein nationales Symbol, und in den ländlichen Txoko-Speiseclubs war der Familienhund seit jeher unter dem Tisch willkommen.`,
    petTips: [`Die saisonalen Verbote an den Stadtstränden werden vom 1. Juni bis 15. September (8 bis 20 Uhr) konsequent durchgesetzt, außerhalb der Saison ist derselbe Sand weitgehend hundetolerant; prüfen Sie stets das Piktogramm am Strandzugang.`, `Das baskische Wetter ist nordatlantisch geprägt: Bringen Sie das ganze Jahr über ein Hundehandtuch und schnelltrocknende Ausrüstung mit; seitlicher Regen ('Sirimiri') ist selbst im Sommer fast täglich möglich.`, `Die Küstenlinien von Euskotren und Renfe Cercanías nehmen außerhalb der Stoßzeiten angeleinte/mit Maulkorb versehene Hunde mit, sehr nützlich für Tagesausflüge nach Hondarribia, Zarautz oder Biarritz.`, `Pintxo-Bars sind hundetolerant, aber überfüllt; besuchen Sie sie vor 20:30 Uhr, um dem Andrang zu entgehen, und geben Sie großzügig Trinkgeld, wenn sich Ihr Hund unter einem Barhocker niederlässt.`, `Die Gezeiten von La Concha und Zurriola können extrem sein (über 6 m Tidenhub), prüfen Sie die Gezeitentabelle, bevor Sie bei Niedrigwasser zum Strand gehen, um nicht vom steigenden Meer eingeschlossen zu werden.`],
    practicalInfo: [`Flughafen: San Sebastián (EAS) ist klein und regional; Biarritz (BIQ, Frankreich) und Bilbao (BIO) sind größere Alternativen, beide mit hundefreundlichen Bussen erreichbar (Pesa, Lurraldebus).`, `Tierärzte: Hospital Veterinario Donosti und Centro Veterinario Igeldo übernehmen Notfälle; die nächste 24-Stunden-Fachversorgung befindet sich mitunter in Pamplona oder Bilbao.`, `Busse (Dbus) lassen außerhalb der Stoßzeiten angeleinte/mit Maulkorb versehene Hunde zu; kleine Hunde in Transportboxen jederzeit, eines der großzügigeren städtischen Netze Spaniens.`, `Tagesausflüge: Pasai Donibane (Fähre nimmt Hunde mit), Hondarribia und die französische Baskenküste liegen alle innerhalb von 40 Minuten und sind überwiegend hundefreundlich.`, `Tierbedarf: Kiwoko im Zentrum, dazu mehrere Tierarztpraxen mit angeschlossenem Laden in Gros und der Altstadt (Antiguo).`],
    sights: {
      "Playa de la Concha": `Die legendäre, muschelförmige Bucht verbietet Hunde vom 1. Juni bis 15. September, 8 bis 20 Uhr. Außerhalb der Saison und früh morgens wird sie zu einem der schönsten Hundestrände Europas, mit den Belle-Époque-Geländern als Kulisse.`,
      "Monte Urgull": `Der 123 m hohe Vorsprung zwischen Altstadt und Meer ist von schattigen Waldwegen durchzogen, die zur Festung Motako Gaztelua und zur Statue des Heiligsten Herzens führen. Hunde an der Leine sind auf allen Außenwegen willkommen.`,
      "Parte Vieja (Old Town)": `Das Pintxo-Barenviertel rund um die Plaza de la Constitución heißt wohlerzogene Hunde auf den meisten Terrassen und in vielen Barräumen willkommen, die baskische Haustierkultur ist ungewöhnlich entspannt. Abends wird es sehr voll, mittags ist der Txikiteo-Bummel ruhiger.`,
      "Paseo Nuevo": `Die vom Meer umtoste Küstenpromenade umrundet den Monte Urgull und bietet Atlantikgischt und dramatische Sturmblicke. Angeleinte Hunde sind willkommen; halten Sie sie im Herbst und Winter bei hohem Wellengang nah bei sich, wenn das Wasser über das Geländer schlägt.`,
      "Monte Igueldo & Funicular": `Die 1912 eröffnete Standseilbahn nimmt angeleinte Hunde (gegen kleine Gebühr) mit zum Panoramagipfel und seinem historischen Vergnügungspark. Alternativ erklimmen Sie den Berg über den GR-121-Wanderweg für den besten Blick auf die Bucht im Baskenland.`,
      "Playa de la Zurriola": `Der Surfstrand des Gros-Viertels verbietet Hunde ebenfalls tagsüber im Sommer, doch der angrenzende Parque de Cristina Enea bietet ganzjährig eine hervorragende grüne Alternative mit ausgewiesenen Hundezonen.`,
    },
  },
  'sankt-polten': {
    history: `Sankt Pölten, die Landeshauptstadt von Niederösterreich, erstreckt sich entlang der Ufer der Traisen zwischen Wien und dem Wachautal. Die barocke Altstadt entfaltet sich rund um den Rathausplatz, einen der schönsten Plätze des Landes, gesäumt von Palais, Kirchen und reich verzierten Fassaden des 18. Jahrhunderts. Der Dom und die Gebäude des Instituts der Englischen Fräulein zeugen von dieser reichen religiösen und architektonischen Vergangenheit. Abseits des historischen Zentrums präsentiert das Regierungsviertel eine entschieden moderne Architektur mit dem Klangturm und dem Landestheater. Am Fluss entlang bieten der Traisenpark und der Sonnenpark weite Grünflächen, während die Viehofner Seen im Norden im Sommer als Badeseen dienen. Das Klima ist kontinental: warme Sommer, kalte und teils schneereiche Winter. Österreich, Eurozone, EU-Mitglied. Notrufnummern: 112, Rettungsdienst 144.`,
    petTips: [`Im Sommer kann das kontinentale Klima heiß werden: Gehen Sie mit Ihrem Hund früh morgens oder abends spazieren und nutzen Sie die Viehofner Seen, wo eine Hundezone ausgeschildert ist, zur Abkühlung.`, `Die bewaldeten Ufer der Traisen und die Weinberge der Wachau beherbergen von Frühling bis Herbst Zecken: Wenden Sie eine Parasitenbehandlung an und untersuchen Sie Ihren Hund nach jedem Spaziergang.`, `Der Winter ist kalt und teils schneereich: Packen Sie für kälteempfindliche Hunde einen Mantel ein und spülen Sie Pfotenballen ab, die Streusalz auf den Gehwegen ausgesetzt waren.`, `Bleiben Sie in der Wachau auf ausgeschilderten Wegen und halten Sie Ihren Hund in der Nähe der eingezäunten Weinstöcke an der Leine; meiden Sie die geschäftige Erntezeit.`, `Sankt Pölten ist ein Eisenbahnknotenpunkt nach Wien: Legen Sie für einen Zug-Tagesausflug Ihrem Hund die Leine an (und bei großen Hunden einen Maulkorb, der bei der ÖBB oft vorgeschrieben ist).`],
    practicalInfo: [`Für die Einreise nach Österreich aus einem EU-Land gilt der europäische Heimtierausweis: Mikrochip und aktuelle Tollwutimpfung.`, `Einheitliche europäische Notrufnummer: 112. Für den Rettungsdienst wählen Sie 144. Es gibt keine landesweite tierärztliche Notrufnummer; fragen Sie in Ihrer Unterkunft nach dem nächsten diensthabenden Tierarzt.`, `Fortbewegung: Das Zentrum von Sankt Pölten ist kompakt und zu Fuß erreichbar; angeleinte Hunde (große Hunde oft mit Maulkorb gemäß den Vorschriften) sind in ÖBB-Zügen und Regionalbussen erlaubt.`, `Örtliche Regel: In der Innenstadt gilt Leinenpflicht, und das Aufsammeln von Hinterlassenschaften ist Pflicht; beachten Sie die Beschilderung in Parks bezüglich Zonen, in denen Freilauf erlaubt ist.`, `Sankt Pölten ist mit dem Zug in unter 30 Minuten von Wien aus erreichbar und liegt am Tor zur Wachau und zum Stift Melk: eine praktische Basis, um Niederösterreich mit Haustier zu erkunden.`],
    sights: {
      "Rathausplatz": `Der große Rathausplatz, das Herz der barocken Altstadt, reiht prächtige Fassaden, eine Dreifaltigkeitssäule und Cafeterrassen aneinander. Angeleinte Hunde sind für einen Bummel durch die Fußgängerzone willkommen; der Zutritt zu Cafés und Geschäften liegt im Ermessen des jeweiligen Betreibers.`,
      "Dom (Cathédrale)": `Der Dom von Sankt Pölten, ursprünglich romanisch und reich barockisiert, birgt ein prachtvolles Inneres. Wie an den meisten Sakralstätten sind Hunde im Inneren nicht zugelassen, doch der angrenzende Platz und die Altstadtgassen können an der Leine begangen werden.`,
      "Regierungsviertel et Klangturm": `Das moderne Regierungsviertel reiht zeitgenössische Architektur, Plätze und den Klangturm, ein Wahrzeichen der Stadt, aneinander. Die weiten Außenflächen und Wege können an der Leine begangen werden; die Innenräume des Turms, des Landestheaters und der Museen lassen in der Regel nur Assistenzhunde zu.`,
      "Sonnenpark et parc de la Traisen": `Entlang der Traisen bietet eine Kette von Grünflächen, darunter der Sonnenpark, Wiesen, schattige Wege und Spaziergänge am Wasser. Angeleinte Hunde sind für lange Spaziergänge willkommen; sammeln Sie Hinterlassenschaften auf und beachten Sie die Beschilderung, wo Freilauf erlaubt sein kann.`,
      "Viehofner Seen": `Nördlich der Stadt bieten diese aus alten Schottergruben entstandenen Badeseen im Sommer grasige Ufer und ruhiges Wasser. In manchen Bereichen sind Hunde erlaubt, und eine Hundeschwimmzone kann ausgeschildert sein; beachten Sie die örtliche Beschilderung und halten Sie Ihren Hund von den Familienbadezonen fern.`,
      "Vallée de la Wachau": `Ein kurzes Stück westlich entfaltet die Wachau ihre terrassierten Weinberge entlang der Donau, eine Weltkulturerbe-Landschaft. Angeleinte Hunde sind auf den Weinbergwegen und in den Dörfern willkommen; respektieren Sie die eingezäunten Weinstöcke und meiden Sie die Erntezeit, wenn reger Betrieb herrscht.`,
    },
  },
  sanremo: {
    history: `Sanremo, Hauptstadt der Riviera dei Fiori in der ligurischen Provinz Imperia, erstreckt sich zwischen Bergen und Küste am Meer, wenige Kilometer von der französischen Grenze entfernt. Die Stadt der Blumen und des berühmten italienischen Musikfestivals verdankt ihren Ruhm einem der mildesten Klimata Italiens, das ab dem 19. Jahrhundert eine russische und englische Wintergesellschaft anzog, daher der von Palmen gesäumte Corso Imperatrice und die prächtigen Belle-Époque-Hotels. Über der modernen Stadt windet sich das mittelalterliche Altstadtviertel La Pigna in konzentrischen Gassen den Hügel hinauf. An der Küste beleben das Jugendstil-Casino (1905), der Porto Vecchio und die Marina Portosole die Stadt, während sich die lange Pista Ciclabile, auf der ehemaligen Bahnstrecke errichtet, am Meer entlangzieht. Italien, Eurozone, EU- und Schengen-Mitglied. Notruf: 112.`,
    petTips: [`Verlassen Sie sich im Sommer nicht auf die großen, kostenpflichtigen Strandbäder (stabilimenti): Die meisten schränken Hunde von Juni bis September ein oder verbieten sie. Nutzen Sie stattdessen den freien Strand Pian di Poma oder den Baubeach in Arma di Taggia, etwa 10 km entfernt.`, `Die Pista Ciclabile ist der beste Ort der Gegend für Hundespaziergänge, doch Schatten ist knapp: Gehen Sie bei Sonnenauf- oder -untergang, prüfen Sie den Belag mit der Hand und führen Sie Wasser mit.`, `Halten Sie Ihren Hund in der Stadt an der Leine und haben Sie einen Maulkorb griffbereit: Das italienische Recht kann ihn in öffentlichen Verkehrsmitteln und an belebten Orten vorschreiben.`, `In Trenitalia-Zügen reisen kleine Hunde kostenlos in einer Transportbox; ein größerer Hund benötigt eine Leine, einen mitzuführenden Maulkorb und ein halbpreisiges Regionalticket.`, `Die Innenräume des Casinos und der Kirchen schließen Haustiere aus: Planen Sie diese Besuche für Zeiten ein, in denen sich Ihr Hund ausruhen kann, oder buchen Sie über Rover, Pawshake oder Holidog einen örtlichen Dogsitter.`],
    practicalInfo: [`Für die Einreise nach Italien aus einem EU-Land gilt der europäische Heimtierausweis: Mikrochip und aktuelle Tollwutimpfung. Italien, Eurozone und Schengen-Raum.`, `Einheitliche europäische Notrufnummer: 112. Für einen tierärztlichen Notfall bietet das Ospedale Veterinario San Remo (Via Barabino 15) einen 24-Stunden-Dienst unter +39 0184 666921.`, `Fortbewegung: Das Zentrum von Sanremo ist flach und zu Fuß erreichbar; der größtenteils unterirdische Bahnhof liegt an der Küstenlinie Genua-Ventimiglia, und Riviera Trasporti bedient die Küste mit dem Bus.`, `Strände: Die meisten kostenpflichtigen Strandbäder schränken Hunde im Sommer ein; der freie Strand Pian di Poma erlaubt sie, und der Baubeach in Arma di Taggia ist ein richtiger Hundestrand. Prüfen Sie die aktuelle städtische Bekanntmachung.`, `Sanremo ist eine ideale Basis für die Riviera dei Fiori: nur ein kurzes Stück von Ospedaletti, Bordighera, Ventimiglia und der französischen Grenze entfernt, entlang des Küstenradwegs.`],
    sights: {
      "Pista Ciclabile del Parco Costiero": `Der große, flache und asphaltierte Weg auf der ehemaligen Küstenbahnstrecke Genua-Ventimiglia, etwa 24 km lang zwischen Ospedaletti und San Lorenzo al Mare. Angeleinte Hunde sind für lange Spaziergänge am Wasser willkommen; der Schatten ist lückenhaft, führen Sie also im Sommer Wasser mit und starten Sie früh.`,
      "Corso Imperatrice": `Die von Palmen gesäumte Uferpromenade, die älteste in Sanremo, benannt nach einer russischen Kaiserin, die hier überwinterte. Flach und eben, wird sie an der Leine begangen und lässt sich leicht mit dem Radweg zu einer längeren Runde mit Meerblick verbinden.`,
      "La Pigna (vieille ville)": `Sanremos mittelalterliches Herz, ein Labyrinth konzentrischer Gassen, Bögen und Treppen, die den Hügel hinaufführen, nach ihrer Form La Pigna (der Kiefernzapfen) genannt. Ein rein im Freien gelegener Rundgang, bei dem angeleinte Hunde willkommen sind; die Gassen sind steil und mit Kopfsteinpflaster versehen, gehen Sie also langsam.`,
      "Giardini di Villa Ormond": `Ein kostenloser öffentlicher Park, angelegt als botanisches Freilichtmuseum, mit Palmenhainen, Zedern und einem japanischen Garten, der aus Sanremos Städtepartnerschaft mit Atami entstand. Angeleinte Hunde sind willkommen; bleiben Sie auf den Wegen, da es sich um eine gepflegte botanische Sammlung handelt.`,
      "Casino di Sanremo": `Das markante Jugendstil-Casino von 1905 krönt die Terrassen über der Uferpromenade. Haustiere sind in den Spielsälen nicht erlaubt; genießen Sie die Fassade und die Palmenterrassen von außen, oder besuchen Sie es abwechselnd, während eine Person beim Hund bleibt.`,
      "Porto Vecchio e Portosole": `Der alte Fischereihafen, der jeden Morgen die Küchen der Piazza Bresca beliefert, liegt neben der großen Yachtmarina Portosole. Die flachen Kais und Cafeterrassen werden an der Leine für einen entspannten Spaziergang am Wasser begangen, direkt neben den Fischrestaurants.`,
    },
  },
  'sant-antoni': {
    history: `Sant Antoni de Portmany an der Westküste Ibizas auf den Balearen ist das große Sonnenuntergangs-Reiseziel der Insel. Aus einem bescheidenen Fischerdorf um seine befestigte Kirche aus dem 14. Jahrhundert gewachsen, entwickelte sich der Ort mit dem Tourismus zu einem Zentrum des Nachtlebens und der elektronischen Musik. Seine tiefe Bucht, die größte der Insel, endet am berühmten Sunset Strip, wo Bars und Terrassen jeden Abend beobachten, wie die Sonne im Meer versinkt. Jenseits des sommerlichen Trubels zeigt Sant Antoni ein anderes Gesicht: die lange Passeig de ses Fonts mit ihren tanzenden Fontänen, die durchscheinenden Buchten von Cala Bassa und Cala Conta im Westen und das ruhige Binnental von Santa Agnès, berühmt für seine winterliche Mandelblüte. Man erkundet ihn an der Leine entlang der Uferpromenade, zwischen Marina, Promenade und Küstenwegen, eine bequeme Basis, um den wilderen Westen der Insel zu erkunden.`,
    petTips: [`Spanisches Recht: In der Stadt gilt Leinenpflicht, und für gelistete PPP-Rassen ist an öffentlichen Orten und in Verkehrsmitteln ein Maulkorb vorgeschrieben; halten Sie Heimtierausweis und Mikrochip stets aktuell.`, `Sommerliches Strandverbot: Auf den Balearen sind Hunde während der Badesaison (etwa Mai bis Oktober) an bewachten Stränden untersagt, prüfen Sie also vor dem Strandbesuch, ob ein ausgewiesener Hundestrand existiert.`, `Mediterrane Hitze: Von Juni bis September übersteigen die Nachmittagstemperaturen häufig 30 °C, gehen Sie also bei Sonnenauf- oder -untergang spazieren und testen Sie den Asphalt vor dem Aufbruch mit dem Handrücken.`, `Nächtlicher Lärm: Sant Antoni ist ein Nachtleben-Hotspot, und Musik und Menschenmassen in den Straßen des West End können im August für einen Hund stressig sein, wählen Sie daher eine Unterkunft abseits des Zentrums.`, `Bootsausflüge: Shuttles nach Cala Salada oder Sonnenuntergangsfahrten akzeptieren manchmal kleine angeleinte Hunde, bestätigen Sie die Richtlinie vor dem Boarding am Hafenschalter.`],
    practicalInfo: [`Notfälle: 112 ist Spaniens einheitliche europäische Nummer; Sant Antoni verfügt über Tierarztpraxen, fragen Sie in Ihrem Hotel nach dem nächsten Bereitschaftsdienst.`, `Busse nach Ibiza-Stadt und zum Flughafen: kleine Hunde in Transportboxen werden meist zugelassen, prüfen Sie die Richtlinie beim Fahrer oder Verkehrsverbund vor dem Einstieg.`, `Strände: Bewachte Strände sind während der Badesaison reglementiert, erkunden Sie also im Voraus eine unbewachte Felsbucht oder eine der Hundezonen der Insel.`, `Der Flughafen Ibiza (IBZ) liegt etwa zwanzig Kilometer entfernt; Spanien ist EU-Mitglied, bringen Sie also den europäischen Heimtierausweis mit aktuellem Mikrochip und Tollwutimpfung mit.`, `Hitze und Menschenmassen: Buchen Sie im Sommer frühzeitig und bevorzugen Sie eine Unterkunft mit schattigem Winkel und Wasserstelle für den Hund, da sich die Insel im Juli und August füllt.`],
    sights: {
      "Sunset Strip i Badia de Sant Antoni": `Die lange Bucht und ihre Promenade versammeln die Sonnenuntergangs-Bars mit Blick auf das offene Meer. Man geht hier an der Leine entlang der Uferpromenade, doch der Stadtstrand ist im Sommer reglementiert, und belebte Abende können für einen Hund laut sein.`,
      "Mirador de Ses Variades": `Dieser Aussichtspunkt am Ende der Promenade ist der klassische Sonnenuntergangsort, gesäumt von Terrassen und Felsen. Ein Freiluftbereich, zugänglich an der Leine, bei Dämmerung sehr überlaufen, kommen Sie also früh mit einem Hund, der Menschenmengen nicht mag.`,
      "Monument de l'Ou (l'oeuf de Colomb)": `Diese große weiße, eiförmige Skulptur am Hafeneingang erinnert an die Legende, die Christoph Kolumbus mit Ibiza verbindet. Ein Freiluftdenkmal, jederzeit einsehbar, ideal für ein schnelles Foto mit dem angeleinten Hund.`,
      "Passeig de ses Fonts": `Diese gestaltete Uferpromenade reiht Rasenflächen, Palmen und beleuchtete Fontänen aneinander, die abends tanzen. Ein Fußgängerbereich, perfekt für einen kühlen Spaziergang an der Leine, mit willkommenen Schattenplätzen während der heißen Stunden.`,
      "Cala Bassa i Cala Conta": `Diese Buchten mit weißem Sand und türkisfarbenem Wasser westlich der Stadt zählen zu den schönsten Ibizas. Während der Badesaison sind Hunde an diesen bewachten Stränden verboten, suchen Sie stattdessen eine kleine, unbewachte Felsbucht.`,
      "Vall de Santa Agnès de Corona": `Dieses ländliche Binnental verfärbt sich um Ende Januar und Februar rosa und weiß durch die Mandelblüte. Ländliche Wege und offene Pfade zum Spazierengehen an der Leine, fernab vom Küstentrubel, ideal außerhalb der Saison.`,
    },
  },
  'sant-josep': {
    history: `Sant Josep de sa Talaia, das den gesamten Südwesten Ibizas auf den Balearen umfasst, ist die größte und ländlichste Gemeinde der Insel. Fernab des Trubels des benachbarten Sant Antoni ist dies ein Land aus pinienbewachsenen Hügeln, Mandelfeldern und langen Trockenmauern, gekrönt vom Sa Talaia, dem mit 475 Metern höchsten Punkt der Insel. Seine zerklüftete Küste reiht einige der schönsten Buchten Ibizas aneinander, von der Cala d'Hort gegenüber dem magnetischen Inselchen Es Vedrà bis zur Cala Tarida und Cala Vadella, während sich im Süden der Naturpark Ses Salines mit seinen Salinen ausbreitet, wo sich Flamingos versammeln. Das Dorf selbst gruppiert sich um eine weißgetünchte befestigte Kirche aus dem 18. Jahrhundert, typisch für die ibizenkische Architektur. Man kommt hierher eher wegen der Natur als wegen des Nachtlebens, und man erkundet sie an der Leine zwischen Küstenwegen, Salinen und einem ruhigen Hinterland.`,
    petTips: [`Spanisches Recht: In der Öffentlichkeit gilt Leinenpflicht, und für gelistete PPP-Rassen ist an öffentlichen Orten und in Verkehrsmitteln ein Maulkorb vorgeschrieben; halten Sie Heimtierausweis und Mikrochip stets aktuell.`, `Sommerliches Strandverbot: Auf den Balearen sind Hunde während der Badesaison (etwa Mai bis Oktober) an bewachten Stränden untersagt, erkunden Sie also vor dem Strandbesuch eine unbewachte Felsbucht.`, `Mediterrane Hitze: Von Juni bis September übersteigen die Nachmittagstemperaturen häufig 30 °C, gehen Sie also bei Sonnenauf- oder -untergang spazieren und testen Sie den Asphalt vor dem Aufbruch mit dem Handrücken.`, `Es Vedrà bei Sonnenuntergang: Die Aussichtspunkte bei Cala d'Hort sind im Sommer bei Dämmerung überfüllt, parken Sie also früh und halten Sie den Hund gut vom Klippenrand fern.`, `Naturpark Ses Salines: ein Schutzgebiet mit brütender Tierwelt, bleiben Sie also an der Leine auf markierten Wegen und halten Sie den Hund von den Vögeln und den Salzlagunen fern.`],
    practicalInfo: [`Notfälle: 112 ist Spaniens einheitliche europäische Nummer; die Gemeinde verfügt über Tierarztpraxen, fragen Sie in Ihrem Hotel nach dem nächsten Bereitschaftsdienst.`, `Fortbewegung: Sant Josep ist sehr weitläufig und ländlich, ein Auto ist zum Erreichen der Buchten fast unerlässlich; kleine Hunde in Transportboxen werden in Bussen meist zugelassen, bestätigen Sie dies beim Fahrer.`, `Strände: Bewachte Strände sind während der Badesaison reglementiert, erkunden Sie also im Voraus eine unbewachte Felsbucht oder eine der Hundezonen der Insel.`, `Der Flughafen Ibiza (IBZ) liegt etwa zwanzig Minuten entfernt; Spanien ist EU-Mitglied, bringen Sie also den europäischen Heimtierausweis mit aktuellem Mikrochip und Tollwutimpfung mit.`, `Natur und Hitze: Bevorzugen Sie eine Unterkunft mit schattigem Winkel und Wasserstelle, da das bewaldete Hinterland außerhalb der Saison hervorragend ist, aber im Hochsommer wenig Schatten bietet.`],
    sights: {
      "Sa Talaia": `Der mit 475 Metern höchste Punkt Ibizas, dieser pinienbewachsene Hügel bietet einen vollen Rundblick über die ganze Insel und an klaren Tagen bis nach Formentera. Der Aufstieg erfolgt an der Leine über schattige Pfade, am besten für die kühleren Stunden reserviert, da es unterwegs keine Wasserstelle gibt.`,
      "Cala d'Hort i Es Vedra": `Diese Bucht liegt gegenüber Es Vedrà, dem berühmtesten magnetischen Felsinselchen Ibizas, spektakulär bei Sonnenuntergang von den Klippenaussichtspunkten aus. Die hochgelegenen Aussichtspunkte lassen sich das ganze Jahr über an der Leine begehen, doch der Sand des bewachten Strandes ist für Hunde während der Badesaison tabu.`,
      "Parc Natural de Ses Salines": `Diese aktiven Salinen im Süden der Insel ziehen Flamingos und eine reiche Zugvogelwelt in einer flachen Landschaft aus Deichen und Lagunen an. Wege und Pfade lassen sich an der Leine begehen, halten Sie dabei Abstand zu den Vögeln und den geschützten Brutgebieten.`,
      "Cala Vadella": `Diese hufeisenförmige Bucht mit ruhigem, geschütztem Wasser ist eine der beliebtesten der Gemeinde zum Familienbaden. Wie die übrigen bewachten Strände der Balearen verbietet sie Hunde während der Badesaison, erkunden Sie stattdessen eine kleine Felsbucht etwas abseits.`,
      "Cala Tarida": `Der größte Sandstrand der Gemeinde, weitläufig und von Restaurants gesäumt, besticht durch sein flaches, klares Wasser. Hunde sind im Sommer auf dem bewachten Sand nicht erlaubt, doch die felsigen Küstenwege, die ihn mit den Nachbarbuchten verbinden, können an der Leine abseits der Badebereiche begangen werden.`,
      "Església de Sant Josep": `Diese weißgetünchte befestigte Kirche aus dem 18. Jahrhundert im Herzen des Dorfes zeigt mit ihrer Arkadenvorhalle und ihrem barocken Altarbild die ländliche Architektur Ibizas. Das Innere lässt keine Hunde zu, doch der schattige Platz davor eignet sich gut für eine angeleinte Pause.`,
    },
  },
  'santa-eulalia': {
    history: `Santa Eulària des Riu an der Ostküste Ibizas auf den Balearen ist das ruhigste und familienfreundlichste Reiseziel der Insel. Sein Name erinnert an eine geografische Besonderheit: Der Riu de Santa Eulària ist der einzige ständig fließende Fluss der Balearen, nahe seiner Mündung von einer alten Steinbrücke römischen Ursprungs überquert. Über der Stadt trägt der Hügel Puig de Missa eine weißgetünchte befestigte Kirche aus dem 16. Jahrhundert und einen alten Weiler, der einst die Küste vor Korsaren bewachte. Darunter verbindet eine lange, von Palmen gesäumte Uferpromenade mit Skulpturen und einer Marina die Strände von Cala Llonga und Es Canar, Heimat des historischen, wöchentlich stattfindenden Hippiemarkts Punta Arabí. Bekannt für seine Küche und sein gemächliches Tempo, erkundet man Santa Eulària an der Leine zwischen Altstadt, Uferpromenade und Flussufern, ein sanfter Gegenpol zu den geschäftigeren Reisezielen der Insel.`,
    petTips: [`Spanisches Recht: In der Stadt gilt Leinenpflicht, und für gelistete PPP-Rassen ist an öffentlichen Orten und in Verkehrsmitteln ein Maulkorb vorgeschrieben; halten Sie Heimtierausweis und Mikrochip stets aktuell.`, `Sommerliches Strandverbot: Auf den Balearen sind Hunde während der Badesaison (etwa Mai bis Oktober) an bewachten Stränden untersagt, prüfen Sie also vor dem Strandbesuch, ob ein ausgewiesener Hundestrand existiert.`, `Mediterrane Hitze: Von Juni bis September übersteigen die Nachmittagstemperaturen häufig 30 °C, gehen Sie also bei Sonnenauf- oder -untergang spazieren und testen Sie den Asphalt vor dem Aufbruch mit dem Handrücken.`, `Flussufer und Puig de Missa: Diese schattigen Orte eignen sich während der heißen Stunden für angeleinte Spaziergänge, führen Sie Wasser und einen faltbaren Napf für den Hund mit.`, `Punta-Arabí-Markt: Angeleinte Hunde werden im Freien toleriert, doch das Gedränge und der glühend heiße Nachmittagsboden im Sommer sind anstrengend, bevorzugen Sie also die morgendliche Öffnungszeit.`],
    practicalInfo: [`Notfälle: 112 ist Spaniens einheitliche europäische Nummer; Santa Eulària verfügt über Tierarztpraxen, fragen Sie in Ihrem Hotel nach dem nächsten Bereitschaftsdienst.`, `Busse nach Ibiza-Stadt und zum Flughafen: kleine Hunde in Transportboxen werden meist zugelassen, prüfen Sie die Richtlinie beim Fahrer oder Verkehrsverbund vor dem Einstieg.`, `Strände: Bewachte Strände sind während der Badesaison reglementiert, erkunden Sie also im Voraus eine unbewachte Felsbucht oder eine der Hundezonen der Insel.`, `Der Flughafen Ibiza (IBZ) liegt etwa zwanzig Kilometer entfernt; Spanien ist EU-Mitglied, bringen Sie also den europäischen Heimtierausweis mit aktuellem Mikrochip und Tollwutimpfung mit.`, `Küche: Viele Terrassen an der Uferpromenade und am s'Alamera heißen Hunde im Freien willkommen, bestätigen Sie dies an der Tür, bevor Sie Platz nehmen.`],
    sights: {
      "Puig de Missa": `Dieser Hügel, gekrönt von einer weißgetünchten befestigten Kirche aus dem 16. Jahrhundert und einem alten Weiler, überblickt die Stadt und das Meer. Die Gassen und der Freiluftvorplatz lassen sich an der Leine begehen, das Innere der Kirche bleibt Hunden jedoch verwehrt.`,
      "Pont Vell del Riu de Santa Eulària": `Diese alte Steinbrücke römischen Ursprungs überspannt den einzigen ständig fließenden Fluss der Balearen, heute von Grün gesäumt. Ein frei zugänglicher Freiluftort an der Leine, angenehm für einen kurzen schattigen Spaziergang am Wasser.`,
      "Passeig marítim i Port Esportiu": `Die lange, von Palmen gesäumte Uferpromenade verbindet das Zentrum mit der Marina und ihren Restaurants mit Blick auf die Boote. Ein Fußgängerbereich, perfekt für einen angeleinten Spaziergang morgens oder abends, ruhiger als die benachbarten Ferienorte.`,
      "Platja de Cala Llonga": `Dieser breite Sandstrand am Kopf einer geschützten Bucht ist ein Familienklassiker südlich der Stadt. An diesem bewachten Strand sind Hunde während der Badesaison verboten, zielen Sie stattdessen auf eine unbewachte Felsbucht.`,
      "Mercat hippy de Punta Arabí (Es Canar)": `Ibizas ältester Hippiemarkt breitet jede Woche seine Hunderte von Kunsthandwerksständen unter den Pinien von Es Canar aus. Ein Freiluftmarkt, auf dem angeleinte Hunde toleriert werden, mit einem Haustier am besten außerhalb der Stoßzeiten und großer Hitze zu besuchen.`,
      "Passeig de s'Alamera": `Diese schattige, von Platanen und Ständen gesäumte Allee führt vom Zentrum hinunter zum Meer, das lebendige Herz des örtlichen Lebens. Ein angenehmer Fußgängerspaziergang an der Leine, gesäumt von Terrassen für eine schattige Pause mit dem Hund.`,
    },
  },
  santander: {
    history: `Santander, die 170.000-Einwohner-Hauptstadt Kantabriens, schmiegt sich um eine der schönsten Buchten Nordspaniens, zwischen den grünen kantabrischen Hügeln und dem offenen Atlantik. Ein vornehmer Ferienort seit König Alfons XIII. 1912 seinen Sommerpalast auf der Halbinsel Magdalena errichtete, baute die Stadt ihr Zentrum nach dem großen Brand von 1941 nüchtern und elegant wieder auf und säumte ihre lange Uferpromenade mit der Belle-Époque-Pracht des Sardinero. Heute ist sie eine der entspanntesten Hundestädte an der spanischen Küste: Eine fast durchgehende, 8 km lange Promenade führt von der Estación Marítima vorbei an den Jardines de Pereda, um die königliche Halbinsel und entlang des Sardinero bis zum Leuchtturm Cabo Mayor, fast durchweg an der Leine begehbar. Worauf man vor allem achten muss, ist das sommerliche Strandverbot, das vom 1. Mai bis 30. September an den Stadtstränden gilt.`,
    petTips: [`Santanders Stadtstrände (Sardinero, Magdalena, Mataleñas) verbieten Hunde während der sommerlichen Badesaison vom 1. Mai bis 30. September; außerhalb dieser Zeit sind sie an der Leine erlaubt.`, `Für einen ganzjährigen Hundestrand überqueren Sie die Bucht zur Playa de Loredo in Ribamontán al Mar, die einen ausgeschilderten hundefreundlichen Bereich hat; bestätigen Sie die aktuelle Zone beim örtlichen Fremdenverkehrsamt.`, `Gehen Sie die fast durchgehende, 8 km lange Uferpromenade von der Estación Marítima bis zum Leuchtturm Cabo Mayor, flach und durchweg an der Leine hundefreundlich.`, `Die eingezäunte leinenfreie Zone (Zona de Esparcimiento Canino) im Parque de las Llamas ist der beste Auslaufort der Stadt, im Sommer zwischen 19 und 21 Uhr am belebtesten und geselligsten.`, `Kantabrien stuft bestimmte Rassen als PPP (potenziell gefährlich) ein: Sie müssen an allen öffentlichen Orten angeleint und mit Maulkorb versehen sein, und der Halter muss eine Lizenz mitführen.`],
    practicalInfo: [`Ein EU-Heimtierausweis mit gültiger Tollwutimpfung und ISO-Mikrochip ist beim Check-in in jedem haustierfreundlichen Hotel erforderlich; Spanien ist EU- und Schengen-Mitglied.`, `Städtische Verordnung: Hunde müssen an allen öffentlichen Orten angeleint sein, außer in markierten leinenfreien Zonen, Halter müssen Hinterlassenschaften aufsammeln, und PPP-Rassen sind stets angeleint und mit Maulkorb zu führen.`, `Fortbewegung: Die Stadt ist zu Fuß erreichbar; TUS-Busse sowie die FEVE- und Renfe-Alvia-Züge nehmen kleine Hunde in geschlossener Transportbox mit, größere Hunde benötigen einen Maulkorb und eine kurze Leine (sowie bei Alvia eine vorherige Genehmigung).`, `Brittany Ferries fährt von der Estación Marítima nach Plymouth und Portsmouth mit Haustierkabinen und Zwingern an Bord; für die Einreise ins Vereinigte Königreich sind ein EU-Heimtierausweis sowie ein Animal Health Certificate erforderlich.`, `Geprüfte 24/7-Tierärzte: Animals Cantabria (Av. de los Castros 73, +34 942 07 09 00) in der Stadt und das regionale Überweisungskrankenhaus Hospital Veterinario Cantabria in Guarnizo (24-Stunden-Notfall +34 608 48 38 21), etwa 12 km südlich.`],
    sights: {
      "Península de la Magdalena": `Eine 25 Hektar große königliche Halbinsel, die die Bucht im Osten abschließt, mit König Alfons XIII. Sommerpalast von 1912 als Herzstück, offenen Rasenflächen, einem kleinen Freilichtzoo und 3 km Klippenwegen mit Meerblick auf drei Seiten. Hunde sind an der Leine im gesamten Gelände und auf den Wegen willkommen; nur das Innere des Palastes und die Zoogehege sind tabu.`,
      "Playa del Sardinero": `Santanders emblematischer, 1,5 km langer, sichelförmiger Goldsandstrand, durch den Vorsprung Piquío in Primera und Segunda geteilt und von Belle-Époque-Hotels und dem Casino gesäumt. Hunde sind während der sommerlichen Badesaison (1. Mai bis 30. September) verboten, den Rest des Jahres jedoch an der Leine erlaubt, und ein leerer Sardinero bei Ebbe an einem Oktobermorgen ist einer der schönsten Hundespaziergänge im Norden.`,
      "Parque de las Llamas": `Der größte innerstädtische Park, rund 30 Hektar Rasenflächen und ein zentraler See, angelegt auf zurückgewonnenem Marschland hinter dem Sardinero. Er beherbergt eine der wichtigsten eingezäunten leinenfreien Hundezonen Santanders (Zona de Esparcimiento Canino), in der Hunde unter Aufsicht frei laufen können; im übrigen Park gilt Leinenpflicht, und PPP-Rassen sind stets angeleint und mit Maulkorb zu führen.`,
      "Faro de Cabo Mayor": `Der 1839 errichtete Leuchtturm auf dem dramatischen Vorgebirge nördlich des Sardinero, der nördlichste Punkt der Bucht und das Ende des städtischen Uferpromenadenwegs. Angeleinte Hunde können die umliegende Klippenheide und den Küstenweg zum Mataleñas-Park erkunden, mit weitem Blick auf das Kantabrische Meer; achten Sie bei starkem Wind auf die ungesicherten Klippenränder.`,
      "Parque de Mataleñas": `Ein Klippenpark zwischen dem Sardinero und dem Leuchtturm Cabo Mayor, mit Pinienhainen, offenen Rasenflächen und einem kleinen städtischen Golfplatz oberhalb wilder Buchten. Angeleinte Hunde sind auf den öffentlichen Wegen und Rasenflächen willkommen (der Golfplatz selbst ist tabu), und der Pfad bildet ein leichtes, schattiges Verbindungsstück auf dem längeren Küstenweg.`,
      "Jardines de Pereda": `Die grünen Uferanlagen zwischen der Altstadt und der Bucht, neben Renzo Pianos Kunstzentrum Centro Botín, mit Skulpturen, Teichen und schattigen Rasenflächen. Angeleinte Hunde sind überall willkommen, was sie zum natürlichen grünen Auftakt der Uferpromenade macht; das Gebäude des Centro Botín und seine Dachterrasse sind für Hunde nicht zugänglich, der umliegende Platz jedoch schon.`,
    },
  },
  'santiago-de-compostela': {
    history: `Santiago de Compostela entstand im 9. Jahrhundert aus der angeblichen Entdeckung des Grabes des Apostels Jakobus und wurde rasch zu einer der drei großen Pilgerstätten der mittelalterlichen Christenheit neben Rom und Jerusalem. Seine barock-romanische Kathedrale, seine vier von Granit umsäumten Plätze und ihr UNESCO-gelistetes historisches Zentrum (1985) sind das Ergebnis von tausend Jahren des Gehens: Pilger, ihre Esel und ihre Hunde prägten eine außergewöhnlich zuvorkommende Kultur gegenüber Reisenden mit Tieren. Die Stadt ist zudem die Hauptstadt Galiciens, einer grünen, nordatlantisch geprägten Region, was ihre 1500 mm Jahresniederschlag und ihr entschieden keltisch-iberisches Gepräge erklärt: Dudelsäcke, pulpo á feira und blühendes Heidekraut.`,
    petTips: [`Das städtische Programm 'Santiguau' listet Hotels, Cafés und Restaurants auf, die offiziell als haustierfreundlich registriert sind, prüfen Sie die Liste auf santiagoturismo.com vor der Buchung.`, `Polierte Granitpflastersteine werden im Regen sehr rutschig (1500 mm/Jahr), erwägen Sie Hundeschuhe für ältere Hunde oder Rassen mit empfindlichen Pfoten.`, `Das Innere der Kathedrale, das Museum und die Dachführung lassen keine Hunde zu (Assistenzhunde ausgenommen); planen Sie ein, dass eine Person draußen beim Hund bleibt, oder buchen Sie einen örtlichen Petsitter.`, `Die meisten öffentlichen Herbergen (albergues) auf dem Jakobsweg nehmen KEINE Hunde auf: Buchen Sie private Herbergen oder haustierfreundliche Pensionen im Voraus, besonders auf den letzten Etappen ab Sarria (Camino Francés) oder Tui (Camino Portugués).`, `Der Verein APACA vergibt die Bescheinigung 'Compostela Dog' (oder 'Perregrina') an Hunde, die den Jakobsweg vollenden, fragen Sie nach Ihrer Ankunft im Pilgerbüro danach.`],
    practicalInfo: [`Flughafen: Santiago-Rosalía de Castro (SCQ) liegt 12 km östlich, mit Flughafenbus und Taxi erreichbar; Hunde in Transportboxen fahren kostenlos im Flughafenbus mit.`, `Tierärzte: AniCura ImaVet Referencia Veterinaria (rund um die Uhr) in Costa Vella im Norden, vollwertiges Überweisungskrankenhaus mit CT und drei Operationssälen.`, `Der städtische Bus TUSSA lässt Hunde nur in geschlossenen Transportboxen zu; bei größeren Hunden bevorzugen Sie Taxi (im Ermessen des Fahrers) oder zu Fuß (kompakte Stadt).`, `Tagesausflüge: Praia do Testal in Noia (35 km, offizieller Hundestrand), A Coruña (60 km, aber Zugang seit der Verordnung von 2025 prüfen, die Hunde von den meisten Stränden verbannte), Finisterre und die Costa da Morte (90 km, Atmosphäre vom Ende der Welt).`, `Tierbedarf: Kiwoko und Tiendanimal am Stadtrand, dazu mehrere Tierarztpraxen mit angeschlossenem Laden in San Lázaro und Conxo.`],
    sights: {
      "Praza do Obradoiro": `Der monumentale Platz, der als Ziellinie des Jakobswegs dient, gerahmt von der barocken Kathedralfassade, dem Hostal dos Reis Católicos (Spaniens ältestem Hotel) und dem Pazo de Raxoi. Angeleinte Hunde sind auf dem gesamten Platz und den drei angrenzenden (Praterías, Quintana, Inmaculada) willkommen.`,
      "Parque da Alameda": `Der wichtigste öffentliche Park der Stadt, eine Belle-Époque-Promenade, die sich südlich der Altstadt erhebt, mit dem Eichenhain Carballeira de Santa Susana und dem besten Blick der Stadt auf die Kathedraltürme. Die Gemeinde hat innerhalb des Eichenhains eine eigene leinenfreie Hundezone ausgewiesen.`,
      "Parque de Bonaval": `Ein ruhiger, terrassierter Park hinter dem ehemaligen Dominikanerkloster, heute Galicisches Museum des Volkes, mit Hortensienbeeten, einem bewaldeten Hain und dem alten Klosterfriedhof auf der oberen Rasenfläche. Der Aussichtspunkt bietet wohl das schönste städtische Panorama der Stadt auf die Kathedrale.`,
      "Parque de Belvís": `Ein grünes Amphitheater, das sich unterhalb des Belvís-Klosters neigt, mit formalen Labyrinthgärten oben und einer ummauerten leinenfreien Hundezone am Südende, einer der sichersten eingezäunten leinenfreien Stellen im Zentrum von Santiago.`,
      "Mercado de Abastos": `Galiciens bedeutendster Lebensmittelmarkt, Granithallen mit offenen Arkaden (1937), die Fischhändler, Metzger und pulperías beherbergen. Angeleinte Hunde sind in der Außenarkade und in den haustierfreundlichen Cafés direkt gegenüber dem Markt an der Praza de Abastos willkommen.`,
      "Cidade da Cultura de Galicia": `Peter Eisenmans monumentaler Architekturkomplex auf dem Monte Gaiás, mit wellenförmig gedeckten, granitverkleideten Gebäuden, eröffnet 2011. Außenplätze und Dachwege sind Tag und Nacht für angeleinte Hunde geöffnet, mit Panoramablick zurück auf das historische Zentrum.`,
    },
  },
  santorini: {
    history: `Santorin ist das Fragment einer Katastrophe: Um 1600 v. Chr. ließ die minoische Eruption, eine der gewaltigsten in der Menschheitsgeschichte, das Zentrum der Insel einstürzen und schuf die versunkene Caldera, die heute bewundert wird. Die Stadt Akrotiri, unter Asche begraben wie ein ägäisches Pompeji, zeugt von der verfeinerten Zivilisation, die hier lebte. Jahrhundertelang lebte die Insel bescheiden von ihren Weinreben, gegen den Wind zu Kränzen geflochten, und ihren Bimssteinbrüchen. Der Tourismus veränderte ab den 1970er-Jahren alles und machte die weißen Dörfer Oia und Fira zu weltweiten Symbolen des Sonnenuntergangs. Mit einem Hund muss man sich Santorin verdienen: Hitze, Menschenmassen und Treppen erfordern Planung, doch der Caldera-Weg im ersten Morgenlicht, die Strände mit schwarzem Sand und die Dörfer im Landesinneren belohnen die Mühe reichlich.`,
    petTips: [`Von Juni bis September ist die Hitze erdrückend und Schatten an der Caldera fast nicht vorhanden: Gehen Sie nur bei Sonnenauf- und -untergang spazieren, niemals in den heißen Stunden, und führen Sie stets Wasser mit.`, `Nehmen Sie mit Hund niemals den Maultierritt vom alten Hafen von Fira und meiden Sie diese rutschigen Treppen: Bevorzugen Sie die Seilbahn (Tiere werden in der Regel im Käfig oder auf dem Arm akzeptiert, vor Ort prüfen) oder die Straße.`, `Der schwarze Sand der Strände erreicht im Sommer extreme Temperaturen: Testen Sie ihn mit der Hand und beschränken Sie den Strandbesuch auf den Vormittag.`, `Die Insel hat viele streunende Katzen und Hunde, meist friedlich: Halten Sie Ihren Hund angeleint und fern von Gruppen, die von Einheimischen gefüttert werden.`, `Auf den Fähren zwischen den Inseln reisen Haustiere in der Regel auf den Außendecks oder in den haustierfreundlichen Kabinen der Reedereien: Buchen Sie früh, diese Plätze sind begrenzt.`],
    practicalInfo: [`Tierarztpraxen in Fira und den Hauptdörfern; bei ernsten Fällen kann eine Verlegung nach Athen nötig sein, tragen Sie also eine Versicherung, die dies abdeckt`, `Europäische Notrufnummer: 112; der örtliche Tierschutzverein SAWA ist eine bekannte Anlaufstelle der Insel für Tiere in Not`, `Zoohandlungen in Fira und Tierbedarfsregale in den Supermärkten der Insel; die Bestände sind begrenzt, bringen Sie das spezielle Futter Ihres Hundes mit`, `Inselbusse (KTEL): kleine Haustiere nur in Transportboxen; bei Taxis hängt die Akzeptanz vom Fahrer ab, erwähnen Sie den Hund bei der Buchung`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung für die Einreise nach Griechenland; melden Sie das Tier sowohl bei Fähren als auch bei Flügen bei der Buchung an`],
    sights: {
      "Oia": `Das meistfotografierte Dorf der Kykladen stapelt seine weißen Häuser und blauen Kuppeln am Caldera-Rand. Gehen Sie früh morgens vor den Menschenmassen an der Leine hindurch; bei Sonnenuntergang wird das Gedränge in den Gassen für einen Hund anstrengend.`,
      "Fira-Oia": `Zehn Kilometer Kammweg zwischen den beiden Dörfern, mit der Caldera darunter auf der ganzen Strecke: einer der schönsten Spaziergänge im Mittelmeerraum. Mit einem angeleinten Hund machbar, nur früh morgens und mit reichlich Wasser, die Strecke bietet keinen Schatten.`,
      "Akrotiri": `Das 'ägäische Pompeji', eine minoische Stadt, die vor 3600 Jahren durch die Eruption erstarrte, wird unter einem modernen Vordach mit erhöhten Stegen besichtigt. Wie bei griechischen archäologischen Stätten generell werden Hunde nicht zugelassen: Planen Sie einen Besuch im Wechsel.`,
      "Perissa": `Der lange Strand mit schwarzem Sand im Südosten, im Rücken vom Felsen Mesa Vouno, ist mit entspannten Tavernen gesäumt. Abseits der organisierten Liegenbereiche und außerhalb des Hochsommers ist er ein angenehmer Spaziergang mit angeleintem Hund, doch schwarzer Sand heizt sich in der Sonne schnell auf.`,
      "Ancient Thera": `Hoch oben auf dem Kamm des Mesa Vouno gelegen, vereint die antike Stadt dorische, hellenistische und römische Überreste über der Ägäis. Die archäologische Stätte lässt keine Hunde zu, doch die Serpentinenstraße hinauf bietet bereits eindrucksvolle Panoramen.`,
      "Pyrgos": `Die frühere Hauptstadt der Insel, dieses Hügeldorf rund um seine venezianische kastro bleibt erstaunlich ruhig. Seine gestuften Gassen führen an der Leine zu einem 360-Grad-Panorama über Caldera und Weinberge, fernab vom Trubel in Oia.`,
    },
  },
  scheveningen: {
    history: `Scheveningen ist Den Haags Nordseestrand-Viertel, ein ehemaliges Fischerdorf, das im 19. Jahrhundert um sein prächtiges Kurhaus von 1885 zu einem der frühesten niederländischen Seebäder wurde. Heute ist es ein lebendiger städtischer Ferienort: eine kilometerlange Boulevard, die berühmte Pier (De Pier), ein noch aktiver Fischereihafen und ein langer Sandstrand, dem geschützte Dünen den Rücken decken. Für einen Hund liegt der eigentliche Reiz in der Mischung aus einer per Straßenbahn erreichbaren Stadt und Hundestränden an beiden Enden der Küste. Der Strandzugang ist jedoch saisonal geregelt und in Zonen unterteilt: Der zentrale Badestrand schließt für Hunde vom 15. Mai bis 1. Oktober, doch der Noorderstrand im Norden und das Ende bei Kijkduin im Süden bleiben ganzjährig geöffnet, oft sogar leinenfrei.`,
    petTips: [`Saisonaler Strandzugang: Vom 1. Oktober bis 15. Mai sind Hunde am gesamten Den-Haag-Strand erlaubt; vom 15. Mai bis 1. Oktober ist der zentrale Badestrand (zwischen dem Zwarte Pad und dem Hafen) für sie tabu.`, `Zwei Strände bleiben Hunden das ganze Jahr über geöffnet: der Noorderstrand im Norden (von etwa Noorderstrand 34 Richtung Katwijk) und das Ende von Kijkduin am Zuiderstrand (ab Strandopgang 2 südwärts), oft leinenfrei.`, `Im Sommer sind Hunde den ganzen Tag an den ausgewiesenen Hundestränden bei Strandslag 1, 2, 9 und 10 erlaubt; andernorts am Zuiderstrand nur abends und nachts, von 21 bis 7 Uhr.`, `In den Dünen des Westduinpark (Natura 2000) besteht Leinenpflicht außer in der Zone Bosjes van Poot; während der Vogelbrutzeit (Mitte März bis Mitte Juli) gilt überall Leinenpflicht, bleiben Sie auf den Wegen.`, `Treffen Sie am Strand auf eine ruhende Robbe, leinen Sie Ihren Hund sofort an und halten Sie mindestens 30 Meter Abstand; führen Sie stets einen Kotbeutel mit, da Bußgelder verhängt werden.`],
    practicalInfo: [`Ein EU-Heimtierausweis mit Mikrochip und gültiger Tollwutimpfung ist beim Check-in im haustierfreundlichen Hotel erforderlich; die Niederlande sind EU- und Schengen-Mitglied.`, `Örtliche Regeln: An öffentlichen Orten gilt Leinenpflicht, Hinterlassenschaften müssen entfernt werden (mit Bußgeld bei Verstoß), führen Sie einen Kotbeutel mit; in den Dünen des Westduinpark gilt Leinenpflicht (Natura 2000), außer bei Bosjes van Poot.`, `Transport: Hunde fahren kostenlos in HTM-Straßenbahnen und -Bussen (Linien 1, 9 und 11 zur Küste); in NS-Zügen sind kleine Hunde kostenlos, größere Hunde benötigen eine Dagkaart Hond (2026 etwa 3,70 Euro), ohne Maulkorbpflicht.`, `Strandübersicht: zentraler Strand vom 15. Mai bis 1. Oktober für Hunde gesperrt; Noorderstrand und Kijkduin ganzjährig geöffnet; praktische Parkmöglichkeiten am Zwarte Pad für den nördlichen Strand.`, `Geprüfte Tierärzte: Dierenkliniek Scheveningen (Gentsestraat 3, 070-3555531) in der Stadt; Evidensia Dierenziekenhuis (Goudenregenstraat 296, 070-2060900) für Notfälle; regionale Bereitschaftsnummer 0900-2226333 (Stand 1.1.2026).`],
    sights: {
      "De Pier": `Scheveningens Wahrzeichen-Pier, die über die Nordsee hinausragt mit Terrassen, Imbissständen, einem Riesenrad und Panoramablicken zurück zur Küste. Angeleinte Hunde sind auf dem Pier-Deck erlaubt, was ihn zu einem guten Spaziergang macht, selbst wenn der Strand im Sommer für Hunde gesperrt ist; die Jahrmarktsattraktionen und Innenbereiche sind nicht für Haustiere.`,
      "Scheveningen Boulevard": `Die kilometerlange Uferboulevard, gesäumt von Restaurants, Beachclubs und Skulpturen, mit dem Meer und der Pier als Kulisse. Angeleinte Hunde sind hier ganzjährig willkommen, was sie zum idealen Ausweichspaziergang während des sommerlichen Strandverbots macht. Sie ist das lebendige Herz des Ferienorts, mit den Straßenbahnlinien 1, 9 und 11 an das übrige Den Haag angebunden.`,
      "Westduinpark": `Ein hügeliger Küstendünenpark zwischen Scheveningen und Kijkduin mit offenem Sand, Strandhafer und niedrigem Wald, geschützt als Natura-2000-Gebiet (Westduinpark & Wapendal). Er zählt zu den schönsten Hundespaziergängen in Den Haag, mit Meerblick von den hohen Dünen. Auf dem größten Teil des Schutzgebiets müssen Hunde angeleint bleiben, um brütende Vögel und weidende Schafe zu schützen.`,
      "Bosjes van Poot": `Eine geschützte Tasche aus Dünenwald im Vogelwijk-Viertel, durchsetzt mit Kiefern und Eichen, Teil des weiteren Westduinpark. Die Gemeinde hat sie offiziell zur leinenfreien Zone erklärt, hierher kommen die örtlichen Hunde nahe Scheveningen zum freien Auslauf. Der leinenfreie Auslauf pausiert während der Vogelbrutzeit (etwa Mitte März bis Mitte Juli).`,
      "Kijkduin hondenstrand": `Am südlichen Ende der Küste ist der Zuiderstrand ab Strandopgang 2 südwärts bis Monster der hundefreundlichste Strand in Den Haag, an dem Hunde das ganze Jahr über ohne saisonale Einschränkung leinenfrei laufen dürfen. Von den Dünen des Westduinpark gerahmt, ist er ruhiger als das zentrale Scheveningen und wird im Hochsommer zur ersten Wahl, wenn die Strände des Ferienorts für Hunde schließen.`,
      "Scheveningen Haven": `Der aktive Fischereihafen, das historische Herz des alten Dorfes, mit Trawlern, Kais und Fischrestaurants entlang der Dr. Lelykade, ein völliger Szenenwechsel gegenüber der Strandboulevard. Die Kais eignen sich für einen angenehmen angeleinten Spaziergang mit Meeresduft und dem Treiben der Flotte. Viele Hafenrestaurants haben Außenterrassen, auf denen ein angeleinter Hund willkommen ist.`,
    },
  },
  sanxenxo: {
    history: `Sanxenxo, ein Ferienort mit rund 17.000 Einwohnern an der Ría von Pontevedra im Herzen der galicischen Rías Baixas, entwickelte sich aus Fischer- und Konservendörfern zu einem der beliebtesten Sommerziele Nordwestspaniens, getragen von seinem atlantischen Licht, Meeresfrüchten und Albariño-Wein. Sein Mittelpunkt ist die Praia de Silgar, ein 750 m langer, mit der Blauen Flagge ausgezeichneter Stadtstrand, verlängert durch die Uferpromenade Silgar-Baltar, die die Marina mit Portonovo verbindet. Für Hundehalter ist Sanxenxo herrlich, erfordert aber etwas Planung: Die Strände verbieten Hunde während der Hauptbadesaison (1. Juni bis 30. September), die Stadt hat keinen eigenen Hundestrand, und die vielbeworbenen Tagesausflüge zu den Inseln Cíes und Ons sind für Haustiere tabu, da es sich um einen Nationalpark handelt. Angeleinte Hunde genießen jedoch das ganze Jahr über die langen Küstenpromenaden, und die ganzjährigen Hundestrände von O Grove liegen etwa zwanzig Kilometer entfernt.`,
    petTips: [`Sanxenxos Strände, einschließlich Silgar, verbieten Hunde während der Badesaison (1. Juni bis 30. September); außerhalb der Saison sind angeleinte Hunde erlaubt.`, `Für ein ganzjähriges Hundeschwimmen fahren Sie zu den Hundestränden von O Grove (O Espiño und O Portiño bei San Vicente do Mar), etwa 20 km entfernt.`, `Besteigen Sie mit Ihrem Hund niemals eine Fähre zu den Inseln Cíes oder Ons: Sie sind ein Nationalpark, in dem Haustiere verboten sind, Blindenführhunde ausgenommen.`, `Sanxenxo hat keinen Bahnhof: Reisen Sie über die Flughäfen Vigo (VGO) oder Santiago (SCQ) und ein Auto an, oder mit dem Bus ab Pontevedra; ein Auto ist bei Weitem am einfachsten.`, `Hunde müssen in der Öffentlichkeit angeleint sein, potenziell gefährliche (PPP) Rassen mit Maulkorb; das atlantische Klima ist mild, aber feucht, packen Sie also Regenausrüstung und Zeckenschutz ein.`],
    practicalInfo: [`Strände: kein Hundestrand in der Gemeinde; Hunde vom 1. Juni bis 30. September verboten, ganzjährige Hundestrände in O Grove (etwa 20 km).`, `Tierärzte: Clínica Veterinaria Portonovo (Ctra. de la Lanzada 28, +34 986 691 551, außerhalb der Öffnungszeiten +34 696 599 164) und Centro Veterinario Sanxenxo (+34 986 691 845); die Notrufnummer 112 ist auf Menschen ausgerichtet.`, `Transport: kein Bahnhof in Sanxenxo, der nächste liegt in Pontevedra (etwa 30 km); Monbus-Busse nehmen kleine Hunde in Transportboxen mit, ein Auto wird empfohlen; Flughäfen Vigo (VGO) und Santiago (SCQ).`, `Inseln: Der Nationalpark der Atlantischen Inseln (Cíes, Ons) verbietet alle Haustiere außer Blindenführhunden; planen Sie keinen Bootsausflug mit Ihrem Hund.`, `Einreise: EU-Besucher benötigen einen EU-Heimtierausweis, Mikrochip und gültige Tollwutimpfung; Besucher von außerhalb der EU benötigen ein Tiergesundheitszeugnis, prüfen Sie die MAPA-Vorschriften.`],
    sights: {
      "Praia de Silgar": `Sanxenxos ikonischer, 750 m langer, mit der Blauen Flagge ausgezeichneter Feinsandstrand im Herzen der Stadt, gerahmt von Promenade und Marina. Angeleinte Hunde sind außerhalb der Badesaison erlaubt, jedoch vom 1. Juni bis 30. September vom Sand verbannt.`,
      "Paseo Marítimo Silgar-Baltar": `Sanxenxos Vorzeigepromenade, etwa 6 km Hin- und Rückweg von der Marina vorbei an den Stränden Silgar und Baltar sowie dem Park Punta Vicaño bis nach Portonovo. Ein flacher, angeleinter Küstenspaziergang, ideal ganzjährig, wenn die Strände im Sommer für Hunde schließen.`,
      "Praia da Lanzada": `Ein riesiger, wilder Atlantikstrand mit Dünen und einem von einer Kapelle gekrönten Vorgebirge auf der Landenge Richtung O Grove, hervorragend für einen angeleinten Spaziergang außerhalb der Saison. Im Sommer sind Hunde auf dem Sand verboten, und Sie sollten zum Schutz der Dünen auf den Wegen bleiben.`,
      "Praias caninas de O Espiño e O Portiño": `Die nächstgelegenen offiziellen Hundestrände, zwei kleine Buchten bei San Vicente do Mar (O Grove) etwa 20 km entfernt, neben der Marina Pedras Negras. Heller Sand und ruhiges, flaches Wasser, für Hunde ganzjährig geöffnet, auch im Sommer.`,
      "Combarro": `Eines der hübschesten Dörfer Galiciens, etwa 15 km entfernt, berühmt für seine Uferreihe aus hórreos (steinernen Getreidespeichern), cruceiros und schmalen Fischergassen an der Ría. Angeleinte Hunde sind willkommen, um die Straßen und die Kaipromenade zu erkunden.`,
      "Illas Cíes e Ons": `Die Inseln Cíes und Ons, Juwelen des Nationalparks der Atlantischen Inseln, sind die bekanntesten Bootsausflüge der Region, doch alle Haustiere sind dort zum Schutz des Ökosystems verboten, Blindenführhunde ausgenommen. Besteigen Sie das Boot nicht mit Ihrem Hund; organisieren Sie für diesen Tag einen Sitter.`,
    },
  },
  seattle: {
    history: `1851 am Ufer der Elliott Bay gegründet, wuchs Seattle zunächst durch die Holzwirtschaft und dann durch den Klondike-Goldrausch von 1897, der die Stadt zum Ausrüstungshafen für Alaska machte. Boeing und später Microsoft und Amazon erledigten den Rest. Die Stadt liegt auf einem schmalen Streifen zwischen dem Puget Sound und dem Lake Washington, mit dem Mount Rainier bei klarem Wetter im Süden. Für einen Hund ist Seattle eine offen hundefreundliche Stadt: mehr als ein Dutzend ausgewiesener leinenfreier Bereiche, eine Craft-Bier-Kultur mit überdachten, beheizten Biergärten, die Hunde das ganze Jahr über willkommen heißen, und Busse, die Hunde jeder Größe mitnehmen. Der Preis dafür ist streng: Die Parkvorschriften verbieten Hunden jeden Strand und jede Badezone der Stadt, ob an der Leine oder frei.`,
    petTips: [`Strände: Seattles Parkvorschriften verbieten Hunden Strände, Badezonen sowie Teiche, Brunnen und Bäche, ob an der Leine oder frei. Alki Beach, der Sand von Golden Gardens und die Uferlinie von Discovery Park sind allesamt gesperrt.`, `Bußgelder: Der Seattle Animal Shelter kontrolliert wirklich; rund 50 bis 150 Dollar für einen freilaufenden Hund oder unterlassenes Aufsammeln, und bis zu 500 Dollar werden für einen Hund am Strand genannt.`, `Schwimmen: Der einzige legale Ort innerhalb der Stadt ist der leinenfreie Bereich im Magnuson Park am Lake Washington. Für Salzwasser benötigen Sie den Marina Beach Park in Edmonds oder den Double Bluff Beach auf Whidbey Island.`, `Sommer: Juli und August kombinieren Hitzespitzen über 30 °C mit Waldbrandrauch, der von Osten des Bundesstaates hereinzieht. Kurzköpfige Rassen, Welpen, ältere Hunde und Tiere mit Herz- oder Lungenerkrankungen sind am stärksten gefährdet; gehen Sie früh spazieren und wischen Sie Fell, Maul und Augen danach ab.`, `Robben: Seehunde werfen ab etwa April ihre Jungen an den Ufern des Puget Sound. Halten Sie etwa 100 Yards Abstand zu einem ruhenden Jungtier und legen Sie sofort die Leine wieder an.`],
    practicalInfo: [`Einreise in die Vereinigten Staaten: Jeder Hund muss mindestens sechs Monate alt sein, einen ISO-konformen Mikrochip tragen, gesund erscheinen und mit einer online ausgefüllten CDC Dog Import Form-Empfangsbestätigung reisen. Aus einem Hochrisikoland für Tollwut sind zusätzliche Tollwutunterlagen erforderlich, und der Hund muss per Flugzeug an einem Flughafen mit CDC-registrierter Tierversorgungseinrichtung ankommen, nach Reservierung.`, `Transport: King-County-Metro-Busse nehmen einen angeleinten Hund jeder Größe mit; ein kleiner Hund auf dem Schoß ist kostenlos, jeder andere Hund benötigt ein zweites bezahltes Ticket. Bei Sound Transit (Link, Sounder, ST Express) beschränken die veröffentlichten Regeln Haustiere trotz der 2025er Abstimmung für kostenlose angeleinte Hunde weiterhin auf kleine Transportboxen, prüfen Sie also am jeweiligen Tag.`, `Fähren: Seit dem 1. Juli 2026 lässt Washington State Ferries einen Hund im Geschirr oder in der Box auf den Fahrzeugdecks, in den Außenbereichen für Passagiere und in markierten Bereichen im Kabineninneren am Ende fern der Kombüse zu. Nicht auf Sitzen oder Tischen erlaubt.`, `Flughafen: Am Seattle-Tacoma (SEA) müssen Haustiere im gesamten Main Terminal in ihren Transportboxen bleiben. Innenauslaufflächen hinter der Sicherheitskontrolle befinden sich in den Concourses A, D, S, N und B sowie in der International Arrivals Facility, dazu vier Außenbereiche vor der Sicherheitskontrolle.`, `Geprüfte Tierärzte: Veterinary Emergency Group, 1827 15th Avenue W in Interbay, +1 564 888-4898, rund um die Uhr geöffnet; Emerald City Emergency Clinic, 4102 Stone Way N in Wallingford, +1 206 634-9000, seit 1994 rund um die Uhr; Urban Animal Capitol Hill, 909 E Thomas Street, +1 206 329-5337, ohne Termin Montag bis Freitag 8 bis 20 Uhr. 911 ist nur für Menschen.`],
    sights: {
      "Warren G. Magnuson Park": `Etwa 3,4 Hektar Gras, Kies und Gestrüpp, die zum Ufer des Lake Washington an der 7400 Sand Point Way NE hinunterführen. Es ist der einzige leinenfreie Bereich in Seattle mit Wasserzugang und damit der einzige Ort in der Stadt, an dem ein Hund legal schwimmen kann, mit einem separaten Gehege für kleine und schüchterne Hunde direkt südlich des Eingangskiosks. Täglich von 4 bis 23:30 Uhr geöffnet, Fahrräder und Joggen sind im Inneren nicht erlaubt.`,
      "Marymoor Park": `Sechzehn Hektar Wiese, Kieswege und Bäume im King County in Redmond, mit Zugang zum Sammamish River: der mit Abstand größte leinenfreie Bereich der Region. Seit der Eröffnung der Stadtbahnverlängerung Downtown Redmond liegt die Marymoor Village Station in Gehweite an der Nordostecke des Parks. Außerhalb der markierten Grenze wird die Leine wieder angelegt, und professionelle Hundeausführer benötigen eine Genehmigung des County.`,
      "Olympic Sculpture Park (SAM)": `Die kostenlose Freiluft-Erweiterung des Seattle Art Museum, angelegt auf einem sanierten Industriegelände, das sich von Belltown hinunter zum Ufer der Elliott Bay zieht, mit monumentalen Werken von Calder, Serra und Oldenburg. Angeleinte Haustiere sind ausdrücklich im gesamten Gelände willkommen, mit einer Leine von höchstens 1,8 Metern und Aufsammelpflicht; nur Servicehunde dürfen den Pavillon und das Amphitheater betreten.`,
      "Pike Place Market": `Der älteste durchgehend betriebene Bauernmarkt des Landes, seit 1907 oberhalb der Elliott Bay geöffnet, mit seinen Blumenständen, Fischhändlern und einem Gewirr von Gassen. Behandeln Sie ihn nur als Außenbesuch: Der Markt verbietet Hunde, Katzen und andere Haustiere in seinen Gebäuden, einschließlich der Main Arcade, und lässt im Inneren nur ausgebildete Servicehunde zu. Die Straßen und Gehwege bleiben für Haustiere offen, kommen Sie also vor 9 Uhr, solange die Menschenmassen es noch zulassen.`,
      "Gas Works Park": `Die verrosteten Krackanlagen einer ehemaligen Kohlevergasungsanlage stehen mitten in einem öffentlichen Park auf einer Landzunge mit Blick auf die Skyline über den Lake Union. Kite Hill bietet den besten kostenlosen Ausblick der Stadt, und der Burke-Gilman Trail verläuft am hinteren Rand des Parks. Angeleinte Hunde sind willkommen, und der Park ist von 6 bis 22 Uhr geöffnet, doch das Betreten des Wassers ist verboten: Das Seesediment enthält gefährliche Stoffe.`,
      "Discovery Park": `Seattles größter Park, 216 Hektar ehemaliges Militärgelände auf der Magnolia-Klippe, mit Waldwegen, offenen Wiesen und Blicken über den Puget Sound zu den Olympic Mountains. Angeleinte Hunde sind auf den Wegen willkommen, doch es gibt überhaupt keinen leinenfreien Bereich, und der Strand unterhalb der Klippe ist zusammen mit der Uferlinie am West-Point-Leuchtturm für sie vollständig gesperrt.`,
    },
  },
  sete: {
    history: `1666 aus einer Entscheidung Colberts geboren, der für den Canal du Midi einen Mittelmeerhafen suchte, wuchs Sète zwischen dem Meer und der Lagune von Thau am Fuß des Mont Saint-Clair heran. Der von Ludwig XIV. gewollte Hafen zog italienische Fischer aus Gaeta und Cetara an, deren Nachfahren noch heute das Viertel Pointe Courte bevölkern und der Stadt ihre tielle, ihre macaronade und ihren singenden Akzent gaben. Auf dem Canal Royal bleiben die Wasserstechturniere, die seit der Hafeneinweihung abgehalten werden, die große Sommerliturgie, die im Saint-Louis-Fest gipfelt. Die eigenwillige Insel schenkte Frankreich zudem zwei Dichter: Paul Valéry, der auf dem Meeresfriedhof ruht, den er besang, und Georges Brassens, unweit seines Corniche-Strands begraben. Zwischen Kanälen, überdachter Markthalle, Fischauktion und Kilometern wilder Lido-Küste in Richtung Marseillan ist Sète eine wunderbare Stadt, die man zu Fuß mit einem Hund entdecken kann.`,
    petTips: [`An den bewachten Stränden der Corniche und des Lido sind Hunde während der Badesaison verboten: Zielen Sie früh morgens auf die unerschlossenen Abschnitte des Lido Richtung Marseillan, und ab Oktober, bis die Rettungsschwimmerposten wieder öffnen, gehört die gesamte Sandbank wieder Ihnen.`, `Der Aufstieg zum Mont Saint-Clair ist steil, und der Asphalt wird im Sommer sehr heiß: Gehen Sie vor 10 Uhr oder am Ende des Tages hinauf, mit Wasser für zwei, denn Schatten gibt es erst im Wald von Pierres Blanches.`, `Während des Saint-Louis-Stechturniers Ende August sättigen Menschenmassen, Blaskapellen und Böller die Kais: Bevorzugen Sie zu dieser Zeit bei einem lärmempfindlichen Hund die Ufer des Thau oder das Viertel Pointe Courte.`, `Lassen Sie Ihren Hund an den Ufern der Lagune von Thau nicht das Brackwasser trinken und nicht in der Nähe der Muschelfarmen herumstöbern: scharfe Schalen für die Pfoten und ein garantiertes Verdauungsrisiko.`, `Die Busse des Netzes Sète agglopôle nehmen kleine Hunde in Transportboxen mit; in TER-Zügen nach Montpellier oder Agde zahlen Haustiere einen ermäßigten Fahrpreis, bei großen Hunden werden Leine und Maulkorb empfohlen.`],
    practicalInfo: [`Mehrere Tierarztpraxen in Sète und den Orten des Thau-Beckens für die routinemäßige Versorgung; bei nächtlichen Notfällen führt Sie die 3115 (die kostenlose nationale tierärztliche Bereitschaftsnummer) zum diensthabenden Dienst, mit 24-Stunden-Kliniken in Montpellier`, `Europäische Notrufnummer: 112; Feuerwehr: 18`, `Zoohandlungen am Stadtrand (Zone Balaruc) und Tierbedarfsregale in den Supermärkten des Zentrums; Hundepflegesalons in der Stadt`, `Busse von Sète agglopôle: kleine Hunde in Transportboxen; TER-Züge nach Montpellier, Agde und Béziers: ermäßigtes Haustierticket; Lagunen-Shuttleboote in der Saison: fragen Sie beim Einsteigen`, `Hunde sind an den bewachten Stränden während der Sommersaison (durch Verordnung) und in der überdachten Markthalle verboten; in der Stadt gilt Leinenpflicht, Kotbeutelspender gibt es an den Kais und auf dem Mont Saint-Clair`],
    sights: {
      "Mont Saint-Clair": `Der Gipfel, der die eigenwillige Insel mit 175 Metern überragt, bietet ein immenses Panorama über die Stadt, den Lido, die Lagune von Thau und an klaren Tagen die Pyrenäen. Der Aufstieg über die Treppen des oberen Viertels und dann durch den Wald von Pierres Blanches ist ein hervorragender angeleinter Spaziergang, am besten in den kühlen Stunden.`,
      "Canal Royal": `Die wasserreiche Hauptschlagader der Stadt reiht bunte Fassaden, Fischerboote und die Pontons der Stechvereine aneinander, deren Champions den ganzen Sommer über mit Lanze und Schild kämpfen. Die Kais eignen sich hervorragend für einen angeleinten Bummel, und die Kai-Terrassen akzeptieren am Tischfuß oft wohlerzogene Hunde.`,
      "Plage de la Corniche": `Der von Brassens geliebte Stadtstrand eröffnet den langen Sandlido, der bis Marseillan reicht. Hunde sind in der Sommersaison in den bewachten Zonen verboten: Weichen Sie früh morgens auf die unerschlossenen Abschnitte des Lido Richtung Triangle de Villeroy aus, und außerhalb der Saison auf die gesamte Sandbank.`,
      "Étang de Thau": `Die große Lagune mit ihren Muschelfarmen versorgt Bouzigues, Mèze und Marseillan, Austernzuchtdörfer, in denen man Austern und Muscheln mit Blick aufs Wasser probiert. Die Ufer und kleinen Häfen eignen sich gut für angeleinte Spaziergänge, und viele Verkostungshütten akzeptieren Hunde auf ihren Terrassen.`,
      "Espace Georges Brassens": `Das Museum, das dem berühmtesten Sohn der Stadt gewidmet ist, spielt seine Stimme über Kopfhörer entlang eines beweglichen Rundgangs ab, gegenüber dem Friedhof Py, in dem er ruht. Hunde betreten das Museum nicht: Besuchen Sie es abwechselnd, denn der benachbarte Park Simone-Veil bietet angenehmes schattiges Warten.`,
      "Halles de Sète": `Der Bauch von Sète quillt über von tielles, Bouzigues-Austern, Fisch von der Auktion und Theken, an denen man inmitten fröhlichen Trubels snackt. Wie in allen überdachten Lebensmittelmärkten dürfen Hunde nicht hinein: Die Terrassen der Nachbarstraßen lassen Sie Ihre Einkäufe gemeinsam genießen.`,
    },
  },
  saranda: {
    history: `Sarandë, die sonnenverwöhnte Hauptstadt der albanischen Riviera, liegt der griechischen Insel Korfu über eine schmale Meerenge gegenüber, ihre hufeisenförmige Bucht von einer langen Uferpromenade gesäumt. Die Stadt trägt den Namen eines frühen byzantinischen Klosters, der Agioi Saranta (Vierzig Heilige), und ihre vielschichtige Vergangenheit reicht von der griechischen und römischen Antike über die osmanische Herrschaft bis zu Jahrzehnten kommunistischer Isolation unter Enver Hoxha, als Albanien von der Welt abgeriegelt war. Seit sich das Land in den 1990er-Jahren wieder öffnete, ist Sarandë zu seinem führenden Sommerferienort geworden, einer wachsenden Wand weißer Wohnblocks rund um die Bucht. Für einen Hundehalter ist es ein Ort der Kontraste: extreme Augusthitze, Menschenmassen und Verkehr, aber auch die außergewöhnlichen UNESCO-Ruinen des nahen Butrint, die Quelle Blaues Auge, der Sonnenuntergang an der Festung Lëkurësi und ruhigere Spaziergänge am Wasser in der Nebensaison.`,
    petTips: [`Im August ist die Hitze extrem (35 °C und mehr) und die Menschenmenge auf dem Höhepunkt: Besuchen Sie Butrint, Lëkurësi und die Promenade früh morgens oder abends, niemals mittags, und führen Sie stets Wasser mit.`, `Ohrmarkierte Streunerhunde (von der Gemeinde sterilisiert und geimpft) halten sich an der Promenade auf; meist ruhig, halten Sie Ihren Hund angeleint und geben Sie ihnen Raum.`, `In Butrint sind angeleinte Hunde auf den Außenwegen erlaubt, jedoch nicht im Museum; Schatten ist knapp, bringen Sie also Wasser mit und meiden Sie die heißen Stunden.`, `Die Strände von Ksamil sind im Hochsommer überfüllt und hundeunfreundlich: Bevorzugen Sie Mai oder Oktober für ruhigen, hundefreundlichen Sand.`, `Asphalt und Fels an der Uferpromenade werden an Sommernachmittagen glühend heiß: Testen Sie den Boden mit dem Handrücken, und kühlen Sie die Pfoten in den Bächen unterhalb des Blauen Auges statt in der geschützten Quelle selbst.`],
    practicalInfo: [`Albanien liegt außerhalb der EU: Für die Rückkehr in die EU mit Ihrem Haustier sind ein ISO-Mikrochip, eine Tollwutimpfung und ein Antikörpertitertest gegen Tollwut (Blutentnahme frühestens 30 Tage nach der Impfung, gefolgt von einer vorgeschriebenen Wartezeit) erforderlich; planen Sie mehrere Monate im Voraus.`, `Fähren und Katamarane verbinden Sarandë in 30 bis 70 Minuten mit Korfu (Griechenland); Hunde werden je nach Betreiber akzeptiert, wobei Maulkorb, Leine und aktuelle Gesundheitsunterlagen erforderlich sind, bestätigen Sie also die Regeln vorab am Schalter.`, `Fortbewegung: Es gibt keine Eisenbahn; die Stadt ist zu Fuß erreichbar, und Taxis oder furgon-Minibusse bedienen Butrint, Ksamil und das Blaue Auge, wobei ein Hund im Ermessen des Fahrers willkommen ist.`, `Die tierärztliche Versorgung in Sarandë ist begrenzt; führen Sie die Gesundheitsunterlagen und etwaige Medikamente Ihres Haustiers mit sich, umfassendere Kliniken finden sich in Gjirokastra oder Tirana; allgemeine Notrufnummer 112 (Rettungsdienst 127).`, `Die Sommerhitze ist von Juni bis September strapaziös, und die Uferpromenade ist ein langer, schattenloser Betonstreifen: Bleiben Sie in der Nähe der ruhigeren nördlichen Promenade und planen Sie Ausflüge für die kühlen Stunden.`],
    sights: {
      "Sarandë Lungomare": `Der lange Fußgängerboulevard entlang der gesamten hufeisenförmigen Bucht, mit Palmen, Cafés und Blick auf Korfu, das Herz des Lebens in Sarandë, besonders in der abendlichen Kühle. Angeleinte Hunde sind auf der gesamten Länge willkommen; gehen Sie im Sommer früh morgens oder nach Sonnenuntergang spazieren, da der Beton die Hitze speichert.`,
      "Lëkurësi Castle": `Eine osmanische Festung aus dem 16. Jahrhundert auf dem Hügel südlich der Stadt, die das schönste Panorama über die Bucht, Ksamil und Korfu bietet und bei Sonnenuntergang atemberaubend ist. Das Gelände und die offenen Wehrgänge lassen sich mit einem angeleinten Hund frei begehen; nur der Innenraum des Restaurants kann eingeschränkt sein.`,
      "Butrint National Park": `Eine UNESCO-gelistete archäologische Stätte 18 km südlich, die ein griechisches Theater, ein römisches Forum, ein frühchristliches Baptisterium und eine venezianische Festung in einer bewaldeten Lagune schichtet, eine der schönsten Albaniens. Angeleinte Hunde sind auf den Außenwegen des Parks erlaubt; bringen Sie Wasser mit, da Schatten knapp und die Sommertage strapaziös sind.`,
      "Syri i Kaltër (Blue Eye)": `Eine tiefblaue Karstquelle etwa 25 km östlich, deren eiskaltes Wasser aus unbekannter Tiefe im Herzen eines Eichenwalds emporquillt. Angeleinte Hunde sind auf dem Weg und rund um das Becken erlaubt; das Baden in der geschützten Quelle ist verboten, doch die flussabwärts gelegenen Bäche lassen einen Hund die Pfoten kühlen.`,
      "Synagogue-Basilica": `Freiluftruinen im Zentrum von Sarandë, wo eine Synagoge aus dem 5. Jahrhundert mit bemerkenswerten Bodenmosaiken später zu einer christlichen Basilika umgebaut wurde, ein seltenes Zeugnis der antiken Vielfalt der Stadt. Die eingezäunte Stätte lässt sich mit einem angeleinten Hund von ihrem Rand aus betrachten; die Mosaike sind außerhalb der Saison oft zum Schutz abgedeckt.`,
      "Ksamil": `Ein Strandort 15 Minuten südlich, berühmt für seine kleinen Buchten mit weißem Sand und erschwimmbaren Inselchen, eine der meistfotografierten Küstenlandschaften Albaniens. Im Juli und August überfüllt und hundeunfreundlich; kommen Sie in der Nebensaison (Mai, Oktober) für ruhigen Sand und stille Buchten.`,
    },
  },
  saturnia: {
    history: `Saturnia, ein winziger Weiler in der toskanischen Maremma, trägt nach lokaler etruskischer und römischer Legende den Namen des Gottes Saturn, was ihn zu einer der ältesten Städte Italiens macht. Was Besucher heute anzieht, ist weniger die antike Vergangenheit als das Wasser: die Cascate del Mulino, eine Reihe natürlicher Kalksteinbecken, geformt von schwefelhaltigem, mit 37,5 °C sprudelndem Wasser, kostenlos und rund um die Uhr, das ganze Jahr über zugänglich. Der ummauerte Weiler bewahrt die Porta Romana, das einzige seiner vier antiken Tore, das noch steht, und die Rocca Aldobrandesca, eine von Siena restaurierte Festung aus dem 12. Jahrhundert. Direkt vor den Toren betreibt das kostenpflichtige Terme di Saturnia Natural Spa & Golf Resort ein VIPets-Programm, das Hunde ausdrücklich an seiner Bar, in seiner Trattoria und entlang der Golfplatzwege willkommen heißt. Ohne Meer, ohne Menschenmassen ist Saturnia die ländlichste und ruhigste Basis der Toskana zum Reisen mit Hund, sofern man ein Auto hat.`,
    petTips: [`Hunde sind rund um die Cascate del Mulino willkommen, jedoch aus hygienischen Gründen nicht in den Badebecken selbst.`, `Das Resort Terme di Saturnia heißt Hunde über sein VIPets-Programm willkommen (Bar, Trattoria, Golfwege, eigener Rasen), jedoch nicht im eigenen Thermalbecken.`, `Ein Auto ist nahezu unverzichtbar: Es gibt weder Bahnhof noch Flughafen in Saturnia, und nur eine dünne Busverbindung nach Manciano.`, `Im Sommer übersteigen die Tagestemperaturen häufig 30 °C: Gehen Sie die Vie Cave und das Dorf früh morgens oder abends ab.`, `Rinder weiden in der umliegenden Landschaft der Maremma: Halten Sie Ihren Hund auf den ländlichen Wegen angeleint.`],
    practicalInfo: [`Kein Bahnhof und kein Flughafen in Saturnia; die nächstgelegenen sind Grosseto und Albinia (40 bis 50 Minuten mit dem Auto) sowie die Flughäfen Rom (2 Std. 15) oder Pisa (2 Std. 30).`, `Örtlicher Tierarzt: Ambulatorio Veterinario Peverini, Via Martiri della Libertà, Manciano (8 km), +39 0564 629150, nach Termin, einschließlich Notfallversorgung.`, `24-Stunden-Tiernotfall: Clinica Veterinaria Costa d'Argento, Strada dell'Airone 4, Albinia (Orbetello), +39 0564 865534, etwa 40 km südlich.`, `Der Hauptparkplatz an den Cascate del Mulino ist kostenpflichtig (etwa 2,50 EUR/Stunde oder 10 EUR/Tag); kostenlose Parkmöglichkeiten am Straßenrand gibt es in Dorfnähe.`, `Italien kennt keine Quarantäne, doch EU-Reisende benötigen einen EU-Heimtierausweis mit gültiger Tollwutimpfung und Mikrochip.`],
    sights: {
      "Cascate del Mulino": `Die berühmten kostenlosen, rund um die Uhr zugänglichen heißen Quellen, in Kalkstein gemeißelt von schwefelhaltigem Wasser mit 37,5 °C. Angeleinte Hunde sind auf dem Naturgelände willkommen, jedoch aus hygienischen Gründen nicht in den Badebecken selbst.`,
      "Porta Romana": `Das einzige der vier römischen Tore Saturnias, das noch steht, öffnet sich zur Linie der antiken Via Clodia. Leicht in wenigen Minuten von den öffentlichen Straßen aus an der Leine zu besichtigen.`,
      "Rocca Aldobrandesca": `Eine Festung aus dem 12. Jahrhundert, erbaut von den Aldobrandeschi und im 15. Jahrhundert von Siena restauriert, direkt neben der Porta Romana. Von außen an der Leine zu besichtigen; das Innere ist für Besucher nicht zugänglich.`,
      "Terme di Saturnia Natural Spa & Golf Resort": `Das kostenpflichtige Thermalresort neben dem Dorf betreibt ein VIPets-Programm, das Hunde ausdrücklich an seiner Bar, in seiner Trattoria und entlang der Golfplatzwege willkommen heißt, mit Körbchen und Napf im Zimmer. Hunde sind im Thermalbecken selbst nicht zugelassen.`,
      "Pitigliano": `Mit dem Beinamen 'Klein-Jerusalem' ist diese vollständig aus Tuffstein erbaute, auf einer Klippe thronende Stadt schon von der Anfahrtsstraße aus weithin sichtbar, 25 km von Saturnia entfernt. Ihre gepflasterten Gassen sind an der Leine begehbar.`,
      "Vie Cave": `In den Tuffstein geschnittene Hohlwege aus etruskischer Zeit verbinden Pitigliano mit Sovana, kühl und schattig selbst im Sommer. Angeleinte Hunde sind auf dieser rund 7 km langen Strecke willkommen, das Gelände ist jedoch stellenweise uneben.`,
    },
  },
  setubal: {
    history: `Setúbal liegt südlich von Lissabon am nördlichen Ufer der Sado-Mündung, wo die Kalksteinhügel der Arrábida in den Atlantik abfallen. Ein aktiver Fischereihafen, die Stadt lebt noch immer im Rhythmus der Boote, die Sardinen und Sepia anlanden, die örtliche Spezialität, serviert als choco frito. Ihre Geschichte reicht bis zu den Römern zurück, die hier Fisch salzten und Garum herstellten; das Castelo de São Filipe aus dem 16. Jahrhundert wacht noch immer über die Bucht. Vor allem aber ist Setúbal das Tor zu zwei Naturwundern: dem Naturschutzgebiet der Sado-Mündung, Heimat einer ansässigen Population Großer Tümmler, und dem Naturpark Arrábida mit seinen weißen Sandstränden und türkisfarbenem Wasser. Für den Reisenden mit Hund vereint sie einen mit Azulejos verzierten Markt, Bergwege, eine Uferpromenade und eine Fähre zu den wilden Stränden der Halbinsel Tróia.`,
    petTips: [`Sommerliches Hundeverbot an den bewachten Stränden der Arrábida (Juni bis September): Bevorzugen Sie außerhalb der Saison die wilden Buchten oder den langen Strand von Tróia.`, `Die Nortada, ein beständiger Nordwind, weht oft an Sommernachmittagen: Führen Sie Wasser mit und suchen Sie Schatten, besonders auf den exponierten Wegen der Arrábida.`, `Kräftige atlantische Sommerhitze: Gehen Sie früh morgens oder abends spazieren, da Sand und Fels mittags glühend heiß werden.`, `Delfintouren in der Sado-Mündung: Nicht jeder Anbieter nimmt Hunde an Bord, bestätigen Sie dies also vor der Buchung und bringen Sie eine Rettungsweste für Ihr Haustier mit.`, `Bei einem tierärztlichen Notfall wählen Sie 112 (die EU-Notrufnummer); in Setúbal sind Tierarztpraxen tätig.`],
    practicalInfo: [`Portugal ist EU- und Schengen-Mitglied: Ein EU-Heimtierausweis plus gültige Tollwutimpfung plus ISO-Mikrochip genügt bei Einreise aus jedem EU-Land.`, `Nächster Flughafen: Lissabon (LIS), etwa 50 km entfernt; erreichbar mit dem Auto oder per Zug/Bus über Lissabon (Hunde willkommen).`, `Die Fähre Setúbal-Tróia verkehrt je nach Saison alle 30 bis 60 Minuten; Hunde sind für die Überfahrt zu den Stränden der Halbinsel erlaubt.`, `Währung: Euro. Städtischer und regionaler Verkehr: Hunde an der Leine und mit Maulkorb oder in einer Transportbox je nach Größe, bestätigen Sie dies beim Betreiber.`, `Beste Reisezeit: Mai/Juni und September/Oktober, um sommerliche Menschenmassen und Strandverbote zu vermeiden.`],
    sights: {
      "Reserva Natural do Estuário do Sado": `Ein riesiges Mündungsschutzgebiet, das eine der wenigen ansässigen Populationen Großer Tümmler Europas beherbergt. Bootstouren lassen Sie sie beobachten; manche Anbieter erlauben Hunde an Bord, bestätigen Sie dies bei der Buchung.`,
      "Parque Natural da Arrábida": `Ein von mediterranem Buschwerk überzogenes Kalksteinmassiv, das sich über türkisfarbenen Buchten erhebt. Zahlreiche Wanderwege sind für angeleinte Hunde geöffnet, mit weitem Blick hinunter zum Atlantik.`,
      "Portinho da Arrábida e Praia de Galapinhos": `Strände mit weißem Sand und türkisfarbenem Wasser (Galapinhos, Portinho) zählen zu den schönsten Portugals. Hunde sind an bewachten Stränden von Juni bis September verboten; ein wilderer Zugang wird außerhalb der Saison mitunter toleriert.`,
      "Castelo de São Filipe": `Eine von Philipp II. errichtete Festung aus dem 16. Jahrhundert oberhalb der Stadt, heute eine pousada. Die äußeren Wehrgänge und der Vorplatz sind für angeleinte Hunde geöffnet, mit hervorragendem Blick über die Mündung und Tróia.`,
      "Mercado do Livramento": `Eine überdachte Markthalle, berühmt für ihre Azulejo-Fliesentafeln und einige der renommiertesten Fischstände des Landes. Hunde sind im Inneren nicht erlaubt; bewundern Sie die gefliesten Fassaden von der Straße aus.`,
      "Península de Tróia": `Eine lange Sandzunge gegenüber Setúbal, erreichbar mit einer zwanzigminütigen Fähre (Hunde erlaubt). Kilometerlanger offener Strand und die römischen Ruinen von Tróia, ideal für lange Spaziergänge außerhalb der Saison.`,
    },
  },
  seville: {
    history: `Sevillas Identität wurde vom Imperium geprägt: als Hispalis unter Rom, als Ishbiliya unter den Almohaden und als exklusiver atlantischer Hafen der spanischen Indien nach 1503 leitete es das Silber der Neuen Welt durch seinen Torre del Oro und brachte Velázquez, Murillo und den Flamenco hervor. Das Ergebnis ist eine Stadt aus nach Orangen duftenden Patios, Mudéjar-Fliesen und der größten gotischen Kathedrale der Welt. Die Sevillaner pflegen eine tief soziale Beziehung zu ihren Hunden, geboren aus einem Leben auf Plätzen und in Patios, in dem der perro de casa schlicht zur Familie an der Tapas-Theke gehört. Der Sommer allerdings ordnet das Leben ganz nach dem Schatten neu: Von Juni bis September leben Hunde wie Halter nachtaktiv, und die schattigen Ufer des Guadalquivir dienen der Stadt als Freiluftwohnzimmer.`,
    petTips: [`Von Juni bis September erreichen die Sommertemperaturen regelmäßig 42 bis 45 °C, das ist für Hunde wirklich gefährlich; gehen Sie nur vor 8 Uhr oder nach 22 Uhr spazieren und nie auf Stein- oder Metalloberflächen in der Sonne.`, `Sevilla unterliegt den autonomen Regeln Andalusiens: Hunde müssen überall in der Öffentlichkeit angeleint sein; für PPP-Rassen sind Maulkorb und Halterlizenz vorgeschrieben; Bußgelder werden im historischen Zentrum aktiv durchgesetzt.`, `Viele historische Patios und Innenhofrestaurants heißen kleine Hunde im Ermessen des Betreibers willkommen, fragen Sie stets nach; achten Sie auf den grünen Aufkleber 'Admitimos Mascotas'.`, `Die Ufer des Guadalquivir bieten mehrere schattige Hundetreffpunkte (rund um den Paseo das Delicias) mit funktionierenden Trinkbrunnen, machen Sie dies zu Ihrer Sommerstandardroute.`, `Die Kutschen für Touristen sowie die Prozessionen der Semana Santa und der Feria de Abril sind für Hunde stressig, meiden Sie das Zentrum während der Karwoche und der April-Feria vollständig.`],
    practicalInfo: [`Flughafen: Sevilla (SVQ) liegt 10 km nordöstlich; Taxis akzeptieren Hunde im Ermessen des Fahrers, und der Flughafenbus EA lässt nur Transportboxen zu.`, `Tierärzte: Hospital Veterinario Sevilla Este (rund um die Uhr) und Clínica Veterinaria Torneo (zentral, am Fluss) übernehmen Notfälle.`, `Öffentlicher Nahverkehr: TUSSAM-Busse lassen kleine Hunde in Transportboxen zu; die Metro Sevilla (eine Linie) erlaubt Hunde jederzeit in Transportboxen, größere Hunde außerhalb der Stoßzeiten mit Maulkorb.`, `Kühlere Alternativen: die unterirdischen, von einem antiken Aquädukt gespeisten Gänge bei Las Setas und der Gartenbereich des Real Alcázar bleiben deutlich kühler als das Straßenniveau.`, `Zoohandlungen: Kiwoko und Tiendanimal im Einkaufsviertel Nervión; Triana hat mehrere unabhängige Nachbarschaftsläden.`],
    sights: {
      "Parque de María Luisa": `Sevillas üppiger, 40 Hektar großer Park ist das Herz der Hundespaziergänge der Stadt, durchzogen von Brunnen, Teichen und maurisch gestalteten, gefliesten Bänken. Angeleinte Hunde sind überall willkommen, außer im Inneren des Denkmals Plaza de España selbst.`,
      "Plaza de España": `Das halbrunde Meisterwerk der Ibero-Amerikanischen Ausstellung von 1929 ist für angeleinte Hunde auf der äußeren Promenade und den Brückenplätzen zugänglich, ein hervorragender Fotostopp. Das Ruderbootverleih am Kanal ist nicht für Haustiere gestattet.`,
      "Real Alcázar & Cathedral": `Keines der beiden UNESCO-Denkmäler lässt Haustiere zu (außer Assistenzhunden), doch das umliegende Viertel Barrio de Santa Cruz ist ein Labyrinth hundefreundlicher Patios und Tapas-Terrassen. Die Plaza del Triunfo vor beiden Stätten ist an der Leine begehbar.`,
      "Guadalquivir Riverside & Triana": `Der Paseo de Nuestra Señora de a O auf der Triana-Seite ist Sevillas klassischer abendlicher Hundespaziergang, mit Bars voller Flamenco-Geschichte, die sich bis ans Flussufer erstrecken. Überqueren Sie die 1852 erbaute Puente de Isabel II für ikonische Kathedralblicke bei Sonnenuntergang.`,
      "Metropol Parasol (Las Setas)": `Das größte Holzbauwerk der Welt beschattet die Plaza de a Encarnación, eine seltene kühle Tagesoase im Sommer, angeleinte Hunde sind darunter willkommen. Der Dachweg erfordert ein Ticket, und Haustiere sind oben nicht erlaubt.`,
      "Parque del Alamillo": `Nördlich des Zentrums ist der Parque del Alamillo Sevillas größte Grünfläche mit großzügigen leinenfreien Zonen, in denen Einheimische ihre großen Hunde vor Einsetzen der Hitze laufen lassen. Zu Fuß über die 1992 erbaute Alamillo-Brücke erreichbar.`,
    },
  },
  sibenik: {
    history: `Erstmals 1066 in einer Urkunde von König Petar Krešimir IV. erwähnt, ist Šibenik die älteste Stadt an der Adria, die von den Kroaten selbst und nicht von Griechen oder Römern gegründet wurde. Ihr Meisterwerk ist die UNESCO-gelistete Kathedrale des Heiligen Jakob, vollständig aus Kalkstein und Marmor von Juraj Dalmatinac und später Nikola Firentinac erbaut, ohne einen einzigen Holzbalken. Vier Festungen bewachen die Stadt: St. Michael über den Dächern, Barone und St. Johannes auf den Hügeln sowie St. Nikolaus, ebenfalls UNESCO-gelistet, die den Eingang zum Kanal von St. Anthony bewacht. Eine Viertelstunde entfernt beginnt der Nationalpark Krka mit seinen Sinterwasserfällen. Zwischen der schattigen Riva, dem Labyrinth mittelalterlicher Treppen und den Bootsfähren nach Zlarin und Prvić lohnt sich Šibenik mit Hund sehr, besonders im Frühjahr und Herbst.`,
    petTips: [`In öffentlichen Bereichen gilt Leinenpflicht; die Treppen der Altstadt sind nach Regen rutschig, und der Stein wird im Sommer sehr heiß, planen Sie den Aufstieg daher früh am Morgen`, `Sommerwarnung: über 30 °C im Juli und August, mit Pflastersteinen und der Riva, die zwischen 11 und 18 Uhr für Pfoten glühend heiß sind; machen Sie den Handrückentest, gehen Sie bei Sonnenauf- und -untergang spazieren und führen Sie stets Wasser mit`, `Der Strand Banj ist während der Badesaison für Hunde tabu; halten Sie sich an die eigens ausgewiesene Hundezone etwas weiter entlang der Küste oder an die Buchten des St.-Anthony-Kanals außerhalb der Saison`, `Nationalpark Krka: Hunde an der Leine auf den Wegen und Bohlenpfaden erlaubt, aber von den Badebereichen bei Skradinski Buk ausgeschlossen; die Bootsfähren des Parks entscheiden von Fall zu Fall, fragen Sie am Anleger in Skradin nach`, `Jadrolinija-Fähren nach Zlarin und Prvić: Hunde reisen an Deck mit Maulkorb und Leine, nicht in den Kabinen; Stadtbusse im Ermessen des Fahrers, kleine Hunde in einer Transportbox werden leichter akzeptiert`],
    practicalInfo: [`Europäische Notrufnummer: 112; in Kroatien Polizei 192, Feuerwehr 193, Rettungsdienst 194, nicht mit einer tierärztlichen Notrufnummer zu verwechseln`, `Tierarztpraxen in Šibenik für die routinemäßige Versorgung; die nächsten 24-Stunden-Tierkliniken befinden sich in Split und Zadar, etwa eine Stunde Fahrzeit entfernt`, `Tierbedarfsregale in den Supermärkten Tommy, Konzum und Studenac der Stadt; besser sortierte Zoohandlungen in den Gewerbegebieten am Stadtrand und in Split`, `Jadrolinija-Fähren Šibenik-Zlarin-Prvić: Hunde reisen kostenlos an Deck, Maulkorb und Leine sind Pflicht; für Krka liegt der Parkanleger in Skradin, 15 Autominuten entfernt`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich; Kroatien ist EU-Mitglied, ohne zusätzliche Formalitäten bei Einreise aus Frankreich, Spanien oder Portugal`],
    sights: {
      "Katedrala svetog Jakova": `Die UNESCO-gelistete Kathedrale des Heiligen Jakob ist berühmt für ihre steinerne Kuppel und ihren Fries aus 71 gemeißelten Köpfen. Hunde sind im Inneren nicht zugelassen, doch der davorliegende Platz, Trg Republike Hrvatske, gesäumt von venezianischen Loggien, ist früh am Morgen ein Genuss an der Leine.`,
      "Tvrđava svetog Mihovila": `Die Festung St. Michael krönt die Altstadt und bietet das schönste Panorama über den Kanal, die Inseln und die Ziegeldächer. Ein Freiluftort, an dem angeleinte Hunde in der Regel zugelassen sind; prüfen Sie das Programm, da die Sommerbühne Konzerte veranstaltet, die den Zugang abends schließen.`,
      "Nacionalni park Krka": `Eine 15-minütige Fahrt entfernt reiht der Nationalpark Krka Sinterwasserfälle, Holzstege und restaurierte Mühlen aneinander. Angeleinte Hunde sind auf den Wegen und Stegen willkommen, jedoch nicht in den Badebereichen bei Skradinski Buk; führen Sie Wasser mit, da mittags Schatten knapp ist.`,
      "Plaža Banj": `Der Strand Banj, zehn Gehminuten von der Riva entfernt, liegt der Altstadt über die Bucht hinweg gegenüber, ein Postkartenmotiv bei Sonnenuntergang. Hunde sind hier während der Badesaison verboten, außerhalb der Saison jedoch toleriert, und ein eigener hundefreundlicher Abschnitt liegt etwas weiter entlang der Küste.`,
      "Kanal svetog Ante": `Die gestaltete Promenade entlang des St.-Anthony-Kanals folgt den Klippen 4 km zwischen der Stadt und der Festung St. Nikolaus, vorbei an Pinien, Buchten und alten Militärtunneln. Breit, teils schattig und autofrei, ist sie Šibeniks schönster Hundespaziergang, an der Leine und mit Wasser im Gepäck.`,
      "Stari grad (Old Town)": `Die Altstadt ist ein Labyrinth aus poliertem Kopfsteinpflaster, gewölbten Gassen und kleinen Plätzen, die von der Riva zur Festung St. Michael hinaufführen. Angeleinte Hunde streifen hier frei umher, und viele Terrassen bringen einen Wassernapf heraus; sparen Sie sich den Aufstieg im Sommer für die kühleren Stunden auf.`,
    },
  },
  siena: {
    history: `Siena, mit rund 53.000 Einwohnern auf drei Tuffhügeln in der südlichen Toskana gelegen, ist eine der am besten erhaltenen mittelalterlichen Städte Europas und UNESCO-Weltkulturerbe. Florenz' großer Rivale im Mittelalter, fror die Stadt ihren gotischen Höhepunkt des 14. Jahrhunderts rund um die muschelförmige Piazza del Campo ein und ist noch heute in 17 contrade (Stadtviertel) geteilt, die zweimal jährlich beim Palio gegeneinander antreten, dem berühmten Pferderennen am 2. Juli und 16. August. In Bezug auf Hunde gelten die italienischen Regeln: An öffentlichen Orten ist eine Leine vorgeschrieben, ein Maulkorb muss mitgeführt werden, und Hinterlassenschaften sind aufzusammeln; das fast vollständig für Autos gesperrte ummauerte Zentrum lässt sich außerhalb der Stoßzeiten wunderbar mit Hund erkunden. Angeleinte Hunde sind auf der Piazza del Campo, entlang der Wehrgänge der Fortezza Medicea und im mittelalterlichen Garten Orto de' Pecci willkommen, jedoch nicht im Dom oder in den Museen. Meiden Sie die Stadt an Palio-Tagen ganz: Die dichten Menschenmassen und der Lärm sind ein Albtraum für ein Tier.`,
    petTips: [`Palio-Tage (2. Juli und 16. August, dazu die Proberennen an den Vortagen): Die Piazza del Campo und das ganze Zentrum sind überfüllt und ohrenbetäubend. Lassen Sie den Hund im Hotel oder fliehen Sie besser für den Tag in die Crete Senesi.`, `Italienische Regeln: In der Öffentlichkeit gilt durchweg Leinenpflicht, ein Maulkorb muss mitgeführt werden (auf Anfrage in Bussen und Zügen angelegt), und Kotbeutel sind vorgeschrieben.`, `Tierärzte: Clinica Veterinaria Senese (Via Paolo Frajese 61, +39 0577 41412) und Clinica Veterinaria San Martino (Strada Cassia Nord 106, +39 0577 319102, Operationssaal für Notfälle bereit). Für eine universitäre Überweisung ist das Ospedale Didattico Veterinario der Universität Pisa (+39 050 221 0177) 1,5 Stunden entfernt.`, `Abschüssiges Kopfsteinpflaster und Ziegel: Das Zentrum ist steil und bei Regen rutschig. Für ältere Hunde bevorzugen Sie die flachen Wehrgänge der Fortezza und den Orto de' Pecci gegenüber den steilsten Gassen.`, `Sommerhitze: Ziegel und Tuff speichern Wärme, im Juli/August 30 °C und mehr. Gehen Sie früh morgens oder abends spazieren und führen Sie Wasser mit, da öffentliche Trinkbrunnen (fontanelli) im Zentrum rar sind.`],
    practicalInfo: [`Anreise: Siena hat keinen Flughafen; der nächste ist Florenz (FLR, 70 km), mit direktem Autostradale-Bus in 1,5 Stunden verbunden. Trenitalia-Regionalzüge ab Florenz (1 Std. 15 bis 1 Std. 45, Hunde mit Maulkorb zugelassen); Tiemme/Sena-Busse nach San Gimignano, Volterra und Montepulciano.`, `Dokumente: EU-Heimtierausweis, ISO-Mikrochip und mindestens 21 Tage alte Tollwutimpfung für EU-Besucher; Animal Health Certificate (AHC), ausgestellt innerhalb von 10 Tagen, für Besucher von außerhalb der EU (Großbritannien nach dem Brexit eingeschlossen).`, `Örtlicher Verkehr: Das ummauerte Zentrum wird vollständig zu Fuß erkundet; Tiemme-Stadtbusse akzeptieren angeleinte Hunde mit griffbereitem Maulkorb, kleine Hunde in geschlossener Transportbox fahren kostenlos. Das Zentrum ist für Autos gesperrt (ZTL), nutzen Sie also die Parkplätze am Rand.`, `Petsitting: Rover, Pawshake und DogHero decken Siena und den Chianti ab; rechnen Sie mit etwa 16 € pro Nacht für Betreuung zu Hause und 12 € pro Spaziergang; buchen Sie rund um die Palio-Termine frühzeitig.`, `Klima: heiße, trockene Sommer mit 26 bis 30 °C, milde Winter mit 7 bis 10 °C und Regen von November bis Februar; beste Monate mit Hund: April/Mai und Ende September/Oktober, wenn die Crete Senesi grün oder golden sind.`],
    sights: {
      "Piazza del Campo": `Der muschelförmige Platz im Herzen Sienas, geteilt in neun Ziegelabschnitte, die auf den Palazzo Pubblico und den Torre del Mangia zulaufen, einer der schönsten mittelalterlichen Plätze der Welt. Immer geöffnet und an der Leine perfekt begehbar; das Innere des Palastes und der Turmaufstieg sind für Hunde gesperrt.`,
      "Fortezza Medicea": `Eine im 16. Jahrhundert von den Medici errichtete Backsteinfestung, deren breite, ebene Wehrgänge heute eine bei Sienesen und ihren Hunden beliebte Panoramapromenade bilden. Zu jeder Stunde frei an der Leine begehbar, mit Blick auf die Hügel der Crete Senesi; die angrenzenden Lizza-Gärten bieten Schatten für eine Pause.`,
      "Orto de' Pecci": `Ein mittelalterliches grünes Tal direkt unterhalb der Piazza del Campo, mit Gemüsebeeten, Weinreben, Nutztieren und weiten Rasenflächen, ein Stück Land mitten im Zentrum. Angeleinte Hunde willkommen auf den Wegen und der Rasenfläche, mit einer Café-Restaurant-Terrasse, die Hunde akzeptiert, ideal für eine Verschnaufpause abseits der Gassen.`,
      "Duomo di Siena": `Eine gotische, schwarz-weiß marmorierte Kathedrale, eine der spektakulärsten Italiens, die die Stadt von ihrem höchsten Punkt aus krönt. Der Vorplatz und die umliegenden Gassen sind an der Leine frei begehbar, um die Fassade zu bewundern; das Innere, die Krypta und die Piccolomini-Bibliothek sind Assistenzhunden vorbehalten.`,
      "Via Francigena": `Der antike Pilgerweg von Canterbury nach Rom führt durch Siena über die Porta Camollia im Norden und die Porta Romana im Süden, markiert durch mittelalterliche Torbauten. Die Abschnitte hinter den Toren, durch Olivenhaine und Hügel, eignen sich hervorragend für angeleinte Spaziergänge abseits des Trubels im Zentrum.`,
      "Crete Senesi": `Die Tonhügel südöstlich von Siena, die typische toskanische Landschaft aus welligen Kämmen, Zypressen und einsamen Gehöften. Mit dem Auto 20 bis 30 Minuten oder mit dem Tiemme-Bus entfernt, mit Wegen und weißen Schotterstraßen, ideal für lange angeleinte Spaziergänge; kein Schatten, brechen Sie im Sommer also früh auf.`,
    },
  },
  sintra: {
    history: `Sintra erhebt sich in den Granithügeln der Serra de Sintra, nur 30 km nordwestlich von Lissabon, ein neblig-mikroklimatischer Lorbeerwald, der seit der Vorgeschichte Siedler und seit dem Mittelalter Königshäuser angezogen hat. Maurische Baumeister errichteten das Castelo dos Mouros auf seinen Felsen; portugiesische Könige verwandelten das Tal in einen Sommerrückzugsort, gekrönt in den 1840er-Jahren von Ferdinand II. überschwänglichem Palácio da Pena, einem Höhepunkt der europäischen Romantik. Lord Byron nannte die Region ein 'herrliches Eden', und die Aristokratie des 19. Jahrhunderts übersäte die Hänge mit Palästen, Follies und botanischen Gärten wie Monserrate und Quinta da Regaleira. Die UNESCO nahm 1995 die gesamte Kulturlandschaft von Sintra in ihre Liste auf. Kühl, grün und gut zu Fuß erkundbar, mit angeleinten Hunden willkommen auf den Waldwegen und in den Schlossgärten, ist Sintra einer der lohnendsten Tagesausflüge Portugals für Reisende mit Haustier.`,
    petTips: [`In den Anlagen der Parques de Sintra (Pena, Monserrate, Castelo dos Mouros) sind Hunde an der Leine in den Gärten und auf den Wegen erlaubt, niemals in den Palästen selbst. Heben Sie Ihr Ticket zum Wiedereintritt auf.`, `Der städtische Zug CP Lissabon-Sintra (40 Minuten ab Rossio) nimmt Hunde mit: kleine kostenlos in einer Tasche, große mit Maulkorb und Leine gegen Ticket.`, `Die Touristenbusse 434 und 435 hinauf zur Pena sind oft voll und können große Hunde abweisen; der Aufstieg zu Fuß durch den Wald ist eine schöne, kühlere Alternative.`, `Die Serra hält Nebel und Feuchtigkeit fest: Selbst im Sommer ist mit einem kühlen Aufstieg und gelegentlich rutschigen Wegen zu rechnen.`, `Am Cabo da Roca ist der Wind stark und die Klippen steil: Eine kurze Leine in der Nähe der Ränder ist unerlässlich.`],
    practicalInfo: [`24-Stunden-Notfalltierarzt: Centro Veterinário Sintra, R. Casal da Ligeira 64, Terrugem, +351 219 612 282`, `Der städtische CP-Zug von Lissabon (Rossio oder Oriente) nach Sintra braucht 40 Minuten, Hunde werden akzeptiert`, `Mikrochip und EU-Heimtierausweis erforderlich; aktuelle Tollwutimpfung, um in Portugal zu reisen`, `Cabo da Roca und die Küstenstrände (Praia das Maçãs, Praia Grande) mit dem Bus 403 oder dem Auto erreichbar`],
    sights: {
      "Palácio Nacional da Pena": `Portugals berühmtester Palast der Romantik krönt die Serra mit seinen gelben und blutroten Türmen. Angeleinte Hunde sind im weitläufigen Park von Pena (200 ha exotische Gärten und Wege) willkommen, jedoch nicht im Palast selbst. Bringen Sie für den bewaldeten Aufstieg Wasser mit.`,
      "Quinta da Regaleira": `Dieses Anwesen im neo-manuelinischen Stil aus dem frühen 20. Jahrhundert ist berühmt für seinen Initiationsbrunnen, eine unterirdisch abtauchende Wendeltreppe, und seine geheimnisvollen Gärten. Angeleinte Hunde sind auf dem Gelände erlaubt, einem grünen Labyrinth, ideal für eine schattige Erkundung.`,
      "Parque de Monserrate": `Der exotische Palast von Monserrate ist in einen der schönsten botanischen Gärten Portugals eingebettet, der Arten aus aller Welt über sanft geschwungene Rasenflächen mischt. Angeleinte Hunde sind hier willkommen, fernab des Trubels bei Pena. Ideal für einen langen, ruhigen Spaziergang.`,
      "Castelo dos Mouros": `Die Wehrgänge der maurischen Burg aus dem 9. Jahrhundert schlängeln sich am Kamm entlang mit weiten Blicken über das Tal und den Atlantik. Angeleinte Hunde dürfen das Gelände und die Mauern begehen; das Gelände ist felsig, bringen Sie also robuste Pfoten und Wasser mit.`,
      "Cabo da Roca": `Der westlichste Punkt des europäischen Festlands, wo die Klippen 140 m in den Atlantik abfallen. Die offenen, windumtosten Wege des Vorgebirges werden an der Leine begangen; halten Sie Ihren Hund gut von den steilen Rändern fern. Spektakuläre Sonnenuntergänge.`,
      "Centro Histórico de Sintra": `Die Altstadt (Vila Velha), unterhalb des Nationalpalastes mit seinen zwei kegelförmigen Schornsteinen, ist ein Labyrinth aus gepflasterten Gassen, Konditoreien (travesseiros und queijadas) und Terrassen, die angeleinte Hunde willkommen heißen. Perfekt für einen Bummel zwischen den Palästen.`,
    },
  },
  sirmione: {
    history: `Sirmione liegt an der Spitze einer schmalen Halbinsel, die sich fast vier Kilometer in den Gardasee in der Lombardei erstreckt. Seit der Antike wegen seiner schwefelhaltigen Thermalquellen geschätzt, inspirierte es den lateinischen Dichter Catull zu einigen seiner berühmtesten Verse; die ausgedehnten römischen Ruinen, die die Landspitze krönen, tragen noch heute seinen Namen, die Grotte di Catullo. Im 13. Jahrhundert errichtete die mächtige Familie della Scala aus Verona hier eine wassergrabenumgebene Festung, die Rocca Scaligera, deren zinnenbewehrte Türme noch immer den Eingang zur Altstadt bewachen. Die gepflasterten, vollständig für Fußgänger reservierten Gassen des Zentrums füllen sich im Sommer mit dichten Menschenmassen, angezogen vom türkisfarbenen Wasser, den Spas und dem Gelato. Für den Reisenden mit Hund bietet Sirmione eine Uferburg, einen mit Olivenbäumen bestandenen archäologischen Park, flache Felsbadestellen und Boote, die den größten See Italiens durchqueren.`,
    petTips: [`Starker Sommerandrang von Juni bis September: Erkunden Sie die Altstadt und die Burg früh morgens, wenn die Fußgängergassen für Ihren Hund noch ruhig sind.`, `Seeschwimmen: Suchen Sie in der Nähe von Sirmione nach einer hundetoleranten Zone (oft kostenlose, unbewachte Strände); das frische Wasser des Gardasees ist im Sommer ideal zur Abkühlung.`, `Sommerhitze auf den Felsplatten und dem Pflaster: Sie werden mittags sehr heiß, gehen Sie also in den kühlen Stunden spazieren und führen Sie Wasser mit.`, `Die Altstadt ist vollständig für Fußgänger: Halten Sie Ihren Hund inmitten der Terrassen und Menschenmassen an einer kurzen Leine und sammeln Sie stets die Hinterlassenschaften auf.`, `Bei einem tierärztlichen Notfall wählen Sie 112 (die EU-Notrufnummer); in Sirmione und rund um Desenzano sind Tierarztpraxen tätig.`],
    practicalInfo: [`Italien ist EU- und Schengen-Mitglied: Ein EU-Heimtierausweis plus gültige Tollwutimpfung plus ISO-Mikrochip genügt bei Einreise aus jedem EU-Land.`, `Nächste Flughäfen: Verona (VRN) etwa 30 km, Bergamo (BGY) und Brescia etwa 50 bis 70 km; Mailand und Venedig etwa 130 km.`, `Der Bahnhof Desenzano del Garda-Sirmione liegt an der Strecke Mailand-Venedig (etwa 8 km); von dort mit Bus oder Taxi, Hunde an der Leine und mit Maulkorb in öffentlichen Verkehrsmitteln erlaubt.`, `Währung: Euro. Die Altstadt ist für Autos gesperrt: Parken Sie an den Parkplätzen am Eingang und gehen Sie mit Ihrem Hund zu Fuß ins Dorf.`, `Beste Reisezeit: Mai/Juni und September für mildes Wetter und um die Hitze und Menschenmassen im August zu vermeiden.`],
    sights: {
      "Rocca Scaligera": `Eine wassergrabenumgebene Burg aus dem 13. Jahrhundert, deren zinnenbewehrte Türme den Eingang zur Altstadt bewachen. Der äußere Burghof ist für angeleinte Hunde geöffnet; der Turmaufstieg und einige Innenräume sind für sie tabu.`,
      "Grotte di Catullo": `Eine ausgedehnte römische Villenruine an der Spitze der Halbinsel, umgeben von einem Olivenhain mit Seeblick. Ein archäologischer Freiluftpark, in dem angeleinte Hunde erlaubt sind; prüfen Sie dies in der Hochsaison am Eingang.`,
      "Spiaggia Jamaica": `Baden auf breiten, flachen Felsplatten an der Spitze der Halbinsel, nahe der Grotte di Catullo. Klares, flaches Wasser; Hunde werden abseits der belebtesten Stellen toleriert, halten Sie sie also angeleint.`,
      "Terme di Sirmione": `Die schwefelhaltigen Thermalquellen, die Sirmione berühmt gemacht haben, mit dem Seeufer-Spa Aquaria. Haustiere sind im Thermalkomplex nicht erlaubt; organisieren Sie eine Hundebetreuung, wenn Sie ihn genießen möchten.`,
      "Centro storico": `Ein Labyrinth vollständig für Fußgänger reservierter, gepflasterter Gassen, gesäumt von Geschäften, Gelaterien und Terrassen. Mit Hund charmant früh morgens oder abends; im Sommer sind die Menschenmassen zu Stoßzeiten sehr dicht.`,
      "Navigazione Lago di Garda": `Boote und Fähren, die Sirmione mit den Uferorten des Gardasees verbinden (Desenzano, Peschiera, Garda). Hunde sind an der Leine an Bord erlaubt, oft zu einem ermäßigten oder kostenlosen Ticket, je nach Größe.`,
    },
  },
  sitges: {
    history: `Ein Fischer- und Weinbaudorf, das zur Hauptstadt des Modernisme wurde, verdankt Sitges seine Verwandlung den 'americanos', Auswanderern, die im 19. Jahrhundert reich aus Kuba zurückkehrten und die prunkvollen Villen entlang der Uferpromenade errichteten. 1891 richtete der Maler Santiago Rusiñol hier sein Atelier Cau Ferrat ein und zog Picasso, Casas und die gesamte Bohème Barcelonas an: Sitges wurde zum Labor der modernen katalanischen Kunst. Das 20. Jahrhundert fügte eine Tradition der Offenheit hinzu, die den Ort heute zu einem der einladendsten, feierfreudigsten Reiseziele Europas macht, berühmt für seinen Karneval und sein fantastisches Filmfestival. Mit 17 Stränden, einer mehrere Kilometer langen Uferpromenade, einem eigenen Hundestrand und dem Massiv von Garraf im Rücken ist Sitges zudem eine der einfachsten katalanischen Küstenstädte, die man mit Hund genießen kann, 35 Minuten mit dem Zug von Barcelona entfernt.`,
    petTips: [`Im Sommer sind Sitges' 17 Strände tagsüber für Hunde gesperrt, außer der offiziellen Hundezone nahe Les Anquines: Dort schwimmt Ihr Hund das ganze Jahr über, mit Duschen und der Promenade in der Nähe.`, `Ende Februar oder Anfang März übernimmt der Karneval für eine Woche das Zentrum, mit Umzugswagen und lauten Menschenmassen bis spät in die Nacht: Meiden Sie diese Termine bei einem lärmempfindlichen Hund, oder bleiben Sie auf der Terramar-Seite, abseits des Trubels.`, `Rodalies-R2-Züge aus Barcelona nehmen Hunde kostenlos mit (Leine und Maulkorb bei großen Hunden, Transportbox bei kleinen): Die 35-minütige Fahrt macht daraus einen einfachen Ausflug.`, `Starten Sie im Garraf-Park im Sommer früh: Der weiße Kalkstein strahlt Hitze ab, es gibt keine Wasserstellen, und die Wege sind exponiert, führen Sie also mehr Wasser mit, als Sie denken zu brauchen.`, `In der Stadt gilt wie überall in Spanien Leinenpflicht, und PPP-gelistete Rassen müssen an öffentlichen Orten einen Maulkorb tragen; das Aufsammeln von Hinterlassenschaften wird auf dem Passeig streng kontrolliert.`],
    practicalInfo: [`Mehrere Tierarztpraxen in der Stadt; bei nächtlichen Notfällen sind die 24-Stunden-Tierkliniken des Großraums Barcelona über die C-32 in 30 bis 40 Minuten erreichbar`, `Europäische Notrufnummer: 112; die örtliche Polizei kann Ihnen die Zonen und Zeiten nennen, in denen Hunde erlaubt sind`, `Zoohandlungen im Zentrum und in Marktnähe, Tierbedarfsregale in den Supermärkten der Stadt`, `Rodalies-R2-Züge kostenlos für Hunde (Leine plus Maulkorb, oder Transportbox); Stadtbusse: kleine Hunde in Transportboxen; Taxis im Ermessen des Fahrers`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich; Leishmaniose-Prophylaxe an der Mittelmeerküste von April bis November empfohlen`],
    sights: {
      "Passeig Marítim": `Die Uferpromenade rollt mehrere Kilometer Palmen und Modernista-Villen entlang der Strände aus, von La Punta bis zur Marina Aiguadolç. Sie ist das Rückgrat der angeleinten Spaziergänge in Sitges, prachtvoll bei Sonnenaufgang, wenn die Strände noch leer sind.`,
      "Platja de les Anquines": `In der Nähe des Hotels Terramar ist dieser kleine Strand Sitges' offizielle Hundezone: Hunde können hier das ganze Jahr über schwimmen, ein seltenes Privileg an der katalanischen Küste. Sand, Wellenbrecher und nahe Duschen machen ihn zum Treffpunkt der Hunde der Stadt.`,
      "Església de Sant Bartomeu i Santa Tecla": `Auf ihrem Vorsprung zwischen zwei Stränden thronend, ist die Kirche aus dem 17. Jahrhundert das endgültige Bild von Sitges. Das Innere lässt keine Hunde zu, doch die Esplanade Baluard darum herum, über den Wellen, ist einer der schönsten Aussichtspunkte der Küste für eine angeleinte Pause.`,
      "Casc Antic": `Hinter der Kirche verbergen die weißen Gassen des alten Sitges blumengeschmückte Patios, Boutiquen und Modernista-Fassaden wie Cau Ferrat und Maricel. Die Museen empfangen keine Hunde, doch das Durchstreifen dieses mediterranen Labyrinths an der Leine ist ein Vergnügen für sich.`,
      "Parc Natural del Garraf": `Direkt hinter der Stadt bietet dieses Kalksteinmassiv mit seiner weißen Garriguen-Landschaft markierte Wege zwischen Zwergpalmen und mediterranen Ausblicken. Angeleinte Hunde sind zugelassen: Die Runde ab La Plana oder der Aufstieg zur Eremitage Trinitat sind schöne Ausflüge für einen halben Tag.`,
      "Port d'Aiguadolç": `Östlich der Stadt reiht die Marina Aiguadolç Segelboote und Fischrestaurants um ein geschütztes Becken auf. Viele Terrassen akzeptieren Hunde, und der von dort zur Kirche führende Küstenweg, in die niedrige Klippe geschnitten, ist ein hübscher angeleinter Spaziergang.`,
    },
  },
  sliema: {
    history: `Sliema, Maltas wichtigster gehobener Küstenort, erstreckt sich entlang der Küste gegenüber Valletta über den Hafen von Marsamxett. Im 19. Jahrhundert noch ein bescheidenes Fischer- und Sommerfrischedorf, dessen Name auf eine marianische Anrufung zurückgeht (Sliem, Frieden), ist es zum modernen wirtschaftlichen und wohnlichen Herz der Insel geworden: Apartmenttürme, Geschäfte, Cafés und eine von morgens bis abends belebte Uferpromenade. Seine Küste besteht nicht aus Sand, sondern aus flachem Kalkstein, durchsetzt von Gezeitentümpeln und den in den Fels geschlagenen alten römischen Bädern. Für einen Hundehalter ist Sliema eine der angenehmsten Städte Maltas: die durchgehende Uferpromenade von Tigné bis St. Julian's ist einer der besten Hundespaziergänge des Archipels, flach, ununterbrochen und begleitet vom Blick auf Vallettas goldene Bastionen über den Hafen hinweg.`,
    petTips: [`Im Hochsommer (Juli/August, 33 °C und mehr) werden die exponierte Promenade und der Kalkstein bis mittags glühend heiß: Gehen Sie bei Sonnenauf- oder -untergang spazieren und führen Sie Wasser mit, da Schatten knapp ist.`, `Sliemas Küste ist felsig und fast sandlos; außerhalb der Saison werden Hunde auf den flachen Felsen und rund um die römischen Bäder toleriert, doch Maltas offizielle Sandhundestrände liegen anderswo (vor allem Little Armier).`, `Gehen Sie die durchgehende Promenade von Tigné nach St. Julian's, flach und ununterbrochen, einer der besten Hundespaziergänge der Insel, mit vielen Terrassencafés, die Hunde draußen willkommen heißen.`, `Nehmen Sie mit Ihrem angeleinten Hund die kleine Fähre hinüber nach Valletta: eine wenige Minuten dauernde Überfahrt mit atemberaubendem Blick auf die Bastionen.`, `Halten Sie Ihren Hund in der Stadt angeleint und sammeln Sie stets auf (Bußgelder werden verhängt); achten Sie auf Pfoten auf sonnenerhitztem Stein und seien Sie vorsichtig auf dem nassen, rutschigen Fels am Wasserrand.`],
    practicalInfo: [`Malta ist EU- und Schengen-Mitglied: Ein EU-Heimtierausweis, ISO-Mikrochip und aktuelle Tollwutimpfung genügen, ohne Titertest, und sind beim Check-in im haustierfreundlichen Hotel erforderlich.`, `Fortbewegung: Maltesische Busse nehmen kleine Hunde in Transportboxen mit (im Ermessen des Fahrers), aber keine großen; Sliema ist kompakt und zu Fuß erreichbar, sonst nutzen Sie haustierfreundliche Taxis (Bolt, eCabs auf Anfrage).`, `Die Fähre Sliema-Valletta (Hafen Marsamxett) lässt angeleinte Hunde auf einer kurzen, malerischen Überfahrt zu; die Gozo-Fähre akzeptiert ebenfalls Hunde.`, `Die Sommerhitze ist von Juni bis September intensiv (33 °C und mehr), mit glühendem Fels und Pflaster und wenig Schatten auf der Promenade: Gehen Sie früh morgens oder abends spazieren, Wasser ist unverzichtbar.`, `Tierärztliche Versorgung: Kliniken sind in Sliema und im benachbarten Gżira tätig, mit einem 24-Stunden-Notfalldienst auf der Insel; allgemeine Notrufnummer 112. Die Küste ist felsig, erwarten Sie also wenig Sand.`],
    sights: {
      "Sliema Promenade": `Die lange gepflasterte Promenade entlang der gesamten Küste von Tigné bis St. Julian's, flach und über mehrere Kilometer ununterbrochen, mit Terrassencafés und ständigem Blick auf Valletta. Sie ist einer der besten Hundespaziergänge Maltas; angeleinte Hunde sind überall willkommen, im Sommer am besten früh oder abends.`,
      "Roman Baths & Fond Għadir": `Das flache Felsplateau von Fond Għadir, wo alte, in den Fels gehauene Becken, bekannt als die Römischen Bäder, von Gezeiten und Dünung gefüllt werden. Ohne Sand ist dies, wo Hunde außerhalb der Saison auf den flachen Felsen toleriert werden; achten Sie auf rutschigen Fels und Wellen und meiden Sie den glühend heißen Stein an Sommernachmittagen.`,
      "Tigné Point": `Das neugestaltete Vorgebirge an der Mündung des Hafens Marsamxett, mit offenen Plätzen, einer Uferpromenade und einem der schönsten frontalen Ausblicke auf Vallettas Befestigungen. Die Freiluftplätze und die Promenade lassen sich mit einem angeleinten Hund frei begehen, hervorragend bei Sonnenuntergang.`,
      "Fort Tigné": `Ein kleines, 1795 fertiggestelltes Fort des Malteserordens, eines der ältesten polygonalen Forts der Welt, das den Hafeneingang bei Tigné Point bewacht. Die Außenanlagen lassen sich mit einem angeleinten Hund besuchen und runden eine einfache Runde ab der Promenade ab.`,
      "Independence Garden": `Ein kleiner öffentlicher Ufergarten (Ġnien l-Indipendenza), mit Palmen, schattigen Bänken und Rasenflächen, eine der wenigen Grünflächen in dieser sehr dicht bebauten Stadt. Angeleinte Hunde sind willkommen, eine wertvolle schattige Pause zwischen den Abschnitten der Promenade.`,
      "Sliema Ferries": `Die Anlegestelle am Kopf des Hafens Marsamxett, von wo die kleine Passagierfähre nach Valletta übersetzt, ein malerischer, wenige Minuten dauernder Sprung. Angeleinte Hunde dürfen an Bord, sodass Sie die Hauptstadt und ihre Bastionen ohne Auto oder Bus erreichen.`,
    },
  },
  sofia: {
    history: `Sofia ist eine der ältesten Hauptstädte Europas: eine thrakische Siedlung namens Serdica im 7. Jahrhundert v. Chr., wurde sie unter Konstantin ein bedeutendes römisches Zentrum, dann ein byzantinischer Bischofssitz, eine osmanische Eroberung und schließlich 1879 die Hauptstadt des bulgarischen Königreichs. Mit rund 1,2 Millionen Einwohnern ist sie zudem die grünste Hauptstadt der EU nach Baumkronenanteil, was der 2290 Meter hohe Vitosha erklärt, der sich direkt aus dem Stadtgefüge erhebt. Die bulgarische Hundekultur ist offen, aber reguliert: Die Stadtverwaltung verlangt eine Erkennungsmarke für registrierte Hunde, Freilauf ist auf markierte Parkabschnitte beschränkt, und ein landesweites Verzeichnis haustierfreundlicher Orte listet fast 500 Cafés und Läden. Sofia ist zudem bemerkenswert erschwinglich, hundefreundliche Hotels beginnen bei 60 € pro Nacht, tierärztliche Notfallbesuche bei 40 €, und die Plattform Pawshake bei 5 € pro Spaziergang.`,
    petTips: [`Metro und Straßenbahn: kleine Hunde in Transportboxen kostenlos, große Hunde benötigen Leine, Maulkorb und Fahrschein. Kontrolleure prüfen tatsächlich.`, `BDZ-Züge: halber Fahrpreis der zweiten Klasse für Hunde mit Maulkorb und Tierheft; Blindenführhunde fahren kostenlos.`, `Zentralste 24/7-Notfalltierärzte: Central Vet Clinic, Tsar Boris III Boulevard 130, +359 2 952 0001.`, `Die Alexander-Newski-Kathedrale, die Boyana-Kirche und die meisten Museen lassen nur Assistenzhunde zu, planen Sie bei Bedarf einen Sitter über Pawshake.`, `Sehr kalte Winter: Temperaturen bis -15 °C im Januar/Februar, packen Sie für kleine Hunde einen Mantel und Pfotenbalsam ein.`],
    practicalInfo: [`Der Flughafen Sofia (SOF) liegt 10 km vom Zentrum entfernt, mit der Metrolinie M1 in 18 Minuten nach Serdika (kleiner Hund in Transportbox kostenlos, großer Hund: Fahrschein plus Maulkorb).`, `Preise hundefreundlicher Hotels: ab 60 € pro Nacht für 4 Sterne, durchschnittlicher Haustierzuschlag 0 bis 50 € pro Aufenthalt.`, `Kontinentales Klima: kalte, schneereiche Winter (0 °C im Januar), warme Sommer (22 °C im Juli); die Stadt liegt auf 550 bis 600 m, sodass Sommernächte kühl bleiben.`, `Pawshake.com und PetBacker dominieren Betreuung und Gassigehen; rechnen Sie mit 6 bis 8 € pro Kurzbesuch, 12 bis 18 € für Ganztagesbetreuung, 15 bis 22 € pro Nacht, zu den günstigsten Tierbetreuungspreisen Osteuropas.`, `Sofia ist mit dem Direktzug 8 Stunden von Bukarest, 6 Stunden von Belgrad und mit dem Bus 7 Stunden von Thessaloniki entfernt, ein praktischer Ausgangspunkt für eine Balkan-Rundreise mit Hund.`],
    sights: {
      "Aleksander Nevski Cathedral": `Eine riesige neobyzantinische Kathedrale mit goldenen Kuppeln, eine der größten orthodoxen Kirchen Europas. Das Innere lässt nur Assistenzhunde zu, doch der weite, steingepflasterte Platz davor und der Samstags-Flohmarkt auf der Rückseite sind leinenfreundlich.`,
      "Vitosha Boulevard": `Sofias Fußgängerachse, 1,2 km vom Sveta-Nedelya-Platz im Süden bis zum Vitosha-Massiv. Cafés, Eisdielen und Buchhandlungen, mit fast durchweg hundefreundlichen Terrassen. Der Blick auf die Vitosha-Gipfel am südlichen Ende ist das Wahrzeichenfoto der Stadt.`,
      "Borisova Gradina": `Sofias ältester öffentlicher Park (1884), 90 Hektar südöstlich des Zentrums. Breite, baumgesäumte Alleen, der Ariana-See, drei Stadien und ruhige Rosengärten; angeleinte Hunde überall, Freilauf wird auf den inneren Waldwegen toleriert.`,
      "Vitosha Nature Park": `Bulgariens erster Naturpark (1934), der das gesamte Massiv südlich der Stadt umfasst. Der Wasserfall von Boyana und das Gebiet Aleko (Bergstation der Gondel) sind die beliebtesten Routen; angeleinte Hunde willkommen, Freilauf wird auf den oberen alpinen Abschnitten toleriert.`,
      "Boyana Church": `Eine UNESCO-Kirche aus dem 13. Jahrhundert, berühmt für ihre 90 mittelalterlichen Fresken. Das Innere lässt nur Assistenzhunde zu, doch das Boyana-Viertel und der markierte Wasserfallweg darüber sind leinenfreundlich.`,
      "Pancharevo Lake": `Ein 4 km langer Bergstausee 15 km vom Zentrum entfernt, der nächste Ort zum Hundeschwimmen bei Sofia. Die freien öffentlichen Abschnitte des Südufers akzeptieren Hunde das ganze Jahr über; Bus 1/3 ab dem Zentrum.`,
    },
  },
  sopot: {
    history: `Sopot wurde zweimal geboren: jahrhundertelang ein kaschubisches Fischerdorf, dann ab 1823 ein mondäner Badeort, als der Arzt der napoleonischen Ära, Jean Georg Haffner, die ersten Seebäder eröffnete. Die Belle Époque hinterließ ihm prächtige Villen, das Grand Hotel von 1927 an der Uferpromenade und seine 512 m lange Holzseebrücke, die längste Europas, 1928 auf ihre heutige Länge erweitert. Zwischen Gdansk und Gdynia eingekeilt, ist die 35.000-Einwohner-Stadt das elegante Bindeglied der Trójmiasto (Dreistadt) und trägt noch immer offiziell den Status Kurort (uzdrowisko), mit brackigen Quellen, die in der Balneotherapie genutzt werden. Für Reisende mit Hund hat Sopot eine bemerkenswerte Wende vollzogen: Seit der Aktualisierung der städtischen Verordnung 2025 haben Hunde ganzjährig Zugang zum Strand außerhalb der bewachten Badezonen, die Stadt unterhält zwölf kostenlose leinenfreie Auslaufflächen, und die Seebrücke selbst heißt angeleinte Hunde ohne Ticket willkommen.`,
    petTips: [`Polnisches Recht: In der Stadt gilt Leinenpflicht, Maulkorb für aggressive Rassen und in der Bahn (SKM, PKP); die Durchsetzung ist locker, führen Sie dennoch einen Maulkorb mit.`, `Seit 2025 haben Hunde außerhalb der Betriebszeiten im Juli/August Zugang zum gesamten Strand außerhalb der bewachten Badezonen; abends öffnet der gesamte Strand wieder.`, `Zwölf kostenlose leinenfreie Auslaufflächen, darunter der mit Agility-Geräten ausgestattete Błonia Sopockie (ul. Bitwy pod Płowcami) und der Park Północny hinter dem Klub Koliba.`, `Der SKM-Zug verbindet Gdansk (15 Min.) und Gdynia (10 Min.), Hunde fahren kostenlos mit Leine und Maulkorb; Trolleybus 21 erreicht den Hundestrand von Kolibki.`, `Waldzecken von März bis November: Behandeln Sie Ihren Hund vor der Ankunft und untersuchen Sie ihn nach jedem Spaziergang im Landschaftspark der Dreistadt.`],
    practicalInfo: [`Tierarzt in Sopot: Sopocka Przychodnia Weterynaryjna, ul. 23 Marca 32E, +48 58 551 31 18 (Mo-Fr 8-20 Uhr, Wochenendvormittage; Chirurgie, Bildgebung, EU-Heimtierausweise).`, `24-Stunden-Notfälle: EDINA New Vet, ul. Chwaszczyńska 22 lok. 5, Gdynia, +48 58 600 42 10, rund um die Uhr geöffnete Tierklinik, 15 Autominuten entfernt.`, `Seebrücke: angeleinte Hunde ganzjährig kostenlos; Ticket für Menschen 10 PLN von April bis September, kostenlos von Oktober bis März.`, `Preise hundefreundlicher Hotels: ab 60 bis 90 € pro Nacht; Sopot ist Polens teuerster Ferienort, doch die Hunde-Extras (Strände, Auslaufflächen) sind kostenlos.`, `Mildes Ostseeklima: 20 bis 21 °C im Juli/August, Wassertemperatur 18 bis 19 °C; außerhalb der Saison unbegrenzter Strand für Hunde und eine fast leere Stadt.`],
    sights: {
      "Molo w Sopocie": `Europas längste Holzseebrücke (512 m) ragt in die Danziger Bucht hinaus. Angeleinte Hunde ganzjährig ohne Ticket erlaubt; Menschen zahlen von April bis September 10 PLN.`,
      "Krzywy Domek": `Das Krumme Häuschen von 2004, eine wellenförmige Fassade, die zum Wahrzeichen des Monte-Cassino-Boulevards wurde. Fotografieren Sie es mit angeleintem Hund von der Straße aus; das Innere ist eine Einkaufspassage ohne Interesse für Hunde.`,
      "Park Północny": `Der Uferpark nördlich der Seebrücke, schattige Alleen zwischen Villen der Kurort-Ära und dem Strand, mit einer eingezäunten Hundeauslauffläche hinter dem Klub Koliba. Verbindet die Seebrücke mit den Hundestrand-Zugängen 43-45.`,
      "Plaża dla psów Sopot": `Der ausgeschilderte Hundeabschnitt des Strandes zwischen den Zugängen 43 und 45 am nördlichen Ende bei Kamienny Potok. Weißer Sand, flaches Wasser, ganzjährig kostenloser Zutritt.`,
      "Opera Leśna": `Das hundertjährige, 4400 Plätze fassende Waldamphitheater, eingebettet in ein Tal des Landschaftsparks der Dreistadt. Umliegende Wege ganzjährig für angeleinte Hunde geöffnet; bei kostenpflichtigen Vorstellungen keine Hunde.`,
      "Błonia Sopockie": `Sopots führende Hundeauslauffläche, kostenlos und rund um die Uhr geöffnet, mit einem Agility-Parcours: Sprünge, Slalomstangen und eine Rampe. Fünf Minuten von den südlichen Strandzugängen entfernt.`,
    },
  },
  sorrento: {
    history: `Auf 80 Meter hohen Tuffklippen über dem Golf von Neapel gelegen, ist Sorrent das römische Surrentum, bereits ein von den Patriziern des Reichs bevorzugter Badeort. Als Geburtsort des Dichters Torquato Tasso hat es sich ein kompaktes historisches Zentrum aus gepflasterten Gassen, terrassierten Zitronenhainen und Limoncello-Läden bewahrt. Mit knapp 16.000 Einwohnern dient es als Tor zum gesamten Golf: Capri 25 Minuten mit der Fähre entfernt, Pompeji 35 Minuten mit der Circumvesuviana-Bahn und die Amalfiküste entlang der SITA-SUD-Buslinie. Die Einwohner Sorrents sind hundefreundlich, Hunde sind an der Leine auf Caféterrassen, in den Gärten der Villa Comunale und entlang des Fischereihafens Marina Grande willkommen.`,
    petTips: [`In der Circumvesuviana (EAV) nach Pompeji und Neapel reisen kleine Hunde in einer Transportbox kostenlos mit; große Hunde mit Maulkorb und Leine benötigen ein ermäßigtes Ticket.`, `Die SITA-SUD-Busse zur Amalfiküste akzeptieren Hunde mit Maulkorb und Leine, sind im Sommer jedoch oft überfüllt: Reisen Sie früh morgens.`, `Im Sommer werden Tuffstufen und Asphalt glühend heiß: Gehen Sie mit Ihrem Hund vor 10 Uhr oder nach 18 Uhr spazieren und führen Sie Wasser mit.`, `Die meisten Strände Sorrents sind private Strandbäder, die Hunde verbieten; Marina di Puolo und Marina del Cantone (Nerano) sind hundetoleranter.`, `Auf den Fähren nach Capri und Ischia (Caremar, NLG, Gescab) sind Hunde in der Regel mit Maulkorb und Leine erlaubt: Bestätigen Sie die Richtlinie vor dem Boarding beim Betreiber.`],
    practicalInfo: [`Tierarzt im Zentrum: Ambulatorio Veterinario Gli Amici del Cuore, Via degli Aranci 31, +39 081 362 2147`, `24/7-Notfall (regionale Überweisungsklinik): Ospedale Veterinario Universitario (Pronto Soccorso H24), Neapel (50 km über die A3), +39 081 253 6088`, `EU-Heimtierausweis akzeptiert; keine Quarantäne für EU-Haustiere`, `Anreise: Flughafen Neapel (NAP, 50 km), dann mit der Circumvesuviana-Bahn oder dem Curreri-Bus nach Sorrent`],
    sights: {
      "Piazza Tasso": `Der weitgehend für Fußgänger reservierte zentrale Platz, gesäumt von Cafés, ist das schlagende Herz des historischen Zentrums. Ideal für einen abendlichen Spaziergang mit angeleintem Hund, bevor es hinunter zur Marina Grande geht.`,
      "Villa Comunale": `Diese Klippengärten bieten einen weiten Blick über den Golf von Neapel und den Vesuv. Angeleinte Hunde sind willkommen; ein öffentlicher Aufzug verbindet den Park mit dem darunterliegenden Hafen Marina Grande.`,
      "Chiostro di San Francesco": `Dieser Kreuzgang aus dem 14. Jahrhundert mit seinen verschlungenen Bögen und dem Bougainvillea-Garten grenzt an die Villa Comunale. Angeleinte Hunde sind im Innenhof erlaubt; der Eintritt ist frei, und der Schatten ist im Sommer willkommen.`,
      "Marina Grande": `Das alte Fischerdorf mit seinen bunten Booten und Meeresfrüchte-Restaurants ist die authentischste Ecke Sorrents. Der Spaziergang am Wasser ist mit Hund einfach; mehrere Terrassen akzeptieren Haustiere.`,
      "Giardini di Cataldo": `Dieser historische Zitronenhain im Herzen der Stadt produziert Sorrents berühmte Zitronen und Limoncello. Der schattige Hain kann mit angeleintem Hund besucht werden; kostenlose Verkostung am Ausgang.`,
      "Vallone dei Mulini": `Diese in den Tuff geschnittene grüne Schlucht mit den farnbewachsenen Ruinen einer alten Mühle wird von einem Aussichtspunkt nahe der Piazza Tasso aus betrachtet. Ein schneller, kostenloser Aussichtspunkt, perfekt mit Hund.`,
    },
  },
  spa: {
    history: `Spa hat der Welt seinen Namen gegeben: Das Wort spa selbst stammt aus dieser kleinen Stadt in den belgischen Ardennen, in der Provinz Lüttich. Ihre Mineralquellen, die pouhons, haben seit dem 16. Jahrhundert Kurgäste und gekrönte Häupter angezogen, und Peter der Große trank am nach ihm benannten pouhon das Wasser. Im 18. Jahrhundert als 'Café Europas' bezeichnet, wurde Spa zum Vorbild jedes Kurorts und krönte diese Entwicklung 2021 mit der Aufnahme in die UNESCO-Welterbeliste unter den großen europäischen Kurstädten. Heute leben rund 10.000 Menschen in einem bewaldeten Tal, zwischen den überdachten Galerien des Parc de Sept Heures, dem Lac de Warfaaz und dem weiten Hochplateau der Hohen Venn. Für einen Hund ist es ein leichtes, grünes Reiseziel: Wälder, Moorwege und ein See sind wenige Minuten vom Zentrum entfernt an der Leine begehbar, auch wenn die Thermen selbst für Tiere tabu bleiben.`,
    petTips: [`Rund um Spa gilt überall Leinenpflicht, auch in der Hohen Venn, und der Zutritt zu den ausgeschilderten Kernzonen des Naturschutzgebiets ist Hunden gänzlich untersagt.`, `Die Thermes de Spa lassen keine Hunde zu (Bäder, Becken, Wellness, Restaurant), organisieren Sie also einen Sitter oder besuchen Sie sie abwechselnd.`, `In SNCB-Zügen reist ein kleiner Hund in einer Transportbox kostenlos; ein größerer angeleinter Hund benötigt pro Fahrt einen Haustierzuschlag von 3 €.`, `Die Wälder der Venn und der Ardennen sind Zeckengebiet: Verwenden Sie Zeckenschutz und untersuchen Sie Ihren Hund nach jedem Spaziergang.`, `Das Ardennenklima ist das ganze Jahr über kühl und feucht, packen Sie also selbst im Sommer ein Handtuch und einen Trockenmantel ein.`],
    practicalInfo: [`Mehrere Tierarztpraxen im Zentrum (Ave. Reine Astrid, Rue du Waux-Hall, Rue Hanster); keine 24-Stunden-Klinik in Spa, der Bereitschaftsdienst läuft über einen regionalen diensthabenden Tierarzt`, `Europäische Notrufnummer: 112; für einen diensthabenden Tierarzt rufen Sie zunächst Ihre nächste Praxis an`, `Zug: Endstation der Linie 44 ist Spa-Géronstère, Umsteigen in Verviers/Pepinster; der SNCB-Haustierzuschlag beträgt 3 € pro Fahrt für einen großen Hund`, `TEC-Bus: Ein kleiner Hund auf dem Schoß oder in einer Box fährt kostenlos, ein großer Hund zahlt Ihren Fahrpreis, Leinenpflicht besteht`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich für die Einreise nach Belgien aus der EU`],
    sights: {
      "Lac de Warfaaz": `Ein 1890 aufgestauter See an den Toren von Spa, umgeben von einem etwa 600 Meter langen befestigten Weg. Er ist der Standard-Hundespaziergang: flach, einfach, mit Stellen, an denen ein angeleinter Hund trinken kann, und Seeuferterrassen für eine Pause.`,
      "Parc de Sept Heures": `Der Park im Stadtzentrum, berühmt für seine langen überdachten Galerien aus dem 19. Jahrhundert. Flach und geschützt, ist er der ideale Ort, um einen angeleinten Hund auszuführen und an einem regnerischen Ardennentag trocken zu bleiben, mit Rasenflächen und altem Baumbestand.`,
      "Hautes Fagnes": `Belgiens größtes Naturschutzgebiet, ein Plateau aus Torfmoor, Heidekraut und Bohlenwegen, gekrönt vom Signal de Botrange (694 m). Hunde sind an der Leine willkommen, doch der Zutritt zu den ausgeschilderten Kernzonen ist ihnen gänzlich untersagt.`,
      "Pouhon Pierre-le-Grand": `Spas berühmteste Mineralquelle, unter einem Pavillon von 1880, der auch das Fremdenverkehrsamt beherbergt. Benannt nach Zar Peter dem Großen, ist sie zentraler Bestandteil des UNESCO-Erbes; ein ruhiger, angeleinter Hund darf im Ermessen des Personals eintreten.`,
      "Les Thermes de Spa": `Die markanten modernen Bäder am Hang über dem Zentrum, erreichbar über eine Panorama-Standseilbahn. Erben der Mineralwassertradition, lassen sie keine Hunde zu, planen Sie also, dass eine Person während des Besuchs beim Hund bleibt.`,
      "Circuit de Spa-Francorchamps": `Die legendäre Formel-1-Strecke wenige Kilometer von der Stadt entfernt, beliebt als Tagesausflug. Sie liegt außerhalb von Spa, und der Zugang für Hunde ist an Renntagen eingeschränkt, betrachten Sie sie also vor allem als Wahrzeichen und Ausflugsziel.`,
    },
  },
  soller: {
    history: `Sóller, eingebettet in ein Tal voller Orangenhaine im Herzen der UNESCO-gelisteten Serra de Tramuntana, ist eine von Bergen umringte mallorquinische Stadt, die ihren Wohlstand den einst nach Frankreich verschifften Zitrusfrüchten verdankt. Rund um die Plaça de la Constitució erinnert die Modernista-Fassade der Kirche Sant Bartomeu, entworfen von einem Schüler Gaudís, an das Vermögen der Orangenhändler des 19. Jahrhunderts. Eine historische Holzstraßenbahn ratterte hinunter nach Port de Sóller mit seiner hufeisenförmigen Bucht, während die berühmte Schmalspurbahn Palma durch dreizehn Bergtunnel verbindet. Orangen- und Zitronenhaine, Mühlen, Trockenmauerwege und Buchten schließen den Horizont ab. Als ideale Basis für Wanderungen in der Tramuntana wird Sóller im Freien und an der Leine gelebt, zwischen Markt, Caféterrassen und Spaziergängen zum Leuchtturm, und bleibt dank seiner Höhenlage kühler als die Ebene.`,
    petTips: [`Spanisches Recht: In der Stadt gilt Leinenpflicht, und für gelistete PPP-Rassen ist an öffentlichen Orten und in Verkehrsmitteln ein Maulkorb vorgeschrieben; halten Sie Heimtierausweis und Mikrochip stets aktuell.`, `Sommerhitze: Das Tal ist kühler als die Ebene, übersteigt von Juni bis September jedoch oft 30 °C, gehen Sie also bei Sonnenauf- oder -untergang spazieren und testen Sie den Asphalt vor dem Aufbruch mit dem Handrücken.`, `Strand von Port de Sóller: Hunde sind während der Badesaison (etwa Mai bis Oktober) vom bewachten Strand verbannt, suchen Sie also eine unbewachte Bucht oder gehen Sie stattdessen den Leuchtturmweg.`, `Wandern in der Tramuntana: Wege sind an der Leine geöffnet, führen Sie reichlich Wasser mit, respektieren Sie die Schafherden und prüfen Sie sommerliche Waldbrandeinschränkungen.`, `Straßenbahn und Zug: An Bord ist ein Maulkorb vorgeschrieben, halten Sie also einen griffbereit; bestätigen Sie in der Hochsaison den Platz für Ihren Hund vor dem Einstieg.`],
    practicalInfo: [`Notfälle: 112 ist Spaniens einheitliche europäische Nummer; Sóller und sein Hafen verfügen über Tierarztpraxen, fragen Sie in Ihrem Hotel nach dem nächsten Bereitschaftsdienst, Palma liegt für 24-Stunden-Notfälle etwa dreißig Kilometer entfernt.`, `Zug von Palma nach Sóller: kleine angeleinte und mit Maulkorb versehene Hunde werden meist zugelassen, prüfen Sie die aktuelle Richtlinie am Bahnhofsschalter vor dem Ticketkauf.`, `Straßenbahn nach Port de Sóller: angeleinte und mit Maulkorb versehene Hunde auf den offenen Plattformen akzeptiert, der einfachste Weg, die Bucht ohne Auto zu erreichen.`, `Strände: Der Hafenstrand ist während der Badesaison reglementiert; erkunden Sie im Voraus eine unbewachte Bucht oder die Hundezonen der Küste.`, `Der Flughafen Palma de Mallorca liegt etwa 30 km entfernt; Spanien ist EU-Mitglied, bringen Sie also den europäischen Heimtierausweis mit aktuellem Mikrochip und Tollwutimpfung mit.`],
    sights: {
      "Plaça de la Constitució i Sant Bartomeu": `Der zentrale Platz mit seinen Caféterrassen und dem Brunnen belebt sich vor der Modernista-Fassade von Sant Bartomeu. Der Platz und der Vorplatz werden an der Leine genossen, das Kircheninnere ist jedoch für Hunde tabu.`,
      "Tramvia de Sóller": `Die 1913 eröffnete Holzstraßenbahn verbindet den Platz über fünf Kilometer durch die Obstgärten mit Port de Sóller. Angeleinte und mit Maulkorb versehene Hunde werden auf den offenen Plattformen akzeptiert, am besten in der Hochsaison beim Fahrer zu bestätigen.`,
      "Ferrocarril de Sóller": `Die 1912 eröffnete Schmalspurbahn durchquert dreizehn Tunnel zwischen Palma und Sóller für eine einstündige, malerische Fahrt. Kleine angeleinte und mit Maulkorb versehene Hunde werden meist zugelassen, prüfen Sie jedoch vor dem Einstieg die aktuelle Richtlinie am Bahnhof.`,
      "Port de Sóller i Far del Cap Gros": `Die runde Bucht des Hafens, ihre Promenade und der zum Leuchtturm Cap Gros hinaufführende Weg bieten einen der schönsten Ausblicke der Küste. Promenade und Leuchtturmweg werden an der Leine begangen; der Hauptstrand ist im Sommer reglementiert.`,
      "Camí de Castelló i horts de tarongers": `Die sich zwischen Orangenbäumen, Zitronenbäumen und Trockenmauern windenden ländlichen Wege führen vom Tal hinunter Richtung Biniaraix. Freiluftwege zum Spazierengehen an der Leine, morgens schattig und nachmittags sehr sonnenexponiert.`,
      "Jardí Botànic de Sóller": `Der botanische Garten zeigt die endemische Flora der Balearen und des westlichen Mittelmeerraums am Fuß der Tramuntana. Wie die meisten botanischen Gärten lässt er keine Hunde zu; planen Sie für diesen Besuch eine Alternative ein.`,
    },
  },
  split: {
    history: `Split wuchs innerhalb eines Palastes heran. Als sich der römische Kaiser Diokletian 305 n. Chr. hierher zurückzog, errichtete er eine Festungsresidenz am Meer, die spätere Flüchtlinge in das lebendige Herz einer Stadt verwandelten, heute schlafen noch immer 3000 Menschen innerhalb ihrer Kalksteinmauern. Das Ergebnis ist UNESCO-gelistetes Chaos: römische Säulen, die mittelalterliche Wohnungen tragen, barocke Altäre gedrängt neben venezianische Kaufmannshäuser, alles einer Adria zugewandt, die blauer ist als jede Postkarte. Split erhebt sich zwischen dem Pinienwald des Marjan-Hügels und der von Palmen gesäumten Riva-Promenade, mit den dalmatinischen Inseln nur eine Fährfahrt entfernt. Kroaten lieben Hunde, besonders den einheimischen Dalmatiner, der genau an dieser Küste gezüchtet wurde, und die meisten Cafés stellen Wassernäpfe bereit.`,
    petTips: [`Splits städtische Strände verbieten Hunde tagsüber vom 1. Juni bis 30. September; Žnjan, die Nebenbuchten von Kašjuni und Trstenik verfügen über eigene, ganzjährig geöffnete Hundebereiche.`, `Kalkstein und Steinstraßen erreichen nachmittags in der Sonne 50 °C, testen Sie mit dem Handrücken; wenn Sie es keine 5 Sekunden aushalten, verbrennt es die Pfoten. Gehen Sie vor 10 Uhr oder nach 20 Uhr spazieren.`, `Kroatien schreibt Leinenpflicht an allen öffentlichen Orten außer in ausgewiesenen Parks vor; in öffentlichen Verkehrsmitteln ist ein Maulkorb Pflicht.`, `Frischwasser ist schwerer zu finden als in Nordeuropa, führen Sie einen faltbaren Napf mit und füllen Sie ihn an den Steinbrunnen des Marjan oder in Riva-Cafés auf.`, `Die Fährgesellschaft Jadrolinija lässt angeleinte Hunde auf den meisten dalmatinischen Inselrouten kostenlos an Deck zu; Kabinen erfordern ein zusätzliches Ticket.`],
    practicalInfo: [`Kroatien ist EU- und Schengen-Mitglied: Ein EU-Heimtierausweis, ISO-Mikrochip und gültige Tollwutimpfung (mindestens 21 Tage alt) genügen; Reisende von außerhalb der EU benötigen ein tierärztliches Gesundheitszeugnis.`, `Der Flughafen Split (SPU) bearbeitet ganzjährig Haustiere in der Kabine bis 8 kg und im Frachtraum; buchen Sie den Haustierplatz mindestens 48 Stunden im Voraus und rechnen Sie im Juli/August mit Hitzeeinschränkungen.`, `24-Stunden-Tierpflege gibt es bei Veterinarska Ambulanta Split (Poljička cesta) und Poliklinika Kreso; beide sprechen Englisch.`, `Sommerhöchstwerte übersteigen oft 32 °C bei intensiver UV-Strahlung; Winter sind mit 5 bis 12 °C mild, doch der Bura-Wind kann brutal wirken, packen Sie im Sommer Sonnenschutzausrüstung und im Winter für kleine Rassen einen leichten Mantel ein.`, `Die Taxi-Apps Bolt und Uber sind in Split verfügbar und akzeptieren Haustiere, wenn dies bei der Buchung angegeben wird; Stadtbusse (Promet) akzeptieren angeleinte Hunde mit Maulkorb gegen ein kleines Haustierticket.`],
    sights: {
      "Diocletian's Palace": `Der 1700 Jahre alte römische Kaiserpalast, der zu Splits Altstadt wurde. Angeleinte Hunde sind im gesamten lebendigen Labyrinth aus Straßen, Plätzen und Kellern willkommen, jedoch nicht in der Kathedrale des Heiligen Domnius, ihrem Glockenturm und den kostenpflichtigen Museen. Frühmorgendliche Spaziergänge vor den Kreuzfahrt-Menschenmassen sind magisch.`,
      "Marjan Hill": `Splits bewaldete Halbinsel, die sich direkt aus der Altstadt erhebt, mit 178 Metern Aleppo-Kiefern, Steinkapellen und Panorama-Aussichtspunkten. Hunde sind überall an der Leine willkommen, und mehrere Felsbuchten an den Südhängen dienen ganzjährig als inoffizielle Hundeschwimmstellen.`,
      "Riva Promenade": `Splits von Palmen gesäumte Uferpromenade ist der tägliche Spazierweg jedes Einheimischen, Hund oder nicht. Angeleinte Hunde sind entlang der gesamten Strecke und auf den meisten Caféterrassen willkommen. Abendliche Meeresbrisen halten sie noch lange kühl, nachdem die Steinstadt gebacken wurde.`,
      "Bačvice Beach": `Splits berühmtester Sandstrand, Heimat des örtlichen Ballspiels picigin. Hunde sind wie an allen städtischen Badestränden Splits tagsüber vom 1. Juni bis 30. September verboten, außerhalb der Saison jedoch morgens und abends erlaubt.`,
      "Žnjan Dog Beach": `Ein offiziell ausgewiesener Haustierstrand östlich des Zentrums, ganzjährig für Hunde geöffnet, auch im Hochsommer. Kieszugang, flaches, warmes Wasser und eine Hundedusche machen ihn im Juli und August zur praktischen Wahl.`,
      "Green Market (Pazar)": `Der Freiluft-Obst- und Gemüsemarkt an der östlichen Palastmauer summt jeden Morgen mit dalmatinischen Bauern. Angeleinte Hunde sind zwischen den Ständen willkommen, und viele Verkäufer halten einen Wassernapf bereit.`,
    },
  },
  'st-ives': {
    history: `St Ives, ein kornischer Fischerhafen um eine weiße Sandbucht am äußersten Westen Englands, verdankt seinen Ruhm zwei Dingen: Pilchards und Licht. Nachdem die Pilchard-Fischerei zusammenbrach, zog die außergewöhnliche Klarheit seines atlantischen Lichts Künstler an, und ab den 1920er-Jahren wurde die Stadt zu einer der großen britischen Künstlerkolonien, heute gekrönt von der Galerie Tate St Ives (1993) und dem Barbara-Hepworth-Museum. Das alte Viertel Downlong, ein Labyrinth aus Granitgassen und Fischerhäuschen, fällt hinunter zu einem geschützten Hafen und fünf Sandstränden. Für einen Hund ist St Ives eine der einladendsten Städte Cornwalls: Hunde reisen kostenlos im kleinen Zweigbahnzug ab St Erth, kostenlos bei den Robbenbootsausflügen, und sind in den Hafenpubs und auf dem South West Coast Path das ganze Jahr über willkommen. Das Einzige, worauf man sich einstellen muss, sind die saisonalen Hunderegeln der Grafschaft Cornwall an den Stränden. Und für EU-Besucher: Seit dem Brexit verlangt Großbritannien ein GB Animal Health Certificate statt des EU-Heimtierausweises.`,
    petTips: [`Strände sind saisonal reguliert: Porthmeor, Porthminster und Carbis Bay verbieten Hunde vom 15. Mai bis 30. September, 10 bis 18 Uhr; der Hafen von St Ives und Porthgwidden vom 1. Juli bis 31. August. Das Bußgeld beträgt 100 Pfund.`, `Bamaluz Beach, Lambeth Walk und die Nordseite des Smeaton's Pier bleiben Hunden das ganze Jahr über geöffnet; gehen Sie die eingeschränkten Strände früh oder spät.`, `Hunde reisen kostenlos mit dem Zug (bis zu zwei pro Fahrgast, an der Leine) und bei den Robbenbootsausflügen; das Stadtzentrum ist für Fußgänger und steil.`, `Halten Sie Ihren Hund auf dem South West Coast Path in der Nähe der ungesicherten Klippenränder und weidender Nutztiere an der Leine.`, `Notfalltierarzt außerhalb der Öffnungszeiten: CVets bei Truro (+44 1872 560952); tagsüber Medivet St Ives (+44 1736 798333).`],
    practicalInfo: [`Einreise ins Vereinigte Königreich nach dem Brexit: Großbritannien akzeptiert den EU-Heimtierausweis nicht; Hunde benötigen ein GB Animal Health Certificate (ausgestellt innerhalb von 10 Tagen), einen Mikrochip, eine Tollwutimpfung und eine Bandwurmbehandlung 24 bis 120 Stunden vor der Ankunft.`, `Anreise: Zug bis St Erth, dann die Zweigbahn nach St Ives Bay (Hunde kostenlos). Nächster Flughafen ist Newquay (NQY), etwa 1 Stunde mit dem Auto.`, `Fortbewegung: Parkplätze in der Stadt sind im Sommer sehr begrenzt; lassen Sie das Auto am Park-and-Ride bei St Erth oder Lelant Saltings und nehmen Sie den Zug. Das Zentrum ist für Fußgänger und steil.`, `Wetter: eines der mildesten Klimata Großbritanniens; milde Winter (9-10 °C), warme, aber nicht heiße Sommer (18 °C). Frühling und Herbst sind ideal, außerhalb der Strandverbote.`, `Nützliche Nummern: allgemeiner Notruf 999 oder 112; Tagestierarzt Medivet St Ives +44 1736 798333; Bereitschaft außerhalb der Öffnungszeiten CVets +44 1872 560952.`],
    sights: {
      "Bamaluz Beach": `Eine kleine, geschützte Sandbucht unterhalb des Museums, zwischen dem Hafen und Porthgwidden, und der einzige Strand von St Ives, der ohne saisonales Verbot das ganze Jahr über für Hunde geöffnet ist.`,
      "Porthmeor Beach": `Der große, mit der Blauen Flagge ausgezeichnete Surfstrand unterhalb der Tate, mit einem hundefreundlichen Café. Hunde vom 15. Mai bis 30. September, 10 bis 18 Uhr verboten; früh, spät und außerhalb der Saison erlaubt.`,
      "St Ives Harbour": `Der goldsandige Arbeitshafen, umgeben von Pubs und Fischerbooten, mit dem Smeaton's Pier. Die Nordseite des Piers ist ganzjährig ein Hundestrand.`,
      "South West Coast Path": `Ein dramatischer Klippenweg westwärts nach Zennor über Granitklippen und Buchten. Ganzjährig für Hunde geöffnet; Leinenpflicht in der Nähe der Klippenränder und bei Nutztieren.`,
      "Seal Island Boat Trips": `Kleine Naturbeobachtungsboote ab dem Hafen zu den Kegelrobbenkolonien bei Seal Island und Godrevy. Hunde sind willkommen und reisen kostenlos, an der Leine an Deck.`,
      "The Island (St Ives Head)": `Das grüne Vorgebirge, das die Stadt teilt, gekrönt von der St.-Nikolaus-Kapelle und umringt von einem ebenen Weg mit Meer auf drei Seiten. Hunde das ganze Jahr über willkommen.`,
    },
  },
  'st-moritz': {
    history: `St. Moritz, der sagenumwobene Alpenferienort im hochgelegenen Engadin in Graubünden, liegt auf rund 1800 Metern um seinen türkisfarbenen See, umringt von Gipfeln und Lärchenwald. Geburtsort des alpinen Wintertourismus seit 1864 und zweifacher Austragungsort der Olympischen Winterspiele, verdankt der Ort seinen Ruhm reichlichem Sonnenschein, einer seit der Antike bekannten eisenhaltigen Mineralquelle und einer wohlhabenden Kundschaft, die seine prachtvollen Grandhotels und Luxusboutiquen errichten ließ. Im Winter friert der See fest genug, um Pferderennen auf Eis, Polo und Cricket auszutragen; im Sommer wird das Tal zu einem riesigen Wanderparadies. Für einen Hundehalter bietet St. Moritz eine großartige Landschaft und ein Netz von Standseil- und Kabinenbahnen, die weitgehend für Haustiere geöffnet sind, aber auch Höhenlage, intensive Sonne und harte Winter, die etwas Vorsicht erfordern.`,
    petTips: [`Achten Sie auf die Höhenlage: Auf 1800 Metern und darüber ist die Luft dünn, und Anstrengung ermüdet einen Hund schneller; lassen Sie Ihren Hund einen oder zwei Tage vor größeren Wanderungen akklimatisieren und bieten Sie häufig Wasser an.`, `Im Winter reizen Streusalz und Splitt die Pfotenballen: Spülen und trocknen Sie die Pfoten nach der Rückkehr, tragen Sie einen Schutzbalsam auf und achten Sie auf Eisklumpen zwischen den Zehen.`, `Die Bergsonne ist sehr stark, besonders reflektiert von Schnee oder in der Höhe: Suchen Sie im Sommer in den heißen Stunden Schatten und schützen Sie hellhäutige oder kurzhaarige Hunde.`, `In den Bergtransportmitteln (Standseilbahnen, Kabinenbahnen, Bernina Express) sind Hunde in der Regel zum ermäßigten oder halben Fahrpreis erlaubt; zu Stoßzeiten kann ein Maulkorb erforderlich sein, halten Sie also einen in der Tasche bereit.`, `Wenn der See für Pferderennen, Polo oder den White Turf zufriert, halten Sie Ihren Hund angeleint und weit von den präparierten Bahnen und Pferden fern; betreten Sie das Eis nie außerhalb markierter Bereiche.`],
    practicalInfo: [`Die Schweiz liegt außerhalb der EU, ist jedoch mit dem EU-Heimtierausweis kompatibel: ISO-Mikrochip, gültige Tollwutimpfung und der Ausweis genügen zur Ein- und Rückreise in die EU, ohne Antikörper-Titertest.`, `In den Schweizer öffentlichen Verkehrsmitteln (RhB-Züge, PostAuto, Bergbahnen) reisen Hunde zum halben Fahrpreis oder mit einem Hunde-Tagespass; kleine Hunde in einer Tasche reisen oft kostenlos, bei Andrang kann ein Maulkorb verlangt werden.`, `St. Moritz ist ein Luxusferienort: Unterkünfte sind teuer, buchen Sie also frühzeitig und vergleichen Sie mit den nahen Engadiner Dörfern (Pontresina, Celerina, Samedan), die oft günstiger und ebenso gastfreundlich sind.`, `Für einen tierärztlichen Notfall befindet sich die regionale Überweisungsklinik in Samedan, wenige Autominuten entfernt; führen Sie Gesundheitsheft und Ausweis Ihres Haustiers mit sich; allgemeine Notrufnummer 112, medizinische Notfälle 144.`, `Das Klima ist alpin: Die Sommer sind kühl und für Hunde angenehm, doch die Sonne ist in der Höhe stark, und die Winter sind lang und schneereich (November bis April), was Pfotenpflege und Aufmerksamkeit gegenüber Streusalz erfordert.`],
    sights: {
      "Lej da San Murezzan (Lake St. Moritz)": `Der türkisfarbene See im Herzen des Ferienorts, umgeben von einer flachen Promenade, die St. Moritz Bad mit Dorf verbindet, perfekt für einen einfachen Spaziergang mit Bergblick. Angeleinte Hunde sind das ganze Jahr über willkommen; im Winter finden auf dem zugefrorenen See Pferderennen und Polo statt, bleiben Sie also dann auf den markierten Uferwegen.`,
      "Muottas Muragl": `Eine historische Standseilbahn, die auf 2456 Meter hinaufführt und eines der schönsten Panoramen über das Engadin und seine Seenkette eröffnet. Hunde sind in der Kabine und auf dem berühmten Panoramaweg (Philosophenweg) von oben erlaubt; bringen Sie Wasser mit, da die Luft trocken und die Sonne stark ist.`,
      "Piz Nair (Corviglia)": `Das Skigebiet Corviglia und der Gipfel Piz Nair (3057 Meter) sind mit Standseilbahn und dann Kabinenbahn vom Zentrum aus erreichbar und eröffnen im Sommer blumenreiche Alpenwiesen. Hunde reisen in den Kabinen zum ermäßigten Ticket; in der Höhe ermüden Sonne und dünne Luft schnell, teilen Sie sich die Anstrengung also gut ein.`,
      "Morteratsch Glacier Trail": `Etwa zwanzig Minuten Richtung Berninapass folgt der Gletscherweg Morteratsch einem nahezu ebenen Tal, markiert mit Pfosten, die den jährlichen Rückzug des Eises zeigen. Angeleinte Hunde sind auf diesem leichten, teils schattigen Spaziergang willkommen; der Gletscherbach lässt einen Hund die Pfoten kühlen.`,
      "Bernina Express": `Eine UNESCO-gelistete Eisenbahn, die über den Berninapass hinunter nach Tirano in Italien führt, eine der spektakulärsten der Alpen mit ihren Spiralviadukten. Hunde fahren zum halben Fahrpreis (bei Andrang kann ein Maulkorb verlangt werden); ein Regionalticket bis Alp Grüm oder Ospizio Bernina genügt, um die schönste Aussicht zu genießen.`,
      "Segantini Museum": `Ein kuppelgekröntes Museum, das dem Maler Giovanni Segantini gewidmet ist, dessen leuchtende Alpenlandschaften die Seele des Engadins einfangen. Hunde sind im Inneren nicht erlaubt; lassen Sie Ihren Begleiter bei einem Freund und genießen Sie anschließend die nahe Seepromenade, die für angeleinte Haustiere geöffnet ist.`,
    },
  },
  stavanger: {
    history: `Stavanger, im 8. Jahrhundert als Wikingerdorf gegründet und 1125 zur Bischofsstadt, als Bischof Reinald die romanische Steinkathedrale errichtete, die noch heute das Stadtzentrum beherrscht, wurde im 20. Jahrhundert nach den Nordsee-Ölfunden von 1969 zu Norwegens 'Ölhauptstadt'. Heute die drittgrößte Stadt des Landes (140.000 Einwohner), verbindet Stavanger ein erdöl-industrielles Erbe (Erdölmuseum am Hafen) mit der größten erhaltenen hölzernen Altstadt Nordeuropas (Gamle Stavanger, 173 Häuser aus dem 18./19. Jahrhundert) und dem ikonischen Preikestolen (Pulpit Rock) 50 Minuten östlich. Für Reisende mit Hund ist es eines der hundefreundlichsten Reiseziele Europas: kostenloser Transport ohne Maulkorb und ohne Ticket (Kolumbus-Busse plus Lysefjord-Fähren, Vy-Züge), die Preikestolen-Wanderung ganzjährig für angeleinte Hunde zugänglich, 35 km hundefreundlicher Atlantiksand 15 Minuten südlich (Solastranden, Borestranden) und eine 24/7-Tierklinik am Stadtrand.`,
    petTips: [`Die norwegische Café-Kultur heißt Hunde standardmäßig willkommen, etwa 75 % der Cafés in Stavanger akzeptieren angeleinte Hunde das ganze Jahr über im Hauptraum.`, `Kolumbus-Busse, Vy-Züge und Lysefjord-Fähren: angeleinte Hunde KOSTENLOS, kein Maulkorb, kein Ticket nötig, zu den großzügigsten Regeln Europas.`, `8 eingezäunte städtische Hundeparks (hundepark); Leinenpflicht vom 1. April bis 19. August in nicht eingezäunten Zonen.`, `24/7-Notfalltierarzt: AniCura Stavanger Smådyrklinikk in Hillevåg (+47 51 56 03 00), 8 Minuten mit dem Auto oder Bus 9.`, `Norwegen verlangt eine Bandwurm-(Echinokokkose-)Behandlung 24 bis 120 Stunden vor der Ankunft, wie auch Finnland, Irland und Malta.`],
    practicalInfo: [`Norwegen ist Schengen-, aber NICHT EU-Mitglied: EU-Heimtierausweis plus gültige Tollwutimpfung plus ISO-Mikrochip plus Bandwurmbehandlung 24 bis 120 Stunden vor der Ankunft.`, `Direkte Vy-Züge: Kristiansand 3 Std. 30, Oslo 8 Std., angeleinte Hunde kostenlos in haustierfreundlichen Wagen.`, `Der Flughafen Stavanger Sola (SVG) liegt 14 km südlich, erreichbar mit Bus 9 (40 Min.) oder dem Expressbus Flybussen (25 Min.), beide hundefreundlich. SAS, Norwegian und Wizz Air akzeptieren alle kleine Hunde in der Kabine.`, `Währung: norwegische Krone (NOK), nicht Euro. Tägliches hundefreundliches Budget: 1000 bis 1500 NOK/Tag (100 bis 150 €) ohne Unterkunft, zu den höchsten Europas.`, `Hundefreundliche Tagesausflüge: Preikestolen (50 Min. mit dem Auto, 8 km Wanderung), Lysefjord-Kreuzfahrt (3 Std. ab Vågen), Sandnes (14 km südlich, 25 Min. mit dem Vy-Zug).`],
    sights: {
      "Gamle Stavanger": `Die größte erhaltene hölzerne Altstadt Nordeuropas, 173 weiße Holzhäuser aus dem 18./19. Jahrhundert. Rund um die Uhr geöffnet, durchweg hundefreundlich.`,
      "Preikestolen (Pulpit Rock)": `Die ikonische, 604 m senkrecht abfallende Klippe über dem Lysefjord, 8 km hundefreundliche Rundwanderung mit angeleintem Hund ganzjährig. 50 Minuten mit dem Auto östlich.`,
      "Vågen Harbour": `Mittelalterlicher Hafen, hölzerne Bootshäuser, Fischmarkt, Lysefjord-Fähren, über 30 Café-Terrassen. Rund um die Uhr geöffnet, durchweg hundefreundlich.`,
      "Fargegata": `Norwegens farbenfrohste Fußgängerstraße, jede Ladenfront in einer anderen kräftigen Farbe gestrichen. Rund um die Uhr geöffnet, durchweg hundefreundlich.`,
      "Mosvatnet": `Zentraler Stadtsee mit flachem 3-km-Rundweg, befestigtem Pfad, Enten, dem beliebtesten Hunderundweg der Stadt. Angeleinte Hunde (April bis August) oder Freilauf (September bis März).`,
      "Solastranden": `2,3 km breiter Atlantiksandstrand 15 Minuten südlich, einer der besten Hundestrände Norwegens, ganzjährig zugänglich.`,
    },
  },
  stockholm: {
    history: `Stockholm, verteilt auf 14 Inseln dort, wo der Mälarsee auf die Ostsee trifft, ist eine Stadt, die ihre Beziehung zur Natur ernst nimmt. Die Schweden sind eifrige Hundehalter (über 900.000 Hunde landesweit, etwa einer pro zehn Einwohner), und Stockholms Infrastruktur spiegelt dies wider: Die Insel Djurgården, die Tagesausflüge in die Schärenwelt und das ausgedehnte Rad- und Fußwegenetz der Stadt machen sie zu einer der von Natur aus hundefreundlichsten Städte Europas. Die Insel Gamla Stan (Altstadt) mit ihren kopfsteingepflasterten Gassen aus dem 13. Jahrhundert lässt sich mit einem ruhigen Hund gut durchqueren; die umgebende Wasserstadt vermittelt für eine europäische Hauptstadt mit 975.000 Einwohnern ein fast einzigartiges Gefühl von Raum.`,
    petTips: [`SL (Stockholms öffentlicher Nahverkehr): Hunde in Transportboxen fahren in allen Verkehrsmitteln kostenlos mit. Größere Hunde benötigen einen Maulkorb und reisen als ermäßigter Fahrgast. Auf dem Arlanda Express sind Hunde nicht erlaubt.`, `Tagesausflug in die Stockholmer Schärenwelt: Die Fähren von Waxholmsbolaget lassen Hunde auf allen Strecken zu. Die Inseln Vaxholm, Sandhamn und Utö bieten hervorragende Hundespaziergänge und hundefreundliche Gasthäuser (värdshus).`, `Warnung vor schwedischer Wildtierwelt: Djurgården und Ekoparken sind Heimat von Elchen (älg). Diese großen Tiere können aggressiv werden, wenn ein Hund sie jagt, halten Sie Ihren Hund also bei Dämmerung und Morgengrauen angeleint.`, `Winter: Stockholm hat im Januar durchschnittlich -3 °C bei kurzer Tageslichtdauer (6 Std.). Hundeschuhe (hundtassar) sind in schwedischen Zoohandlungen weit verbreitet und für vereiste Gehwege und Streusalzschutz empfehlenswert.`, `Schwedische Fika-Kultur: Die meisten kafé und konditori (Café-Bäckereien) in Stockholm heißen Hunde willkommen. Södermalm hat die höchste Dichte hundefreundlicher unabhängiger Cafés.`],
    practicalInfo: [`Notfalltierarzt: Evidensia Djursjukhuset Stockholm, Rasundavägen, Solna (+46 10 750 10 00), rund um die Uhr geöffnete Fachtierklinik nördlich des Stadtzentrums.`, `Anreise: Der Flughafen Stockholm Arlanda liegt 42 km nördlich. Der Arlanda Express braucht 18 Minuten bis zum Stockholmer Hauptbahnhof (Hunde nicht erlaubt); Flughafenbusse (Flygbussarna) lassen Hunde in Transportboxen zu.`, `Aus Norwegen: Direktzüge von Oslo nach Stockholm (4 Std. 45, SJ Norge/SJ AB). Hunde in Transportboxen oder mit Maulkorb und ermäßigtem Ticket.`, `Beste Saison: Juni bis August für lange Tageslichtdauer (bis zu 18 Std.), Freiluftschwimmen und Schärenausflüge. Dezember/Januar für Weihnachtsmärkte und Schneespaziergänge, doch bereiten Sie sich auf Kälte und Dunkelheit vor.`],
    sights: {
      "Djurgården Island": `Die königliche Parkinsel, Heimat des Vasa-Museums, des Freilichtmuseums Skansen und des ABBA-Museums, ist Stockholms wichtigstes Hundeziel. Die bewaldete Südhälfte ist vollständig leinenfrei; der Uferweg im Norden bietet spektakuläre Blicke auf die Stadt. Hunde begegnen hier regelmäßig Rehen.`,
      "Södermalm & Tantolunden": `Södermalm, Stockholms bohemienhafte südliche Insel, ist das hundefreundlichste Viertel der Stadt. Der Park Tantolunden hat einen Schrebergartenbereich, offene Rasenflächen, ein Ufer und eine eigene Hundeauslauffläche. Die Café-Kultur in SoFo (südlich der Folkungagatan) ist hervorragend, mit Hunden, die in den meisten Lokalen drinnen willkommen sind.`,
      "Ekoparken (Royal National City Park)": `Der weltweit erste Nationalstadtpark, 27 km² Wald, Wiesen, Seen und königliche Schlösser innerhalb der Stadtgrenzen. Hunde an der Leine in den Wiesenzonen; leinenfrei in den bewaldeten Bereichen. Elche, Rehe und Hasen sind regelmäßige Sichtungen, halten Sie Ihren Hund also unter Kontrolle.`,
      "Gamla Stan (Old Town)": `Die mittelalterliche Insel im Herzen Stockholms lässt sich mit Hund gut durchqueren, besonders morgens vor Ankunft der Touristengruppen. Die kopfsteingepflasterten Gassen (gränder) sind schmal, doch der Hauptplatz (Stortorget) und die Uferwege sind breit und hundefreundlich.`,
      "Vasa Museum & Skansen": `Weder das Vasa-Museum noch Skansen lassen Hunde im Inneren zu. Die Außenbereiche von Skansen erlauben Hunde an der Leine in einigen Abschnitten, prüfen Sie die aktuellen Regeln bei Ankunft. Beide lohnen einen Solobesuch; planen Sie die Hundezeit inzwischen für die bewaldeten Südwege von Djurgården ein.`,
    },
  },
  strasbourg: {
    history: `Strasbourg wurde 12 v. Chr. von den Römern als Argentoratum gegründet, um einen strategischen Rheinübergang zu bewachen, und entwickelte sich im Mittelalter zu einer unverwechselbaren elsässischen Stadt, deren Identität sich in den Fachwerkhäusern von Petite France widerspiegelt. Als freie Reichsstadt des Heiligen Römischen Reiches wurde es 1681 französisch, nach 1870 von Deutschland annektiert, kehrte 1919 zu Frankreich zurück, wurde von 1940 bis 1944 erneut besetzt und blieb danach dauerhaft französisch. Dieses doppelte Erbe brachte eine einzigartige Kultur hervor, elsässischen Dialekt, Flammkuchen und Riesling neben französischen bürgerlichen Traditionen. Heute ist Straßburg Sitz des Europäischen Parlaments, des Europarats und des Europäischen Gerichtshofs für Menschenrechte, und die gesamte Grande Île ist UNESCO-Weltkulturerbe. Die Stadt hat rund 285.000 Einwohner und eine bemerkenswert aktive Hundehalterkultur, unterstützt von der Community strasdog.fr mit über 80 zertifizierten haustierfreundlichen Adressen.`,
    petTips: [`Die CTS-Straßenbahnen erlauben Hunde an der Leine mit Maulkorb seit Juli 2023, ein Baskerville-Maulkorb wird von CTS ausdrücklich empfohlen, da er Hecheln und Trinken erlaubt und dabei die Vorschrift erfüllt. Kaufen Sie einen vor der Reise.`, `Die Community-Website strasdog.fr pflegt eine Echtzeitkarte hundefreundlicher Restaurants, Bars und Dienstleistungen in ganz Straßburg, unbedingt vor der Anreise lesen.`, `Weihnachtsmarktsaison (Ende Nov-Dez): Vorsicht bei offen verkaufter Schokolade an jedem Stand, dunkle Schokolade ist für Hunde schon in kleinen Mengen giftig; halten Sie Ihren Hund eng bei sich und achten Sie stets auf den Boden.`, `Elsässische Sommer: im Juli-August können die Temperaturen 30°C überschreiten, vermeiden Sie Spaziergänge auf Asphalt während der Nachmittagshitze (13:00–17:00 Uhr); die schattigen Treidelwege entlang der Ill sind die kühlste Alternative.`, `Die elsässische Terrassenkultur ist sehr einladend: Ist eine Terrasse geöffnet, gilt ein wohlerzogener Hund an der Leine in der Regel als willkommen, sofern kein Schild etwas anderes besagt, man muss nicht jedes Mal fragen.`],
    practicalInfo: [`Tierärztlicher Notdienst: Maison des Urgences Vétérinaires 67, Tel. 03 68 71 83 00, abends geöffnet (ab 19:30 Mo–Fr), samstags ab 12:30 Uhr und sonn- und feiertags rund um die Uhr. Die Clinique Agoravet bietet ganzjährig 24/7-Versorgung.`, `Freilaufzonen: Parc de l'Orangerie (eingezäunt, nordöstliche Ecke) und Parc de la Citadelle (nicht eingezäunt, Beschilderung am Eingang beachten) sind die beiden wichtigsten ausgewiesenen Freilaufflächen der Stadt.`, `Mit dem Zug: Der Bahnhof Strasbourg-Ville bedient TGV aus Paris (2:15 Std.) und TER aus Lyon, Colmar und Basel. Hunde über 6 kg müssen im TGV in einer Transportbox reisen oder ein Pauschalticket lösen; die Regeln variieren je nach Betreiber.`, `EU-Heimtierreisen: Straßburg liegt im Schengen-Raum. In der EU registrierte Haustiere benötigen für jede grenzüberschreitende Reise, einschließlich des Rheinübergangs nach Deutschland, einen gültigen EU-Heimtierausweis mit Mikrochip und aktueller Tollwutimpfung.`, `Beste Basis: Die Viertel Petite France und Krutenau bieten direkten Zugang zu Kanalspaziergängen, hundefreundlichen Bars, dem Parc de l'Orangerie (15 Min. zu Fuß) und dem Parc de la Citadelle (20 Min. zu Fuß).`],
    sights: {
      "Cathédrale Notre-Dame": `Von 1647 bis 1874 das höchste Gebäude der Welt, ist die 142 Meter hohe Kathedrale aus rosafarbenem Sandstein ein gotisches Meisterwerk, dessen kunstvoll geschnitzte Westfassade nach wie vor erstaunt. Hunde dürfen die Kathedrale selbst nicht betreten, der umliegende Fußgängerplatz und das gesamte Äußere sind jedoch an der Leine voll zugänglich.`,
      "Petite France": `Straßburgs bekanntestes Viertel, ein Labyrinth aus elsässischen Fachwerkhäusern des 16.–17. Jahrhunderts, die sich in den Kanälen der Ill spiegeln. Hunde an der Leine sind auf jeder Kopfsteinpflasterstraße, jedem Kai und jeder Fußgängerbrücke dieses Open-Air-UNESCO-Welterbes willkommen.`,
      "Ponts Couverts": `Vier Verteidigungstürme aus dem 13. Jahrhundert, die einst den Eingang zu Petite France markierten; die überdachten Brücken, die sie verbanden, sind längst verschwunden, doch die Türme und ihr Spiegelbild im Wasser bleiben Straßburgs bekanntestes Bild. Der an allen vier Türmen vorbeiführende Treidelweg ist an der Leine vollständig hundefreundlich.`,
      "Parc de l'Orangerie": `Straßburgs Vorzeigepark, 26 Hektar gestaltete Gärten, ein Pavillon aus der Zeit Napoleons III., ein See, ein Storchennistplatz und eine eingezäunte Freilaufzone in der nordöstlichen Ecke. Direkt neben dem Europäischen Parlament gelegen, ist er das grüne Herz des Europaviertels und die beste Hundeeinrichtung der Stadt.`,
      "Grande Île": `Die historische Insel im Herzen Straßburgs ist seit 1988 UNESCO-Weltkulturerbe, der einzige Eintrag, bei dem ein ganzes Stadtzentrum statt eines einzelnen Bauwerks klassifiziert wurde. Jede Straße, jeder Platz und jeder Kai der Insel ist mit einem Hund an der Leine begehbar.`,
      "Jardins des Deux Rives": `Ein binationaler Park beiderseits des deutsch-französischen Rheins, verbunden durch die Fußgängerbrücke Passerelle des Deux Rives. Hunde an der Leine können frei von Frankreich nach Deutschland (Kehl) wechseln, und die französische Seite verfügt über eine ausgewiesene Freilauffläche sowie informellen Zugang zum Rheinufer.`,
    },
  },
  stuttgart: {
    history: `Stuttgart begann im 10. Jahrhundert als Stuotgarten, ein königliches Gestüt, im Becken des Nesenbachs und ist bis heute eine der wenigen europäischen Landeshauptstädte, die noch von bewirtschafteten Weinbergen umringt sind, die direkt bis ins Stadtzentrum hinaufreichen. Als Landeshauptstadt Baden-Württembergs und historische Heimat der Dynastien Mercedes-Benz, Porsche und Bosch verbindet die Stadt Präzisionsingenieurskunst mit einer schwäbischen Outdoor-Kultur, Biergärten, Stäffele-Weinbergtreppen und Waldpfaden, die sie besonders gut für Hundehalter geeignet macht. Nach den Bombenangriffen von 1944 größtenteils wiederaufgebaut, ersetzte Stuttgart seinen mittelalterlichen Kern durch funktionale Nachkriegsarchitektur, bewahrte aber das Schlossgarten-Band, das das Zentrum mit dem Neckar verbindet, sowie die großen Parks auf den Anhöhen, Killesberg und Rosensteinpark, die den täglichen Hundespaziergang noch heute prägen.`,
    petTips: [`Stuttgart schreibt eine strikte, stadtweite Leinenpflicht vor, außer in den drei eingezäunten Hundeauslaufgebieten: mittlerer Schlossgarten, Rosensteinpark und Killesberg.`, `Mit dem Deutschland-Ticket oder einem beliebigen VVS-Monats- oder Wochenabo fährt Ihr Hund kostenlos in S-Bahn, U-Bahn und Bus; für Einzelfahrten kaufen Sie ein Kind-Einzelticket (ca. 1,50 €).`, `Schwäbische Biergärten und Wirtschaften heißen Hunde durchweg willkommen, in praktisch jedem traditionellen Lokal gibt es auf Wunsch kostenlos einen Wassernapf.`, `Im Sommer sollten Spaziergänge vor 10 Uhr und nach 19 Uhr eingeplant werden, das Stuttgarter Kessel staut die Hitze, und die Nachmittagstemperaturen erreichen im Juli-August 30 °C. Meiden Sie mittags die südseitigen Stäffele-Treppen.`, `24/7-Tierärztlicher Notdienst: AniCura Tierklinik Stuttgart-Plieningen (Mittlere Filderstraße 31), Tel. +49 711 637 380. Rufen Sie vor 22 Uhr an, damit das Tor aufgeschlossen wird.`],
    practicalInfo: [`Deutschland gehört zur EU, EU-Heimtierausweis, gültige Tollwutimpfung und ein ISO-11784/11785-Mikrochip sind vorgeschrieben.`, `Der Flughafen Stuttgart (STR) liegt 13 km südlich des Zentrums; die U-Bahn-Linie U6 verbindet den Flughafen in 27 Minuten mit dem Hauptbahnhof und nimmt Hunde mit (Kinderticket ca. 1,50 €).`, `Gemäßigtes Kontinentalklima: heiße Sommer (20-30 °C im Juli-August), kühle Winter (-2 bis 5 °C, gelegentlich Schnee von Dezember bis Februar), packen Sie für kurzhaarige Rassen einen Mantel ein.`, `Stuttgarter Hundehalter zahlen eine jährliche Hundesteuer (108 € im Jahr 2026), Reisende mit einem Aufenthalt unter 21 Tagen sind jedoch davon befreit.`, `Edeka, Rewe und dm-Drogerie sind die Alltagsketten für Futter und Zubehör; für Premiummarken hat Fressnapf mehrere Filialen im Umland.`],
    sights: {
      "Schlossplatz": `Stuttgarts zentraler Platz, vor dem das Neue Schloss aus dem 18. Jahrhundert thront, mit Rasenflächen, Brunnen und Terrassen. Straßenbahnlinien U5/U6/U7.`,
      "Schlossgarten": `61 Hektar grünes Band, das das Zentrum mit dem Neckar verbindet, mit einer eingezäunten Hundefreilaufzone im Mittelabschnitt zwischen Eckensee und Mineralbad Berg.`,
      "Höhenpark Killesberg": `50 Hektar großer Höhenpark nördlich des Zentrums mit gepflegten Blumenterrassen, dem 40 m hohen hölzernen Killesbergturm und einer kleinen Freilaufzone am Südende. U-Bahn U5.`,
      "Bärensee": `Der größte von drei Waldstauseen westlich des Zentrums, gelegen in 200 Jahre altem Buchenwald. 6 km Rundweg um drei Seen, Hundeschwimmen außerhalb der Schwanenbrutzeit geduldet.`,
      "Stäffele Vineyard Staircases": `Stuttgarts charakteristische Weinbergtreppen (Württembergstaffel, Eugensplatzstaffel, Karlshöhestaffel), die südseitige Hänge mit klassischem Stadtpanorama erklimmen.`,
      "Rosensteinpark": `65 Hektar großer Landschaftspark rund um Schloss Rosenstein, Stuttgarts größte städtische Grünfläche. Buchenwald, Wiesen und Verbindungswege zur Neckarpromenade.`,
    },
  },
  swinoujscie: {
    history: `Swinoujscie ist seit dem frühen 19. Jahrhundert Hafen- und Kurstadt, als preußische Ärzte erstmals seine Seeluft und Solebäder verordneten, und wuchs zu Polens westlichster Stadt heran, verteilt auf drei Ostseeinseln direkt an der deutschen Grenze. 1945 schwer beschädigt und als polnischer Marine- und Fährhafen wiederaufgebaut, trägt es die Spuren dieser Geschichte noch heute in seinem gelbbraunen Leuchtturm, dem höchsten der polnischen Küste, und im windmühlenförmigen Seezeichen Stawa Mlyny an der Hafeneinfahrt. Heute ist die Breite das prägende Merkmal der Stadt: einer der breitesten Sandstrände Polens verläuft über die gesamte Länge der Insel Uznam, dahinter liegt der 58 Hektar große Kurpark Park Zdrojowy, und eine 12 Kilometer lange Uferpromenade führt ununterbrochen bis in die deutschen Ostseebäder Ahlbeck, Heringsdorf und Bansin. Für Besucher mit Hund bietet Swinoujscie etwas an der Ostseeküste Seltenes: Polens ersten eigenen Hundestrand, seit 2006 geöffnet, seit 2022 einen eingezäunten Freilaufbereich im Kurpark und einen kompletten grenzüberschreitenden Spaziergang, den ein angeleinter Hund von Anfang bis Ende bewältigen kann.`,
    petTips: [`Die einzige echte Freilauffläche in der Stadt ist der eingezäunte, rund 4.000 Quadratmeter große Hundeauslauf, der 2022 im Park Zdrojowy angelegt wurde, Zugang über die Cisowa-Allee; überall sonst gilt Leinenpflicht, auch am Strand.`, `An den geschäftigsten Tagesstunden im Juli und August ist der Hauptstrand für Hunde eingeschränkt; der eigene Hundestrand bei Stawa Mlyny ist stattdessen ganzjährig geöffnet.`, `Ein Maulkorb ist nur für nach polnischem Recht als aggressiv eingestufte Rassen vorgeschrieben; die meisten Hunde benötigen auf öffentlichen Straßen, in Parks und am Strand lediglich eine Leine.`, `Es gibt keinen 24-Stunden-Tierarzt in Swinoujscie; die nächste rund um die Uhr geöffnete Tierklinik befindet sich in Szczecin, etwa 105 km entfernt, speichern Sie die Nummer, bevor Sie sie brauchen.`, `Wer die Promenade nach Deutschland gehen möchte, sollte den EU-Heimtierausweis des Hundes sowie den eigenen Ausweis oder Reisepass mitführen; beide Länder haben seit 2023 zeitweise wieder Stichproben an dieser Grenze eingeführt.`],
    practicalInfo: [`Nächstgelegener Flughafen: Szczecin-Goleniow (SZZ), etwa 100 km / 1,5 Std. mit dem Auto südlich. Ein direkter Regionalzug verbindet Szczecin in etwa 1:45 Std. mit dem Bahnhof Swinoujscie Centrum.`, `Swinoujscie ist flach und kompakt; Leuchtturm, Stawa Mlyny, Hundestrand und Park Zdrojowy sind alle innerhalb von 15 Gehminuten miteinander verbunden.`, `Polen verwendet den Zloty (PLN), nicht den Euro, wenngleich viele touristische Betriebe an der Uferpromenade wegen der deutschen Tagesausflügler beide Währungen anzeigen. Kartenzahlung ist weit verbreitet.`, `Tierärztliche Praxen tagsüber: Gabinet Weterynaryjny Vet Medica (ul. Wojska Polskiego 4A-B/5C, +48 887 849 585) und Przychodnia Weterynaryjna Brosvet (ul. Warszawska 29, +48 91 321 70 60). Nächste 24-Stunden-Klinik: Szczecin, etwa 105 km entfernt.`, `Hauptsaison ist Juli-August, wenn sich die Bevölkerung vervielfacht und die Strandzeiten-Beschränkung gilt; Spätfrühling und September bieten einen ruhigeren, noch milden Besuch mit weniger Strandbeschränkungen.`],
    sights: {
      "Latarnia Morska": `Der fast 65 Meter hohe gelbbraune Leuchtturm aus der Mitte des 19. Jahrhunderts ist der höchste an der polnischen Ostseeküste. Das Gelände heißt angeleinte Hunde willkommen, wobei die enge Wendeltreppe im Inneren am besten nacheinander bewältigt wird, während der andere Halter unten wartet.`,
      "Stawa Mlyny": `Ein weißes, windmühlenförmiges Seezeichen, das 1873-1874 zur Lenkung der Schiffe in den Hafen errichtet wurde, und eines der bekanntesten Wahrzeichen der Stadt. Es liegt direkt am Ende der Promenade neben dem Hundestrand, ein leichter Leinenspaziergang und Fotostopp.`,
      "Park Zdrojowy": `Ein 58 Hektar großer Kurpark, angelegt vom Landschaftsarchitekten Peter Joseph Lenné im 19. Jahrhundert, mit altem Baumbestand, Teichen und schattigen Wegen, die den Pier mit dem Stadtzentrum verbinden. Angeleinte Hunde sind überall willkommen, und im Park selbst befindet sich ein eingezäunter Freilaufbereich.`,
      "Plaza dla Psow": `Polens allererster ausgewiesener Hundestrand, über 1.000 Quadratmeter Sand neben dem Wahrzeichen Stawa Mlyny, mit zweisprachiger Beschilderung und Kotbeutelspendern ausgestattet. Ganzjährig geöffnet, im Unterschied zur saisonalen Beschränkung am Hauptstrand.`,
      "Prom Bielik": `Eine kostenlose städtische Fähre, die etwa alle 20 Minuten den Swine-Flusskanal zur Insel Wolin überquert und Fußgänger, Radfahrer und Autos gleichermaßen mitnimmt. Hunde reisen an der Leine kostenlos, und die kurze Überfahrt ist selbst eine Attraktion.`,
      "Promenada do Ahlbeck": `Eine ebene, gepflasterte Uferpromenade, die vom Zentrum Swinoujscies bis in die deutschen Ostseebäder Ahlbeck, Heringsdorf und Bansin auf der Insel Usedom führt, etwa 12 km einfache Strecke. Angeleinte Hunde können die gesamte Route gehen; führen Sie Ausweis oder Reisepass mit, da seit 2023 zeitweise wieder Grenzkontrollen eingeführt wurden.`,
    },
  },
  sydney: {
    history: `Sydney wuchs aus der Strafkolonie von 1788 an der Sydney Cove zur größten Stadt Australiens heran, rund 5,3 Millionen Menschen rund um einen der großartigsten natürlichen Naturhäfen der Welt. Seine Sandsteinklippen, Ozeanstrände und Buschland-Reservate prägen eine berühmt naturverbundene Lebensweise, und Hunde sind fest darin verankert: Hundestrände am Hafen, riesige Gemeindereservate und eine ganzjährige Terrassen- und Biergartenkultur. Zwei örtliche Gegebenheiten bestimmen einen Besuch mit Hund. Erstens ist der Zugang streng zoniert: Die berühmten Surfstrände (Bondi, Manly, Coogee) verbieten Hunde, Freilaufzonen sind nach Zone und Uhrzeit gekennzeichnet, und Nationalparkgebiet ist für Haustiere gesperrt. Zweitens gilt dies weitgehend auch für den öffentlichen Nahverkehr, sodass die meisten Halter mit dem Auto oder einem haustierfreundlichen Fahrdienst unterwegs sind. Der Lohn für die Planung um diese Regeln herum ist eine der wirklich hundefreundlichsten Großstädte überhaupt, mit exzellenten 24/7-Notfalltierärzten und einer ausgeprägten Tierpflege-Wirtschaft.`,
    petTips: [`Der Zugang zu Stränden und Freilaufflächen ist streng zoniert: Die Surfstrände (Bondi, Manly, Coogee) verbieten Hunde; anderswo hängt der Freilauf von Zone und Uhrzeit ab, Bußgelder ab rund 220 AUD.`, `Die Paralysezecke (Ixodes holocyclus) lebt entlang der Küste und im Buschland und kann tödlich sein: Verwenden Sie ein vom Tierarzt empfohlenes Präventivmittel und untersuchen Sie Ihren Hund täglich nach einem Busch- oder Küstenspaziergang.`, `Der Sommer ist heiß und schwül: Gehen Sie früh morgens oder abends spazieren, prüfen Sie Gehweg und Sand mit der Hand, und lassen Sie einen Hund niemals in einem geparkten Auto zurück.`, `Der öffentliche Nahverkehr schließt Haustiere weitgehend aus: keine Hunde in Zügen oder der Metro; Busse, Straßenbahnen und Fähren nehmen nur kleine Haustiere in einer Transportbox nach Ermessen des Personals mit, planen Sie also mit Auto oder haustierfreundlichem Fahrdienst.`, `24/7-Notfälle: SASH Alexandria (nahe der Innenstadt) und North Ryde (im Norden) sowie das Animal Referral Hospital in Homebush (innerer Westen); speichern Sie eine Nummer und rufen Sie vorher an.`],
    practicalInfo: [`Australien hat eine der weltweit strengsten Biosicherheitsvorschriften: Die Einfuhr ist auf zugelassene Länder beschränkt und erfordert eine Einfuhrgenehmigung, ISO-Mikrochip, Tollwutimpfung und einen RNATT-Titertest, vorgeschriebene Behandlungen sowie danach eine staatliche Quarantäne von mindestens 10 Tagen in der Einrichtung Mickleham bei Melbourne. Rechnen Sie mit mehreren Monaten Vorbereitung.`, `Flughafen: Sydney Kingsford Smith (SYD) ist das Haupttor; lebende Tiere durchlaufen die Quarantäneeinrichtung in Melbourne, bevor es mit einem Inlandsflug weiter nach Sydney geht. Prüfen Sie die Tiertransportregeln Ihrer Fluggesellschaft.`, `Währung: der australische Dollar (AUD). Ein haustierfreundliches Budget liegt im mittleren bis hohen Bereich: Kalkulieren Sie einen Spielraum für Tiertaxis, Fahrdienste und bezahlte Sitter ein, da öffentliche Verkehrsmittel für Haustiere gesperrt sind.`, `Beste Reisezeiten: Frühling (September-November) und Herbst (März-Mai) sind mild zum Spazierengehen; der Sommer (Dezember-Februar) ist heiß und schwül mit Zecken- und Hitzerisiko; der Winter (Juni-August) ist mild und sonnig, ideal für Spaziergänge.`, `Gesetz: Der NSW Companion Animals Act schreibt Leinenpflicht im öffentlichen Raum außerhalb ausgewiesener Freilaufzonen vor, mit Bußgeldern durch die Gemeinde; anerkannte Assistenzhunde sind überall zugelassen, auch in Verkehrsmitteln.`],
    sights: {
      "Sydney Park": `Die größte Freilauffläche der Innenstadt, auf ehemaligen Ziegeleihügeln in Alexandria gelegen, mit Feuchtgebieten, weiten Rasenflächen und Stadtblick. Morgens und abends der Treffpunkt für Hunde aus dem inneren Westen.`,
      "Centennial Parklands": `Einer der großartigsten Stadtparks der Welt, mit rund 43 Prozent seiner Freifläche als Freilaufzone ausgewiesen (Sandstone Ridge, Federation Valley). Hunde bleiben den Teichen, Spielplätzen und dem Bereich um den Pavillon fern.`,
      "Rose Bay Foreshore": `Ein ruhiger Hafenstrand in den östlichen Vororten, an dem Hunde jederzeit auf dem markierten Abschnitt zwischen Dumaresq Reserve und Percival Park frei laufen dürfen. Einer der wenigen ganztägigen Hundestrände Sydneys.`,
      "Barangaroo Reserve": `Ein rekonstruiertes Sandsteinvorland am westlichen Rand des Stadtzentrums, mit Uferpromenade und Brückenblick. Hunde sind überall an der Leine willkommen und dürfen im Wasser der Schwimmbucht Marrinawi Cove baden.`,
      "Federation Cliff Walk": `Ein Klippenpfad von Dover Heights Richtung Watsons Bay am Macquarie Lighthouse vorbei, mit weiten Meeresblicken und Freilaufreservaten (Raleigh Reserve, Lighthouse Reserve). Am Gap Park und im Nationalparkbereich sind Hunde verboten.`,
      "Glebe Foreshore Walk": `Ein Uferspaziergang im inneren Westen von Blackwattle Bay bis zum Bicentennial Park, gesäumt von hundefreundlichen Cafés. Angeleinte Hunde auf dem Weg, mit Blick auf die Anzac Bridge und die Bucht.`,
    },
  },
  sylt: {
    history: `Sylt ist die größte der nordfriesischen Inseln, ein langes Sandband aus Dünen und Heide in der Nordsee vor Schleswig-Holstein. Seit 1927 durch den Hindenburgdamm mit dem Festland verbunden, hat sie keine Straßenbrücke: Autos werden in Niebüll auf den Autozug verladen, während Fußgänger mit dem Zug in Westerland, dem Hauptort, ankommen. Darum gruppieren sich im Süden die Orte Kampen, Wenningstedt, Rantum und Hörnum sowie im äußersten Norden List. Die Insel lebt vom gehobenen Küstentourismus, aber auch von Fischerei und Schafbeweidung auf ihren Deichen. Ihre Westküste zieht sich vierzig Kilometer Strand entlang der Nordsee, im Osten liegt das Wattenmeer, ein UNESCO-Weltnaturerbe. Für Hundehalter ist Sylt außergewöhnlich: Jeder Ort hat seinen eigenen offiziellen Hundestrand, und die Aufnahme von Haustieren wird einfach als selbstverständlich vorausgesetzt.`,
    petTips: [`Jeder Sylter Ort hat seinen eigenen offiziellen Hundestrand: Westerland, Wenningstedt, Kampen, Rantum, Hörnum und List. In der Hauptsaison (etwa 15. März bis 31. Oktober) sind Hunde auf diese Abschnitte beschränkt, oft an der Leine; vom 1. November bis 14. März laufen sie an den meisten Stränden frei.`, `Im Nationalpark Wattenmeer und den Dünenreservaten (Hörnum-Odde, der Ellenbogen, Braderuper Heide, Morsum Kliff) besteht ganzjährig Leinenpflicht, besonders im Frühjahr, wenn Vögel am Boden brüten.`, `In List und auf dem Ellenbogen weiden Schafe frei: Halten Sie den Hund jederzeit an der Leine, das Hetzen von Schafen wird schwer bestraft.`, `Das Klima ist das ganze Jahr über kühl, feucht und sehr windig; selbst im Sommer werden selten mehr als 20°C erreicht. Bringen Sie ein Handtuch zum Trocknen eines nassen Hundes mit und wählen Sie an windigen Tagen dünengeschützte Strandplätze.`, `Immer aufräumen: An den meisten Strandzugängen stehen Kotbeutelspender, kostenlose Beutel gibt es auch im List Tourist Office; es drohen Bußgelder.`],
    practicalInfo: [`Tierärzte auf der Insel: Tierarztpraxis Wohlenberg in Westerland (Königskamp 25, Tel. 04651 35677) und Tierarztpraxis Petersen in Wenningstedt-Braderup, die eine Notfall-Mobilnummer angibt (0173 6109226).`, `Deutschland ist EU-Mitglied: Aus einem anderen EU-Land benötigen Sie lediglich Mikrochip, gültige Tollwutimpfung und EU-Heimtierausweis; für Ankünfte von außerhalb der EU gelten strengere Regeln.`, `Es gibt keine Brücke: Autos queren mit dem Sylt Shuttle-Autozug ab Niebüll, wo der Hund im Auto bleibt und kostenlos mitreist (ein eingezäunter Hundeauslauf befindet sich am Terminal).`, `Im Deutsche-Bahn-Zug über den Hindenburgdamm reisen kleine Hunde in einer Transportbox kostenlos; größere Hunde zahlen 50 % des Fahrpreises der zweiten Klasse und müssen an Bord Maulkorb und Leine tragen.`, `Im Nationalpark Wattenmeer und den Dünenreservaten gilt ganzjährig Leinenpflicht; in List und auf dem Ellenbogen, wo Schafe weiden, gilt sie jederzeit.`],
    sights: {
      "Hundestrand Westerland": `Westerlands offizieller Hundestrand am nördlichen Ende des Hauptorts nahe der Nordseeklinik bietet einen weiten Sandstreifen, auf dem sich Hunde zu Hause fühlen. In der Hauptsaison (etwa 15. März bis 31. Oktober) besteht Leinenpflicht; vom 1. November bis 14. März laufen Hunde an den meisten Stränden der Insel frei.`,
      "Rotes Kliff, Kampen": `Kampens Rotes Kliff, eine rund dreißig Meter hohe Wand aus ockerrotem Geröll, die sich etwa vier Kilometer entlang der Westküste erstreckt, ist Sylts Wahrzeichen. Der Klippenpfad und der Strand darunter werden beide mit einem angeleinten Hund begangen, am schönsten im weichen Licht von morgens oder abends.`,
      "Braderuper Heide": `Eine von Sylts größten Heideflächen zwischen Kampen und Braderup über dem Wattenmeer, durchzogen von Holzstegen. Ende August und im September verfärbt sich das Heidekraut lila. Es ist ein geschütztes Naturschutzgebiet: Zum Schutz bodenbrütender Vögel gilt ganzjährig Leinenpflicht.`,
      "Lister Ellenbogen": `Die wilde Dünenhalbinsel an der Nordspitze der Insel, der nördlichste Punkt Deutschlands, mit zwei Leuchttürmen und einem langen, fast menschenleeren Strand. Eine atemberaubende Landschaft für einen Spaziergang, doch hier weiden Schafe frei und Vögel brüten: Der Hund bleibt überall und ganzjährig an der Leine.`,
      "Keitum": `Das grüne Herz Sylts, ein Dorf mit reetgedeckten friesischen Kapitänshäusern, eingebettet zwischen alten Bäumen an der geschützten Ostküste. Seine Gassen, Gärten und der niedrige Weg entlang des Wattenmeers bieten einen ruhigen Spaziergang mit angeleintem Hund, ideal bei schlechtem Wetter, wenn die offenen Strände zu exponiert sind.`,
      "Nationalpark Wattenmeer": `Das Watt des Wattenmeers, ein UNESCO-Weltnaturerbe, eine sich ständig wandelnde Gezeitenlandschaft an der Ostseite der Insel. Geführte Wattwanderungen starten in Hörnum; manche akzeptieren angeleinte Hunde. Schutzgebiet: Es gilt jederzeit Leinenpflicht, und Sie müssen sich von den Vögeln fernhalten; wagen Sie sich nie ohne Führung ins Watt.`,
    },
  },
  syracuse: {
    history: `Syrakus wurde 734 v. Chr. von korinthischen Siedlern gegründet und war eine der mächtigsten Städte der griechischen Welt, Rivale Athens und Heimat des Archimedes, der hier während der römischen Belagerung 212 v. Chr. getötet wurde. Cicero nannte sie „die größte und schönste der griechischen Städte“. Von diesem Glanz sind das griechische Theater, die Latomien-Steinbrüche und das Ohr des Dionysios im archäologischen Park Neapolis erhalten geblieben. Das Herz der Stadt schlägt auf der Insel Ortigia, einem barocken Labyrinth, das nach dem Erdbeben von 1693 wiederaufgebaut wurde und wo der Dom in einem Athena-Tempel steht, dessen dorische Säulen noch immer in den Mauern sichtbar sind. Als UNESCO-Welterbe gelistet, wird Syrakus zu Fuß erlebt: mit Hund fügen sich Ortigia im ersten Morgenlicht, die Uferpromenade und das Naturreservat Plemmirio zu einer strahlenden sizilianischen Route aus goldenem Stein und türkisem Wasser.`,
    petTips: [`In Italien ist die Leine in der Stadt Pflicht, und Sie müssen einen Maulkorb mitführen, der angelegt werden muss, wenn die Behörden oder ein Verkehrsbetrieb dies verlangen.`, `Der sizilianische Sommer ist glühend heiß: Spaziergänge nur bei Sonnenaufgang und am Abend, niemals mittags über die Steinplatten Ortigias, sie speichern die Hitze.`, `An freien Stränden werden Hunde außerhalb der Saison geduldet, an den bewirtschafteten Lidos im Sommer jedoch oft verboten: Achten Sie auf die Buchten von Plemmirio und die kommunale Beschilderung.`, `Die AST-Stadtbusse nehmen kleine Haustiere in Transportboxen mit; für große Hunde können nach den aktuellen Regeln Maulkorb und Ticket erforderlich sein.`, `Parasitenschutz ist unerlässlich: Leishmaniose ist in Süditalien endemisch, schützen Sie Ihren Hund von Frühling bis Herbst vor Sandmücken.`],
    practicalInfo: [`Tierärztliche Kliniken in Syrakus und den Nachbarorten; für komplexe Notfälle sind die tierärztlichen Einrichtungen Catanias etwa eine Stunde mit dem Auto entfernt`, `Europäische Notrufnummer: 112; Ihre Unterkunft kennt den diensthabenden Tierarzt der Region`, `Tierbedarfsgeschäfte in der Stadt und Tierabteilungen in Supermärkten; auf Ortigia selbst sind Geschäfte spärlicher gesät`, `Trenitalia-Regionalzüge: kleine Haustiere in Transportboxen reisen kostenlos, große Hunde an der Leine mit Maulkorb zum ermäßigten Fahrpreis gemäß aktuellen Regeln`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung sind vorgeschrieben; planen Sie zudem Leishmaniose- und Zeckenschutz ein, passend für Süditalien`],
    sights: {
      "Ortigia": `Syrakus' historisches Inselzentrum wird an der Leine zwischen barocken Palästen, schattigen Gassen und der Uferpromenade erkundet. Früh am Morgen, wenn die Fischer zurückkehren und die Plätze leer sind, ist es einer der schönsten Stadtspaziergänge Siziliens.`,
      "Parco Archeologico della Neapolis": `Das aus dem Fels gehauene griechische Theater, das Ohr des Dionysios und die Latomien-Steinbrüche bilden eine der großen antiken Stätten des Mittelmeerraums. Hunde sind in der Regel nicht zugelassen: Besuchen Sie abwechselnd, während Ihr Begleiter im Schatten eine Pause genießt.`,
      "Fonte Aretusa": `Diese Süßwasserquelle am Meeresrand, bepflanzt mit wildem Papyrus, hat seit der Antike Mythen genährt: Die Nymphe Arethusa soll sich hier in eine Quelle verwandelt haben. Der überblickende Aussichtspunkt und der benachbarte Lungomare sind an der Leine frei begehbar.`,
      "Riserva del Plemmirio": `Das Meeresschutzgebiet südlich der Stadt reiht Kalksteinbuchten, kristallklares Wasser und Küstenpfade auf der Halbinsel Maddalena aneinander. Die Pfade werden an der Leine begangen; für das Hundeschwimmen folgen Sie der Beschilderung, manche Buchten schränken es im Sommer ein.`,
      "Duomo di Siracusa": `Ortigias Kathedrale umschließt einen dorischen Athena-Tempel aus dem 5. Jahrhundert v. Chr., dessen Säulen sich durch die Mauern ziehen. Hunde bleiben draußen, doch die Piazza Duomo, ein Bogen aus weißem Stein, ist eines der schönsten städtischen Wohnzimmer Italiens.`,
      "Mercato di Ortigia": `Der Morgenmarkt in der Via de Benedictis quillt über von Zitrusfrüchten, Fisch und sizilianischem Käse in einem fröhlichen Marktgeschrei. Angeleinte Hunde schlängeln sich außerhalb der Stoßzeit problemlos hindurch; die Sandwiches an der Theke sind das Anstehen wert.`,
    },
  },
  tallinn: {
    history: `Tallinn erscheint erstmals 1154 auf einer arabischen Karte und trat 1285 der Hanse bei, wodurch seine Altstadt zu einem der besterhaltenen mittelalterlichen Ensembles Europas wurde und seit 1997 UNESCO-Welterbe ist. Die estnische Hauptstadt mit rund 460.000 Einwohnern verzeichnet etwa 30.000 Hunde, eine Zahl, die seit der Abschaffung der örtlichen Hundesteuer 2014 stark gewachsen ist. Tallinn ist wohl die hundefreundlichste Stadt im Baltikum: Alle öffentlichen Verkehrsmittel sind für Einwohner kostenlos (Hunde eingeschlossen, große mit Maulkorb), eingezäunte Hundeauslaufplätze (koerte jalutusväljak) gibt es in jedem Stadtteil, und historische Bastionen wie Toompea werden morgens routinemäßig mit Haustier begangen. Das estnische Recht schreibt Leinenpflicht in bebauten Gebieten und Maulkorbpflicht für große Rassen in öffentlichen Verkehrsmitteln vor, die Durchsetzung ist jedoch entspannter als bei den nordischen Nachbarn, solange man aufräumt und höflich bleibt.`,
    petTips: [`Nicht-Einwohner zahlen 2 € pro Fahrt für einen Hund in Straßenbahnen, Oberleitungsbussen und Bussen; große Rassen müssen an Bord einen Maulkorb tragen.`, `Das Kopfsteinpflaster der Altstadt heizt sich im Juli schnell auf, nehmen Sie die schattigen Straßen Vene und Müürivahe und prüfen Sie die Pfotentemperatur mit der Hand.`, `Estland wendet die EU-Heimtierausweis-Regeln an; die Tollwutimpfung muss mindestens 21 Tage zurückliegen, und Zeckenschutz ist von April bis Oktober unverzichtbar.`, `24/7-Tierärztlicher Notdienst: Loomakliinik Well, Paldiski mnt 50A (+372 600 2837), 5 Min. mit Straßenbahnlinie 1 vom Zentrum entfernt.`, `Nutzen Sie die kostenlosen blauen Kotbeutelspender in jedem Tallinner Hundepark; wer nicht aufräumt, riskiert 40 € Bußgeld vor Ort.`],
    practicalInfo: [`Der Flughafen Tallinn (TLL) ist Europas nächstgelegener zu einer Hauptstadt, 4 km entfernt, in 15 Min. mit Straßenbahnlinie 4 erreichbar; Hunde zahlen den Standardfahrpreis.`, `Beste Reisezeiten: Mai-September für Meerbäder in Pirita, Ende Dezember für verschneite Altstadtgassen.`, `24/7-Tierärztlicher Notdienst: Loomakliinik Well, Paldiski mnt 50A, +372 600 2837.`, `Tallink- und Viking-Line-Fähren nach Helsinki (2 Std.) nehmen Hunde ab 25 € für Hin- und Rückfahrt in Tierkabinen mit; im Sommer frühzeitig buchen.`, `Tallinns Leitungswasser aus dem Ülemiste-See ist ganzjährig sicher und kalt, kostenlose Nachfüllstationen entlang der Kulturmeile.`],
    sights: {
      "Vanalinn & Toompea": `Eine im 13. Jahrhundert ummauerte Stadt mit 1,9 km Wallanlagen, Kopfsteingassen und dem rosa Schloss Toompea. Hunde an der Leine können überall im Freien spazieren gehen, auch auf den Aussichtsplattformen Kohtuotsa und Patkuli, nur die Kirchen und das Parlament bleiben tabu.`,
      "Kadriorg Park & Palace Gardens": `Peter der Große errichtete 1718 diese barocke Sommerresidenz in einem 70 Hektar großen Park mit Schwanenteich, japanischem Garten und der präsidialen Rosenallee. Angeleinte Hunde streifen überall im Freien umher, und der Park führt über eine Kiefernpromenade direkt bis zum Meer in Pirita.`,
      "Pirita Beach & Promenade": `Ein 2 km langer Ostseesandstrand 5 km von der Altstadt entfernt, mit einer markierten Hundeschwimmzone an seinem östlichen Ende, jenseits des TOP-Sport-Zentrums. Außerhalb der Saison (Oktober-April) ist praktisch der gesamte Strand freilauf-tauglich.`,
      "Telliskivi Creative City": `Ein ehemaliges sowjetisches Bahndepot, wiedergeboren als Tallinns coolstes Kreativviertel, mit Streetart, Vintage-Läden, dem Fotografiska-Museum und über 20 Restaurants. Die meisten Cafés, F-hoone, Peatus und Kivi Paber Käärid, heißen Hunde offen im Innenbereich willkommen, samt Napf.`,
      "Kalamaja & Patarei Seafront": `Ein Viertel mit pastellfarbenen Holzhäusern neben dem sowjetzeitlichen Seefort und Gefängnis Patarei. Die Uferpromenade Kulturmeile führt 2 km entlang des Wassers bis zum Wasserflugzeughafen Lennusadam, im Freien vollständig hundefreundlich.`,
      "Löwenruh Park Dog Area": `Im Stadtteil Kristiine enthält dieser romantische Park aus dem 19. Jahrhundert eine von Tallinns größten eingezäunten Freilaufzonen mit Agility-Geräten, Wasserzapfstellen und schattigen Bänken. Straßenbahnlinie 4 hält direkt am Tor.`,
    },
  },
  tampere: {
    history: `Tampere, 1779 an den Tammerkoski-Stromschnellen gegründet, die die Seen Näsijärvi und Pyhäjärvi verbinden, wurde im 19. Jahrhundert dank der Baumwollspinnerei Finlayson (1820), einer der größten Nordeuropas, zum „Manchester Finnlands“. Die Stadt war Schauplatz entscheidender Momente der finnischen Geschichte, des Bürgerkriegs von 1918, der offiziellen Unabhängigkeitserklärung von Russland 1917 im Finlayson-Ratssaal, des ersten öffentlichen Treffens zwischen Lenin und Stalin. Heute die drittgrößte Stadt des Landes (240.000 Einwohner) und inoffizielle Sauna-Hauptstadt, ist Tampere eine der hundefreundlichsten Städte Europas: Nysse-Straßenbahnen und VR-Züge sind für angeleinte Hunde kostenlos (kein Maulkorb, kein Ticket), 22 eingezäunte kommunale koira-aitaus, zwei Hundestrände am See 15 Min. zu Fuß vom Zentrum entfernt und der Bergrücken Pyynikki, der weltweit höchste Kiesos, mit seinem legendären Aussichtsturm-Café.`,
    petTips: [`Die finnische Café-Kultur heißt Hunde standardmäßig willkommen, etwa 75 % der Tampere kahvilat lassen angeleinte Hunde ganzjährig im Hauptraum zu.`, `Nysse-Straßenbahnen und VR-Züge: angeleinte Hunde KOSTENLOS, kein Maulkorb, kein Ticket erforderlich, eine der großzügigsten Regelungen Europas.`, `22 eingezäunte kommunale koira-aitaus, offizielle Karte unter tampere.fi/koirat; Leinenpflicht vom 1. März bis 19. August in nicht eingezäunten Zonen.`, `24/7-Tierärztlicher Notdienst: Evidensia Eläinsairaala in Hervanta (+358 200 60080), 12 Min. mit dem Auto oder der Straßenbahnlinie 1.`, `Finnland verlangt eine Bandwurmbehandlung (Echinokokkose), die 24-120 Std. vor der Einreise verabreicht und im EU-Heimtierausweis dokumentiert werden muss.`],
    practicalInfo: [`Finnland gehört zur EU und zum Schengen-Raum: EU-Heimtierausweis + gültige Tollwutimpfung + ISO-Mikrochip + Bandwurmbehandlung 24-120 Std. vor der Ankunft.`, `Direkte VR-Züge: Helsinki 1:30 Std., Turku 2 Std., Jyväskylä 1:30 Std., Oulu 4 Std., Rovaniemi 8 Std., angeleinte Hunde kostenlos in haustierzugelassenen Wagen.`, `Flughafen Tampere-Pirkkala (TMP) 35 Min. mit Straßenbahnlinie 1; Helsinki-Vantaa (HEL) 1:45 Std. mit Direktzug, haustierfreundliche Flüge bei Finnair, KLM, Lufthansa.`, `Währung: Euro. Tägliches haustierfreundliches Budget: 70-95 €/Tag ohne Unterkunft, eines der niedrigsten in Skandinavien.`, `Zu meidende Festivals mit ängstlichem Hund: Tampere Floral Festival (Juni), Tampere Filmfestival (März), Eurovision Song Contest 2026 (Mai, falls Finnland Gastgeber ist).`],
    sights: {
      "Tammerkoski Rapids": `Dramatische Stromschnellen zwischen den beiden Seen, UNESCO-Uferweg rund um die Uhr geöffnet, hundefreundlich mit angeleinten Hunden.`,
      "Pyynikki Ridge & Tower": `Der weltweit höchste Kiesos, legendäres Aussichtsturm-Café von 1929, Panoramaterrasse über beide Seen, hundefreundliche Waldpfade.`,
      "Finlayson Quarter": `Baumwollspinnerei von 1820, heute Kreativviertel, Innenhöfe, Wege und Terrassen ganzjährig hundefreundlich mit angeleinten Hunden.`,
      "Pyynikki Dog Beach": `Offizieller Hundestrand am Pyhäjärvi-See, 15 Min. zu Fuß vom Zentrum entfernt, sandiger Einstieg, ganzjährig zugänglich.`,
      "Hatanpää Arboretum": `7 Hektar großer Gutsgarten am Südufer des Pyhäjärvi, 6.000 Arten, Rosengarten, Gutscafé, angeleinte Hunde.`,
      "Kauppi Forest": `Tamperes größter Stadtwald, 700 ha, 30 km Wanderwege, 4 eingezäunte koira-aitaus, direkter Zugang zum See Näsijärvi.`,
    },
  },
  taormina: {
    history: `Taormina thront 200 Meter über dem Ionischen Meer auf einem Ausläufer des Monte Tauro, gegenüber dem Ätna (3.357 m). Von den Sikelern gegründet und im 4. Jahrhundert v. Chr. von den Griechen als Tauromenion kolonisiert, hat die Stadt ein spektakuläres griechisch-römisches Teatro Antico bewahrt, das noch immer mit dem Ätna im Hintergrund über die Bucht blickt. Unter Römern, Arabern, Normannen und Aragonesen blieb Taormina ein beliebter Erholungsort: Goethe, Brahms, Truman Capote und D.H. Lawrence hielten sich hier auf, und 2022 wurde die zweite Staffel der HBO-Serie The White Lotus im San Domenico Palace gedreht. Die Gemeinde zählt nur 11.000 ständige Einwohner, zieht aber mehrere Millionen Besucher jährlich an. Die Sizilianer heißen angeleinte Hunde willkommen: die Fußgängerzone Corso Umberto, die Gärten der Villa Comunale und die meisten Café-Terrassen nehmen sie gerne auf.`,
    petTips: [`Die Seilbahn Funivia Taormina-Mazzarò nimmt kleine Hunde in einer Transportbox kostenlos und große Hunde mit Maulkorb an der Leine mit; erkundigen Sie sich am Ticketschalter unten an der Via Pirandello.`, `Trenitalia-Regionalzüge (Bahnhof Taormina-Giardini, 5 km unterhalb) nehmen Hunde ≤6 kg in einer Transportbox kostenlos mit, größere Hunde mit Maulkorb zum halben Fahrpreis.`, `Im Sommer erreichen Corso Umberto und die Tuffstein-Treppen 32-34 °C: Gehen Sie mit Ihrem Hund vor 10 Uhr oder nach 18 Uhr spazieren und führen Sie Wasser mit; der Scirocco-Wind bringt noch mehr Hitze.`, `Bei Isola Bella und Mazzarò sind angeleinte Hunde außerhalb der Badesaison (Oktober bis April) zugelassen; für ganzjähriges Hundeschwimmen fahren Sie zum Sea Cup Beach in Letojanni, 5 km nördlich.`, `Ein Ätna-Ausflug ist mit angeleintem Hund bis zur Rifugio Sapienza (1.923 m, 1 Std. Fahrt) möglich; die Gipfelseilbahnen nehmen keine Tiere mit, bleiben Sie also auf den unteren Pfaden des Parco dell'Etna.`],
    practicalInfo: [`Tierarzt im Stadtzentrum: Ambulatorio Veterinario Città di Taormina, Via Diodoro Siculo 12, +39 0942 21180`, `Außerhalb der Öffnungszeiten: Ambulatorio Veterinario Dott. La Manna, Via Francavilla 7/A, +39 0942 577168`, `EU-Heimtierausweis wird akzeptiert; keine Quarantäne für EU-Haustiere`, `Anreise: Flughafen Catania (CTA, 1 Std. mit dem Auto oder Bus Etna Trasporti / SAIS), dann Trenitalia-Regionalzug oder Interbus nach Taormina`],
    sights: {
      "Teatro Antico di Taormina": `Dieses griechisch-römische Theater aus dem 3. Jahrhundert v. Chr., von den Römern überarbeitet, ist Siziliens spektakulärstes: Es öffnet sich direkt zum Ätna und zur Bucht hin. Angeleinte Hunde sind im archäologischen Freiluftbereich zugelassen (vor dem Besuch beim Parco Archeologico nachfragen). Die sommerlichen Taormina-Arte-Konzerte füllen es allabendlich.`,
      "Corso Umberto": `Die Fußgängerachse, die Taormina von Porta Catania bis Porta Messina durchquert, bündelt Geschäfte, Gelaterien und Cafés. Ein idealer Leinenspaziergang, besonders morgens vor den Menschenmassen oder in der Dämmerung zur passeggiata.`,
      "Villa Comunale": `Die 1922 von Florence Trevelyan angelegte öffentliche Gartenanlage „Parco Duca di Cesarò“ bietet ein Panorama über den Ätna und das Ionische Meer. Angeleinte Hunde sind auf den schattigen Wegen willkommen, ideal bei sommerlicher Hitze.`,
      "Isola Bella": `„Die Perle des Mittelmeers“, ein Inselchen, das über einen bei Ebbe begehbaren Kieselstrand-Damm mit dem Ufer verbunden ist. Ein regionales Naturschutzgebiet: Angeleinte Hunde sind außerhalb der Badesaison (Oktober bis April) auf dem Damm und am Strand zugelassen.`,
      "Funivia Taormina-Mazzarò": `Die 5-minütige Seilbahn verbindet das zentrale Taormina mit der 200 m tiefer gelegenen Bucht Mazzarò. Kleine Hunde in einer Transportbox sind zugelassen; große Hunde mit Maulkorb und Leine werden in der Regel akzeptiert (am Ticketschalter erfragen).`,
      "Castelmola": `Das Bergdorf 4 km westlich von Taormina auf 550 m Höhe bietet einen 360°-Blick über den Ätna und die Bucht. Der Aufstieg (1,5 Std.) mit angeleintem Hund ist anspruchsvoll, wird aber durch die Dorfgassen und einen Halt in der Bar Turrisi belohnt.`,
    },
  },
  tarifa: {
    history: `Tarifa, der südlichste Punkt des europäischen Festlands, liegt auf der Landzunge, an der sich Mittelmeer und Atlantik treffen, gegenüber Marokkos Rif-Gebirge, nur 14 km über die Straße von Gibraltar entfernt. Die Stadt trägt den Namen von Tarif ibn Malik, dem Berberfeldherrn, der 710 hier landete, und ihre weiß getünchte Altstadt ist noch immer von Almohaden-Mauern umschlossen, gekrönt vom Castillo de Guzmán el Bueno aus dem 10. Jahrhundert. Von Levante- und Poniente-Wind umweht, ist Tarifa zur Welthauptstadt des Windsurfens und Kitesurfens geworden, aber auch ein erstklassiger Ort für Wal- und Delfinbeobachtung in der Meerenge und ein bedeutender Vogelzug-Korridor. Für Reisende mit Hund bietet Tarifa weite Feinsandstrände (Los Lances, Valdevaqueros, Bolonia), ein von Wanderwegen durchzogenes Naturparkhinterland, ein mildes ganzjähriges Klima und ein 24/7-Tierkrankenhaus in Algeciras, zwanzig Autominuten entfernt. Das andalusische Zentrum ist kompakt und autofrei, perfekt zum Schlendern mit Leine in der Hand zwischen den Terrassen.`,
    petTips: [`An den großen Stränden (Los Lances, Valdevaqueros) laufen Hunde außerhalb der Saison frei; im Sommer sind sie im Allgemeinen früh morgens und nach 20 Uhr erlaubt. Prüfen Sie die kommunale Beschilderung an jedem Zugang.`, `Der Levante-Wind wirbelt Sand auf und ermüdet Hunde: Bringen Sie Wasser und Schatten mit und meiden Sie die windigsten Stunden wegen empfindlicher Ohren und Augen.`, `Der Sand kann im Hochsommer glühend heiß werden: Gehen Sie früh oder spät spazieren und prüfen Sie die Temperatur mit der Hand, bevor Sie Ihren Hund laufen lassen.`, `Nicht alle vom Hafen aus startenden Walbeobachtungstouren nehmen Haustiere mit: Bestätigen Sie dies vor der Buchung beim Anbieter.`, `Für einen Tagesausflug nach Tanger mit der Fähre benötigt Ihr Hund einen EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung; prüfen Sie vor der Abreise die Einreisebestimmungen Marokkos.`],
    practicalInfo: [`24/7-Tierkrankenhaus: Hospital Veterinario Alba, Algeciras (20 Min. von Tarifa entfernt), +34 956 667 352`, `Örtliche Klinik: Clínica Veterinaria Europa Tarifa, La Vega 221, +34 956 68 53 43`, `Fähre nach Tanger (FRS / Inter Shipping): 35 Min.; für die Rückreise sind EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich`, `Flughäfen: Jerez (1:15 Std.), Gibraltar (45 Min.), Málaga (2 Std.); keine Quarantäne für EU-Haustiere mit gültigem Ausweis`],
    sights: {
      "Playa de Los Lances": `Tarifas großer Strand, über 7 km goldener Sand, gesäumt von einer Lagune und dem Naturpark. Am nördlichen Ende befindet sich eine ausgewiesene Hundezone, wo Hunde außerhalb der Saison frei laufen und schwimmen dürfen; im Sommer bleiben sie früh morgens und am späten Nachmittag willkommen. Der klassische Ort zum Schwimmen und Spazierengehen.`,
      "Casco Antiguo y Puerta de Jerez": `Tarifas mittelalterliches Herz, ein Labyrinth aus weiß getünchten Gassen, blumengeschmückten Innenhöfen und schattigen Plätzen, betreten durch die Puerta de Jerez aus dem 13. Jahrhundert. Angeleinte Hunde sind überall willkommen, und die meisten Terrassen nehmen vierbeinige Begleiter gerne auf. Perfekt in der Kühle von Morgen oder Abend.`,
      "Playa de Valdevaqueros": `Westlich der Stadt wird diese dramatische Bucht von einer riesigen Sanddüne dominiert und vom Wind umweht, der sie zu Europas berühmtestem Kitesurf-Spot macht. Außerhalb der Sommersaison ist sie ein endloser Spielplatz für Hunde, die über den Sand und in die Wellen galoppieren können. Prüfen Sie in der Hochsaison die ausgehängten Regeln am Eingang.`,
      "Playa de Bolonia": `Zwanzig km nordwestlich birgt dieser wilde, als Naturdenkmal gelistete Strand eine 30 m hohe Wanderdüne und grenzt an die römischen Ruinen von Baelo Claudia. Der Strand heißt angeleinte Hunde außerhalb der bewachten Sommerbadezonen willkommen; das archäologische Gelände hingegen lässt sie nicht zu. Der Blick auf die Meerenge ist eindrucksvoll.`,
      "Castillo de Guzmán el Bueno": `Die Festung aus dem 10. Jahrhundert, die die Altstadt überragt, verdankt ihren Namen Guzmán el Bueno, der 1294 lieber seinen Sohn opferte, als die Festung den Belagerern zu übergeben. Hunde sind im Inneren des Denkmals nicht zugelassen, doch der angrenzende Aussichtspunkt und die äußeren Wallanlagen bieten einen offenen Spaziergang mit Blick auf den Hafen und Afrika.`,
      "Parque Natural del Estrecho": `Der Naturpark, der die gesamte Spitze der Meerenge schützt, entfaltet Küsten- und Waldpfade, darunter der Aussichtspunkt Cerro de la Peña und die Wege des Pinar del Bujeo, wo angeleinte Hunde Panoramen über zwei Kontinente genießen. Es ist auch einer der besten Beobachtungspunkte für den Vogel- und Walzug im Frühling und Herbst.`,
    },
  },
  tarragona: {
    history: `Tarragona, historische Hauptstadt der gleichnamigen katalanischen Provinz, ist das antike römische Tarraco, die Verwaltungs- und Militärmetropole, die unter Augustus mit Carthago Nova um die Kontrolle über Hispania wetteiferte. Das archäologische Ensemble von Tarraco ist seit 2000 UNESCO-Weltkulturerbe und umfasst das Amphitheater am Meer, den Circus, das Forum, die zyklopischen Mauern aus dem 3. Jahrhundert v. Chr. sowie mehrere Villen und Aquädukte. Die Stadt zählt heute rund 135.000 Einwohner (250.000 im Ballungsraum), erstreckt sich zwischen der mittelalterlichen Oberstadt (Part Alta), der zum Meer hinabführenden Rambla Nova und der Küste Costa Daurada. Bei Hunden setzt Katalonien strenge Vorschriften durch (Leine ≤2 m, genehmigungspflichtige „potenziell gefährliche“ Rassen, Pflicht zum Aufsammeln von Kot und Abspülen von Urin), doch Tarragona ist eine der einladendsten großen katalanischen Städte: drei ausgewiesene Hundestrände, rund 80 vom Tourismusamt gelistete hundefreundliche Restaurants, ein 5 km entferntes 24/7-Tierkrankenhaus in La Canonja und eine 70-minütige Rodalies-Fahrt nach Barcelona mit Hund.`,
    petTips: [`Katalanisches Dekret 6/1999: Leine ≤2 m an jedem öffentlichen Ort; Maulkorbpflicht für die acht gesetzlich als potenziell gefährlich eingestuften Rassen (Dekret 170/2002).`, `Strände: drei ausgewiesene Hundebereiche (Platja Llarga, Platja del Miracle, Bon Caponet) und die wilde Bucht Cala Fonda ganzjährig; von Juni bis September sind Hunde an bewachten Stränden verboten, Bußgelder 100–300 €.`, `24-Stunden-Tierkrankenhaus: AniCura Bofarull (La Canonja) +34 977 552 233; zentrale Klinik mit erweiterten Öffnungszeiten Hospital Veterinario Dr. Patino +34 977 235 779; Notdienst-Rotation COVT +34 977 211 989.`, `Katalanische Pflicht: Führen Sie neben dem Kotbeutel eine kleine Flasche Wasser plus verdünnte Seife mit, um Urin vom Gehweg zu spülen. Bußgelder ab 100 €.`, `Sommer: Römischer Stein und Asphalt erreichen im Juli-August zwischen 13:00 und 17:00 Uhr 45 °C. Gehen Sie bei Morgengrauen oder nach 19:00 Uhr spazieren, oder verwenden Sie Pfotenschuhe.`],
    practicalInfo: [`Anreise: Flughafen Reus (REU) 13 km, Barcelona-El Prat (BCN) 1 Std.; Renfe Rodalies ab Barcelona Sants in 70 Min.; AVE/Avlo-Hochgeschwindigkeitszug ab Camp de Tarragona mit kostenpflichtigem Hundesitzplatz.`, `Dokumente: EU-Heimtierausweis + ISO-Mikrochip + mindestens 21 Tage alte Tollwutimpfung für EU-Besucher; für Nicht-EU-Besucher (Großbritannien eingeschlossen, post-Brexit) ein innerhalb von 10 Tagen ausgestelltes Tiergesundheitszeugnis (AHC).`, `Örtlicher Nahverkehr: EMT Tarragona (Bus) nimmt kleine Hunde in Transportboxen kostenlos mit, größere Hunde außerhalb der Stoßzeiten nach Ermessen des Fahrers; Fahrpreis 1,55 €.`, `Haustierbetreuung: Rover, Gudog und TrustedHousesitters decken die Stadt ab; 14–18 € pro Nacht für Betreuung zu Hause und 10–13 € pro Spaziergang; buchen Sie 4 Wochen im Voraus für Semana Santa, die Festes de Santa Tecla (Mitte September) und Weihnachten.`, `Klima: warme Sommer 24–28 °C, gelegentlich vom Mestral-Wind durchweht; milde Winter 10–14 °C mit im Oktober konzentriertem Regen. Beste Monate mit Hund: Mai, Juni und Ende September.`],
    sights: {
      "Amfiteatre Romà": `Das römische Amphitheater aus dem 2. Jahrhundert n. Chr., in das seeseitige Vorland gehauen, bot einst 15.000 Zuschauern Platz. Der eingezäunte Innenbereich ist für Hunde ohne Assistenzfunktion gesperrt, doch der umliegende Park und der obere Aussichtspunkt bleiben offen und bieten einen der spektakulärsten Leinenspaziergänge Kataloniens.`,
      "Balcó del Mediterrani": `Der Balkon mit schmiedeeisernem Geländer am Ende der Rambla Nova, mit Blick auf das Mittelmeer und das Amphitheater. Der meistfotografierte Aussichtspunkt Tarragonas, rund um die Uhr geöffnet, angeleinte Hunde willkommen; katalanische Tradition besagt, man berührt das Eisen (tocar ferro) für Glück.`,
      "Passeig Arqueològic": `Eine 1 km lange schattige Promenade zwischen den inneren römischen Mauern (3. Jh. v. Chr.) und den äußeren Befestigungen aus dem 18. Jahrhundert, mit Aussichtspunkten, Rasenflächen und Wachtürmen. Im Freien, an der Leine, perfekt kombiniert mit dem Camp de Mart, um die ganze Mauer zu umrunden.`,
      "Parc del Francolí": `Tarragonas größter Stadtpark, 32 ha entlang des Flusses Francolí, mit eingezäunter àrea d'esbarjo per a gossos (Hundefreilauffläche), ebenen Wegen und einer Fußgängerpromenade am Flussufer. Der örtliche Alltagsspaziergang, 15 Gehminuten von der Rambla Nova entfernt.`,
      "Platja Llarga & Cala Fonda": `Östlich der Stadt setzt Platja Llarga (3 km Sand, ausgewiesener Hundebereich) die Costa-Daurada-Küste fort; ein Weg durch den Pinienwald Bosc de la Marquesa führt in 20 Min. zur Cala Fonda, der unbewachten, bei Hunden beliebten Bucht, ganzjährig geöffnet.`,
      "Catedral de Tarragona (cloister)": `Die romanisch-gotische Kathedrale aus dem 12. Jahrhundert krönt die Part Alta. Das Innere ist für Hunde ohne Assistenzfunktion gesperrt, doch der offene Kreuzgang und der umliegende Platz sind mit angeleintem Hund zugänglich und bieten einen der ruhigsten Ausblicke über die Altstadt.`,
    },
  },
  tavira: {
    history: `Ein phönizischer Handelsposten, dann eine wohlhabende maurische Stadt, wurde Tavira 1242 von den Rittern von Santiago zurückerobert, deren Burg noch heute das Gassengewirr der weißen Stadt überragt. Sein goldenes Zeitalter verdankte es dem Thunfischfang und dem Handel mit Nordafrika: Im 16. Jahrhundert war es die bevölkerungsreichste Stadt der Algarve, wohlhabend genug, um etwa dreißig Kirchen auf beiden Flussufern zu verteilen, dazu die vierseitigen Pyramidendächer, genannt tesouro-Dächer, die ihr eine unverwechselbare Silhouette verleihen. Die sogenannte Römische Brücke, sieben Bögen über den Gilão, verbindet seit Jahrhunderten die beiden Stadthälften. Das große Erdbeben von 1755 und die Verlandung des Hafens beendeten ihre Blütezeit und ließen sie fast unberührt zurück. Heute, zwischen rosafarbenen, von Flamingos gesäumten Salinen, der Ria Formosa und einem per Fähre erreichbaren Inselstrand, ist Tavira eine der sanftesten Städte der Algarve, die man mit Hund genießen kann.`,
    petTips: [`An den bewachten Stränden von Ilha de Tavira und Barril sind Hunde während der Badesaison verboten (Bußgelder drohen): Genießen Sie die Insel außerhalb der Saison, oder zielen Sie früh morgens auf die nicht konzessionierten Sandabschnitte fernab der Rettungsschwimmerposten.`, `Die Fähren zur Ilha de Tavira nehmen Hunde im Allgemeinen mit, oft kostenlos oder zum halben Preis, Leine erforderlich und manchmal Maulkorb für große Hunde verlangt: Erkundigen Sie sich je nach Betreiber am Pier.`, `In der Ria Formosa halten Sie die Leine auf den Salinendeichen und den Naturpfaden kurz: Im Frühjahr brüten Vögel, und trügerisches Wattgebiet lässt einen Hund schnell einsinken.`, `Der Algarve-Sommer ist glühend heiß: Weiße Kopfsteine und Sand übersteigen nachmittags 50 Grad, gehen Sie in den kühlen Stunden hinaus, prüfen Sie den Boden mit dem Handrücken und führen Sie stets Wasser mit, Brunnen sind außerhalb des Zentrums selten.`, `Vorsicht vor Pinienprozessionsspinnern von Januar bis April in den Küstenkiefernwäldern: Halten Sie Ihren Hund von den Raupenzügen fern und suchen Sie sofort tierärztliche Hilfe, wenn Nase oder Zunge eine berührt.`],
    practicalInfo: [`Tierarztpraxen in Tavira und den Nachbarorten für die Grundversorgung; die nächsten 24-Stunden-Tierkliniken befinden sich in Faro und Loulé, eine halbe Autostunde entfernt`, `Europäische Notrufnummer: 112`, `Tierbedarfsgeschäfte und Tierabteilungen in den Supermärkten der Stadt; Hundepflege im Zentrum verfügbar`, `CP-Regionalzüge auf der Algarve-Linie: kleine Hunde in Transportboxen reisen kostenlos, große Hunde an der Leine mit Maulkorb zum halben Fahrpreis; Inselfähren: Hunde im Allgemeinen zugelassen, am Pier nachfragen`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich; Leinenpflicht im öffentlichen Raum, Hunde an bewachten Stränden in der Saison verboten, Leishmaniose-Prophylaxe in Südportugal dringend empfohlen (Sandmücken von Mai bis Oktober aktiv)`],
    sights: {
      "Ponte Romana": `Die siebenbogige Brücke über den Gilão, trotz ihres Namens mittelalterlichen Ursprungs, ist Fußgängern vorbehalten und verbindet die beiden Ufer der Altstadt. Sie ist die Pflichtüberquerung jedes Leinenspaziergangs, besonders schön bei Sonnenuntergang, wenn sich die weißen Fassaden im Fluss spiegeln.`,
      "Castelo de Tavira": `Die nach der Rückeroberung wiederaufgebauten maurischen Mauern beherbergen einen frei zugänglichen Garten voller Bougainvillea und Jacarandas. Angeleinte Hunde streifen hier gerne umher, doch der Aufstieg auf die Wallanlagen hat kein Geländer: Halten Sie die Leine kurz und genießen Sie den Blick über die tesouro-Dächer.`,
      "Ilha de Tavira": `Elf Kilometer Sand und Dünen zwischen Lagune und Ozean, erreichbar per Fähre vom Zentrum oder von Quatro Águas. Hunde sind im Allgemeinen an Bord des Boots erlaubt, im Sommer jedoch am bewachten Strand verboten: Die Insel genießt man mit Hund am besten außerhalb der Saison, wenn der Sand wieder frei ist.`,
      "Salinas de Tavira": `Die an die Ria Formosa grenzenden Salinen färben sich im Sommer rosa und beherbergen Flamingos, Säbelschnäbler und Stelzenläufer. Die Deiche lassen sich zu Fuß oder per Rad erkunden, für Hunde ist eine kurze Leine Pflicht: Davon hängt die Ruhe der Vögel im Naturpark ab, besonders während der Frühjahrsbrut.`,
      "Torre de Tavira": `Der ehemalige Wasserturm, umgebaut zur Camera obscura, projiziert live durch ein Spiegel- und Linsensystem ein 360-Grad-Bild der Stadt und der Lagune. Die Führung findet in einem dunklen Raum statt, in den Hunde nicht mitkommen dürfen: Wechseln Sie sich ab, der Burggarten wartet zwei Schritte entfernt.`,
      "Jardim do Coreto": `Entlang des Gilão reihen der Musikpavillon-Garten und seine Uferpromenade Palmen, azulejo-Bänke und Terrassen mit Blick auf die Fischerboote aneinander. Es ist Taviras Freiluft-Wohnzimmer, perfekt für den Abendspaziergang an der Leine, der sich entlang der Kais bis zum Markt und den Salinen fortsetzt.`,
    },
  },
  tbilisi: {
    history: `Tiflis, die Hauptstadt Georgiens, erstreckt sich in einem steilen Kaukasustal am Fluss Mtkwari (Kura), an der Schnittstelle zwischen Europa und Asien. Der Legende nach geht die Gründung im 5. Jahrhundert auf König Wachtang Gorgassali zurück, der die warmen Schwefelquellen entdeckte; der Name der Stadt selbst kommt vom georgischen tbili, „warm“. Als begehrte Kreuzung war sie nacheinander persisch, osmanisch, russisch und sowjetisch, und diese Vermischung zeigt sich in der Altstadt, wo orthodoxe Kirchen, eine Moschee, eine Synagoge und Kuppelbäder nebeneinanderstehen. Seit der Unabhängigkeit 1991 vereint Tiflis geschnitzte Holzgassen, restaurierte Fassaden und kühne zeitgenössische Architektur. Für Hundehalter ist es eine überraschend einladende Stadt: Georgien duldet und versorgt seine Straßenhunde, nach Sterilisation und Impfung mit Ohrmarke versehen, und seine Parks und Hügel bieten schöne Spaziergänge.`,
    petTips: [`Georgien ist bekannt für seine Toleranz gegenüber Straßenhunden, die von der Kommune sterilisiert, geimpft und mit Ohrmarken versehen werden: Sie sind meist ruhig und gut genährt, halten Sie Ihren Hund dennoch an der Leine und vermeiden Sie Konfrontationen um Futter.`, `Sommer in Tiflis sind heiß und trocken (oft 32 bis 35 °C): Gehen Sie früh morgens oder abends spazieren, führen Sie stets Wasser mit und suchen Sie schattige Parks wie Vake statt offener Steinplätze in praller Sonne.`, `Die Altstadt besteht aus steilen Gassen und Kopfsteinpflaster, das sich an Sommernachmittagen aufheizt: Prüfen Sie den Boden mit dem Handrücken, bevor Sie Ihren Hund spazieren führen, und bevorzugen Sie die Erdpfade der Hügel.`, `Bei der Seilbahn (Narikala) und der Standseilbahn (Mtatsminda) werden kleine, getragene Hunde in der Regel zugelassen, doch die Regel variiert je nach Personal: Halten Sie für den Fall einer Ablehnung Maulkorb und weiche Transporttasche griffbereit.`, `Im Winter kann es in Tiflis oben auf den Hügeln kalt und verschneit sein; außerhalb der Stadt Vorsicht vor Herdenschutzhunden (kaukasische Owtscharkas), die die Herden bewachen und fremde Hunde nicht mögen.`],
    practicalInfo: [`Georgien liegt außerhalb der EU: Für die Rückkehr in die EU mit Haustier sind ein ISO-Mikrochip, eine gültige Tollwutimpfung und ein Tollwut-Antikörpertitertest (Blutabnahme frühestens 30 Tage nach der Impfung, danach obligatorische Wartezeit) erforderlich; planen Sie mehrere Monate im Voraus.`, `Fortbewegung: Die Metro von Tiflis nimmt Hunde nur in einer Transportbox mit, doch die Stadt ist sehr gut zu Fuß erkundbar; Taxis und Bolt nehmen Haustiere häufig mit, informieren Sie den Fahrer und führen Sie eine Decke für den Sitz mit.`, `Das Klima ist kontinental: Sommer sind heiß und trocken (Juli und August oft über 32 °C) und Winter kalt; führen Sie im Sommer stets Wasser mit und planen Sie Ausflüge für die kühlen Stunden.`, `Für einen tierärztlichen Notfall betreiben mehrere moderne Kliniken in den Vierteln Vake und Saburtalo; führen Sie Gesundheitsheft und Ausweis Ihres Haustiers mit sich; allgemeine Notrufnummer 112.`, `Die Währung ist der georgische Lari (GEL); Hunde sind auf Café- und Restaurantterrassen gewöhnlich unkompliziert willkommen, doch bestätigen Sie dies für Innenräume an der Tür, da dies stärker variiert.`],
    sights: {
      "Abanotubani": `Das historische Schwefelbadviertel, erkennbar an seinen Ziegelkuppeln und dem Schwefelgeruch, die legendäre Wiege der Stadt am Fuß der Festung. Sie können die Gassen und den Weg zum Wasserfall Leghwtakhewi frei mit angeleintem Hund erkunden; die Bäder selbst, in Innenräumen, sind für Haustiere nicht zugänglich.`,
      "Narikala Fortress": `Eine Festung aus dem 4. Jahrhundert, die die Altstadt krönt, zu Fuß oder per Seilbahn vom Rike-Park aus erreichbar, deren Wallanlagen ganz Tiflis und das Tal überblicken. Die offenen Wallanlagen sind mit angeleintem Hund begehbar; die Seilbahnkabine lässt üblicherweise kleine, getragene Hunde zu, fragen Sie aber vor dem Einsteigen beim Personal nach.`,
      "Kartlis Deda (Mother of Georgia)": `Eine monumentale Aluminiumstatue auf dem Sololaki-Grat, eine Weinschale in der einen Hand für Freunde, ein Schwert in der anderen für Feinde, ein Sinnbild des georgischen Geistes. Der Aussichtspunkt und der zu ihm führende Kammweg werden mit angeleintem Hund erkundet; das Panorama über die Stadt und den Mtkwari ist bei Sonnenuntergang herrlich.`,
      "Rike Park & Peace Bridge": `Ein moderner Uferpark, der über die nachts beleuchtete Glas-Stahl-Fußgängerbrücke Friedensbrücke mit der Altstadt verbunden ist. Rasenflächen, Springbrunnen und Wege eignen sich für angenehme Spaziergänge mit angeleintem Hund, und hier befindet sich die Abfahrtsstation der Seilbahn zur Narikala-Festung; führen Sie Wasser mit, da im Sommer wenig Schatten vorhanden ist.`,
      "Mtatsminda Park": `Ein Vergnügungspark und Aussichtspunkt auf dem heiligen Mtatsminda-Hügel, erreichbar mit einer historischen Standseilbahn, der den höchsten Blick über Tiflis bietet. Die offenen Wege und Gärten heißen angeleinte Hunde willkommen; die Standseilbahn lässt üblicherweise kleine, getragene Hunde zu, wobei die Fahrgeschäfte selbst für sie tabu sind.`,
      "Vake Park": `Ein großer, grüner Park im Wohnviertel Vake, eine der grünen Lungen der Stadt, mit einem monumentalen Brunnen, schattigen Alleen und bewaldeten Hängen, die zum Turtle Lake hinaufführen. Er ist der ideale Ort für einen langen Spaziergang mit angeleintem Hund abseits des Verkehrs, sehr beliebt bei Einheimischen und ihren Haustieren.`,
    },
  },
  tenby: {
    history: `Tenby, walisisch Dinbych-y-pysgod („die kleine Festung der Fische“), ist eine mittelalterliche ummauerte Hafenstadt an der südlichen Küste von Pembrokeshire. Ihre Mauern aus dem 13. Jahrhundert, das Torhaus Five Arches und ein pastellfarbener Hafen aus georgianischen Häusern machen sie zu einer der besterhaltenen ummauerten Städte in Wales, einst wohlhabend durch Fischerei und dann, in viktorianischer Zeit, als per Eisenbahn erreichbarer Seebadeort. Die Stadt schmiegt sich um drei Strände, North Beach, Castle Beach und den langen South Beach, mit Blick auf die klösterliche Insel Caldey Island. Für einen Hund ist Tenby eine bequeme Basis: Hunde reisen kostenlos mit dem Zug auf der West-Wales-Linie, kostenlos mit den Booten nach Caldey Island und sind in den Hafenpubs und auf dem Pembrokeshire Coast Path ganzjährig willkommen. Einzig zu beachten sind die saisonalen Strand-Hunderegeln, die der Pembrokeshire County Council vom 1. Mai bis 30. September festlegt. Und seit dem Brexit verlangt Großbritannien statt des EU-Heimtierausweises ein britisches Tiergesundheitszeugnis (GB Animal Health Certificate).`,
    petTips: [`Strände unterliegen vom 1. Mai bis 30. September saisonalen Beschränkungen: Am North Beach gilt ein vollständiges Verbot, am Castle Beach und am Stadtende des South Beach ein Teilverbot. Das Penally-Ende des South Beach bleibt ganzjährig geöffnet.`, `Verstöße können ein Bußgeld (berichtet mit 75 Pfund) und bis zu 500 Pfund für Verstöße gegen die Ortssatzung nach sich ziehen; die Kommune hat zunächst Verwarnungen erprobt. Lesen Sie bei Ankunft stets die Schilder.`, `Hunde reisen kostenlos mit dem Zug (bis zu zwei pro Fahrgast, an der Leine) und mit den Booten nach Caldey Island; die ummauerte Altstadt ist Fußgängerzone und steil.`, `Auf dem Pembrokeshire Coast Path halten Sie Ihren Hund an der Leine, nahe an ungesicherten Klippenkanten und weidendem Vieh.`, `Tierarzt tagsüber: Tenby Vets, Lower Park Road (+44 1834 842278); weitere Abdeckung und außerhalb der Öffnungszeiten über Fenton Vets in Pembroke Dock (+44 1437 762806).`],
    practicalInfo: [`Einreise nach dem Brexit in Großbritannien: Großbritannien akzeptiert den EU-Heimtierausweis nicht; Hunde benötigen ein britisches Tiergesundheitszeugnis (innerhalb von 10 Tagen ausgestellt), einen Mikrochip, eine Tollwutimpfung und eine Bandwurmbehandlung 24 bis 120 Stunden vor der Ankunft.`, `Anreise: Zug auf der West-Wales-Linie über Whitland und Carmarthen zum Bahnhof Tenby (Hunde kostenlos). Nächstgelegener Flughafen ist Cardiff (CWL), etwa 2 Stunden mit dem Auto.`, `Fortbewegung: Die ummauerte Altstadt ist größtenteils Fußgängerzone; parken Sie das Auto an den Parkplätzen am Stadtrand und gehen Sie hinein. Im Juli und August sehr belebt.`, `Wetter: mildes ozeanisches Klima, feuchter und kühler als die englische Südküste; milde Winter (8 °C), warme, aber nicht heiße Sommer (18 °C). Frühling und Herbst sind ideal, außerhalb der Strandverbote.`, `Nützliche Nummern: allgemeiner Notruf 999 oder 112; Tierarzt tagsüber Tenby Vets +44 1834 842278; Fenton Vets Pembroke Dock +44 1437 762806.`],
    sights: {
      "South Beach (Penally end)": `Der lange, hellsandige Strand, der Richtung Penally verläuft, mit Blick auf Caldey Island. Das Penally-Ende unterliegt keinem saisonalen Verbot und bleibt für Hunde ganzjährig geöffnet.`,
      "Castle Beach": `Eine geschützte Bucht unterhalb des Castle Hill mit Blick auf St Catherine's Island, einst zu Großbritanniens bestem Strand gewählt. Teilverbot vom 1. Mai bis 30. September; außerhalb der Saison und in erlaubten Bereichen für Hunde geöffnet.`,
      "North Beach": `Der postkartenreife Strand unterhalb der bunten Hafenhäuser, mit dem Goscar Rock. Vollständiges Hundeverbot vom 1. Mai bis 30. September; vom 1. Oktober bis 30. April für Hunde geöffnet.`,
      "Pembrokeshire Coast Path": `Der Küstenweg verlässt Tenby in beide Richtungen, Richtung Penally und Saundersfoot, entlang von Klippen und Stränden. Ganzjährig für Hunde geöffnet; nahe Klippenkanten und Vieh gilt Leinenpflicht.`,
      "Caldey Island Boat Trips": `Kleine Boote vom Hafen zur klösterlichen Insel Caldey Island, mit einer Abtei, Stränden und einem Leuchtturm. Hunde willkommen und kostenlos, an Bord und auf der Insel stets an der Leine.`,
      "Tenby Town Walls": `Die mittelalterlichen Mauern aus dem 13. Jahrhundert, das Torhaus Five Arches und das Gassengewirr der Altstadt. Alles im Freien, hundefreundliches Erkunden an der Leine, ganzjährig.`,
    },
  },
  tenerife: {
    history: `Teneriffa, die größte der Kanarischen Inseln, ist ein spanischer Archipel vor der Küste Marokkos, dessen subtropisches Klima sie zu einem der führenden europäischen Winterziele macht: 22 bis 26 °C im Süden selbst im Januar. Die Insel wird vom Teide (3.715 m) beherrscht, dem höchsten Punkt Spaniens und dem Vulkan im Herzen eines UNESCO-gelisteten Nationalparks. Im Norden ist auch die frühere Hauptstadt La Laguna UNESCO-gelistet, während der ländliche Park Anaga einen relikten Lorbeerwald schützt. Bei Hunden gibt es, da die Kanarischen Inseln zu Spanien und der EU gehören, keine Quarantäne: Ein EU-Heimtierausweis, ISO-Mikrochip und aktuelle Tollwutimpfung genügen. Der touristische Süden, von Costa Adeje über Los Cristianos bis Playa de las Américas, konzentriert hundefreundliche Hotels, Uferpromenaden und englischsprachige Kliniken, und die Kitesurf-Stadt El Médano verfügt über den Hundestrand Playa del Cabezo. Ein echtes 24-Stunden-Tierkrankenhaus in Santa Cruz rundet das Angebot ab.`,
    petTips: [`Kanarische Inseln = Spanien + EU: keine Quarantäne. Ein EU-Heimtierausweis, ISO-Mikrochip und aktuelle Tollwutimpfung genügen für EU-Haustiere.`, `Referenz-Hundestrand: Playa del Cabezo in El Médano, ganzjährig für angeleinte Hunde geöffnet; prüfen Sie stets die Beschilderung des Ayuntamiento, da der Hundezugang je nach Gemeinde variiert.`, `24-Stunden-Tierkrankenhaus: Medivet 24 horas San Antonio (Santa Cruz) +34 922 28 46 11; im Süden Animal Center Sur (El Médano) +34 922 176 081, 24-Std.-Bereitschaftsleitung +34 607 346 183; englischsprachige Klinik VetSur Armeñime in Costa Adeje +34 922 125 590.`, `Hitze: Von Juni bis September verbrennen dunkler vulkanischer Sand und Asphalt Pfotenballen von Mittag bis zum späten Nachmittag. Gehen Sie bei Sonnenaufgang oder nach Sonnenuntergang spazieren und führen Sie überall Wasser mit.`, `Rassen, die gesetzlich als potenziell gefährlich (PPP) eingestuft sind: Maulkorb und kurze Leine sind nach spanischem und kanarischem Recht in der Öffentlichkeit vorgeschrieben.`],
    practicalInfo: [`Anreise: Flughafen Teneriffa Süd (TFS), das Winter-Charter-Drehkreuz, 15-30 Min. von Costa Adeje, Los Cristianos und El Médano entfernt; Teneriffa Nord (TFN) für Inter-Insel- und Festlandflüge.`, `Dokumente: EU-Heimtierausweis + ISO-Mikrochip + mindestens 21 Tage alte Tollwutimpfung für EU-Besucher, keine Quarantäne; für Nicht-EU-Besucher (Großbritannien eingeschlossen, post-Brexit) ein innerhalb von 10 Tagen ausgestelltes Tiergesundheitszeugnis (AHC).`, `Örtlicher Nahverkehr: TITSA-Busse und die Straßenbahn Santa Cruz-La Laguna nehmen kleine Hunde in Transportboxen mit; die Fähren von Fred Olsen und Armas nach La Gomera, La Palma, El Hierro und Gran Canaria erlauben Haustiere. Für Teide und den Norden ist ein Mietwagen empfehlenswert.`, `Haustierbetreuung: Rover und Gudog decken den Süden ab (Costa Adeje, Los Cristianos, Arona); buchen Sie 2-3 Wochen im Voraus in der Winterhauptsaison (Dezember-März) und an Ostern.`, `Klima: mildes ganzjähriges Sonnenklima 22-26 °C im Süden; heißer und schattenloser Süden im Sommer, kühlerer, grüner Norden. Beste Monate mit Hund: November bis April.`],
    sights: {
      "Parque Nacional del Teide": `Spaniens meistbesuchter Nationalpark, rund um den Vulkan Teide (3.715 m). Die Gipfelseilbahn und strenge Schutzzonen sind für Hunde gesperrt, doch viele niedriger gelegene Pfade und Aussichtspunkte auf dem Plateau Las Cañadas sind an der Leine zugänglich. Bereiten Sie sich auf Kälte in großer Höhe und scharfes Vulkangestein vor.`,
      "Playa del Cabezo (El Médano)": `Teneriffas Referenz-Hundestrand, ein goldener Sandabschnitt in El Médano unterhalb des Montaña Roja, bei Kitesurfern wegen des zuverlässigen Winds beliebt. Angeleinte Hunde ganzjährig willkommen; prüfen Sie vor Ort die Beschilderung des Ayuntamiento.`,
      "Parque Rural de Anaga": `Ein UNESCO-Biosphärenreservat mit uraltem Lorbeerwald im Nordosten, mit tiefen Schluchten, Kammwegen und Weilern. Viele markierte Pfade heißen angeleinte Hunde willkommen und bieten kühle, schattige Spaziergänge, ideal an heißen Tagen.`,
      "La Laguna (San Cristóbal de La Laguna)": `Die UNESCO-gelistete frühere Hauptstadt, ein Raster aus farbenfrohen Kolonialstraßen und Plätzen. Die gesamte Altstadt ist ein Leinenspaziergang mit Cafés und Terrassen, in einem selbst bei starker Hitze angenehmen kühlen Nordklima. Museen im Innenbereich bleiben für Hunde gesperrt.`,
      "Garachico": `Eine historische Nordküstenstadt, nach dem Ausbruch von 1706 wiederaufgebaut, berühmt für ihre natürlichen Vulkangesteinsbecken (El Caletón) und Kopfsteingassen. Uferpromenade und Gassen bieten einen Leinenspaziergang in ruhiger Umgebung abseits des Ferien-Südens.`,
      "Paseo Marítimo de Costa Adeje": `Die lange, gestaltete Promenade, die die Strände von Costa Adeje (Fañabé, Torviscas, El Duque) verbindet, mit Cafés, Palmen und Meerblick auf der gesamten Strecke. Der schönste Leinenspaziergang im Süden; die Hotelstrände selbst schränken Hunde ein.`,
    },
  },
  'the-hague': {
    history: `Den Haag ist nicht die offizielle Hauptstadt der Niederlande, vereint jedoch deren Funktion: Sitz der Regierung, des Parlaments, der Botschaften und seit 1913 des Internationalen Gerichtshofs. Im 13. Jahrhundert um einen gräflichen Jagdsitz am Hofvijver-Teich gegründet, ist die Stadt bis heute königliche Residenz, mit einer luftigen, baumgesäumten Stadtplanung, die sie von Amsterdam oder Rotterdam abhebt. Von ihren 560.000 Einwohnern sind bei der Gemeinde über 50.000 Hunde registriert, und die örtliche Kultur räumt ihnen großzügig Platz ein: 11 km Küste bei Scheveningen und Kijkduin, leinenfreie Natura-2000-Dünen, zentrale Wälder wie den Haagse Bos, und eine Verkehrspolitik, die kleine Hunde kostenlos in einer Transporttasche mitfahren lässt. Den Haag ist eine der bestausgestatteten europäischen Hauptstädte, um mit Hund zu leben und zu reisen.`,
    petTips: [`Saisonales Strandverbot in Scheveningen (15. Mai-1. Okt.): Weichen Sie auf Kijkduin südlich von strandslag 2 oder Noorderstrand nördlich von Pfahl 34 aus, beide ganzjährig leinenfrei.`, `Am zentralen Strand von Scheveningen dürfen Hunde im Sommer nur zwischen 21:00 und 07:00 Uhr ohne Leine laufen, ein kleines, aber lebhaftes lokales gesellschaftliches Ritual.`, `HTM (Straßenbahnen und Busse): kleine Hunde in einer Transporttasche reisen kostenlos, große Hunde an der Leine werden ohne Aufpreis akzeptiert, sofern sie im Gang sitzen.`, `24/7-Tierärztlicher Notdienst: AniCura Haaglanden Rijswijk, Frijdastraat 20a (+31 85 483 13 00), 10 Autominuten vom Zentrum entfernt.`, `Der japanische Garten von Clingendael verbietet Hunde (nur Assistenzhunde erlaubt); das übrige Anwesen ist an der Leine vollständig zugänglich.`],
    practicalInfo: [`Der Hauptflughafen für Den Haag ist Amsterdam Schiphol (AMS), 45 Minuten mit dem Direktzug; Rotterdam-Den Haag (RTM) liegt näher, bedient aber weniger Ziele.`, `In NS-Zügen benötigen große Hunde ein Dog Day Ticket für etwa 3,50 €, ganztägig im gesamten inländischen Netz gültig. Kleine Hunde in einer Tasche reisen kostenlos.`, `24/7-Notdienstleitung für die Region: 0900-2226333, die zur diensthabenden Klinik weiterleitet (in der Praxis AniCura Rijswijk).`, `Ozeanisches Klima: milde Sommer (19 °C im Juli), grauer und windiger Winter; der Nordseewind macht von Oktober bis März einen Mantel für kleine Hunde sinnvoll.`, `Pawshake.nl ist die gängige Plattform für Tierbetreuung; kalkulieren Sie 15-20 € pro Kurzbesuch, 30 € für Ganztagesbetreuung, 35 € pro Nacht.`],
    sights: {
      "Hofvijver & Binnenhof": `Ein Teich aus dem 13. Jahrhundert, umgeben vom Parlamentskomplex, frei zugänglich für angeleinte Hunde rund um die Innenhöfe und den Uferweg. Das Innere des Binnenhofs ist bis 2028 wegen Renovierung geschlossen, doch die Runde außen bleibt einer der fotogensten Spaziergänge des Landes.`,
      "Westduinpark & Bosjes van Poot": `Ein 240 Hektar großes Natura-2000-Dünenreservat zwischen Kijkduin und Scheveningen, mit ausgedehnten leinenfreien Abschnitten, Meerblick und direktem Strandzugang. Eine der größten städtischen Naturflächen der Niederlande.`,
      "Scheveningen Pier & Boulevard": `Ein langer, ebener Boulevard mit Blick auf die Nordsee und den ikonischen De Pier. Angeleinte Hunde gehen die gesamte Promenade und den größten Teil des Piers selbst entlang, auch außerhalb der Saison, wenn der darunterliegende Strand leinenfrei wird.`,
      "Haagse Bos": `Ein jahrhundertealter Laubwald von über 100 Hektar, der sich vom Malieveld bis zum Park Marlot erstreckt und von Staatsbosbeheer verwaltet wird. Mehrere markierte leinenfreie Zonen entlang des Hauptwegs; der Eingang am Malieveld liegt zehn Gehminuten vom Binnenhof entfernt.`,
      "Lange Voorhout": `Eine L-förmige Kastanienallee, gesäumt von Botschaften und Museen, die jeden Sommer eine kostenlose Freiluft-Skulpturenausstellung beherbergt. Angeleinte Hunde nehmen ohne Ticket am kulturellen Rahmen teil.`,
      "Landgoed Clingendael": `Ein 100 Hektar großes Landgut aus dem 17. Jahrhundert in Benoordenhout, mit formalen Gärten, Teichen und einem funktionierenden Bauernhof. Angeleinte Hunde sind überall zugelassen außer im japanischen Garten, der nur sechs Wochen im Jahr geöffnet ist.`,
    },
  },
  texel: {
    history: `Texel ist die größte der westfriesischen Inseln, eine Sandbank vor der Nordspitze der Niederlande, im Osten begrenzt vom Wattenmeer, einem UNESCO-Weltnaturerbe. Sie ist in etwa zwanzig Minuten mit der TESO-Fähre ab Den Helder erreichbar und legt in 't Horntje an; Hunde reisen kostenlos, müssen an Deck aber angeleint bleiben. Die Insel lebt von Schafzucht, Fischerei und Küstentourismus, und sieben Dörfer, darunter der Hauptort Den Burg und der Hafen Oudeschild, prägen eine Landschaft aus Deichen, Poldern und Dünen. Dreißig Kilometer Sandstrand liegen der Nordsee zugewandt, während der Nationalpark Dünen von Texel Heide und Wald schützt. Für Hundehalter ist Texel ein Paradies: lange, ganzjährig für Hunde erlaubte Strände, überall Radwege und eine tief verwurzelte tierfreundliche Kultur.`,
    petTips: [`Texel ist eine der hundefreundlichsten Inseln der Niederlande: breite Strände erlauben Hunde das ganze Jahr über, doch vom 1. Mai bis 15. September werden manche Abschnitte reguliert oder erfordern eine Leine, achten Sie also auf die Schilder und die nummerierten Pfähle (paal), die die Zonen markieren.`, `Auf der TESO-Fähre ab Den Helder reisen Hunde kostenlos, müssen an Deck aber angeleint bleiben; kaufen Sie ein Rückfahrticket, da nur bei der Ausfahrt von der Insel bezahlt wird.`, `Die Insel lebt vom Radfahren: Viele Verleihe bieten Hundekörbe und Anhänger an, eine praktische und gut akzeptierte Art, sich auf den ebenen Radwegen fortzubewegen.`, `Halten Sie Ihren Hund im Nationalpark der Dünen im Frühjahr streng angeleint, um bodenbrütende Vögel zu schützen, und achten Sie in den Dünen und im hohen Gras auf Zecken (Borreliose-Risiko).`, `Die Nordsee ist kalt und der Wind oft stark: Spülen Sie Sand und Salz nach dem Schwimmen aus dem Fell, führen Sie frisches Wasser und ein Handtuch mit und achten Sie beim Schwimmen Ihres Hundes auf die Strömung.`],
    practicalInfo: [`Die Niederlande gehören zur EU: Ein EU-Heimtierausweis, ein ISO-Mikrochip und eine aktuelle Tollwutimpfung genügen, ohne Quarantäne oder besondere Formalitäten bei der Ankunft.`, `Der Zugang erfolgt nur über die TESO-Fähre zwischen Den Helder und 't Horntje, etwa 20 Minuten, im Sommer sehr häufig; Hunde reisen kostenlos, angeleint.`, `Das Klima ist maritim und windig: milde Sommer (oft 18 bis 22 °C), ideal für die langen Strände, kühle, feuchte Winter; außerhalb der Saison genießen Hunde die größte Freiheit im Sand.`, `Eine Tierarztpraxis in Den Burg deckt die Grundversorgung und Notfälle auf der Insel ab; für einen allgemeinen Notfall gilt die einheitliche europäische Nummer 112.`, `Die Währung ist der Euro; Unterkünfte, Terrassencafés und viele Restaurants heißen Hunde willkommen, bestätigen Sie dies aber bei der Buchung, besonders in der Sommerhauptsaison.`],
    sights: {
      "Noordzeestrand": `Der lange Nordseestrand entlang der gesamten Westküste der Insel, markiert durch nummerierte Pfähle (paal), die als Treffpunkte dienen. Breite Abschnitte erlauben Hunden außerhalb der Saison Freilauf; im Sommer, vom 1. Mai bis 15. September, werden manche Abschnitte reguliert, doch mehrere Strände bleiben ganzjährig für Hunde geöffnet.`,
      "Nationaal Park Duinen van Texel": `Der Nationalpark Dünen von Texel schützt einen an Nistvögeln reichen Gürtel aus Dünen, Heide und Wald entlang der Westküste. Hunde sind auf den markierten Wegen an der Leine zugelassen; im Frühjahr ist die Leine unerlässlich zum Schutz bodenbrütender Vögel, und manche strengen Schutzzonen sind gesperrt.`,
      "Den Burg": `Der Hauptort der Insel mit Marktplatz, Einkaufsgassen und gotischer Kirche, das lebendige Herz Texels, wo im Sommer der Montagsmarkt stattfindet. Hier lässt es sich leicht mit angeleintem Hund flanieren, und viele Terrassencafés heißen Haustiere gern mit einer Schale Wasser willkommen.`,
      "Oudeschild": `Der Fischereihafen der Insel, gesäumt von Kuttern und Loggern, mit Fischauktion, dem Meeresmuseum Kaap Skil und einer restaurierten Windmühle mit Blick auf das Wattenmeer. Sie können mit angeleintem Hund entlang der Kais schlendern, und hier starten auch Ausflüge zur Robbenbeobachtung und zum Krabbenfang.`,
      "Ecomare": `Das Natur- und Rettungszentrum für Robben und Schweinswale in De Koog präsentiert die Tierwelt von Wattenmeer und Nordsee. Es handelt sich um einen Innenbesuch mit Becken und Tierheim: Hunde sind nicht zugelassen, planen Sie also, Ihren Begleiter in der Unterkunft zu lassen oder sich abzuwechseln.`,
      "Vuurtoren Eierland": `Der rote Leuchtturm von De Cocksdorp an der Nordspitze der Insel, ein ikonischer Wächter zwischen Dünen und Nordsee. Die Umgebung, der nahe Strand und die Dünenpfade lassen sich alle mit angeleintem Hund begehen; der Aufstieg auf den Turm im Innenbereich ist für Haustiere nicht zugänglich.`,
    },
  },
  thessaloniki: {
    history: `Thessaloniki ist Griechenlands zweitgrößte Stadt und eine der ältesten durchgehend bewohnten Städte Europas, 315 v. Chr. vom mazedonischen König Kassander gegründet, der sie nach seiner Frau, einer Halbschwester Alexanders des Großen, benannte. Als kosmopolitische Balkan-Kreuzung war sie nacheinander römische Hauptstadt, byzantinische Metropole, osmanische Stadt und Heimat einer blühenden sephardisch-jüdischen Gemeinde. Heute ist sie die kulturelle Hauptstadt Nordgriechenlands, reich an Denkmälern der Antike, von Byzanz und der Osmanenzeit, die alle in einem lebendigen städtischen Gefüge nebeneinander bestehen. Ihre Kultur ist zutiefst mediterran: gutes Essen, lange Abende und Hunde, die auf Terrassen in der ganzen Stadt wirklich willkommen sind. Die Nea Paralia, eine 2013 neu gestaltete, 3,5 km lange Promenade mit eigener Hundezone, verkörpert die natürliche Beziehung der Stadt zu ihren vierbeinigen Bewohnern.`,
    petTips: [`Für die Einreise nach Griechenland sind ein gültiger EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich, prüfen Sie die Ablaufdaten vor der Reise.`, `Leinenpflicht auf allen öffentlichen Straßen und in Parks; nur offiziell ausgewiesene leinenfreie Bereiche sind ausgenommen.`, `Organisierte Strände (mit Liegen und Rettungsschwimmern) sind für Hunde tabu; unorganisierte Strände in Peraia und Agia Triada erlauben Hunde ganzjährig.`, `Extreme Hitze im Juli-August (32 °C): Gehen Sie vor 8 Uhr oder nach 20 Uhr spazieren und führen Sie stets Wasser mit.`, `Thessaloniki hat eine Streunerpopulation, die meisten sind von der Kommune geimpft und mit Ohrmarke versehen; halten Sie Ihren Hund angeleint, wenn Streuner in der Nähe sind.`],
    practicalInfo: [`Tierärztlicher Notdienst werktags abends (14:00–9:00 Uhr) und 24 Std. am Wochenende: Tierärztliches Lehrkrankenhaus der AUTh, +30 2310 994403.`, `Stadttierarzt (sonntags geöffnet): City Paws, Proksenoy Koromila 20, 2316 019719.`, `OASTH-Bus: kleiner Hund in Transportbox nach Ermessen des Fahrers akzeptiert; großer Hund mit Maulkorb und Leine erforderlich.`, `Nächstgelegener hundefreundlicher Strand: Peraia (25 Min. Autofahrt südlich von Thessaloniki), unorganisierte Abschnitte ganzjährig hundefreundlich.`, `Flughafen Thessaloniki (SKG) 15 km östlich; Taxi ins Zentrum etwa 15–20 €, 15–25 Min.`],
    sights: {
      "White Tower": `Das Wahrzeichen Thessalonikis, ein osmanischer Turm aus dem 16. Jahrhundert an der Uferpromenade. Die Außenanlagen und die Promenade sind hundefreundlich; das Museum im Inneren nicht. Perfekt für einen Spaziergang bei Sonnenuntergang.`,
      "Nea Paralia": `Der 3,5 km lange Uferpark mit eigener Hundezone, Thessalonikis geselligste Abendpromenade. Durchweg hundefreundliche Cafés.`,
      "Ano Poli": `Die osmanische Oberstadt, ein Gassengewirr mit Kopfsteinpflaster, byzantinischen Mauern und Nachbarschaftstavernen, ideal für einen ruhigen Hundespaziergang abseits des Stadtrummels.`,
      "Arch of Galerius": `Der römische Bogen aus dem 4. Jahrhundert im Stadtzentrum, umgeben von einer abends lebhaften Fußgängerpiazza. Umliegende Café-Terrassen heißen Hunde durchweg willkommen.`,
      "Seich Sou Forest": `Der 3.300 Hektar große Stadtwald im Nordosten, die beste Flucht für Hunde vor Thessalonikis Hitze, mit markierten Pfaden und kühlerem Mikroklima.`,
      "Ladadika": `Das ehemalige Olivenöl-Lagerviertel, heute ein stimmungsvolles Nachtlebenviertel mit hundefreundlichen Ouzerien und Restaurants in autofreien Kopfsteingassen.`,
    },
  },
  tirano: {
    history: `Tirano im oberen Veltlin in der Lombardei bewacht die Alpengrenze zur Schweiz an der Mündung der Täler, die zum Berninapass hinaufführen. Die kleine Stadt ist vor allem als italienischer Endpunkt des Bernina Express bekannt, der UNESCO-gelisteten Rhätischen Bahn, die sie mit St. Moritz verbindet und dabei spektakuläre Viadukte und Gletscher ohne Zahnradantrieb überquert. Ihr historisches Zentrum gruppiert sich um die Basilika der Madonna di Tirano, ein großes Renaissance-Wallfahrtsheiligtum, und alte Paläste wie den Palazzo Salis. Ringsum tragen terrassierte Hänge die Weinberge des Veltlins, Heimat des Sforzato-Weins, während Apfelplantagen den Talboden säumen. Als Tor zu den Rätischen Alpen und dem nahen Schweizer Tal Poschiavo wird Tirano an der Leine erkundet, zwischen Gassen, Bahnsteigen und Bergpfaden.`,
    petTips: [`Italienisches Recht: Hunde an der Leine an öffentlichen Orten, ein Maulkorb ist auf Verlangen in Verkehrsmitteln und an belebten Orten mitzuführen, halten Sie Ausweis und Mikrochip aktuell.`, `Bernina Express: Angeleinte Hunde reisen mit Ticket mit, buchen Sie also im Sommer früh und wählen Sie einen ruhigen Platz, da die Fahrt nach St. Moritz mehrere Stunden dauert.`, `Grenzübertritt in die Schweiz: Poschiavo liegt außerhalb der EU, führen Sie also den europäischen Ausweis des Haustiers für die Grenze mit und prüfen Sie die aktuellen Schweizer Vorschriften.`, `Bergklima: Sommer bleiben für einen Hund kühl und angenehm, doch Winter sind schneereich und kalt, bringen Sie also etwas mit, um die Pfotenballen vor Streusalz zu schützen.`, `Basilika und Kirchen: Die Innenräume von Gotteshäusern lassen keine Hunde zu, planen Sie also, sich abzuwechseln oder auf den Außenplätzen und Vorplätzen zu bleiben.`],
    practicalInfo: [`Notfälle: 112 ist Italiens einheitliche Notrufnummer; Tirano und das Tal verfügen über Tierarztpraxen, fragen Sie Ihr Hotel nach dem nächsten Bereitschaftsdienst.`, `Zug: Der Bahnhof Tirano verbindet das italienische Netz (Trenord nach Sondrio und Mailand) mit der Schweizer Rhätischen Bahn; kleine Hunde in einer Transportbox und große Hunde an der Leine mit Maulkorb gemäß den Regeln jedes Betreibers.`, `Schweizer Grenze: Das Tal Poschiavo liegt wenige Kilometer entfernt, außerhalb der EU, führen Sie also den Ausweis des Haustiers für eine Rundreise mit.`, `Saison: kühle, für einen Hund angenehme Sommer, schneereiche Winter, prüfen Sie also den Zugang zu Höhenpfaden und rüsten Sie sich je nach Jahreszeit aus.`, `Weinberge und Obstgärten: Respektieren Sie die terrassierten Kulturen und privaten Obstgärten, bleiben Sie auf markierten Wegen und sammeln Sie stets den Kot Ihres Hundes auf.`],
    sights: {
      "Bernina Express": `Tirano ist der italienische Endpunkt dieses berühmten Panoramazugs der Rhätischen Bahn, der über spiralförmige Viadukte und Gletscherpässe nach St. Moritz hinaufsteigt. Angeleinte Hunde sind mit Ticket an Bord zugelassen, bringen Sie also Wasser und einen ruhigen Platz mit, da die Fahrt mehrere Stunden dauert.`,
      "Basilica della Madonna di Tirano": `Dieses große Renaissance-Wallfahrtsheiligtum, im 16. Jahrhundert am Ort einer Marienerscheinung errichtet, birgt ein reich verziertes Inneres und eine monumentale Orgel. Hunde sind im Inneren der Basilika nicht zugelassen, doch der weite Vorplatz und die davor liegenden Gärten können an der Leine begangen werden.`,
      "Centro storico e Palazzo Salis": `Tiranos Altstadt reiht Kopfsteingassen, historische Häuser und den Palazzo Salis aneinander, ein aristokratisches Herrenhaus mit barocken Salons und ummauertem Garten. Sie schlendern an der Leine durch Straßen und Plätze, während der Zugang zu den historischen Räumen des Palasts Besuchern ohne Hund vorbehalten bleibt.`,
      "Vigneti della Valtellina": `Die Hänge oberhalb von Tirano sind mit terrassierten, von Trockenmauern gehaltenen Weinreben bedeckt, Heimat des Sforzato und der Rotweine des Veltlins. Weinbergpfade lassen sich an der Leine zwischen den Reihen begehen und bieten in den kühleren Stunden schöne Ausblicke über das Tal.`,
      "Valle di Poschiavo": `Gleich jenseits der Schweizer Grenze setzt das Tal Poschiavo die alpine Landschaft mit seinen Seen und Dörfern fort, erreichbar mit Zug oder Auto von Tirano aus. Pfade und Seeufer lassen sich an der Leine begehen, denken Sie an den Heimtierausweis für den Grenzübertritt.`,
      "Alpi Retiche": `Rund um Tirano bieten die Rätischen Alpen zahlreiche Wanderrouten durch Bergweiden, Wälder und die Apfelplantagen des Talbodens. Die Pfade werden an der Leine begangen, und die Höhenkühle im Sommer bekommt Hunden gut, solange Sie Wasser mitführen.`,
    },
  },
  tokyo: {
    history: `Tokyo begann als Edo, eine bescheidene Burgstadt, die zur Hauptstadt des Shoguns aufstieg, nachdem Tokugawa Ieyasu 1603 dort seine Regierung errichtete. Als der Meiji-Kaiser 1868 Kyoto verließ, wurde die Stadt in Tokyo, „östliche Hauptstadt“, umbenannt, und sie ist zweimal aus fast vollständiger Zerstörung wiederauferstanden: dem großen Kanto-Erdbeben von 1923 und den Brandbombardierungen von 1945. Heute ist sie der Anker des weltweit größten Ballungsraums, ein Mosaik unterschiedlicher Stadtbezirke, in dem das Neonlicht von Shibuya und Shinjuku auf die Tempel von Asakusa und ruhige Wohngassen trifft. Für Hundehalter ist Tokyo lohnend, aber anspruchsvoll: Die Regeln sind strenger und wörtlicher als in Europa. Hunde fahren in JR- und U-Bahn-Zügen nur in einer geschlossenen Transportbox, öffentliche Parks verlangen Leinen, und Freilauf ist auf registrierte Hundeauslaufplätze beschränkt, und Restaurants im Innenbereich lassen selten Haustiere zu. Dem stehen hervorragende Hundeauslaufplätze, Uferparks an der Bucht von Tokyo und rund um die Uhr geöffnete englischsprachige Tierärzte gegenüber.`,
    petTips: [`Führen Sie die Original-Tollwutimpfbescheinigung Ihres Hundes stets mit: Sie ist zur Registrierung an Tokyos öffentlichen Hundeauslaufplätzen erforderlich, eine Kopie oder ein Foto wird meist abgelehnt.`, `Nur kleine Hunde dürfen JR und die U-Bahn nutzen, vollständig in einer geschlossenen Transportbox innerhalb der Grenzen des Betreibers; mittelgroße und große Hunde müssen ein gebuchtes Tiertaxi nehmen.`, `Sommer in Tokyo sind heiß und sehr feucht: Gehen Sie bei Sonnenaufgang oder nach Einbruch der Dunkelheit spazieren, prüfen Sie den Gehweg mit der Hand und führen Sie überall Wasser mit.`, `24-Stunden-Notfalltierärzte: Japan Animal Medical Center in Shibuya (03-3378-3366) und Daktari Animal Hospital in Minato (03-5420-0012), beide können bei vorherigem Anruf Englischsprachigen helfen.`, `Restaurants lassen Hunde selten im Innenbereich zu: Zielen Sie auf Terrassen und die hundefreundlichen Lokale von Hiroo, Azabu-Juban, Daikanyama und Jiyugaoka, und rufen Sie immer vorher an.`],
    practicalInfo: [`Japan gehört weder zur EU noch zum Schengen-Raum: Die Einfuhr eines Hundes erfordert einen ISO-Mikrochip, zwei Tollwutimpfungen, einen Antikörper-Serologietest mit anschließender Wartezeit sowie eine vorab erfolgte Quarantäneanmeldung, alles Monate im Voraus zu organisieren.`, `Flughäfen: Haneda (HND) liegt am nächsten zum Zentrum, Narita (NRT) weiter außerhalb; prüfen Sie die Tiertransportregeln Ihrer Fluggesellschaft rechtzeitig vor der Abreise.`, `Währung: der japanische Yen. Das tägliche haustierfreundliche Budget fällt hoch aus, da Tokyo eine der teureren Hauptstädte ist, kalkulieren Sie also einen Spielraum für Tiertaxis ein.`, `Beste Reisezeiten: Frühling und Herbst sind mild zum Spazierengehen; meiden Sie den heißen, feuchten Sommer, die Regenzeit von Juni bis Juli und Taifunstörungen um September.`, `Für einen großen Hund planen Sie jede Fahrt um ein gebuchtes Tiertaxi herum, da Züge ausgeschlossen sind; speichern Sie die Notfall-Tierarztnummern, bevor Sie sie brauchen.`],
    sights: {
      "Yoyogi Park Dog Run": `Großer, eingezäunter Hundeauslauf von rund 3.600 m² im Herzen des Yoyogi Park nahe Harajuku, nach Hundegröße unterteilt. Freilauf im Inneren, jedoch ist eine vorherige Registrierung im Parkbüro mit der Original-Tollwutbescheinigung erforderlich.`,
      "Komazawa Olympic Park Dog Run": `Geräumiger Hundeauslauf im Erbe-Park der Olympischen Spiele von 1964 in Setagaya, mit getrennten Zonen für Hunde bis 5 kg, 5 bis 12 kg und größere. Kostenlos für registrierte Nutzer, mit weiten Leinenspazierwegen drumherum.`,
      "Hachiko Statue, Shibuya": `Bronzestatue des treuen Akita, der jahrelang auf seinen Besitzer wartete, vor dem Bahnhof Shibuya. Offener öffentlicher Raum, angeleinte Hunde willkommen; meiden Sie das Gedränge zur Stoßzeit an der nahen Scramble-Kreuzung.`,
      "Odaiba Seaside Park": `Künstlicher Strand und lange Uferpromenade auf der Insel Odaiba, mit Blick auf die Rainbow Bridge und die Skyline. Angeleinte Hunde willkommen auf Sand und Promenade; Schwimmen in der Bucht ist nicht erlaubt.`,
      "Jonanjima Seaside Park": `Uferpark an der Bucht von Tokyo bei Haneda, mit Sandstrand, eingezäuntem Hundeauslauf und Grillbereichen. Flugzeuge fliegen tief darüber hinweg; spülen Sie danach salzige Pfoten ab, da die Bucht kein Ort zum Hundeschwimmen ist.`,
      "Asakusa & Sensoji Approach": `Das historische Viertel Asakusa und der Zugang zum Sensoji-Tempel, mit der Straße Nakamise und ihren Gassen. Angeleinte Hunde sind auf den äußeren öffentlichen Straßen erlaubt; der innere heilige Bereich des Tempels lässt keine Hunde zu.`,
    },
  },
  toledo: {
    history: `Toledo, in römischer Zeit als Toletum gegründet, war nacheinander Hauptstadt des westgotischen Königreichs (6.–8. Jahrhundert), ein maurisches Kulturzentrum (Tulaytula, 711–1085) und Hauptstadt Kastiliens, bis der Hof 1561 nach Madrid zog. Seit 1986 ist die Stadt ein UNESCO-Freilichtmuseum, in dem sich christliches (gotische Kathedrale, Alcázar), jüdisches (Synagogen Tránsito und Santa María la Blanca) und islamisches (Moschee Cristo de la Luz, Stadttor Puerta de Bisagra) Erbe begegnen. Auf einem Granitfelsen thronend, den die Tajo-Schlucht auf drei Seiten umschließt, verdankt Toledo seinen Beinamen „Kaiserstadt“ Karl V., der es im 16. Jahrhundert zu seiner Hauptstadt machte. Für Reisende mit Hund ist Toledo eines der zugänglichsten UNESCO-Ziele Spaniens: die Casco Histórico ist in 25 Min. zu Fuß erkundbar, die Tasca-Kultur duldet Hunde standardmäßig, die 7 km lange Senda Ecológica führt entlang des Tajo, der Mirador del Valle ist hundefreundlich, und eine direkte Avant-Bahnverbindung von Madrid dauert 33 Minuten.`,
    petTips: [`Die kastilische Tasca-Kultur heißt Hunde standardmäßig willkommen, etwa 75 % der Cafés Toledos lassen angeleinte Hunde ganzjährig auf der Terrasse zu.`, `Unauto-Busse + Touristenbahn (Trenecito): angeleinte Hunde kostenlos in den offenen Wagen der Bahn; mittelgroße/große Hunde brauchen in Bussen Maulkorb und halben Fahrpreis.`, `Renfe-Avant-Züge Madrid-Toledo in 33 Min.: kleine Hunde in Transportbox bis 10 kg kostenlos, größere mit Zusatzticket und Maulkorb.`, `24/7-Tierärztlicher Notdienst: Hospital Veterinario Toledo, rua Río Bullaque 11 (+34 925 22 22 33), im Stadtzentrum.`, `Die Casco Histórico ist größtenteils gepflastert und steil (bis zu 15° Gefälle), im Sommer sind Stiefel unverzichtbar (50 °C an der Oberfläche); kleine und ältere Hunde schaffen es nur mit häufigen Pausen.`],
    practicalInfo: [`Spanien gehört zur EU und zum Schengen-Raum: EU-Heimtierausweis + gültige Tollwutimpfung + ISO-Mikrochip genügen aus jedem EU-Land.`, `Direkte AVE-Renfe-Züge: Madrid 33 Min. (Avant), Sevilla 1:45 Std., Córdoba 2 Std., Barcelona 3 Std., kleine Hunde in Transportbox kostenlos, größere mit Zusatzticket und Maulkorb.`, `Flughafen Madrid-Barajas (MAD) 1:10 Std. mit Cercanías + Avant, der nächstgelegene hundefreundliche internationale Drehkreuz für Toledo.`, `Währung: Euro. Tägliches haustierfreundliches Budget: 50-75 €/Tag ohne Unterkunft, eines der niedrigsten Spaniens nach Córdoba und Granada.`, `Zu meidende Festivals mit ängstlichem Hund: Fronleichnam (Juni), Karwochenprozessionen (März-April), El-Greco-Musikfestival (Juli).`],
    sights: {
      "Mirador del Valle": `Ikonischer Aussichtspunkt gegenüber der Casco Histórico, der meistfotografierte Blickwinkel auf die Skyline Toledos. Kostenlos rund um die Uhr, hundefreundlich mit angeleinten Hunden.`,
      "Puente de San Martín": `Mittelalterliche Brücke aus dem 14. Jahrhundert mit fünf gotischen Bögen über den Tajo, Toledos fotogenste Brücke. Rund um die Uhr geöffnet, durchweg hundefreundlich.`,
      "Plaza de Zocodover": `Hauptplatz im Herzen der Casco Histórico, Treffpunkt aller mittelalterlichen Straßen, Cafés und Tabernas. Rund um die Uhr geöffnet, hundefreundlich.`,
      "Senda Ecológica del Tajo": `7 km langer Rundweg entlang des Tajo um die Casco Histórico, ikonischer Stadtblick von der anderen Seite der Schlucht. Angeleinte Hunde.`,
      "Puerta de Bisagra": `Maurisch-renaissancezeitliches Stadttor aus dem 9. Jahrhundert, der Haupteingang zur Casco Histórico von Madrid aus. Rund um die Uhr geöffnet, hundefreundlich mit angeleinten Hunden.`,
      "Judería": `Mittelalterliches jüdisches Viertel mit zwei denkmalgeschützten Synagogen (Tránsito und Santa María la Blanca), Kopfsteingassen, Blick auf die Tajo-Schlucht. Im Freien hundefreundlich; die Innenräume der Synagogen nur für Assistenzhunde.`,
    },
  },
  toronto: {
    history: `Toronto, das aus dem französischen Handelsposten Fort Rouillé und der 1793 gegründeten Kolonialstadt York hervorging, ist heute Kanadas größte Stadt und eine der multikulturellsten Metropolen der Welt, mit mehr als der Hälfte der Einwohner im Ausland geboren. Entlang des Nordufers des Ontariosees erbaut und von einem Netz bewaldeter Schluchten durchzogen, die zum Wasser hinabführen, mischt die Stadt Türme des Finanzviertels, rote Backsteinviertel im viktorianischen Stil und sehr große Parks. Für Halter unterscheidet sich Toronto vom Rest Nordamerikas: Ein Hund jeder Größe fährt außerhalb der Stoßzeiten kostenlos mit U-Bahn, Straßenbahn und Bus, die Stadt verfügt über mehr als achtzig ausgewiesene Freilaufflächen, und das Recht Ontarios erlaubt Hunde auf Restaurantterrassen. Die Kompromisse sind real: Die Badestrände sind vom 1. April bis 31. Oktober für Hunde gesperrt, und Ontario setzt weiterhin ein Rasseverbot durch, das keine andere große westliche Rechtsordnung anwendet.`,
    petTips: [`Das TTC-Stoßzeitverbot: Kein Haustier darf werktags von 6:30 bis 10:00 Uhr und von 15:30 bis 19:00 Uhr in U-Bahn, Straßenbahn oder Bus mitgenommen werden. Außerhalb dieser Zeiten ist die Fahrt kostenlos, ohne Größenbeschränkung.`, `Außerhalb einer ausgewiesenen Freilaufzone darf die Leine höchstens zwei Meter lang sein, ein loser Hund anderswo riskiert ein Bußgeld von bis zu 615 Dollar.`, `Badestrände sind vom 1. April bis 31. Oktober für Hunde gesperrt. Die eine sommerliche Ausnahme ist die Freilauffläche Cherry Beach, die ganzjährig geöffnet ist.`, `Vom 1. November bis 31. März dürfen Hunde bei Kew-Balmy und Woodbine unterhalb der Schneezaunlinie frei laufen, im Sand zwischen Zaun und Wasser.`, `Streusalz von Dezember bis März: Verwenden Sie Schuhe oder eine Pfotenbalsam, spülen und trocknen Sie die Ballen dann nach jedem Spaziergang ab.`],
    practicalInfo: [`Einreise nach Kanada: eine gültige, von einem approbierten Tierarzt unterzeichnete Tollwutimpfbescheinigung auf Englisch oder Französisch, mit Mikrochipnummer, Impfdatum, Ablaufdatum und Impfstoffmarke (CFIA).`, `Rassegesetz Ontarios: Besitz, Weitergabe oder Einfuhr eines Pitbulls ist in der Provinz verboten, mit einer weit gefassten Definition, die im Erscheinungsbild ähnliche Hunde einschließt. Holen Sie sich vor der Buchung rechtlichen Rat.`, `Vom Flughafen Pearson (YYZ) erreicht der UP-Express-Zug die Union Station in 25 Minuten und nimmt außerhalb der Stoßzeiten bis zu zwei angeleinte Hunde kostenlos mit.`, `24-Stunden-Tierärztliche Notfälle: Veterinary Emergency Clinic, 920 Yonge Street, +1 416 920-2002; Central Toronto Veterinary Referral Clinic, 1051 Eglinton Avenue West, +1 416 784-4444. 911 ist nur für Menschen.`, `Währung: kanadischer Dollar. Die tierärztliche Versorgung ist vollständig privat, und normalerweise wird vor der Behandlung eine Anzahlung verlangt, prüfen Sie also, was Ihre Reiseversicherung abdeckt.`],
    sights: {
      "Cherry Beach Dogs Off-Leash Area": `Der einzige echte Hundestrand der Stadt, ganzjährig geöffnet am Outer Harbour. Landseitig eingezäunt und zum Wasser hin offen, mit einem Bereich für kleine Hunde und einem doppelt gesicherten Eingang.`,
      "High Park Dog Hill": `Eine 3,4 Hektar große Freilauffläche plus ausgewiesene Wanderwege, zwischen dem Grenadier Restaurant und dem Zoo. Nicht eingezäunt, also nur für Hunde mit zuverlässigem Rückruf geeignet.`,
      "The Distillery Historic District": `Vierzig viktorianische Industriegebäude rund um kopfsteingepflasterte, vollständig autofreie Gassen. Hunde im Freien an der Leine willkommen, nicht erlaubt in den Restaurants und Bars selbst.`,
      "Toronto Island Park": `Autofreie Inseln, fünfzehn Minuten über den Hafen vom Jack Layton Ferry Terminal entfernt. Haustiere an der Leine an Bord und auf den Inseln erlaubt, die Inselstrände sind für Hunde gesperrt.`,
      "Evergreen Brick Works": `Ein ehemaliges Ziegelwerk im Don Valley, umgewandelt in ein Umweltzentrum, mit Bauernmarkt und Steinbruchteichen. Angeleinte Hunde im Freien, außer im Children's Garden.`,
      "Trinity Bellwoods Park": `Die westliche Hundemulde, die Senke eines verfüllten Stausees südlich der Dundas Street West. Leinenfrei und nicht eingezäunt, an einem Sommerabend sehr belebt.`,
    },
  },
  'tossa-de-mar': {
    history: `Tossa de Mar liegt in einer Bucht an der Costa Brava, in der Provinz Girona, Katalonien. Sie beherbergt die Vila Vella, die einzige noch stehende befestigte mittelalterliche Stadt an der gesamten katalanischen Küste: ein Labyrinth aus Kopfsteingassen, umringt von Wallanlagen und zylindrischen Türmen aus dem 12. Jahrhundert, auf einer Landzunge über dem Meer gelegen. Aus einem Fischerdorf, das in den 1930er Jahren zur Künstlerzuflucht wurde (Marc Chagall nannte es das „blaue Paradies“), verdankt Tossa seinen Ruhm auch dem Film Pandora, der 1951 mit Ava Gardner hier gedreht wurde, deren Statue heute über die Bucht wacht. Rund um die Altstadt windet sich der Küstenpfad camí de ronda entlang der Klippen zu versteckten Buchten, während die Playa Gran und die Bucht Mar Menuda die Bucht säumen. Für Reisende mit Hund vereint Tossa Freiluft-Wallanlagen, Küstenpfade und mediterrane Pinienwälder.`,
    petTips: [`Sommerliches Hundeverbot an den bewachten Stränden (Platja Gran, Mar Menuda) von der Osterwoche bis Ende September: Weichen Sie außerhalb der Saison auf die wilden Buchten entlang des camí de ronda aus.`, `Starke mediterrane Hitze im Juli und August: Gehen Sie früh morgens oder abends spazieren, da Sand und Fels der Bucht mittags glühen.`, `Der Tramuntana, ein heftiger Nordwind, kann an der Costa Brava plötzlich aufkommen: Halten Sie kleine Hunde an kurzer Leine auf den exponierten Klippenpfaden.`, `Der camí de ronda ist schmal und liegt hoch über dem Meer: Halten Sie Ihren Hund angeleint, da manche Abschnitte felsig und nach Regen rutschig sind.`, `Für einen tierärztlichen Notfall wählen Sie 112 (die europäische Notrufnummer); tierärztliche Kliniken gibt es in Tossa und im benachbarten Lloret de Mar.`],
    practicalInfo: [`Spanien gehört zur EU und zum Schengen-Raum: EU-Heimtierausweis + gültige Tollwutimpfung + ISO-Mikrochip genügen aus jedem EU-Land.`, `Nächstgelegener Flughafen: Girona-Costa Brava (GRO), etwa 40 km entfernt; Barcelona-El Prat (BCN) etwa 100 km.`, `Kein Bahnhof in Tossa: erreichbar mit dem Auto oder per Bus ab Girona, Lloret de Mar oder Barcelona (Hunde an der Leine und mit Maulkorb oder je nach Größe in einer Transportbox).`, `Währung: Euro. In Katalonien müssen als „potenziell gefährlich“ eingestufte Hunde in der Öffentlichkeit Leine und Maulkorb tragen.`, `Beste Reisezeit: Mai-Juni und September-Oktober, um die Sommermassen und das Strandverbot zu vermeiden.`],
    sights: {
      "Vila Vella": `Eine denkmalgeschützte befestigte Anlage aus dem 12. Jahrhundert, die sich auf der Landzunge Mont Guardí erhebt. Ihre Kopfsteingassen, Wallanlagen und zylindrischen Türme lassen sich mit angeleintem Hund frei im Freien begehen, mit weiten Ausblicken über die Bucht.`,
      "Far de Tossa i Museu Municipal": `Der Leuchtturm, der die Vila Vella krönt, und das im ehemaligen Gouverneurshaus untergebrachte Städtische Museum, Spaniens erstes Museum für zeitgenössische Kunst (1935). Die Leuchtturm-Esplanade davor ist an der Leine zugänglich, doch Hunde dürfen das Museum nicht betreten.`,
      "Platja Gran i Mar Menuda": `Die beiden Sandstrände der Bucht, die breite Platja Gran unterhalb der Wallanlagen und die bei Tauchern beliebte Bucht Mar Menuda. An diesen bewachten Stränden sind Hunde von der Osterwoche bis Ende September verboten; außerhalb der Saison wird der Zugang geduldet.`,
      "Camí de Ronda": `Der alte Zollpfad, der den Klippen der Costa Brava zu versteckten Buchten wie Cala Bona und Cala Pola folgt. Ganzjährig für angeleinte Hunde geöffnet und von Pinien beschattet, ist es Tossas schönster Hundespaziergang.`,
      "Estàtua d'Ava Gardner": `Eine Bronzestatue der Schauspielerin auf einem Balkon der Vila Vella, zur Erinnerung an die Dreharbeiten von Pandora 1951 in Tossa. Ein Freiluft-Aussichtspunkt, frei zugänglich mit Hund, mit Blick auf Meer und Wallanlagen.`,
      "Cala Pola i Cala Giverola": `Wilde Buchten nördlich von Tossa, eingebettet in die Pinienwälder und erreichbar über den camí de ronda oder eine Naturstraße. Abseits der Stadtstrände bieten sie außerhalb der Saison ruhige Bademöglichkeiten, an denen angeleinte Hunde besser geduldet werden.`,
    },
  },
  toulon: {
    history: `Toulon, seit Ludwig XIV. Frankreichs wichtigster Mittelmeer-Marinehafen, erstreckt sich am Fuß des 584 Meter hohen Mont Faron an einer der schönsten natürlichen Reeden der Welt. Phokäer, Römer, Sarazenen, dann Vauban, der die Stadt 1679 in die Festung verwandelte, die wir heute kennen: Der Quai Atlantes von Pierre Puget, der Tour Royale aus dem 16. Jahrhundert und die Befestigungen der Vieille Ville sind das Erbe jener Zeit. Im 20. Jahrhundert ist Toulon leider berühmt für die Versenkung der französischen Flotte im November 1942, um sie vor dem Zugriff der Nazis zu bewahren, und für die Befreiung im August 1944, an die im Mémorial du Débarquement auf dem Gipfel des Mont Faron erinnert wird. Für reisende Haustiere verlangt Frankreich den EU-Heimtierausweis, ISO-Mikrochip und eine gültige Tollwutimpfung. Toulon ist eine der bestausgestatteten französischen Städte für Hunde: ein offizieller cani-plage an der Anse Tabarly, zwei eingezäunte cani-parcs am Mourillon, das Réseau Mistral, das große angeleinte, mit Maulkorb versehene Hunde offiziell in Bussen und Wasserbussen zulässt (eine französische Seltenheit), und die Seilbahn zum Mont Faron, die Hunde kostenlos mitnimmt.`,
    petTips: [`Die Seilbahn zum Mont Faron nimmt angeleinte Hunde ohne Größenbeschränkung kostenlos mit, eine der wenigen großen französischen Seilbahnen, die dies tun.`, `Das Réseau Mistral ist eines der wenigen französischen Stadtnetze, das große angeleinte Hunde mit Maulkorb offiziell in Bussen und bateau-bus zulässt (gegen Ticket); kleine Haustiere im Korb und Blindenführhunde kostenlos.`, `Strände am Mourillon: Hunde ganzjährig auf Sand und Rasenflächen verboten; gepflasterte Promenade Henri Fabre 06:00–08:30 Uhr im Sommer (1. Juni–31. August), ganztägig vom 1. September bis 31. Mai. Ganzjährig cani-plage Anse Tabarly mit Hundeschwimm-Rampe.`, `Porquerolles: TLV-TVM-Fähre für angeleinte Hunde kostenlos, doch alle Strände der Insel verbieten Hunde (Vorschriften des Nationalparks). Nur Wanderwege.`, `Zwei rund um die Uhr geöffnete Notfall-Tierkliniken: Telo Vet (04 22 54 04 54) und Vétérinaires 2 Toute Urgence (04 27 04 02 70); kostenlose landesweite Hotline 3115.`],
    practicalInfo: [`Anreise: SNCF-Bahnhof 5 Gehminuten von der Vieille Ville entfernt, TGV nach Paris 4 Std., küstennaher TER nach Marseille 50 Min., Nizza 2 Std. Flughafen Toulon-Hyères (TLN) 20 Min. östlich (saisonal) oder Marseille Provence (MRS, 1:30 Std.) für mehr Optionen.`, `Strände: ganzjährig cani-plage Anse Tabarly (Hundeschwimm-Rampe), Mourillon Promenade Henri Fabre an der Leine 06:00–08:30 Uhr im Sommer und ganztägig außerhalb des Sommers; Sand und Rasenflächen am Mourillon jederzeit für Hunde verboten (Vorschrift von 2023).`, `Parks: Mont Faron (Seilbahn für Hunde kostenlos), Cani-parc du Mourillon (zwei eingezäunte Freilaufflächen), Sentier du Littoral Cap Brun (2024 wiedereröffnet, an der Leine).`, `Verkehrsmittel: Das Réseau Mistral lässt große angeleinte Hunde mit Maulkorb offiziell in Bussen und bateau-bus zu (gegen Ticket); kleine Haustiere im Korb und Blindenführhunde kostenlos, eine französische Seltenheit.`, `Tierärzte: Telo Vet (04 22 54 04 54, Avenue Pierre Loti, 24/7), Vétérinaires 2 Toute Urgence (04 27 04 02 70, route de Marseille, nachts + Wochenenden), Clinique des 4 Chemins; kostenlose landesweite Hotline 3115.`],
    sights: {
      "Téléphérique du Mont Faron": `Die Seilbahn, die den 584 Meter hohen Mont Faron in 6 Minuten von der unteren Station Super-Toulon aus erklimmt, mit einem 360-Grad-Mittelmeerpanorama an der Spitze. Das Fremdenverkehrsamt bestätigt, dass Hunde kostenlos in der Kabine mitfahren, an der Leine, ohne Größenbeschränkung. Schließt bei starkem Mistral.`,
      "Marché du Cours Lafayette": `Der große provenzalische Markt Toulons, jeden Morgen außer montags unter den Platanen des Cours Lafayette. Fisch, Obst, Gemüse, Blumen, provenzalische Kräuter und Street Food: pichade, cade toulonnaise, socca. Angeleinte Hunde gehören zum täglichen Marktbild; bringen Sie eigene Kotbeutel mit. Bekannt durch Gilbert Bécauds Lied Les marchés de Provence.`,
      "Anse Tabarly (cani-plage)": `Der offizielle, ganzjährige Hundestrand am östlichen Ende des Mourillon, mit Hundeschwimmzone, einer Rampe ins Wasser für ältere Hunde und schattigen Bänken. Von der Stadt Toulon gelistet. Hunde an der Leine auf dem Zugang; leinenfrei nur innerhalb der Hundeschwimmzone erlaubt.`,
      "Sentier du Littoral (Cap Brun)": `Der Küstenpfad um die felsige Halbinsel Cap Brun östlich des Mourillon, 2024 nach 15 Jahren Sperrung wegen Erdrutschgefahr vollständig wiedereröffnet. Klippenblick über die Reede und die Iles d'Or. Angeleinte Hunde in Felszonen geduldet; bewachte Sandstrände verbieten Hunde im Sommer.`,
      "Quai Cronstadt + Caryatides d'Atlantes": `Der Fußgängerkai zwischen Hafen und Vieille Ville, mit im Becken vertäuten Fregatten der französischen Marine und den Atlantes-Karyatiden von Pierre Puget an der Fassade des Musée National de la Marine. Ebene 1 km lange Runde, jederzeit an der Leine für Hunde zugänglich. Das Museumsinnere verbietet Hunde außer Blindenführhunden.`,
      "Cani-parc du Mourillon": `Zwei eingezäunte Freilaufflächen, die die Stadt 2023 an den Stränden des Mourillon eingerichtet hat: eine für kleine Hunde, eine für mittlere und große. Sitzgelegenheiten, Wasserstelle und Kotbeutelspender. Die einzige formell eingezäunte Freilauffläche innerhalb Toulons. Impfung erforderlich.`,
    },
  },
  torun: {
    history: `Toruń ist die Wiege der polnischen Astronomie und eine von nur zwei mittelalterlichen polnischen Städten, deren Zentrum den Zweiten Weltkrieg fast unversehrt überstand. 1233 vom Deutschen Orden am Ufer der Weichsel gegründet, trat die Stadt rasch der Hanse bei und errichtete ihr gewaltiges gotisches Rathaus aus rotem Backstein, eines der monumentalsten in Nordeuropa. Hier wurde 1473 Nikolaus Kopernikus geboren, in einem Kaufmannshaus am Marktplatz, das heute ein Museum ist. Die örtliche Spezialität, die seit dem 13. Jahrhundert belegten pierniki-Lebkuchen, wurde zu einer Industrie und einem Wahrzeichen, gefeiert im Museum des Lebendigen Lebkuchens in der ul. Rabiańska. Das historische Zentrum ist seit 1997 UNESCO-Weltkulturerbe wegen seines herausragenden Ensembles backsteingotischer Architektur. Die MPK-Straßenbahnen nehmen Hunde an der Leine mit, die Terrassen an beiden Rynek-Plätzen heißen sie gerne willkommen, und die Stadt unterhält rund zwanzig eingezäunte Hundefreilaufflächen (wybiegi).`,
    petTips: [`Der öffentliche Nahverkehr MZK Toruń verlangt für alle Hunde eine Leine und für als aggressiv eingestufte Rassen einen Maulkorb in Straßenbahnen und Bussen; kleine Hunde in einer geschlossenen Transportbox reisen kostenlos.`, `Polens elf gelistete „gefährliche Rassen“ benötigen eine Genehmigung des Rathauses; führen Sie Abstammungspapiere mit, um Verwechslungen mit ähnlich aussehenden Hunden zu vermeiden.`, `Mittags erreicht das Reisegruppengedränge am Rynek Staromiejski seinen Höhepunkt; gehen Sie mit Ihrem Hund früh morgens (vor 10:00 Uhr) oder nach 18:00 Uhr spazieren.`, `Bußgelder für Hundekot im Stadtzentrum erreichen 500 PLN; städtische Ordnungskräfte patrouillieren nahe dem Rynek und dem Bulwar Filadelfijski, führen Sie stets Beutel mit sich.`, `Die Strömung der Weichsel ist stark und zum Schwimmen unsicher; für echtes Hundeschwimmen fahren Sie zum See Chełmżyńskie 25 km nördlich, erreichbar mit dem Zug ab Toruń Główny.`],
    practicalInfo: [`EU-Reisende benötigen einen EU-Heimtierausweis, einen ISO-Mikrochip und eine mindestens 21 Tage zurückliegende Tollwutimpfung; Nicht-EU-Reisende benötigen ein innerhalb von 10 Tagen vor Ankunft ausgestelltes tierärztliches Gesundheitszeugnis.`, `Der nächste internationale Flughafen ist Bydgoszcz Ignacy Jan Paderewski (BZG), 45 km westlich; regelmäßige Bus- und Zugverbindungen ab Toruń Główny.`, `24-Stunden-Tierkliniken sind unter anderem MAX-VET und Weterynarz 24h Arka Noego (ul. Wybickiego 64A), Notfälle werden auf Englisch behandelt; die Lecznica Wyszyńskiego deckt die tägliche Grundversorgung ab.`, `Toruńs Winter liegen bei -3 bis 0 °C mit Schnee von Dezember bis März; Pfotenbalsam, Schuhe und ein Mantel für kurzhaarige Rassen sind unverzichtbar. Sommer sind mild bei 19-23 °C.`, `Die Taxi-Apps Bolt, Free Now und iTaxi akzeptieren Haustiere bei entsprechender Angabe bei der Buchung; ein Handtuch für den Sitz wird als Höflichkeit erwartet.`],
    sights: {
      "Rynek Staromiejski": `Ein mittelalterlicher Marktplatz aus dem 13. Jahrhundert, dominiert vom gotischen Rathaus aus rotem Backstein und umringt von gotischen und barocken Bürgerhäusern. Die Kopernikus-Statue steht im Zentrum, und Café-Terrassen säumen den Platz. Angeleinte Hunde willkommen auf dem Kopfsteinpflaster und den meisten Terrassen; das Rathausmuseum im Inneren lässt nur Assistenzhunde zu.`,
      "Krzywa Wieża (Leaning Tower)": `Ein Verteidigungsturm aus dem 13. Jahrhundert, in die Stadtmauern eingebaut, der wegen lehmiger Fundamente etwa 1,5 Meter von der Senkrechten abweicht. Die örtliche Legende schreibt die Neigung einem bestraften Ordensritter zu. Angeleinte Hunde ringsum draußen willkommen; das Café im Inneren lässt nur Assistenzhunde zu.`,
      "Bulwar Filadelfijski": `Eine 2 km lange Uferpromenade an der Weichsel am Fuß der mittelalterlichen Stadtmauern, benannt nach Philadelphia, Toruńs amerikanischer Partnerstadt. Postkartenblick zurück auf die backsteingotischen Türme. Angeleinte Hunde ganzjährig willkommen, Hundetoilette nahe der ul. św. Jakuba, kleine Kiesstrände bei Niedrigwasser.`,
      "Park Tysiąclecia (Bydgoskie Przedmieście)": `Ein großer Landschaftspark aus dem 19. Jahrhundert westlich der Altstadt, mit alten Eichen- und Kastanienalleen, zwei Teichen und weiten Rasenflächen. Am südlichen Rand befindet sich eine eingezäunte Hundefreilauffläche (wybieg) mit Agility-Rampen. Einstündige Runde, verbunden mit dem Bulwar Filadelfijski.`,
      "Las Bielany": `Ein 350 Hektar großer Kiefern- und Eichenwald am nordwestlichen Stadtrand, in 15 Minuten mit Bus 27 erreichbar. Netz markierter Wander- und Radwege. Auf den inneren Pfaden wird Freilauf geduldet, an den Eingängen gilt Leinenpflicht.`,
      "Old Town walls and gates circuit": `Der Rundgang entlang der erhaltenen mittelalterlichen Mauern um die Altstadt führt am Klostertor, am Brückentor und am Seglertor vorbei, alle in roter Backsteingotik. Eine einstündige, vollständig im Freien liegende Runde, angeleinte Hunde ganzjährig willkommen.`,
    },
  },
  toulouse: {
    history: `Toulouse, „La Ville Rose“ an der Garonne, verdankt seinen warmen rosa Farbton dem aus Flusslehm gebrannten Terrakotta-Backstein, der schon zur Römerzeit verwendet wurde, als die Stadt als Tolosa bekannt war. Als Hauptstadt der mittelalterlichen Grafen von Toulouse und Wiege der Trobador-Dichtung wurde sie durch den Waid-Handel (pastel) des 16. Jahrhunderts reich, der ihre Renaissance-Stadtpaläste finanzierte. Heute ist sie Frankreichs viertgrößte Stadt und Europas Luftfahrthauptstadt, Heimat von Airbus und der Cité de l'Espace. Die Garonne-Kais und der Canal du Midi aus dem 17. Jahrhundert, ein UNESCO-Standort und Geistesprodukt von Pierre-Paul Riquet, bilden eine nahezu durchgehende Uferpromenade, größtenteils von Platanen beschattet und hundefreundlich. Mit der Prairie des Filtres, die leinenfreie Wiesen mitten in der Stadt bietet, rangiert Toulouse durchweg unter Frankreichs hundefreundlichsten Stadtzentren.`,
    petTips: [`Die Prairie des Filtres erlaubt Freilauf unter wirksamer Rufkontrolle, kein eingezäuntes Gehege, trainieren Sie also den Rückruf, bevor Sie hingehen.`, `Die Tisséo-Metrolinien A und B nehmen kleine Hunde (<6 kg) in geschlossenen Transportboxen kostenlos mit; größere Hunde sind nur in oberirdischen Straßenbahn- und Buslinien erlaubt, angeleint und mit Maulkorb.`, `Hunde der Kategorien 1 und 2 benötigen die städtische französische Genehmigung (attestation und Maulkorb), die Polizei Toulouse kontrolliert an den Treidelwegen des Kanals.`, `Am Canal du Midi gibt es im zentralen Abschnitt alle 500 m verpflichtende Hundekot-Stationen; Bußgelder bei Nichteinsammeln erreichen 68 €.`, `Die Sommerhitze kann 38 °C erreichen; die Kais Daurade und Saint-Pierre bleiben selbst mittags unter Platanen schattig, anders als der offene Place du Capitole.`],
    practicalInfo: [`Nächstgelegener Flughafen: Toulouse-Blagnac (TLS), 8 km vom Zentrum entfernt, angebunden durch die Straßenbahnlinie T2, die angeleinte und mit Maulkorb versehene Hunde mitnimmt.`, `Der 24-Stunden-Notfalltierarzt Clinique Vétérinaire des Carmes (boulevard Lascrosses) deckt die zentralen Bezirke ab; ADVETIA in Purpan übernimmt fachärztliche Überweisungen.`, `Leitungswasser ist unbedenklich, und Trinkbrunnen finden sich im Jardin des Plantes, am Grand-Rond und in der Prairie des Filtres, bringen Sie eine faltbare Schale mit.`, `Die Garonne tritt im Winter und Frühling über die Ufer; prüfen Sie vor Spaziergängen an den unteren Kais nach starkem Regen die Website Vigicrues.`, `Französisches Recht verlangt für alle einreisenden Hunde ISO-Mikrochip, Tollwutimpfung und EU-Heimtierausweis, sowie Leinenpflicht in allen öffentlichen Räumen Toulouses.`],
    sights: {
      "Prairie des Filtres": `Eine 4 Hektar große Überschwemmungswiese am linken Garonne-Ufer, direkt gegenüber der Altstadt. Sie ist einer der wenigen französischen Innenstadtparks, in denen Hunde frei laufen dürfen, und füllt sich bei Sonnenuntergang mit Einheimischen, Frisbees und Gitarren.`,
      "Canal du Midi": `Der 240 km lange, UNESCO-gelistete, von Ludwig XIV. in Auftrag gegebene Kanal beginnt am Port Saint-Sauveur und erstreckt sich bis zum Mittelmeer. Der durchgehende, von Platanen beschattete Treidelweg eignet sich ideal für lange Leinenspaziergänge oder Radtouren mit Hundeanhänger.`,
      "Basilique Saint-Sernin": `Zwischen 1080 und 1120 erbaut, ist dies die größte erhaltene romanische Kirche Europas und eine wichtige Station auf dem Jakobsweg nach Santiago de Compostela. Hunde dürfen mit Ihnen auf der umliegenden Place Saint-Sernin sitzen, doch nicht in die Basilika.`,
      "Place du Capitole": `Der weite Hauptplatz aus dem 18. Jahrhundert, beherrscht vom Capitole-Rathaus mit dem in das Pflaster eingelassenen okzitanischen Kreuz. Angeleinte Hunde sind auf dem Platz und unter den Arkaden willkommen, wo mehrere Cafés im Sommer Wassernäpfe bereitstellen.`,
      "Jardin des Plantes": `Dieser 1794 angelegte, 7 Hektar große Botanische Garten verbindet sich über Bogenbrücken mit dem Grand-Rond und dem Jardin Royal. Angeleinte Hunde sind auf allen Hauptwegen erlaubt, das im Park gelegene Naturkundemuseum lässt sie jedoch nicht zu.`,
      "Pont Neuf & Quais de la Garonne": `1659 von Ludwig XIV. nach fast einem Jahrhundert Bauzeit eingeweiht, verbindet die Pont Neuf die Altstadt mit Saint-Cyprien. Die gepflasterten Kais auf beiden Ufern sind sonntags für Autos gesperrt und bieten Hundehaltern ununterbrochene Kilometer entlang des rosafarbenen Flusses.`,
    },
  },
  tours: {
    history: `Tours ist die historische Hauptstadt der Touraine, am Südufer der Loire an ihrem Zusammenfluss mit dem Cher gelegen, und das Tor zu den Loire-Schlössern, UNESCO-Weltkulturerbe. Ihre Wurzeln sind römisch (das im 1. Jahrhundert von Augustus gegründete Caesarodunum), doch die Stadt nahm ihre mittelalterliche Gestalt als Wallfahrtszentrum um das Grab des heiligen Martin von Tours (Bischof des 4. Jahrhunderts, Schutzpatron Frankreichs) an und als königliche Residenz unter den Valois-Königen im 15. und 16. Jahrhundert. Jeanne d'Arc erhielt hier 1429 ihr Schwert in der Basilika. Das Fachwerk-Vieux-Tours rund um die Place Plumereau bewahrt die Kaufmannsstadt des späten Mittelalters; der Boulevard Béranger aus dem 19. Jahrhundert und das elegante Viertel Prébendes d'Oé spiegeln die Belle-Époque-Erweiterung wider. Mit rund 136.000 Einwohnern (300.000 im Ballungsraum) und einer starken Universitätspräsenz verbindet Tours provinzielle Ruhe mit der kulturellen Infrastruktur einer Regionalhauptstadt. Die Tierkultur der Stadt ist bemerkenswert ausgereift: Das Netz Fil Bleu nimmt Hunde jeder Größe mit (in Frankreich selten), die Kommune eröffnete 2021 ihre erste offizielle aire d'ébats canins im Parc de Sainte-Radegonde, und jedes bedeutende Loire-Schloss im Umkreis von 60 km heißt angeleinte Hunde in seinen Gärten willkommen.`,
    petTips: [`Das Fil-Bleu-Straßenbahn- und Busnetz ist für Frankreich ungewöhnlich haustierfreundlich, kleine Hunde in Transportboxen reisen auf dem Schoß des Halters, größere Hunde angeleint und mit Maulkorb für den Preis eines Fahrgastscheins (1,60 €). Kategorie-1-Hunde (Pitbull und Ähnliche) sind verboten.`, `Alle vier großen Loire-Schlösser bei Tours heißen Hunde in ihren Gärten willkommen: Villandry, Chenonceau, Amboise, Chambord. Nur kleine Hunde in Tasche oder Korb dürfen die Innenräume betreten; große Hunde bleiben draußen, kombinieren Sie den Besuch mit einem Sitter, wenn Sie die Innenräume sehen möchten.`, `Die Duldung des Hundeschwimmens am Loire-Ufer ist örtlicher Brauch, keine offizielle Regelung, das beste Zeitfenster ist Mitte Juli bis Anfang September, wenn der Fluss am niedrigsten steht. Meiden Sie es nach starkem Regen (Mai, Oktober), wenn die Strömung zunimmt.`, `Tierärztliche Notdienste außerhalb der Öffnungszeiten übernimmt Urg&Vet in Rochecorbon (5 km östlich von Tours) jede Nacht von 19:00–08:00 Uhr sowie an allen Wochenenden/Feiertagen. Zentrale Tagespraxen sind TouraineVet und Clinique Tour Carrée; rufen Sie deren ALVETIS-Leitung +33 2 47 40 10 30 außerhalb der Öffnungszeiten an.`, `Tours liegt an der TGV-InOui-Linie: Paris Montparnasse in 1:05 Std. (kleine Haustiere 7 € in Transportbox, größere Hunde halber Erwachsenenfahrpreis). Der Bahnhof Saint-Pierre-des-Corps, 5 km östlich, bewältigt den Großteil des TGV-Verkehrs, der Fil-Bleu-Shuttle nimmt Hunde für die Anschlussverbindung mit.`],
    practicalInfo: [`Nächstgelegene Flughäfen: Tours Val de Loire (TUF) 10 Min. nördlich der Stadt (saisonal Ryanair); Paris Orly und CDG per TGV in 1:05 Std. (Kabinenhaustiere bei den meisten Fluggesellschaften erlaubt).`, `Der zentrale Bahnhof Tours Gare bedient regionale TER-Züge; Saint-Pierre-des-Corps 5 km östlich bewältigt den stärkeren TGV-Verkehr. SNCF: kleine Haustiere 7 € in Transportbox pro Fahrt; größere Hunde angeleint und mit Maulkorb zum halben Erwachsenenfahrpreis.`, `Leitungswasser ist stadtweit trinkbar; das Vieux-Tours verfügt über öffentliche Wallace-Brunnen, die im Sommer als Wassernäpfe genutzt werden können.`, `Führen Sie überall Kotbeutel mit, kommunale Bußgelder für Nichteinsammeln betragen 68 €, strenger durchgesetzt im Vieux-Tours und entlang des Loire-Uferdamms.`, `EU-Heimtierausweis, Mikrochip und Tollwutimpfung erforderlich. Britische Reisende benötigen seit dem Brexit ein von einem amtlichen Tierarzt innerhalb von 10 Tagen vor der Reise ausgestelltes Tiergesundheitszeugnis (AHC).`],
    sights: {
      "Place Plumereau": `Der ikonische mittelalterliche Platz im Herzen des Vieux-Tours, umringt von Fachwerkhäusern des 15. Jahrhunderts, die zu Café-Restaurants umgebaut wurden. Die Kopfsteinpflaster-Fußgängerzone verbindet sich mit der Rue Colbert und der Rue du Grand Marché, angeleinte Hunde sind überall willkommen und fast alle Terrassen nehmen sie auf.`,
      "Cathédrale Saint-Gatien": `Tours' gotische Kathedrale, zwischen dem 13. und 16. Jahrhundert erbaut, mit Buntglasfenstern aus dem 13.–15. Jahrhundert, die den Zweiten Weltkrieg überstanden. Das Innere lässt keine Hunde zu (außer registrierten Assistenzhunden), doch die davorliegende Place de la Cathédrale, der angrenzende Psalette-Kreuzgang und der dahinterliegende Jardin de Beaune-Semblançay heißen angeleinte Hunde willkommen.`,
      "Parc de Sainte-Radegonde": `Tours' größter Stadtpark, 14 Hektar Wald, Rasenflächen und Spielbereiche nördlich der Loire, Heimat der ersten offiziellen aire d'ébats canins der Stadt (eingezäunte Hundefreilauffläche), eingeweiht am 3. Oktober 2021. Es gibt sogar ein über 1 Hektar großes Lama-Gehege nahe dem Tennisclub.`,
      "Château de Villandry": `Die Renaissancegärten von Villandry, 15 km westlich von Tours, gelten als die schönsten Europas, sechs terrassierte Abschnitte einschließlich des zierlichen Renaissance-Küchengartens. Angeleinte Hunde sind in den 9 Hektar Gärten willkommen; kleine Hunde in Tasche oder Korb dürfen auch das Schlossinnere betreten.`,
      "Loire à Vélo": `Die 900 km lange regionale Radroute entlang der Loire, die direkt durch Tours führt. Der 8 km lange Abschnitt Richtung Vouvray im Osten verläuft unter Platanen am Flussufer, vollständig hundefreundlich zum Gehen oder Radfahren, mit Endpunkt an den Weinterrassen von Vouvray.`,
      "Jardin des Prébendes d'Oé": `Ein 4 Hektar großer englischer Landschaftspark aus dem 19. Jahrhundert, 1872 von den Brüdern Bühler gestaltet (die auch den Parc de la Tête d'Or in Lyon entwarfen), 7 Gehminuten vom Bahnhof entfernt. Ein Bach, alte Bäume, Rasenflächen und Blumenbeete in einer edlen Belle-Époque-Kulisse. Angeleinte Hunde willkommen.`,
    },
  },
  trapani: {
    history: `Trapani, die „Sichel“, die am Meer an Siziliens Westspitze liegt, verdankt ihren griechischen Namen (Drepanon, Sichel) der gekrümmten Landzunge, die ihren Hafen schützt. Von den Elymern gegründet und dann karthagischer Handelsposten, war sie die Anlegestelle für den heiligen Berg Eryx, bevor sie unter den Aragonesen zu einem großen Salz- und Korallenhafen wurde. Ihre seit der Antike bewirtschafteten Salinen reihen ihre Windmühlen noch immer zwischen Himmel und Lagune auf. Die Altstadt, auf ihrem barocken Vorsprung gedrängt, entfaltet Paläste, Kirchen und die Fußgängerstraße Via Torrearsa bis hinunter zu den Molen, von denen man zu den Ägadischen Inseln und nach Tunesien ablegt. Überragt von Erice, das auf 750 Metern thront und durch eine spektakuläre Seilbahn verbunden ist, lebt Trapani dem Wasser zugewandt: Fischcouscous, Thunfisch, Salz und Sonnenuntergänge über den Sümpfen. Eine flache, gut begehbare, windige Stadt, perfekt zum Erkunden an der Leine.`,
    petTips: [`Italienische Regel: eine höchstens 1,5 m lange Leine in der Stadt und ein griffbereiter Maulkorb, in Verkehrsmitteln, der Seilbahn und auf den Fähren vorgeschrieben; ohne einen mitgeführten Maulkorb riskieren Sie ein Bußgeld.`, `Sizilianische Sommerhitze: Von Juni bis September steigt das Thermometer oft über 33 °C, und die Salinendeiche bieten keinen Schatten, gehen Sie also bei Sonnenaufgang oder -untergang spazieren und führen Sie stets Wasser mit.`, `Asphalt, Salz und Felsen glühen am Nachmittag: Prüfen Sie den Boden mit dem Handrücken, bevor Sie Ihren Hund spazieren führen, und bevorzugen Sie schattige Pausen unter den Arkaden der Stadt.`, `Sizilien ist ein Leishmaniose-Endemiegebiet (Sandmücken von April bis Oktober in der Dämmerung aktiv): Besprechen Sie mit Ihrem Tierarzt vor der Reise ein Repellent-Halsband oder Spot-on-Mittel.`, `Strände: Die meisten Lidos verbieten Hunde im Sommer; zielen Sie auf unbewachte Buchten, die Küste von San Vito Lo Capo etwa vierzig Kilometer entfernt, oder ausgeschilderte Hundebereiche, am besten frühmorgens.`],
    practicalInfo: [`Notfälle: 112 ist Italiens einheitliche europäische Nummer; Trapani hat mehrere Tierarztkliniken im Zentrum und nahe dem Hafen, fragen Sie Ihr Hotel nach dem nächsten Bereitschaftsdienst.`, `Fähren und Tragflügelboote zu den Ägadischen Inseln (Liberty Lines, Siremar): Hunde angeleint und mit Maulkorb zugelassen, für große Hunde kann ein Ticket erforderlich sein, erkundigen Sie sich am Hafenschalter.`, `Seilbahn Trapani-Erice: angeleinte und mit Maulkorb versehene Hunde in der Kabine erlaubt; es ist der einfachste Weg, das Bergdorf ohne die Serpentinenstraße zu erreichen.`, `Strände: Lidos verbieten Hunde im Sommer; die Küste von San Vito Lo Capo (etwa vierzig Kilometer entfernt) hat Buchten und ausgeschilderte Hundebereiche, es lohnt sich, diese vor der Abfahrt zu erkunden.`, `Der Flughafen Trapani-Birgi (Vincenzo Florio) liegt etwa 15 km entfernt; Italien gehört zur EU, bringen Sie also den europäischen Heimtierausweis mit aktuellem Mikrochip und Tollwutimpfung mit.`],
    sights: {
      "Centro Storico e Via Torrearsa": `Die Fußgängerachse der Altstadt von Trapani verläuft zwischen barocken Palästen, einem überdachten Markt und Fassaden auf der Landzunge am Meer. Alles spielt sich draußen an der Leine ab: der Morgenmarkt, der Aperitivo und der Spaziergang zur Kathedrale San Lorenzo.`,
      "Saline di Trapani e Riserva WWF": `Die historischen Salinen, ihre Windmühlen und das WWF-Reservat bilden eine flache Lagune, durch die Flamingos und Stelzenläufer ziehen. Deichwege im Freien, Hunde an der Leine: sehr der Sonne ausgesetzt, bringen Sie also Wasser mit und besuchen Sie früh oder bei Sonnenuntergang.`,
      "Funivia Trapani-Erice": `Die Seilbahn steigt in zehn Minuten von Trapani nach Erice auf, mit Panorama über die Salinen und die Ägadischen Inseln. Angeleinte und mit Maulkorb versehene Hunde sind in der Kabine erlaubt: Ein Maulkorb ist Pflicht, und es ist am besten, außerhalb der Stoßzeiten zu fahren.`,
      "Erice": `Das mittelalterliche Dorf auf 750 Metern Höhe, Kopfsteingassen, die Venusburg und Wallanlagen im Nebel. Erreichbar zu Fuß oder mit der Seilbahn, komplett an der Leine begehbar: Der Boden ist bei Nässe rutschig, bringen Sie also Wasser und schattige Pausen mit.`,
      "Torre di Ligny": `Der spanische Turm aus dem 17. Jahrhundert markiert die äußerste Spitze der Sichel, zwischen zwei Meeren, mit einem der schönsten Sonnenuntergänge Siziliens. Die Mole und der Uferweg werden an der Leine begangen, sehr windig und schattenlos.`,
      "Isole Egadi (Favignana)": `Vom Hafen aus bedienen Tragflügelboote und die Fähre Favignana, Levanzo und Marettimo, mit kristallklarem Wasser. Angeleinte und mit Maulkorb versehene Hunde sind an Bord erlaubt: Favignana lässt sich per Rad oder zu Fuß zwischen Buchten und alten Thunfischfallen erkunden.`,
    },
  },
  trento: {
    history: `Das römische Tridentum an der Etsch, Trient trägt seinen Namen von den drei Hügeln, die es umgeben, und seinen Ruhm vom Konzil, das hier zwischen 1545 und 1563 das katholische Europa neu ordnete. Fast acht Jahrhunderte lang von Fürstbischöfen aus dem Castello del Buonconsiglio regiert, bewahrte die Stadt ihre Renaissancepaläste mit freskengeschmückten Fassaden rund um die Piazza del Duomo. Bis 1918 österreichisch, ist sie heute Hauptstadt einer wohlhabenden autonomen Provinz mit einem Ruf für hohe Lebensqualität. Als Universitäts- und Wissenschaftsstadt mit Renzo Pianos MUSE-Museum bleibt sie vor allem eine Bergstadt: Die Seilbahn steigt in vier Minuten nach Sardagna hinauf, und der Monte Bondone erhebt sich über 2.000 Meter über die Dächer. Für Hunde ist es eine Stadt eingezäunter Auslaufflächen, bewaldeter Parks und alpiner Wanderwege, die fast im Stadtzentrum beginnen.`,
    petTips: [`Führen Sie stets einen Maulkorb mit sich: Busse, Regionalzüge und die Seilbahn nach Sardagna verlangen einen zusammen mit einer höchstens 1,5 Meter langen Leine, unabhängig von der Größe Ihres Hundes.`, `Bei Trentino Trasporti reisen kleine, auf dem Arm getragene Hunde kostenlos, größere zahlen ein 1,20-Euro-Ticket; ein Tier pro Fahrgast, außer bei den eigens dafür vorgesehenen Kabinenfahrten der Seilbahn.`, `Seit 1997 unterhält die Stadt eingezäunte Hundeauslaufflächen mit Brunnen in ihren Hauptparks: Gocciadoro, Melta, Alexander Langer und Piazza Venezia sind am praktischsten.`, `Meiden Sie im Juli und August das glühende Talpflaster in den heißen Stunden: Fahren Sie hinauf zum Monte Bondone oder brechen Sie früh zu den Hundestränden am Lago di Caldonazzo auf, 25 Minuten entfernt.`, `Der öffentliche Strand im Ort Caldonazzo verbietet Hunde: Zielen Sie auf die beiden offiziellen Bau-Beaches, San Cristoforo und Le Stanghe in Calceranica, und bringen Sie Wasser mit, vor Ort gibt es keine Brunnen.`],
    practicalInfo: [`24-Stunden-Tierärztliche Notfälle: Clinica Veterinaria Animal Care, Via Palermo 19/4, Tel. +39 0461 390342 (Notfälle +39 347 049 3266).`, `Bereitschaftsdienst 24/7 einschließlich Feiertage: Ambulatorio Veterinario Martignano, Notfälle +39 340 854 7293 (anrufen, keine Nachrichten senden).`, `Europäische Notrufnummer: 112. Bei einem verletzten Wildtier weist Sie die örtliche Polizei Trients an den zuständigen Dienst.`, `Führen Sie in Zügen den Impfausweis oder EU-Heimtierausweis Ihres Hundes mit sich: Er kann an Bord kontrolliert werden.`, `Kotbeutel sind überall in der Stadt Pflicht; die Auslaufflächen bieten Spender und Brunnen, doch die Hundestrände am Lago di Caldonazzo haben kein Trinkwasser.`],
    sights: {
      "Piazza del Duomo": `Trients gutes Stube: die Kathedrale San Vigilio, der Neptunbrunnen und die vollständig freskierten Cazuffi-Rella-Häuser. Der Platz und die davon ausgehenden Arkadenstraßen sind mit angeleintem Hund frei begehbar, am schönsten früh morgens, bevor sich die Café-Terrassen füllen.`,
      "Castello del Buonconsiglio": `Die Residenz der Fürstbischöfe, teils mittelalterliche Burg, teils Renaissance-Loggia. Die durch die Porta dei Diamanti betretenen Gärten heißen angeleinte Hunde jeder Größe kostenlos willkommen; im Museum sind nur kleine, getragene oder transportierte Hunde zugelassen.`,
      "Funivia Trento-Sardagna": `Vier Minuten Seilbahnfahrt, um 400 Meter zum Balkon von Sardagna über dem Etschtal aufzusteigen. Kleine, auf dem Arm getragene Hunde fahren kostenlos, größere zahlen 1,20 Euro mit Maulkorb und Leine; die Seilbahn erlaubt sogar mehrere Tiere bei eigens dafür vorgesehenen Kabinenfahrten.`,
      "Parco di Gocciadoro": `Zwanzig Hektar Wald und Rasenflächen auf dem Hügel im Südosten, die große grüne Lunge für Trients Hunde. Eine eingezäunte Hundeauslauffläche mit Trinkbrunnen und im Sommer wertvollen schattigen Pfaden; außerhalb des Geheges gilt Leinenpflicht.`,
      "MUSE - Museo delle Scienze": `Renzo Pianos spektakuläres Wissenschaftsmuseum lässt keine Hunde zu, hat aber eine Lösung parat: Der städtische Zwinger in der Via delle Bettine 35 bietet kostenlose Tagesboxen und einen Abholservice für 10 Euro am Museum, im Voraus zu buchen.`,
      "Monte Bondone e Le Viote": `Trients eigener Berg, mit der weiten Hochebene Viote auf rund 1.500 Metern: Picknickwiesen, hundefreundliche Wege und garantierte Kühle, wenn das Tal schwitzt. Nur der alpine botanische Garten ist für Hunde tabu; achten Sie auf weidende Herden und behalten Sie die Leine an.`,
    },
  },
  treviso: {
    history: `An einer Flusskreuzung geboren, wuchs Treviso an den Quellen der Sile und den Armen des Cagnan, die seine Bürger seit dem Mittelalter zu Kanälen, Mühlen und Waschhäusern zähmten. Erst freie Kommune und dann ab 1339 treue Besitzung Venedigs, übernahm es die Lebenskunst der Serenissima: freskierte Arkaden, gotische Paläste und ein seit 1856 auf einer eigenen Insel betriebener Fischmarkt. Seine im 16. Jahrhundert von Venedig errichteten Mauern umschließen noch heute das Zentrum. Am Karfreitag 1944 schwer bombardiert, baute sich die Stadt mit Sorgfalt und Zurückhaltung wieder auf. Heute Hauptstadt des roten Radicchio, Geburtsort des Tiramisu und Tor zu den UNESCO-Prosecco-Hügeln, bietet Treviso venezianische Atmosphäre ohne das Gedränge: eine Stadt aus Wasser und Arkaden, vollständig zu Fuß zu entdecken, zur großen Freude jedes Hundes.`,
    petTips: [`Italienische Faustregel: eine höchstens 1,5 m lange Leine in der Stadt und ein griffbereiter Maulkorb, erforderlich in öffentlichen Verkehrsmitteln und bei jeder Aufforderung; ohne mitgeführten Maulkorb riskieren Sie ein Bußgeld.`, `MOM-Busse lassen Hunde mit Leine und Maulkorb zu (kleine Haustiere in Transportboxen reisen kostenlos); in Trenitalia-Regionalzügen kostet das Hundeticket 50 % eines Fahrpreises zweiter Klasse, und große Hunde sind werktags von 7 bis 9 Uhr verboten.`, `Die Stadt unterhält ein Netz eingezäunter sgambatura-Hundeauslaufflächen, etwa jene im Parco Ducale (2023) mit Doppeltoren und Brunnen: Erfragen Sie, welche Ihrem Hotel am nächsten liegt.`, `Die venetische Ebene ist im Sommer schwül: Gehen Sie bei Sonnenaufgang und -untergang spazieren, führen Sie stets Wasser mit und besprechen Sie mit Ihrem Tierarzt vor der Reise die Herzwurm-Prophylaxe (Filaria), Mücken gehören zur Landschaft.`, `Notfälle: Clinica Veterinaria Strada Ovest (+39 0422 262237) und Ospedale Veterinario San Francesco (+39 0422 450288) betreiben beide rund um die Uhr Dienste in und knapp außerhalb von Treviso.`],
    practicalInfo: [`24/7-Tierärzte: Clinica Veterinaria Strada Ovest, Strada San Pelajo 127 (+39 0422 262237) und Ospedale Veterinario San Francesco, Via Feltrina 29 in Castagnole di Paese (+39 0422 450288, CT und MRT); in Conegliano das Ospedale Veterinario Città di Conegliano (+39 0438 33566).`, `Venedig ist 30 Minuten mit dem Zug entfernt: Trenitalia-Hundeticket zu 50 % eines Fahrpreises zweiter Klasse, Leine und Maulkorb, Gesundheitsheft mitführen; meiden Sie werktags Regionalzüge von 7 bis 9 Uhr mit einem großen Hund.`, `Nächster Hundestrand: Bau Bau Beach in Lido di Jesolo (etwa 40 Autominuten entfernt), mit ausgewiesener Hundeschwimmzone; außerhalb der Hundebereiche verbieten die Küstenstrände Hunde im Sommer.`, `Der Flughafen Treviso (Ryanair) liegt 10 Minuten vom Zentrum entfernt: Die meisten Billigfluggesellschaften nehmen auf diesen Strecken keine Haustiere in der Kabine mit, prüfen Sie dies vor der Buchung.`, `MOM-Busse: Hunde mit Leine und Maulkorb zugelassen, kleine Haustiere in Transportboxen kostenlos; das ummauerte Zentrum lässt sich ohnehin in einer Viertelstunde zu Fuß durchqueren.`],
    sights: {
      "Piazza dei Signori": `Trevisos bürgerliches Wohnzimmer, beherrscht vom Palazzo dei Trecento aus dem 13. Jahrhundert und erweitert durch die Calmaggiore-Arkaden Richtung Duomo. Alles spielt sich draußen ab, an der Leine, besonders zur Aperitivo-Zeit, wenn die Terrassen überquellen.`,
      "Isola della Pescheria": `Die kleine Insel am Kanal Cagnan beherbergt seit 1856 den Fischmarkt, umgeben von Weiden und Uferfassaden. Durchstöbern Sie die Morgenstände an kurzer Leine und folgen Sie dann dem Kanal Buranelli, dem meistfotografierten Blick der Stadt.`,
      "Restera del Sile": `Der alte Treidelweg entlang der Sile verlässt die Mauern und führt flach und autofrei Richtung Casier und den regionalen Flusspark. Es ist Trevisos großer Hundespaziergang, an Wochenenden voller Radfahrer: Halten Sie eine kurze Leine und den rechten Wegrand.`,
      "Mura di Treviso": `Der venezianische Mauergürtel aus dem 16. Jahrhundert, gesäumt von Wasser und Bäumen, bildet eine schattige Promenade rund um das Zentrum. Die vollständige Runde ergibt eine schöne, etwa einstündige Leinenrunde, kühl selbst im Sommer.`,
      "Parco dello Storga": `Ein 67 Hektar großer Quellwasserpark nordöstlich der Stadt, wo die Storga inmitten von Wiesen, Wäldern und alten Gehöften entspringt. Flache Kieswege, an der Leine: Dies ist ein Naturschutzgebiet, halten Sie sich also von Brutzonen fern.`,
      "Colline del Prosecco": `Die UNESCO-Hügel von Conegliano-Valdobbiadene beginnen 20 Minuten nördlich: rebengestreifte Kämme, Weiler und Panoramagassen. Weinbergpfade an der Leine und Verkostungen bei Familienweingütern, die oft ruhige Hunde akzeptieren, wenn man vorher anruft.`,
    },
  },
  trieste: {
    history: `Triest, Hauptstadt von Friaul-Julisch Venetien und ein bedeutender habsburgischer Adriahafen, war fünf Jahrhunderte lang (1382–1918) der Zugang des österreichisch-ungarischen Reiches zum Mittelmeer. Kaiserin Maria Theresia ließ das Borgo Teresiano des 18. Jahrhunderts errichten, ein rasterförmiges Viertel, durchzogen vom Canal Grande, das der Stadt ihre noch immer intakte klassizistische Silhouette verlieh. Als kosmopolitische Kreuzung von Italienern, Slowenen, Juden und Griechen beherbergte sie James Joyce (der hier einen Großteil des Ulysses schrieb), Italo Svevo und Umberto Saba. Heute, eine Stadt mit rund 200.000 Einwohnern und 22.000 registrierten Hunden, vereint Triest die Piazza Unità d'Italia (Europas größter Platz am Meer), das habsburgische Schloss Miramare, das Karst-Kalksteinplateau zum Wandern und den Bau Beach von Barcola zum Hundeschwimmen, alles im Winter von der Bora heimgesucht, einem legendären, kalten katabatischen Wind.`,
    petTips: [`Die Bora weht von Dezember bis März mit Böen von 60-100 km/h, gelegentlich bis zu 200 km/h, stark genug, um kleine Hunde anzuheben; prüfen Sie morgens OSMER FVG und bleiben Sie an Rot-Alarm-Tagen im geschützten Raster des Borgo Teresiano.`, `Das italienische Landesgesetz (DM 23/03/2007) verlangt, dass jeder Hundehalter in der Öffentlichkeit einen Maulkorb (auch ohne ihn zu tragen) und eine höchstens 1,5 m lange Leine mitführt; die Polizei kann bei fehlendem mitgeführtem Maulkorb 25-160 € Bußgeld verhängen.`, `Die Busse von Trieste Trasporti nehmen kleine Hunde in Transportboxen kostenlos mit; größere Hunde reisen angeleint und mit Maulkorb zum einfachen Fahrgastpreis, die Regel gilt einheitlich im gesamten Netz.`, `Barcola Bau Beach ist die einzige ausgewiesene Hundeschwimmzone, zwischen Cedas und Il Pane Quotidiano; entlang der übrigen 4 km des Lungomare gilt Leinenpflicht, und Hunde sind im Juli-August vom Wasser ausgeschlossen.`, `Der am besten erreichbare 24-Stunden-Notfalltierarzt ist die Clinica Veterinaria Tergeste (+39 338 4265881); parallel dazu ist 1515 (Carabinieri Forestali) die nationale Leitung für Tiere in Not.`],
    practicalInfo: [`Nächstgelegener Flughafen: Trieste Ronchi dei Legionari (TRS), 33 km nordwestlich, mit direktem TS-TRS-Zug in 35 Min. mit Trieste Centrale verbunden (Hunde gemäß Trenitalia-Regeln zugelassen).`, `24-Stunden-Notfalltierarzt: Clinica Veterinaria Tergeste (+39 338 4265881) in Roiano; der regionale öffentliche Dienst ASUGI deckt die Bereitschaftsrotation außerhalb der Öffnungszeiten für den Rest der Provinz ab.`, `Leitungswasser ist unbedenklich; Trinkbrunnen finden sich im Parco di Miramare, auf der Piazza Unità und in jedem kommunalen area cani, bringen Sie eine faltbare Schale mit.`, `Die Osmize, die karstischen Hof-Weinschenken, öffnen nur wenige Wochen im Jahr; prüfen Sie den Kalender auf osmize.com und bringen Sie Bargeld mit, die meisten akzeptieren keine Karten.`, `Italienisches Recht: EU-Heimtierausweis, ISO-Mikrochip und aktuelle Tollwutimpfung sind für jeden einreisenden Hund vorgeschrieben; Maulkorb und 1,5-m-Leine sind in der Öffentlichkeit mitzuführen, Bußgelder für Hundekot liegen in Triest bei 100-500 €.`],
    sights: {
      "Piazza Unità d'Italia": `Europas größter Platz am Meer, der sich direkt zur Adria hin öffnet und von habsburgischen Palästen des 19. Jahrhunderts gerahmt wird. Vollständig Fußgängerzone und hundefreundlich, mit Café-Terrassen, die angeleinte Hunde willkommen heißen.`,
      "Castello di Miramare": `Habsburgisches neugotisches Schloss von Erzherzog Maximilian, thronend auf einem Vorgebirge 7 km nordwestlich des Zentrums. Der 22 Hektar große Uferpark ist an der Leine vollständig hundefreundlich; das Schlossinnere bleibt für Hunde tabu.`,
      "Canal Grande di Trieste": `1754-56 gegrabener, schiffbarer Kanal im Herzen des Borgo Teresiano, der bis zur Chiesa di Sant'Antonio Nuovo reicht. Fußgängerkais auf beiden Ufern, Café-Terrassen entlang der gesamten Länge, ideal für einen langen Leinenspaziergang mit Blick auf vertäute Segelboote.`,
      "Cattedrale di San Giusto": `Kathedrale aus dem 14. Jahrhundert auf dem gleichnamigen Hügel, neben dem venezianisch-habsburgischen Schloss San Giusto. Angeleinte Hunde willkommen auf Terrassen, Bastionen und im Steingarten; das Kathedraleninnere ist für Hunde gesperrt.`,
      "Barcola Seafront": `4 km lange Uferpromenade zwischen Cedas und Miramare, Triests beliebter Stadtstrand, mit dem eigenen Bau Beach zwischen Cedas und Il Pane Quotidiano. Tiefes Wasser vor Betonplattformen, ideal zum Hundeschwimmen von Juni bis September.`,
      "Carso (Karst Plateau)": `Kalksteinplateau auf 200-400 m Höhe über der Stadt, in 15 Min. mit Bus 4 oder Straßenbahn (wenn in Betrieb) erreichbar. Netz hundefreundlicher CAI-Wanderwege, das karstische Val-Rosandra-Tal und Osmize, ländliche Hof-Weinschenken, die nur wenige Wochen im Jahr öffnen und im Allgemeinen tierfreundlich sind.`,
    },
  },
  trogir: {
    history: `Im 3. Jahrhundert v. Chr. von griechischen Siedlern aus Vis als Tragurion gegründet, ist Trogir eine kleine Stadt auf einer Insel, durch eine Brücke mit dem Festland und durch eine weitere mit der Insel Čiovo verbunden. Ihr mittelalterlicher Kern, ein UNESCO-Weltkulturerbe, gilt als das besterhaltene romanisch-gotische Ensemble Mitteleuropas: die Kathedrale des heiligen Laurentius mit Radovans berühmtem Portal, venezianische Paläste, eine Loggia und die Festung Kamerlengo, die über das Meer wacht. Die ganze Stadt wird zu Fuß erkundet, und das sehr bequem mit Hund: die palmengesäumte Riva, die morgens kühlen Gassen und die Mauern bilden eine ideale Leinenrunde, während die Strände von Čiovo, jenseits der Brücke, hundegeduldete Abschnitte fernab der Hauptbadezonen bieten. Der Flughafen Split liegt 25 Minuten entfernt, was Trogir zu einem bemerkenswert bequemen Tor nach Dalmatien macht.`,
    petTips: [`Sommerwarnung: über 30 °C im Juli und August, wobei polierte Steinplatten zwischen 11 und 18 Uhr für Pfoten brennend heiß werden; machen Sie den Handrückentest, gehen Sie bei Sonnenaufgang und am Abend spazieren und führen Sie stets Wasser mit`, `Die Altstadt füllt sich mittags im Sommer mit Tagesausflüglern aus Split; erledigen Sie die Runde Riva-Mauern-Kamerlengo vor 9 Uhr oder nach 19 Uhr, Ihr Hund wird es Ihnen danken`, `Kroatisches Recht verbietet Hunde vom 15. Mai bis 15. September an nicht ausgewiesenen Badestränden; überqueren Sie die Brücke nach Čiovo und zielen Sie auf die geduldeten Abschnitte Richtung Okrug und Slatine, fernab der Hauptzonen`, `In der Öffentlichkeit besteht Leinenpflicht; die mittelalterlichen Gassen sind eng, und der polierte Stein wird nach Regen rutschig, ein Geschirr hält im Gedränge besser als ein Halsband`, `Bootsausflüge zu den Inseln und nach Split: Auf den Jadrolinija-Fähren sind Maulkorb und Leine an Deck vorgeschrieben, während die kleinen privaten Shuttles von Fall zu Fall entscheiden, fragen Sie also vor dem Einsteigen nach`],
    practicalInfo: [`Europäische Notrufnummer: 112; in Kroatien Polizei 192, Feuerwehr 193, Rettungsdienst 194, nicht mit einer tierärztlichen Leitung zu verwechseln`, `Tierarztpraxen in Trogir und der unmittelbaren Umgebung für die Grundversorgung; die nächsten 24-Stunden-Tierkliniken befinden sich in Split, eine halbe Autostunde entfernt`, `Tierabteilungen in den Tommy-, Konzum- und Studenac-Supermärkten der Stadt und von Čiovo; besser sortierte Tierbedarfsgeschäfte in den Einkaufszentren rund um Split`, `Der Flughafen Split ist 25 Minuten mit Auto oder Bus entfernt; Stadtbusse und Küstenlinien nehmen Hunde nach Ermessen des Fahrers mit, kleine Hunde in einer Transportbox werden leichter akzeptiert, und örtliche Taxis sind bei vorherigem Anruf im Allgemeinen entgegenkommend`, `EU-Heimtierausweis, Mikrochip und aktuelle Tollwutimpfung erforderlich; Kroatien gehört zur EU, ohne zusätzliche Formalitäten bei Ankunft aus Frankreich, Spanien oder Portugal`],
    sights: {
      "Katedrala svetog Lovre": `Die Kathedrale des heiligen Laurentius, das Juwel der UNESCO-Altstadt, öffnet sich durch das 1240 von Radovan geschnitzte romanische Portal, das schönste an der Adria. Hunde sind im Gebäude und im Glockenturm nicht zugelassen, doch das Portal und die Piazza Ivana Pavla II lassen sich früh morgens an der Leine am besten bewundern.`,
      "Tvrđava Kamerlengo": `Die im 15. Jahrhundert von Venedig errichtete Festung Kamerlengo sperrt die westliche Spitze der Insel und bietet vom Mauerrundgang aus den schönsten Blick über die Dächer, den Kanal und Čiovo. Als Freiluftstätte lässt sie im Allgemeinen angeleinte Hunde zu; im Sommer kann die Freilichtbühne den Zugang abends sperren.`,
      "Trogirska riva": `Trogirs Riva verläuft unter Palmen am Kanal entlang, vorbei an Yachten, Terrassen und venezianischen Fassaden, vom Stadttor bis zur Festung Kamerlengo. Breit und flach, ist sie der naheliegende Hundespaziergang morgens und abends; viele Cafés bringen ungefragt einen Wassernapf.`,
      "Otok Čiovo": `Jenseits der Brücke reiht die Insel Čiovo Pinienwälder, Buchten und Kiesstrände aneinander, weit ruhiger als das historische Inselchen. Abseits der Hauptbadezonen dulden mehrere Abschnitte Hunde, besonders Richtung Okrug und Slatine; fahren Sie im Sommer früh los und bringen Sie tragbaren Schatten mit.`,
      "Trg Ivana Pavla II": `Der zentrale Platz vereint auf wenigen Metern die Kathedrale, die mittelalterliche Loggia, den Uhrturm und das Rathaus: ganz Trogir auf einer polierten Steinbühne. Angeleinte Hunde streifen hier frei umher; kommen Sie im Sommer vor 9 Uhr, denn danach füllt sich der Platz mit Tagesausflüglern aus Split.`,
      "Park Garagnin-Fanfogna": `Direkt gegenüber der Festlandbrücke vereint dieser historische Garten der Familie Garagnin, einer der frühesten klassischen Gärten Dalmatiens, schattige Wege, Zitrusbäume und lapidare Überreste. Es ist das einzige echte Stück Grün wenige Schritte von der Altstadt entfernt, perfekt für eine kühle Pause mit angeleintem Hund.`,
    },
  },
  tromso: {
    history: `Tromsø, 1794 gegründet und von polaren Entdeckern des 19. Jahrhunderts „Paris des Nordens“ genannt, ist Norwegens arktische Hauptstadt, 350 km nördlich des Polarkreises. Mit 77.000 Einwohnern ist sie eine der größten Städte oberhalb des Polarkreises, der historische Ausgangspunkt für Expeditionen nach Spitzbergen und zum Pol. Das Klima ist für diesen Breitengrad dank des Golfstroms paradoxerweise mild: Im Juli liegen die Höchstwerte durchschnittlich bei 14 °C, im Januar bei rund -3 °C, ideal für kurzköpfige und ältere Hunde, die unter kontinentaler Hitze leiden. Die Stadt ist berühmt für die Nordlichter von September bis März und die Mitternachtssonne von Mai bis Juli. Hunde sind hier alltägliche Begleiter: Die norwegische Leinenpflicht (1. April-20. August) schützt brütende Vögel, außerhalb dieser Saison sind die Waldpfade von Tromsdalen und das Südufer von Telegrafbukta leinenfreie Refugien. Tromsø ist auch das Tor zur Küstenfähre Hurtigruten, die Bergen mit Kirkenes verbindet und über eigene Tierkabinen verfügt.`,
    petTips: [`Strenge norwegische Leinenpflicht 1. April-20. August überall außerhalb eingezäunter Hundeparks; außerhalb der Saison leinenfrei mit zuverlässigem Rückruf auf den Wegen.`, `Reflektierendes Halsband und Geschirr sind zwischen Oktober und April unerlässlich; die Polarnacht (27. Nov.-15. Jan.) plus Schneeblendung machen Hunde für Autofahrer unsichtbar.`, `Svipper-Buslinie 42 zum Flughafen Tromsø (TOS): angeleinte Hunde nach Ermessen des Fahrers, kleine Hunde in Transportboxen kostenlos.`, `Tierärztliche Notdienste arbeiten mit telefonischer Ersteinschätzung: Tromsø Dyrehospital (+47 77 60 04 70) und AniCura Tromsø (+47 77 67 56 00); kein 24/7-Direktzugang ohne Anmeldung.`, `Norwegische Tierarztgebühren gehören zu den höchsten Europas: eine grundlegende Notfallberatung kostet 1.800-2.500 NOK (155-215 €). Versicherung wird empfohlen.`],
    practicalInfo: [`Der Flughafen Tromsø (TOS) ist 10 Min. mit Bus 42 vom Zentrum entfernt; ein Auslaufbereich für Haustiere liegt östlich des Terminals.`, `Küstenfähre Hurtigruten Bergen-Kirkenes: täglicher Anlauf, Tierkabinen müssen vorab gebucht werden, Hunde nur an der Leine auf den Außendecks.`, `Nordlicht-Minibustouren (Chasing Lights, Tromsø Friluftsenter, Arctic Explorer): manche Anbieter akzeptieren ruhige Hunde bei privaten oder kleinen Gruppentouren, fragen Sie bei der Buchung nach.`, `Aurora-Saison Mitte September bis Anfang April; Mitternachtssonne Ende Mai bis Ende Juli; keine echte Dunkelheit von Mitte Mai bis Mitte August.`, `In Norwegen verbotene Rassen: American Staffordshire Terrier, Pit Bull, Tosa Inu, Dogo Argentino, Fila Brasileiro, tschechoslowakischer Wolfshund.`],
    sights: {
      "Fjellheisen Cable Car": `Ikonische Seilbahn zum Storsteinen auf 421 m, Panorama über die arktische Stadt und die Fjorde. Kleine Hunde in Transportboxen kostenlos, große Hunde mit Maulkorb nach Ermessen des Personals.`,
      "Arctic Cathedral": `Ikonische weiße dreieckige Kirche von 1965 auf der Tromsdalen-Seite. Der Außenplatz ist rund um die Uhr für Hunde geöffnet, nur Assistenzhunde dürfen hinein.`,
      "Telegrafbukta Park": `Nach Süden ausgerichteter Buchtpark, der Hauptstrand der Stadt. Leinenfrei außerhalb der Brutsaison (1. April-20. August) bei zuverlässigem Rückruf.`,
      "Tromsdalen Forest Trails": `Bewaldete Ausläufer auf dem Festland, Ausgangspunkt der Sherpa-Treppe. Leinenfrei außerhalb der Brutsaison, ideal zum Skijöring von Januar bis März.`,
      "Storgata Main Street": `Hauptverkehrsader und Stortorget-Platz, die Café- und Geschäftsachse, angeleinten Hunden zugänglich. Bank und Windschutz an den meisten Café-Eingängen im Winter.`,
      "Prestvannet Lake Loop": `Flacher 2 km langer Rundweg um den See auf der höchsten Stelle der Insel, ganzjährig beleuchtet. Strenge Leinenpflicht nahe dem Ufer (Vogelschutzgebiet).`,
    },
  },
  trondheim: {
    history: `Trondheim, im Jahr 997 n. Chr. vom Wikingerkönig Olav Tryggvason als Kaupangen gegründet, war die erste Hauptstadt des mittelalterlichen Norwegen und während des gesamten Mittelalters Sitz des mächtigen Erzbistums Nidaros. Der Nidarosdom, ab 1070 über dem Grab des heiligen Olav (1030 als Märtyrer gestorben) erbaut, ist die nördlichste gotische Kathedrale der Welt und bleibt der Krönungsort norwegischer Könige. Mehrfach niedergebrannt und identisch wiederaufgebaut, ist die Stadt heute Skandinaviens viertgrößtes Universitätszentrum (NTNU, 40.000 Studierende) und Norwegens drittgrößte Stadt (210.000 Einwohner). Für Reisende mit Hund verbindet Trondheim mittelalterliches Erbe mit zugänglicher Natur: das mittelalterliche Zentrum in 20 Min. begehbar, 80 km² Stadtwald Bymarka am Stadtrand, die historische Straßenbahn Gråkallbanen von 1955 (die nördlichste der Welt) und ein 14 km langer Küstenpfad entlang der Halbinsel Lade am Trondheimsfjord.`,
    petTips: [`Die norwegische Café-Kultur heißt Hunde standardmäßig willkommen, etwa 80 % der Cafés in Trondheim lassen angeleinte Hunde ganzjährig im Hauptraum zu.`, `AtB-Busse, Gråkallbanen-Straßenbahn und Vy-Züge: angeleinte Hunde KOSTENLOS, Maulkorb für mittelgroße/große Hunde erforderlich (kleine Hunde in Transportbox ausgenommen).`, `6 eingezäunte kommunale hundepark; Leinenpflicht vom 1. April bis 19. August in nicht eingezäunten Zonen.`, `24/7-Tierärztlicher Notdienst: Empet Trondheim in Heimdal (+47 73 84 02 00), 15 Min. mit dem Auto vom Zentrum.`, `Norwegen verlangt eine Bandwurmbehandlung (Echinokokkose), verabreicht 24-120 Std. vor Ankunft, ebenso wie Finnland, Irland und Malta.`],
    practicalInfo: [`Norwegen gehört zum Schengen-Raum, aber NICHT zur EU: EU-Heimtierausweis + gültige Tollwutimpfung + ISO-Mikrochip + Bandwurmbehandlung 24-120 Std. vor Ankunft.`, `Direkte Vy-Züge: Oslo 6:30 Std. (die legendäre Dovrebanen über die Berge), Bodø 10 Std. (Nordlandsbanen), Stockholm 12 Std. (mit einer Umsteigeverbindung), angeleinte Hunde kostenlos in haustierzugelassenen Wagen.`, `Der Flughafen Trondheim Værnes (TRD) liegt 30 km nordöstlich, erreichbar mit dem Bus Værnes Ekspressen (45 Min.) oder dem Zug (35 Min.), beide hundefreundlich. SAS, Norwegian und Wizz Air nehmen alle kleine Hunde in der Kabine mit.`, `Währung: norwegische Krone (NOK), nicht Euro. Tägliches haustierfreundliches Budget: 1.000-1.500 NOK/Tag (90-135 €) ohne Unterkunft, eines der höchsten Europas.`, `Hundefreundliche Tagesausflüge: Insel Munkholmen (10 Min. Fähre im Sommer), Bymarka mit der Gråkallbanen-Straßenbahn (22 Min.), Atlantic Road (3 Std. mit dem Auto westlich).`],
    sights: {
      "Nidaros Cathedral": `Die nördlichste gotische Kathedrale der Welt (UNESCO), norwegisches Nationalheiligtum über dem Grab des heiligen Olav. Außenbereich und Gärten hundefreundlich; im Inneren nur Assistenzhunde.`,
      "Gamle Bybro": `Die 1681 erbaute hölzerne Alte Stadtbrücke, die Midtbyen mit Bakklandet verbindet, mit dem ikonischen Tor des Glücks am Ostende. Rund um die Uhr geöffnet, hundefreundlich.`,
      "Bakklandet Quarter": `Buntes Holzviertel aus dem 18. Jahrhundert, Kopfsteingassen, bohemische Cafés (Baklandet Skydsstation), Blick auf den Fluss Nidelva. Durchweg hundefreundlich.`,
      "Bymarka Urban Forest": `80 km² Stadtwald, 200 km Wanderwege, erreichbar mit der historischen Gråkallbanen-Straßenbahn. Leinenfrei außerhalb der Brutsaison (April-August).`,
      "Kristiansten Fortress": `Sternförmige Festung von 1681 auf dem Hügel über Bakklandet, Panoramablick von den äußeren Wallanlagen, hundefreundlich mit angeleinten Hunden.`,
      "Munkholmen Island": `Kleine Fjordinsel im Trondheimsfjord, ehemaliges Kloster und ehemalige Festung. Fähre Munken ab Ravnkloa (Mai-September), im Freien hundefreundlich.`,
    },
  },
  turin: {
    history: `Turin, im 1. Jahrhundert v. Chr. von den Römern als Iulia Augusta Taurinorum gegründet, wurde 1563 Hauptstadt des Herzogtums Savoyen und nach der Einigung Italiens (1861–1865) dessen erste Hauptstadt. Das Erbe des Hauses Savoyen prägt die Stadt: 18 km barocke Arkaden (das längste durchgehende Arkadensystem Europas), monumentale Plätze und königliche Paläste, verbunden durch Fußgängerpromenaden. Als Italiens viertgrößte Stadt mit 850.000 Einwohnern verbindet Turin diese historische Eleganz mit industriellem Geist, Fiat, Kino, Technologie, und einer tiefen Verbundenheit mit dem Po, der die Stadt auf 10 km durchquert. Für Hundehalter ist Turin eine der praktischsten italienischen Städte: Arkaden schützen vor Regen und Sommersonne, mehr als 35 eingezäunte Aree Cani verteilen sich auf jeden Stadtteil, und die eine Stunde entfernten Alpen bieten ganzjährige hundefreundliche Ausflüge.`,
    petTips: [`Weicher Maulkorb PFLICHT in Bus, Straßenbahn und U-Bahn des GTT, Bußgelder von 25–250 € werden konsequent durchgesetzt.`, `Zahnradbahn Sassi-Superga: angeleinte, mit Maulkorb versehene Hunde gegen Aufpreis von 1 € an Wochenend-Zugfahrten zugelassen.`, `Die offiziellen Aree Cani (35+) sind unter comune.torino.it/verdepubblico/aree-cani gelistet, alle kostenlos, die meisten rund um die Uhr geöffnet.`, `24/7-Notfallkliniken: Anubi in Moncalieri (011 6469480) und Torinese in Cenisia (011 3852070).`, `Gehwege erreichen im Sommer 55 °C, bevorzugen Sie die 18 km überdachter Arkaden oder gehen Sie vor 09:00 / nach 19:30 Uhr spazieren.`],
    practicalInfo: [`EU-Heimtierausweis und gültige Tollwutimpfung bei jedem Check-in in einem hundefreundlichen Hotel erforderlich.`, `Leinenpflicht in allen öffentlichen Räumen außerhalb der Aree Cani, Bußgelder ab 50 €.`, `Das Ägyptische Museum, das Kinomuseum (Mole Antonelliana) und der Königspalast verbieten Hunde, buchen Sie einen örtlichen Pawshake-Sitter.`, `Trenitalia ab Porta Nuova nimmt angeleinte, mit Maulkorb versehene Hunde gegen ein vergünstigtes Zusatzticket mit, nützlich für Alpen-Tagesausflüge.`, `Flughafen Turin (TRN): Auslaufbereich für Haustiere in Terminal 1; die meisten großen Fluggesellschaften nehmen auf europäischen Strecken Haustiere in der Kabine mit.`],
    sights: {
      "Parco del Valentino": `84 Hektar am Po mit dem Castello del Valentino und zwei eingezäunten Aree Cani. Turins beliebtester Park.`,
      "Piazza Castello": `Der monumentale zentrale Platz mit dem Königspalast, dem Königlichen Theater und Zugang zu den Giardini Reali (freier Eintritt, angeleinte Hunde willkommen).`,
      "Basilica di Superga": `Barocke Basilika, die den Hügel krönt, erreichbar mit der historischen Zahnradbahn. Panoramaterrasse für angeleinte Hunde zugänglich.`,
      "Murazzi del Po": `Bogenanlagen aus dem 19. Jahrhundert entlang des Po, Ausgangspunkt des 10 km langen durchgehenden Hundespaziergangs zum Valentino und zum Borgo Medievale.`,
      "Parco della Pellerina": `169 Hektar im Westen der Stadt, Turins größter Stadtpark. Drei eingezäunte Aree Cani, ein kleiner See und 6 km Rundwege.`,
      "Quadrilatero Romano": `Historisches Viertel mit Kopfsteinstraßen und jahrhundertealten Arkaden-Cafés. Das Herz der Bicerin-Kultur und hundefreundlicher Trattorien.`,
    },
  },
}
